#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define MOISTURE_SENSOR_CHANNEL 0
#define SPI_CE0_PIN 8
#define SPI_MOSI_PIN 10
#define SPI_MISO_PIN 9
#define SPI_SCLK_PIN 11

static int gpio_handle;
static int spi_handle;

void log_timestamped_moisture(int moisture) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: Moisture level: %d\n", time_string, moisture);
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }

    if (gpioSetMode(SPI_CE0_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_MOSI_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SPI_MISO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SPI_SCLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        return -1;
    }

    return 0;
}

int init_spi() {
    spi_handle = pi_spi_open(0, SPI_MODE_0, 1000000, 8, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return -1;
    }

    if (gpio_handle = gpioGetNum(SPI_CE0_PIN) < 0 ||
        gpioSetState(SPI_CE0_PIN, GPIO_LOW) < 0) {
        fprintf(stderr, "Failed to get or set SPI_CE0_PIN state\n");
        return -1;
    }

    return 0;
}

int read_moisture() {
    unsigned char data[3];
    int moisture;

    if (gpio_handle < 0 || gpioSetState(SPI_CE0_PIN, GPIO_HIGH) < 0 ||
        pi_spi_xfer(spi_handle, data, data, 3) < 0 ||
        gpioSetState(SPI_CE0_PIN, GPIO_LOW) < 0) {
        fprintf(stderr, "Failed to read moisture level\n");
        return -1;
    }

    moisture = (data[1] << 8) | data[2];

    return moisture;
}

void cleanup() {
    if (spi_handle >= 0) {
        pi_spi_close(spi_handle);
    }

    if (gpio_handle >= 0) {
        gpioTerm();
    }
}

int main() {
    int moisture;

    if (init_gpio() < 0 || init_spi() < 0) {
        cleanup();
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        moisture = read_moisture();
        if (moisture < 0) {
            fprintf(stderr, "Error reading moisture level, skipping\n");
            continue;
        }

        log_timestamped_moisture(moisture);
        sleep(1);
    }

    cleanup();
    return 0;
}

