#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define ADS1115_I2C_BUS 1
#define ADS1115_I2C_ADDR 0x48
#define MLX91219_AIN_PIN 0
#define ADS1115_AIN0 0b100
#define ADS1115_PGA_4096V 0b111100
#define ADS1115_DR_128HZ 0b00000100
#define MLX91219_SENSITIVITY 40.0f / 1000.0f

int main() {
    int i2c_fd, adc_fd;
    uint8_t config_reg[2] = {0};
    uint16_t adc_data;
    float current;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(ADS1115_I2C_BUS, ADS1115_I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    config_reg[0] = ADS1115_AIN0 | ADS1115_PGA_4096V | ADS1115_DR_128HZ;
    if (pigpio_i2cWriteI2CBlockData(i2c_fd, 0x01, 1, &config_reg[0]) < 0) {
        fprintf(stderr, "Failed to write ADS1115 configuration register\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    adc_fd = pigpio_i2c_open(ADS1115_I2C_BUS, ADS1115_I2C_ADDR, 2);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open ADC FIFO\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        usleep(500000); // Wait 500ms

        if (pigpio_i2cReadI2CBlockData(adc_fd, 0x00, 2, &adc_data) < 0) {
            fprintf(stderr, "Failed to read ADC data\n");
            close(adc_fd);
            close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        current = (adc_data * MLX91219_SENSITIVITY) - 2048.0f;
        printf("Current: %.3f A\n", current);
    }

    close(adc_fd);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

