#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <spidev.h>

#define SPI_DEVICE_NUM 0
#define SPI_CHIP_SELECT 8
#define FLAME_SENSOR_GPIO 4
#define ADC_CHANNEL 0
#define SAMPLE_INTERVAL 1000
#define TEMP_MIN 10
#define TEMP_MAX 40
#define ADC_RESOLUTION 1024

static char flame_data_file[] = "flame_data.csv";
static spi_device *spidev;
static FILE *csv_file;

void log_data(int flame_detected, uint16_t adc_value, double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];
    char line[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(line, sizeof(line), "%s,%d,%.1f\n", time_str, flame_detected, temperature);
    fputs(line, csv_file);
}

double map_temperature(uint16_t adc_value) {
    double temperature = TEMP_MIN + (adc_value / ADC_RESOLUTION) * (TEMP_MAX - TEMP_MIN);
    return temperature;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    return 0;
}

int init_spi() {
    int bits_per_word = 8;
    int mode = SPI_MODE_0;
    int speed_hz = 1000000;

    if ((spidev = spiOpen(SPI_DEVICE_NUM, SPI_CHIP_SELECT)) == NULL) {
        perror("spiOpen");
        return -1;
    }

    if (spiWriteRead(spidev, &speed_hz, 4, NULL, 0) < 0) {
        perror("spiWriteRead");
        return -1;
    }

    if (spiSetDataMode(spidev, mode) < 0) {
        perror("spiSetDataMode");
        return -1;
    }

    if (spiSetBitsPerWord(spidev, bits_per_word) < 0) {
        perror("spiSetBitsPerWord");
        return -1;
    }

    return 0;
}

int main() {
    int gpio_init_status = init_gpio();
    int spi_init_status = init_spi();
    int flame_detected = 0;
    uint16_t adc_value = 0;
    double temperature = 0.0;
    int sample_count = 0;

    if (gpio_init_status < 0 || spi_init_status < 0) {
        fprintf(stderr, "Error initializing GPIO or SPI\n");
        goto cleanup;
    }

    if ((csv_file = fopen(flame_data_file, "w")) == NULL) {
        perror("fopen");
        goto cleanup;
    }

    while (1) {
        if (gpioRead(FLAME_SENSOR_GPIO) == 0) {
            flame_detected = 1;
        }

        adc_value = spi_xfer16(spidev, &ADC_CHANNEL, 2);
        if (adc_value == -1) {
            perror("spi_xfer16");
            continue;
        }

        temperature = map_temperature(adc_value);

        log_data(flame_detected, adc_value, temperature);
        sample_count++;

        if (sample_count >= SAMPLE_INTERVAL) {
            sample_count = 0;
            usleep(1000000 - (SAMPLE_INTERVAL % 1000));
        }
    }

cleanup:
    if (csv_file) {
        fclose(csv_file);
    }

    if (spidev) {
        spiClose(spidev);
    }

    gpioTerm();

    return 0;
}

