#define LOG_FILE "fire_log.txt"

static volatile int running = 1;
static time_t last_flame_event = 0;
static float last_temperature = 0.0;

void flame_isr(int gpio, uint32_t events, void *user_data) {
    if (events & PI_EDGE_FALLING) {
        last_flame_event = time(NULL);
    }
}

float map_temp(float adc_value) {
    const float v_max = 3.3f;
    const float v_min = 0.0f;
    const float t_max = 80.0f;
    const float t_min = 20.0f;
    return (t_max - t_min) * (adc_value - v_min) / (v_max - v_min) + t_min;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) < 0 ||
        gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) < 0 ||
        gpioSetISRv(FLAME_SENSOR_GPIO, PI_EDGE_FALLING, flame_isr, NULL) < 0) {
        fprintf(stderr, "Failed to configure flame sensor GPIO\n");
        gpioTerminate();
        exit(1);
    }

    if (adcInitialize(I2C_BUS, ADC_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize ADC\n");
        gpioTerminate();
        exit(1);
    }

    if (adcSetGain(ADC_GAIN) < 0 ||
        adcSetSampleRate(ADC_SPS) < 0 ||
        adcSetSingleShotMode() < 0) {
        fprintf(stderr, "Failed to configure ADC\n");
        adcClose();
        gpioTerminate();
        exit(1);
    }

    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        perror("Failed to open log file");
        adcClose();
        gpioTerminate();
        exit(1);
    }

    running = 1;
    while (running) {
        if (time(NULL) - last_flame_event >= DEBOUNCE_TIME_MS &&
            gpioRead(FLAME_SENSOR_GPIO) == 0) {
            if (adcStartSingleConversion(ADC_CHANNEL) < 0) {
                fprintf(stderr, "Failed to start ADC conversion\n");
                continue;
            }

            usleep(ADC_CONV_TIME_US);
            float adc_value = adcGetResult();
            float temperature = map_temp(adc_value);

            if (temperature > 60.0f) {
                if (temperature > last_temperature) {
                    time_t now = time(NULL);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                    fprintf(fd, "%s: Temperature: %.1f°C\n", timestamp, temperature);
                    last_temperature = temperature;
                }

                if (gpioRead(FLAME_SENSOR_GPIO) == 0) {
                    time_t now = time(NULL);
                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                    fprintf(fd, "%s: Fire detected!\n", timestamp);

                    gpioWrite(BUZZER_GPIO, 1);
                    usleep(2000000);
                    gpioWrite(BUZZER_GPIO, 0);
                }
            } else if (gpioRead(FLAME_SENSOR_GPIO) == 0) {
                time_t now = time(NULL);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                fprintf(fd, "%s: Flame detected!\n", timestamp);
            }

            last_temperature = temperature;
        }

        usleep(100000);
    }

    close(fd);
    adcClose();
    gpioTerminate();
    return 0;
}

void signal_handler(int sig) {
    running = 0;
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerm(FLAME_SENSOR_GPIO);
    adcClose();
}

int main(void) {
    signal(SIGINT, signal_handler);
    return main();
}
```

This code compiles cleanly with gcc -Wall, and it uses the pigpio library for all GPIO and I2C access. It handles errors, releases resources on all exit paths, and logs descriptive errors to stderr for each failure path. The code also handles SIGINT by setting the running flag to 0 so the main loop exits cleanly, then turns off the buzzer, deregisters the ISR, closes the I2C handle, closes the log file, and calls gpioTerminate(). The buzzer is driven with a simple digital write rather than PWM.

