#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define ADC_VREF 3.3
#define SENSOR_SENSITIVITY 100.0f
#define THRESHOLD 5.0f
#define FAN_GPIO 18
#define ADC_CS_GPIO 8
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const unsigned int *consumer,
                                const unsigned int *flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, consumer, flags);
}

int main(int argc, char **argv)
{
    int spi_fd, adc_cs_gpio, fan_gpio;
    struct spi_ioc_transfer transfer = {0};
    uint8_t rx[3] = {0};
    float current = 0.0f;
    time_t timestamp;
    struct gpiod_chip *chip;
    struct gpiod_line_request *fan_request;

    if ((chip = gpiod_chip_open_by_name("gpiochip4")) == NULL) {
        perror("Failed to open gpiochip4");
        return 1;
    }

    if ((fan_request = gpiod_line_request_get_byindex(chip, FAN_GPIO)) == NULL) {
        perror("Failed to get fan GPIO line");
        goto cleanup_chip;
    }

    if (gpiod_line_request_direction_output(fan_request, GPIOD_LINE_ACTIVE_HIGH) < 0) {
        perror("Failed to set fan GPIO direction");
        goto cleanup_line_request;
    }

    if ((adc_cs_gpio = gpiod_get_index_byname(chip, "gpio8")) < 0) {
        perror("Failed to get ADC CS GPIO index");
        goto cleanup_line_request;
    }

    if ((fan_gpio = gpiod_get_index_byname(chip, "gpio18")) < 0) {
        perror("Failed to get fan GPIO index");
        goto cleanup_line_request;
    }

    if ((spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        goto cleanup_gpio;
    }

    transfer.tx_buf = (uint8_t[]) {0x01, 0x80, 0x00};
    transfer.rx_buf = rx;
    transfer.len = sizeof(rx);
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Failed to send SPI transfer");
        goto cleanup_spi;
    }

    current = ((rx[1] & 0x03) << 8) | rx[2];
    current /= (1 << 10);
    current *= ADC_VREF / SENSOR_SENSITIVITY;

    if (current > THRESHOLD)
        gpiod_line_set_value(fan_request, 1);
    else
        gpiod_line_set_value(fan_request, 0);

    timestamp = time(NULL);
    printf("%s, %f A\n", ctime(&timestamp), current);
    fprintf(stderr, "%s, %f A\n", ctime(&timestamp), current);

    if (access("current_log.txt", F_OK) != -1) {
        FILE *log_file = fopen("current_log.txt", "a");
        if (log_file) {
            fprintf(log_file, "%s, %f A\n", ctime(&timestamp), current);
            fclose(log_file);
        }
    } else {
        FILE *log_file = fopen("current_log.txt", "w");
        if (log_file) {
            fprintf(log_file, "Timestamp,Current (A)\n");
            fclose(log_file);
        }
    }

    sleep(1);

cleanup_spi:
    close(spi_fd);

cleanup_gpio:
    gpiod_line_release(fan_request);

cleanup_line_request:
    gpiod_chip_release(chip);

cleanup_chip:
    return 0;
}

