#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define GPIO_FLAME_SENSOR 4
#define GPIO_ADC_SENSOR 0
#define ADC_RESOLUTION 10
#define ADC_MIN 0
#define ADC_MAX 1023
#define ADC_TEMP_MIN 10.0
#define ADC_TEMP_MAX 40.0
#define CSV_FILE "flame_data.csv"

static int g_spi_fd = -1;
static time_t g_last_log = 0;

void log_data(int flame, uint16_t adc_value) {
    time_t now = time(NULL);
    if (difftime(now, g_last_log) >= 1) {
        g_last_log = now;

        FILE *file = fopen(CSV_FILE, "a");
        if (file) {
            fprintf(file, "%lu,%d,%d\n", now, flame, adc_value);
            fclose(file);
        } else {
            perror("Failed to open flame_data.csv");
        }
    }
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }

    if (gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT) < 0 ||
        gpioSetMode(GPIO_ADC_SENSOR, PI_INPUT_PULL_UP_DOWN) < 0) {
        perror("Failed to set GPIO modes");
        return -1;
    }

    return 0;
}

int init_spi(uint32_t spi_speed) {
    if (spiOpen(SPI_BUS, SPI_DEVICE, &g_spi_fd) < 0) {
        perror("Failed to open SPI bus");
        return -1;
    }

    if (spiSetDataMode(g_spi_fd, SPI_MODE_0) < 0 ||
        spiSetClockDivider(g_spi_fd, spi_speed) < 0 ||
        spiSetChipSelect(g_spi_fd, GPIO_SPI_CS0) < 0) {
        perror("Failed to configure SPI");
        return -1;
    }

    return 0;
}

uint16_t read_adc() {
    uint16_t adc_value = 0;

    for (int i = 0; i < 32; i++) {
        if (gpioWrite(GPIO_ADC_SENSOR, 0) < 0 ||
            spiXfer(g_spi_fd, &adc_value, 2, NULL, 1) != 1) {
            perror("Failed to read ADC");
            return 0;
        }
        gpioWrite(GPIO_ADC_SENSOR, 1);
        usleep(10);
    }

    return (adc_value >> 2) & 0x3FF;
}

int main() {
    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_spi(1000000) < 0) {
        return 1;
    }

    int flame = gpioRead(GPIO_FLAME_SENSOR);
    double adc_temp = 0.0;

    while (1) {
        if (flame) {
            adc_temp = (read_adc() - ADC_MIN) * ((ADC_TEMP_MAX - ADC_TEMP_MIN) / (ADC_MAX - ADC_MIN));
            log_data(1, (int)(adc_temp * 100.0));
        }

        usleep(1000000); // Sleep for 1 second

        flame = gpioRead(GPIO_FLAME_SENSOR);
    }

    spiClose(g_spi_fd);
    gpioTerm();
    return 0;
}

