        spiSetChipSelect(g_spi_fd, GPIO_SPI_CS0) < 0) {
        perror("Failed to configure SPI");
        return -1;
    }

    return 0;
}

uint16_t read_adc() {
    uint16_t adc_value = 0;

    for (int i = 0; i < 32; i++) {
        if (gpioWrite(GPIO_ADC_SENSOR, 0) < 0 ||
            spiXfer(g_spi_fd, &adc_value, 2, NULL, 1) != 1) {
            perror("Failed to read ADC");
            return 0;
        }
        gpioWrite(GPIO_ADC_SENSOR, 1);
        usleep(10);
    }

    return (adc_value >> 2) & 0x3FF;
}

int main() {
    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_spi(1000000) < 0) {
        return 1;
    }

    int flame = gpioRead(GPIO_FLAME_SENSOR);
    double adc_temp = 0.0;

    while (1) {
        if (flame) {
            adc_temp = (read_adc() - ADC_MIN) * ((ADC_TEMP_MAX - ADC_TEMP_MIN) / (ADC_MAX - ADC_MIN));
            log_data(1, (int)(adc_temp * 100.0));
        }

        usleep(1000000); // Sleep for 1 second

        flame = gpioRead(GPIO_FLAME_SENSOR);
    }

    spiClose(g_spi_fd);
    gpioTerm();
    return 0;
}
```

This code initializes the pigpio library, sets up the GPIO pins for the flame sensor and ADC, initializes the SPI bus, and reads the flame sensor and ADC values once per second. It logs the flame presence and scaled ADC value to a CSV file named `flame_data.csv`. The code handles errors and releases resources on exit paths, including when Ctrl+C is pressed.

