#define NO2_REG 0x01
#define CO_THRESHOLD 25
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define SAMPLE_INTERVAL 5

int gpiod_init(int *pi, uint32_t *pi_mode, uint32_t *pi_offset) {
    if (gpioInitialise() < 0) {
