    *pi_mode = GPIOMode_INPUT;
    *pi_offset = 0;

    return 0;
}

void gpiod_terminate(int pi, uint32_t *pi_mode, uint32_t *pi_offset) {
    gpioTerminate();
    *pi_mode = 0;
    *pi_offset = 0;
}

int i2c_read(int pi, int bus, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
