    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    ret = pigpio_i2c_read_device(fd, reg, buf, len);
    if (ret < 0) {
        perror("Failed to read from I2C device");
    }

    pigpio_i2c_close(fd);

    return ret;
}

void log_co_level(float co_level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%f\n", co_level);
    fclose(log_file);
}

void log_alert(const char *message) {
    FILE *alert_file = fopen(ALERT_FILE, "a");
    if (!alert_file) {
        perror("Failed to open alert file");
        return;
    }

    fprintf(alert_file, "%s\n", message);
    fclose(alert_file);
}

float calculate_co_level(uint16_t ox, uint16_t red) {
    // This is a simplified calculation. You may need to adjust it based on your sensor's specifications.
    float co_level = (float)ox * 5.0 / 65535 * 1000;
    return co_level;
}

int main() {
    int pi, pi_mode, pi_offset;
    uint8_t data[4];
    float co_level;
    struct timespec delay;

    if (gpiod_init(&pi, &pi_mode, &pi_offset) != 0) {
        return 1;
    }

    clock_gettime(CLOCK_REALTIME, &delay);
    delay.tv_sec += SAMPLE_INTERVAL;

    while (1) {
        if (i2c_read(pi, I2C_BUS, MICS_ADDR, CO_REG, data, sizeof(data)) <= 0 ||
            i2c_read(pi, I2C_BUS, MICS_ADDR, NO2_REG, data + 2, sizeof(data) - 2) <= 0) {
            perror("Failed to read from I2C device");
            continue;
        }

        co_level = calculate_co_level(data[0] | (data[1] << 8), data[3] | (data[4] << 8));
        log_co_level(co_level);

