#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MIC_ADDR1 0x48
#define MIC_ADDR2 0x49
#define REG_ADDR 0x00

static double mic_sensitivity = -38.0 / 20.0 * log10(2.0);
static double mic_ref_pressure = 20.0e-6;

void i2c_read_mic(uint8_t addr, uint16_t *data) {
    if (i2c_read_register16(I2C_BUS, addr, REG_ADDR, data) < 0) {
        *data = -999;
    }
}

double dB_to_Pa(double dB) {
    return pow(10, dB / 20.0) * mic_ref_pressure;
}

double sound_pressure_level(uint16_t raw_data) {
    double voltage = raw_data * (3.3 / (1 << 16));
    double pressure = dB_to_Pa(20.0 * log10(voltage / mic_sensitivity));
    return pressure < 0 ? 0.0 : pressure;
}

void log_data(const char *tag, uint16_t data1, uint16_t data2) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen("audio_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s, %d, %d\n", time_str, (int)data1, (int)data2);
        fclose(log_file);
    }
}

void sigint_handler(int signum) {
    gpioTerm();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    uint16_t data1, data2;
    double avg_level;

    while (1) {
        i2c_read_mic(MIC_ADDR1, &data1);
        i2c_read_mic(MIC_ADDR2, &data2);

        avg_level = (sound_pressure_level(data1) + sound_pressure_level(data2)) / 2.0;
        log_data("sound_pressure_level", data1, data2);

        usleep(100000);
    }

    gpioTerm();
    return 0;
}

