#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define MIC1_CS 8
#define MIC2_CS 9
#define ADC_MISO 9
#define ADC_MOSI 10
#define ADC_SCLK 11
#define LED_GPIO 27

#define SAMPLE_COUNT 100
#define SAMPLE_INTERVAL 1000000L  // 1 ms
#define THRESHOLD 0.7
#define LOG_FILE "audio_events.csv"

double adc_read(int cs_pin) {
    uint16_t adc_value;
    gpioWrite(cs_pin, 0);
    usleep(10);
    gpioWrite(cs_pin, 1);

    for (int i = 0; i < 24; i++) {
        if (gpioRead(ADC_MISO) == 0)
            adc_value |= (1 << i);
    }

    return (adc_value * 3.3) / (1 << 12);
}

double rms(double *samples, int count) {
    double sum = 0;
    for (int i = 0; i < count; i++)
        sum += samples[i] * samples[i];
    return sqrt(sum / count);
}

void log_event(const char *mic1_rms, const char *mic2_rms) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s,%s,%s\n", timestamp, mic1_rms, mic2_rms);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    FILE *file = fopen(LOG_FILE, "w");
    if (!file) {
        perror("Failed to create log file");
        goto cleanup;
    }
    fprintf(file, "Timestamp,Mic1 RMS,Mic2 RMS\n");
    fclose(file);

    double mic1_samples[SAMPLE_COUNT];
    double mic2_samples[SAMPLE_COUNT];
    struct timespec start, end;

    for (int i = 0; i < SAMPLE_COUNT; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        mic1_samples[i] = adc_read(MIC1_CS);
        mic2_samples[i] = adc_read(MIC2_CS);
        usleep(SAMPLE_INTERVAL);
    }

    double mic1_rms = rms(mic1_samples, SAMPLE_COUNT);
    double mic2_rms = rms(mic2_samples, SAMPLE_COUNT);

    if (mic1_rms > THRESHOLD || mic2_rms > THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        usleep(500000);
        gpioWrite(LED_GPIO, 0);
    }

    log_event(fmt::to_string(mic1_rms).c_str(), fmt::to_string(mic2_rms).c_str());

cleanup:
    gpioTerminate();
    return 0;
}

