    uint16_t atime = 0xFF;
    uint16_t control = 0x01;
    uint16_t enable = 0x01 | 0x02;

    if (i2c_w_reg16(i2c_fd, REG_ATIME, atime) < 0 ||
        i2c_w_reg16(i2c_fd, REG_CONTROL, control) < 0 ||
        i2c_w_reg16(i2c_fd, REG_ENABLE, enable) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
    }

    usleep(3000000); // Wait at least 3 ms after power-on before reading
}

