        i2c_r_reg16(i2c_fd, REG_GREEN, &color_values[2]) < 0 ||
        i2c_r_reg16(i2c_fd, REG_BLUE, &color_values[3]) < 0) {
        fprintf(stderr, "Failed to read color values\n");
    }
}

