        perror("Failed to open CSV file");
        return;
    }

    va_list args;
    va_start(args, format);
    vfprintf(csv_file, format, args);
    va_end(args);
    fflush(csv_file);
    fclose(csv_file);
}

void sigint_handler(int signum) {
    close(i2c_fd);
    fclose(csv_file);
    gpioTerminate();
    exit(0);
}

