#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <linux/spidev.h>

#define CS_GPIO 8
#define MOISTURE_SENSOR_CHANNELS 2

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags)
{
    return gpiod_chip_get_request_lines(chip, nlines, lines, flags);
}

static void handle_signal(int signum)
{
    printf("\nExiting...\n");
    cleanup();
    exit(0);
}

static void setup_signals()
{
    struct sigaction sa;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
}

static int init_gpio(struct gpiod_chip *chip)
{
    int ret;
    struct gpiod_line_request_data data = {0};

    ret = gpiod_chip_open_byname(chip, "gpiochip0");
    if (ret < 0) {
        perror("gpiochip0 open");
        return ret;
    }

    data.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    ret = gpiod_chip_request_line(chip, CS_GPIO, &data);
    if (ret < 0) {
        perror("CS GPIO request");
        goto cleanup_gpiochip;
    }

    return 0;

cleanup_gpiochip:
    gpiod_chip_close(chip);
    return ret;
}

static int init_spi(const char *device)
{
    int ret, fd;
    struct spi_ioc_transfer transfers[MOISTURE_SENSOR_CHANNELS];

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Can't open spi device");
        return fd;
    }

    for (int i = 0; i < MOISTURE_SENSOR_CHANNELS; i++) {
        transfers[i].tx_buf = (unsigned char*)&(i << 2);
        transfers[i].rx_buf = (unsigned char*)malloc(3);
        transfers[i].len = 3;
        transfers[i].speed_hz = 100000;
        transfers[i].bits_per_word = 8;
    }

    ret = ioctl(fd, SPI_IOC_MESSAGE(MOISTURE_SENSOR_CHANNELS), transfers);
    if (ret < 0) {
        perror("Can't configure spi transfer");
        goto cleanup_spi;
    }

    return fd;

cleanup_spi:
    for (int i = 0; i < MOISTURE_SENSOR_CHANNELS; i++)
        free(transfers[i].rx_buf);
    close(fd);
    return ret;
}

static void cleanup()
{
    gpiod_chip_release_lines(gpiod_chip_get_byname("gpiochip0"), CS_GPIO);
    gpiod_chip_close(gpiod_chip_get_byname("gpiochip0"));
}

static double map_moisture(unsigned int adc_value)
{
    return (adc_value / 1023.0) * 100.0;
}

static void log_reading(const char *filename, unsigned int timestamp,
                        double moisture1, double moisture2)
{
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Can't open log file");
        return;
    }

    fprintf(file, "%lu,%f,%f\n", timestamp, moisture1, moisture2);
    fclose(file);
}

int main()
{
    struct gpiod_chip *chip;
    int spi_fd;
    struct timespec ts;
    double moisture1, moisture2;
    char filename[64];

    setup_signals();

    chip = gpiod_chip_get_byname("gpiochip0");
    if (!chip) {
        perror("Can't get gpiochip0");
        exit(EXIT_FAILURE);
    }

    if (init_gpio(chip) < 0)
        exit(EXIT_FAILURE);

    spi_fd = init_spi("/dev/spidev0.0");
    if (spi_fd < 0)
        exit(EXIT_FAILURE);

    snprintf(filename, sizeof(filename), "moisture_log.csv");
    log_reading(filename, time(NULL), 0.0, 0.0);

    while (1) {
        gpiod_line_set_value(chip->lines[CS_GPIO], 0);
        usleep(10);

        for (int i = 0; i < MOISTURE_SENSOR_CHANNELS; i++) {
            spi_ioc_message_t msg = {
                .tx_buf = transfers[i].tx_buf,
                .rx_buf = transfers[i].rx_buf,
                .len = transfers[i].len,
                .speed_hz = transfers[i].speed_hz,
                .bits_per_word = transfers[i].bits_per_word,
            };

            if (ioctl(spi_fd, SPI_IOC_MESSAGE, &msg) < 0) {
                perror("Can't read spi");
                goto cleanup;
            }

            moisture1 += map_moisture(transfers[0].rx_buf[1] | (transfers[0].rx_buf[2] << 8));
            moisture2 += map_moisture(transfers[1].rx_buf[1] | (transfers[1].rx_buf[2] << 8));
        }

        gpiod_line_set_value(chip->lines[CS_GPIO], 1);

        clock_gettime(CLOCK_REALTIME, &ts);
        log_reading(filename, ts.tv_sec, moisture1 / MOISTURE_SENSOR_CHANNELS,
                    moisture2 / MOISTURE_SENSOR_CHANNELS);

        moisture1 = 0.0;
        moisture2 = 0.0;
        usleep(5000000);
    }

cleanup:
    close(spi_fd);
    cleanup();
    return 0;
}

