#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_SCLK_GPIO 11
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define MOTOR_SHUTDOWN_GPIO 17
#define SENSOR_CHANNEL 0
#define SENSOR_SENSITIVITY 0.1
#define SENSOR_OFFSET 0.05
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds
#define MAX_SPI_RETRIES 3
#define CSV_FILE "current_log.csv"

static gpiod_line_request_linestate_t motor_shutdown_state = GPIOD_LINE_REQUEST_ACTIVE_LOW;
static gpiod_line_request *motor_shutdown_request;
static int spi_fd;
static char *spidev_mem;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_line_release(motor_shutdown_request);
        close(spi_fd);
        free(spidev_mem);
        exit(0);
    }
}

int read_adc(int channel) {
    int adc_value = 0;
    int data[3];

    for (int i = 0; i < MAX_SPI_RETRIES; ++i) {
        if (x exchange(spidev_mem + 6 + channel * 3, &adc_value, 0, spi_fd) == 1) {
            break;
        }
        usleep(10000);
    }

    if (i == MAX_SPI_RETRIES) {
        perror("Failed to read ADC value");
        exit(1);
    }

    data[0] = (adc_value & 0xFF);
    data[1] = (adc_value >> 8) & 0xFF;
    data[2] = (adc_value >> 16) & 0xFF;

    adc_value = (data[0] | (data[1] << 8) | (data[2] << 16)) * 3.3 / (1024 * 1023);

    return adc_value;
}

float get_current(int adc_value) {
    return (adc_value - SENSOR_OFFSET) * SENSOR_SENSITIVITY;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    if ((spidev_mem = mmap(NULL, 256, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0)) == MAP_FAILED) {
        perror("Failed to mmap SPI device");
        exit(1);
    }

    if (gpiod_chip_open_withlabel("gpiochip0") < 0) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if ((motor_shutdown_request = gpiod_chip_get_line_request_byname(gpiod_chip_get_fd(), "motor_shutdown")) == NULL) {
        perror("Failed to get motor shutdown line request");
        exit(1);
    }

    if (gpiod_line_request_enable(motor_shutdown_request, motor_shutdown_state) < 0) {
        perror("Failed to enable motor shutdown line");
        exit(1);
    }

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        exit(1);
    }

    time_t current_time;
    float current;
    int adc_value;

    while (1) {
        current_time = time(NULL);
        adc_value = read_adc(SENSOR_CHANNEL);
        current = get_current(adc_value);

        if (current > 10.0) {
            gpiod_line_set_value(motor_shutdown_request, 0);
            fprintf(csv_file, "%ld,%f,OVERCURRENT\n", current_time, current);
            sleep(1);
            gpiod_line_set_value(motor_shutdown_request, 1);
        } else {
            fprintf(csv_file, "%ld,%f\n", current_time, current);
        }

        fflush(csv_file);
        usleep(SAMPLE_INTERVAL);
    }

    fclose(csv_file);
    gpiod_line_release(motor_shutdown_request);
    close(spi_fd);
    munmap(spidev_mem, 256);
    gpiod_chip_close(gpiod_chip_get_fd());

    return 0;
}

