#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define REG_PRESSURE 0x00

static const char *LOG_FILE = "pressure_log.csv";

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_handle;
    uint16_t raw_value;
    double pressure_kPa;
    time_t timestamp;
    FILE *log_file;
    char log_line[128];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2c_handle = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 1000000);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        goto cleanup;
    }

    if (pigpio_i2c_write_read_data(i2c_handle, REG_PRESSURE, &raw_value, 2) < 0) {
        fprintf(stderr, "Failed to read pressure data from sensor\n");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    fprintf(log_file, "timestamp,pressure_kPa\n");
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (pigpio_i2c_write_read_data(i2c_handle, REG_PRESSURE, &raw_value, 2) < 0) {
            perror("I2C read failure");
            continue;
        }

        pressure_kPa = (raw_value / 65535.0) * 500.0;
        timestamp = time(NULL);
        ctime_r(&timestamp, log_line);
        snprintf(log_line + 11, sizeof(log_line) - 11, ",%.2f\n", pressure_kPa);
        fputs(log_line, log_file);
        fflush(log_file);
        sleep(1);
    }

cleanup:
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) pigpio_i2c_close(i2c_handle);
    gpioTerminate();
    return 0;
}

