#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

#define ADS1115_ADDR 0x48
#define AIN0 0
#define AIN1 1
#define PRESSURE_V_MIN 0.0
#define PRESSURE_V_MAX 5.0
#define PRESSURE_SCALE (400.0 / (PRESSURE_V_MAX - PRESSURE_V_MIN))
#define TEMP_V_MIN 1.0
#define TEMP_V_MAX 2.0
#define TEMP_SCALE ((100.0 - 0.0) / (TEMP_V_MAX - TEMP_V_MIN))
#define WARNING_PRESSURE 105.0
#define GPIO_LED 17

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }
    return 0;
}

int init_i2c(int addr) {
    if (i2cOpen(addr, &i2c_handle) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }
    return 0;
}

int configure_ads1115(int gain, int data_rate) {
    char config_reg[] = {0x00, 0x81, 0x00, 0x00};

    config_reg[1] = (gain << 5) | (data_rate << 2);

    if (i2cWriteReg16(i2c_handle, ADS1115_ADDR, 0x01, config_reg, sizeof(config_reg)) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }
    return 0;
}

float read_ads1115(int channel) {
    char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadReg16(i2c_handle, ADS1115_ADDR, 0x02 + (channel << 3), buf, 2) >= 0) {
            float adc_value = (buf[1] << 8) | buf[0];
            adc_value = adc_value * 3.3 / 4096;
            return adc_value;
        }
        retries--;
    }

    fprintf(stderr, "Failed to read ADS1115 after 3 retries\n");
    return NAN;
}

float pressure_to_kpa(float adc_value) {
    return PRESSURE_SCALE * (adc_value - PRESSURE_V_MIN);
}

float temperature_to_celsius(float adc_value) {
    return TEMP_SCALE * (adc_value - TEMP_V_MIN);
}

void setup_warning_led() {
    gpioSetMode(GPIO_LED, PI_OUTPUT);
}

void toggle_warning_led(float pressure) {
    if (pressure > WARNING_PRESSURE) {
        gpioWrite(GPIO_LED, 1);
    } else {
        gpioWrite(GPIO_LED, 0);
    }
}

void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    int ret;

    if (init_pigpio() != 0) {
        return 1;
    }

    if (init_i2c(ADS1115_ADDR) != 0) {
        goto cleanup;
    }

    if (configure_ads1115(2, 128) != 0) {
        goto cleanup;
    }

    setup_warning_led();

    while (1) {
        float pressure_adc = read_ads1115(AIN0);
        float temperature_adc = read_ads1115(AIN1);

        if (isnan(pressure_adc) || isnan(temperature_adc)) {
            fprintf(stderr, "Failed to read ADC values\n");
            continue;
        }

        float pressure = pressure_to_kpa(pressure_adc);
        float temperature = temperature_to_celsius(temperature_adc);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);
        toggle_warning_led(pressure);

        sleep(1);
    }

cleanup:
    cleanup();
    return 0;
}

