#include <pigpio.h>

#define MCP3008_CE 8
#define MCP3008_SCLK 11
#define MCP3008_MOSI 10
#define MCP3008_MISO 9
#define MLX91209_ANALOG_OUT 0
#define VCC 3.3
#define SENSITIVITY 66.0
#define ZERO_CURRENT_MIDPOINT (VCC / 2)
#define SAMPLE_INTERVAL 100
#define OVERCURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.txt"
#define GPIO27 27

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void log_current(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
