    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    float pressure;

    while (1) {
        int adc_value = read_adc(AIN0);
        if (adc_value >= 0) {
            pressure = voltage_to_pressure(adc_to_voltage(adc_value));
            if (pressure >= 0 && pressure <= 100000) { // 0-100 kPa range
                rawtime = time(NULL);
                timeinfo = localtime(&rawtime);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
                log_pressure(pressure);
                printf("%s %f kPa\n", timestamp, pressure / 1000.0); // Output in mPa for better readability
            }
        }
        usleep(1000000 / SAMPLE_RATE); // Sleep for the inverse of the sample rate
    }

    cleanup();
    return 0;
}

