#define ADC_CS_PIN 20
#define ADC_CLK_PIN 23
#define ADC_DO_PIN 24
#define HIH_VDD 5.0
#define HIH_R0 10000.0
#define HIH_BETA 3950.0
#define HIH_SLOPE 0.0315
#define HIH_OFFSET 0.824
#define EMAIL_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"

int init_pigpio();
int init_spi();
int init_adc();
float read_hih_humidity();
float read_hih_temperature();
float read_adc(int channel);
void log_reading(float humidity, float temperature);
void send_email_alert(const char *subject, const char *body);
void cleanup();

int main() {
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (init_spi() != 0 || init_adc() != 0) {
        fprintf(stderr, "Failed to initialize SPI or ADC\n");
        cleanup();
        return 1;
    }

    while (1) {
        float humidity = read_hih_humidity();
        float temperature = read_hih_temperature();

        if (humidity > EMAIL_THRESHOLD) {
            send_email_alert("High Humidity Alert",
                             "Humidity exceeded the threshold of 80%. Current humidity: "
                             + std::to_string(humidity) + "%");
        }

        log_reading(humidity, temperature);
        sleep(60);
    }

    cleanup();
    return 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        return -1;
    }
    return 0;
}

int init_spi() {
    spiOpen(0, SPI_MODE_0, 1000000);
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);
    gpioWrite(SPI_CS_PIN, 1);
    gpioSetMode(SPI_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(SPI_SCLK_PIN, PI_OUTPUT);
    return 0;
}

int init_adc() {
    int adc_fd = open("/dev/mem", O_RDONLY | O_SYNC);
    if (adc_fd < 0) {
        perror("Failed to open /dev/mem");
        return -1;
    }

    void *adc_base = mmap(NULL, 4096, PROT_READ, MAP_SHARED, adc_fd, 0x20200000);
    if (adc_base == MAP_FAILED) {
        perror("Failed to mmap /dev/mem");
        close(adc_fd);
        return -1;
    }

    gpioSetMode(ADC_CS_PIN, PI_OUTPUT);
    gpioWrite(ADC_CS_PIN, 1);

    uint32_t *adc_ctrl = (uint32_t *) (adc_base + 0x00);
    uint32_t *adc_data = (uint32_t *) (adc_base + 0x04);

    *adc_ctrl = 0x80000000 | (3 << 16) | (0 << 8) | 0x03; // MCP3208, 12-bit, single-ended, internal ref

    return 0;
}

float read_hih_humidity() {
    gpioWrite(SPI_CS_PIN, 0);

    uint8_t cmd[] = {0x2E, 0x00, 0x00, 0x00};
    spiWriteRead(SPI_MOSI_PIN, SPI_SCLK_PIN, cmd, 4, NULL, 0);

    gpioWrite(SPI_CS_PIN, 1);

    uint16_t adc_data = read_adc(0);
    float vout = adc_data * HIH_VDD / 4096;
    float rh = (vout - HIH_OFFSET) / HIH_SLOPE;

    return rh * 100;
}

float read_hih_temperature() {
    float r = read_adc(1);
    float temp = 1 / (1 / (1 / (HIH_BETA * (r / 10000 - 1)) - 1 / HIH_R0) - 273.15);
    return temp;
}

float read_adc(int channel) {
    gpioWrite(ADC_CS_PIN, 0);

    uint8_t cmd[] = {0x00, (channel << 6) | 0x03};
    spiWriteRead(ADC_DO_PIN, ADC_CLK_PIN, cmd, 2, NULL, 0);

    uint16_t data = *((uint16_t *) (ADC_DO_PIN + 12));
    gpioWrite(ADC_CS_PIN, 1);

    return data;
}

void log_reading(float humidity, float temperature) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s,%f,%f\n", timestamp, humidity, temperature);
    fclose(log_file);
}

void send_email_alert(const char *subject, const char *body) {
    // Implement email sending using ssmtp library
}

void cleanup() {
    spiClose(0);
    gpioTerm();
    munmap((void *) 0, 4096);
    close(0);
    exit(0);
}

