#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define GPIO_CHIP "/dev/gpiochip4"
#define GPIO_LINE "8"
#define TMP36_VREF 3.3
#define TMP36_MIN_VOLTAGE 0.0
#define TMP36_MAX_VOLTAGE 4.095
#define TMP36_MIN_TEMP -40.0
#define TMP36_MAX_TEMP 125.0
#define LOG_FILE "temperature_log.csv"

int spi_fd, gpio_fd, log_fd;
struct spi_ioc_transfer transfers[1];
struct gpiod_line *gpio_line;

void cleanup(void) {
    if (gpio_line) gpiod_line_put(gpio_line);
    if (spi_fd >= 0) close(spi_fd);
    if (gpio_fd >= 0) close(gpio_fd);
    if (log_fd >= 0) fclose(log_fd);
    munmap(transfers, sizeof(transfers));
}

void handle_signal(int sig) {
    printf("\nReceived signal %d, exiting gracefully...\n", sig);
    cleanup();
    exit(0);
}

float read_temp(void) {
    int ret;
    unsigned char data[3];
    struct spi_ioc_transfer *transfer = &transfers[0];

    transfer->tx_buf = (unsigned long*) &data;
    transfer->rx_buf = (unsigned long*) &data;
    transfer->len = 3;
    transfer->speed_hz = SPI_SPEED;
    transfer->bits_per_word = SPI_BITS;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer);
    if (ret < 1) {
        perror("Failed to read from SPI device");
        return NAN;
    }

    float voltage = (data[1] * TMP36_VREF) / (1 << 12);
    if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP36_MAX_VOLTAGE) {
        printf("Invalid temperature reading: %.4fV\n", voltage);
        return NAN;
    }

    float temperature = (voltage - 0.5) / 0.01;
    if (temperature < TMP36_MIN_TEMP || temperature > TMP36_MAX_TEMP) {
        printf("Invalid temperature reading: %.1f°C\n", temperature);
        return NAN;
    }

    return temperature;
}

int main(void) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    gpio_fd = gpiod_open_name_with_label(GPIO_CHIP, GPIO_LINE, GPIOD_IN_ACTIVE_LOW);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        return 1;
    }

    gpio_line = gpiod_get_line_by_index(gpio_fd, 0);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    gpiod_line_request_active_low(gpio_line, GPIOD_LINE_REQUEST_INPUT);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) != 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) != 0) {
        perror("Failed to set SPI max speed");
        return 1;
    }

    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    time_t now;
    float temperature;

    while (1) {
        gpiod_line_set_value(gpio_line, 1);
        usleep(100000);
        gpiod_line_set_value(gpio_line, 0);

        temperature = read_temp();
        if (isnan(temperature)) continue;

        now = time(NULL);
        fprintf(log_fd, "%ld,%.1f\n", (long) now, temperature);

        if (ftell(log_fd) == 0) {
            fprintf(log_fd, "timestamp,temperature_celsius\n");
        }
    }

    cleanup();
    return 0;
}

