        perror("Failed to open log file");
        return 1;
    }

    time_t now;
    float temperature;

    while (1) {
        gpiod_line_set_value(gpio_line, 1);
        usleep(100000);
        gpiod_line_set_value(gpio_line, 0);

        temperature = read_temp();
        if (isnan(temperature)) continue;

        now = time(NULL);
        fprintf(log_fd, "%ld,%.1f\n", (long) now, temperature);

        if (ftell(log_fd) == 0) {
            fprintf(log_fd, "timestamp,temperature_celsius\n");
        }
    }

    cleanup();
    return 0;
}
