        fprintf(stderr, "Failed to read ADC data\n");
        return -1;
    }

    gpioWrite(cs, 1);

    int vref = 3300; // 3.3V * 1024
    int adc_value = adc_data[ch];
    double voltage = (adc_value * vref) / ADC_MAX_VALUE;

    if (voltage < ADXL335_0G_POINT - (ADXL335_SENSITIVITY * 2.0)) {
        fprintf(stderr, "ADC value out of range: %.2f V\n", voltage);
        return -1;
    }

    return adc_value;
}

void log_data(const char *data) {
    write(STDOUT_FILENO, data, strlen(data));
}

void handle_sigint(int sig) {
    fprintf(stderr, "Received SIGINT, exiting...\n");
    exit(0);
}

