#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define CMD_REG 0xC0
#define FIFO_REG 0xC1
#define SAMPLES_PER_MEASUREMENT 4

static const char *log_file = "biometric_log.csv";

void log_row(uint16_t ir, uint16_t red, int error) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log_fp = fopen(log_file, "a");
    if (!log_fp) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_fp, "%s,HR,SpO2,Error\n", timestamp);
    fprintf(log_fp, "%s,%u,%u,%d\n", timestamp, ir, red, error);
    fflush(log_fp);
    fclose(log_fp);
}

int si1172_read(uint16_t *ir, uint16_t *red, int *error) {
    int i2c_fd = i2c_open(I2C_BUS, SI1172_ADDR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        *error = 2;
        return -1;
    }

    if (i2cWriteReadRegister16(i2c_fd, CMD_REG, 0, NULL, 0) < 0) {
        perror("Failed to write command register");
        *error = 1;
        i2cClose(i2c_fd);
        return -1;
    }

    uint16_t samples[SAMPLES_PER_MEASUREMENT];
    for (int i = 0; i < SAMPLES_PER_MEASUREMENT; ++i) {
        if (i2cWriteReadRegister16(i2c_fd, FIFO_REG, 2, &samples[i], 2) < 0) {
            perror("Failed to read FIFO register");
            *error = 1;
            i2cClose(i2c_fd);
            return -1;
        }
    }

    i2cClose(i2c_fd);

    *ir = samples[0];
    *red = samples[1];
    *error = 0;
    return 0;
}

int main(void) {
    int i2c_fd = -1;
    uint16_t ir, red;
    int error;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    if (i2c_fd = i2c_open(I2C_BUS, SI1172_ADDR) < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    FILE *log_fp = fopen(log_file, "w");
    if (!log_fp) {
        perror("Failed to create log file");
        i2cClose(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    fprintf(log_fp, "Timestamp,HR,SpO2,Error\n");
    fflush(log_fp);

    while (1) {
        if (si1172_read(&ir, &red, &error) < 0) {
            log_row(0, 0, error);
            continue;
        }

        log_row(ir, red, error);
        sleep(1);
    }

    fclose(log_fp);
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

