#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define SPI_MODE 0
#define SPI_BAUD 1000000
#define SPI_DEVICE 0
#define SPI_CE0_PIN 8

#define ADC_CS_PIN 7
#define ADC_CLK_PIN 11
#define ADC_MISO_PIN 9
#define ADC_MOSI_PIN 10

#define ADC_RESOLUTION 10
#define ADC_FULL_SCALE 3300
#define SCALE_FACTOR 0.02
#define OFFSET 0.5

#define FILENAME "flow_log.csv"

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void log_flow_rate(double flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    FILE *file;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + 19, sizeof(timestamp) - 19, ".%06lu", (unsigned long) (1e6 * (double) gpioGetTicks() / gpioTickResolution()));

    file = fopen(FILENAME, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,%f\n", timestamp, flow_rate);
    fflush(file);
    fclose(file);
}

double read_adc(int cs_pin, int clk_pin, int miso_pin, int mosi_pin) {
    uint8_t data[3] = {0};
    int i;

    gpioSetMode(cs_pin, PI_OUTPUT);
    gpioWrite(cs_pin, 0);

    gpioSetMode(clk_pin, PI_OUTPUT);
    gpioSetMode(miso_pin, PI_INPUT);
    gpioSetMode(mosi_pin, PI_OUTPUT);

    for (i = 0; i < 24; i++) {
        gpioWrite(clk_pin, 1);
        usleep(4);
        gpioWrite(clk_pin, 0);

        if (gpioRead(miso_pin)) {
            data[i / 8] |= (1 << (i % 8));
        }
    }

    gpioWrite(cs_pin, 1);

    if (data[2] == 0xFF && data[3] == 0x00) {
        return (double) data[1] * ADC_FULL_SCALE / (1 << (8 * ADC_RESOLUTION));
    }

    return 0.0;
}

double read_flow_rate() {
    int adc_value = read_adc(ADC_CS_PIN, ADC_CLK_PIN, ADC_MISO_PIN, ADC_MOSI_PIN);
    if (adc_value == 0 || adc_value == ADC_FULL_SCALE) {
        return NAN;
    }

    return SCALE_FACTOR * adc_value + OFFSET;
}

int main() {
    int spi_fd, adc_cs_pin, adc_clk_pin, adc_miso_pin, adc_mosi_pin;
    double flow_rate;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    spi_fd = gpioOpen(SPI_DEVICE, SPI_MODE, SPI_BAUD);
    if (spi_fd < 0) {
        perror("gpioOpen");
        return 1;
    }

    adc_cs_pin = ADC_CS_PIN;
    adc_clk_pin = ADC_CLK_PIN;
    adc_miso_pin = ADC_MISO_PIN;
    adc_mosi_pin = ADC_MOSI_PIN;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        flow_rate = read_flow_rate();
        if (isnan(flow_rate)) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            continue;
        }

        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Plausibility check failed: %f\n", flow_rate);
            continue;
        }

        log_flow_rate(flow_rate);
        usleep(1000000);
    }

    gpioTerm();
    close(spi_fd);

    return 0;
}

