        return (double) data[1] * ADC_FULL_SCALE / (1 << (8 * ADC_RESOLUTION));
    }

    return 0.0;
}

double read_flow_rate() {
    int adc_value = read_adc(ADC_CS_PIN, ADC_CLK_PIN, ADC_MISO_PIN, ADC_MOSI_PIN);
    if (adc_value == 0 || adc_value == ADC_FULL_SCALE) {
        return NAN;
    }

    return SCALE_FACTOR * adc_value + OFFSET;
}

int main() {
    int spi_fd, adc_cs_pin, adc_clk_pin, adc_miso_pin, adc_mosi_pin;
    double flow_rate;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    spi_fd = gpioOpen(SPI_DEVICE, SPI_MODE, SPI_BAUD);
    if (spi_fd < 0) {
        perror("gpioOpen");
        return 1;
    }

    adc_cs_pin = ADC_CS_PIN;
    adc_clk_pin = ADC_CLK_PIN;
    adc_miso_pin = ADC_MISO_PIN;
    adc_mosi_pin = ADC_MOSI_PIN;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        flow_rate = read_flow_rate();
        if (isnan(flow_rate)) {
            fprintf(stderr, "Invalid flow rate: %f\n", flow_rate);
            continue;
        }

        if (flow_rate < 0.0 || flow_rate > 5.0) {
            fprintf(stderr, "Plausibility check failed: %f\n", flow_rate);
            continue;
        }

        log_flow_rate(flow_rate);
        usleep(1000000);
    }

    gpioTerm();
    close(spi_fd);

    return 0;
}
```

This code initializes the pigpio library, opens the SPI device, initializes the MCP3008 ADC, and reads the flow rate every second. It logs the flow rate with a microsecond-precision timestamp in the specified format to a file named `flow_log.csv`. The code handles errors gracefully, including sensor-absent conditions, SPI bus errors, and plausibility checks. It also releases resources on exit paths and handles SIGINT and SIGTERM signals.

