#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <pigpio.h>

#define MCP3008_CE0_PIN 8
#define MCP3008_MOSI_PIN 10
#define MCP3008_SCK_PIN 9
#define MIC1_AIN0_PIN 18
#define MIC2_AIN1_PIN 19
#define SAMPLE_RATE 8000
#define GAIN (1.0 / 2.048) // Assuming 2.048V full-scale output from the microphones

volatile int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void spi_init(int spi_bus, int cs_pin) {
    gpioInitialise();
    gpioSetMode(cs_pin, PI_OUTPUT);
    gpioWrite(cs_pin, 0);
    gpioSetMode(spi_bus, PI_MODE_0);
    gpioSetSpeed(spi_bus, 1000000);
    gpioSetMode(PI_SPI_CS0, PI_OUTPUT);
    gpioSetMode(PI_SPI_SCK, PI_INPUT);
    gpioSetMode(PI_SPI_MOSI, PI_OUTPUT);
    gpioSetMode(PI_SPI_MISO, PI_INPUT);
}

int16_t read_adc(int channel) {
    int data = 0;
    gpioWrite(MCP3008_CE0_PIN, 0);
    usleep(10);
    gpioWrite(MCP3008_MOSI_PIN, (channel << 3) | 0x01);
    gpioWrite(MCP3008_CE0_PIN, 1);
    usleep(10);

    for (int i = 0; i < 16; i++) {
        usleep(1);
        data |= gpioRead(MCP3008_MISO_PIN) << (15 - i);
    }

    return data >> 4;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    double gain1 = atof(argv[1]);
    double gain2 = atof(argv[2]);

    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    spi_init(PI_SPI0, MCP3008_CE0_PIN);

    int mic1_data, mic2_data;
    double noise_cancellation_data;

    FILE *output_file = fopen("output.csv", "w");
    if (!output_file) {
        perror("fopen");
        return 1;
    }

    fprintf(output_file, "Time,Noise Cancellation\n");

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double time = ts.tv_sec + ts.tv_nsec * 1e-9;

    while (running) {
        mic1_data = read_adc(MIC1_AIN0_PIN) * GAIN * gain1;
        mic2_data = read_adc(MIC2_AIN1_PIN) * GAIN * gain2;

        noise_cancellation_data = mic1_data - mic2_data;

        fprintf(output_file, "%f,%f\n", time, noise_cancellation_data);

        ts = ts; // Prevent compiler warning
        clock_gettime(CLOCK_MONOTONIC, &ts);
        time = ts.tv_sec + ts.tv_nsec * 1e-9;

        usleep(1250000); // Adjust the sleep time to achieve the desired sample rate
    }

    fclose(output_file);
    gpioTerminate();

    return 0;
}

