#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define MCP3008_ADDR 0x48
#define CH0_BIT 0

static const char *LOG_FILE = "moisture_log.txt";

int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }
    return 0;
}

int init_spi(void) {
    if (gpioSetMode(PERIPHERAL, GPIO_BOARD_SPI0_CE0) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    if (gpioSetMode(PERIPHERAL, GPIO_BOARD_SPI0_SCK) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    if (gpioSetMode(PERIPHERAL, GPIO_BOARD_SPI0_MOSI) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    if (gpioSetMode(PERIPHERAL, GPIO_BOARD_SPI0_MISO) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    if (spiOpen(0, &g_spi_handle) < 0) {
        perror("spiOpen");
        return -1;
    }

    if (spiSetDataMode(g_spi_handle, SPI_MODE_0) < 0) {
        perror("spiSetDataMode");
        return -1;
    }

    if (spiSetBitsPerWord(g_spi_handle, 8) < 0) {
        perror("spiSetBitsPerWord");
        return -1;
    }

    if (spiSetMaxSpeedHz(g_spi_handle, 1000000) < 0) {
        perror("spiSetMaxSpeedHz");
        return -1;
    }

    return 0;
}

uint16_t read_adc(void) {
    uint16_t adc_value = 0;

    // Send SPI command for single-ended conversion on channel 0
    if (spiXfer(g_spi_handle, &adc_value, &adc_value, 2) != 2) {
        perror("spiXfer");
        return 0;
    }

    // Convert 10-bit raw value to voltage (0-5V) and moisture percentage (0-100%)
    float voltage = (adc_value * 5.0) / 1024.0;
    float moisture = (voltage - 0.5) * 100.0;

    if (moisture < 0 || moisture > 100) {
        fprintf(stderr, "Invalid moisture value: %f\n", moisture);
        return 0;
    }

    return adc_value;
}

void log_moisture(const char *timestamp, uint16_t adc_value) {
    FILE *log_file = fopen(LOG_FILE, "a");

    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s,%u\n", timestamp, adc_value);
    fclose(log_file);
}

void signal_handler(int sig) {
    gpioTerm();
    exit(0);
}

int main(void) {
    int ret;
    struct timespec ts;
    char timestamp[32];
    uint16_t adc_value;

    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_spi() < 0) {
        gpioTerm();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        asctime_r(localtime_r(&ts.tv_sec, timestamp), timestamp);
        timestamp[strlen(timestamp) - 1] = '\0';
        timestamp[strlen(timestamp) - 2] = 'T';
        timestamp[strlen(timestamp) - 3] = ' ';
        timestamp[strlen(timestamp) - 4] = 'Z';

        adc_value = read_adc();
        if (adc_value > 0) {
            log_moisture(timestamp, adc_value);
        }

        nanosleep((const struct timespec[]){{0, 60 * NANOSECONDS_PER_SECOND}}, NULL);
    }

