#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define MCP3008_CE0_PIN 8
#define MCP3008_MISO_PIN 9
#define MCP3008_MOSI_PIN 10
#define MCP3008_SCLK_PIN 11
#define LED_PIN 17

static pthread_t thread_id;
static FILE *json_file;

void sigint_handler(int signum) {
    printf("\nGracefully shutting down...\n");
    pthread_exit(NULL);
}

void spi_init() {
    if (gpioInitialise() < 0) {
        pigpio_error("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MCP3008_CE0_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_MISO_PIN, PI_INPUT) ||
        gpioSetMode(MCP3008_MOSI_PIN, PI_OUTPUT) ||
        gpioSetMode(MCP3008_SCLK_PIN, PI_OUTPUT)) {
        pigpio_error("Failed to set GPIO modes");
        exit(EXIT_FAILURE);
    }

    if (gpioSetSPI(MCP3008_CE0_PIN, MCP3008_MISO_PIN, MCP3008_MOSI_PIN, MCP3008_SCLK_PIN, 1000000, 0) < 0) {
        pigpio_error("Failed to initialize SPI");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc() {
    uint8_t tx_buf[3] = {0x01, 0x80 | (0 << 4), 0x00};
    uint8_t rx_buf[3];
    int ret;

    gpioWrite(MCP3008_CE0_PIN, 0);
    ret = spiXfer(MCP3008_CHIP_SELECT, tx_buf, sizeof(tx_buf), rx_buf, sizeof(rx_buf);
    gpioWrite(MCP3008_CE0_PIN, 1);

    if (ret < 0) {
        pigpio_error("Failed to read ADC");
        return 0;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

float adc_to_percentage(uint16_t adc_value) {
    return (float)adc_value / 1023 * 100.0;
}

void log_water_level(const char *timestamp, float water_level) {
    char json_entry[256];
    snprintf(json_entry, sizeof(json_entry), "{\"timestamp\":\"%s\",\"water_level\":%.2f}%s", timestamp, water_level, json_file ? "," : "");

    if (json_file) {
        fputs(json_entry, json_file);
        fflush(json_file);
    }

    printf("%s\n", json_entry);
}

void *main_loop(void *arg) {
    while (1) {
        uint16_t adc_value = read_adc();
        float water_level = adc_to_percentage(adc_value);

        log_water_level(iso8601_timestamp(NULL), water_level);

        if (water_level > 75.0f) {
            gpioWrite(LED_PIN, 1);
        } else if (water_level < 70.0f) {
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(100);
        sleep(5);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    spi_init();

    json_file = fopen("water_levels.json", "a");

    if (pthread_create(&thread_id, NULL, main_loop, NULL) != 0) {
        pigpio_error("Failed to create main loop thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    gpioTerm();
    fclose(json_file);

    return 0;
}

char *iso8601_timestamp(const struct timespec *ts) {
    char *timestamp;
    size_t size = 25;
    time_t now;
    struct tm *tm;

    if (ts) {
        now = ts->tv_sec;
    } else {
        now = time(NULL);
    }

    tm = localtime(&now);

    asctime_r(tm, &timestamp);
    timestamp[strlen(timestamp) - 1] = '\0';
    timestamp[strlen(timestamp) - 3] = 'T';
    timestamp[strlen(timestamp) - 2] = ':';
    timestamp[strlen(timestamp) - 1] = 'Z';

    if (ts) {
        snprintf(timestamp + strlen(timestamp), size - strlen(timestamp), ".%03ld", ts->tv_nsec / 1000000);
    }

    return timestamp;
}

