#include <pigpio.h>
#include <sys/mman.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define ADC_CHANNEL 0
#define CAL_DRY 300
#define CAL_WET 700
#define MOISTURE_THRESHOLD 30
#define LOG_FREQUENCY 60
#define MSMTP_CMD "msmtp -C /path/to/msmtp.conf"

static const char *email_recipient;
static const char *msmtp_config_path;
static int spi_fd, gpio_fd;
static char *log_file = "plant_data.txt";
static time_t last_log_time = 0;

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void log_moisture(int moisture) {
    time_t now = time(NULL);
    if (difftime(now, last_log_time) >= LOG_FREQUENCY) {
        FILE *log_file_ptr = fopen(log_file, "a");
        if (!log_file_ptr)
            die("Failed to open log file");

        char timestamp[30];
        ctime_r(&now, timestamp);
        timestamp[strlen(timestamp) - 1] = '\0';
        fprintf(log_file_ptr, "%s, %d%%\n", timestamp, moisture);
        fclose(log_file_ptr);
        last_log_time = now;
    }
}

void send_email_alert(int moisture) {
    char command[256];
    snprintf(command, sizeof(command), "%s << EOF\nTo: %s\nSubject: Soil Moisture Alert\n\nSoil moisture level is critically low: %d%%\nEOF", MSMTP_CMD, email_recipient, moisture);

    pid_t pid = fork();
    if (pid == -1)
        die("Failed to fork");

    if (!pid) {
        close(spi_fd);
        close(gpio_fd);
        execlp("sh", "sh", "-c", command, NULL);
        die("Failed to execute msmtp");
    }

    int status;
    waitpid(pid, &status, 0);
    if (WEXITSTATUS(status) != 0)
        fprintf(stderr, "Failed to send email alert\n");
}

int read_adc(void) {
    uint32_t adc_value;
    if (gpioPeripheralDataRead(SPI_BUS, SPI_DEVICE, &adc_value) < 0)
        die("Failed to read ADC value");

    return adc_value;
}

int main(int argc, char **argv) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <SPI bus> <SPI device> <ADC channel> <calibration dry> <calibration wet> <moisture threshold> <logging frequency> <email recipient> <msmtp config file>\n");
        return EXIT_FAILURE;
    }

    email_recipient = argv[6];
    msmtp_config_path = argv[7];

    int spi_bus = atoi(argv[1]);
    int spi_device = atoi(argv[2]);
    int adc_channel = atoi(argv[3]);
    int cal_dry = atoi(argv[4]);
    int cal_wet = atoi(argv[5]);
    int moisture_threshold = atoi(argv[5]);
    int log_frequency = atoi(argv[6]);

    if (gpioInitialise() < 0)
        die("Failed to initialize pigpio");

    gpio_fd = gpioOpen(0, 0, 0);
    if (gpioSetModeFunction(SPI_BUS, SPI_DEVICE, PI_FUNCTION_SPI) < 0 ||
        gpioSetMode(SPI_BUS, SPI_DEVICE, PI_INPUT) < 0 ||
        gpioSetMode(SPI_BUS, SPI_DEVICE + 1, PI_OUTPUT) ||
        gpioWrite(SPI_BUS, SPI_DEVICE + 1, 0) < 0 ||
        gpioSetClockDivider(SPI_BUS, 256) < 0 ||
        gpioSetDataMode(SPI_BUS, SPI_MODE_0) < 0 ||
        gpioSetSpidevSpeed(SPI_BUS, SPI_DEVICE, 500 * 1000) < 0)
        die("Failed to configure SPI");

    spi_fd = gpioOpen(SPI_BUS, SPI_DEVICE, GPIO_FD_READWRITE);
    if (spi_fd < 0)
        die("Failed to open SPI device");

    void *spi_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);
    if (spi_map == MAP_FAILED)
        die("Failed to map SPI device");

    int *spi_data = (int *)spi_map;

    while (1) {
        int moisture = (read_adc() - cal_dry) * 100.0 / (cal_wet - cal_dry);
        if (moisture < moisture_threshold) {
            send_email_alert(moisture);
        }
        log_moisture(moisture);
        sleep(log_frequency);
    }

    munmap(spi_map, 4096);
    close(spi_fd);
    gpioTerm();
    return EXIT_SUCCESS;
}

