#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define CHIP_SELECT GPIO8
#define ADC_CHANNEL 0

#define MOISTURE_MIN 0
#define MOISTURE_MAX 1023
#define MOISTURE_SCALE 100

static int g_spi_fd = -1;
static FILE *g_log_file = NULL;

void sigint_handler(int signum) {
    if (g_spi_fd != -1) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }

    return 0;
}

int open_spi() {
    g_spi_fd = gpioSPIOpen(SPI_BUS, SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    return 0;
}

int read_adc() {
    uint32_t adc_value = 0;
    if (gpioSPIXfer(g_spi_fd, &adc_value, 1, NULL, 4) != 4) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    return adc_value;
}

float calculate_moisture(uint32_t adc_value) {
    float moisture = (float)(adc_value - MOISTURE_MIN) / (MOISTURE_MAX - MOISTURE_MIN) * MOISTURE_SCALE;
    if (moisture < 0) {
        moisture = 0;
    } else if (moisture > MOISTURE_SCALE) {
        moisture = MOISTURE_SCALE;
    }

    return moisture;
}

int init_log_file(const char *filename) {
    g_log_file = fopen(filename, "w");
    if (g_log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", filename);
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    int sample_interval = 1000;
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
    }

    if (init_pigpio() != 0) {
        return 1;
    }

    if (gpioSetMode(CHIP_SELECT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for chip select\n");
        goto cleanup;
    }

    if (gpioSetMode(ADC_CHANNEL, PI_ANALOG) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for ADC channel\n");
        goto cleanup;
    }

    if (open_spi() != 0) {
        goto cleanup;
    }

    if (init_log_file("soil_moisture.log") != 0) {
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    time_t current_time;
    while (1) {
        gpioWrite(CHIP_SELECT, 0);
        if (read_adc() < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping sample\n");
            continue;
        }
        gpioWrite(CHIP_SELECT, 1);

        current_time = time(NULL);
        fprintf(g_log_file, "%s,%04u,%04u,%05u\n", ctime(&current_time), read_adc(), (uint32_t)calculate_moisture(read_adc()), time(NULL) % 1000000);
        fflush(g_log_file);

        usleep(sample_interval * 1000);
    }

cleanup:
    if (g_spi_fd != -1) {
        close(g_spi_fd);
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
    }

    gpioTerminate();

    return 0;
}

