            fprintf(stderr, "Failed to read ADC value, skipping sample\n");
            continue;
        }
        gpioWrite(CHIP_SELECT, 1);

        current_time = time(NULL);
        fprintf(g_log_file, "%s,%04u,%04u,%05u\n", ctime(&current_time), read_adc(), (uint32_t)calculate_moisture(read_adc()), time(NULL) % 1000000);
        fflush(g_log_file);

        usleep(sample_interval * 1000);
    }

cleanup:
    if (g_spi_fd != -1) {
        close(g_spi_fd);
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
    }

    gpioTerminate();

    return 0;
}
