#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_CE_PIN 8
#define ADC_MISO_PIN 9
#define ADC_MOSI_PIN 10
#define ADC_SCLK_PIN 11
#define ADC_CH_PIN 0
#define SENSOR_MIN_VOLTAGE 0.5
#define SENSOR_MAX_VOLTAGE 4.5
#define SENSOR_MIN_PRESSURE 10.0
#define SENSOR_MAX_PRESSURE 150.0
#define SAMPLE_INTERVAL 1000

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

double adc_read(void) {
    uint32_t adc_val;
    if (gpioRead(ADC_CE_PIN) != GPIO_LOW) {
        gpioWrite(ADC_CE_PIN, GPIO_LOW);
        spiWriteRead(ADC_MOSI_PIN, ADC_MISO_PIN, &adc_val, 3);
        gpioWrite(ADC_CE_PIN, GPIO_HIGH);
    }
    return (adc_val >> (8 - ADC_CH_PIN)) * 3.3 / (1 << ADC_CH_PIN);
}

double map_pressure(double adc_voltage) {
    double range = SENSOR_MAX_PRESSURE - SENSOR_MIN_PRESSURE;
    double offset = SENSOR_MIN_PRESSURE - (SENSOR_MIN_VOLTAGE - adc_voltage) * range / (SENSOR_MAX_VOLTAGE - SENSOR_MIN_VOLTAGE);
    return offset;
}

int main(void) {
    int ret;
    double adc_voltage, pressure;
    time_t timestamp;
    struct tm *tm;
    char timestamp_str[32];

    if ((ret = pigpio_init()) < 0) {
        die("pigpio_init");
    }

    if (gpioInitialise() < 0) {
        die("gpioInitialise");
    }

    gpioSetMode(ADC_CE_PIN, PI_OUTPUT);
    gpioSetMode(ADC_MISO_PIN, PI_INPUT);
    gpioSetMode(ADC_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(ADC_SCLK_PIN, PI_OUTPUT);

    signal(SIGINT, [](int sig) {
        pigpio_stop();
        gpioTerm();
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int sig) {
        pigpio_stop();
        gpioTerm();
        exit(EXIT_SUCCESS);
    });

    while (1) {
        adc_voltage = adc_read();
        if (adc_voltage < SENSOR_MIN_VOLTAGE || adc_voltage > SENSOR_MAX_VOLTAGE) {
            fprintf(stderr, "Invalid ADC voltage: %.2fV\n", adc_voltage);
            continue;
        }

        pressure = map_pressure(adc_voltage);
        time(&timestamp);
        tm = localtime(&timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", tm);
        printf("%s Pressure: %.2f kPa\n", timestamp_str, pressure);

        sleep(SAMPLE_INTERVAL / 1000.0);
    }

    gpioTerm();
    pigpio_stop();
    return EXIT_SUCCESS;
}

