#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define GPIO_CS_LINE "gpiochip0"
#define GPIO_CS_LINE_NUM 16

int spi_fd, gpio_fd;
struct spi_ioc_transfer transfers[1];
char read_buf[3] = {0};
char write_buf[4] = {0x40, 0x00, 0x00};

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer t = {
        .tx_buf = write_buf,
        .rx_buf = read_buf,
        .len = sizeof(write_buf),
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &t) < 1) {
        perror("Can't configure SPI");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    gpio_fd = gpiod_open_name_label(GPIO_CS_LINE, "MCP3008 CS");
    if (gpio_fd < 0) {
        perror("Can't open GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_direction_output(gpio_fd, GPIO_CS_LINE_NUM, GPIOD_ACTIVE_LOW);
}

uint16_t read_adc() {
    gpiod_set_value(gpio_fd, GPIO_CS_LINE_NUM, 1);
    usleep(10);
    gpiod_set_value(gpio_fd, GPIO_CS_LINE_NUM, 0);

    if (write(spi_fd, write_buf, sizeof(write_buf)) != sizeof(write_buf)) {
        perror("Can't write to SPI");
        exit(EXIT_FAILURE);
    }

    if (write(spi_fd, read_buf + 1, sizeof(read_buf) - 1) != sizeof(read_buf) - 1) {
        perror("Can't read from SPI");
        exit(EXIT_FAILURE);
    }

    uint16_t result = (read_buf[1] << 8) | read_buf[2];
    return result >> 2;
}

void log_moisture(float moisture) {
    printf("Moisture: %.2f%%\n", moisture * 100);
}

void signal_handler(int sig) {
    close(spi_fd);
    gpiod_close(gpio_fd);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    gpio_init();

    while (1) {
        float moisture = read_adc() / 1024.0;
        moisture = (moisture <= 0) ? 0 : (moisture >= 1) ? 1 : moisture;
        log_moisture(moisture);
        sleep(5);
    }

    return 0;
}

