#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <wiringPiSPI.h>

#define MOISTURE_LOW_THRESHOLD 300
#define MOISTURE_HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define SPI_CHIP_SELECT 0
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11
#define PUMP_GPIO 17

typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

volatile sig_atomic_t running = 1;
LogEntry log_buffer[BUFFER_SIZE];
int log_head = 0;
int log_tail = 0;

void signal_handler(int signum) {
    running = 0;
}

int read_moisture() {
    static const unsigned char adc_command[3] = {0x00, 0x00, 0x00};
    static const unsigned char adc_read_length = 3;
    unsigned char adc_response[3];
    int moisture_level;

    if (spiWriteRead(SPI_CHIP_SELECT, SPI_MOSI, SPI_MISO, adc_command, adc_read_length, adc_response) < adc_read_length) {
        fprintf(stderr, "Failed to read moisture sensor\n");
        return -1;
    }

    moisture_level = (adc_response[1] << 8) | adc_response[2];
    return moisture_level;
}

void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

void log_entry(LogEntry entry) {
    log_buffer[log_head] = entry;
    log_head = (log_head + 1) % BUFFER_SIZE;
}

void print_log() {
    int i;
    for (i = log_tail; i != log_head; i = (i + 1) % BUFFER_SIZE) {
        printf("%ld: Moisture: %d, Pump: %s\n", log_buffer[i].timestamp, log_buffer[i].moisture_level, log_buffer[i].pump_state ? "ON" : "OFF");
    }
}

int main() {
    int moisture_level;
    int pump_state = 0;
    struct timespec delay;
    time_t current_time;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (wiringPiSPISetup(SPI_CHIP_SELECT, 1000000) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        goto cleanup;
    }

    delay.tv_sec = 5;
    delay.tv_nsec = 0;

    while (running) {
        current_time = time(NULL);

        moisture_level = read_moisture();
        if (moisture_level < MOISTURE_LOW_THRESHOLD) {
            if (!pump_state) {
                control_pump(1);
                pump_state = 1;
                log_entry((LogEntry){current_time, moisture_level, pump_state});
            }
        } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state) {
            control_pump(0);
            pump_state = 0;
            log_entry((LogEntry){current_time, moisture_level, pump_state});
        }

        log_tail = (log_tail + 1) % BUFFER_SIZE;

        nanosleep(&delay, NULL);
    }

    control_pump(0);

cleanup:
    gpioTerminate();
    close(gpioTerm);

    print_log();
    return 0;
}

