void deinit_pigpio(void);
void deinit_i2c(int i2c_fd);
int read_max30102_part_id(int i2c_fd);
void write_max30102_reg(int i2c_fd, uint8_t reg, uint16_t value);
uint16_t read_max30102_reg(int i2c_fd, uint8_t reg, size_t len);
void log_error(const char *message);
void log_data(const char *timestamp, float spO2, float heart_rate);

int main(void) {
    int i2c_fd = -1;
    uint16_t part_id;

    if (init_pigpio() != 0) {
        log_error("Failed to initialize pigpio library");
        return 1;
    }

    if ((i2c_fd = init_i2c()) < 0) {
        log_error("Failed to open I2C device");
        goto cleanup_pigpio;
    }

    if (read_max30102_part_id(i2c_fd) != 0x15) {
        log_error("MAX30102 not found");
        goto cleanup_i2c;
    }

    write_max30102_reg(i2c_fd, MODE_CONFIG, 0x40);
    usleep(100000);
    write_max30102_reg(i2c_fd, MODE_CONFIG, 0x03);
    write_max30102_reg(i2c_fd, SPO2_CONFIG, 0x27);
    write_max30102_reg(i2c_fd, LED1_PA, 0x24);
    write_max30102_reg(i2c_fd, LED2_PA, 0x24);

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    while (1) {
        uint16_t data[6];
        size_t bytes_read = read_max30102_reg(i2c_fd, FIFO_REG, sizeof(data));
        if (bytes_read != sizeof(data)) {
            log_error("Failed to read FIFO data");
            continue;
        }

        float red_led = (data[0] * ADC_RANGE) / 255.0f;
        float ir_led = (data[1] * ADC_RANGE) / 255.0f;
        float spO2 = (red_led / ir_led) * 100.0f;
        float heart_rate = 60.0f / (data[3] * 1.0f / 1024.0f);

        if (spO2 < 95.0f || heart_rate > 100.0f) {
            rawtime = time(NULL);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            log_data(timestamp, spO2, heart_rate);
        }

        usleep(1000000);
    }

cleanup_i2c:
    deinit_i2c(i2c_fd);

cleanup_pigpio:
    deinit_pigpio();

    return 0;
}

int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        perror("pigpio_init");
        return 1;
    }
    return 0;
}

int init_i2c(void) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAX30102_ADDR) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

void deinit_pigpio(void) {
    gpioTerminate();
}

void deinit_i2c(int i2c_fd) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int read_max30102_part_id(int i2c_fd) {
    uint8_t data[2];
    if (write_max30102_reg(i2c_fd, 0xFF, 1) != 1 ||
        read_max30102_reg(i2c_fd, 0xFF, sizeof(data)) != 1) {
        return -1;
    }

    return data[0];
}

void write_max30102_reg(int i2c_fd, uint8_t reg, uint16_t value) {
    uint8_t data[3];
    data[0] = reg;
    data[1] = value >> 8;
    data[2] = value & 0xFF;
    write(i2c_fd, data, sizeof(data));
}

uint16_t read_max30102_reg(int i2c_fd, uint8_t reg, size_t len) {
    uint8_t data[len + 1];
    data[0] = reg;
    write(i2c_fd, &data, 1);
    read(i2c_fd, &data, len);

    uint16_t result = 0;
    for (size_t i = 0; i < len; ++i) {
        result = (result << 8) | data[i + 1];
    }

    return result;
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void log_data(const char *timestamp, float spO2, float heart_rate) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s, SpO2: %.2f%%, Heart Rate: %.1f bpm\n", timestamp, spO2, heart_rate);
        fclose(log_file);
    }
}
