#define SPI_MODE 0
#define SPI_SPEED 1000000
#define MCP3008_CS 18
#define MCP3008_CMD_START 0x40
#define MCP3008_CMD_LEN 3
#define MCP3008_CMD_SINGLE_END_SHIFT 4

static FILE *csv_file;

void log_to_csv(int channel, uint16_t voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(csv_file, "%s,%d,%d\n", time_str, channel, voltage);
}

int mcp3008_read(uint16_t *result, int channel) {
    static uint8_t tx_buf[MCP3008_CMD_LEN] = {0};
    static uint8_t rx_buf[3] = {0};
    int status;

    tx_buf[0] = MCP3008_CMD_START;
    tx_buf[1] = (channel << MCP3008_CMD_SINGLE_END_SHIFT) | 0x03; // Single-ended, 10-bit
    tx_buf[2] = 0;

    status = gpioSPIWriteRead(MCP3008_CS, SPI_MODE, SPI_SPEED, tx_buf, MCP3008_CMD_LEN, rx_buf, 3);
    if (status < 0) {
        perror("SPI Write/Read Error");
        return -1;
    }

    *result = (rx_buf[1] & 0x03) << 8 | rx_buf[2];
    return 0;
}

void setup() {
    if ((csv_file = fopen("analog_log.csv", "w")) == NULL) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MCP3008_CS, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    gpioWrite(MCP3008_CS, 1);
}

void teardown() {
    fclose(csv_file);
    gpioTerminate();
}

int main(void) {
    setup();
    uint16_t readings[3] = {0};
    int i;

    for (i = 0; i < 3; ++i) {
        if (mcp3008_read(&readings[i], i) < 0) {
            perror("Failed to read ADC channel");
            teardown();
            return EXIT_FAILURE;
        }
    }

    while (1) {
        for (i = 0; i < 3; ++i) {
            if (mcp3008_read(&readings[i], i) < 0) {
                perror("Failed to read ADC channel");
                continue;
            }

            log_to_csv(i, (3300 * readings[i]) / readings[2]);
        }
        usleep(500000);
    }

    teardown();
    return EXIT_SUCCESS;
}

