#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>

#define ADS1115_ADDR 0x48
#define ADS1115_PWDN_BIT 0x01
#define ADS1115_MUX_REG 0x01
#define ADS1115_CONFIG_REG 0x00
#define ADS1115_ADC_RES 12
#define ADS1115_ADC_MAX_VAL (1 << ADS1115_ADC_RES)
#define IR_SENSOR_GPIO 0
#define RELAY_GPIO 17
#define DOOR_SENSOR_GPIO 27
#define SAMPLES_FOR_CALIBRATION 10
#define SAMPLE_DELAY_MS 50
#define POLL_DELAY_MS 200
#define THRESHOLD_PERCENTAGE 80
#define LOG_FILE "/var/log/door_events.log"

struct i2c_rdwr_ioctl_data {
    struct i2c_msg messages[2];
};

int init_i2c(void) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

int init_gpio(void) {
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_HIGH;
    int ret;

    gpiod_line_request_dt_node gpio_req_nodes[] = {
        { .name = "gpio" , .offset = offsetof(struct device_node, gpio) },
        { .name = "gpio-chip", .offset = offsetof(struct gpiochip, base_gpios) },
    };

    gpiod_line_request_data_vlinstr_array data = {
        { .gpio = IR_SENSOR_GPIO, .flags = flags },
        { .gpio = RELAY_GPIO, .flags = GPIOD_LINE_REQUEST_OUTPUT },
        { .gpio = DOOR_SENSOR_GPIO, .flags = flags },
    };

    gpiod_line_request_data_array data_array = {
        .array = data,
        .count = ARRAY_SIZE(data),
        .dt_node_array = gpio_req_nodes,
        .dt_node_count = ARRAY_SIZE(gpio_req_nodes),
    };

    ret = gpiod_chip_request_lines(0, &data_array);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        return -1;
    }

    return 0;
}

uint16_t read_adc(int i2c_fd) {
    struct i2c_rdwr_ioctl_data data = {
        .messages = {
            {
                .addr = ADS1115_ADDR,
                .flags = 0,
                .len = 2,
                .buf = (char*)&cmd,
            },
            {
                .addr = ADS1115_ADDR,
                .flags = I2C_M_RD,
                .len = 2,
                .buf = (char*)&result,
            },
        },
    };

    cmd[0] = ADS1115_MUX_REG | (IR_SENSOR_GPIO << 3);
    cmd[1] = ADS1115_CONFIG_REG | ADS1115_ADC_RES;

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        perror("Failed to read ADC");
        return 0;
    }

    return (result[0] << 8) | result[1];
}

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s %s\n", timestamp, event);
    fclose(log_file);
}

int main(void) {
    int i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(i2c_fd);
        return 1;
    }

    uint16_t baseline_samples[SAMPLES_FOR_CALIBRATION];
    uint16_t average = 0;
    for (int i = 0; i < SAMPLES_FOR_CALIBRATION; ++i) {
        usleep(SAMPLE_DELAY_MS * 1000);
        baseline_samples[i] = read_adc(i2c_fd);
        average += baseline_samples[i];
    }
    average /= SAMPLES_FOR_CALIBRATION;

    float threshold = average * THRESHOLD_PERCENTAGE / 100.0;

    while (1) {
        uint16_t reading = read_adc(i2c_fd);
        if (reading < threshold) {
            gpiod_line_set_value_cansleep(RELAY_GPIO, 1);
            usleep(3 * 1000 * 1000);
            gpiod_line_set_value_cansleep(RELAY_GPIO, 0);

            int door_open = gpiod_line_get_value_cansleep(DOOR_SENSOR_GPIO);
            if (!door_open) {
                log_event("door opened");
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    gpiod_chip_release_lines(0);
    close(i2c_fd);

    return 0;
}

