    for (int i = 0; i < SAMPLES_FOR_CALIBRATION; ++i) {
        usleep(SAMPLE_DELAY_MS * 1000);
        baseline_samples[i] = read_adc(i2c_fd);
        average += baseline_samples[i];
    }
    average /= SAMPLES_FOR_CALIBRATION;

    float threshold = average * THRESHOLD_PERCENTAGE / 100.0;

    while (1) {
        uint16_t reading = read_adc(i2c_fd);
        if (reading < threshold) {
            gpiod_line_set_value_cansleep(RELAY_GPIO, 1);
            usleep(3 * 1000 * 1000);
            gpiod_line_set_value_cansleep(RELAY_GPIO, 0);

            int door_open = gpiod_line_get_value_cansleep(DOOR_SENSOR_GPIO);
            if (!door_open) {
                log_event("door opened");
            }
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    gpiod_chip_release_lines(0);
    close(i2c_fd);

    return 0;
}
```

This code initializes the I2C bus, ADS1115 ADC, and GPIO lines using libgpiod. It takes 10 baseline samples, calculates the threshold, and then continuously polls the ADC. If the reading drops below the calibrated threshold, it energizes the relay for 3 seconds to release the door lock, reads the door sensor, and logs the event.

The code also logs every event with millisecond timestamps to /var/log/door_events.log. On SIGINT/SIGTERM, it de-energizes the relay, releases all libgpiod lines, closes the I2C file descriptor, and exits cleanly.

