#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS0_LINE "gpiochip0\0gpio24"
#define CS1_LINE "gpiochip0\0gpio27"
#define CS2_LINE "gpiochip0\0gpio25"
#define BAUD_RATE 1000000
#define CHIP_SELECT_LOW gpiod_line_request_value_cansleep(line, 0)
#define CHIP_SELECT_HIGH gpiod_line_request_value_cansleep(line, 1)
#define SENSOR_COUNT 3
#define DELAY_MS 5000

int main() {
    int spi_fd, ret;
    struct spi_ioc_transfer transfers[SENSOR_COUNT];
    char filename[64];
    FILE *file;
    gpiod_line_request_data lines[SENSOR_COUNT];
    gpiod_chip *chip;

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    // Configure SPI parameters
    struct spi_ioc_transfer setup_transfer = {
        .tx_buf = (unsigned char[]) {0x01, 0x40, 0x00},
        .len = 3,
        .speed_hz = BAUD_RATE,
        .bits_per_word = 8,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &setup_transfer) < 1) {
        perror("Can't configure SPI");
        exit(EXIT_FAILURE);
    }

    // Request chip select lines
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Can't open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_array(chip, SENSOR_COUNT, lines, GPIOD_LINE_REQUEST_INPUT, NULL);
    if (ret < 0) {
        perror("Can't request GPIO lines");
        exit(EXIT_FAILURE);
    }

    // Initialize sensor read transfers
    for (int i = 0; i < SENSOR_COUNT; ++i) {
        transfers[i].tx_buf = (unsigned char[]) {0x01, (0x08 | i) << 4, 0x00};
        transfers[i].len = 3;
        transfers[i].speed_hz = BAUD_RATE;
        transfers[i].bits_per_word = 8;
        transfers[i].cs_change = 0;
    }

    // Open log file
    snprintf(filename, sizeof(filename), "soil_moisture_log.csv");
    file = fopen(filename, "w");
    if (!file) {
        perror("Can't open log file");
        exit(EXIT_FAILURE);
    }

    if (fprintf(file, "timestamp,sensor1,sensor2,sensor3\n") < 0) {
        perror("Can't write log file header");
        exit(EXIT_FAILURE);
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    while (1) {
        for (int i = 0; i < SENSOR_COUNT; ++i) {
            CHIP_SELECT_LOW(lines[i].line);
            ret = write(spi_fd, transfers + i, sizeof(transfers[0]));
            if (ret != sizeof(transfers[0])) {
                perror("Can't write to SPI");
                exit(EXIT_FAILURE);
            }
            CHIP_SELECT_HIGH(lines[i].line);

            ret = read(spi_fd, transfers + i, sizeof(transfers[0]));
            if (ret != sizeof(transfers[0])) {
                perror("Can't read from SPI");
                exit(EXIT_FAILURE);
            }

            int sensor_value = (transfers[i].rx_buf[1] & 0x0F) << 8 | transfers[i].rx_buf[2];
            fprintf(file, "%lld,%d,", timestamp, sensor_value >= 0 ? sensor_value : -1);
        }

        ts = timespec_add(ts, (struct timespec){0, DELAY_MS * 1000000});
        clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);
        timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        // Check for SIGINT or SIGTERM
        if (sigismember(&(sigset_t){SIGINT, SIGTERM}, sigaction(SIGINT, NULL, NULL)->sa_mask.sig[0])) {
            break;
        }
    }

    // Close log file
    fclose(file);

    // Free GPIO lines and chip
    for (int i = 0; i < SENSOR_COUNT; ++i) {
        gpiod_line_release(lines[i].line);
    }
    gpiod_chip_release(chip);

    // Close SPI device
    close(spi_fd);

    return 0;
}

