#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define MCP3008_ADDR 0x48
#define GPIO_PUMP 18
#define GPIO_CE0 8
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

typedef struct {
    int threshold;
    int duration;
    int sleep_interval;
} Config;

void log_moisture(int moisture) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s: Moisture: %d%%\n", timestamp, moisture);
    fprintf(stderr, "%s: Moisture: %d%%\n", timestamp, moisture);
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file) {
        fprintf(log_file, "%s: Moisture: %d%%\n", timestamp, moisture);
        fclose(log_file);
    }
}

void log_error(const char *message) {
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s: Error: %s\n", timestamp, message);
    fprintf(stderr, "%s: Error: %s\n", timestamp, message);
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file) {
        fprintf(log_file, "%s: Error: %s\n", timestamp, message);
        fclose(log_file);
    }
}

int read_adc(int channel) {
    int adc_value = 0;
    int retries = 3;
    while (retries > 0) {
        if (gpioSPIWriteRead(MCP3008_ADDR, (channel << 3) | 0x01, &adc_value, 2) == 0) {
            return adc_value;
        }
        retries--;
    }
    log_error("Failed to read ADC value");
    return -1;
}

void map_moisture(int adc_value, int *moisture) {
    *moisture = (adc_value - 200) * 100 / (800 - 200);
    if (*moisture < 0) {
        *moisture = 0;
    }
    if (*moisture > 100) {
        *moisture = 100;
    }
}

int main(int argc, char *argv[]) {
    Config config = {DEFAULT_THRESHOLD, DEFAULT_DURATION, DEFAULT_SLEEP_INTERVAL};
    int moisture = 0;
    int pump_on = 0;
    int spi_fd = -1;

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        exit(1);
    }

    gpioSetMode(GPIO_PUMP, PI_OUTPUT);
    gpioSetMode(GPIO_CE0, PI_OUTPUT);

    if (gpioSetSPI(0, SPI_MODE, SPI_SPEED) < 0) {
        log_error("Failed to set SPI");
        goto cleanup;
    }

    spi_fd = gpioOpen(0, PI_READ_WRITE, 0, 0);
    if (spi_fd < 0) {
        log_error("Failed to open SPI");
        goto cleanup;
    }

    if (argc > 1) {
        for (int i = 1; i < argc; ++i) {
            if (strcmp(argv[i], "-t") == 0 && (i + 1) < argc) {
                config.threshold = atoi(argv[++i]);
            } else if (strcmp(argv[i], "-d") == 0 && (i + 1) < argc) {
                config.duration = atoi(argv[++i]);
            } else if (strcmp(argv[i], "-s") == 0 && (i + 1) < argc) {
                config.sleep_interval = atoi(argv[++i]);
            }
        }
    }

    while (1) {
        gpioDigitalWrite(GPIO_CE0, 0);
        int adc_value = read_adc(ADC_CHANNEL);
        gpioDigitalWrite(GPIO_CE0, 1);

        if (adc_value == -1) {
            log_error("Failed to read ADC value");
            continue;
        }

        map_moisture(adc_value, &moisture);
        log_moisture(moisture);

        if (moisture < config.threshold) {
            if (!pump_on) {
                gpioDigitalWrite(GPIO_PUMP, 1);
                pump_on = 1;
                log_moisture(moisture);
                log_moisture(moisture + " - Pump activated");
                sleep(config.duration);
            }
        } else {
            if (pump_on) {
                gpioDigitalWrite(GPIO_PUMP, 0);
                pump_on = 0;
                log_moisture(moisture);
                log_moisture(moisture + " - Pump deactivated");
            }
        }

        sleep(config.sleep_interval);
    }

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpioTerminate();
    return 0;

    // Handle SIGINT and SIGTERM here, shut off the pump and exit cleanly
    // ...
}

