- CE0 (Chip Enable) on GPIO8
- CLK (Clock) on GPIO11
- MOSI (Master Out, Slave In) on GPIO10
- MISO (Master In, Slave Out) on GPIO9

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define ADC_CS_PIN 8
#define ADC_CLK_PIN 11
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define SAMPLE_INTERVAL_US 10000
#define EMA_ALPHA 0.2
#define PEAK_THRESHOLD_MARGIN 20

static int g_log_fd = -1;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_peak(time_t timestamp, int value) {
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%f", localtime(&timestamp));
    fprintf(g_log_fd, "%s,%d\n", timestamp_str, value);
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return -1;
    }

    gpioSetMode(ADC_CS_PIN, PI_OUTPUT);
    gpioSetMode(ADC_CLK_PIN, PI_OUTPUT);
    gpioSetMode(ADC_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(ADC_MISO_PIN, PI_INPUT);

    return 0;
}

int init_spi() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return -1;
    }

    if (spiOpen(0, &g_spi_handle) < 0) {
        log_error("Failed to open SPI bus");
        return -1;
    }

    spiSlaveSelect(g_spi_handle, ADC_CS_PIN);
    spiWriteRead(g_spi_handle, 0x00, &g_adc_data, 3);
    spiSlaveSelect(g_spi_handle, 0);

    return 0;
}

void deinit_spi() {
    spiClose(g_spi_handle);
}

int read_adc() {
    spiSlaveSelect(g_spi_handle, ADC_CS_PIN);
    spiWriteRead(g_spi_handle, 0x40 | (0x03 << 3), &g_adc_data, 3);
    spiSlaveSelect(g_spi_handle, 0);

    int raw_value = (g_adc_data[1] << 8) | g_adc_data[2];
    return raw_value;
}

double calculate_ema(double current, double previous, double alpha) {
    return current * (1 - alpha) + previous * alpha;
}

int main(int argc, char *argv[]) {
    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_spi() < 0) {
        goto cleanup_pigpio;
    }

    g_log_fd = open("/var/log/sound_events.log", O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (g_log_fd < 0) {
        log_error("Failed to open log file");
        goto cleanup_spi;
    }

    double ema_value = 0.0;
    time_t last_peak_time = 0;

    while (1) {
        usleep(SAMPLE_INTERVAL_US);

        int raw_value = read_adc();
        double current_value = (double)raw_value / 1023.0;
        ema_value = calculate_ema(current_value, ema_value, EMA_ALPHA);

        if (current_value > ema_value * (1 + PEAK_THRESHOLD_MARGIN / 100.0)) {
            time_t current_time = time(NULL);
            if (current_time > last_peak_time + 1) {
                log_peak(current_time, raw_value);
                last_peak_time = current_time;
            }
        }
    }

cleanup_spi:
    deinit_spi();
cleanup_pigpio:
    gpioTerm();

    if (g_log_fd >= 0) {
        close(g_log_fd);
    }

    return 0;
}
