    // Configure PCF8591 control byte
    control_byte = 0b00000000; // Single-ended mode, analog output disabled

    // Prepare I2C messages
    i2c_msgs[0].addr = PCF8591_ADDR;
    i2c_msgs[0].flags = 0;
    i2c_msgs[0].len = 1;
    i2c_msgs[0].buf = (char *)&control_byte;

    i2c_msgs[1].addr = PCF8591_ADDR;
    i2c_msgs[1].flags = I2C_M_RD;
    i2c_msgs[1].len = 1;
    i2c_msgs[1].buf = &dummy_data;

    // Perform dummy read and discard the byte
    ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        perror("Failed to perform dummy read");
        close(i2c_fd);
        gpiod_put_line(ain0_line, 0);
        exit(1);
    }

    while (1) {
        // Prepare I2C messages for reading ADC value
        i2c_msgs[0].addr = PCF8591_ADDR;
        i2c_msgs[0].flags = 0;
        i2c_msgs[0].len = 0;
        i2c_msgs[1].addr = PCF8591_ADDR;
        i2c_msgs[1].flags = I2C_M_RD;
        i2c_msgs[1].len = 1;
        i2c_msgs[1].buf = (char *)malloc(1);

        // Read ADC value and print it
        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read ADC value");
            close(i2c_fd);
            gpiod_put_line(ain0_line, 0);
            exit(1);
        }
        printf("%d\n", *(unsigned char *)i2c_msgs[1].buf);

        // Wait 100ms
        usleep(100000);
    }

    // Clean up resources on SIGINT
    signal(SIGINT, [](int sig) {
        close(i2c_fd);
        gpiod_put_line(ain0_line, 0);
        exit(0);
    });

    return 0;
}

