#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <adc1115.h>
#include <pigpio.h>

#define SS49E_THRESHOLD 500.0f
#define BUFFER_SIZE 10
#define ADC_RESOLUTION 12
#define ADC_GAIN 1
#define ADC_VREF 3300.0f // 3.3V * 2^12

float ss49e_transfer_function(float voltage) {
    return (voltage - 2.5f) / (1.4f * 1000.0f);
}

struct reading {
    float voltage;
    float gauss;
    time_t timestamp;
};

void log_message(const char *message) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_PERROR, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

void i2c_read_adc(int adc_address, float *value) {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return;
    }

    if (ioctl(file, I2C_SLAVE, adc_address) < 0) {
        perror("Failed to acquire I2C bus");
        close(file);
        return;
    }

    adc_read_single_ended(file, ADC_MUX_AIN0, ADC_RESOLUTION, ADC_GAIN, ADC_VREF, value);
    close(file);
}

void gpio_setup(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_NUM_27, PI_OUTPUT);
    gpioWrite(GPIO_NUM_27, 0);
}

void gpio_shutdown(void) {
    gpioWrite(GPIO_NUM_27, 1);
}

void buffer_push(struct reading *buffer, struct reading reading) {
    int index = (int)(time(NULL) % BUFFER_SIZE);
    for (int i = BUFFER_SIZE - 1; i > index; i--) {
        buffer[i] = buffer[i - 1];
    }
    buffer[index] = reading;
}

float buffer_average(const struct reading *buffer, size_t size) {
    float sum = 0.0f;
    for (size_t i = 0; i < size; i++) {
        sum += buffer[i].gauss;
    }
    return sum / size;
}

void signal_handler(int signal) {
    gpio_shutdown();
    gpioTerm();
    exit(signal);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gpio_setup();

    struct reading buffer[BUFFER_SIZE];
    float voltage;

    while (1) {
        i2c_read_adc(0x48, &voltage);

        if (voltage < 0.0f || voltage > ADC_VREF) {
            log_message("Invalid ADC reading");
            continue;
        }

        float gauss = ss49e_transfer_function(voltage);
        buffer_push(buffer, (struct reading){voltage, gauss, time(NULL)});

        float average = buffer_average(buffer, BUFFER_SIZE);
        if (average > SS49E_THRESHOLD) {
            log_message("Magnetic field exceeded threshold");
            gpio_shutdown();
        }

        sleep(1);
    }

    return 0;
}

