#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define ADC_CH 0
#define ADC_FREQ 1000000
#define ADC_MODE 0
#define ADC_RES 10
#define THRESHOLD 300
#define RELAY_PIN 18
#define LOG_FILE "watering_events.txt"
#define WATERING_DURATION 10
#define WAIT_BETWEEN_READINGS 60

typedef struct {
    time_t timestamp;
    int moisture_level;
} WateringEvent;

int init_gpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    return 0;
}

int init_adc() {
    int spi_fd = spiOpen(0, ADC_MODE, ADC_FREQ);
    if (spi_fd < 0) {
        perror("spiOpen");
        return -1;
    }

    if (spiWriteRead(spi_fd, &ADC_CH, sizeof(ADC_CH), NULL, 0) < 0) {
        perror("spiWriteRead");
        close(spi_fd);
        return -1;
    }

    void *map_base = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);
    if (map_base == MAP_FAILED) {
        perror("mmap");
        close(spi_fd);
        return -1;
    }

    close(spi_fd);

    return (int)map_base;
}

int read_moisture(void *adc_base) {
    int adc_val = 0;
    if (spiXfer(adc_base, &ADC_CH, sizeof(ADC_CH), &adc_val, sizeof(adc_val)) < 0) {
        perror("spiXfer");
        munmap(adc_base, 4096);
        return -1;
    }

    adc_val = (adc_val >> 2) & ((1 << ADC_RES) - 1);

    if (adc_val < 0 || adc_val > (1 << ADC_RES)) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_val);
        munmap(adc_base, 4096);
        return -1;
    }

    return adc_val;
}

void log_event(WateringEvent event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: Moisture level: %d\n", ctime(&now), event.moisture_level);
    fclose(log_file);
}

void water() {
    gpioWrite(RELAY_PIN, 1);
    sleep(WATERING_DURATION);
    gpioWrite(RELAY_PIN, 0);
}

int main() {
    int gpio_init_status = init_gpio();
    if (gpio_init_status < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        goto cleanup;
    }

    void *adc_base = init_adc();
    if (adc_base == MAP_FAILED) {
        fprintf(stderr, "Failed to initialize ADC\n");
        gpioTerm();
        goto cleanup;
    }

    WateringEvent last_event = {0};
    time_t last_read = 0;

    while (1) {
        int moisture_level = read_moisture(adc_base);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level\n");
            gpioTerm();
            goto cleanup;
        }

        time_t current_time = time(NULL);
        if (current_time - last_read > WAIT_BETWEEN_READINGS) {
            last_read = current_time;

            if (moisture_level < THRESHOLD) {
                water();
                last_event.moisture_level = moisture_level;
                last_event.timestamp = current_time;
                log_event(last_event);
            }
        }

        usleep(100000);
    }

cleanup:
    munmap(adc_base, 4096);
    gpioTerm();
    return 0;
}

