    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "%s: Moisture level: %d\n", ctime(&now), event.moisture_level);
    fclose(log_file);
}

void water() {
    gpioWrite(RELAY_PIN, 1);
    sleep(WATERING_DURATION);
    gpioWrite(RELAY_PIN, 0);
}

int main() {
    int gpio_init_status = init_gpio();
    if (gpio_init_status < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        goto cleanup;
    }

    void *adc_base = init_adc();
    if (adc_base == MAP_FAILED) {
        fprintf(stderr, "Failed to initialize ADC\n");
        gpioTerm();
        goto cleanup;
    }

    WateringEvent last_event = {0};
    time_t last_read = 0;

    while (1) {
        int moisture_level = read_moisture(adc_base);
        if (moisture_level < 0) {
            fprintf(stderr, "Failed to read moisture level\n");
            gpioTerm();
            goto cleanup;
        }

        time_t current_time = time(NULL);
        if (current_time - last_read > WAIT_BETWEEN_READINGS) {
            last_read = current_time;

            if (moisture_level < THRESHOLD) {
                water();
                last_event.moisture_level = moisture_level;
                last_event.timestamp = current_time;
                log_event(last_event);
            }
        }

        usleep(100000);
    }

cleanup:
    munmap(adc_base, 4096);
    gpioTerm();
    return 0;
}
```

To compile the code, install the pigpio library and run:

```sh
gcc -o moisture_monitor moisture_monitor.c -lwiringPi -lpthread -lrt
```

Then, run the compiled program with:

```sh
sudo ./moisture_monitor
```

The program will log watering events to 'watering_events.txt' and activate the water pump when the soil moisture level drops below the specified threshold. The pump will run for 10 seconds per watering cycle, and readings will be taken every 60 seconds. The program will gracefully handle errors and release resources on SIGINT/SIGTERM.

