    gpioSetMode(OUTPUT, GPIO_1, ALT0); // MCP3008 CS

    while (1) {
        gpioWrite(GPIO_1, 0); // MCP3008 CS low

        if (spiXfer(spi_fd, (const unsigned char[]) {0x40 | (CHANNEL << 5)},
                    (unsigned char*)&adc_value, 2) != 2) {
            printf("SPI transfer failed, retrying...\n");
            continue;
