#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define ADC_SPI_CHIP_SELECT 8
#define ADC_SPI_MODE 0
#define ADC_SPI_SPEED 1000000
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RESOLUTION 1024
#define UPDATE_INTERVAL 100000

int adc_read(int spi_fd, int cs) {
    uint8_t data[3];
    int ret;

    data[0] = 0x01; // Start bit + command for single-ended conversion
    data[1] = 0x00; // Channel 0
    data[2] = 0x00; // No additional commands

    ret = write(spi_fd, data, 3);
    if (ret != 3) {
        perror("Failed to write to SPI");
        return -1;
    }

    ret = read(spi_fd, data, 3);
    if (ret != 3) {
        perror("Failed to read from SPI");
        return -1;
    }

    // Ignore the first and last byte (start bit and dummy byte)
    uint16_t adc_value = (data[1] << 8) | data[2];

    return adc_value;
}

void pwm_set_duty(int pwm_gpio, int duty) {
    gpio_set_mode(pwm_gpio, PI_OUTPUT);
    gpio_set_PWMfunction(pwm_gpio, 0, PWM_FREQ);
    gpio_pwm_range(pwm_gpio, PWM_RESOLUTION);
    gpio_pwm_duty(pwm_gpio, duty);
}

void sigint_handler(int signum) {
    printf("Received SIGINT or SIGTERM, exiting...\n");
    gpioTerm(gpioHandle);
    exit(0);
}

int main() {
    int spi_fd, pwm_gpio;
    int adc_value, pwm_duty;
    struct spi_ioc_transfer spi_xfer[1];
    int ret;

    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        return 1;
    }

    gpioHandle = gpioOpen(0, GPIO_RDWR, 0, 0);
    if (!gpioHandle) {
        perror("Failed to open pigpio handle");
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    ret = gpioSetMode(ADC_SPI_CHIP_SELECT, PI_OUTPUT);
    if (ret < 0) {
        perror("Failed to set GPIO mode for SPI chip select");
        return 1;
    }

    spi_xfer[0].tx_buf = (unsigned char*) &ADC_SPI_MODE;
    spi_xfer[0].rx_buf = (unsigned char*) &ADC_SPI_MODE;
    spi_xfer[0].len = sizeof(ADC_SPI_MODE);
    spi_xfer[0].speed_hz = ADC_SPI_SPEED;

    ret = ioctl(spi_fd, SPI_IOC_WRITE_MODE32, &spi_xfer[0]);
    if (ret < 1) {
        perror("Failed to configure SPI mode");
        return 1;
    }

    ret = gpioSetMode(ADC_SPI_CHIP_SELECT, PI_OUTPUT);
    gpioWrite(ADC_SPI_CHIP_SELECT, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    pwm_gpio = gpioFindFree();
    if (pwm_gpio < 0) {
        perror("Failed to find free GPIO for PWM");
        return 1;
    }

    pwm_set_duty(pwm_gpio, 0);

    while (1) {
        usleep(UPDATE_INTERVAL);

        gpioWrite(ADC_SPI_CHIP_SELECT, 1);
        adc_value = adc_read(spi_fd, ADC_SPI_CHIP_SELECT);
        gpioWrite(ADC_SPI_CHIP_SELECT, 0);

        pwm_duty = adc_value * PWM_RESOLUTION / 1024;
        pwm_set_duty(pwm_gpio, pwm_duty);

        printf("ADC: %d, PWM duty: %d\n", adc_value, pwm_duty);
    }

    close(spi_fd);
    gpioTerm(gpioHandle);

    return 0;
}

