#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <adc1115.h>

#define ADC_ADDRESS 0x48
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0

double threshold;

void i2c_read_adc(int fd, uint8_t channel, uint16_t *result) {
    uint8_t buffer[2];

    if (write(fd, &channel, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    *result = (buffer[0] << 8) | buffer[1];
}

double convert_adc_to_gauss(uint16_t adc_value) {
    return (adc_value * 3.3) / 4096 * 0.001;
}

void blink_led(int gpio) {
    gpio_write(gpio, 1);
    usleep(50000);
    gpio_write(gpio, 0);
    usleep(50000);
}

void sigint_handler(int signum) {
    gpio_write(LED_GPIO, 0);
    gpioTerm(NULL);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int i2c_fd, adc_fd;
    uint16_t adc_value;
    double field_strength;

    if (argc > 2) {
        fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    if (argc == 2) {
        threshold = atof(argv[1]);
    } else {
        threshold = DEFAULT_THRESHOLD;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    gpio_set_mode(LED_GPIO, PI_OUTPUT);
    signal(SIGINT, sigint_handler);

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADC_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    if ((adc_fd = open("/dev/mem", O_RDWR | O_SYNC) ) < 0) {
        perror("Failed to open /dev/mem");
        exit(EXIT_FAILURE);
    }

    void *adc_reg = mmap(NULL, 2 * 1024 * 1024, PROT_READ | PROT_WRITE, MAP_SHARED, adc_fd, ADC1115_BASE);
    if (adc_reg == MAP_FAILED) {
        perror("Failed to map ADC1115 registers");
        exit(EXIT_FAILURE);
    }

    while (1) {
        i2c_read_adc(i2c_fd, 0, &adc_value);
        field_strength = convert_adc_to_gauss(adc_value);

        if (field_strength > threshold) {
            blink_led(LED_GPIO);
        }

        printf("Magnetic field strength: %.2f Gauss\n", field_strength);
        usleep(100000);
    }

    munmap(adc_reg, 2 * 1024 * 1024);
    close(adc_fd);
    i2c_close(i2c_fd);
    gpioTerm(NULL);

    return EXIT_SUCCESS;
}

