#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <syslog.h>
#include <pthread.h>
#include <pigpio.h>
#include <mraa.hpp>
#include <mqtt/async_client.h>

#define RPI_V2_GPIO_GPIO 8
#define RPI_V2_GPIO_PWM 17
#define ADC_CH 0
#define SPI_SPEED 1000000
#define SENSOR_MIN 30
#define SENSOR_MAX 35
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_QOS 1

mraa_aio_context* adc;
mqtt::async_client::sptr client;
pthread_t mqtt_thread;
bool pump_on = false;

void mqtt_callback(mqtt::const_message_ptr message) {
    if (strcasecmp(message->get_topic(), MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcasecmp(message->get_payload(), "pump_on") == 0) {
            pump_on = true;
        } else if (strcasecmp(message->get_payload(), "pump_off") == 0) {
            pump_on = false;
        }
    }
}

void mqtt_reconnect_callback(mqtt::async_client::sptr client) {
    client->connect(MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
    client->subscribe(MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
}

void mqtt_publish_moisture(int moisture) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", moisture);
    client->publish(MQTT_TOPIC_SOIL_MOISTURE, buf, MQTT_QOS);
}

void adc_read_callback(double value) {
    int moisture = (int)(value * 100);
    if (pump_on && moisture < SENSOR_MIN) {
        gpioWrite(RPI_V2_GPIO_PWM, 1);
    } else if (!pump_on && moisture > SENSOR_MAX) {
        gpioWrite(RPI_V2_GPIO_PWM, 0);
    }
    mqtt_publish_moisture(moisture);
}

int main(int argc, char* argv[]) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        return 1;
    }

    adc = new mraa_aio(ADC_CH);
    if (!adc) {
        syslog(LOG_ERR, "Failed to initialize ADC");
        return 1;
    }

    client = mqtt::async_client::create(MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
    client->set_callback(mqtt_callback);
    client->set_auto_reconnect(true);
    client->set_reconnect_callback(mqtt_reconnect_callback);

    if (gpioSetMode(RPI_V2_GPIO_PWM, PI_OUTPUT) < 0 ||
        gpioWrite(RPI_V2_GPIO_PWM, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize relay");
        return 1;
    }

    spi_init(SPI_SPEED);
    spi_chipselect(0, RPI_V2_GPIO_GPIO);

    mraa_aio_read(adc, adc_read_callback);

    pthread_create(&mqtt_thread, NULL, [client]() {
        client->connect(MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
        client->subscribe(MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
        client->loop_forever();
        return 0;
    }, NULL);

    sleep(60);

