#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_CS 8
#define SPI_CHIP_SELECT (1 << SPI_CS)
#define SPI_SPEED 1000000
#define MCP3008_CMD_CONFIG 0x00
#define MCP3008_CMD_SINGLE_ENDED_0 0x00
#define MCP3008_CMD_START 0x01

int main() {
    int spi_fd;
    struct spi_ioc_transfer transfers[1];
    char *spibuf;
    int ret;

    if ((spi_fd = open(SPI_DEV, O_RDWR)) < 0) {
        perror("Can't open spi device");
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Can't set spi mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &ret) < 0) {
        perror("Can't get max speed");
        close(spi_fd);
        return 1;
    }

    if (spi_fd > ret || SPI_SPEED > ret) {
        fprintf(stderr, "SPI speed too high\n");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) != 0) {
        perror("Can't set spi speed");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_GD_MODE, &SPI_MODE) != 0) {
        perror("Can't get spi mode");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) != 0) {
        perror("Can't set bits per word");
        close(spi_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &ret) != 0) {
        perror("Can't get bits per word");
        close(spi_fd);
        return 1;
    }

    if (ret != 8) {
        fprintf(stderr, "Wrong bits per word\n");
        close(spi_fd);
        return 1;
    }

    spibuf = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);
    if (spibuf == MAP_FAILED) {
        perror("Can't mmap");
        close(spi_fd);
        return 1;
    }

    transfers[0].tx_buf = (unsigned char*)&MCP3008_CMD_START;
    transfers[0].rx_buf = (unsigned char*)&spibuf;
    transfers[0].len = 1;
    transfers[0].speed_hz = SPI_SPEED;
    transfers[0].bits_per_word = 8;
    transfers[0].cs_change = SPI_CS;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers);
    if (ret < 1) {
        perror("Can't send command");
        munmap(spibuf, 4096);
        close(spi_fd);
        return 1;
    }

    unsigned int adc_value = (spibuf[1] << 8) | spibuf[2];
    double voltage = adc_value * 3.3 / 1024.0;
    printf("ADC raw value: %u, Voltage: %.3f V\n", adc_value, voltage);

    for (;;) {
        usleep(500000); // Sleep for 500 ms
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers);
        if (ret < 1) {
            perror("Can't send command");
            break;
        }

        adc_value = (spibuf[1] << 8) | spibuf[2];
        voltage = adc_value * 3.3 / 1024.0;
        printf("ADC raw value: %u, Voltage: %.3f V\n", adc_value, voltage);
    }

    munmap(spibuf, 4096);
    close(spi_fd);
    return 0;
}

