#define MCP3008_CS0 18
#define MCP3008_CS1 17
#define MCP3008_CS2 27
#define VREF 3.3
#define NUM_CHANNELS 3

static FILE *fp;

void sigint_handler(int signum) {
    printf("\nExiting gracefully...\n");
    gpioTerm();
    fclose(fp);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return 1;
    }

    if (gpioSetMode(MCP3008_CS0, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_CS1, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_CS2, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO modes");
        gpioTerm();
        return 1;
    }

    if (gpioSetPWMfrequency(MCP3008_CS0, 1000000) < 0 ||
        gpioSetPWMfrequency(MCP3008_CS1, 1000000) < 0 ||
        gpioSetPWMfrequency(MCP3008_CS2, 1000000) < 0) {
        perror("Failed to set PWM frequency");
        gpioTerm();
        return 1;
    }

    if ((fp = fopen("sensor_data.csv", "w")) == NULL) {
        perror("Failed to open sensor_data.csv for writing");
        gpioTerm();
        return 1;
    }

    fprintf(fp, "Time,Channel 0,Channel 1,Channel 2\n");

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);

        gpioWrite(MCP3008_CS0, 0);
        uint16_t adc_value0 = (uint16_t)gpioRead(gpioGetAddr(MCP3008_CS0, 0));
        gpioWrite(MCP3008_CS0, 1);

        gpioWrite(MCP3008_CS1, 0);
        uint16_t adc_value1 = (uint16_t)gpioRead(gpioGetAddr(MCP3008_CS1, 0));
        gpioWrite(MCP3008_CS1, 1);

        gpioWrite(MCP3008_CS2, 0);
        uint16_t adc_value2 = (uint16_t)gpioRead(gpioGetAddr(MCP3008_CS2, 0));
        gpioWrite(MCP3008_CS2, 1);

        double voltage0 = (adc_value0 * VREF) / 1024.0;
        double voltage1 = (adc_value1 * VREF) / 1024.0;
        double voltage2 = (adc_value2 * VREF) / 1024.0;

        fprintf(fp, "%lld,%.6f,%.6f,%.6f\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000, voltage0, voltage1, voltage2);

        usleep(5000000); // Sleep for 5 seconds
    }

    return 0;
}

