code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <spidev.h>
#include <time.h>
#include <signal.h>
#include <wiringPi.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 1023
#define SAMPLE_INTERVAL 10000
#define THRESHOLD 500
#define SPI_DEVICE_0 "/dev/spidev0.0"
#define BUFFER_SIZE 3

struct adc_data {
    int adc_value;
    time_t timestamp;
};

struct adc_data adc_data_buffer[BUFFER_SIZE];
int adc_buffer_head = 0;
int adc_buffer_tail = 0;

void adc_read_thread(void);
void motor_control(int adc_value);
void log_event(int adc_value);
void cleanup_spi(int spi_fd);
void cleanup_pigpio(void);

volatile sig_atomic_t running = 1;

int spi_fd;
struct spi_ioc_transfer spi_transfers[BUFFER_SIZE];

int main(void) {
    wiringPiSetup();
    gpioInitialise();

    if ((spi_fd = open(SPI_DEVICE_0, O_RDWR)) < 0) {
        perror("Cannot open SPI device");
        exit(EXIT_FAILURE);
    }

    pthread_t adc_read_thread_id;
    if (pthread_create(&adc_read_thread_id, NULL, adc_read_thread, NULL) != 0) {
        perror("Cannot create ADC read thread");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup_pigpio);
    signal(SIGTERM, cleanup_pigpio);

    while (running) {
        usleep(10000);
    }

    cleanup_spi(spi_fd);
    cleanup_pigpio();
    close(spi_fd);
    pthread_join(adc_read_thread_id, NULL);
    return 0;
}

void adc_read_thread(void *arg) {
    while (running) {
        struct spi_ioc_transfer transfer = {
            .tx_buf = (unsigned char *)&ADC_CHANNEL,
            .rx_buf = (unsigned char *)&adc_data_buffer[adc_buffer_head].adc_value,
            .len = 2,
            .delay_usecs = SAMPLE_INTERVAL,
            .bits_per_word = 8,
            .cs_change = SPI_CS_CHANGE_NONE,
        };

        if (xfer(spi_fd, &transfer, 1) < 0) {
            perror("ADC read error");
        } else {
            adc_data_buffer[adc_buffer_head].timestamp = time(NULL);
            adc_buffer_head = (adc_buffer_head + 1) % BUFFER_SIZE;
        }
    }
}

void motor_control(int adc_value) {
    if (adc_value > THRESHOLD) {
        int pwm_period_us = 10000;
        int pwm_duty_cycle = (adc_value - THRESHOLD) * (pwm_period_us * 100) / (ADC_RESOLUTION - THRESHOLD);

        gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
        gpioSetPWMfrequency(MOTOR1_GPIO, 100);
        gpioSetPWMrange(MOTOR1_GPIO, pwm_period_us);
        gpioSetPWMdutycycle(MOTOR1_GPIO, pwm_duty_cycle);

        gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);
        gpioSetPWMfrequency(MOTOR2_GPIO, 100);
        gpioSetPWMrange(MOTOR2_GPIO, pwm_period_us);
        gpioSetPWMdutycycle(MOTOR2_GPIO, pwm_duty_cycle);

        log_event(adc_value);
    } else {
        gpioWrite(MOTOR1_GPIO, LOW);
        gpioWrite(MOTOR2_GPIO, LOW);
    }
}

void log_event(int adc_value) {
    FILE *log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        perror("Cannot open log file");
        return;
    }

    char timestamp_str[20];
    ctime_r(&adc_data_buffer[adc_buffer_tail].timestamp, timestamp_str);
    timestamp_str[strlen(timestamp_str) - 1] = '\0';

    fprintf(log_file, "%s ADC: %d\n", timestamp_str, adc_value);
    fclose(log_file);
}

void cleanup_spi(int spi_fd) {
    close(spi_fd);
}

void cleanup_pigpio(void) {
    gpioTerm();
    gpioTerm();
}

