#include <spidev.h>

#define MOISTURE_THRESHOLD 30
#define RELAY_GPIO 17
#define ADC_CS 0
#define ADC_SPI_BUS 0
#define ADC_SPI_DEVICE 0
#define ADC_RESOLUTION 10
#define ADC_FREQ 1000000

static int spi_fd, gpio_fd;
static struct spi_ioc_transfer spi_transfers[4];

void setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for relay\n");
        exit(EXIT_FAILURE);
    }

    spi_fd = spiOpen(ADC_SPI_BUS, ADC_SPI_DEVICE, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }

    if (spi_xfer(spi_fd, spi_transfers, 4) < 0) {
        fprintf(stderr, "Failed to configure SPI\n");
        exit(EXIT_FAILURE);
    }

    if (spi_setBaudrate(spi_fd, ADC_FREQ) < 0) {
        fprintf(stderr, "Failed to set SPI frequency\n");
        exit(EXIT_FAILURE);
    }

    gpio_fd = pigpio_lib_init(NULL);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (gpioTerm(gpio_fd) < 0) {
        fprintf(stderr, "Failed to terminate pigpio library\n");
    }

    if (spiClose(spi_fd) < 0) {
        fprintf(stderr, "Failed to close SPI device\n");
    }

    gpioTerm(gpio_fd);
    exit(EXIT_SUCCESS);
}

int read_adc(int channel) {
    int adc_value = 0;

    spi_transfers[0].tx_buf = (unsigned char*)&channel;
    spi_transfers[0].len = sizeof(channel);
    spi_transfers[1].rx_buf = (unsigned char*)&adc_value;
    spi_transfers[1].len = sizeof(adc_value);

    if (spi_xfer(spi_fd, spi_transfers, 2) != 2) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    adc_value = (adc_value >> (8 - ADC_RESOLUTION)) * 3.3 * 100 / (1 << ADC_RESOLUTION);
    return adc_value;
}

void toggle_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

void log_and_check_moisture(int moisture) {
    time_t now = time(NULL);
    struct tm* tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    printf("%s: Moisture level: %d%%\n", timestamp, moisture);

    if (moisture < MOISTURE_THRESHOLD) {
        toggle_relay(1);
        printf("Turning on water pump due to low moisture level\n");
    } else {
        toggle_relay(0);
        printf("Turning off water pump due to sufficient moisture level\n");
    }
}

