    setup();

    int moisture;
    int retries = 3;

    while (1) {
        for (int i = 0; i < retries; ++i) {
            moisture = read_adc(ADC_CS);
            if (moisture >= 0) {
                break;
            }
        }

        if (moisture < 0) {
            fprintf(stderr, "Failed to read moisture level after %d retries\n", retries);
            cleanup();
            return EXIT_FAILURE;
        }

        log_and_check_moisture(moisture);
        sleep(60);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

