#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define ADC_CS 0
#define RELAY_GPIO 17
#define LOG_FILE "door_events.log"
#define SENSOR_THRESHOLD 20
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_DELAY_S 1

struct adc_data {
    uint16_t adc_value;
    struct timeval timestamp;
};

int adc_read(int spi_fd) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned char[]) { 0x00, 0x00, 0x00 },
        .rx_buf = (unsigned char[]) { 0 },
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = 1000000,
        .bits_per_word = 8,
    };

    if (spi_xfer(spi_fd, &transfer, 1) != 1) {
        perror("Failed to read ADC");
        return -1;
    }

    return transfer.rx_buf[0] | (transfer.rx_buf[1] << 8);
}

int main() {
    int adc_fd, gpio_fd, spi_fd, ret;
    struct gpiod_line *relay_line;
    struct adc_data last_data;
    struct timeval current_time;
    long last_event_time = 0;

    if ((adc_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Failed to open ADC device");
        exit(EXIT_FAILURE);
    }

    if ((spi_fd = gpiod_claim_index(0, "relay", GPIOD_CLAIM_FLAG_KEEP_STATE)) < 0) {
        perror("Failed to claim GPIO line for relay");
        exit(EXIT_FAILURE);
    }
    relay_line = gpiod_get_line_by_index(spi_fd, "relay");
    gpiod_line_request_line(relay_line, "relay", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH);

    while (1) {
        gettimeofday(&current_time, NULL);

        int adc_value = adc_read(adc_fd);
        float distance = 58.8 * pow(adc_value, -0.13);

        if (distance < SENSOR_THRESHOLD && (current_time.tv_sec - last_event_time) > DEBOUNCE_DELAY_S) {
            gpiod_line_set_value(relay_line, 1);
            last_event_time = current_time.tv_sec;
            fprintf(stderr, "Door opened at %ld.%06ld\n", (long)current_time.tv_sec, (long)current_time.tv_usec);
            fflush(stderr);
        }

        if (distance > SENSOR_THRESHOLD && gpiod_line_get_value(relay_line)) {
            gpiod_line_set_value(relay_line, 0);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_release(relay_line);
    gpiod_release(spi_fd);
    close(adc_fd);
    close(spi_fd);

    return 0;
}

