#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>
#include <spidev.h>

#define MCP3008_ADDR 0x48
#define CS_GPIO 8
#define SOIL_MOISTURE_CHANNELS 3
#define PWM_GPIO 17
#define PWM_FREQ 100
#define PWM_RES 1023
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

int spi_fd;
int pwm_handle;

void log_data(int *adc_values, int valve_position) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,", timestamp);

    for (int i = 0; i < SOIL_MOISTURE_CHANNELS; ++i) {
        fprintf(log_file, "%d,", adc_values[i]);
    }

    fprintf(log_file, "%d\n", valve_position);
    fclose(log_file);
}

int read_adc(int channel) {
    unsigned char command[3] = {0x40 | (channel & 0x07), 0x00, 0x00};
    unsigned char response[3];

    if (spiXfer(spi_fd, command, response, 3) != 3) {
        perror("Failed to read ADC");
        return -1;
    }

    int adc_value = (response[1] << 8) | response[2];
    return adc_value >> 6;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    if (spi_open(spi_fd, CS_GPIO, SPI_MODE_0, 1000000) < 0) {
        perror("Failed to open SPI channel");
        return 1;
    }

    int adc_values[SOIL_MOISTURE_CHANNELS] = {0};
    int total = 0;
    int valve_position = 0;

    signal(SIGINT, [](int signum) {
        close(spi_fd);
        gpioTerm();
        fclose(log_file);
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        close(spi_fd);
        gpioTerm();
        fclose(log_file);
        exit(0);
    });

    while (1) {
        for (int i = 0; i < SOIL_MOISTURE_CHANNELS; ++i) {
            int adc_value = read_adc(i);
            if (adc_value >= 0) {
                adc_values[i] = adc_value;
                total += adc_value;
            }
        }

        if (total > 0) {
            int average = total / SOIL_MOISTURE_CHANNELS;
            valve_position = PWM_RES - (average * PWM_RES / 1023);
            gpioPWM(PWM_GPIO, PWM_FREQ, valve_position);
            total = 0;
        }

        log_data(adc_values, valve_position);
        sleep(LOG_INTERVAL);
    }

    return 0;
