#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_TRIG 23
#define GPIO_ECHO 24
#define GPIO_PWM 18
#define SPI_DEVICE_ID_MCP3008 0
#define SPI_MODE 0
#define SPI_BAUD_RATE 1000000

struct gpiod_line_request *trig_req, *echo_req, *pwm_req;
struct spi_device *spidev;
int spi_fd;

void setup() {
    gpiod_line_request_configure(trig_req, GPIOD_IN, GPIOD_PULL_UP);
    gpiod_line_request_configure(echo_req, GPIOD_IN, GPIOD_PULL_UP);
    gpiod_line_request_configure(pwm_req, GPIOD_OUT_HIGH, GPIOD_PULL_NONE);

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Can't open spi device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Can't set spi mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_BAUD_RATE) != 0) {
        perror("Can't set spi speed");
        exit(EXIT_FAILURE);
    }
}

unsigned int read_adc() {
    char read_buf[3];
    unsigned int adc_value;

    if (write(spi_fd, &XFER_LEN, 1) != 1) {
        perror("Can't write to spi");
        exit(EXIT_FAILURE);
    }

    if (read(spi_fd, read_buf, XFER_LEN) != XFER_LEN) {
        perror("Can't read from spi");
        exit(EXIT_FAILURE);
    }

    adc_value = (read_buf[1] << 8) | read_buf[2];

    return adc_value;
}

unsigned int get_distance() {
    unsigned long long start, stop;
    unsigned int duration, distance;

    gpiod_line_set_value(trig_req, 0);
    usleep(10000);
    gpiod_line_set_value(trig_req, 1);

    start = get_time();
    while (!gpiod_line_get_value(echo_req)) {}
    stop = get_time();

    duration = (stop - start) * 1000000;
    distance = (duration / 2) / 29.1;

    return distance;
}

unsigned int map_distance_to_frequency(unsigned int distance) {
    return 220 + (distance * (880 - 220)) / 200;
}

void set_pwm_duty_cycle(unsigned int duty_cycle) {
    gpiod_line_set_value(pwm_req, duty_cycle);
}

void save_calibration() {
    FILE *file = fopen("theremin_config.txt", "w");

    if (file) {
        fprintf(file, "distance_threshold %d\n", distance_threshold);
        fprintf(file, "photoresistor_threshold %d\n", photoresistor_threshold);
        fclose(file);
    }
}

void load_calibration() {
    FILE *file = fopen("theremin_config.txt", "r");

    if (file) {
        char line[256];
        char token[64];
        int ret;

        while ((ret = fscanf(file, "%s %s", line, token)) != EOF) {
            if (strcmp(line, "distance_threshold") == 0) {
                sscanf(token, "%d", &distance_threshold);
            } else if (strcmp(line, "photoresistor_threshold") == 0) {
                sscanf(token, "%d", &photoresistor_threshold);
            }
        }

        fclose(file);
    }
}

void cleanup() {
    gpiod_line_release(trig_req);
    gpiod_line_release(echo_req);
    gpiod_line_release(pwm_req);
    close(spi_fd);
}

int main() {
    int distance, adc_value, frequency, photoresistor_value;
    double distance_threshold, photoresistor_threshold;

    load_calibration();

    trig_req = gpiod_chip_get_line_request(gpiod_chip_get_by_name("gpiochip0"), GPIO_TRIG);
    echo_req = gpiod_chip_get_line_request(gpiod_chip_get_by_name("gpiochip0"), GPIO_ECHO);
    pwm_req = gpiod_chip_get_line_request(gpiod_chip_get_by_name("gpiochip0"), GPIO_PWM);

    if (!trig_req || !echo_req || !pwm_req) {
        perror("Can't get gpio line requests");
        exit(EXIT_FAILURE);
    }

    setup();

    while (1) {
        distance = get_distance();

        if (distance > distance_threshold) {
            distance = distance_threshold;
        }

        frequency = map_distance_to_frequency(distance);
        adc_value = read_adc();

        if (adc_value > photoresistor_threshold) {
            photoresistor_value = photoresistor_threshold;
        } else {
            photoresistor_value = adc_value;
        }

        set_pwm_duty_cycle(frequency * photoresistor_value / 1024);

        printf("Distance: %d, Frequency: %d, Photoresistor: %d\n", distance, frequency, photoresistor_value);

        usleep(100000);
    }

    cleanup();
    return 0;
}

