#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define MQ_135_ADC_CHANNEL 0
#define FAN_GPIO 18
#define ADC_RESOLUTION 10
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define SPI_CS 0
#define SPI_DATA 1
#define SPI_CLK 2
#define SPI_MISO 3

static int g_spi_fd = -1;
static int g_fan_state = 0;

void log_timestamp_and_aqi(const char *message, int aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: AQI=%d\n", time_str, aqi);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: AQI=%d\n", time_str, aqi);
        fclose(log_file);
    }
}

int read_adc(int channel) {
    uint8_t data[3];
    int retries = 3;

    while (retries > 0) {
        if (spiWriteRead(g_spi_fd, 0x01, data, 3) != 3) {
            usleep(1000000);
            retries--;
            continue;
        }

        uint16_t adc_value = (data[1] << 8) | data[2];
        if (adc_value >= (1 << (ADC_RESOLUTION - 1)) && adc_value <= (1 << ADC_RESOLUTION) - 1)
            return adc_value;

        break;
    }

    if (retries == 0) {
        perror("Failed to read ADC");
        exit(EXIT_FAILURE);
    }

    return -1;
}

int main() {
    int ret;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    g_spi_fd = spiOpen(0, SPI_MODE, SPI_SPEED_HZ);
    if (g_spi_fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    gpioWrite(FAN_GPIO, g_fan_state);

    while (1) {
        int adc_value = read_adc(MQ_135_ADC_CHANNEL);
        if (adc_value == -1) {
            perror("Failed to read ADC");
            continue;
        }

        int aqi = (adc_value - 400) / 6.5;
        log_timestamp_and_aqi("", aqi);

        if (aqi > AQI_THRESHOLD) {
            if (!g_fan_state) {
                gpioWrite(FAN_GPIO, 1);
                g_fan_state = 1;
            }
        } else {
            if (g_fan_state) {
                gpioWrite(FAN_GPIO, 0);
                g_fan_state = 0;
            }
        }

        sleep(5);
    }

    gpioTerminate();
    close(g_spi_fd);

    return 0;
}

int sigint_handler(int signum) {
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
    close(g_spi_fd);
    fclose(fopen(LOG_FILE, "w"));
    exit(EXIT_SUCCESS);
}

int main_wrapper(int argc, char *argv[]) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    return main();
}

