#define MCP3008_CE0_GPIO 8
#define MCP3008_SCLK_GPIO 11
#define MCP3008_MOSI_GPIO 10
#define MCP3008_MISO_GPIO 9
#define PUMP_GPIO 18
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL 60
#define MOISTURE_THRESHOLD 300

int init_pigpio();
int init_spi();
int read_moisture();
void log_data(const char *status, int moisture);
void turn_on_pump();
void turn_off_pump();
void cleanup();

int main() {
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (init_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    int moisture;
    int fd_log = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd_log < 0) {
        perror("Failed to open log file");
        return 1;
    }

    time_t current_time;
    struct tm *time_info;
    while (1) {
        moisture = read_moisture();
        if (moisture <= MOISTURE_THRESHOLD) {
            turn_on_pump();
        } else {
            turn_off_pump();
        }
        log_data(moisture <= MOISTURE_THRESHOLD ? "Pump ON" : "Pump OFF", moisture);
        sleep(SAMPLE_INTERVAL);
    }

    close(fd_log);
    cleanup();
    return 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        return -1;
    }
    return 0;
}

int init_spi() {
    if (gpioSetMode(MCP3008_CE0_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_SCLK_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_MOSI_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(MCP3008_MISO_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        return -1;
    }

    spiOpen(0, SPI_MODE_0, 1000000);
    return 0;
}

int read_moisture() {
    gpioWrite(MCP3008_CE0_GPIO, 0);
    spiWrite(0, 0x40 | (0 << 3)); // Send command for single-ended, 10-bit conversion
    usleep(10);
    gpioWrite(MCP3008_CE0_GPIO, 1);

    unsigned int adc_value = spiRead(0);
    unsigned int moisture = (adc_value >> 2) & 0x3FF;
    return moisture;
}

void log_data(const char *status, int moisture) {
    time(&current_time);
    time_info = localtime(&current_time);
    char timestamp[25];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    char log_line[100];
    snprintf(log_line, sizeof(log_line), "%s %s: Moisture: %d\n", timestamp, status, moisture);
    write(fd_log, log_line, strlen(log_line));
}

void turn_on_pump() {
    gpioWrite(PUMP_GPIO, 1);
}

void turn_off_pump() {
    gpioWrite(PUMP_GPIO, 0);
}

void cleanup() {
    spiClose(0);
    gpioTerm();
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);
}

