#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define RASPBERRY_PI_VERSION 1
#define MIN_SPEED 50
#define MAX_SPEED 255
#define POT_RESOLUTION 1024
#define LOG_BASE 10
#define SPI_CH 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MOSI 10
#define MISO 9
#define SCLK 11
#define CE0 8
#define MOTOR1_EN 18
#define MOTOR1_DIR 23
#define MOTOR2_EN 24
#define MOTOR2_DIR 25

static volatile int running = 1;

double log_map(double x, double x_min, double x_max, double y_min, double y_max) {
    return y_min + (x - x_min) * log(x / x_max) / log(x_max / x_min) * (y_max - y_min);
}

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return 0;
}

int init_spi(int *fd) {
    struct spi_ioc_transfer transfers[2];

    *fd = open("/dev/spidev0.0", O_RDWR);
    if (*fd < 0) {
        perror("Can't open spi device");
        return -1;
    }

    memset(transfers, 0, sizeof(transfers));

    transfers[0].tx_buf = (unsigned char*)&(SPI_MODE);
    transfers[0].len = 4;
    transfers[0].speed_hz = SPI_SPEED;
    transfers[0].bits_per_word = 8;

    transfers[1].tx_buf = (unsigned char*)&(CE0);
    transfers[1].len = 1;
    transfers[1].speed_hz = SPI_SPEED;
    transfers[1].bits_per_word = 8;

    if (ioctl(*fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Can't set spi mode");
        return -1;
    }

    transfers[0].tx_buf = (unsigned char*)&(SPI_CH);
    if (ioctl(*fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Can't set spi channel");
        return -1;
    }

    transfers[1].tx_buf = (unsigned char*)&(MOSI);
    transfers[1].rx_buf = (unsigned char*)malloc(3);
    transfers[1].len = 3;
    if (ioctl(*fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Can't read chip id");
        return -1;
    }

    free(transfers[1].rx_buf);

    return 0;
}

int read_adc(int fd, int channel) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned char*)&(channel),
        .len = 1,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    struct spi_ioc_transfer response;
    response.rx_buf = malloc(3);
    response.len = 3;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1 ||
        ioctl(fd, SPI_IOC_MESSAGE(1), &response) < 1) {
        perror("Can't read adc");
        return -1;
    }

    unsigned int adc_value = (response.rx_buf[1] << 8) | response.rx_buf[0];
    free(response.rx_buf);

    return adc_value;
}

void control_motors(int speed_factor1, int speed_factor2) {
    gpioPWM(MOTOR1_EN, MIN_SPEED + speed_factor1 * (MAX_SPEED - MIN_SPEED));
    gpioPWM(MOTOR2_EN, MIN_SPEED + speed_factor2 * (MAX_SPEED - MIN_SPEED));

    gpioWrite(MOTOR1_DIR, 1);
    gpioWrite(MOTOR2_DIR, 0);

    usleep(2000000); // 2 seconds

    gpioWrite(MOTOR1_DIR, 0);
    gpioWrite(MOTOR2_DIR, 1);

    usleep(2000000); // 2 seconds

    gpioPWM(MOTOR1_EN, MIN_SPEED);
    gpioPWM(MOTOR2_EN, MIN_SPEED);

    usleep(5000000); // 5 seconds
}

int main() {
    int fd_spi;
    int pot1_value, pot2_value;
    double speed_factor1, speed_factor2;

    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_spi(&fd_spi) < 0) {
        return 1;
    }

    while (running) {
        pot1_value = read_adc(fd_spi, 0);
        pot2_value = read_adc(fd_spi, 1);

        speed_factor1 = log_map(pot1_value, 0, POT_RESOLUTION, MIN_SPEED, MAX_SPEED);
        speed_factor2 = log_map(pot2_value, 0, POT_RESOLUTION, MIN_SPEED, MAX_SPEED);

        control_motors(speed_factor1, speed_factor2);
    }

    close(fd_spi);
    gpioTerm();

    return 0;
}

