    usleep(2000000); // 2 seconds

    gpioWrite(MOTOR1_DIR, 0);
    gpioWrite(MOTOR2_DIR, 1);

    usleep(2000000); // 2 seconds

    gpioPWM(MOTOR1_EN, MIN_SPEED);
    gpioPWM(MOTOR2_EN, MIN_SPEED);

    usleep(5000000); // 5 seconds
}

int main() {
