    int pot1_value, pot2_value;
    double speed_factor1, speed_factor2;

    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_spi(&fd_spi) < 0) {
        return 1;
    }

    while (running) {
        pot1_value = read_adc(fd_spi, 0);
        pot2_value = read_adc(fd_spi, 1);

        speed_factor1 = log_map(pot1_value, 0, POT_RESOLUTION, MIN_SPEED, MAX_SPEED);
        speed_factor2 = log_map(pot2_value, 0, POT_RESOLUTION, MIN_SPEED, MAX_SPEED);

        control_motors(speed_factor1, speed_factor2);
    }

    close(fd_spi);
    gpioTerm();

    return 0;
}
