#include <spidev.h>

#define ADC_CS 1
#define ADC_MODE 0
#define ADC_SPI_BUS 0
#define ADC_SPI_DEVICE 0
#define ADC_RESOLUTION 10
#define SAMPLE_INTERVAL 100000
#define SLPM_MIN 0
#define SLPM_MAX 200

static char log_file[] = "airflow_log.txt";

void log_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, message);
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        log_timestamped_message("ERROR: pigpio initialization failed");
        return -1;
    }
    return 0;
}

int init_spi() {
    int spi_fd;
    struct spi_ioc_transfer spi_xfer[1];

    spi_fd = spi_open(ADC_SPI_BUS, ADC_SPI_DEVICE);
    if (spi_fd < 0) {
        log_timestamped_message("ERROR: SPI device open failed");
        return -1;
    }

    spi_xfer[0].tx_buf = &ADC_CS;
    spi_xfer[0].rx_buf = NULL;
    spi_xfer[0].len = 1;
    spi_xfer[0].speed_hz = 1000000;
    spi_xfer[0].bits_per_word = 8;

    if (spi_ioctl(spi_fd, SPI_IOC_MESSAGE(1), spi_xfer) < 1) {
        log_timestamped_message("ERROR: SPI CS setup failed");
        spi_close(spi_fd);
        return -1;
    }

    return spi_fd;
}

float read_adc_voltage(int spi_fd) {
    int16_t adc_value;
    struct spi_ioc_transfer spi_xfer[2];

    spi_xfer[0].tx_buf = &ADC_CS;
    spi_xfer[0].rx_buf = &adc_value;
    spi_xfer[0].len = 1;
    spi_xfer[0].speed_hz = 1000000;
    spi_xfer[0].bits_per_word = 16;

    spi_xfer[1].tx_buf = NULL;
    spi_xfer[1].rx_buf = NULL;
    spi_xfer[1].len = 0;
    spi_xfer[1].speed_hz = 1000000;
    spi_xfer[1].bits_per_word = 16;

    if (spi_ioctl(spi_fd, SPI_IOC_MESSAGE(2), spi_xfer) < 2) {
        log_timestamped_message("ERROR: ADC read failed");
        return -1.0f;
    }

    float voltage = (adc_value * 3.3f) / (1 << ADC_RESOLUTION);
    return voltage;
}

float calculate_airflow(float voltage) {
    if (voltage < 0.5f || voltage > 4.5f) {
        log_timestamped_message("ERROR: Invalid voltage value");
        return -1.0f;
    }

    float airflow = (voltage - 0.5f) / (4.5f - 0.5f) * SLPM_MAX;
    if (airflow < SLPM_MIN || airflow > SLPM_MAX) {
        log_timestamped_message("ERROR: Invalid airflow value");
        return -1.0f;
    }

    return airflow;
}

void log_airflow(float airflow) {
    FILE *log_file_ptr;
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[20];

    log_file_ptr = fopen(log_file, "a");
    if (log_file_ptr == NULL) {
        log_timestamped_message("ERROR: Log file open failed");
        return;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S ", timeinfo);
    fprintf(log_file_ptr, "%s%f\n", time_string, airflow);
    fclose(log_file_ptr);
}

int main() {
    int spi_fd, pigpio_fd;
    float voltage, airflow;
    int exit_status = 0;

    if (init_pigpio() < 0) {
        exit(EXIT_FAILURE);
    }

    spi_fd = init_spi();
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    while (1) {
        voltage = read_adc_voltage(spi_fd);
        if (voltage < 0.0f) {
            usleep(SAMPLE_INTERVAL);
            continue;
        }

        airflow = calculate_airflow(voltage);
        if (airflow < 0.0f) {
            usleep(SAMPLE_INTERVAL);
            continue;
        }

        log_airflow(airflow);
        usleep(SAMPLE_INTERVAL);
    }

    close(spi_fd);
    gpioTerminate();

    return exit_status;
}

