code:
#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_SPEED 1000000
#define GPIO_LINE "gpiochip0/gpio8"
#define ADMP401_CS_GPIO GPIO_LINE
#define MCP3008_CMD (0x01 << 8 | (0x08 << 4))
#define MCP3008_CS_LOW gpiod_line_request_direction_output(line, GPIOD_LINE_ACTIVE_LOW)
#define MCP3008_CS_HIGH gpiod_line_request_direction_input(line)

static int spi_fd;
static struct gpiod_line *line;
static FILE *log_file;

static void spi_open(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) != 0) {
        perror("Failed to set SPI bits per word");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) != 0) {
        perror("Failed to set SPI max speed");
        exit(EXIT_FAILURE);
    }
}

static void gpio_init(void) {
    line = gpiod_chip_get_line_byname(gpiod_chip_get_byname("gpiochip0"), ADMP401_CS_GPIO);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    MCP3008_CS_HIGH(line);

    gpiod_line_request_enable(line, "mic_cs");
}

static void log_init(void) {
    log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void spi_transfer(const uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfers[1] = {
        {
            .tx_buf = (unsigned long)tx_buf,
            .rx_buf = (unsigned long)rx_buf,
            .len = len,
            .delay_usecs = 0,
            .speed_hz = SPI_SPEED,
        }
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 0) {
        perror("Failed to perform SPI transfer");
        exit(EXIT_FAILURE);
    }
}

static void sample_and_log(void) {
    uint8_t tx_buf[3] = {MCP3008_CMD, 0, 0};
    uint8_t rx_buf[3];

    MCP3008_CS_LOW(line);
    spi_transfer(tx_buf, rx_buf, sizeof(tx_buf));
    MCP3008_CS_HIGH(line);

    uint16_t raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    uint64_t timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;

    fprintf(log_file, "%llu|%u\n", timestamp_ns, raw_adc_value);
    fflush(log_file);
}

static void signal_handler(int sig) {
    gpiod_line_release(line);
    close(spi_fd);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_open();
    gpio_init();
    log_init();

    const uint32_t period_ns = 1000000;
    struct timespec next_sample = {0, period_ns};

    while (1) {
        nanosleep(&next_sample, NULL);
        sample_and_log();
    }

    gpiod_line_release(line);
    close(spi_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

