        exit(EXIT_FAILURE);
    }
}

static void sample_and_log(void) {
    uint8_t tx_buf[3] = {MCP3008_CMD, 0, 0};
    uint8_t rx_buf[3];

    MCP3008_CS_LOW(line);
    spi_transfer(tx_buf, rx_buf, sizeof(tx_buf));
    MCP3008_CS_HIGH(line);

    uint16_t raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    uint64_t timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;

    fprintf(log_file, "%llu|%u\n", timestamp_ns, raw_adc_value);
    fflush(log_file);
}

static void signal_handler(int sig) {
    gpiod_line_release(line);
    close(spi_fd);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_open();
    gpio_init();
    log_init();

    const uint32_t period_ns = 1000000;
    struct timespec next_sample = {0, period_ns};

    while (1) {
        nanosleep(&next_sample, NULL);
        sample_and_log();
    }

    gpiod_line_release(line);
    close(spi_fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}
```

This code initializes the SPI device, requests the GPIO line, opens the log file, and samples the audio at 1000 Hz with a 1 ms period. It handles errors from opening the SPI device, GPIO line request, log file, and signals (SIGINT, SIGTERM) for graceful shutdown. The code also releases the GPIO line request, closes the SPI fd, and closes the log file on all exit paths.

