#include <pigpio.h>
#include <adxl335.h>
#include <mcp3008.h>

#define ADXL335_ADDR 0x53
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define SAMPLE_RATE 10
#define SCALE_FACTOR 300.0 / 3.3

adxl335_t adxl335;
mcp3008_t mcp3008;

void sigint_handler(int signum) {
    gpioTerm();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (adxl335_init(&adxl335, ADXL335_ADDR) < 0) {
        fprintf(stderr, "Failed to initialize ADXL335\n");
        gpioTerm();
        return 1;
    }

    if (mcp3008_init(&mcp3008, CS_PIN, MOSI_PIN, MISO_PIN, SCLK_PIN) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        adxl335_deinit(&adxl335);
        gpioTerm();
        return 1;
    }

    double x, y, z;
    double last_time = 0.0;

    while (1) {
        double current_time = gpioCycleCount() * (1.0 / gpioCycleTime());
        double elapsed_time = current_time - last_time;
        last_time = current_time;

        if (elapsed_time > 1.0 / SAMPLE_RATE) {
            int adc_values[3];

            if (mcp3008_read_adc_values(&mcp3008, adc_values) < 0) {
                fprintf(stderr, "Failed to read ADC values\n");
                continue;
            }

            x = (adc_values[0] * SCALE_FACTOR) - 1.5;
            y = (adc_values[1] * SCALE_FACTOR) - 1.5;
            z = (adc_values[2] * SCALE_FACTOR) - 1.5;

            // Apply Kalman filter here

            printf("Acceleration (g): X: %.3f, Y: %.3f, Z: %.3f\n", x, y, z);
        }

        usleep(1e6 / SAMPLE_RATE);
    }

    adxl335_deinit(&adxl335);
    mcp3008_deinit(&mcp3008);
    gpioTerm();

    return 0;
}

