#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>
#include <errno.h>
#include <string.h>

#define V_QUiescent 1.65
#define SENSITIVITY 0.025
#define SAMPLE_INTERVAL 100000
#define LOG_FILE "magnetic_log.txt"

static gpiod_line_handle_t *lines[3];
static FILE *log_file;

void gpiod_line_request_error_handler(struct gpiod_chip *chip, struct gpiod_line *line, int error, void *user_data) {
    fprintf(stderr, "Error requesting GPIO line %d: %s\n", line->number, strerror(error));
}

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
}

void log_magnetic_field(double sensor1, double sensor2, double sensor3) {
    if (log_file) {
        fprintf(log_file, "%f,%f,%f\n", sensor1, sensor2, sensor3);
        fflush(log_file);
    }
}

double read_sensor(gpiod_line_handle_t *line) {
    uint32_t value;
    int ret;

    ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        log_error("Error reading GPIO line");
        return NAN;
    }

    return (value == 1) ? 3.3 : 0.0;
}

double calculate_magnetic_field(double voltage) {
    double magnetic_field = (voltage - V_QUiescent) / SENSITIVITY;

    if (magnetic_field < -100 || magnetic_field > 100) {
        log_error("Magnetic field value out of range");
    }

    return magnetic_field;
}

int main() {
    int i;
    struct gpiod_chip *chip;
    struct gpiod_line_request request[3];

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        log_error("Error opening GPIO chip");
        return 1;
    }

    for (i = 0; i < 3; ++i) {
        request[i].consumer = "Hall-Effect sensor";
        request[i].line = i;
        request[i].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        request[i].request_err_cb = gpiod_line_request_error_handler;

        lines[i] = gpiod_chip_request_line(chip, &request[i], NULL);
        if (!lines[i]) {
            log_error("Error requesting GPIO line");
            goto cleanup;
        }
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Error opening log file");
        goto cleanup;
    }

    while (1) {
        double sensor_values[3];

        for (i = 0; i < 3; ++i) {
            sensor_values[i] = read_sensor(lines[i]);
            if (isnan(sensor_values[i])) {
                continue;
            }

            sensor_values[i] = calculate_magnetic_field(sensor_values[i]);
        }

        log_magnetic_field(sensor_values[0], sensor_values[1], sensor_values[2]);
        usleep(SAMPLE_INTERVAL);
    }

cleanup:
    for (i = 0; i < 3; ++i) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    if (log_file) {
        fclose(log_file);
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

