#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define ADC_CH 0
#define RELAY_PIN 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, event);
    fprintf(stderr, "\n");

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_string, event);
        fclose(log_file);
    }
}

int adc_read(void) {
    int adc_value;
    if (gpioRead(ADC_CH + 16) == 0) {
        if (gpioSPIWriteRead(ADC_CH, 0x00, 0x00, &adc_value, 3) < 0) {
            log_event("ADC read error");
            return -1;
        }
    } else {
        log_event("ADC channel not idle");
        return -1;
    }
    return adc_value;
}

void relay_toggle(int state) {
    if (state)
        gpioWrite(RELAY_PIN, 1);
    else
        gpioWrite(RELAY_PIN, 0);
}

void signal_handler(int signum) {
    log_event("Received signal");
    relay_toggle(0);
    gpioTerm();
    exit(0);
}

int main(void) {
    int adc_value;
    int moisture_level;

    if (gpioInitialise() < 0) {
        log_event("Failed to initialise pigpio");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set relay pin mode");
        goto cleanup;
    }

    relay_toggle(0);

    log_event("Program started");

    while (1) {
        adc_value = adc_read();
        if (adc_value >= 0) {
            moisture_level = (1023 - adc_value) * 100 / 1023;
            log_event(moisture_level < MOISTURE_THRESHOLD ? "Moisture level is low, turning on the pump" : "Moisture level is high, turning off the pump");
            relay_toggle(moisture_level < MOISTURE_THRESHOLD);
        } else {
            log_event("ADC read error");
        }
        sleep(60);
    }

cleanup:
    gpioTerm();
    return 0;
}

