    exit(0);
}

int main(void) {
    int adc_value;
    int moisture_level;

    if (gpioInitialise() < 0) {
        log_event("Failed to initialise pigpio");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set relay pin mode");
        goto cleanup;
    }

    relay_toggle(0);

    log_event("Program started");

    while (1) {
        adc_value = adc_read();
        if (adc_value >= 0) {
            moisture_level = (1023 - adc_value) * 100 / 1023;
            log_event(moisture_level < MOISTURE_THRESHOLD ? "Moisture level is low, turning on the pump" : "Moisture level is high, turning off the pump");
            relay_toggle(moisture_level < MOISTURE_THRESHOLD);
        } else {
            log_event("ADC read error");
        }
        sleep(60);
    }

cleanup:
    gpioTerm();
    return 0;
}
```

This code assumes that the MCP3008 ADC is connected to the Raspberry Pi's SPI0 pins (SCLK, MOSI, MISO, CE0), and the 12V water pump relay is connected to GPIO17. Make sure to install the pigpio library before compiling the code:

```sh
sudo apt-get update
sudo apt-get install pigpio
```

Compile the code with:

```sh
gcc -o soil_moisture soil_moisture.c -lwiringPi -lpthread -lrt -lrt -lpigpio
```

Run the compiled program with:

```sh
./soil_moisture
```

The program will run indefinitely, checking the soil moisture level every 60 seconds and logging events to 'watering.log'. If the moisture level falls below 30%, it will turn on the water pump relay, and if the moisture rises to 30% or above, it will turn off the pump. The program will also handle clean shutdown with signal handlers for SIGINT and SIGTERM.

