#define SPI_BITS 8
#define SPI_SPEED 1000000
#define CS_GPIO 18
#define CHANNELS 3

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *consumer,
                                unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, consumer, flags);
}

int main() {
    int spi_fd, ret;
    struct spi_ioc_transfer transfers[CHANNELS];
    char buffer[2];
    FILE *csv_file;
    char csv_filename[] = "sensor_data.csv";
    struct gpiod_chip *chip;
    struct gpiod_line_request line_req;
    struct timespec delay;

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Can't open SPI device");
        exit(EXIT_FAILURE);
    }

    // Configure SPI bus settings
    struct spi_ioc_transfer setup_transfer = {
        .tx_buf = (unsigned long *)&buffer,
        .rx_buf = NULL,
        .len = 2,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &setup_transfer) < 1) {
        perror("Can't set SPI settings");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line for CS
    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("Can't open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_array(&line_req, 1, &chip->lines[CS_GPIO],
                                 "SPI_CS") < 0) {
        perror("Can't request GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable(line_req.lines, 1) < 0) {
        perror("Can't enable GPIO line");
        gpiod_line_release_request(&line_req);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize CSV file
    if ((csv_file = fopen(csv_filename, "w")) == NULL) {
        perror("Can't open CSV file");
        gpiod_line_release_request(&line_req);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

