        fflush(csv_file);
        gpiod_line_release_request(&line_req);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_SUCCESS);
    });

    // Set up SPI transfers for each channel
    for (int i = 0; i < CHANNELS; ++i) {
        transfers[i].tx_buf = (unsigned long *)&buffer;
        transfers[i].rx_buf = (unsigned long *)&buffer;
        transfers[i].len = 3;
        transfers[i].delay_usecs = 0;

        buffer[0] = 0x01;
        buffer[1] = (0x80 | (i << 4));
        buffer[2] = 0x00;
    }

