        ret = write(spi_fd, transfers, CHANNELS * sizeof(struct spi_ioc_transfer));
        if (ret < 0) {
            perror("Can't write to SPI device");
            goto cleanup;
        }

        // Read data from MCP3008
        ret = read(spi_fd, transfers, CHANNELS * sizeof(struct spi_ioc_transfer));
        if (ret < 0) {
            perror("Can't read from SPI device");
            goto cleanup;
        }

        // Extract ADC values
        unsigned int adc_values[CHANNELS];
        for (int i = 0; i < CHANNELS; ++i) {
            adc_values[i] = ((transfers[i].rx_buf[1] & 0x03) << 8) | transfers[i].rx_buf[2];
        }

        // Convert ADC values to moisture levels (for example, 1023 -> 0% to 0 -> 100%)
        float moisture_levels[CHANNELS];
        for (int i = 0; i < CHANNELS; ++i) {
            moisture_levels[i] = (100.0f - (adc_values[i] * 100.0f / 1023.0f));
        }

        // Log data to CSV file
        char time_str[20];
        ctime(&time_str[0]);
        time_str[19] = '\0';
        fprintf(csv_file, "%s", time_str);
        for (int i = 0; i < CHANNELS; ++i) {
            fprintf(csv_file, ",%f", moisture_levels[i]);
        }
        fprintf(csv_file, "\n");

        // Delay between readings
        nanosleep(&delay, NULL);
    }

cleanup:
    fclose(csv_file);
    gpiod_line_release_request(&line_req);
    gpiod_chip_close(chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

