#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <cjson/cJSON.h>
#include <pigpio.h>
#include <mosquitto.h>

#define GPIO_LED 17
#define CLIENT_ID "rpi_led_control"
#define BROKER "mqtt.eclipseprojects.io"
#define PORT 1883

static int g_reconnect_delay = 1000;
static mosquitto_t *g_mosq;
static pigpio_t *g_pi;
static bool g_led_state = false;

static void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        mosquitto_subscribe(mosq, NULL, "home/led_control", 0);
    } else {
        fprintf(stderr, "Failed to connect: %s\n", mosquitto_strerror(result));
        sleep(g_reconnect_delay);
        g_reconnect_delay *= 2;
        if (g_reconnect_delay > 60000) {
            g_reconnect_delay = 60000;
        }
        mosquitto_reconnect(mosq);
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    time_t now = time(NULL);
    const char *timestamp = ctime(&now);
    cJSON *root = cJSON_Parse(msg->payload);

    if (!root || !cJSON_IsObject(root)) {
        fprintf(stderr, "Invalid JSON payload: %s\n", msg->payload);
        cJSON_Delete(root);
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(root, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        fprintf(stderr, "Invalid 'led_state' field or invalid type: %s\n", msg->payload);
        cJSON_Delete(root);
        return;
    }

    g_led_state = led_state->valueint;
    gpioWrite(GPIO_LED, g_led_state);
    cJSON_Delete(root);
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int reason) {
    fprintf(stderr, "Disconnected: %s\n", mosquitto_strerror(reason));
    g_reconnect_delay = 1000;
    mosquitto_reconnect(mosq);
}

static void signal_handler(int sig) {
    fprintf(stderr, "Received signal %d, exiting...\n", sig);

    mosquitto_disconnect(g_mosq, 0);
    gpioWrite(GPIO_LED, !g_led_state);
    gpioTerminate(g_pi);
    exit(0);
}

int main() {
    struct sigaction sa;
    time_t start_time;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    g_pi = pigpio_get_state();
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, !g_led_state);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    start_time = time(NULL);
    mosquitto_lib_init(NULL);

    g_mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!g_mosq) {
        perror("mosquitto_new");
        return 1;
    }

    mosquitto_set_log_function(g_mosq, log_callback);
    mosquitto_set_callback(g_mosq, on_connect);
    mosquitto_set_callback(g_mosq, on_message);
    mosquitto_set_callback(g_mosq, on_disconnect);

    if (mosquitto_connect(g_mosq, BROKER, PORT, 60) != MOSQ_ERR_SUCCESS) {
        perror("mosquitto_connect");
        return 1;
    }

    mosquitto_loop_start(g_mosq);

    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) > 60) {
            break;
        }
        usleep(100000);
    }

    mosquitto_loop_stop(g_mosq, true);
    mosquitto_destroy(g_mosq);
    mosquitto_lib_cleanup();

    gpioTerminate(g_pi);
    return 0;
}

void log_callback(struct mosquitto *mosq, int level, const char *str) {
    fprintf(stderr, "[%s] %s\n", mosquitto_log_type_str(level), str);
}

