    .lines = (struct gpiod_line_request_data){
        [SOUND_SENSOR_GPIO] = { .direction = GPIOD_IN, },
        [ALARM_LED_GPIO] = { .direction = GPIOD_OUT_IN, .value = 1, },
    },
    .num_lines = 2,
};

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *sound_sensor, *alarm_led;
    unsigned int sound_level;
    unsigned long long last_poll_time = 0;
    unsigned long long current_time;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    ret = gpiod_line_request_lines(chip, &lines_data, GPIOD_LINE_REQUEST_DIRECTIONS);
    if (ret < 0) {
        perror("Failed to request GPIO lines");
        goto cleanup_chip;
    }

    sound_sensor = gpiod_get_line(chip, SOUND_SENSOR_GPIO);
    alarm_led = gpiod_get_line(chip, ALARM_LED_GPIO);

    while (1) {
        current_time = gpiod_get_ns_time();
        if (current_time - last_poll_time >= POLL_INTERVAL_MS * 1000000) {
            last_poll_time = current_time;

            sound_level = gpiod_line_get_value(sound_sensor);
            printf("Sound level: %u\n", sound_level);

            if (!sound_level) {
                gpiod_line_set_value(alarm_led, !gpiod_line_get_value(alarm_led));
                usleep(LED_ON_MS * 1000);
                gpiod_line_set_value(alarm_led, 0);
            }
        }

        usleep(10000);
    }

cleanup_chip:
    gpiod_line_release(sound_sensor);
    gpiod_line_release(alarm_led);
    gpiod_chip_release(chip);

    return 0;
}
