#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUMBER 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

volatile sig_atomic_t shutdown_requested = 0;

void signal_handler(int sig) {
    shutdown_requested = 1;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    if ((ret = gpiod_chip_open_byname(GPIO_CHIP_NAME, &chip)) < 0) {
        perror("gpiod_chip_open_byname");
        goto cleanup;
    }

    // Get the GPIO line
    if ((ret = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER, &line)) < 0) {
        perror("gpiod_chip_get_line");
        goto cleanup_chip;
    }

    // Request the line for falling-edge event detection
    if ((ret = gpiod_line_request_consumer(line, "vibration-monitor", GPIOD_LINE_REQUEST_DIRECTION_IN)) < 0) {
        perror("gpiod_line_request_consumer");
        goto cleanup_line;
    }

    // Configure the line for single-line event API
    if ((ret = gpiod_line_set_debounce(line, 10)) < 0) {
        perror("gpiod_line_set_debounce");
        goto cleanup_line_request;
    }

    // Main event loop
    while (!shutdown_requested) {
        struct timespec ts;
        struct gpiod_line_event event;

        // Wait for a falling edge event
        if ((ret = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_FALLING, &ts)) < 0) {
            perror("gpiod_line_event_wait");
            continue;
        }

        // Read the event
        if ((ret = gpiod_line_event_read(line, &event)) < 0) {
            perror("gpiod_line_event_read");
            continue;
        }

        // Log and print the event
        time_t rawtime;
        struct tm *timeinfo;
        char time_str[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("fopen");
            continue;
        }

        fprintf(log_file, "%s: Vibration detected\n", time_str);
        fclose(log_file);

        printf("%s: Vibration detected\n", time_str);

        // Shutdown the system
        system("sudo shutdown -h now");
    }

    // Cleanup: release the line and close the chip
    cleanup_line_request:
        gpiod_line_release(line);
    cleanup_line:
        gpiod_line_put(line);
    cleanup_chip:
        gpiod_chip_close(chip);
    cleanup:
        return EXIT_SUCCESS;
}

