#define BMP280_ADDR 0x76
#define SDA_PIN 3
#define SCL_PIN 5
#define I2C_BUS 1

#define BMP280_ID_REG 0xD0
#define BMP280_CAL_REG 0x88
#define BMP280_CTRL_MEAS 0xF4
#define BMP280_RAW_PRESS_REG 0xF7
#define BMP280_RAW_TEMP_REG 0xFA
#define BMP280_AC1 0x88
#define BMP280_AC2 0x8A
#define BMP280_AC3 0x8C
#define BMP280_AC4 0x8E
#define BMP280_AC5 0x90
#define BMP280_AC6 0x92
#define BMP280_B5 0xE1
#define BMP280_B6 0xE3
#define BMP280_B1 0xEE
#define BMP280_B2 0xEF
#define BMP280_MB 0x01
#define BMP280_MC 0x02
#define BMP280_MD 0x03

static const char *log_file = "altitude_log.txt";

void bmp280_init(void);
uint16_t bmp280_read_word(uint8_t reg);
int32_t bmp280_compensate_pressure(uint16_t raw_press);
int32_t bmp280_compensate_temperature(uint16_t raw_temp);
float bmp280_compute_altitude(int32_t compensated_press, int32_t sea_level_press);
void log_altitude(time_t timestamp, int32_t compensated_press, float compensated_temp, float altitude);

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    bmp280_init();

    if (gpioPeripheralSetup(I2C_BUS, SDA_PIN, SCL_PIN, PI_PHYSICAL) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        return 1;
    }

    if (bmp280_read_byte(BMP280_ID_REG) != 0x58) {
        fprintf(stderr, "BMP280 chip ID mismatch\n");
        return 1;
    }

    // Read and apply calibration
    uint16_t cal_data[16];
    for (size_t i = 0; i < 16; ++i) {
        cal_data[i] = bmp280_read_word(BMP280_AC1 + i);
    }

    // Configure sensor
    bmp280_write_byte(BMP280_CTRL_MEAS, 0x24); // Oversampling x1, normal mode

    time_t last_log_time = time(NULL);
    while (1) {
        time_t current_time = time(NULL);
        if (difftime(current_time, last_log_time) > 5) {
            last_log_time = current_time;

            uint16_t raw_press = bmp280_read_word(BMP280_RAW_PRESS_REG);
            int32_t compensated_press = bmp280_compensate_pressure(raw_press);

            uint16_t raw_temp = bmp280_read_word(BMP280_RAW_TEMP_REG);
            int32_t compensated_temp = bmp280_compensate_temperature(raw_temp);

            float altitude = bmp280_compute_altitude(compensated_press, 101325);

            log_altitude(current_time, compensated_press, compensated_temp, altitude);
        }

        usleep(500000); // Sleep for 500ms
    }

    gpioTerminate();
    return 0;
}

void bmp280_init(void) {
    // Soft reset
    bmp280_write_byte(BMP280_CTRL_MEAS, 0xB6);
    usleep(10000);
    bmp280_write_byte(BMP280_CTRL_MEAS, 0x2E);
}

uint16_t bmp280_read_word(uint8_t reg) {
    uint16_t data;
    gpioI2cReadReg16(I2C_BUS, BMP280_ADDR, reg, &data);
    return data;
}

int32_t bmp280_compensate_pressure(uint16_t raw_press) {
    int32_t var1, var2, p;

    var1 = ((((int64_t)raw_press) << 12) / 4096) - ((int64_t)cal_data[BMP280_AC6] * 6 + ((int64_t)cal_data[BMP280_AC5] * ((int64_t)raw_press) >> 16));
    var2 = ((var1 * (int64_t)cal_data[BMP280_B6]) >> 10) * ((int64_t)cal_data[BMP280_B1] * ((var1 * (int64_t)cal_data[BMP280_B2]) >> 11)) / 4096;
    p = (1 << 23) / (1 + ((var1 + var2) / 4096));

    return p;
}

int32_t bmp280_compensate_temperature(uint16_t raw_temp) {
    int32_t var1, var2, t;

    var1 = (((int64_t)raw_temp) << 14) / 32768;
    var2 = var1 - ((int64_t)cal_data[BMP280_AC2] * var1 * var1) / 512 + ((int64_t)cal_data[BMP280_AC1] * var1) / 2;
    t = (var1 + var2) / 16;

    return t;
}

float bmp280_compute_altitude(int32_t compensated_press, int32_t sea_level_press) {
    float sea_level_altitude = 44330; // Sea level altitude in meters
    float T = bmp280_compensate_temperature(compensated_press) / 100.0;
    float P = compensated_press / 100.0;
    float P_SL = sea_level_press / 100.0;
    float T_SL = sea_level_altitude / 44330;
    float P_a = P / P_SL - 1;
    float T_a = T / T_SL - 1;
    float altitude = 44330 * (1 - pow((P_a / (1 + T_a)), 5.255));

    return altitude;
}

void log_altitude(time_t timestamp, int32_t compensated_press, int32_t compensated_temp, float altitude) {
    FILE *log_file_ptr = fopen(log_file, "a");
    if (!log_file_ptr) {
        perror("Failed to open log file");
        return;
    }

    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.000Z", localtime(&timestamp));
    fprintf(log_file_ptr, "%s,%d,%d,%f\n", timestamp_str, compensated_press, compensated_temp, altitude);
    fflush(log_file_ptr);

    fclose(log_file_ptr);
}

int bmp280_write_byte(uint8_t reg, uint8_t value) {
    return gpioI2cWrite(I2C_BUS, BMP280_ADDR, &reg, 1, &value, 1);
}

