#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <signal.h>
#include <pigpio.h>

#define MCP3008_SPI_CE0_GPIO 8
#define MCP3008_SPI_CH0_REG 0x00
#define VREF 3.3
#define LM35_SLOPE 0.01

#define BUFFER_SIZE 120
float buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void sigterm_handler(int signum) {
    running = 0;
}

float read_temperature() {
    uint16_t rx[3];
    int status = pigpio_spi_xfer(gpioNum(MCP3008_SPI_CE0_GPIO), MCP3008_SPI_CH0_REG, rx, 3);

    if (status < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return NAN;
    }

    float temperature = ((rx[1] & 0x03) << 8) | rx[2];
    temperature *= VREF / 1024.0;
    temperature *= LM35_SLOPE;
    return temperature;
}

void log_to_file(float temperature) {
    int fd = open("temp_log.dat", O_WRONLY | O_CREAT | O_APPEND | O_SYNC, S_IRUSR | S_IWUSR);

    if (fd < 0) {
        fprintf(stderr, "Error opening temp_log.dat: %s\n", strerror(errno));
        return;
    }

    if (write(fd, &temperature, sizeof(temperature)) != sizeof(temperature)) {
        fprintf(stderr, "Error writing to temp_log.dat: %s\n", strerror(errno));
    }

    if (lseek(fd, -sizeof(float), SEEK_CUR) != -1) {
        if (fsync(fd) < 0) {
            fprintf(stderr, "Error fsyncing temp_log.dat: %s\n", strerror(errno));
        }
    }

    close(fd);
}

int main() {
    int status;

    if ((status = pigpio_init()) < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(MCP3008_SPI_CE0_GPIO, PI_OUTPUT);
    gpioWrite(MCP3008_SPI_CE0_GPIO, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        float temperature = read_temperature();

        if (!isnan(temperature)) {
            buffer[buffer_head] = temperature;
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;

            if (buffer_head == buffer_tail) {
                log_to_file(temperature);
                buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
            }

            printf("Temperature: %.2f °C\n", temperature);
        }

        usleep(500000); // Sleep for 500 ms (0.5 seconds)
    }

    gpioTerm();
    pigpio_terminate();

    return 0;
}
```

This code assumes that you have the pigpio library installed on your Raspberry Pi. To install it, run the following command:

```sh
sudo apt-get install pigpio
```

Make sure to connect the LM35 temperature sensor and MCP3008 ADC according to the wiring instructions for SPI0 (CE0, GPIO 8-11).

Compile the code with:

```sh
gcc -o temp_reader temp_reader.c -lpigpio -lrt
```

Run the compiled program with:

```sh
./temp_reader
```

You can stop the program by pressing Ctrl+C or sending a SIGTERM signal. The program will cleanly close the SPI and pigpio resources and exit. The temperature readings will be logged to the console and the file 'temp_log.dat'.

