#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDR_BH1750 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define MAX_SPI_DATA 3
#define MCP3008_CH0 0

struct i2c_data {
    int file;
    char *dev_name;
};

struct spi_data {
    int file;
    void *spi;
};

struct sensor_data {
    struct i2c_data bh1750;
    struct spi_data mcp3008;
};

void log_error(const char *msg) {
    perror(msg);
    fprintf(stderr, "Error: %s\n", strerror(errno));
}

void i2c_init(struct i2c_data *data, const char *dev_name) {
    data->file = open(dev_name, O_RDWR);
    if (data->file < 0) {
        log_error("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(data->file, I2C_SLAVE, I2C_ADDR_BH1750) < 0) {
        log_error("Failed to acquire I2C address");
        exit(EXIT_FAILURE);
    }
}

void spi_init(struct spi_data *data) {
    struct spi_open_desc desc = {0};

    data->file = open(SPI_DEVICE, O_RDWR);
    if (data->file < 0) {
        log_error("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    desc.bits_per_word = 8;
    desc.max_speed_hz = 1000000;
    if (ioctl(data->file, SPI_IOC_WRITE_MODE32, &desc) < 0) {
        log_error("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    data->spi = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, data->file, 0);
    if (data->spi == MAP_FAILED) {
        log_error("Failed to mmap SPI device");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_bh1750(struct i2c_data *data, uint16_t *lux) {
    uint8_t buf[2];

    if (write(data->file, 0x23, 1) != 1) {
        log_error("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(data->file, buf, 2) != 2) {
        log_error("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    *lux = (buf[0] << 8) | buf[1];
}

uint16_t spi_read_mcp3008(struct spi_data *data, uint8_t channel) {
    uint16_t result;
    uint8_t buf[MAX_SPI_DATA];

    buf[0] = 0x00 | (channel << 6);
    if (write(data->file, &buf, 1) != 1) {
        log_error("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }

    if (read(data->file, buf, MAX_SPI_DATA) != MAX_SPI_DATA) {
        log_error("Failed to read from SPI device");
        exit(EXIT_FAILURE);
    }

    result = (buf[1] << 8) | buf[2];
    return result;
}

void log_entry(const char *timestamp, uint16_t lux, uint16_t sound) {
    char log_line[128];
    snprintf(log_line, sizeof(log_line), "%s, Light: %u, Sound: %u\n", timestamp, lux, sound);
    printf("%s", log_line);

    FILE *log_file = fopen("environmental_log.txt", "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fputs(log_line, log_file);
    fclose(log_file);
}

void cleanup(struct sensor_data *sensor_data) {
    close(sensor_data->bh1750.file);
    close(sensor_data->mcp3008.file);
    munmap(sensor_data->mcp3008.spi, 4096);
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    cleanup(sensor_data);
    exit(EXIT_SUCCESS);
}

int main() {
    struct sensor_data sensor_data = {0};
    struct timespec ts = {0};
    uint16_t lux = 0, sound = 0;

    i2c_init(&sensor_data.bh1750.dev_name, "/dev/i2c-1");
    spi_init(&sensor_data.mcp3008);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        i2c_read_bh1750(&sensor_data.bh1750, &lux);
        sound = spi_read_mcp3008(&sensor_data.mcp3008, MCP3008_CH0);

        log_entry(timestamp, lux, sound);
        ts.tv_sec += 1;
        nanosleep(&ts, NULL);
    }

    return 0;
}

