#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <libgpiod.h>

#define SENSOR_GPIO 17
#define LOG_FILE "flame_events.log"

static void log_event(const char *pin, const char *state) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];
    FILE *log_file = fopen(LOG_FILE, "a");

    if (!log_file) {
        perror("fopen");
        return;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%d,%s\n", time_str, SENSOR_GPIO, state);
    fclose(log_file);
}

static int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_byname");
        return -1;
    }

    line = gpiod_chip_get_line(chip, SENSOR_GPIO);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_put(chip);
        return -1;
    }

    ret = gpiod_line_request_output_flags(line, GPIOD_LINE_REQUEST_DIRECTION_IN,
                                          GPIOD_LINE_REQUEST_ACTIVE_HIGH);
    if (ret < 0) {
        perror("gpiod_line_request_output_flags");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        return -1;
    }

    ret = gpiod_line_set_debounce(line, 10);
    if (ret < 0) {
        perror("gpiod_line_set_debounce");
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(line);
        gpiod_chip_put(chip);
        return -1;
    }

    ret = gpiod_line_set_pull(line, GPIOD_PULL_DOWN);
    if (ret < 0) {
        perror("gpiod_line_set_pull");
        gpiod_line_set_value(line, 0);
        gpiod_line_put(line);
        gpiod_chip_put(line);
        gpiod_chip_put(chip);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_put(line);
    }

    if (chip) {
        gpiod_chip_put(chip);
    }
}

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state;

    ret = init_gpio();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return ret;
    }

    while (1) {
        ret = gpiod_line_get_value(line, &state);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (state) {
            printf("Flame detected!\n");
            log_event(SENSOR_GPIO, "HIGH");
        } else {
            log_event(SENSor_GPIO, "LOW");
        }

        sleep(1);
    }

    cleanup_gpio(chip, line);
    return ret;
}

