#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

#define ADC_SPI_CH 0
#define ADC_SPI_MODE 0
#define ADC_SPI_SPEED 500000
#define DAC_I2C_ADDR 0x62
#define DAC_I2C_BUS 1

#define TMP36_ADC_CHANNEL 0
#define TMP36_ADC_RESOLUTION 1024
#define TMP36_ADC_REFERENCE 3.3f
#define TMP36_TEMP_MIN_C 0.0f
#define TMP36_TEMP_MAX_C 50.0f
#define TMP36_TEMP_SCALE (TMP36_TEMP_MAX_C - TMP36_TEMP_MIN_C) / (TMP36_ADC_RESOLUTION - 1)
#define DAC_VOLTAGE_MIN 0.0f
#define DAC_VOLTAGE_MAX 3.3f
#define DAC_VOLTAGE_SCALE (DAC_VOLTAGE_MAX - DAC_VOLTAGE_MIN) / (TMP36_TEMP_MAX_C - TMP36_TEMP_MIN_C)

static const char *LOG_FILE = "temperature_log.txt";

int spi_init(int channel, int mode, int speed) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (spiOpen(channel, &spiHandle) < 0) {
        perror("spiOpen");
        return -1;
    }

    if (spiSetMode(spiHandle, mode) < 0) {
        perror("spiSetMode");
        return -1;
    }

    if (spiSetDataMode(spiHandle, 8) < 0) {
        perror("spiSetDataMode");
        return -1;
    }

    if (spiSetClockDivider(spiHandle, speed) < 0) {
        perror("spiSetClockDivider");
        return -1;
    }

    return 0;
}

int i2c_init(uint8_t addr, uint8_t bus) {
    if (i2c_setup(bus, &i2c_fd) < 0) {
        perror("i2c_setup");
        return -1;
    }

    if (i2c_address(i2c_fd, addr, I2C_ADDR_FLAG_READWRITE) < 0) {
        perror("i2c_address");
        return -1;
    }

    return 0;
}

float read_tmp36() {
    uint16_t adc_value;

    if (spi_init(ADC_SPI_CH, ADC_SPI_MODE, ADC_SPI_SPEED) < 0) {
        perror("spi_init");
        return NAN;
    }

    if (spiXfer(spiHandle, &adc_value, 2, NULL, 0, 1000) != 2) {
        perror("spiXfer");
        return NAN;
    }

    float temp_c = TMP36_TEMP_MIN_C + TMP36_TEMP_SCALE * (adc_value / TMP36_ADC_RESOLUTION);

    spiClose(spiHandle);

    return temp_c;
}

void write_dac(float voltage) {
    uint16_t dac_value = DAC_VOLTAGE_MIN + DAC_VOLTAGE_SCALE * voltage;

