#include <time.h>
#include <pigpio.h>

#define MCP3008_ADDR 0x48
#define CS_PIN 18
#define MOISTURE_SENSORS 3

static char log_file[] = "soil_data.txt";

void die(const char *msg) {
    perror(msg);
    exit(1);
}

void log_timestamped_data(int sensor, unsigned int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s, Sensor %d: %u\n", time_str, sensor, adc_value);
    fprintf(stderr, "%s, Sensor %d: %f%%\n", time_str, sensor,
            (1.0 - (adc_value / 1023.0)) * 100.0);
    fprintf(stderr, "%s, Sensor %d: %u\n", time_str, sensor, adc_value);
}

int main(void) {
    int fd, i;
    unsigned char data[3];
    unsigned int adc_values[MOISTURE_SENSORS];

    if (gpioInitialise() < 0)
        die("gpioInitialise");

    if (spiOpen(&fd, MCP3008_ADDR, CS_PIN, 0) < 0)
        die("spiOpen");

    for (i = 0; i < MOISTURE_SENSORS; ++i) {
        data[0] = (i << 5) | 0x01; // Set command: single-ended, channel, start conversion
        if (spiXfer(fd, data, data, 1, 3) < 0)
            die("spiXfer");

        if (data[2] & 0x08) { // Check for conversion complete
            die("ADC conversion failed");
        }

        adc_values[i] = (data[1] << 8) | data[2];
        if (adc_values[i] > 1023 || adc_values[i] < 0) {
            fprintf(stderr, "Invalid ADC value: %u\n", adc_values[i]);
            continue;
        }

        log_timestamped_data(i + 1, adc_values[i]);
    }

    gpioTerminate();
    spiClose(fd);

    FILE *log_file_ptr = fopen(log_file, "a");
    if (!log_file_ptr)
        die("fopen");

    for (i = 0; i < MOISTURE_SENSORS; ++i) {
        fprintf(log_file_ptr, "%s, Sensor %d: %u\n", ctime(&rawtime), i + 1,
                adc_values[i]);
    }

    fclose(log_file_ptr);

    sleep(60);

    signal(SIGINT, [](int signum) {
        gpioTerminate();
        spiClose(fd);
        pigpio_stop();
        fprintf(stderr, "Goodbye!\n");
        exit(0);
    });

    while (1) {
        if (gpioTerminate() < 0 || spiClose(fd) < 0)
            die("Termination error");

        if (gpioInitialise() < 0)
            die("gpioInitialise");

        if (spiOpen(&fd, MCP3008_ADDR, CS_PIN, 0) < 0)
            die("spiOpen");

        for (i = 0; i < MOISTURE_SENSORS; ++i) {
            // Repeat read and logging process here
        }

        sleep(60);
    }

    return 0;
}

