#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define RELAY_PIN_COUNT 4
#define DELAY_MS 1000

static gpiod_line_handle_array_t *relay_handles;
static int relay_pins[RELAY_PIN_COUNT] = {17, 22, 23, 24};

void signal_handler(int signum) {
    for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
        gpiod_line_set_value(relay_handles[i], 0);
    }

    gpiod_line_release(relay_handles[0]);
    free(relay_handles);
    exit(0);
}

int main(void) {
    struct gpiod_chip *chip;
    int ret;

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Request GPIO chip
    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    // Allocate memory for relay handles
    relay_handles = malloc(RELAY_PIN_COUNT * sizeof(gpiod_line_handle_t));
    if (!relay_handles) {
        perror("Failed to allocate memory for relay handles");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request output lines and set initial values
    for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
        gpiod_line_request_output(chip, relay_pins[i], "relay_sequencer");
        ret = gpiod_line_set_value(relay_handles[i] = gpiod_get_line_byname(chip, gpiolib_get_line_name(chip, relay_pins[i])), 0);
        if (ret < 0) {
            perror("Failed to set relay initial value");
            goto cleanup;
        }
    }

    // Main loop
    for (int relay = 0; relay < RELAY_PIN_COUNT; ++relay) {
        gpiod_line_set_value(relay_handles[relay], 1);
        usleep(DELAY_MS * 1000);
        gpiod_line_set_value(relay_handles[relay], 0);
        usleep((RELAY_PIN_COUNT - relay - 1) * DELAY_MS * 1000);
    }

    // Cleanup and release resources
cleanup:
    for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
        if (relay_handles[i]) {
            gpiod_line_release(relay_handles[i]);
        }
    }
    free(relay_handles);
    gpiod_chip_close(chip);

    return 0;
}

