#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CS_GPIO          8
#define ADC_MODE             0
#define ADC_CLOCK_DIVIDER    1
#define ADC_CHANNEL          0
#define LED_GPIO            16
#define THRESHOLD            500
#define SAMPLE_INTERVAL      10
#define DEBOUNCE_DELAY       100
#define LOG_FILE             "sound_events.log"

static int g_gpio_init = 0;
static int g_spi_fd = -1;
static int g_led_state = 0;

void signal_handler(int signum) {
    if (g_spi_fd != -1) {
        gpioTerm(g_spi_fd);
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    if (g_gpio_init) {
        gpioTerm();
        g_gpio_init = 0;
    }

    g_led_state = 0;
    gpioWrite(LED_GPIO, g_led_state);

    exit(0);
}

int adc_read() {
    uint32_t adc_value = 0;
    int status = 0;

    if (g_spi_fd == -1) {
        status = gpioInitialise();
        if (status < 0) {
            perror("gpioInitialise");
            return -1;
        }
        g_gpio_init = 1;

        status = gpioSetMode(ADC_CS_GPIO, PI_OUTPUT);
        if (status < 0) {
            perror("gpioSetMode");
            return -1;
        }

        status = gpioSetMode(LED_GPIO, PI_OUTPUT);
        if (status < 0) {
            perror("gpioSetMode");
            return -1;
        }

        status = gpioSetMode(ADC_CHANNEL, PI_ANALOG);
        if (status < 0) {
            perror("gpioSetMode");
            return -1;
        }

        status = gpioSetSPI(ADC_CS_GPIO, ADC_MODE, ADC_CLOCK_DIVIDER);
        if (status < 0) {
            perror("gpioSetSPI");
            return -1;
        }

        g_spi_fd = gpioOpen(ADC_CHANNEL, GPIO_RD_DATA, 0, 0);
        if (g_spi_fd < 0) {
            perror("gpioOpen");
            return -1;
        }
    }

    status = gpioWrite(ADC_CS_GPIO, 0);
    if (status < 0) {
        perror("gpioWrite");
        return -1;
    }

    status = write(g_spi_fd, "\x00\x40\x00\x00", 4);
    if (status != 4) {
        perror("write");
        return -1;
    }

    status = read(g_spi_fd, &adc_value, 4);
    if (status != 4) {
        perror("read");
        return -1;
    }

    adc_value = (adc_value >> 4) & 0x0FFF;

    gpioWrite(ADC_CS_GPIO, 1);

    return adc_value;
}

void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s\n", time_str);
    fclose(log_file);
}

int main() {
    signal(SIGINT, signal_handler);

    while (1) {
        int adc_value = adc_read();
        if (adc_value < 0) {
            perror("adc_read");
            continue;
        }

        if (adc_value > THRESHOLD) {
            g_led_state = !g_led_state;
            gpioWrite(LED_GPIO, g_led_state);
            log_event();
            usleep(500000);

            usleep(DEBOUNCE_DELAY * 1000);
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    return 0;
}

