        perror("Failed to read from MCP3008");
        return -1;
    }

    if (gpioWrite(GPIO_SPI_CS0, 1) != GPIO_OK) {
        perror("Failed to write CS0 high");
        return -1;
    }

    adc_value = (rx[1] & 0x0F) << 8 | rx[2];
    return adc_value;
}

