    int rain_level;
    int motor_pin_en_a = GPIO_17;
    int motor_pin_en_b = GPIO_18;
    int motor_pin_in1 = GPIO_27;
    int motor_pin_in2 = GPIO_22;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(motor_pin_en_a, PI_OUTPUT) != GPIO_OK ||
        gpioSetMode(motor_pin_en_b, PI_OUTPUT) != GPIO_OK ||
        gpioSetMode(motor_pin_in1, PI_OUTPUT) != GPIO_OK ||
        gpioSetMode(motor_pin_in2, PI_OUTPUT) != GPIO_OK) {
        perror("Failed to set GPIO modes");
        return 1;
    }

    if (gpioSetPWMfunction(motor_pin_en_a, PWM_RANGE, PWM_DUTY) != GPIO_OK ||
