        perror("Failed to set PWM functions");
        return 1;
    }

    if (gpioSetPWMrange(motor_pin_en_a, PWM_RANGE) != GPIO_OK ||
        gpioSetPWMrange(motor_pin_en_b, PWM_RANGE) != GPIO_OK) {
        perror("Failed to set PWM ranges");
        return 1;
    }

    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    struct spi_ioc_transfer xfer[1] = {
        {
            .tx_buf = {0x01, (0x08 | CHANNEL) << 4, 0x00},
            .rx_buf = {0},
            .len = 3,
            .delay_usecs = 10,
            .speed_hz = 1000000,
            .bits_per_word = 8,
        }
    };

    while (!shutdown) {
        rain_level = read_adc(CHANNEL);
        rain_level = (1023 - rain_level) * 10 / 1023;
        log_rain_reading(rain_level);

        if (rain_level >= RAIN_THRESHOLD) {
            gpioWrite(motor_pin_in1, 1);
            gpioWrite(motor_pin_in2, 0);
            gpioHardwarePWM(motor_pin_en_a, PWM_DUTY);
