            gpioWrite(motor_pin_in1, 0);
            gpioWrite(motor_pin_in2, 1);
            gpioHardwarePWM(motor_pin_en_b, PWM_DUTY);
            sleep(3);
        }

        usleep(1000000);
    }

    close(spi_fd);
    gpioTerminate();

    return 0;
}

