#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_GPIO 26
#define LED_GPIO 16
#define ADC_RESOLUTION 10
#define ADC_REF_VOLTAGE 3.3
#define THRESHOLD (2.31 * ADC_RESOLUTION / ADC_REF_VOLTAGE)
#define DEBOUNCE_MS 50
#define DETECT_MS 500

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
    gpioTerm(0);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(ADC_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm(0);
        return 1;
    }

    if (gpioSetPullUpDown(ADC_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set ADC GPIO pull-up\n");
        gpioTerm(0);
        return 1;
    }

    int adc_value = 0;
    unsigned long last_detect = 0;

    while (running) {
        adc_value = (gpioRead(ADC_GPIO) * (ADC_RESOLUTION - 1)) / (1 << 16);

        if (adc_value > THRESHOLD) {
            if (time(NULL) - last_detect > DEBOUNCE_MS) {
                gpioWrite(LED_GPIO, 1);
                printf("Clap detected at %s\n", ctime(&time(NULL)));
                last_detect = time(NULL);
                usleep(DETECT_MS * 1000);
                gpioWrite(LED_GPIO, 0);
            }
        }
    }

    gpioTerm(0);
    return 0;
}

