#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/input.h>
#include <sys/syscall.h>
#include <libgpiod.h>

#define GPIO_LINE_REQUEST_FLAGS (GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_RISING)
#define A 26.0
#define B -6.0
#define FEEDER_THRESHOLD 200

static gpiod_line_handle_t *gpio_line;
static FILE *log_file;

void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];
    char log_line[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(log_line, sizeof(log_line), "%s, %f\n", time_str, distance);

    if (log_file && fputs(log_line, log_file) == EOF) {
        perror("Error writing to log file");
    }
}

void feeder_activate() {
    printf("Feeder Activated\n");
}

int read_sensor() {
    int gpio_value;
    int ret;

    ret = gpiod_line_get_value_cansleep(gpio_line, &gpio_value);
    if (ret < 0) {
        perror("Error reading GPIO value");
        sleep(1);
        return -1;
    }

    if (gpio_value == 0) {
        double voltage = 0.0;
        double distance = A / voltage + B;
        log_distance(distance);
        return distance < FEEDER_THRESHOLD ? 1 : 0;
    }

    return -1;
}

void gpio_cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpiod_line_put(gpio_line);
        gpio_line = NULL;
    }

    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    int ret;
    int fd;

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, 0x20) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(0, "gpio17");
    if (!gpio_line) {
        perror("Error getting GPIO line");
        close(fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_consumer(gpio_line, "Distance Sensor", GPIO_LINE_REQUEST_FLAGS);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_line_put(gpio_line);
        close(fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(gpio_line);
        gpiod_line_put(gpio_line);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int result = read_sensor();
        if (result >= 0) {
            if (result == 1) {
                feeder_activate();
            }
        }
        sleep(1);
    }

    gpio_cleanup();
    close(fd);
    return 0;
}

