#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <errno.h>
#include <libgpiod.h>

#define MCP3008_CS_GPIO 8
#define MCP3008_SPI_DEVICE "/dev/spidev0.0"
#define MCP3008_SPI_MODE 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_ADC_CHANNEL 0
#define DRV5055_SENSITIVITY 100
#define DRV5055_QUIE_OUTPUT 1650
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL 500

static gpiod_chip *gpiochip;
static int spi_fd;
static struct spi_ioc_transfer transfer = {
    .tx_buf = (unsigned char *) &tx_buf,
    .rx_buf = (unsigned char *) &rx_buf,
    .len = sizeof(tx_buf),
    .delay_usecs = 0,
    .speed_hz = MCP3008_SPI_SPEED,
};

static uint8_t tx_buf = {0};
static uint8_t rx_buf[3];

void sigint_handler(int signum) {
    gpiod_set_value_cansleep(gpiochip, MCP3008_CS_GPIO, 1);
    close(spi_fd);
    gpiod_release(gpiochip);
    fclose(log_file);
    exit(0);
}

float read_adc() {
    gpiod_set_value_cansleep(gpiochip, MCP3008_CS_GPIO, 0);
    if (spi_xcv(spi_fd, &transfer, 1) != 1) {
        perror("SPI read error");
        return NAN;
    }
    gpiod_set_value_cansleep(gpiochip, MCP3008_CS_GPIO, 1);

    uint16_t adc_value = (rx_buf[1] << 8) | rx_buf[2];
    float vout_mV = (float)adc_value * 3300.0 / 1023.0;
    float B_mT = ((vout_mV - DRV5055_QUIE_OUTPUT) / DRV5055_SENSITIVITY);
    return B_mT;
}

int main() {
    struct stat st;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ts_sec = ts.tv_sec;
    double ts_frac = ts.tv_nsec / 1e9;

    gpiochip = gpiod_chip_open_byname("gpiochip0");
    if (!gpiochip) {
        perror("Failed to open gpiochip");
        return 1;
    }

    if (gpio_is_requested(gpiochip, MCP3008_CS_GPIO)) {
        gpiod_line_request_dt(gpiochip, MCP3008_CS_GPIO, "MCP3008 CS");
    } else {
        gpiod_line_request_dir(gpiochip, MCP3008_CS_GPIO, GPIOD_LINE_DIR_OUT);
    }

    spi_fd = open(MCP3008_SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        goto cleanup_gpio;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &MCP3008_SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        goto cleanup_spi;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &MCP3008_SPI_SPEED) != 0) {
        perror("Failed to set SPI speed");
        goto cleanup_spi;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_spi;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        float B_mT = read_adc();
        if (B_mT == NAN) continue;

        ts = ts;
        ts.tv_sec += SAMPLE_INTERVAL / 1e6;
        ts.tv_nsec = (ts.tv_sec * 1e9 + SAMPLE_INTERVAL % 1e6) % 1e9;
        clock_nanosleep(CLOCK_REALTIME, TIMER_ABSTIME, &ts, NULL);

        fprintf(log_file, "%ld,%.2f\n", (long)ts_sec, B_mT);
        ts_sec = ts.tv_sec;
        ts_frac = ts.tv_nsec / 1e9;
    }

cleanup_spi:
    close(spi_fd);

cleanup_gpio:
    gpiod_line_release(gpiochip, MCP3008_CS_GPIO);
    gpiod_chip_close(gpiochip);

    fclose(log_file);

    return 0;
}

