#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define MCP3008_CS_PIN 24
#define MCP3008_SPI_CH 0
#define MCP3008_ADC_RES 1024
#define SAMPLE_INTERVAL 60
#define LOG_FILE "moisture_log.txt"

int init_pigpio(void);
int init_spi(void);
int read_adc(uint16_t *rx_buf);
void log_data(const char *timestamp, int adc_value);
void log_error(const char *timestamp, const char *message);
void cleanup(void);

int main(void) {
    if (init_pigpio() != 0) {
        return 1;
    }

    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    while (1) {
        if (read_adc(rx_buf) < 0) {
            log_error(ctime(&rawtime), "ADC read failure");
            continue;
        }

        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        log_data(timestamp, rx_buf[2] | (rx_buf[1] & 0x03) << 8);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }
    return 0;
}

int init_spi(void) {
    if (spiOpen(MCP3008_SPI_CH, 1000000) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", MCP3008_SPI_CH);
        return -1;
    }

    gpioSetMode(MCP3008_CS_PIN, PI_OUTPUT);
    gpioWrite(MCP3008_CS_PIN, 1);
    return 0;
}

int read_adc(uint16_t *rx_buf) {
    uint8_t tx_buf[3] = {0x01, 0x80 | (MCP3008_ADC_RES - 1), 0x00};
    int result = spiXfer(MCP3008_SPI_CH, tx_buf, sizeof(tx_buf), rx_buf, sizeof(rx_buf));

    if (result != sizeof(rx_buf)) {
        return -1;
    }

    return 0;
}

void log_data(const char *timestamp, int adc_value) {
    FILE *log_file = fopen(LOG_FILE, "a");

    if (log_file == NULL) {
        log_error(timestamp, "Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %d\n", timestamp, adc_value);
    fclose(log_file);
}

void log_error(const char *timestamp, const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");

    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%s, Error: %s\n", timestamp, message);
    fclose(log_file);
}

void cleanup(void) {
    gpioTerm();
    spiClose(MCP3008_SPI_CH);
}

