#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>
#include <spidev.h>

#define GPIO_LINE 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BAUD 1000000

struct gpiod_line *gpio_line;
struct spi_device *spi;
int spi_fd;

void sigint_handler(int signum) {
    gpiod_line_set_value(gpio_line, 0);
    spi_close(spi_fd);
    gpiod_line_release(gpio_line);
    fclose(log_file);
    exit(0);
}

int init_gpio() {
    int ret;
    gpiod_line_request_array_with_consumer(NULL, 1, &gpio_line, "ADC_reader", GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW);
    if (IS_ERR(gpio_line)) {
        perror("Failed to request GPIO line");
        return -1;
    }
    ret = gpiod_line_get_value(gpio_line);
    if (ret < 0) {
        perror("Failed to get initial GPIO line value");
        return -1;
    }
    gpiod_line_set_value(gpio_line, 1);
    return 0;
}

int init_spi() {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned char *) NULL,
        .rx_buf = (unsigned char *) NULL,
        .len = 0,
        .delay_usecs = 0,
        .speed_hz = SPI_BAUD,
        .bits_per_word = 8,
    };

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &SPI_MODE) != 0) {
        perror("Failed to get SPI mode");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_BAUD) != 0) {
        perror("Failed to set SPI speed");
        return -1;
    }

    transfer.tx_buf = (unsigned char *) malloc(3);
    transfer.rx_buf = (unsigned char *) malloc(3);
    transfer.len = 3;

    if (transfer.tx_buf == NULL || transfer.rx_buf == NULL) {
        perror("Failed to allocate memory for SPI transfer");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Failed to perform SPI transfer");
        return -1;
    }

    free(transfer.tx_buf);
    free(transfer.rx_buf);

    return 0;
}

int main() {
    int ret;
    FILE *log_file;
    time_t timestamp;
    double current_A;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_gpio() < 0) {
        perror("Failed to initialize GPIO");
        return -1;
    }

    if (init_spi() < 0) {
        perror("Failed to initialize SPI");
        return -1;
    }

    log_file = fopen("current_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    while (1) {
        ret = init_spi();
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            continue;
        }

        current_A = (transfer.rx_buf[1] * 3.3) / 1023 * 100;

        time(&timestamp);
        fprintf(log_file, "%ld,%f\n", timestamp, current_A);

        sleep(1);
    }

    fclose(log_file);
    return 0;
}

