    char timestamp[30];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + 14, 6, "%.2f", current);

    FILE *log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        perror("Failed to open current_log.txt");
        gpioTerminate();
        exit(1);
    }

    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file);
    fclose(log_file);
}

double interpolate_current(double voltage) {
    if (voltage < 2.5 || voltage > 5.0) {
        fprintf(stderr, "Warning: Voltage out of range [2.5V, 5V]\n");
        return NAN;
    }

    return (voltage - 2.5) * (50.0 / 2.5);
}

int read_adc(int channel) {
    int tx[3] = {0x01, 0x80 | (channel << 4), 0x00};
    int rx[3];

    if (spiXfer(SPI_CHANNEL, tx, rx, 3) < 0) {
        perror("SPI transfer error");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main() {
    int pi_fd = pigpio_init(NULL);
    if (pi_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(pi_fd));
        exit(1);
    }

    if (wiringPiSetup() < 0) {
        fprintf(stderr, "Failed to setup wiringPi: %s\n", strerror(wiringPiSetup()));
        gpioTerminate(pi_fd);
        exit(1);
    }

    gpioSetMode(SPI_CE, PI_OUTPUT);
    gpioWrite(SPI_CE, 1);

    int spi_fd = spiOpen(SPI_CE, SPI_MODE_0, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus: %s\n", strerror(spi_fd));
        gpioTerminate(pi_fd);
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    while (!g_interrupt_received) {
        int adc_value = read_adc(MLX91211_CH_0);
        if (adc_value < 0) {
            continue;
        }

        double voltage = adc_value * 3.3 / 1023;
        double current = interpolate_current(voltage);
        log_current(current);

        gpioDelay(100000);
    }

    spiClose(spi_fd);
    gpioTerminate(pi_fd);

    return 0;
}
```

This code initializes the pigpio library, sets up the SPI bus, reads the ADC value from the MCP3008, interpolates the current, logs the current value, and handles errors gracefully. It also installs a SIGINT handler to cleanly exit the program when the user presses Ctrl+C.

