#define DEBOUNCE_DELAY_US 2000
#define LOG_INTERVAL_MS 1000

static gpiod_line_handle_t *sensor1_line;
static gpiod_line_handle_t *sensor2_line;
static struct gpiod_chip *chip;

void log_sensor_state(int sensor, int state) {
    static long last_log = 0;
    long now = time(NULL);

    if (now - last_log >= LOG_INTERVAL_MS) {
        printf("Sensor %d: %s\n", sensor, state ? "No object" : "Object present");
        last_log = now;
    }
}

int read_sensor(gpiod_line_handle_t *line) {
    int samples[DEBOUNCE_SAMPLES];
    int i, majority;

    for (i = 0; i < DEBOUNCE_SAMPLES; i++) {
        usleep(DEBOUNCE_DELAY_US);
        samples[i] = gpiod_line_get_value(line);
    }

    majority = samples[0];
    for (i = 1; i < DEBOUNCE_SAMPLES; i++) {
        majority = (samples[i] == 1) ? (majority + 1) : (majority - 1);
    }

    return majority < 0 ? 1 : 0;
}

int main(void) {
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!sensor1_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(sensor1_line, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!sensor2_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(sensor2_line, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("gpiod_line_request_input");
        gpiod_line_release(sensor2_line);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (1) {
        int sensor1_state = read_sensor(sensor1_line);
        int sensor2_state = read_sensor(sensor2_line);

        log_sensor_state(SENSOR1_GPIO, sensor1_state);
        log_sensor_state(SENSOR2_GPIO, sensor2_state);

        if (sensor1_state == sensor2_state && sensor1_state == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        usleep(100000);
    }

    gpiod_line_release(sensor2_line);
    gpiod_line_release(sensor1_line);
    gpiod_chip_close(chip);

    return 0;
}

