#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/wait.h>

#define PIR_GPIO 17
#define CAM_RESOLUTION "1280x720"
#define CAM_ISO_TIMESTAMP_FORMAT "/%Y-%m-%d_%H-%M-%S"
#define CAM_OUTPUT_DIR "/home/pi/security_cam"
#define CAM_COMMAND "libcamera-still"

static int g_pigpio_init_status;
static pid_t g_child_pid;

void log_event(const char *event) {
    openlog("security_cam", LOG_PID | LOG_PERROR, LOG_USER);
    syslog(LOG_INFO, "Event: %s", event);
    closelog();
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }
    g_pigpio_init_status = 1;
    return 0;
}

void cleanup_pigpio() {
    if (g_pigpio_init_status) {
        gpioTerm();
        g_pigpio_init_status = 0;
    }
}

void setup_gpio(int gpio) {
    if (gpioSetMode(gpio, PI_INPUT) < 0 || gpioSetPullUpDown(gpio, PI_PUD_DOWN) < 0) {
        perror("gpioSetMode or gpioSetPullUpDown");
    }
}

void poll_gpio(int gpio, unsigned int delay_ms) {
    unsigned int prev_state = gpioRead(gpio);
    usleep(delay_ms * 1000);
    unsigned int cur_state = gpioRead(gpio);

    if (prev_state != cur_state) {
        usleep(200 * 1000); // Debounce delay
        if (gpioRead(gpio) != prev_state) {
            log_event("Motion detected");
            capture_image();
        }
    }
}

void capture_image() {
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;
    char output_path[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), CAM_ISO_TIMESTAMP_FORMAT, timeinfo);
    snprintf(output_path, sizeof(output_path), "%s/%s.jpg", CAM_OUTPUT_DIR, timestamp);

    if (access(CAM_OUTPUT_DIR, F_OK | R_OK | W_OK) != 0) {
        perror("Accessing output directory");
        return;
    }

    pid_t child_pid = fork();
    if (child_pid == -1) {
        perror("Fork failed");
        return;
    }

    if (child_pid == 0) {
        execlp(CAM_COMMAND, CAM_COMMAND, "--resolution", CAM_RESOLUTION, "--output", output_path, (char *)NULL);
        perror("Execvp failed");
        exit(1);
    }

    int status;
    waitpid(child_pid, &status, 0);

    if (WEXITSTATUS(status) != 0) {
        log_event("Capture failed");
    } else {
        log_event("Capture success");
    }
}

int main(int argc, char *argv[]) {
    if (init_pigpio() != 0) {
        return 1;
    }

    setup_gpio(PIR_GPIO);

    log_event("Startup");

    while (1) {
        poll_gpio(PIR_GPIO, 50);
    }

    cleanup_pigpio();
    return 0;
}

