struct v4l2_requestbuffers req;
struct v4l2_buffer *buffers;
fd_set fds;
struct timeval tv;
int frame_count = 0;

void handle_signal(int sig) {
    printf("\nGracefully shutting down...\n");
    close(fd);
    munmap(buffers[0].start, buffers[0].length);
    free(buffers);
    exit(0);
}

int xioctl(int fd, int request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main() {
    signal(SIGINT, handle_signal);

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("Cannot open /dev/video0");
        return 1;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &fmt) < 0) {
        perror("Cannot query video device capabilities");
        return 1;
    }

    if (!(fmt.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return 1;
    }

    fmt.format.pix_format.width = 640;
    fmt.format.pix_format.height = 480;
    fmt.format.pix_format.field = V4L2_FIELD_ANY;
    fmt.format.pix_format.pixelformat = V4L2_PIX_FMT_MJPEG;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Cannot set video format");
        return 1;
    }

    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Cannot request buffers");
        return 1;
    }

    buffers = malloc(req.count * sizeof(struct v4l2_buffer));
    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer *b = &buffers[i];
        b->b = &buffers[i];
        b->buf.index = i;
        b->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_QBUF, &b->buf) < 0) {
            perror("Cannot queue buffer");
            return 1;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMON, &req.type) < 0) {
        perror("Cannot start streaming");
        return 1;
    }

    void *maps[BUFFER_COUNT];
    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer *b = &buffers[i];
        if (xioctl(fd, VIDIOC_DQBUF, &b->buf) < 0) {
            perror("Cannot dequeue buffer");
            return 1;
        }
        maps[i] = mmap(NULL, b->buf.length, PROT_READ, MAP_SHARED, fd, b->buf.m.offset);
        if (maps[i] == MAP_FAILED) {
            perror("Cannot map buffer");
            return 1;
        }
    }

    while (1) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        select(fd + 1, &fds, NULL, NULL, &tv);

        if (FD_ISSET(fd, &fds)) {
            if (xioctl(fd, VIDIOC_DQBUF, &buffers[0].buf) == 0) {
