                gettimeofday(&tv, NULL);
                printf("%lu.%06lu\n", (unsigned long)tv.tv_sec, (unsigned long)tv.tv_usec);
                FILE *fp = fopen("frame_log.txt", "a");
                if (fp) {
                    fprintf(fp, "%lu.%06lu\n", (unsigned long)tv.tv_sec, (unsigned long)tv.tv_usec);
