                }

                if (xioctl(fd, VIDIOC_QBUF, &buffers[0].buf) < 0) {
                    perror("Cannot queue buffer");
                }

                for (int i = 1; i < req.count; i++) {
                    struct v4l2_buffer *b = &buffers[i];
                    if (xioctl(fd, VIDIOC_DQBUF, &b->buf) == 0) {
                        munmap(maps[i - 1], maps[i - 1] ? maps[i - 1]->length : 0);
                        maps[i - 1] = mmap(NULL, b->buf.length, PROT_READ, MAP_SHARED, fd, b->buf.m.offset);
                        if (maps[i - 1] == MAP_FAILED) {
                            perror("Cannot remap buffer");
                            return 1;
                        }
                    } else if (b->buf.flags & V4L2_BUF_FLAG_DONE) {
                        frame_count++;
                    } else {
                        break;
                    }
                }
            }
        }
    }

    return 0;
}

