void servo_cb_handler(struct gpiod_line_request *request, int event, void *data) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        gpiod_line_set_value(request, 0);
    }
}

void button_cb_handler(struct gpiod_line_request *request, int event, void *data) {
    if (event == GPIOD_LINE_EVENT_EDGE_RISING) {
        int gpio = request->number;
        switch (gpio) {
            case BUTTON_UP_GPIO:
                tilt_move(tilt_get() + SERVO_STEP);
                break;
            case BUTTON_DOWN_GPIO:
                tilt_move(tilt_get() - SERVO_STEP);
                break;
            case BUTTON_LEFT_GPIO:
                pan_move(pan_get() - SERVO_STEP);
                break;
            case BUTTON_RIGHT_GPIO:
                pan_move(pan_get() + SERVO_STEP);
                break;
        }
    }
}

void pan_move(int duty) {
    if (duty < SERVO_MIN) {
        duty = SERVO_MIN;
    } else if (duty > SERVO_MAX) {
        duty = SERVO_MAX;
    }
