    struct v4l2_requestbuffers req = {
        .count = BUFFER_COUNT,
        .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
        .memory = VMEM_MMAP,
    };

    if (xioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        exit(1);
    }

    buffers = malloc(req.count * sizeof(struct v4l2_buffer));
    if (!buffers) {
        perror("Failed to allocate buffer memory");
        exit(1);
    }

    for (int i = 0; i < req.count; ++i) {
        struct v4l2_buffer *b = &buffers[i];
        b->mem = mmap(NULL, req.buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, camera_fd, req.buffers[i].m.offset);
