    for (int i = 0; i < req.count; ++i) {
        struct v4l2_buffer *b = &buffers[i];
        struct v4l2_buffer *next = (i + 1 < req.count) ? &buffers[i + 1] : buffers;
        b->next = next->mem ? next : buffers;
        if (xioctl(camera_fd, VIDIOC_QBUF, b) < 0) {
            perror("Failed to queue buffer");
            exit(1);
