    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(camera_fd, &fds);

    struct timeval tv = { 2000, 0 };

    while (1) {
        if (select(camera_fd + 1, &fds, NULL, NULL, &tv) > 0) {
            struct v4l2_buffer *b = buffers;
            if (xioctl(camera_fd, VIDIOC_DQBUF, b) < 0) {
