For the box blur implementation, you can use the following code as a starting point:

```c
void box_blur(unsigned char *image, int width, int height, int radius) {
    int kernel_size = 2 * radius + 1;
    int kernel[kernel_size][kernel_size];
    int sum;

    for (int i = 0; i < kernel_size; ++i) {
        for (int j = 0; j < kernel_size; ++j) {
            kernel[i][j] = (i - radius) * (i - radius) + (j - radius) * (j - radius);
            if (kernel[i][j] <= radius * radius) {
                kernel[i][j] = 1;
            } else {
                kernel[i][j] = 0;
            }
        }
    }

    for (int y = radius; y < height - radius; ++y) {
        for (int x = radius; x < width - radius; ++x) {
            sum = 0;
            for (int ky = -radius; ky <= radius; ++ky) {
                for (int kx = -radius; kx <= radius; ++kx) {
                    int ny = y + ky;
                    int nx = x + kx;
                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        sum += image[(ny * width + nx) * 3 + 0] * kernel[ky + radius][kx + radius];
                        sum += image[(ny * width + nx) * 3 + 1] * kernel[ky + radius][kx + radius];
                        sum += image[(ny * width + nx) * 3 + 2] * kernel[ky + radius][kx + radius];
                    }
                }
            }
            image[(y * width + x) * 3 + 0] = sum / (kernel_size * kernel_size);
            image[(y * width + x) * 3 + 1] = sum / (kernel_size * kernel_size);
            image[(y * width + x) * 3 + 2] = sum / (kernel_size * kernel_size);
        }
    }
}
