    printf("Type: %s\n", fmt.fmt.pix.pixelformat == V4L2_PIX_FMT_YUYV ? "YUYV" : "Unknown");
    printf("Width: %d\n", fmt.fmt.pix.width);
    printf("Height: %d\n", fmt.fmt.pix.height);

    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixelformat = fmt.fmt.pix.pixelformat;
    if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) < 0) {
        perror("Error enumerating frame sizes");
        close(fd);
        return 1;
    }

    printf("\nSupported resolutions:\n");
    while (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
        printf("Width: %d, Height: %d\n", frmsize.discrete.width, frmsize.discrete.height);
        memset(&frmsize, 0, sizeof(frmsize));
        if (++frmsize.index >= frmsize.count) break;
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) < 0) {
            perror("Error enumerating frame sizes");
            close(fd);
            return 1;
        }
    }

    memset(&frmival, 0, sizeof(frmival));
    frmival.index = 0;
    frmival.pixelformat = fmt.fmt.pix.pixelformat;
    frmival.width = fmt.fmt.pix.width;
    frmival.height = fmt.fmt.pix.height;
    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) < 0) {
        perror("Error enumerating frame intervals");
        close(fd);
        return 1;
    }

    printf("\nSupported frame rates:\n");
    while (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
        printf("Numerator: %d, Denominator: %d\n", frmival.discrete.numerator, frmival.discrete.denominator);
        memset(&frmival, 0, sizeof(frmival));
        if (++frmival.index >= frmival.count) break;
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) < 0) {
            perror("Error enumerating frame intervals");
            close(fd);
            return 1;
        }
    }

    memset(&query_ctrl, 0, sizeof(query_ctrl));
    query_ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &query_ctrl) >= 0) {
        printf("\nAutofocus is supported.\n");
    } else if (errno != ENOATTR) {
        perror("Error querying focus control");
    }

    close(fd);
    return 0;
}
```

This code opens the video device at `/dev/video0`, checks if it is a valid V4L2 device, queries its capabilities, current format, supported resolutions, frame rates, and autofocus support. It handles errors by printing an error message and exiting with a non-zero code. The code also checks the return values of every ioctl call and handles the cases where the device node does not exist or cannot be opened, where the camera does not support frame-size or interval enumeration, and where the focus control is not present.

