#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define CAMERA_WIDTH 640
#define CAMERA_HEIGHT 480
#define CAMERA_QUALITY 85
#define SERVER_IP "<server_ip>"
#define SERVER_PORT "<server_port>"

static CURL *curl;
static char *filename;
static time_t last_motion = 0;

static void gpio_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0 || gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN)) {
        fprintf(stderr, "Failed to configure GPIO%d as input with pull-down resistor\n", PIR_GPIO);
        exit(EXIT_FAILURE);
    }
}

static void gpio_cleanup(void) {
    gpioTerminate();
}

static void curl_init(void) {
    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        exit(EXIT_FAILURE);
    }
}

static void curl_cleanup(void) {
    curl_easy_cleanup(curl);
}

static void create_dir_if_not_exists(const char *path) {
    struct stat st;

    if (stat(path, &st) == -1 && errno == ENOENT) {
        if (mkdir(path, 0755) == -1) {
            perror("Failed to create directory");
            exit(EXIT_FAILURE);
        }
    }
}

static size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    size_t remaing = size * nmemb;
    size_t written = fwrite(ptr, size, nmemb, stdout);
    return remaing - written;
}

static void send_json_payload(const char *filename, const char *timestamp, int motion, int pin) {
    char json[256];
    snprintf(json, sizeof(json),
             "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":%d,\"pin\":%d}",
             filename, timestamp, motion, pin);

    CURLcode res;
    res = curl_easy_setopt(curl, CURLOPT_URL, http_build_url("%s:%s/upload", SERVER_IP, SERVER_PORT));
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set URL: %s\n", curl_easy_strerror(res));
        exit(EXIT_FAILURE);
    }

    res = curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to set write callback: %s\n", curl_easy_strerror(res));
        exit(EXIT_FAILURE);
    }

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to send JSON payload: %s\n", curl_easy_strerror(res));
        exit(EXIT_FAILURE);
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    curl_init();
    gpio_init();

    create_dir_if_not_exists("motion_captures");

    while (1) {
        int state = gpioRead(PIR_GPIO);
        if (state == GPIO_HIGH) {
            if (time(NULL) - last_motion > DEBOUNCE_MS) {
                last_motion = time(NULL);

                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", localtime(&last_motion));
                filename = asprintf(NULL, "motion_captures/%s.jpg", timestamp);
                if (!filename) {
                    perror("Failed to allocate memory for filename");
                    exit(EXIT_FAILURE);
                }

                char command[256];
                snprintf(command, sizeof(command),
                         "raspistill -o %s -w %d -h %d -q %d", filename, CAMERA_WIDTH, CAMERA_HEIGHT, CAMERA_QUALITY);
                system(command);

                send_json_payload(filename, timestamp, 1, PIR_GPIO);
            }
        }

        usleep(100000);
    }

    gpio_cleanup();
    curl_cleanup();
    free(filename);
    return 0;
}

curl_global_slist *global_init(void) {
    curl_global_slist *slist = curl_global_slist_append(NULL, CURL_GLOBAL_ALL);
    if (!slist) {
        perror("Failed to initialize libcurl global state");
        exit(EXIT_FAILURE);
    }
    return slist;
}

