static gpiod_line_data_callback_t g_gpio_callback;
static int g_gpio_fd = -1;
static FILE *g_log_file = NULL;

static void gpio_cb(struct gpiod_line_event *ev)
{
    time_t rawtime;
    struct tm *timeinfo;
    char filename[32];
    int ret;

    rawtime = time(NULL);
    timeinfo = localtime(&rawtime);
    snprintf(filename, sizeof(filename), "%04d%02d%02d_%02d%02d%02d_%03d.jpg",
             timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
             timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
             (int)(1000.0 * (ev->value ? 1.0 : 0.0)));

    ret = system(gsprintf("libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename));
    if (ret != 0) {
        fprintf(g_log_file, "[%s] Failed to capture image: %s\n", ctime(&rawtime), strerror(errno));
    } else {
        fprintf(g_log_file, "[%s] Captured image: %s\n", ctime(&rawtime), filename);
    }
}

int main(void)
{
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_data data = {
        .consumer = "Motion Detection",
        .request_flags = GPIO_LINE_REQUEST_FLAGS,
        .request_timeout_ms = GPIO_LINE_REQUEST_TIMEOUT_MS,
    };

    g_gpio_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (g_gpio_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    g_log_file = fdopen(g_gpio_fd, "w");
    if (!g_log_file) {
        perror("Failed to open log file for writing");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_open_byname("gpiochip0", &chip);
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line_bylabel(chip, "GPIO17", &g_gpio_request);
    if (ret < 0) {
        perror("Failed to get GPIO17 line");
        exit(EXIT_FAILURE);
    }

    g_gpio_callback.callback = gpio_cb;
    ret = gpiod_line_request_set_debounce(g_gpio_request, GPIO_LINE_REQUEST_TIMEOUT_MS);
    if (ret < 0) {
        perror("Failed to set debounce");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_set_callback(g_gpio_request, &g_gpio_callback);
    if (ret < 0) {
        perror("Failed to set callback");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_enable(g_gpio_request);
    if (ret < 0) {
        perror("Failed to enable GPIO line");
        exit(EXIT_FAILURE);
    }

    fprintf(g_log_file, "Started motion detection on GPIO17\n");

    while (1) {
        sleep(1);
    }

    gpiod_line_request_free(g_gpio_request);
    gpiod_chip_close(chip);
    fclose(g_log_file);
    close(g_gpio_fd);

    return 0;
}
