#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define BUFFER_COUNT 1
#define BUFFER_SIZE (WIDTH * HEIGHT * 2)

static int fd;
static void *buf_addr;

static void sigint_handler(int signum) {
    if (fd >= 0) {
        close(fd);
        munmap(buf_addr, BUFFER_SIZE);
        exit(EXIT_FAILURE);
    }
}

int main() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    fd_set fds;
    int ret, i;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    fd = open("/dev/video0", O_RDWR | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (strncmp(cap.driver, "uvcvideo", 8)) {
        fprintf(stderr, "This is not a USB UVC camera\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        exit(EXIT_FAILURE);
    }

    buf_addr = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf_addr == MAP_FAILED) {
        perror("mmap");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap(buf_addr, BUFFER_SIZE);
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) < 0) {
        perror("VIDIOC_STREAMON");
        munmap(buf_addr, BUFFER_SIZE);
        close(fd);
        exit(EXIT_FAILURE);
    }

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    while (1) {
        ret = select(fd + 1, &fds, NULL, NULL, NULL);
        if (ret < 0) {
            if (errno != EINTR) {
                perror("select");
                break;
            }
            continue;
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            perror("VIDIOC_DQBUF");
            continue;
        }

        if (buf.type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            continue;
        }

        if (buf.bytesused != BUFFER_SIZE ||
            buf.width != WIDTH ||
            buf.height != HEIGHT ||
            buf.format.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
            fprintf(stderr, "Invalid buffer format\n");
            continue;
        }

        uint8_t *yuyv = (uint8_t *)buf_addr;
        uint8_t *cropped_yuyv = malloc(CROP_WIDTH * CROP_HEIGHT * 2);

        for (i = 0; i < CROP_HEIGHT; ++i) {
            memcpy(cropped_yuyv + i * CROP_WIDTH * 2,
                   yuyv + (CROP_Y + i) * WIDTH * 2 + CROP_X * 2,
                   CROP_WIDTH * 4);
        }

        FILE *fp = fopen("cropped.yuv", "wb");
        if (!fp) {
            perror("fopen");
            free(cropped_yuyv);
            continue;
        }

        if (fwrite(cropped_yuyv, CROP_WIDTH * CROP_HEIGHT * 2, 1, fp) != 1) {
            perror("fwrite");
        }

        fclose(fp);
        free(cropped_yuyv);

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
        }
    }

    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
        perror("VIDIOC_STREAMOFF");
    }

    munmap(buf_addr, BUFFER_SIZE);
    close(fd);

    return EXIT_SUCCESS;
}

