#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <termios.termios>
#include <fcntl.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_MIN_PWM 500
#define SERVO_MAX_PWM 2500
#define SERVO_DEGREE_PER_PWM (SERVO_MAX_PWM - SERVO_MIN_PWM) / 180.0
#define SERVO_NEUTRAL_PWM ((SERVO_MIN_PWM + SERVO_MAX_PWM) / 2)
#define DEGREE_INCREMENT 5
#define DELAY_MS 100

static int servo_pan, servo_tilt;
static int servo_pwm_resolution = 16;
static int uart_fd;

void sigint_handler(int sig) {
    servo_pan = SERVO_NEUTRAL_PWM;
    servo_tilt = SERVO_NEUTRAL_PWM;
    gpioTerm(0);
    exit(0);
}

void set_servo(int gpio, int pwm) {
    if (pwm < SERVO_MIN_PWM || pwm > SERVO_MAX_PWM) {
        fprintf(stderr, "Invalid PWM value: %d\n", pwm);
        return;
    }

    gpio_set_PWMfrequency(gpio, servo_pwm_resolution);
    gpio_pwm_write(gpio, pwm);
}

int read_key() {
    char c;
    if (read(uart_fd, &c, 1) != 1) {
        return -1;
    }

    c = tolower(c);
    switch (c) {
        case 'w':
            return 1; // up
        case 's':
            return -1; // down
        case 'a':
            return -DEGREE_INCREMENT; // left
        case 'd':
            return DEGREE_INCREMENT; // right
        case 'q':
            return -2; // quit
        default:
            return -1; // invalid key
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    tcgetattr(uart_fd, &oldt);
    cfmakeraw(&newt);
    tcsetattr(uart_fd, TCSANOW, &newt);

    servo_pan = servo_tilt = SERVO_NEUTRAL_PWM;
    servo_pwm_resolution = pigpio_get_pwmres();

    if (servo_pwm_resolution < 16) {
        fprintf(stderr, "Warning: Using PWM resolution of %d instead of 16\n", servo_pwm_resolution);
    }

    gpioSetMode(GPIO_MODE_BCM);
    gpioSetPWMfunction(GPIO_NUM_17, 0, 0);
    gpioSetPWMfunction(GPIO_NUM_18, 0, 0);

    while (1) {
        int key = read_key();
        if (key == -1) {
            continue;
        }

        if (key == -2) {
            break;
        }

        int new_pan = servo_pan + key * DEGREE_INCREMENT;
        if (new_pan < 0 || new_pan > 180) {
            fprintf(stderr, "Invalid angle: %d\n", new_pan);
            continue;
        }

        set_servo(GPIO_NUM_17, SERVO_MIN_PWM + new_pan * SERVO_DEGREE_PER_PWM);
        servo_pan = new_pan;
        usleep(DELAY_MS * 1000);

        new_tilt = servo_tilt + key * DEGREE_INCREMENT;
        if (new_tilt < 0 || new_tilt > 180) {
            fprintf(stderr, "Invalid angle: %d\n", new_tilt);
            continue;
        }

        set_servo(GPIO_NUM_18, SERVO_MIN_PWM + new_tilt * SERVO_DEGREE_PER_PWM);
        servo_tilt = new_tilt;
        usleep(DELAY_MS * 1000);
    }

    gpioTerm(0);
    return 0;
}

