#define I2C_BUS 1
#define I2C_ADDR 0x3C

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define FONT_WIDTH 5
#define FONT_HEIGHT 7

typedef struct {
    unsigned char data[FONT_HEIGHT];
    unsigned char space;
} font_t;

font_t font[] = {
    {
        {0x00, 0x00, 0x07, 0x00, 0x00, 0x00, 0x00, 0x00},
        '0'
    },
    {
        {0x00, 0x14, 0x0f, 0x00, 0x00, 0x00, 0x00, 0x00},
        '1'
    },
    // Add more digits and other characters as needed
};

void i2c_write(int bus, int addr, const unsigned char *data, int len) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioI2cInit(bus, addr) < 0) {
        fprintf(stderr, "Failed to initialize I2C on bus %d\n", bus);
        exit(1);
    }

    int ret = gpioI2cWriteRead(bus, addr, data, len, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "I2C write error on bus %d\n", bus);
        exit(1);
    }

    gpioTerminate();
}

void draw_string(unsigned char *buf, int x, int y, const char *str) {
    for (int i = 0; *str != '\0'; ++i, ++str) {
        font_t *font_ptr = &font[*str - '0'];
        for (int j = 0; j < FONT_HEIGHT; ++j) {
            int pos = (y + j) * SCREEN_WIDTH + x;
            for (int k = 0; k < FONT_WIDTH; ++k) {
                if (font_ptr->data[j] & (1 << (FONT_WIDTH - k - 1))) {
                    buf[pos + k] = 1;
                }
            }
        }
        x += FONT_WIDTH;
    }
}

void update_display(unsigned char *buf) {
    unsigned char data[SCREEN_WIDTH];
    for (int i = 0; i < SCREEN_WIDTH; ++i) {
