#define SENSOR_GPIO 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27

static int gpio_fd, i2c_fd;
static unsigned long long total_volume = 0;
static unsigned long long current_volume = 0;
static unsigned long long last_update = 0;

void i2c_write_data(unsigned char *data, int len) {
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, data, len) != len) {
        perror("Failed to write data to I2C device");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_data(unsigned char *data, int len) {
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read data from I2C device");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    if (wiringPiSetup() == -1) {
        perror("Failed to initialize wiringPi");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpioOpen(SENSOR_GPIO, GPIOF_IN, 0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", LCD_I2C_BUS);

    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        exit(EXIT_FAILURE);
    }
}

void display_data(unsigned long long current_volume, unsigned long long total_volume) {
    unsigned char data[16];

    snprintf(data, sizeof(data), "Flow: %llu L/min  Vol: %llu L", current_volume, total_volume);
    i2c_write_data(data, strlen(data));
}

void handle_signal(int sig) {
    close(gpio_fd);
    close(i2c_fd);
    gpioTerm();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();

    struct timespec ts = {1, 0};
    while (1) {
        unsigned long long current_time = time(NULL);
        unsigned long long elapsed_time = current_time - last_update;

        if (elapsed_time >= 1000000000) {
            display_data(current_volume, total_volume);
            last_update = current_time;
        }

        if (elapsed_time >= 1000000) {
            unsigned long long edge_count = gpioRead(SENSOR_GPIO);
            current_volume = (edge_count - total_volume) * 1000 / 450;
            total_volume += current_volume;
            printf("Flow: %llu L/min  Vol: %llu L\n", current_volume, total_volume);
            last_update = current_time;
        }

        nanosleep(&ts, NULL);
    }

    return 0;
}

