code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <spidev.h>

#define LCD_ADDR 0x27
#define LCD_BUS 1
#define ANEMO_GPIO 17
#define ADC_CS 0
#define ADC_MODE 0
#define ADC_SPEED 1000000
#define SAMPLE_INTERVAL 500
#define ADC_MIN 0
#define ADC_MAX 1023
#define DEG_PER_ADC_COUNT (360.0 / (ADC_MAX - ADC_MIN))

static int lcd_fd, spi_fd, i2c_fd;
static char lcd_buf[16];
static struct spi_ioc_transfer spi_xfer[1];
static struct i2c_rdwr_ioctl_data i2c_xfer[2];

void lcd_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (bbI2COpen(LCD_BUS, LCD_ADDR, 0, &i2c_fd, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus for LCD\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ANEMO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for anemometer\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(ANEMO_GPIO, AlertFunc, NULL) < 0) {
        fprintf(stderr, "Failed to set rising edge interrupt for anemometer\n");
        exit(EXIT_FAILURE);
    }

    if (spiOpen(0, &spi_fd, SPICLOCK_1000000) < 0) {
        fprintf(stderr, "Failed to open SPI bus for ADC\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ADC_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for ADC chip select\n");
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(ADC_CS, 1) < 0) {
        fprintf(stderr, "Failed to write to GPIO for ADC chip select\n");
        exit(EXIT_FAILURE);
    }

    memset(lcd_buf, ' ', sizeof(lcd_buf));
    lcd_puts(0, "Wind Speed & Direction");
    lcd_goto(1, 0);
    lcd_puts("   ---     ---");

    signal(SIGINT, graceful_shutdown);
    signal(SIGTERM, graceful_shutdown);
}

void lcd_puts(int row, const char *str) {
    if (row < 0 || row > 1) {
        fprintf(stderr, "Invalid row number\n");
        return;
    }

    if (i2c_fd < 0) {
        fprintf(stderr, "LCD not initialized\n");
        return;
    }

    i2c_xfer[0].addr = LCD_ADDR;
    i2c_xfer[0].flags = 0;
    i2c_xfer[0].len = strlen(str);
    i2c_xfer[0].buf = (char *)str;
    i2c_xfer[1].addr = LCD_ADDR;
    i2c_xfer[1].flags = I2C_M_RD;
    i2c_xfer[1].len = 16;
    i2c_xfer[1].buf = lcd_buf;

    if (i2c_rdwr(i2c_fd, i2c_xfer, 2) < 0) {
        fprintf(stderr, "Failed to write to LCD\n");
    }
}

void lcd_goto(int row, int col) {
    if (row < 0 || row > 1 || col < 0 || col > 15) {
        fprintf(stderr, "Invalid row or column number\n");
        return;
    }

    lcd_buf[col] = ' ';
    lcd_buf[col + 16] = ' ';

    if (i2c_fd < 0) {
        fprintf(stderr, "LCD not initialized\n");
        return;
    }

    i2c_xfer[0].addr = LCD_ADDR;
    i2c_xfer[0].flags = 0;
    i2c_xfer[0].len = 1;
    i2c_xfer[0].buf = &row;
    i2c_xfer[1].addr = LCD_ADDR;
    i2c_xfer[1].flags = I2C_M_RD;
    i2c_xfer[1].len = 16;
    i2c_xfer[1].buf = lcd_buf;

    if (i2c_rdwr(i2c_fd, i2c_xfer, 2) < 0) {
        fprintf(stderr, "Failed to write to LCD\n");
    }
}

void anemometer_interrupt(int gpio, uint32_t event) {
    static uint32_t last_pulse_time = 0;
    static uint32_t pulse_count = 0;
    static double wind_speed = 0.0;

    if (event != PI_EDGE_RISING) {
        return;
    }

    uint32_t current_time = pigpio_time_ns();
    double elapsed_time = (current_time - last_pulse_time) / 1e6;

    if (elapsed_time > SAMPLE_INTERVAL) {
        wind_speed += pulse_count * 0.5;
        pulse_count = 0;
        last_pulse_time = current_time;

        lcd_goto(1, 0);
        snprintf(lcd_buf + 1, 6, "%.1f m/s", wind_speed);
    }

    pulse_count++;
}

void adc_read(int16_t *adc_value) {
    if (spi_fd < 0) {
        fprintf(stderr, "ADC not initialized\n");
        *adc_value = -1;
        return;
    }

    gpioWrite(ADC_CS, 0);

    spi_xfer[0].tx_buf = (unsigned char *)"00000000";
    spi_xfer[0].rx_buf = (unsigned char *)adc_value;
    spi_xfer[0].bits_per_word = 8;
    spi_xfer[0].delay_usecs = 0;
    spi_xfer[0].length = 1;

    if (spiXfer(spi_fd, spi_xfer, 1) != 1) {
        fprintf(stderr, "Failed to read from ADC\n");
        *adc_value = -1;
    }

    gpioWrite(ADC_CS, 1);
}

void wind_vane_read(double *wind_direction) {
    int16_t adc_value;

    if (adc_read(&adc_value) < 0) {
        fprintf(stderr, "Failed to read from ADC\n");
        *wind_direction = -1.0;
        return;
    }

    if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
        fprintf(stderr, "ADC reading is stuck at minimum or maximum\n");
        *wind_direction = -1.0;
        return;
    }

    *wind_direction = DEG_PER_ADC_COUNT * (adc_value - ADC_MIN);
}

void graceful_shutdown(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (gpioTerm() < 0) {
        fprintf(stderr, "Failed to terminate pigpio library\n");
    }

    exit(signum);
}

int main() {
    lcd_init();

    double wind_speed = 0.0;
    double wind_direction = 0.0;

    while (1) {
        wind_vane_read(&wind_direction);
        lcd_goto(1, 7);
        snprintf(lcd_buf + 11, 6, "%.0f deg", wind_direction);
        usleep(500000);
    }

    return 0;
}

