void AlertFunc(int gpio, uint32_t events) {
    static uint32_t last_pulse_time = 0;
    static uint32_t pulse_count = 0;

    if (events & PI_EDGE_RISING_EDGE) {
        uint32_t current_time = gpioGetOverrun(gpio);
