#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define ROWS 8
#define COLS 8
#define DELAY_US 800
#define WAVE_STEP 1
#define LEFT_TO_RIGHT 1
#define RIGHT_TO_LEFT 0

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, lines, flags, NULL);
}

static void display_wave(int direction, int *wave) {
    for (int row = 0; row < ROWS; row++) {
        for (int col = 0; col < COLS; col++) {
            int index = (direction == LEFT_TO_RIGHT) ? (col + wave[row]) : (COLS - col - 1 - wave[row]);
            if (index >= 0 && index < COLS) {
                gpiod_line_set_value(lines[row], wave[row] == index);
            }
        }
        usleep(DELAY_US * 1000);
        for (int col = 0; col < COLS; col++) {
            gpiod_line_set_value(lines[row], 0);
        }
    }
}

int main(void) {
    struct gpiod_chip *chip;
    const char *const lines[ROWS] = {"gpiochip0\0", "gpiochip0\0", "gpiochip0\0", "gpiochip0\0",
                                     "gpiochip0\0", "gpiochip0\0", "gpiochip0\0", "gpiochip0\0"};
    const char *const columns[COLS] = {"gpiochip1\0", "gpiochip1\0", "gpiochip1\0", "gpiochip1\0",
                                       "gpiochip1\0", "gpiochip1\0", "gpiochip1\0", "gpiochip1\0"};
    int wave[ROWS];
    int direction = LEFT_TO_RIGHT;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        return 1;
    }

    if (gpiod_line_request_array(chip, lines, ROWS, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_array(chip, columns, COLS, GPIOD_LINE_REQUEST_OUTPUT) < 0) {
        fprintf(stderr, "Failed to request columns\n");
        gpiod_chip_release_lines(chip, lines, ROWS);
        gpiod_chip_close(chip);
        return 1;
    }

    for (int row = 0; row < ROWS; row++) {
        wave[row] = row;
    }

    while (1) {
        display_wave(direction, wave);

        if (direction == LEFT_TO_RIGHT) {
            for (int row = 0; row < ROWS; row++) {
                if (wave[row] == COLS - 1) {
                    wave[row] = -1;
                }
                wave[row]++;
            }
        } else {
            for (int row = ROWS - 1; row >= 0; row--) {
                if (wave[row] == 0) {
                    wave[row] = COLS;
                }
                wave[row]--;
            }
        }

        if (direction == LEFT_TO_RIGHT && wave[ROWS - 1] == COLS - 1) {
            direction = RIGHT_TO_LEFT;
        } else if (direction == RIGHT_TO_LEFT && wave[0] == 0) {
            direction = LEFT_TO_RIGHT;
        }

        usleep(DELAY_US * 1000);
    }

    gpiod_line_release(columns[0]);
    gpiod_line_release(columns[1]);
    gpiod_line_release(columns[2]);
    gpiod_line_release(columns[3]);
    gpiod_line_release(columns[4]);
    gpiod_line_release(columns[5]);
    gpiod_line_release(columns[6]);
    gpiod_line_release(columns[7]);

    gpiod_chip_release_lines(chip, lines, ROWS);
    gpiod_chip_close(chip);

    return 0;
}

