int init_sensor() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }

    if (gpioSetMode(I2C_BUS, PI_MODE_INOUT) < 0) {
        perror("Failed to set I2C bus mode");
        return -1;
    }

    // Stub for proprietary firmware download
    // Refer to the datasheet and ULD API for the actual sequence
    printf("%s: Stubbed firmware download\n", TAG);

    // I2C address setup
    if (i2c_setup(I2C_BUS, VL53L3CX_ADDR) < 0) {
        perror("Failed to setup I2C communication");
        return -1;
    }

    // Sensor model ID verification
    uint8_t model_id;
    if (i2cReadRegister16(I2C_BUS, VL53L3CX_ADDR, 0x01, &model_id, 1) != 1) {
        perror("Failed to read sensor model ID");
        return -1;
    }

    if (model_id != 0x64) {
        printf("%s: Incorrect sensor model ID (expected 0x64, got 0x%02X)\n", TAG, model_id);
        return -1;
    }

    return 0;
}

