        time_t rawtime;
        struct tm *timeinfo;
        char time_str[32];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);

        printf("%s Distance: %d mm\n", time_str, *distance);
    }
}

