#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX_ADDR 0x4C
#define REG_DISTANCE 0x0D

static char *logfile = "depth_log.csv";

void log_distance(int distance) {
    FILE *fp = fopen(logfile, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        perror("Failed to write to log file");
    }
    fclose(fp);
}

int i2c_read_16(int bus, int addr, int reg) {
    int data[2];
    if (i2c_read_register16_rep(bus, addr, reg, data, 2) < 0) {
        perror("Failed to read from I2C");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

int main() {
    int ret, i2c_fd, pi_fd;
    if ((pi_fd = pigpio_init()) < 0) {
        perror("Failed to initialize pigpio");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }

    if ((i2c_fd = pigpio_i2c_open_bus(pi_fd, I2C_BUS)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (pigpio_i2c_set_slave(i2c_fd, MLX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    int distance;
    struct stat st;
    if (stat(logfile, &st) != 0 || S_ISREG(st.st_mode) == 0) {
        printf("Creating log file\n");
        log_distance(-1);
    }

    while (1) {
        if ((ret = i2c_read_16(i2c_fd, MLX_ADDR, REG_DISTANCE)) < 0) {
            log_distance(-1);
            usleep(100000);
            continue;
        }
        log_distance(ret);
        usleep(100000);
    }

    pigpio_i2c_close(i2c_fd);
    gpioTerm();
    pigpio_terminate();
    return 0;
}

