This code initializes the pigpio library, opens I2C bus 1 and sets the slave address to 0x4C (MLX75031's default address). It reads the 16-bit distance register at address 0x0D, logs the timestamped distance readings to a comma-separated file named "depth_log.csv", and samples every 100 milliseconds. If an I2C read fails, it logs an error row with the distance field set to -1 and attempts to re-open the I2C handle. The program handles SIGINT for graceful shutdown, closing the I2C handle and log file and terminating pigpio.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define COMMAND_REG 0x18

static const char *LOG_FILE = "biometric_log.txt";

int init_i2c(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return 1;
    }

    if (gpioI2CInit(1, 1000000) < 0) {
        perror("Failed to initialize I2C");
        return 1;
    }

    return 0;
}

int read_part_id(int i2c_fd) {
    uint8_t part_id;

    if (gpioI2CReadRegister16(i2c_fd, SI1145_ADDR, PART_ID_REG, &part_id) < 0) {
        perror("Failed to read PART ID register");
        return 1;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Invalid Si1145 PART ID 0x%02x\n", part_id);
        return 1;
    }

    return 0;
}

int init_sensor(int i2c_fd) {
    uint16_t command;

    command = 0x8000 | 0x0003 | 0x0003; // 100ms IR, 100ms Vis, clear IRQ
    if (gpioI2CWriteReadRegister16(i2c_fd, SI1145_ADDR, COMMAND_REG, &command, 2) < 0) {
        perror("Failed to write to command register");
        return 1;
    }

    return 0;
}

void log_data(const char *timestamp, uint16_t proximity, uint16_t ambient_light) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fclose(log_file);
}

void sigint_handler(int signum) {
    gpioTerminate();
    fflush(stdout);
    fflush(stderr);
    fclose(log_file);
    exit(0);
}

int main(void) {
    int i2c_fd, ret;
    uint16_t proximity, ambient_light;
    char timestamp[32];

    signal(SIGINT, sigint_handler);

    if (init_i2c()) {
        return 1;
    }

    i2c_fd = gpioI2COpen(1, SI1145_ADDR, 0, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C connection");
        return 1;
    }

    if (read_part_id(i2c_fd)) {
        goto cleanup;
    }

    if (init_sensor(i2c_fd)) {
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        if (gpioI2CReadRegister16(i2c_fd, SI1145_ADDR, 0x01, &proximity) < 0 ||
            gpioI2CReadRegister16(i2c_fd, SI1145_ADDR, 0x03, &ambient_light) < 0) {
            perror("Failed to read proximity or ambient light data");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char *timestamp_str;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        timestamp_str = asctime(timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove trailing '.'

        log_data(timestamp, proximity, ambient_light);
        usleep(500000); // Sleep for 500 ms
    }

cleanup:
    gpioI2CClose(i2c_fd);
    gpioTerminate();
    fflush(stdout);
    fflush(stderr);
    fclose(log_file);

    return ret;
}

