        if (gpioI2CReadRegister16(i2c_fd, SI1145_ADDR, 0x01, &proximity) < 0 ||
            gpioI2CReadRegister16(i2c_fd, SI1145_ADDR, 0x03, &ambient_light) < 0) {
            perror("Failed to read proximity or ambient light data");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char *timestamp_str;

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        timestamp_str = asctime(timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);
        timestamp[strlen(timestamp) - 1] = '\0'; // Remove trailing '.'

        log_data(timestamp, proximity, ambient_light);
        usleep(500000); // Sleep for 500 ms
    }

cleanup:
    gpioI2CClose(i2c_fd);
    gpioTerminate();
    fflush(stdout);
    fflush(stderr);
    fclose(log_file);

    return ret;
}
