#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS_FORCE 0x06
#define ALS_FORCE 0x07
#define PS_DATA_REG 0x18
#define PS_DATA_LEN 2
#define ALS_DATA_REG 0x22
#define ALS_DATA_LEN 2
#define LOG_FILE "biometric_data.log"

int i2c_write_reg(int bus, uint8_t addr, uint16_t reg, uint16_t value) {
    if (gpioI2cWrite(bus, addr, &reg, 2) != 2) {
        perror("i2cWrite error");
        return -1;
    }
    if (gpioI2cWrite(bus, addr, (uint8_t*)&value, 2) != 2) {
        perror("i2cWrite error");
        return -1;
    }
    return 0;
}

int i2c_read_reg(int bus, uint8_t addr, uint16_t reg, uint16_t* data) {
    if (gpioI2cRead(bus, addr, (uint8_t*)&reg, 1) != 1) {
        perror("i2cRead error");
        return -1;
    }
    if (gpioI2cRead(bus, addr, (uint8_t*)data, 2) != 2) {
        perror("i2cRead error");
        return -1;
    }
    return 0;
}

void sigint_handler(int sig) {
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_fd = -1;
    FILE* log_file = NULL;
    uint16_t part_id;
    uint16_t data_ps[PS_DATA_LEN];
    uint16_t data_als[ALS_DATA_LEN];

    if (gpioInitialise() < 0) {
        perror("gpioInitialise error");
        return 1;
    }

    i2c_fd = gpioOpen(I2C_BUS, SI1145_ADDR);
    if (i2c_fd < 0) {
        perror("gpioOpen error");
        goto cleanup;
    }

    if (i2c_write_reg(i2c_fd, SI1145_ADDR, PART_ID_REG, 0) < 0) {
        goto cleanup;
    }

    if (gpioI2cRead(i2c_fd, SI1145_ADDR, (uint8_t*)&part_id, 1) != 1) {
        perror("i2cRead error");
        goto cleanup;
    }

    if (part_id != 0x45) {
        fprintf(stderr, "Invalid part ID: 0x%04x\n", part_id);
        goto cleanup;
    }

    if (i2c_write_reg(i2c_fd, SI1145_ADDR, HW_KEY_REG, 0x17) < 0) {
        goto cleanup;
    }

    if (i2c_write_reg(i2c_fd, SI1145_ADDR, CH_LIST_REG, 0x03) < 0) {
        goto cleanup;
    }

    if (i2c_write_reg(i2c_fd, SI1145_ADDR, COMMAND_REG, PS_FORCE | ALS_FORCE) < 0) {
        goto cleanup;
    }

    sleep(1); // Wait for the sensor to complete the measurements

    if (i2c_read_reg(i2c_fd, SI1145_ADDR, PS_DATA_REG, data_ps) < 0) {
        goto cleanup;
    }

    if (i2c_read_reg(i2c_fd, SI1145_ADDR, ALS_DATA_REG, data_als) < 0) {
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen error");
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        time_t now = time(NULL);
        struct tm* tm_now = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

        fprintf(log_file, "%s,%d,%d\n", timestamp, data_ps[0], data_als[0]);
        fflush(log_file);

        sleep(1);
    }

cleanup:
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) gpioTerm(i2c_fd);
    gpioTerminate();

    return 0;
}

