code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman map_file;
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define VOLTAGE_DIVIDER_R1 1000
#define VOLTAGE_DIVIDER_R2 2000
#define DISTANCE_MIN 2
#define DISTANCE_MAX 400
#define RETRY_DELAY_MS 30
#define POLLING_INTERVAL_MS 60000
#define REMINDER_DISTANCE 15
#define LOG_FILE "distance_log.txt"

struct gpiod_line *trigger, *echo;
FILE *log_file;

void log_timestamped(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);
    fprintf(log_file, "%s: %s\n", timestamp, message);
}

void log_error(const char *message) {
    log_timestamped(message);
    fprintf(log_file, " (Error: %s)\n", strerror(errno));
}

int read_echo_voltage() {
    int echo_fd = open("/dev/gpiochip0", O_RDONLY);
    if (echo_fd < 0) {
        log_error("Failed to open gpiochip0");
        return -1;
    }

    uint32_t echo_reg = gpiod_get_rawdata(echo);
    close(echo_fd);

    double echo_voltage = (echo_reg * VOLTAGE_DIVIDER_R2) / (VOLTAGE_DIVIDER_R1 + VOLTAGE_DIVIDER_R2);
    return (int)(echo_voltage * 3.3 * 1000);
}

void trigger_pulse() {
    gpiod_line_set_value(trigger, 1);
    usleep(10000);
    gpiod_line_set_value(trigger, 0);
}

uint32_t measure_distance() {
    int echo_voltage = read_echo_voltage();
    if (echo_voltage < 0) {
        log_error("Failed to read echo voltage");
        return 0;
    }

    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        if (gpiod_line_get_value(echo) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            uint32_t elapsed_ns = (end.tv_sec - start.tv_sec) * 1000000000 + end.tv_nsec - start.tv_nsec;
            double pulse_seconds = elapsed_ns / 1e9;

            if (pulse_seconds > 0 && pulse_seconds < 50000) {
                double distance_cm = (pulse_seconds * 34300) / 2;
                if (distance_cm >= DISTANCE_MIN && distance_cm <= DISTANCE_MAX) {
                    return distance_cm;
                }
            }
        }

        if (elapsed_ns > 30000000) {
            log_error("Echo never rose or stuck high");
            return 0;
        }

        usleep(RETRY_DELAY_MS * 1000);
    }

    return 0; // Unreachable
}

void log_and_remind(uint32_t distance_cm) {
    if (distance_cm < REMINDER_DISTANCE) {
        log_timestamped("Time to water the plant!");
    }
    log_timestamped(distance_cm ? (char*)malloc(16 + 6 + 1 + 3 * sizeof(uint32_t)) : "Sensor absent");
    fprintf(log_file, "%u cm", distance_cm);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (trigger) {
        gpiod_line_release(trigger);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        return 1;
    }

    trigger = gpiod_claim_line_raw("gpiochip0", TRIGGER_GPIO);
    if (!trigger) {
        log_error("Failed to claim trigger GPIO");
        return 1;
    }

    echo = gpiod_claim_line_raw("gpiochip0", ECHO_GPIO);
    if (!echo) {
        log_error("Failed to claim echo GPIO");
        return 1;
    }

    gpiod_line_set_direction_output(trigger, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_set_direction_input(echo, GPIOD_LINE_ACTIVE_HIGH);

    while (1) {
        trigger_pulse();
        uint32_t distance_cm = measure_distance();
        log_and_remind(distance_cm);
        sleep(POLLING_INTERVAL_MS / 1000);
    }

    return 0;
}

