    log_timestamped(distance_cm ? (char*)malloc(16 + 6 + 1 + 3 * sizeof(uint32_t)) : "Sensor absent");
    fprintf(log_file, "%u cm", distance_cm);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (trigger) {
        gpiod_line_release(trigger);
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        return 1;
    }

    trigger = gpiod_claim_line_raw("gpiochip0", TRIGGER_GPIO);
    if (!trigger) {
        log_error("Failed to claim trigger GPIO");
        return 1;
    }

    echo = gpiod_claim_line_raw("gpiochip0", ECHO_GPIO);
    if (!echo) {
        log_error("Failed to claim echo GPIO");
        return 1;
    }

    gpiod_line_set_direction_output(trigger, GPIOD_LINE_ACTIVE_HIGH);
    gpiod_line_set_direction_input(echo, GPIOD_LINE_ACTIVE_HIGH);

    while (1) {
        trigger_pulse();
        uint32_t distance_cm = measure_distance();
        log_and_remind(distance_cm);
        sleep(POLLING_INTERVAL_MS / 1000);
    }

    return 0;
}
