#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x5A
#define MEAS_RATE0 0x08
#define COMMAND 0x47
#define PS_DATA0 0x24
#define PS_DATA1 0x25
#define PART_ID 0x00
#define BPM_SCALE 5

static gpiod_line_request_lines(1, "gpiochip0", GPIO_DIRECTION_OUT, NULL);
static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int read_part_id(int fd) {
    int ret;
    uint8_t id;

    ret = i2c_smbus_read_byte_data(fd, PART_ID);
    if (ret < 0) {
        perror("Failed to read PART_ID");
        return -1;
    }

    id = (uint8_t)ret;
    if (id != 0x11) {
        fprintf(stderr, "Invalid Si1182 part ID: 0x%02X\n", id);
        return -1;
    }

    return 0;
}

int write_reg(int fd, uint8_t reg, uint8_t value) {
    int ret;
    uint8_t data[2];

    data[0] = reg;
    data[1] = value;

    ret = i2c_master_send(fd, data, 2);
    if (ret != 2) {
        perror("Failed to write register");
        return -1;
    }

    return 0;
}

int read_reg(int fd, uint8_t reg, uint16_t *data) {
    int ret;

    ret = i2c_smbus_read_word_data(fd, reg);
    if (ret < 0) {
        perror("Failed to read register");
        return -1;
    }

    *data = (uint16_t)ret;
    return 0;
}

uint16_t combine_le16(uint8_t *buf) {
    return (uint16_t)(((uint16_t)buf[0] << 8) | buf[1]);
}

double placeholder_bpm(uint16_t ps_data) {
    double bpm = 60.0 * (double)ps_data / 65535;
    return bpm * BPM_SCALE;
}

void log_sample(const char *timestamp, double bpm) {
    static FILE *csv = NULL;

    if (!csv) {
        csv = fopen("heartrate.csv", "w");
        if (!csv) {
            perror("Failed to open CSV file");
            exit(EXIT_FAILURE);
        }
    }

    fprintf(csv, "%s,%f\n", timestamp, bpm);
    fflush(csv);
}

int main() {
    int i2c_fd, ret;
    uint16_t ps_data[2];
    char timestamp[32];

    gpiod_line_set_value_cansleep(gpio_get_line(0), 1);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    ret = read_part_id(i2c_fd);
    if (ret < 0) {
        exit(EXIT_FAILURE);
    }

    ret = write_reg(i2c_fd, MEAS_RATE0, 0x01);
    if (ret < 0) {
        perror("Failed to set measurement rate");
        exit(EXIT_FAILURE);
    }

    ret = write_reg(i2c_fd, COMMAND, 0x01);
    if (ret < 0) {
        perror("Failed to reset/start sensor");
        exit(EXIT_FAILURE);
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02dT%02d:%02d:%02d.%06ld",
             tv.tv_year, tv.tv_mon, tv.tv_mday, tv.tv_hour, tv.tv_min, tv.tv_sec, tv.tv_usec);

    while (running) {
        ret = read_reg(i2c_fd, PS_DATA0, &ps_data[0]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read PS_DATA0\n");
            continue;
        }

        ret = read_reg(i2c_fd, PS_DATA1, &ps_data[1]);
        if (ret < 0) {
            fprintf(stderr, "Failed to read PS_DATA1\n");
            continue;
        }

        double bpm = placeholder_bpm(combine_le16(ps_data));
        log_sample(timestamp, bpm);

        usleep(100000);
        gettimeofday(&tv, NULL);
        snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02dT%02d:%02d:%02d.%06ld",
                 tv.tv_year, tv.tv_mon, tv.tv_mday, tv.tv_hour, tv.tv_min, tv.tv_sec, tv.tv_usec);
    }

    close(i2c_fd);
    fclose(csv);
    gpiod_line_release_request_line(gpio_get_line(0));

    return 0;
}

