#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x29
#define GPIO_TRIGGER 17

#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

#define TIMEOUT_US 100000

void log_distance(time_t timestamp, uint16_t distance_mm) {
    FILE *log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%lu,%u\n", timestamp, distance_mm);
    fclose(log_file);
}

int main() {
    int i2c_fd, gpio_fd;
    uint8_t data[15];
    time_t timestamp;
    struct timespec timeout;
    int ret;

    if ((gpio_fd = pigpio_init()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioInitialise(gpio_fd) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(gpio_fd, GPIO_TRIGGER, GPIO_IN) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    if (gpioSetPullUp(gpio_fd, GPIO_TRIGGER) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up\n");
        return 1;
    }

    if ((i2c_fd = pigpio_i2c_open(gpio_fd, I2C_BUS, SENSOR_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C connection\n");
        return 1;
    }

    if (i2cWriteReadRegister16(i2c_fd, 0x80, 0x00, &ret) < 0) {
        fprintf(stderr, "Failed to write to sensor\n");
        return 1;
    }

    if (ret != 0xAA) {
        fprintf(stderr, "Sensor not found at 0x29\n");
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &timestamp);

