#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x6A
#define GPIO_LED 17

int i2c_file;
struct i2c_rdwr_ioctl_data i2c_data[2];
uint8_t read_buf[2];
uint16_t distance;

void i2c_read(uint8_t reg) {
    i2c_data[0].addr = SENSOR_ADDR << 1;
    i2c_data[0].flags = 0;
    i2c_data[0].len = 1;
    i2c_data[0].buf = &reg;

    i2c_data[1].addr = SENSOR_ADDR << 1;
    i2c_data[1].flags = I2C_M_RD;
    i2c_data[1].len = 2;
    i2c_data[1].buf = read_buf;

    if (ioctl(i2c_file, I2C_RDWR, i2c_data) < 0) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
}

void log_distance(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S.%f", timeinfo);

    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s, %d\n", time_str, distance);
    fclose(log_file);
}

void gpio_setup(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
}

void gpio_control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

void i2c_setup(void) {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", I2C_BUS);

    i2c_file = open(filename, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        exit(EXIT_FAILURE);
    }
}

void cleanup(void) {
    if (i2c_file >= 0) {
        if (ioctl(i2c_file, I2C_DISABLE) < 0) {
            perror("Failed to release I2C bus");
        }
        close(i2c_file);
    }

    gpioTerminate();
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_setup();
    gpio_setup();

    while (1) {
        i2c_read(0x00);
        distance = (read_buf[0] << 8) | read_buf[1];

        if (distance < 20) {
            gpio_control_led(1);
        } else {
            gpio_control_led(0);
        }

        log_distance();
        usleep(100000);
    }

    cleanup();
    return 0;
}

