    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s, %d\n", time_str, distance);
    fclose(log_file);
}

void gpio_setup(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
}

void gpio_control_led(int state) {
    gpioWrite(GPIO_LED, state);
}

void i2c_setup(void) {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", I2C_BUS);

    i2c_file = open(filename, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        exit(EXIT_FAILURE);
    }
}

void cleanup(void) {
    if (i2c_file >= 0) {
        if (ioctl(i2c_file, I2C_DISABLE) < 0) {
            perror("Failed to release I2C bus");
        }
        close(i2c_file);
    }

    gpioTerminate();
}

void signal_handler(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_setup();
    gpio_setup();

    while (1) {
        i2c_read(0x00);
        distance = (read_buf[0] << 8) | read_buf[1];

        if (distance < 20) {
            gpio_control_led(1);
        } else {
            gpio_control_led(0);
        }

        log_distance();
        usleep(100000);
    }

    cleanup();
    return 0;
}
