#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100

int main(int argc, char *argv[]) {
    if (argc > 2) {
        fprintf(stderr, "Usage: %s [threshold]\n", argv[0]);
        return 1;
    }

    int threshold = DEFAULT_THRESHOLD;
    if (argc == 2) {
        threshold = atoi(argv[1]);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);

    int i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 1000000);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        gpioTerm();
        return 1;
    }

    sigset_t sigint_set;
    sigemptyset(&sigint_set);
    sigaddset(&sigint_set, SIGINT);
    sigprocmask(SIG_SETMASK, &sigint_set, NULL);

    FILE *log_file = fopen("tof_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        pigpio_i2c_close(i2c_fd);
        gpioTerm();
        return 1;
    }

    time_t rawtime;
    struct tm *time_info;
    while (1) {
        if (pigpio_i2c_writeRead(i2c_fd, &WHO_AM_I, 1, NULL, 0) != 1) {
            perror("pigpio_i2c_writeRead");
            fclose(log_file);
            pigpio_i2c_close(i2c_fd);
            gpioTerm();
            return 1;
        }

        int who_am_i = (int)igpio_read(0);
        if (who_am_i != 0x01) {
            fprintf(stderr, "Invalid WHO_AM_I response: 0x%02X\n", who_am_i);
            continue;
        }

        uint16_t distance;
        if (pigpio_i2c_writeRead(i2c_fd, 0x00, 1, (char *)&distance, 2) != 2) {
            perror("pigpio_i2c_writeRead");
            fclose(log_file);
            pigpio_i2c_close(i2c_fd);
            gpioTerm();
            return 1;
        }

        rawtime = time(NULL);
        time_info = localtime(&rawtime);
        fprintf(log_file, "%02d:%02d:%02d.%03d : Distance = %d mm\n",
                time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                time_info->tm_msec, distance);

        if (distance < threshold) {
            gpioWrite(GPIO_LED, 1);
        }

        usleep(50000);
    }

    fclose(log_file);
    pigpio_i2c_close(i2c_fd);
    gpioTerm();
    return 0;
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Exiting...\n");
        exit(0);
    }
}

