#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x50
#define COMMAND_LEN 4
#define RESPONSE_LEN 15
#define DISTANCE_OFFSET 11

static int i2c_file;
static FILE *log_file;

void i2c_init() {
    const char *i2c_dev_name = "/dev/i2c-" I2C_BUS;
    if ((i2c_file = open(i2c_dev_name, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void log_init() {
    if ((log_file = fopen("intrusion_log.txt", "w+")) == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(const uint8_t *data, size_t len) {
    if (write(i2c_file, data, len) != len) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read(uint8_t *buf, size_t len) {
    return read(i2c_file, buf, len);
}

void i2c_close() {
    if (close(i2c_file) < 0) {
        perror("Failed to close I2C device");
    }
}

void log_close() {
    if (fclose(log_file) != 0) {
        perror("Failed to close log file");
    }
}

uint16_t process_response(const uint8_t *response) {
    if (response[0] != SENSOR_ADDR) {
        fprintf(stderr, "Invalid response header\n");
        return 0;
    }

    uint16_t distance = (response[DISTANCE_OFFSET] << 8) | response[DISTANCE_OFFSET + 1];
    return distance;
}

void sample_and_log(uint16_t *averaged_distance) {
    uint8_t command[COMMAND_LEN] = {SENSOR_ADDR, 0x0A, 0x00, 0x01};
    uint8_t response[RESPONSE_LEN];
    uint16_t distance;
    int i;
    uint16_t total_distance = 0;

    for (i = 0; i < 10; ++i) {
        i2c_write(command, COMMAND_LEN);
        usleep(10000);
        if (i2c_read(response, RESPONSE_LEN) != RESPONSE_LEN) {
            perror("Failed to read from I2C device");
            return;
        }

        distance = process_response(response);
        if (distance > 0) {
            total_distance += distance;
        }
    }

    *averaged_distance = total_distance / 10;

    if (*averaged_distance < 1000) {
        time_t rawtime;
        struct tm *timeinfo;
        char time_str[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s, %u mm\n", time_str, *averaged_distance);
    }
}

int main() {
    uint16_t averaged_distance;
    sigset_t sigint_mask;

    i2c_init();
    log_init();

    sigemptyset(&sigint_mask);
    sigaddset(&sigint_mask, SIGINT);
    if (pthread_sigmask(SIG_SETMASK, &sigint_mask, NULL) != 0) {
        perror("Failed to set signal mask");
        exit(EXIT_FAILURE);
    }

    while (1) {
        sample_and_log(&averaged_distance);
        usleep(100000);
    }

    i2c_close();
    log_close();
    return 0;
}

