#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L0X_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

static int i2c_fd;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int init_i2c() {
    i2c_fd = pigpio_i2c_open(I2C_BUS, VL53L0X_ADDR, 1000000);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VL53L0X_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    return 0;
}

int read_model_id() {
    uint8_t buf[2];
    if (pigpio_i2c_read_mem_into(i2c_fd, 0xC0, buf, 2) < 0) {
        perror("pigpio_i2c_read_mem_into");
        return -1;
    }

    if (memcmp(buf, (const void*)0xEE, 1) != 0) {
        fprintf(stderr, "Invalid model ID\n");
        return -1;
    }

    return 0;
}

uint16_t read_distance() {
    uint8_t buf[2];
    if (pigpio_i2c_read_mem_into(i2c_fd, RESULT_RANGE_STATUS, buf, 2) < 0) {
        fprintf(stderr, "pigpio_i2c_read_mem_into: reading distance\n");
    }

    uint16_t distance = (buf[0] << 8) | buf[1];
    return ntohs(distance);
}

void clear_interrupt() {
    if (pigpio_i2c_write_mem(i2c_fd, SYSTEM_INTERRUPT_CLEAR, 1) < 0) {
        perror("pigpio_i2c_write_mem");
    }
}

void single_shot_ranging() {
    if (pigpio_i2c_write_mem(i2c_fd, SYSRANGE_START, 1) < 0) {
        perror("pigpio_i2c_write_mem");
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    int timeout = 100;
    int poll_interval = 1000;
    int elapsed = 0;
    uint16_t distance;

    while (elapsed < timeout && running) {
        if (pigpio_i2c_read_mem_into(i2c_fd, RESULT_INTERRUPT_STATUS, &distance, 1) < 0) {
            fprintf(stderr, "pigpio_i2c_read_mem_into: polling interrupt\n");
        }

        if ((distance & 0x01) == 0x01) {
            distance = read_distance();
            now = time(NULL);
            printf("%04d-%02d-%02d %02d:%02d:%02d Distance: %d mm\n",
                   now, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, distance);
            clear_interrupt();
            break;
        }

        usleep(poll_interval * 1000);
        elapsed += poll_interval;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_i2c() < 0) {
        goto cleanup;
    }

    if (read_model_id() < 0) {
        goto cleanup;
    }

    while (running) {
        single_shot_ranging();
        usleep(500000);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    return 0;
}

