#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define SI1182_ADDR 0x39
#define SI1182_CONFIG_REG 0x18
#define SI1182_IRQ_STATUS_REG 0x25
#define SI1182_PROX_LSB_REG 0x2A
#define SI1182_PROX_MSB_REG 0x2B

int i2c_file;

void sigint_handler(int signum) {
    gpioTerminate();
    close(i2c_file);
    exit(0);
}

int init_i2c() {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", 1);
    if ((i2c_file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1182_ADDR << 1) < 0) {
        perror("Failed to acquire bus access");
        return -1;
    }

    return 0;
}

int init_sensor() {
    if (i2c_writeReg16(SI1182_ADDR, SI1182_CONFIG_REG, 0x01) < 0) {
        perror("Failed to write to CONFIG register");
        return -1;
    }

    return 0;
}

uint16_t read_proximity() {
    uint16_t value = 0;
    if (i2c_readReg16(SI1182_ADDR, SI1182_IRQ_STATUS_REG, &value) < 0) {
        perror("Failed to read IRQ status register");
        return 0;
    }

    if (!(value & 0x01)) {
        return 0;
    }

    if (i2c_readReg16(SI1182_ADDR, SI1182_PROX_LSB_REG, (uint8_t *)&value) < 0) {
        perror("Failed to read proximity LSB register");
        return 0;
    }

    if (i2c_readReg16(SI1182_ADDR, SI1182_PROX_MSB_REG, (uint8_t *)&value) < 0) {
        perror("Failed to read proximity MSB register");
        return 0;
    }

    return value;
}

int main() {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    if (init_sensor() < 0) {
        close(i2c_file);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint16_t proximity = read_proximity();
        if (proximity > 0) {
            printf("Proximity value: %u\n", proximity);
        }
        usleep(500000);
    }

    close(i2c_file);
    gpioTerminate();
    return 0;
}

int i2c_writeReg16(uint8_t addr, uint16_t reg, uint16_t value) {
    uint8_t data[3];
    data[0] = (reg >> 8) & 0xFF;
    data[1] = reg & 0xFF;
    data[2] = value & 0xFF;
    (void)write(i2c_file, data, 3);
    if (gpioPoll(gpioGetLastError()) < 0) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_readReg16(uint8_t addr, uint16_t reg, uint8_t *data) {
    uint8_t buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    (void)write(i2c_file, buf, 2);
    if (gpioPoll(gpioGetLastError()) < 0) {
        perror("I2C write error");
        return -1;
    }

    (void)read(i2c_file, data, 2);
    if (gpioPoll(gpioGetLastError()) < 0) {
        perror("I2C read error");
        return -1;
    }

    *data = (data[0] << 8) | data[1];
    return 0;
}

