#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define DEVICE_ADDR 0x4C
#define DISTANCE_REG 0x00
#define DISTANCE_FACTOR 0.125
#define SLEEP_MS 500

int main() {
    int i2c_fd;
    char buf[2];
    ssize_t bytes_read;
    unsigned short distance;

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, DEVICE_ADDR) < 0) {
        perror("Failed to set slave address");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_RDWR, i2c_smbus_read_i2c_block_data(DEVICE_ADDR, DISTANCE_REG, 2, buf)) < 0) {
        perror("Failed to read distance data");
        close(i2c_fd);
        return 1;
    }

    distance = (buf[0] << 8) | buf[1];
    printf("Distance: %.2f mm\n", DISTANCE_FACTOR * distance);

    signal(SIGINT, [](int sig) {
        close(i2c_fd);
        exit(0);
    });
    signal(SIGTERM, [](int sig) {
        close(i2c_fd);
        exit(0);
    });

    for (;;) {
        if (ioctl(i2c_fd, I2C_RDWR, i2c_smbus_read_i2c_block_data(DEVICE_ADDR, DISTANCE_REG, 2, buf)) < 0) {
            perror("Failed to read distance data");
            continue;
        }

        distance = (buf[0] << 8) | buf[1];
        printf("Distance: %.2f mm\n", DISTANCE_FACTOR * distance);
        nanosleep((const struct timespec[]){{SLEEP_MS * 1e6, 0}}, NULL);
    }

    close(i2c_fd);
    return 0;
}

