#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3101_ADDR 0x44
#define CHANNEL_0 0

int main() {
    int i2c_fd, ret;
    uint16_t distance, ambient_light, error_flags;
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;

    if ((i2c_fd = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, OPT3101_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = i2cReadRegister16_Rep(i2c_fd, 0x00, 0x03, &error_flags, 1);
        if (ret < 0) {
            perror("I2C read error");
            continue;
        }

        ret = i2cReadRegister16_Rep(i2c_fd, 0x04 + CHANNEL_0 * 4, 2, &distance, 1);
        if (ret < 0) {
            perror("I2C read error");
            continue;
        }

        ret = i2cReadRegister16_Rep(i2c_fd, 0x02 + CHANNEL_0 * 4, 1, &ambient_light, 1);
        if (ret < 0) {
            perror("I2C read error");
            continue;
        }

        printf("Channel 0 distance: %dmm, Ambient light: %d, Error flags: 0x%04x\n",
               distance, ambient_light, error_flags);
        usleep(500000);
    }

    gpioTerminate();
    close(i2c_fd);
    return 0;
}

int i2cReadRegister16_Rep(int i2c_fd, uint8_t reg, uint16_t len, uint16_t *data, int repeat) {
    int ret;
    uint8_t buf[2];

    for (int i = 0; i < repeat; ++i) {
        buf[0] = (reg >> 8) & 0xFF;
        buf[1] = reg & 0xFF;
        ret = write(i2c_fd, buf, 2);
        if (ret != 2) {
            return -1;
        }

        ret = read(i2c_fd, buf, 2);
        if (ret != 2) {
            return -1;
        }

        *data = (buf[0] << 8) | buf[1];
        if ((*data & 0xFF00) == (reg & 0xFF00)) {
            return 0;
        }
    }

    return -1;
}

