#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define RESISTOR_VALUE 1000
#define ECHO_PROTECTION_RESISTOR (RESISTOR_VALUE / (RESISTOR_VALUE - 1))
#define TIMEOUT_US 200000
#define MAX_PULSE_US 38000
#define DISTANCE_SCALE_FACTOR 0.0343

static time_t last_log_time = 0;
static int gpio_init_status = -1;

void log_distance(int pulse_us) {
    time_t current_time = time(NULL);
    if (difftime(current_time, last_log_time) >= 1) {
        printf("%lu: Distance: %.2f cm\n", current_time, (pulse_us * DISTANCE_SCALE_FACTOR) / 2);
        last_log_time = current_time;
    }
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }
    gpio_init_status = 1;

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioSetPullUp(ECHO_GPIO, ECHO_PROTECTION_RESISTOR);

    return 0;
}

void cleanup_gpio() {
    if (gpio_init_status > 0) {
        gpioTerminate();
        gpio_init_status = -1;
    }
}

int measure_distance() {
    gpioWrite(TRIGGER_GPIO, 1);
    usleep(10);
    gpioWrite(TRIGGER_GPIO, 0);

    uint32_t echo_start_tick = gpioTick();
    uint32_t echo_end_tick = echo_start_tick;

    while (gpioRead(ECHO_GPIO) == 0) {
        if (gpioTick() - echo_start_tick > TIMEOUT_US) {
            perror("Echo rising edge timeout");
            return -1;
        }
    }

    echo_end_tick = gpioTick();

    while (gpioRead(ECHO_GPIO) == 1) {
        if (gpioTick() - echo_end_tick > TIMEOUT_US) {
            perror("Echo falling edge timeout");
            return -1;
        }
    }

    int pulse_us = (gpioTick() - echo_start_tick) - (gpioTick() - echo_end_tick);
    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        perror("Invalid pulse duration");
        return -1;
    }

    return pulse_us;
}

int main(int argc, char *argv[]) {
    if (init_gpio() < 0) {
        return 1;
    }

    while (1) {
        int distance = measure_distance();
        if (distance < 0) {
            perror("Error measuring distance");
            break;
        }
        log_distance(distance);
        sleep(1);
    }

    cleanup_gpio();
    return 0;
}

