#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define UART_BAUD_RATE B115200
#define GPIO_LED 17
#define RADAR_MAGIC_WORD_LEN 8
#define RADAR_DATA_LEN 128
#define RADAR_BIN_COUNT 64
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

int uart_fd, gpio_led_handle;
char radar_magic_word[RADAR_MAGIC_WORD_LEN];
uint16_t radar_data[RADAR_BIN_COUNT];
time_t current_time;
FILE *log_file;

void uart_init() {
    struct termios options;

    if ((uart_fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY)) < 0) {
        perror("Failed to open UART");
        exit(EXIT_FAILURE);
    }

    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, B115200);
    cfsetospeed(&options, B115200);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = 1;

    if (tcsetattr(uart_fd, TCSANOW, &options) < 0) {
        perror("Failed to set UART attributes");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    gpio_led_handle = gpioInitialise(GPIO_LED, OUTPUT);
}

void log_intrusion(float distance) {
    char timestamp[25];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&current_time));

    if (log_file) {
        fprintf(log_file, "%s,%f\n", timestamp, distance);
        fflush(log_file);
    }
}

void handle_intrusion(float distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(gpio_led_handle, 1);
        sleep(2);
        gpioWrite(gpio_led_handle, 0);
        log_intrusion(distance);
    }
}

int read_radar_data() {
    int i, read_bytes;

    if (read(uart_fd, radar_magic_word, RADAR_MAGIC_WORD_LEN) != RADAR_MAGIC_WORD_LEN) {
        perror("Failed to read radar magic word");
        return -1;
    }

    if (memcmp(radar_magic_word, "\x02\x01\x04\x03\x06\x05\x08\x07", RADAR_MAGIC_WORD_LEN) != 0) {
        perror("Invalid radar magic word");
        return -1;
    }

    read_bytes = read(uart_fd, radar_data, RADAR_DATA_LEN);
    if (read_bytes != RADAR_DATA_LEN) {
        perror("Failed to read radar data");
        return -1;
    }

    for (i = 0; i < RADAR_BIN_COUNT; i++) {
        radar_data[i] = ntohs(radar_data[i]);
    }

    return 0;
}

void cleanup() {
    if (uart_fd >= 0) {
        close(uart_fd);
    }

    if (gpio_led_handle >= 0) {
        gpioTerminate();
    }

    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    uart_init();
    gpio_init();

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (read_radar_data() == 0) {
            float distance = RADAR_BIN_COUNT * 0.0486f * radar_data[0];
            handle_intrusion(distance);
        }

        current_time = time(NULL);
        usleep(100000);
    }

    cleanup();
    return 0;
}

