code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define SENSOR_LINE "line17"
#define BUZZER_LINE "line18"
#define LOG_FILE "obstacle_log.txt"

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = {
        [SENSOR_LINE] = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW,
        [BUZZER_LINE] = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_HIGH,
    },
};

int main(void) {
    int fd, ret;
    struct timespec ts;
    gpiod_line *sensor_line, *buzzer_line;
    FILE *log_file;

    fd = gpiod_chip_open(GPIO_CHIP);
    if (fd < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_request_lines_data(fd, &lines_data, 1);
    if (ret < 0) {
        perror("gpiod_chip_request_lines_data");
        close(fd);
        exit(EXIT_FAILURE);
    }

    sensor_line = gpiod_get_line_byname(fd, SENSOR_LINE);
    buzzer_line = gpiod_get_line_byname(fd, BUZZER_LINE);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        gpiod_chip_release_lines_data(fd, &lines_data);
        close(fd);
        exit(EXIT_FAILURE);
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%s Sensor initialized\n", ctime(&ts.tv_sec));

    while (1) {
        int state;
        ret = gpiod_line_get_value(sensor_line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        state = (ret == 0) ? 0 : 1;
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%s Sensor state changed: %d\n", ctime(&ts.tv_sec), state);

        if (state == 1) {
            gpiod_line_set_value(buzzer_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
        }

        usleep(100000);
    }

    fclose(log_file);
    gpiod_chip_release_lines_data(fd, &lines_data);
    close(fd);

    return EXIT_SUCCESS;
}

void signal_handler(int sig) {
    gpiod_chip_release_lines_data(fd, &lines_data);
    close(fd);
    exit(EXIT_SUCCESS);
}

int main(void) {
    struct sigaction sa;

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
