        perror("i2c_read_reg16_rep");
        exit(EXIT_FAILURE);
    }

    distance = (buf[0] << 8) | buf[1];
}

void log_distance(void) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    snprintf(log_file, sizeof(log_file), "distance_log.txt");
    FILE *log_fp = fopen(log_file, "a");

    if (!log_fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (difftime(now, last_log_time) < 0.1)
        return;

    last_log_time = now;
    fprintf(log_fp, "%s.%03ld: Distance: %u cm\n", asctime(tm_now), (long)(1000 * (now - last_log_time)));
    fflush(log_fp);
    fclose(log_fp);
}

void gpio_alert(void) {
    gpio_write(GPIO_PIN, 1);
    sleep(1);
    gpio_write(GPIO_PIN, 0);
}

