        perror("i2c_open");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        if (gpio_read(GPIO_FD) == 0) {
            cleanup(0);
