#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODE_START 0x007
#define VL53L1X_SYSRANGE_START 0x000
#define VL53L1X_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR 0x014
#define VL53L1X_RESULT_RANGE_STATUS 0x078
#define DISTANCE_LOG "distance_log.csv"
#define TIMEOUT_MS 100
#define MIN_DISTANCE 300
#define WARNING_DISTANCE_1 600
#define WARNING_DISTANCE_2 1200

int main() {
    int i2c_fd, ret;
    uint16_t distance;
    char timestamp[32];
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    int running = 1;
    int i2c_address = VL53L1X_I2C_ADDR << 1;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }

    if (pigpio_start() < 0) {
        perror("Failed to start pigpio");
        exit(EXIT_FAILURE);
    }

    if (xusleep(2 * 1000 * 1000) != 0) {
        perror("Failed to sleep for 2ms");
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_word_data(i2c_fd, 0x0000, 0x00) != 0) {
        perror("Failed to write software reset");
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(i2c_fd, VL53L1X_MODE_START, 0x01) != 0) {
        perror("Failed to start continuous back-to-back ranging");
        exit(EXIT_FAILURE);
    }

    log_file = fopen(DISTANCE_LOG, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    if (fprintf(log_file, "timestamp,distance_mm\n") < 0) {
        perror("Failed to write header to log file");
        exit(EXIT_FAILURE);
    }

    while (running) {
        if (i2c_smbus_read_byte_data(i2c_fd, VL53L1X_SYSRANGE_START) & 0x01) {
            if (i2c_smbus_read_word_data(i2c_fd, VL53L1X_RESULT_RANGE_STATUS, &distance) != 0) {
                perror("Failed to read distance");
                continue;
            }

            rawtime = time(NULL);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(log_file, "%s,%d\n", timestamp, distance);

            if (distance < MIN_DISTANCE) {
                printf("STOP\n");
            } else if (distance >= MIN_DISTANCE && distance < WARNING_DISTANCE_1) {
                printf("APPROACH\n");
            } else if (distance >= WARNING_DISTANCE_1 && distance < WARNING_DISTANCE_2) {
                printf("SLOW\n");
            } else {
                printf("CLEAR\n");
            }

            if (i2c_smbus_write_byte_data(i2c_fd, VL53L1X_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
                perror("Failed to clear interrupt");
            }

            usleep(100 * 1000);
        }

        if (i2c_smbus_read_byte_data(i2c_fd, VL53L1X_RESULT_INTERRUPT_STATUS) & 0x01) {
            if (i2c_smbus_read_word_data(i2c_fd, VL53L1X_RESULT_RANGE_STATUS, &distance) != 0) {
                perror("Failed to read distance");
                continue;
            }
        }
    }

    fclose(log_file);
    i2c_smbus_close_device(i2c_fd);
    close(i2c_fd);
    pigpio_stop();

    return 0;
}

