            if (i2cWriteReadRegister16(i2c_fd, 0x00, 0x00, 0x01, &distance, 2) >= 2)
                break;
            usleep(I2C_RETRY_DELAY * 1000);
        }

        if (i == I2C_RETRY_COUNT) {
            perror("Failed to read distance from sensor");
            continue;
        }

        distance /= DISTANCE_SCALE;
        blink_freq = MIN_DISTANCE + (distance * BLINK_FREQ_SCALE) / (MAX_DISTANCE - MIN_DISTANCE);
        blink_freq = (blink_freq <= 0.0) ? 1.0 : (blink_freq >= 100.0) ? 100.0 : blink_freq;

        timestamp = time(NULL);
        printf("%s Distance: %.2f mm, Blink Frequency: %.2f Hz\n", ctime(&timestamp), distance * 1000.0, blink_freq);

        gpioWrite(LED_PIN, led_state);
        led_state = !led_state;
        usleep(blink_freq * 1e6);
        gpioWrite(LED_PIN, !led_state);

        usleep(100000);
    }

cleanup:
    gpioTerm();
    close(i2c_fd);
    return 0;
}

int i2cWriteReadRegister16(int i2c_fd, uint8_t reg, uint8_t write_data, uint16_t ack_count, uint16_t *read_data, int len) {
    int ret;
    uint8_t buf[3];

    buf[0] = (reg << 1) | (write_data ? 0x01 : 0x00);
    buf[1] = write_data;

    ret = write(i2c_fd, buf, 2);
    if (ret < 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (write_data) {
        usleep(I2C_RETRY_DELAY * 1000);

        ret = read(i2c_fd, buf + 2, len * 2);
        if (ret < len * 2) {
            perror("Failed to read from I2C device");
            return -1;
        }

        for (int i = 0; i < ack_count; ++i) {
            if (buf[2 + i * 2] == (ack_count - i - 1))
                break;
        }

        if (i == ack_count) {
            perror("Invalid ACK count from I2C device");
            return -1;
        }

        for (int i = 0; i < len; ++i) {
            read_data[i] = (buf[2 + i * 2] << 8) | buf[2 + i * 2 + 1];
        }
    }

    return ret;
}
