#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 10
#define LOG_FILE "proximity_log.txt"

void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s, Sensor %d, %s\n", time_str, sensor_id, event_type);
    fclose(log_file);
}

int main(void) {
    int ret;
    uint32_t previous_states[2] = {0};

    if ((ret = gpioInitialise()) < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        goto cleanup;
    }

    while (1) {
        uint32_t current_states[2] = {gpioRead(SENSOR_1_GPIO), gpioRead(SENSOR_2_GPIO)};

        for (int i = 0; i < 2; ++i) {
            if (current_states[i] != previous_states[i]) {
                if (current_states[i]) {
                    log_event(i + 1, "DETECTED");
                } else {
                    log_event(i + 1, "CLEARED");
                }
            }
            previous_states[i] = current_states[i];
        }

        usleep(POLL_INTERVAL_MS * 1000);

        for (int i = 0; i < DEBOUNCE_MS; ++i) {
            usleep(1000);
            current_states[0] = gpioRead(SENSOR_1_GPIO);
            current_states[1] = gpioRead(SENSOR_2_GPIO);
            if (current_states[0] == previous_states[0] && current_states[1] == previous_states[1]) {
                break;
            }
        }
    }

cleanup:
    gpioTerminate();
    return 0;
}

