#include <time.h>

#define I2C_BUS 1
#define TDK_CH101_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    int ret;
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    struct i2c_msg msg[2];

    memset(&msg, 0, sizeof(msg));
    msg[0].addr = TDK_CH101_ADDR << 1;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = TDK_CH101_ADDR << 1;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = buf;

    i2c_msg[0] = msg[0];
    i2c_msg[1] = msg[1];

    ret = ioctl(fd, I2C_RDWR, &i2c_msg[0]);
    if (ret < 0) {
        perror("I2C read error");
        return -1;
    }

    return 0;
}

int main() {
    int i2c_fd, csv_fd;
    time_t timestamp;
    uint8_t data[2];
    ssize_t bytes_read;
    int ret;

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C file open error");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TDK_CH101_ADDR) < 0) {
        perror("I2C slave address setup error");
        goto cleanup;
    }

    csv_fd = fopen("distance_log.csv", "w");
    if (!csv_fd) {
        perror("CSV file open error");
        goto cleanup;
    }

    fprintf(csv_fd, "timestamp,distance_mm\n");

    while (1) {
        ret = i2c_read(i2c_fd, MEAS_TRIGGER, NULL, 0);
        if (ret < 0) {
            perror("I2C write error");
            continue;
        }

        usleep(100000); // Wait 100 ms for the sensor to prepare for the measurement.

        ret = i2c_read(i2c_fd, MEAS_STATUS, data, 1);
        if (ret < 0) {
            perror("I2C read error");
            continue;
        }

        if (!(data[0] & 0x01)) {
            fprintf(stderr, "Data-ready bit not set\n");
            continue;
        }

        ret = i2c_read(i2c_fd, DIST_HIGH, data, 2);
        if (ret < 0) {
            perror("I2C read error");
            continue;
        }

        timestamp = time(NULL);
        fprintf(csv_fd, "%s,%d\n", ctime(&timestamp), (data[0] << 8 | data[1]) * 10);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

cleanup:
    if (csv_fd) fclose(csv_fd);
    if (i2c_fd) close(i2c_fd);

    return 0;
}

