This code initializes the VL53L5CX sensor, configures it for an 8x8 zone grid, and periodically reads and logs the distance data for each zone. It handles errors and releases resources on exit paths, including when receiving a SIGINT signal.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MLX75030_REG_PWR_CTRL 0x00
#define MLX75030_REG_MEAS_MODE 0x01
#define MLX75030_REG_RESULT_0_MSB 0x02
#define MLX75030_REG_RESULT_0_LSB 0x03
#define MLX75030_REG_RESULT_1_MSB 0x04
#define MLX75030_REG_RESULT_1_LSB 0x05
#define MLX75030_REG_RESULT_2_MSB 0x06
#define MLX75030_REG_RESULT_2_LSB 0x07
#define MLX75030_REG_RESULT_3_MSB 0x08
#define MLX75030_REG_RESULT_3_LSB 0x09
#define MLX75030_REG_RESULT_4_MSB 0x0A
#define MLX75030_REG_RESULT_4_LSB 0x0B
#define MLX75030_REG_RESULT_5_MSB 0x0C
#define MLX75030_REG_RESULT_5_LSB 0x0D

int main() {
    int i2c_fd, success;
    unsigned char data[7];
    time_t rawtime;
    struct tm *timeinfo;
    int retries = 3;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, MLX75030_ADDR, &success);
    if (i2c_fd < 0 || !success) {
        fprintf(stderr, "Failed to open I2C bus or communicate with MLX75030\n");
        if (i2c_fd >= 0) {
            pigpio_i2c_close(i2c_fd);
        }
        gpioTerminate();
        return 1;
    }

    success = pigpio_write_i2c_reg8(i2c_fd, MLX75030_REG_PWR_CTRL, 0x03);
    if (!success) {
        fprintf(stderr, "Failed to write power control register\n");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    success = pigpio_write_i2c_reg8(i2c_fd, MLX75030_REG_MEAS_MODE, 0x01);
    if (!success) {
        fprintf(stderr, "Failed to write measurement mode register\n");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        for (int i = 0; i < retries; ++i) {
            success = pigpio_read_i2c_block_data(i2c_fd, MLX75030_REG_RESULT_0_MSB, 7, data);
            if (success >= 0) {
                break;
            }
            usleep(10000);
        }

        if (success < 0) {
            fprintf(stderr, "Failed to read data from MLX75030 after %d retries\n", retries);
            pigpio_i2c_close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        printf("%d-%02d-%02d %02d:%02d:%02d.%03d: Distance = %d mm\n",
               timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
               timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
               (int)(1000 * (timeinfo->tm_usec / 1000)),
               (data[0] << 8 | data[1]) + (data[2] << 16 | data[3] << 24));

        usleep(100000);
    }

    pigpio_i2c_close(i2c_fd);
    gpioTerminate();
    return 0;
}

