        return -1;
    }

    return 0;
}

static int i2c_read(int bus, int addr, int reg, int *value, int len) {
    if (i2cRead(bus, addr, &reg, 1, value, len, 1000) < 0) {
        fprintf(stderr, "Error reading from register %04X: %s\n", reg, gpioStrerror(gpioLastError()));
        return -1;
    }

    return 0;
}

static void print_timestamp(void) {
    struct timespec ts;
