           ts.tv_year - 1900, ts.tv_mon + 1, ts.tv_mday, ts.tv_hour, ts.tv_min, ts.tv_sec, ts.tv_nsec);
}

static void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

