        fprintf(stderr, "Failed to initialize pigpio library: %s\n", gpioStrerror(gpioLastError()));
        return 1;
    }

    if (gpioSetMode(PI_MODE_WR, PI_BS0, I2C_BUS) < 0 ||
        gpioSetMode(PI_MODE_WR, PI_BS1, I2C_BUS) < 0 ||
        gpioSetMode(PI_MODE_RD, PI_BS0, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to set GPIO modes for I2C bus: %s\n", gpioStrerror(gpioLastError()));
        goto cleanup;
    }

    if (i2cOpen(I2C_BUS, VL53L4CX_ADDR, &i2c_handle) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpioStrerror(gpioLastError()));
        goto cleanup;
    }

    if (i2c_write(I2C_BUS, VL53L4CX_ADDR, SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to perform soft reset: %s\n", gpioStrerror(gpioLastError()));
        goto cleanup;
    }

    usleep(10000);

    if (i2c_write(I2C_BUS, VL53L4CX_ADDR, START_RANGING_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging: %s\n", gpioStrerror(gpioLastError()));
        goto cleanup;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        usleep(500000);

        if (i2c_read(I2C_BUS, VL53L4CX_ADDR, INT_STATUS_REG, &status, 1) < 0) {
            fprintf(stderr, "Failed to read interrupt status: %s\n", gpioStrerror(gpioLastError()));
            continue;
        }

        if ((status & 0x01) != 0) {
            int distance_high, distance_low;

            if (i2c_read(I2C_BUS, VL53L4CX_ADDR, DISTANCE_HIGH_REG, &distance_high, 1) < 0 ||
                i2c_read(I2C_BUS, VL53L4CX_ADDR, DISTANCE_LOW_REG, &distance_low, 1) < 0) {
                fprintf(stderr, "Failed to read distance data: %s\n", gpioStrerror(gpioLastError()));
                continue;
            }

            print_timestamp();
            printf("Distance: %d mm\n", (distance_high << 8 | distance_low) / 16);
        }
    }

cleanup:
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return 0;
}

