#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define SOUND_SPEED 343.0
#define MIN_ECHO_TIME 50
#define MAX_DISTANCE 400
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define LOG_FILE "sensor_data.log"
#define LOG_INTERVAL 200

int servo_angle_to_pulse(int angle);
void log_data(int distance);
void sigint_handler(int signum);
void sigterm_handler(int signum);

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_SERVO_OUTPUT);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    int last_log_time = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;

    while (1) {
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        double start_time = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;
        double elapsed_time = 0;
        int pulse_width = 0;

        while (gpioRead(ECHO_PIN) == 0) {
            ts.tv_sec = start_time + elapsed_time / 1000;
            ts.tv_nsec = (elapsed_time % 1000) * 1_000_000;
            clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);

            if (elapsed_time > 50000) {
                fprintf(stderr, "Echo stuck high for more than 50 ms\n");
                break;
            }
        }

        while (gpioRead(ECHO_PIN) == 1) {
            ts.tv_sec = start_time + elapsed_time / 1000;
            ts.tv_nsec = (elapsed_time % 1000) * 1_000_000;
            clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);

            if (elapsed_time > 50000) {
                fprintf(stderr, "Echo stuck low for more than 50 ms\n");
                break;
            }

            elapsed_time = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000 - start_time;
            pulse_width = elapsed_time * 1000000 / 2;
        }

        if (pulse_width > 0) {
            double distance = pulse_width * SOUND_SPEED / 2 / 10000;
            int servo_angle = (MAX_DISTANCE - distance) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / (MAX_DISTANCE - 2) + SERVO_MIN_PULSE;
            gpioServoWrite(SERVO_PIN, servo_angle);
            log_data((int)(distance * 10));
        }

        ts.tv_sec = last_log_time + LOG_INTERVAL / 1000;
        ts.tv_nsec = (LOG_INTERVAL % 1000) * 1_000_000;
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
        last_log_time = ts.tv_sec * 1000 + ts.tv_nsec / 1_000_000;
    }

    gpioServoWrite(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

int servo_angle_to_pulse(int angle) {
    return angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180 + SERVO_MIN_PULSE;
}

void log_data(int distance) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fclose(log_file);
}

void sigint_handler(int signum) {
    gpioServoWrite(SERVO_PIN, 0);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signum) {
    gpioServoWrite(SERVO_PIN, 0);
    gpioTerminate();
    exit(0);
}

