code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/msg.h>
#include <pigpio.h>

#define VL53L1X_I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define BUZZER_GPIO 23
#define QUEUE_KEY 1234
#define QUEUE_SIZE 1024
#define TIMEOUT_US 50000
#define DISTANCE_THRESHOLD 100

typedef struct {
    long mtype;
    uint16_t distance;
} msg_t;

int i2c_fd, queue_id, gpio_handle, ret;
char *i2c_map;

void i2c_write_reg(uint8_t reg, uint16_t value) {
    if (i2c_write(i2c_fd, (const char *)&reg, 1) != 1 ||
        i2c_write(i2c_fd, (const char *)&value, 2) != 2) {
        perror("i2c_write_reg");
        exit(EXIT_FAILURE);
    }
}

uint16_t i2c_read_reg(uint8_t reg, size_t len) {
    uint8_t buf[len];
    if (i2c_read(i2c_fd, &reg, 1) != 1 || i2c_read(i2c_fd, buf, len) != len) {
        perror("i2c_read_reg");
        exit(EXIT_FAILURE);
    }
    return *(uint16_t *)buf;
}

void check_model_id() {
    if (i2c_read_reg(0x010F, 1) != 0xEA) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        exit(EXIT_FAILURE);
    }
}

void software_reset() {
    i2c_write_reg(0x0000, 0x0001);
    usleep(100000);
    i2c_write_reg(0x0000, 0x0000);
}

void configure_timing_budget() {
    i2c_write_reg(0x0080, 0x01);
    i2c_write_reg(0x0081, 0x00);
    i2c_write_reg(0x0082, 0x00);
    i2c_write_reg(0x0083, 0x00);
    i2c_write_reg(0x0084, 0x00);
    i2c_write_reg(0x0085, 0x00);
}

void init_i2c() {
    i2c_fd = pigpio_i2c_open(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR, TIMEOUT_US);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        exit(EXIT_FAILURE);
    }
    i2c_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (i2c_map == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    gpio_handle = pigpio_init();
    if (gpio_handle < 0) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }
    if (gpio_set_mode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        perror("gpio_set_mode");
        exit(EXIT_FAILURE);
    }
}

void init_queue() {
    queue_id = msgget(QUEUE_KEY, IPC_CREAT | 0666);
    if (queue_id == -1) {
        perror("msgget");
        exit(EXIT_FAILURE);
    }
}

void log_distance(uint16_t distance) {
    msg_t msg;
    msg.mtype = QUEUE_KEY;
    msg.distance = distance;
    if (msgsnd(queue_id, &msg, sizeof(msg), 0) == -1) {
        perror("msgsnd");
    }
}

void check_distance() {
    uint16_t distance;
    while (1) {
        if (i2c_read_reg(0x0089, 1) & 0x01) {
            distance = (i2c_read_reg(0x0096, 2) << 8) | i2c_read_reg(0x0097, 2);
            if (distance < DISTANCE_THRESHOLD) {
                gpio_write(BUZZER_GPIO, 1);
            }
            log_distance(distance);
        }
        usleep(50000);
    }
}

int main() {
    init_i2c();
    check_model_id();
    software_reset();
    configure_timing_budget();
    init_gpio();
    init_queue();

    pigpio_set_mode(VL53L1X_I2C_BUS, PI_MODE_I2C_SDA_SCL_ALT_0);

    check_distance();

    pigpio_stop();
    munmap(i2c_map, 4096);
    close(i2c_fd);
    msgctl(queue_id, IPC_RMID, NULL);
    gpioTerm(gpio_handle);
    return 0;
}

