#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define BUZZER_GPIO 22
#define SOUND_SPEED 34300
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define UPDATE_INTERVAL 100
#define TIMEOUT 50000
#define TICK_PER_US (1000000 / pigpio_quick_ticks())

static volatile int running = 1;
static int distance = -1;
static time_t last_update = 0;

void alarm_handler(int signum) {
    running = 0;
}

void trigger() {
    gpioWrite(TRIGGER_GPIO, 1);
    usleep(10);
    gpioWrite(TRIGGER_GPIO, 0);
}

uint32_t get_time() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000000000 + ts.tv_nsec;
}

double get_distance() {
    uint32_t start = get_time();
    while (gpioRead(ECHO_GPIO) == 0) {
        if (get_time() - start > TIMEOUT) {
            return -1;
        }
    }
    uint32_t end = get_time();
    uint32_t pulse_width = end - start;
    if (pulse_width > TICK_PER_US * MAX_DISTANCE * 2) {
        return MAX_DISTANCE;
    }
    double distance_cm = (pulse_width * SOUND_SPEED) / (TICK_PER_US * 2);
    if (distance_cm < MIN_DISTANCE || distance_cm > MAX_DISTANCE) {
        return -2;
    }
    return distance_cm;
}

void gpio_setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_GPIO, PI_INPUT_PULL_UP) < 0 ||
        gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetAlertFuncEx(ECHO_GPIO, PI_EDGE_BOTH, distance_cb) < 0) {
        fprintf(stderr, "Failed to register alert function\n");
        gpioTerminate();
        exit(1);
    }
}

void distance_cb(int gpio, uint32_t tick) {
    if (running) {
        distance = get_distance();
        if (distance >= 0) {
            last_update = get_time();
        }
    }
}

void buzzer_control(int on) {
    if (on) {
        gpioWrite(BUZZER_GPIO, 1);
    } else {
        gpioWrite(BUZZER_GPIO, 0);
    }
}

int main() {
    signal(SIGINT, alarm_handler);
    gpio_setup();

    while (running) {
        alarm(UPDATE_INTERVAL);
        usleep(100000);
        if (get_time() - last_update >= UPDATE_INTERVAL) {
            if (distance >= 0) {
                printf("Distance: %.2f cm\n", distance);
                if (distance < 30) {
                    buzzer_control(1);
                } else {
                    buzzer_control(0);
                }
            }
            last_update = get_time();
        }
        usleep(100000);
    }

    buzzer_control(0);
    gpioTerminate();
    return 0;
}

