#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <wiringPiI2C.h>
#include <pthread.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define VL53L1X_I2C_ADDR 0x29
#define SERVO_GPIO 18
#define MQTT_BROKER_IP "mqtt.example.com"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "gate_controller"

static int vl53l1x_i2c_fd;
static MQTTClient client;

void vl53l1x_software_reset() {
    if (vl53l1x_i2c_fd < 0)
        return;

    if (i2c_writeByteData(vl53l1x_i2c_fd, 0x80, 0x80) < 0) {
        perror("Failed to send software reset command");
    }
}

int vl53l1x_wait_for_boot() {
    int retries = 10;
    while (retries--) {
        if (i2c_readByteData(vl53l1x_i2c_fd, 0x81) == 0x01)
            return 0;
        usleep(100000);
    }

    perror("Failed to detect VL53L1X boot status");
    return -1;
}

int vl53l1x_start_ranging() {
    if (vl53l1x_i2c_fd < 0)
        return -1;

    if (i2c_writeByteData(vl53l1x_i2c_fd, 0x80, 0x01) < 0) {
        perror("Failed to start ranging");
        return -1;
    }

    return 0;
}

uint16_t vl53l1x_read_distance() {
    if (vl53l1x_i2c_fd < 0)
        return 0;

    if (i2c_readWordData(vl53l1x_i2c_fd, 0x88) < 0) {
        perror("Failed to read distance");
        return 0;
    }

    return (uint16_t)i2c_readWordData(vl53l1x_i2c_fd, 0x8A);
}

void servo_move(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return;
    }

    gpioServo(SERVO_GPIO, angle);
}

void gate_event_log(const char *event, const char *params) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        perror("Failed to open gate log file");
        return;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    if (params)
        fprintf(log_file, "  %s\n", params);
    fclose(log_file);
}

void mqtt_callback(void *context, MQTTClient_deliveryToken *token) {
    char topic[64];
    char message[128];

    MQTTClient_messageAttrs attr;
    MQTTClient_messageAttrs_init(&attr);
    MQTTClient_messageAttrs_setQoS(&attr, MQTTCLIENT_QOS_0);

    MQTTClient_getMessage(client, token, message, sizeof(message), &attr);
    MQTTClient_messageAttrs_getTopicName(&attr, topic, sizeof(topic));

    if (strstr(topic, "force_open") != NULL) {
        gate_event_log("Force open", "");
        servo_move(0);
    } else if (strstr(topic, "force_close") != NULL) {
        gate_event_log("Force close", "");
        servo_move(180);
    } else if (strstr(topic, "status_request") != NULL) {
        snprintf(message, sizeof(message), "Gate status: %s\n", servo_move(180) ? "Closed" : "Open");
        MQTTClient_publish(client, topic, message, strlen(message), MQTTCLIENT_QOS_0, false);
    }
}

int init_vl53l1x() {
    if ((vl53l1x_i2c_fd = wiringPiI2CSetup(VL53L1X_I2C_ADDR)) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    vl53l1x_software_reset();
    if (vl53l1x_wait_for_boot() < 0)
        return -1;

    if (vl53l1x_start_ranging() < 0)
        return -1;

    return 0;
}

void cleanup() {
    if (vl53l1x_i2c_fd >= 0)
        close(vl53l1x_i2c_fd);

    MQTTClient_disconnectFromBroker(client);
    MQTTClient_destroy(&client);
    gpioTerm();
    exit(0);
}

void *mqtt_thread(void *arg) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.clientID.cstring = MQTT_CLIENT_ID;

    if ((rc = MQTTClient_create(&client, MQTT_BROKER_IP, MQTT_BROKER_PORT, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        perror("Failed to create MQTT client");
        cleanup();
    }

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        perror("Failed to connect to MQTT broker");
        cleanup();
    }

    MQTTClient_setCallback(client, mqtt_callback, NULL);

    while (!gpioTerm()) {
        usleep(100000);
    }

    MQTTClient_disconnectFromBroker(client);
    MQTTClient_destroy(&client);

    return NULL;
}

int main() {
    int rc;
    uint16_t distance;

    if (wiringPiSetup() < 0) {
        perror("Failed to initialize wiringPi");
        return 1;
    }

    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    if (init_vl53l1x() < 0) {
        perror("Failed to initialize VL53L1X");
        return 1;
    }

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    pthread_t mqtt_thread_id;
    if ((rc = pthread_create(&mqtt_thread_id, NULL, mqtt_thread, NULL)) != 0) {
        perror("Failed to create MQTT thread");
        cleanup();
    }

    while (1) {
        distance = vl53l1x_read_distance();
        if (distance <= 20) {
            gate_event_log("Open gate", "");
            servo_move(0);
        } else {
            gate_event_log("Close gate", "");
            servo_move(180);
        }
        sleep(1);
    }

    return 0;
}

