static time_t last_timeout = 0;
static uint32_t rising_edge_tick = 0;
static uint32_t falling_tick = 0;
static int log_file_fd = -1;

void echo_callback(int gpio, uint32_t tick) {
    if (gpio != ECHO_GPIO) return;

    if (gpioRead(gpio) == 0) {
        if (rising_edge_tick) {
            falling_tick = tick;
            if (falling_tick - rising_edge_tick < 100000 || falling_tick - rising_edge_tick > 30000000) {
                fprintf(stderr, "Warning: Invalid pulse width: %lu us\n", falling_tick - rising_edge_tick);
            } else {
                double distance = (falling_tick - rising_edge_tick) * SOUND_SPEED / 2.0;
                time_t now = time(NULL);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%f", localtime(&now));

                fprintf(stderr, "Distance: %.2f cm at %s\n", distance, timestamp);
                fprintf(log_file_fd, "%s,%.2f\n", timestamp, distance);
                fflush(log_file_fd);
                last_valid_echo = now;
            }
            rising_edge_tick = 0;
        } else {
            rising_edge_tick = tick;
        }
    }
}

