        gpioTerminate();
        return 1;
    }

    if ((log_file_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT | O_SYNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    while (1) {
        gpioWrite(TRIG_GPIO, 1);
        usleep(10000);
        gpioWrite(TRIG_GPIO, 0);

        last_echo = time(NULL);
        if (last_echo - last_valid_echo > TIMEOUT) {
            fprintf(stderr, "Warning: Timeout waiting for echo\n");
            last_timeout = last_echo;
        } else if (last_echo - last_timeout > SAMPLE_RATE * 1000000) {
            last_timeout = last_echo;
        }

        usleep(200000);
