#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <wiringPiI2C.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>

#define VL53L1X_I2C_ADDR 0x29
#define SERVO_PWM_GPIO 18
#define SHUTDOWN_GPIO 23
#define INTERRUPT_GPIO 24
#define LOG_FILE "parking_log.txt"

static int i2c_fd;
static int servo_pwm_handle;
static int shutdown_gpio;
static int interrupt_gpio;
static int distance;
static time_t last_log_time;
static pthread_t sensor_thread;

void sigint_handler(int signum) {
    printf("\nExiting...\n");
    close(i2c_fd);
    gpioTerm(servo_pwm_handle);
    gpioTerm(shutdown_gpio);
    gpioTerm(interrupt_gpio);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int init_i2c() {
    if ((i2c_fd = wiringPiI2CSetup(VL53L1X_I2C_ADDR)) < 0) {
        perror("Failed to initialize I2C");
        return -1;
    }

    if (wiringPiI2CReadReg16(i2c_fd, 0x01) != 0xFE91) {
        fprintf(stderr, "Invalid VL53L1X model ID\n");
        return -1;
    }

    return 0;
}

int init_gpio() {
    if (wiringPiSetup() == -1) {
        perror("Failed to initialize GPIO");
        return -1;
    }

    shutdown_gpio = gpioInitialise();
    if (shutdown_gpio < 0) {
        perror("Failed to initialize shutdown GPIO");
        return -1;
    }

    gpioSetMode(shutdown_gpio, PI_OUTPUT);
    gpioWrite(shutdown_gpio, 1);

    interrupt_gpio = gpioInitialise();
    if (interrupt_gpio < 0) {
        perror("Failed to initialize interrupt GPIO");
        return -1;
    }

    gpioSetMode(interrupt_gpio, PI_INPUT);
    gpioSetPullUp(interrupt_gpio, 1);
    gpioSetAlertFunc(interrupt_gpio, on_interrupt, NULL);

    if ((servo_pwm_handle = gpioPWM(SERVO_PWM_GPIO, 50)) < 0) {
        perror("Failed to initialize servo PWM GPIO");
        return -1;
    }

    return 0;
}

void on_interrupt(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        distance = read_distance();
        log_event(distance);
        if (distance <= 50) {
            open_gate();
        } else {
            close_gate();
        }
    }
}

int read_distance() {
    int data[9];
    if (wiringPiI2CReadReg16(i2c_fd, 0x00) != 0xAA55) {
        perror("Failed to read VL53L1X data");
        return -1;
    }

    if (wiringPiI2CReadReg16(i2c_fd, 0x03) != 0x0100) {
        perror("Failed to read VL53L1X data");
        return -1;
    }

    for (int i = 0; i < 9; ++i) {
        data[i] = wiringPiI2CReadReg16(i2c_fd, 0x0A + i * 2);
    }

    double range_mm = (data[0] << 8 | data[1]) / 16.0;
    double signal_rate_kHz = (data[2] << 8 | data[3]) / 1000.0;
    double ambient_temp_C = (data[4] << 8 | data[5]) / 100.0;
    double ph_mm = (data[6] << 8 | data[7]) / 100.0;
    double signal_mm = range_mm + ph_mm;

    return signal_mm;
}

void open_gate() {
    gpioPWM(servo_pwm_handle, 2.0);
    printf("Opening gate: %f cm\n", distance);
}

void close_gate() {
    gpioPWM(servo_pwm_handle, 0.0);
    printf("Closing gate: %f cm\n", distance);
}

void log_event(int distance) {
    time_t current_time = time(NULL);
    if (difftime(current_time, last_log_time) > 1) {
        last_log_time = current_time;
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%s: Gate state: %s, Distance: %d cm\n", ctime(&current_time), distance <= 50 ? "Open" : "Closed", distance);
            fclose(log_file);
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if (init_i2c() < 0 || init_gpio() < 0) {
        return 1;
    }

    gpioWrite(shutdown_gpio, 0);

    if (pthread_create(&sensor_thread, NULL, (void*(*)(void*))sensor_loop, NULL) != 0) {
        perror("Failed to create sensor thread");
        return 1;
    }

    pthread_join(sensor_thread, NULL);

    return 0;
}

void* sensor_loop(void* arg) {
    while (1) {
        usleep(100000);
        distance = read_distance();
        if (distance == -1) {
            perror("Failed to read distance");
            break;
        }
    }

    return NULL;
}

