code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define VL53L1X_ADDR 0x29
#define VL53L1X_I2C_BUS 1
#define MOTOR_FWD_GPIO 17
#define MOTOR_REV_GPIO 18
#define DIST_THRESH_MIN 10
#define DIST_THRESH_MAX 30

int i2c_file;
int motor_fwd_pin, motor_rev_pin;

void i2c_write_reg(uint16_t reg, uint16_t val) {
    if (i2c_smbus_write_word_data(i2c_file, reg, val) < 0) {
        perror("i2c_smbus_write_word_data");
        exit(EXIT_FAILURE);
    }
}

uint16_t i2c_read_reg(uint16_t reg) {
    int retries = 3;
    uint16_t val;

    do {
        if (i2c_smbus_read_word_data(i2c_file, reg) < 0) {
            if (--retries > 0) {
                usleep(1000 * retries);
            } else {
                perror("i2c_smbus_read_word_data");
                exit(EXIT_FAILURE);
            }
        } else {
            val = i2c_smbus_get_word_data(i2c_file, reg);
            break;
        }
    } while (1);

    return val;
}

void i2c_init() {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-1", 0);
    if ((i2c_file = open(filename, O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }
}

void motor_init() {
    motor_fwd_pin = gpioInitialise();
    motor_rev_pin = gpioInitialise();

    gpioSetMode(MOTOR_FWD_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_REV_GPIO, PI_OUTPUT);
    gpioWrite(MOTOR_FWD_GPIO, 0);
    gpioWrite(MOTOR_REV_GPIO, 0);
}

void motor_control(uint16_t distance) {
    if (distance < DIST_THRESH_MIN) {
        gpioWrite(MOTOR_FWD_GPIO, 1);
        gpioWrite(MOTOR_REV_GPIO, 0);
    } else if (distance > DIST_THRESH_MAX) {
        gpioWrite(MOTOR_FWD_GPIO, 0);
        gpioWrite(MOTOR_REV_GPIO, 1);
    } else {
        gpioWrite(MOTOR_FWD_GPIO, 0);
        gpioWrite(MOTOR_REV_GPIO, 0);
    }
}

void isr_cb(int gpio, uint32_t events, void *user_data) {
    uint16_t distance;

    i2c_write_reg(0x0000, 0x00); // Soft reset
    usleep(1000 * 1000);
    i2c_write_reg(0x0000, 0x01); // Start measurement

    while ((i2c_read_reg(0x0089) & 0x01) == 0) {
        // Wait for data ready
    }

    distance = (i2c_read_reg(0x0096) << 8) | i2c_read_reg(0x0097);
    printf("Distance: %d mm\n", distance);
    motor_control(distance);
}

int main() {
    i2c_init();
    motor_init();

    gpioSetAlertFunc(24, PI_EDGE_RISING, isr_cb, NULL);

