#define GPIO_DATA_FN 3
#define GPIO_LED_17 17
#define GPIO_LED_18 18
#define GPIO_LED_27 27
#define GPIO_LED_22 22

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *names, unsigned int flags) {
    return gpiod_chip_request_lines(chip, nlines, names, flags);
}

static int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(fd, buf, 2);
}

static int i2c_read_reg(int fd, unsigned char reg, unsigned char *value) {
    char buf[2];
    buf[0] = reg;
    if (write(fd, &buf, 1) != 1) {
        perror("i2c_read_reg: write");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("i2c_read_reg: read");
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static void i2c_init(void) {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("i2c_init: open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("i2c_init: ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Soft reset
    if (i2c_write_reg(i2c_fd, 0x80, 0x63) < 0) {
        perror("i2c_init: soft reset");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify sensor presence
    unsigned char id;
    if (i2c_read_reg(i2c_fd, 0x0F, &id) < 0) {
        perror("i2c_init: read ID");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (id != 0x01) {
        log_event("MPR121 not found");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure MPR121
    if (i2c_write_reg(i2c_fd, 0x00, 0x00) < 0) { // Stop mode
        perror("i2c_init: ELECONFIG0");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x01, 0x01) < 0) { // Baseline filtering
        perror("i2c_init: MHDR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x02, 0x01) < 0) { // NHDR
        perror("i2c_init: NHDR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x03, 0x0E) < 0) { // NCLR
        perror("i2c_init: NCLR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x04, 0x00) < 0) { // FDLR
        perror("i2c_init: FDLR");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x5A, 0x0B) < 0) { // Auto-configuration thresholds
        perror("i2c_init: register 0x5A");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x5D, 0xC8) < 0) {
        perror("i2c_init: register 0x5D");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x5E, 0x82) < 0) {
        perror("i2c_init: register 0x5E");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x5F, 0xB4) < 0) {
        perror("i2c_init: register 0x5F");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (i2c_write_reg(i2c_fd, 0x00, 0x0C) < 0) { // Enable all electrodes in run mode
        perror("i2c_init: ELECONFIG0");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void gpio_init(void) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpio_init: gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    ret = gpio_request_lines(chip, 4,
                             (const char*[]) { "gpio17", "gpio18", "gpio27", "gpio22" },
                             GPIOD_INPUT);
    if (ret < 0) {
        perror("gpio_init: gpio_request_lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, [](int signum) {
        log_event("Received SIGINT, exiting...");
        gpiod_chip_release_lines(chip, 4, (const char*[]) { "gpio17", "gpio18", "gpio27", "gpio22" });
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int signum) {
        log_event("Received SIGTERM, exiting...");
        gpiod_chip_release_lines(chip, 4, (const char*[]) { "gpio17", "gpio18", "gpio27", "gpio22" });
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    });
}

static void poll_sensor(void) {
    unsigned char status[13];
    unsigned char led_pattern = 0;
    int i2c_fd = -1;

    i2c_init();
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("poll_sensor: open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("poll_sensor: ioctl");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (i2c_read_reg(i2c_fd, 0x00, status) < 0) {
            perror("poll_sensor: read status");
            close(i2c_fd);
            break;
        }
        if (i2c_read_reg(i2c_fd, 0x01, &status[12]) < 0) {
            perror("poll_sensor: read status");
            close(i2c_fd);
            break;
        }

        for (int i = 0; i < 12; ++i) {
            if (status[i] & 0x01) {
                led_pattern = (led_pattern & ~(0xF << (i * 4))) | (1 << (i * 4));
                break;
            }
        }

        if (led_pattern == 0) {
            log_event("No electrode detected");
        } else {
            log_event("Electrode detected:");
            for (int i = 0; i < 4; ++i) {
                if (led_pattern & (1 << (i * 3))) {
                    gpiod_set_value_cansleep(gpiochip_get_line_byname(chip,
                                                                       (const char*[]) { "gpio17", "gpio18", "gpio27", "gpio22" }[i]), 1);
                } else {
                    gpiod_set_value_cansleep(gpiochip_get_line_byname(chip,
                                                                       (const char*[]) { "gpio17", "gpio18", "gpio27", "gpio22" }[i]), 0);
                }
            }
        }

        usleep(50000);
    }

    close(i2c_fd);
}

int main(void) {
    gpio_init();
    poll_sensor();
    return 0;
}

