#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define TRIG_GPIO 17
#define ECHO_GPIO 18
#define PULSE_WIDTH_MIN 58
#define PULSE_WIDTH_MAX 25000
#define SAMPLE_INTERVAL 1000000
#define LOG_FILE "distance_log.txt"

static volatile int running = 1;
static time_t last_log_time = 0;
static int log_fd = -1;

void isr_callback(int gpio, uint32_t events, void *user_data) {
    static uint32_t start_us = 0;
    uint32_t end_us = pigpio_get_time_us();
    uint32_t pulse_us = end_us - start_us;

    if (events & PI_EDGE_RISING_EDGE) {
        start_us = pigpio_get_time_us();
        return;
    }

    if (pulse_us > PULSE_WIDTH_MIN && pulse_us < PULSE_WIDTH_MAX) {
        time_t now = time(NULL);
        double distance_m = (pulse_us * 343.0) / (2.0 * 1e6);

        if (log_fd >= 0) {
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s, %f\n", timestamp, distance_m);
            fflush(log_fd);
            if (now - last_log_time > 60) {
                last_log_time = now;
                fseek(log_fd, 0, SEEK_SET);
            }
        }
    }
}

void sigint_handler(int signum) {
    running = 0;
    gpioTerminate();
    if (log_fd >= 0) {
        close(log_fd);
        log_fd = -1;
    }
}

int main(void) {
    int ret;

    if ((ret = pigpio_init()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(-ret));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("Failed to open log file");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(TRIG_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);

    gpioSetPullUpDown(ECHO_GPIO, PI_PUD_UP);
    gpioSetISRFuncEx(ECHO_GPIO, PI_EDGE_BOTH, isr_callback, NULL);

    while (running) {
        gpioWrite(TRIG_GPIO, 1);
        usleep(10);
        gpioWrite(TRIG_GPIO, 0);
        usleep(SAMPLE_INTERVAL);
    }

    gpioTerminate();
    close(log_fd);

    return 0;
}

