#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_GPIO GPIO_NUM_27
#define I2C_RDWR_LEN 32

static int i2c_fd;
static int i2c_address = VL53L1X_ADDR << 1;

void i2c_init() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        syslog(LOG_ERR, "Failed to acquire I2C bus: %s", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio library: %s", gpioStrerror());
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioWrite(TRIGGER_GPIO, 1);
}

void sensor_init() {
    uint8_t data[] = {0x00, 0x00, 0x01};

    if (writeI2CReg16(0x0018, data, 3) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018: %s", gpioStrerror());
        exit(EXIT_FAILURE);
    }

    if (writeI2CReg8(0x0019, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019: %s", gpioStrerror());
        exit(EXIT_FAILURE);
    }

    if (writeI2CReg8(0x0020, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020: %s", gpioStrerror());
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance() {
    uint8_t data[I2C_RDWR_LEN];
    ssize_t bytes_read;

    data[0] = 0x00;
    data[1] = 0x14;

    bytes_read = i2cReadReg16(data, 2);
    if (bytes_read != 2) {
        syslog(LOG_ERR, "Failed to read from register 0x0014: %s", gpioStrerror());
        return 0;
    }

    return (data[0] << 8) | data[1];
}

uint8_t read_status() {
    uint8_t data[I2C_RDWR_LEN];
    ssize_t bytes_read;

    data[0] = 0x00;
    data[1] = 0x16;

    bytes_read = i2cReadReg8(data, 1);
    if (bytes_read != 1) {
        syslog(LOG_ERR, "Failed to read from register 0x0016: %s", gpioStrerror());
        return 0;
    }

    return data[0];
}

void log_sensor_data(const char *prefix, uint16_t distance, uint8_t status) {
    time_t timestamp = time(NULL);
    struct tm *tm_info = localtime(&timestamp);
    char log_str[256];

    strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(log_str + strlen(log_str), sizeof(log_str) - strlen(log_str), " %s Distance: %.2f mm Status: %d\n", prefix, distance * 0.001, status);

    openlog("vl53l1x_sensor", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "%s", log_str);
    closelog();
}

void sigint_handler(int signum) {
    close(i2c_fd);
    gpioTerm();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpio_init();
    i2c_init();
    sensor_init();

    while (1) {
        uint16_t distance = read_distance();
        uint8_t status = read_status();

        log_sensor_data("Successful read", distance, status);
        usleep(100000);
    }

    close(i2c_fd);
    gpioTerm();

    return EXIT_SUCCESS;
}

