#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define SAMPLES 5
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define MIN_SERVO_PW 500
#define MAX_SERVO_PW 2500
#define LOG_FILE "distance_log.csv"

volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    running = 0;
    gpioServo(SERVO_GPIO, 90);
    gpioTerminate();
}

double moving_average(double values[], int size) {
    double sum = 0.0;
    for (int i = 0; i < size; ++i) {
        sum += values[i];
    }
    return sum / size;
}

double distance_from_pulse_width(int pulse_width_us) {
    double speed_of_sound = 34300.0;
    double time_us = (double)pulse_width_us / 1000000.0;
    double distance_cm = (speed_of_sound * time_us) / 2.0;
    return distance_cm;
}

int servo_angle_from_distance(double distance_cm) {
    double log_base = log(MAX_DISTANCE / MIN_DISTANCE);
    double log_distance = log(distance_cm / MIN_DISTANCE);
    double angle = (180.0 / log_base) * log_distance;
    if (angle < 0.0) {
        angle = 0.0;
    } else if (angle > 180.0) {
        angle = 180.0;
    }
    return angle;
}

int servo_pulse_width_from_angle(double angle_degrees) {
    double pulse_width_us = MIN_SERVO_PW + (MAX_SERVO_PW - MIN_SERVO_PW) * pow(angle_degrees / 180.0, 3);
    return pulse_width_us;
}

void echo_callback(int gpio, uint32_t tick) {
    static int pulse_start_tick = 0;
    static int samples[SAMPLES] = {0};
    static int sample_index = 0;

    if (gpio != ECHO_GPIO) {
        return;
    }

    if (tick - pulse_start_tick >= TIMEOUT_US) {
        samples[sample_index] = -1.0;
        sample_index = (sample_index + 1) % SAMPLES;
        return;
    }

    int pulse_width_us = (int)(tick - pulse_start_tick);
    samples[sample_index] = distance_from_pulse_width(pulse_width_us);
    sample_index = (sample_index + 1) % SAMPLES;

    double moving_average_distance = moving_average(samples, SAMPLES);
    int servo_angle = servo_angle_from_distance(moving_average_distance);
    int servo_pulse_width = servo_pulse_width_from_angle(servo_angle);

    if (moving_average_distance < MIN_DISTANCE || moving_average_distance > MAX_DISTANCE) {
        moving_average_distance = -1.0;
    }

    if (servo_pulse_width < MIN_SERVO_PW || servo_pulse_width > MAX_SERVO_PW) {
        servo_pulse_width = 900; // Default servo position
    }

    if (moving_average_distance != -1.0) {
        gpioServo(SERVO_GPIO, servo_pulse_width);
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s,%f,%d\n", timestamp, moving_average_distance, servo_angle);
        fflush(file);
        fclose(file);
    }

    pulse_start_tick = tick;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_GPIO, pigpio_callback, echo_callback) < 0) {
        fprintf(stderr, "Failed to set echo callback\n");
        return 1;
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioSetMode(SERVO_GPIO, PI_SERVO_OUTPUT);

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioWrite(TRIGGER_GPIO, 1);
    usleep(10);
    gpioWrite(TRIGGER_GPIO, 0);

    while (running) {
        usleep(100000);
        gpioSetMode(TRIGGER_GPIO, PI_INPUT);
    }

    gpioTerminate();
    return 0;
}

