#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <sys/mman.h>

#define I2C_BUS 1
#define GPIO_INTERRUPT_PIN 27
#define LOG_FILE "proximity.log"
#define DEFAULT_I2C_ADDR 0x60
#define DEFAULT_THRESHOLD 1000

int i2c_fd;
unsigned char i2c_addr;
unsigned short threshold;
pthread_t i2c_read_thread;
volatile int interrupt_flag = 0;

void i2c_read(void *arg) {
    unsigned char buf[2];
    while (1) {
        if (i2c_read_reg16_polled(i2c_fd, i2c_addr, 0x08, buf, 2) < 0) {
            perror("i2c_read_reg16_polled");
            break;
        }
        if (interrupt_flag) {
            interrupt_flag = 0;
            time_t rawtime;
            struct tm *timeinfo;
            char time_str[32];

            rawtime = time(NULL);
            timeinfo = localtime(&rawtime);
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s, %d, %s\n", time_str, buf[0] | (buf[1] << 8),
                   buf[0] | (buf[1] << 8) > threshold ? "ALERT" : "SAFE");

            if (freopen(LOG_FILE, "a", stdout) == NULL) {
                perror("freopen");
            }
        }
    }
}

int main(int argc, char *argv[]) {
    int ret;
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (argc > 1 && !strcmp(argv[1], "--help")) {
        printf("Usage: %s [-a <i2c_address>] [-t <threshold>]\n", argv[0]);
        return 0;
    }

    i2c_addr = DEFAULT_I2C_ADDR;
    threshold = DEFAULT_THRESHOLD;

    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "-a")) {
            i++;
            if (i < argc) {
                i2c_addr = strtol(argv[i], NULL, 16);
            } else {
                fprintf(stderr, "Missing argument for -a\n");
                return 1;
            }
        } else if (!strcmp(argv[i], "-t")) {
            i++;
            if (i < argc) {
                threshold = atoi(argv[i]);
            } else {
                fprintf(stderr, "Missing argument for -t\n");
                return 1;
            }
        }
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, i2c_addr * 2);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        return 1;
    }

    ret = gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT);
    if (ret < 0) {
        perror("gpioSetMode");
        return 1;
    }

    ret = gpioSetIntDebounce(GPIO_INTERRUPT_PIN, 100);
    if (ret < 0) {
        perror("gpioSetIntDebounce");
        return 1;
    }

    ret = gpioSetIntEdgeType(GPIO_INTERRUPT_PIN, PI_RISING_EDGE);
    if (ret < 0) {
        perror("gpioSetIntEdgeType");
        return 1;
    }

    ret = gpioSetAlertFunc(GPIO_INTERRUPT_PIN, interrupt_handler);
    if (ret < 0) {
        perror("gpioSetAlertFunc");
        return 1;
    }

    ret = pthread_create(&i2c_read_thread, NULL, i2c_read, NULL);
    if (ret != 0) {
        perror("pthread_create");
        return 1;
    }

    gpioTerm();
    return 0;
}

void interrupt_handler(int gpio, uint32_t events) {
    if (events & PI_INTEDGE_RISING_EDGE) {
        interrupt_flag = 1;
    }
}

