#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 200
#define TIMEOUT 200000
#define FREQUENCY_MIN 200
#define FREQUENCY_MAX 2000
#define LOG_BASE 10
#define PWM_FREQ 8000
#define PWM_DUTY_CYCLE 50

static volatile int running = 1;

void sigint_handler(int signum) {
    running = 0;
    gpioTerm(0);
    exit(0);
}

void sigterm_handler(int signum) {
    running = 0;
    gpioTerm(0);
    exit(0);
}

double map_distance_to_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1;
    }

    return FREQUENCY_MIN + (FREQUENCY_MAX - FREQUENCY_MIN) * exp(log(FREQUENCY_MAX / FREQUENCY_MIN) * distance / (MAX_DISTANCE - MIN_DISTANCE));
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    double frequency = FREQUENCY_MIN;

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        double distance = gpioWaveTxBusy(TIMEOUT) ? -1 : (gpioRead(ECHO_PIN) == 0) ? -1 : (1.0 * gpioWaveTxTime() * 343 / 2) / 1000.0;

        if (distance >= 0) {
            frequency = map_distance_to_frequency(distance);
        }

        if (frequency >= 0) {
            gpioHardwarePWM(SPEAKER_PIN, PWM_FREQ, frequency * PWM_DUTY_CYCLE);
        }

        usleep(100000);
    }

    gpioTerm(0);
    return 0;
}

