#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIN_DIST 5.0
#define MAX_DIST 50.0
#define MIN_FREQ 200.0
#define MAX_FREQ 2000.0
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define PULSE_WIDTH_TIMEOUT 100000

static double last_distance = NAN;
static double last_frequency = NAN;

void sigint_handler(int signum) {
    gpioTerm();
    exit(0);
}

double map_distance(double distance) {
    return MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    signal(SIGINT, sigint_handler);

    while (1) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelayUs(10);
        gpioWrite(TRIGGER_PIN, 0);

        uint32_t start_time = gpioGetTicks();
        uint32_t end_time = start_time;
        double pulse_width_us = 0.0;

        while ((gpioRead(ECHO_PIN) == 0) && (end_time - start_time < PULSE_WIDTH_TIMEOUT)) {
            end_time = gpioGetTicks();
        }

        if (end_time - start_time >= PULSE_WIDTH_TIMEOUT) {
            fprintf(stderr, "Error: Timeout while waiting for echo pulse\n");
            pulse_width_us = last_distance ? last_distance * 1000000.0 : NAN;
        } else {
            pulse_width_us = (end_time - start_time) / 1000.0;
        }

        double distance = pulse_width_us / 58.2;
        double frequency = map_distance(distance);

        if (!isnan(distance) && !isnan(frequency)) {
            last_distance = distance;
            last_frequency = frequency;
        }

        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        gpioHardwarePWM(BUZZER_PIN, frequency, 1000000.0 / 2); // 50% duty cycle
        usleep(10000); // 10 ms delay
    }

    gpioTerm();
    return 0;
}

