#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000
#define PULSE_WIDTH_US 10
#define SPEED_OF_SOUND_CM_US 29.1

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

double measure_distance() {
    double pulse_start = gpioRead(ECHO_PIN);
    gpioWrite(TRIGGER_PIN, 1);
    usleep(PULSE_WIDTH_US * 1000);
    gpioWrite(TRIGGER_PIN, 0);

    double pulse_end = gpioRead(ECHO_PIN);
    double pulse_duration = pulse_end - pulse_start;

    if (pulse_duration > TIMEOUT_US) {
        return -1.0;
    }

    return pulse_duration * SPEED_OF_SOUND_CM_US / 2.0 / 1000.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

