    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);

    while (!exit_flag) {
        double distance = measure_distance();

        if (distance < 2.0 || distance > 400.0) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < 10.0) {
                printf("  Too close!\n");
            }
            printf("\n");
        }

        usleep(500000);
    }

    gpioTerminate();
    return 0;
}

