code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SPI_MODE 0
#define SPI_DATA_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_HOLD_TIME 100
#define SENSOR_CS_PIN 8
#define SENSOR_REG_ADDRESS_LOW 0x0C
#define SENSOR_REG_ADDRESS_HIGH 0x0D
#define SENSOR_REG_CONTINUOUS_MODE 0x01
#define SENSOR_REG_RANGE_5M 0x00
#define SENSOR_REG_TRIGGER 0x00
#define SENSOR_REG_DATA_LOW 0x0C
#define SENSOR_REG_DATA_HIGH 0x0D
#define LOG_FILE "distance_log.csv"

static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

void sigint_handler(int signum) {
    close_resources();
    exit(0);
}

void sigterm_handler(int signum) {
    close_resources();
    exit(0);
}

void close_resources() {
    if (g_spi_handle != -1) {
        gpioTerm(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for sensor CS pin\n");
        return -1;
    }

    g_spi_handle = gpioOpen(0, GPIO_SPI, SPI_MODE, SPI_DATA_MODE, SPI_BITS_PER_WORD);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        return -1;
    }

    return 0;
}

int init_sensor() {
    if (gpioWrite(SENSOR_CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to write to sensor CS pin\n");
        return -1;
    }

    if (spiXfer(g_spi_handle, &SENSOR_REG_ADDRESS_LOW, &SENSOR_REG_CONTINUOUS_MODE, 1, 1, SPI_MODE, SPI_MODE, SPI_MAX_HOLD_TIME) < 0) {
        fprintf(stderr, "Failed to write to sensor register 0x01\n");
        return -1;
    }

    if (spiXfer(g_spi_handle, &SENSOR_REG_ADDRESS_LOW, &SENSOR_REG_RANGE_5M, 1, 1, SPI_MODE, SPI_MODE, SPI_MAX_HOLD_TIME) < 0) {
        fprintf(stderr, "Failed to write to sensor register 0x02\n");
        return -1;
    }

    if (spiXfer(g_spi_handle, &SENSOR_REG_ADDRESS_LOW, &SENSOR_REG_TRIGGER, 1, 1, SPI_MODE, SPI_MODE, SPI_MAX_HOLD_TIME) < 0) {
        fprintf(stderr, "Failed to trigger sensor measurement\n");
        return -1;
    }

    usleep(10000); // Wait for sensor to stabilize

    return 0;
}

uint16_t read_sensor() {
    uint16_t data_low, data_high;

    if (gpioWrite(SENSOR_CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to write to sensor CS pin\n");
        return 0;
    }

    if (spiXfer(g_spi_handle, &SENSOR_REG_ADDRESS_LOW, &data_low, 1, 2, SPI_MODE, SPI_MODE, SPI_MAX_HOLD_TIME) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return 0;
    }

    data_high = data_low;
    data_low <<= 8;
    data_high >>= 8;
    data_low |= data_high;

    gpioWrite(SENSOR_CS_PIN, 1);

    if (data_low == 0xFFFF) {
        // Sensor-absent condition
        fprintf(stderr, "Sensor-absent condition detected\n");
        return 0;
    }

    return data_low;
}

void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (g_log_file == NULL) {
        g_log_file = fopen(LOG_FILE, "a");
        if (g_log_file == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    fprintf(g_log_file, "%s,%d\n", time_str, distance);
    fflush(g_log_file);
}

int main(int argc, char *argv[]) {
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    if (init_pigpio() < 0) {
        return 1;
    }

    if (init_sensor() < 0) {
        close_resources();
        return 1;
    }

    g_log_file = fopen(LOG_FILE, "w");
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        close_resources();
        return 1;
    }

    fprintf(g_log_file, "Time,Distance (mm)\n");
    fflush(g_log_file);

    while (1) {
        uint16_t distance = read_sensor();
        if (distance > 0) {
            log_distance(distance);
        }
        usleep(100000); // 100 ms delay between readings
    }

    close_resources();
    return 0;
}

