#define I2C_BUS 1
#define SI1120_ADDR 0x60
#define SI1120_ID 0x41
#define ALS_REG 0x22
#define ALS_REG_LEN 2
#define PS_REG 0x18
#define PS_REG_LEN 2
#define RETRY_COUNT 3
#define DELAY_MS 10
#define LOG_FILE "si1120_log.txt"

int init_pigpio(void);
void deinit_pigpio(void);
int init_i2c(void);
void deinit_i2c(void);
int read_reg(uint8_t reg, uint8_t *buf, size_t len);
void log_timestamped_data(const char *tag, uint16_t als, uint16_t ps);

int main(void) {
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        deinit_pigpio();
        return 1;
    }

    if (reset_sensor() != 0) {
        fprintf(stderr, "Failed to reset the sensor\n");
        deinit_i2c();
        deinit_pigpio();
        return 1;
    }

    if (check_part_id() != 0) {
        fprintf(stderr, "Invalid Si1120 part ID\n");
        deinit_i2c();
        deinit_pigpio();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        deinit_i2c();
        deinit_pigpio();
        return 1;
    }

    while (1) {
        uint8_t als_buf[ALS_REG_LEN];
        uint8_t ps_buf[PS_REG_LEN];
        if (read_reg(ALS_REG, als_buf, ALS_REG_LEN) != 0 ||
            read_reg(PS_REG, ps_buf, PS_REG_LEN) != 0) {
            fprintf(stderr, "Failed to read ALS or PS data\n");
            continue;
        }

        uint16_t als = ((als_buf[0] << 8) | als_buf[1]);
        uint16_t ps = ((ps_buf[0] << 8) | ps_buf[1]);
        log_timestamped_data("ALS", als, ps);
        log_timestamped_data("PS", als, ps);

        usleep(500000); // 500 ms delay
    }

    fclose(log_file);
    deinit_i2c();
    deinit_pigpio();
    return 0;
}

int reset_sensor(void) {
    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (i2cWrite(SI1120_ADDR, 0x30, &0x01, 1) == 1) {
            return 0;
        }
        usleep(DELAY_MS * 1000);
    }
    return -1;
}

int check_part_id(void) {
    uint8_t buf[1];
    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (read_reg(0x00, buf, 1) == 1 && buf[0] == SI1120_ID) {
            return 0;
        }
        usleep(DELAY_MS * 1000);
    }
    return -1;
}

int read_reg(uint8_t reg, uint8_t *buf, size_t len) {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cReadRegisters(SI1120_ADDR, reg, buf, len) == len) {
            return 0;
        }
        usleep(DELAY_MS * 1000);
        --retries;
    }
    return -1;
}

