    fprintf(log_file, "%s: ALS=%04x PS=%04x\n", timestamp, als, ps);
}

int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }
    return 0;
}

void deinit_pigpio(void) {
    gpioTerminate();
}

