    if (i2cOpen(I2C_BUS, &pii_i2c_handle) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

void deinit_i2c(void) {
    i2cClose(pii_i2c_handle);
}

