#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x39
#define REG_ID 0x00
#define REG_RATE 0x08
#define REG_ALS_MSB 0x22
#define REG_ALS_LSB 0x23
#define REG_PROX_MSB 0x24
#define REG_PROX_LSB 0x25
#define LUX_SCALE 0.1

static int i2c_file;
static char log_file[] = "biometric_log.txt";

void i2c_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int i2c_init() {
    i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Failed to talk to Si1182: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

void i2c_cleanup() {
    close(i2c_file);
    remove(log_file);
}

void sigint_handler(int signum) {
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

void log_data(const char *timestamp, uint16_t als_msb, uint16_t als_lsb,
              uint16_t prox_msb, uint16_t prox_lsb) {
    FILE *log_fd = fopen(log_file, "a");
    if (!log_fd) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_fd, "%s,%u,%u,%u,%u\n", timestamp, (als_msb << 8) | als_lsb,
            (prox_msb << 8) | prox_lsb, als_msb, als_lsb);
    fclose(log_fd);
}

int main() {
    struct sigaction sa;
    int ret;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    ret = sigaction(SIGINT, &sa, NULL);
    if (ret < 0) {
        i2c_error("Failed to set SIGINT handler");
    }

    sa.sa_handler = sigterm_handler;
    ret = sigaction(SIGTERM, &sa, NULL);
    if (ret < 0) {
        i2c_error("Failed to set SIGTERM handler");
    }

    if (i2c_init() < 0) {
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_file, I2C_FD_SWITCHING, 1) < 0) {
        i2c_error("Failed to enable fast mode");
    }

    uint8_t part_id[2];
    ret = read(i2c_file, part_id, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read part ID: %s\n", strerror(errno));
        goto cleanup;
    }

    if (part_id[0] != 0x11 || part_id[1] != 0x82) {
        fprintf(stderr, "Invalid Si1182 part ID\n");
        goto cleanup;
    }

    ret = ioctl(i2c_file, I2C_CLAIM_FLAG, I2C_CLAIM_FLAG_FORCE);
    if (ret < 0) {
        i2c_error("Failed to claim I2C bus");
    }

    ret = ioctl(i2c_file, I2C_SET_SCL_SPEED, 400);
    if (ret < 0) {
        i2c_error("Failed to set I2C SCL speed");
    }

    ret = ioctl(i2c_file, I2C_ALGO_ADDR_10BIT, 1);
    if (ret < 0) {
        i2c_error("Failed to enable 10-bit addressing");
    }

    ret = ioctl(i2c_file, I2C_SET_SLAVE_FORCE, SI1182_ADDR << 1);
    if (ret < 0) {
        i2c_error("Failed to set slave address");
    }

    ret = ioctl(i2c_file, I2C_SET_RETRY, 3);
    if (ret < 0) {
        i2c_error("Failed to set I2C retry count");
    }

    ret = ioctl(i2c_file, I2C_SET_TIMEOUT, 100);
    if (ret < 0) {
        i2c_error("Failed to set I2C timeout");
    }

    uint8_t rate = 0x07;
    ret = write(i2c_file, &rate, 1);
    if (ret != 1) {
        i2c_error("Failed to set measurement rate");
        goto cleanup;
    }

