#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define PROXIMITY_LOG "proximity_log.txt"

static int i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(fd, reg, value) < 0) {
        perror("i2cWriteByteData");
        return -1;
    }
    return 0;
}

static int i2c_read_byte_data(int fd, uint8_t reg) {
    uint8_t data;
    if (i2cReadByteData(fd, reg, &data) < 0) {
        perror("i2cReadByteData");
        return -1;
    }
    return data;
}

static void init_sensor(int *i2c_fd) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if ((*i2c_fd = i2cOpen(I2C_BUS, SI1145_ADDR)) < 0) {
        fprintf(stderr, "Failed to open I2C connection to Si1145\n");
        exit(EXIT_FAILURE);
    }

    if (i2c_write_byte_data(*i2c_fd, 0x07, 0x03) ||
        i2c_write_byte_data(*i2c_fd, 0x06, 0x02) ||
        i2c_write_byte_data(*i2c_fd, 0x1A, 0x00) ||
        i2c_write_byte_data(*i2c_fd, 0x21, 0x0B) ||
        i2c_write_byte_data(*i2c_fd, 0x22, 0x49) ||
        i2c_write_byte_data(*i2c_fd, 0x0C, 0x03) ||
        i2c_write_byte_data(*i2c_fd, 0x0F, 0x0F) ||
        i2c_write_byte_data(*i2c_fd, 0x11, 0x01) ||
        i2c_write_byte_data(*i2c_fd, 0x0D, 0x07) ||
        i2c_write_byte_data(*i2c_fd, 0x80, 0x03)) {

        fprintf(stderr, "Failed to initialise Si1145 sensor\n");
        exit(EXIT_FAILURE);
    }
}

static void log_proximity(uint16_t proximity, const char *timestamp) {
    int fd = open(PROXIMITY_LOG, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        perror("open");
        return;
    }

    char log_line[128];
    snprintf(log_line, sizeof(log_line), "%s %u\n", timestamp, proximity);
    write(fd, log_line, strlen(log_line));
    close(fd);
}

static void read_proximity(int *i2c_fd) {
    uint16_t proximity = (i2c_read_byte_data(*i2c_fd, 0x16) << 8) | i2c_read_byte_data(*i2c_fd, 0x17);
    log_proximity(proximity, ctime(&time(NULL)));
}

static void sigint_handler(int sig) {
    i2cClose(*i2c_fd);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_fd;
    init_sensor(&i2c_fd);

    while (1) {
        int retries = 3;
        while (retries > 0 && i2c_read_byte_data(i2c_fd, 0x00) != 0x68) {
            usleep(100000);
            retries--;
        }

        if (retries == 0) {
            fprintf(stderr, "Failed to communicate with Si1145 sensor\n");
            exit(EXIT_FAILURE);
        }

        read_proximity(&i2c_fd);
        usleep(2000000); // Wait 2 seconds before the next reading
    }

    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

