#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define SAMPLE_INTERVAL 1000
#define TRIGGER_PULSE_WIDTH 10

static volatile bool measurement_in_progress = false;
static time_t last_measurement_time = 0;
static uint32_t echo_rising_edge_time = 0;
static uint32_t echo_falling_edge_time = 0;

void echo_alert_cb(uint32_t gpio, uint32_t event) {
    if (!measurement_in_progress) {
        return;
    }

    measurement_in_progress = false;

    if (event & PI_EDGE_RISING_EDGE) {
        echo_rising_edge_time = gpioGetTime();
    } else if (event & PI_EDGE_FALLING_EDGE) {
        echo_falling_edge_time = gpioGetTime();
        double time_diff = (echo_falling_edge_time - echo_rising_edge_time) / 1000000.0;
        double distance_cm = (time_diff * 0.0343) / 2;

        if (distance_cm < 20) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }

        printf("Distance: %.2f cm\n", distance_cm);
        last_measurement_time = time(NULL);
    }
}

void signal_handler(int sig) {
    gpioTerm();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        goto cleanup;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, PI_EDGE_BOTH, echo_alert_cb, NULL) < 0) {
        fprintf(stderr, "Failed to set echo pin alert function\n");
        goto cleanup;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelayUs(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelayUs(50);
    gpioWrite(TRIGGER_PIN, 0);

    while (1) {
        if (time(NULL) - last_measurement_time >= SAMPLE_INTERVAL) {
            measurement_in_progress = true;
        }
        usleep(100000);
    }

cleanup:
    gpioTerm();
    return 0;
}

