Here's a C program that fulfills the user's request using the pigpio library. This code initializes the ultrasonic sensor and servo motor, measures distance, displays it in centimeters, and rotates the servo motor proportionally to the distance.

```c
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MID_PULSE 1500
#define UPDATE_INTERVAL 100000
#define TIMEOUT 50000

static volatile int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

double measure_distance() {
    double distance = -1.0;
    gpioWrite(TRIGGER_PIN, 0);
    usleep(2);
    gpioWrite(TRIGGER_PIN, 1);
    usleep(10);
    gpioWrite(TRIGGER_PIN, 0);

    long start_time = time(NULL);
    long elapsed_time;
    long echo_time;

    while ((gpioRead(ECHO_PIN) == 0) && (time(NULL) - start_time < TIMEOUT)) {}
    elapsed_time = time(NULL) - start_time;
    start_time = time(NULL);

    while ((gpioRead(ECHO_PIN) == 1) && (time(NULL) - start_time < TIMEOUT)) {}
    echo_time = time(NULL) - start_time;

    if (echo_time > 0) {
        distance = (echo_time * 34300) / (2 * 1000);
    }

    return distance;
}

void set_servo_angle(int angle) {
    int pulse_width = SERVO_MIN_PULSE + (angle * ((SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180.0));
    gpioWrite(SERVO_PIN, 1);
    gpioDelay(pulse_width);
    gpioWrite(SERVO_PIN, 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    while (running) {
        double distance = measure_distance();

        if (distance >= 0) {
            int servo_angle = (MAX_DISTANCE - distance) * 90.0 / (MAX_DISTANCE - MIN_DISTANCE);
            set_servo_angle(servo_angle);
            printf("Distance: %.1f cm, Servo angle: %.1f degrees\n", distance, servo_angle);
        }

        usleep(UPDATE_INTERVAL);
    }

    gpioTerminate();
    return 0;
}
```

This code initializes the pigpio library, sets the trigger, echo, and servo pins, and handles SIGINT signals. It measures the distance using the HC-SR04 ultrasonic sensor and displays it in centimeters. The servo motor angle is set proportionally to the distance, and the program runs continuously until it receives a SIGINT signal. When the program receives a SIGINT signal, it stops the servo motor, terminates the pigpio library, and exits cleanly.

