#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SI7005_I2C_BUS 1
#define SI7005_I2C_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUM_REG 0x02

static int g_i2c_handle = -1;
static int g_initialized = 0;

void i2c_write_byte(uint8_t addr, uint8_t data) {
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C handle not initialized\n");
        return;
    }

    if (i2cWrite(g_i2c_handle, (uint16_t)addr << 1 | 0, &data, 1, 10) < 0) {
        fprintf(stderr, "I2C write failed\n");
        close(g_i2c_handle);
        g_i2c_handle = -1;
        g_initialized = 0;
    }
}

uint16_t i2c_read_word(uint8_t addr) {
    uint16_t data;
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C handle not initialized\n");
        return 0;
    }

    if (i2cRead(g_i2c_handle, (uint16_t)addr << 1 | 1, &data, 2, 10) < 2) {
        fprintf(stderr, "I2C read failed\n");
        close(g_i2c_handle);
        g_i2c_handle = -1;
        g_initialized = 0;
        return 0;
    }

    return data;
}

void i2c_init() {
    if (g_initialized) {
        return;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        exit(1);
    }

