    uint16_t data;
    if (g_i2c_handle < 0) {
        fprintf(stderr, "I2C handle not initialized\n");
        return 0;
    }

    if (i2cRead(g_i2c_handle, (uint16_t)addr << 1 | 1, &data, 2, 10) < 2) {
        fprintf(stderr, "I2C read failed\n");
        close(g_i2c_handle);
        g_i2c_handle = -1;
        g_initialized = 0;
        return 0;
    }

