    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 2;
    i2c_msg[0].buf = data;
    i2c_msg[1].addr = MPU_ADDR;
    i2c_msg[1].flags = I2C_M_NOSTART | I2C_M_NOSTOP;
    i2c_msg[1].len = 0;

    ret = i2c_rdwr(i2c_fd, i2c_msg, 2);
    if (ret != 2) {
        perror("Failed to send reset command");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    usleep(100000); // Wait for the MPU-6050 to stabilize

    // Clear sleep bit
    data[0] = 0x6B;
    data[1] = 0x08;
    i2c_msg[0].len = 2;
    i2c_msg[1].len = 0;

    ret = i2c_rdwr(i2c_fd, i2c_msg, 2);
    if (ret != 2) {
        perror("Failed to clear sleep bit");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

