    data[0] = 0x19;
    data[1] = 0x07;
    i2c_msg[0].len = 2;
    i2c_msg[1].len = 0;

    ret = i2c_rdwr(i2c_fd, i2c_msg, 2);
    if (ret != 2) {
        perror("Failed to set sample-rate divider");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

