    data[0] = 0x1C;
    data[1] = 0x10; // ±2 g range
    data[2] = 0x1B;
    data[3] = 0x18; // ±250 deg/s range

    i2c_msg[0].len = 4;
    i2c_msg[1].len = 0;

    ret = i2c_rdwr(i2c_fd, i2c_msg, 2);
    if (ret != 2) {
