        i2c_msg[0].addr = MPU_ADDR;
        i2c_msg[0].flags = 0;
        i2c_msg[0].len = 14;
        i2c_msg[0].buf = data;
        i2c_msg[1].addr = MPU_ADDR;
        i2c_msg[1].flags = I2C_M_RD;
        i2c_msg[1].len = 0;

