        if (ret != 2) {
            perror("Failed to read data from MPU-6050");
            continue;
        }

        accel_x = (data[12] << 8) | data[11];
        accel_y = (data[14] << 8) | data[13];
        accel_z = (data[16] << 8) | data[15];
        temp = (data[20] << 8) | data[19];
        gyro_x = (data[22] << 8) | data[21];
        gyro_y = (data[24] << 8) | data[23];
        gyro_z = (data[26] << 8) | data[25];

        printf("Accelerometer: %.2f %.2f %.2f\n", accel_x / 16384.0, accel_y / 16384.0, accel_z / 16384.0);
        printf("Temperature: %.1f °C\n", temp / 340.0 + 36.53);
        printf("Gyroscope: %.2f %.2f %.2f\n", gyro_x / 131.0, gyro_y / 131.0, gyro_z / 131.0);
        printf("\n");

        usleep(100000); // Wait 100 ms before the next read
    }

    // Handle SIGINT and SIGTERM
    signal(SIGINT, [](int signum) {
        close(i2c_fd);
        gpioTerminate();
        exit(0);
    });
    signal(SIGTERM, [](int signum) {
        close(i2c_fd);
        gpioTerminate();
        exit(0);
    });

    return 0;
}

