#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_MEASURE_HIGH_REP 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

int main(void) {
    int i2c_bus = 1;
    int i2c_fd;
    int ret;
    unsigned char data[8];
    unsigned short temp_raw, humidity_raw;
    float temp, humidity;
    unsigned char crc_calculated, crc_received;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(i2c_bus, SHT40_ADDR, &ret);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", i2c_bus, strerror(ret));
        goto cleanup;
    }

    while (1) {
        ret = pigpio_i2c_write_read(i2c_fd, &SHT40_CMD_MEASURE_HIGH_REP, 1, data, 8);
        if (ret < 0) {
            fprintf(stderr, "I2C read/write error: %s\n", strerror(ret));
            goto cleanup;
        }

        if (data[0] != SHT40_CMD_MEASURE_HIGH_REP) {
            fprintf(stderr, "Invalid command response\n");
            continue;
        }

        usleep(10000); // Wait at least 10 ms for the measurement to complete

        ret = pigpio_i2c_read_data(i2c_fd, data, 6);
        if (ret < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(ret));
            goto cleanup;
        }

        temp_raw = (data[1] << 8) | data[0];
        crc_calculated = crc8(data, 2, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INIT);
        crc_received = data[3];
        if (crci8(data + 2, 4, SHT40_CRC_POLYNOMIAL, SHT40_CRC_INIT) != crc_received) {
            fprintf(stderr, "Invalid CRC\n");
            continue;
        }

        temp = -45.0 + 175.0 * (float)temp_raw / 65535;
        humidity_raw = (data[5] << 8) | data[4];
        humidity = -6.0 + 125.0 * (float)humidity_raw / 65535;
        if (humidity < 0.0 || humidity > 100.0) {
            fprintf(stderr, "Invalid humidity value\n");
            continue;
        }

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humidity);

        sleep(5);
    }

cleanup:
    close(i2c_fd);
    gpioTerm();
    return 0;
}

unsigned char crc8(const unsigned char *data, int len, unsigned char poly, unsigned char init) {
    unsigned char crc = init;
    while (len--) {
        crc ^= *data++;
        for (int i = 0; i < 8; ++i) {
            if (crc & 0x80)
                crc = (crc << 1) ^ poly;
            else
                crc <<= 1;
        }
    }
    return crc;
}

unsigned char crci8(const unsigned char *data, int len, unsigned char poly, unsigned char init) {
    return crc8(data, len, poly, init);
}

