#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x5A

struct i2c_data {
    char *dev_name;
    int file;
    void *map_base;
};

int i2c_init(struct i2c_data *data) {
    int ret;
    if ((ret = open(data->dev_name, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    data->file = ret;

    if ((ret = ioctl(data->file, I2C_SLAVE, SENSOR_ADDR)) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(data->file);
        return -1;
    }

    return 0;
}

void i2c_cleanup(struct i2c_data *data) {
    if (data->map_base)
        munmap(data->map_base, 4096);

    if (data->file >= 0)
        close(data->file);
