#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

static const uint8_t cmd_config[] = {0x36, 0x08};
static const uint8_t crc_table[16] = {
    0x00, 0x1D, 0x3A, 0x23, 0x54, 0x47, 0x78, 0x65, 0x90, 0x81, 0xB2, 0xA9, 0xD6, 0xCB, 0xE8, 0xFF
};

void crc8(uint8_t *data, size_t len, uint8_t *crc) {
    uint8_t crc_reg = *crc;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc_reg = (crc_reg & 0x80) ? (crc_reg << 1) ^ CRC_POLYNOMIAL : crc_reg << 1;
            crc_reg ^= data[i];
        }
    }
    *crc = crc_reg;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (i2c_open(I2C_BUS, 1000000) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (i2c_write_read(SENSOR_ADDR, cmd_config, sizeof(cmd_config), NULL, 0) < 0) {
        fprintf(stderr, "Failed to write configuration to sensor\n");
        return 1;
    }

    FILE *log_file = fopen("pressure_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    if (fprintf(log_file, "timestamp,pressure(Pa),temperature(°C)\n") < 0) {
        perror("Failed to write header row");
        fclose(log_file);
        return 1;
    }

    time_t rawtime;
    struct tm *time_info;
    char time_str[32];

    while (1) {
        uint8_t data[9];
        if (i2c_write_read(SENSOR_ADDR, NULL, 0, data, sizeof(data)) < 0) {
            perror("Failed to read data from sensor");
            continue;
        }

        uint8_t crc_calculated = crc8(data, sizeof(data) - 1, NULL);
        if (data[sizeof(data) - 1] != crc_calculated) {
            fprintf(stderr, "Invalid CRC checksum\n");
            continue;
        }

        time(&rawtime);
        time_info = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%SZ", time_info);

        float pressure = (data[0] | data[1] << 8) / 10.0f;
        float temperature = (data[2] | data[3] << 8) / 10.0f;

        if (fprintf(log_file, "%s,%f,%f\n", time_str, pressure, temperature) < 0) {
            perror("Failed to write data to log file");
            break;
        }

        sleep(1);
    }

    fclose(log_file);

    i2c_close();
    gpioTerminate();

    return 0;
}

