#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <sys/time.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_REPEATABILITY 0xFD

static const uint8_t crc_poly = 0x31;

uint8_t sht40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit; --bit) {
            crc = (crc & 0x80) ? (crc << 1 ^ crc_poly) : (crc << 1);
            crc ^= data[i] & 0x01;
            data[i] >>= 1;
        }
    }
    return crc;
}

double sht40_temperature(uint16_t raw) {
    return -45.0 + 175.0 * raw / 65535;
}

double sht40_humidity(uint16_t raw) {
    return 100.0 * raw / 65535;
}

int main(void) {
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    struct timeval tv;
    uint8_t buf[8];
    int ret;

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR << 1) < 0) {
        perror("Failed to talk to SHT40");
        goto cleanup;
    }

    log_fp = fopen("sht40_log.txt", "w");
    if (!log_fp) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        usleep(10000); // Wait at least 10 ms for the measurement to complete before reading

        if (write(i2c_fd, &SHT40_CMD_HIGH_REPEATABILITY, 1) != 1) {
            perror("Failed to write command to SHT40");
            continue;
        }

        if (read(i2c_fd, buf, 6) != 6) {
            perror("Failed to read data from SHT40");
            continue;
        }

        uint16_t temp_raw = (buf[0] << 8) | buf[1];
        uint16_t hum_raw = (buf[3] << 8) | buf[4];
        uint8_t temp_crc = buf[2];
        uint8_t hum_crc = buf[5];

        if (sht40_crc8(&buf[0], 6) != (temp_crc ^ hum_crc)) {
            fprintf(stderr, "CRC error\n");
            continue;
        }

        double temp = sht40_temperature(temp_raw);
        double hum = sht40_humidity(hum_raw);

        gettimeofday(&tv, NULL);
        fprintf(log_fp, "%lu.%06lu, %f, %f\n", tv.tv_sec, tv.tv_usec, temp, hum);

        sleep(5);
    }

cleanup:
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);

    return 0;
}

