#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define COMMAND_CONTINUOUS_MEASUREMENT 0x362F

struct i2c_rdwr_ioctl_data {
    __u16 num_msgs;
    __u16 msgs;
    __u32 timeout;
    struct i2c_msg *msgs;
};

struct i2c_msg {
    __u16 addr;
    __u16 flags;
    __u16 len;
    __u8 *buf;
};

int open_i2c_device(void) {
    int file;
    const char *filename = "/dev/i2c-" I2C_BUS;

    if ((file = open(filename, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    return file;
}

void close_i2c_device(int file) {
    close(file);
}

int i2c_write(int file, __u8 *buf, size_t len) {
    struct i2c_msg msg = {
        .addr = SENSOR_ADDR,
        .flags = 0,
        .len = len,
        .buf = buf
    };

    struct i2c_rdwr_ioctl_data data = {
        .num_msgs = 1,
        .msgs = &msg,
        .timeout = 1000
    };

    if (ioctl(file, I2C_RDWR, &data) < 0) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    return 0;
}

int i2c_read(int file, __u8 *buf, size_t len) {
    struct i2c_msg msg = {
        .addr = SENSOR_ADDR,
        .flags = I2C_M_RD,
        .len = len,
        .buf = buf
    };

    struct i2c_rdwr_ioctl_data data = {
        .num_msgs = 1,
        .msgs = &msg,
        .timeout = 1000
    };

    if (ioctl(file, I2C_RDWR, &data) < 0) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    return 0;
}

uint8_t crc8_ccitt(const uint8_t *data, size_t len) {
    uint8_t crc = 0;

    for (size_t i = 0; i < len; ++i) {
        for (int bit = 8; bit > 0; --bit) {
            crc ^= (crc & 0x80) >> 7;
            crc <<= 1;
            crc ^= (data[i] & 0x01) << 7;
            data[i] >>= 1;
        }
    }

    return crc;
}

int main(void) {
    int file = open_i2c_device();

    if (file < 0) {
        return EXIT_FAILURE;
    }

    i2c_write(file, &COMMAND_CONTINUOUS_MEASUREMENT, 1);
    sleep(0.045);

    __u8 pressure_buf[4] = {0};
    __u8 temperature_buf[4] = {0};
    __u8 scale_factor_buf[4] = {0};

    i2c_read(file, pressure_buf, 3);
    if (crc8_ccitt(pressure_buf, 3) != pressure_buf[3]) {
        fprintf(stderr, "Invalid pressure CRC\n");
        goto cleanup;
    }

    i2c_read(file, &pressure_buf[3], 1);

    i2c_read(file, temperature_buf, 3);
    if (crc8_ccitt(temperature_buf, 3) != temperature_buf[3]) {
        fprintf(stderr, "Invalid temperature CRC\n");
        goto cleanup;
    }

    i2c_read(file, &temperature_buf[3], 1);

    i2c_read(file, scale_factor_buf, 3);
    if (crc8_ccitt(scale_factor_buf, 3) != scale_factor_buf[3]) {
        fprintf(stderr, "Invalid scale factor CRC\n");
        goto cleanup;
    }

    float pressure = (float)pressure_buf[0] | ((float)pressure_buf[1] << 8) | ((float)pressure_buf[2] << 16) / scale_factor_buf[0];
    float temperature = (float)temperature_buf[0] / 200.0 - 45.0;

    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    FILE *log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        goto cleanup;
