        log_error_message("CRC mismatch");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    float temp_c = -45.0 + 175.0 * (raw / 65535.0);
    return temp_c;
}

int main(void) {
    int i2c_fd;
    int ret;

    if ((i2c_fd = gpio_i2c_open(I2C_BUS, SENSOR_ADDR)) < 0) {
        log_error_message("I2C initialization failure");
        return 1;
    }

    signal(SIGINT, SIG_DFL);

