    log_file = fopen(log_filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    uint8_t cmd[] = {0x36, 0x2F, 0x00}; // Continuous measurement command
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        perror("Failed to write to the sensor");
        goto cleanup;
    }
    usleep(1000); // Wait at least 1 ms

    uint8_t data[6];
    ssize_t bytes_read = read(i2c_fd, data, sizeof(data));
    if (bytes_read != sizeof(data)) {
        perror("Failed to read from the sensor");
        goto cleanup;
    }

    if (crc8(data, 5) != data[5] || crc8(data + 1, 4) != data[6]) {
        fprintf(stderr, "Invalid CRC\n");
        goto cleanup;
    }

    float pressure = (data[0] * 240.0 + data[1]) / 10.0;
    float temperature = (data[3] * 200.0 + data[4]) / 16.0 - 45.0;

    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%f,%f\n", time_str, pressure, temperature);

cleanup:
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}
```

This code initializes the I2C bus, opens the log file, sends the continuous measurement command to the sensor, waits for a response, validates the CRC, converts the raw data to pressure and temperature, logs the data, and cleans up resources on exit. It also handles errors and gracefully exits when encountering I2C write/read errors or a sensor-absent path.

