#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x40
#define FAN_GPIO 18
#define BUFFER_SIZE 60

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
volatile size_t head = 0;
volatile size_t tail = 0;

void i2cWriteRead(uint8_t addr, uint8_t reg, uint16_t *tx_buf, uint16_t *rx_buf, size_t len) {
    int ret;
    for (size_t i = 0; i < len; ++i) {
        if ((ret = pigpio_i2cWriteRead(gpiod_num, addr << 1, &reg, 1, tx_buf[i], 2)) < 0) {
            if (i > 2) {
                fprintf(stderr, "Failed to communicate with Si7021: %s\n", strerror(errno));
                return;
            }
            usleep(10000);
        }
        if (ret < 2) {
            fprintf(stderr, "Short read from Si7021: %s\n", strerror(errno));
            return;
        }
        rx_buf[i] = (rx_buf[i] << 8) | rx_buf[i] >> 8;
    }
}

float temperatureFromRaw(uint16_t raw) {
    return 175.72 * raw / 65536.0 - 46.85;
}

float humidityFromRaw(uint16_t raw) {
    return 125.0 * raw / 65536.0 - 6.0;
}

void logReading(Reading reading) {
    if ((head + 1) % BUFFER_SIZE == tail) {
        fprintf(stderr, "Buffer full, dropping a reading\n");
        return;
    }
    buffer[head] = reading;
    head = (head + 1) % BUFFER_SIZE;
}

void printBuffer() {
    for (size_t i = tail; i != head; i = (i + 1) % BUFFER_SIZE) {
        printf("%ld: %.2f °C, %.2f %%\n", buffer[i].timestamp, buffer[i].temperature, buffer[i].humidity);
    }
}

int main() {
    int gpiod_num;
    if ((gpiod_num = pigpio_init()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    time_t last_print = time(NULL);
    while (1) {
        uint16_t temp_raw, hum_raw;
        i2cWriteRead(SENSOR_ADDR, 0xE3, NULL, &temp_raw, 1);
        i2cWriteRead(SENSOR_ADDR, 0xE5, NULL, &hum_raw, 1);
        float temp = temperatureFromRaw(temp_raw);
        float hum = humidityFromRaw(hum_raw);
        Reading reading = {time(NULL), temp, hum};
        logReading(reading);

        if (difftime(time(NULL), last_print) > 2) {
            last_print = time(NULL);
            printBuffer();
        }

        if (temp > 28.0) {
            gpioWrite(FAN_GPIO, 1);
        } else if (temp < 27.0) {
            gpioWrite(FAN_GPIO, 0);
        }
    }

    gpioTerminate();
    gpioTerm();
    pigpio_terminate();
    return 0;
}

