#include <time.h>
#include <pigpio.h>

#define SCD40_ADDR 0x62
#define SCD40_I2C_BUS 1
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

static const char *LOG_FILE = "air_quality.log";
static const char *LOG_FORMAT = "%lu,%d,%.1f,%.1f\n";

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

uint16_t crc8(const uint8_t *data, size_t len) {
    uint16_t crc = CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc >> 1) ^ (crc & 1 ? CRC_POLYNOMIAL : 0);
            crc &= 0xFF;
            crc = (crc << 8) | (data[i] & 0xFF);
        }
    }
    return crc;
}

int main(void) {
    if (gpioInitialise() < 0)
        die("gpioInitialise");

    if (gpioSetMode(SCD40_I2C_BUS, PI_MODE_INOUT) < 0 ||
        gpioSetMode(SCD40_I2C_BUS | PI_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SCD40_I2C_BUS | GPIO_SCL, PI_OUTPUT) < 0 ||
        gpioSetMode(SCD40_I2C_BUS | GPIO_SDA, PI_OUTPUT) < 0)
        die("gpioSetMode");

    if (i2cOpen(SCD40_I2C_BUS, SCD40_ADDR, &i2c_handle) < 0)
        die("i2cOpen");

    if (i2cWriteRead(i2c_handle, 0x21B1, 0, 0, 1) != 1)
        die("Start Periodic Measurement");

    time_t last_log = time(NULL);
    while (1) {
        usleep(5000000); // Wait 5 seconds

        if (i2cRead(i2c_handle, 0xE4B8, 1, &data, 1) != 1)
            die("i2cRead data-ready flag");

        if (data[0] & 0x80) {
            if (i2cRead(i2c_handle, 0xEC05, 9, data + 1, 9) != 9)
                die("i2cRead data");

            uint16_t crc = crc8(data + 1, 7);
            if (crc != ((data[8] << 8) | data[9]))
                die("CRC check failed");

            time_t now = time(NULL);
            double co2 = data[1] | (data[2] << 8);
            double temperature = -45.0 + 175.0 * co2 / (pow(2, 16) - 1);
            double humidity = 100.0 * co2 / (pow(2, 16) - 1);

            FILE *log_file = fopen(LOG_FILE, "a");
            if (!log_file)
                die("fopen log file");

            fprintf(log_file, LOG_FORMAT, now, co2, temperature, humidity);
            fclose(log_file);

            last_log = now;
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

