code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_I2C_BUS 1
#define LED_GPIO 17
#define BUFFER_SIZE 20
#define CRC_POLYNOMIAL 0x31

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
    time_t timestamp;
} SensorData;

SensorData buffer[BUFFER_SIZE];
volatile size_t buffer_head = 0;
volatile size_t buffer_tail = 0;

void sigint_handler(int signum) {
    (void)signum;
    stop_measurement();
    close_i2c();
    gpioTerm(LED_GPIO);
    gpioTerm();
    exit(0);
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return -1;
    }
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    return 0;
}

int init_i2c() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

void stop_measurement() {
    write_i2c(0x00);
}

int write_i2c(uint8_t data) {
    ssize_t ret = write(g_i2c_fd, &data, 1);
    if (ret != 1) {
        perror("write");
        return -1;
    }
    return 0;
}

ssize_t read_i2c(uint8_t *buf, size_t len) {
    ssize_t ret = read(g_i2c_fd, buf, len);
    if (ret < 0) {
        perror("read");
        return -1;
    }
    return ret;
}

uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j > 0; --j) {
            crc = (crc << 1) ^ (crc & 0x80 ? CRC_POLYNOMIAL : 0);
            crc ^= data[i] & 0x01;
            data[i] >>= 1;
        }
    }
    return crc;
}

int read_data() {
    uint8_t buf[9];

    // Start periodic measurement
    if (write_i2c(0x21B1) < 0) {
        return -1;
    }

    // Wait for data ready
    while (!(read_i2c(&buf[0], 1) && (buf[0] & 0x01) == 0) && gpioTerm(LED_GPIO) < 0) {
        usleep(500000);
    }
    if (gpioSetMode(LED_GPIO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    // Read measurement
    if (read_i2c(buf, 9) != 9) {
        perror("read_i2c");
        return -1;
    }

    // Validate CRC-8 checksum
    for (size_t i = 0; i < 6; ++i) {
        if (buf[i] + buf[i + 1] + crc8(&buf[i + 2], 2) != buf[6 + i]) {
            perror("Invalid CRC-8 checksum");
            return -1;
        }
    }

    SensorData *data = &buffer[buffer_head];
    data->co2 = (buf[0] << 8) | buf[1];
    data->temperature = (buf[2] << 8 | buf[3]) / 10.0;
    data->humidity = (buf[4] << 8 | buf[5]) / 100.0;
    data->timestamp = time(NULL);
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;

    if (buffer_head == buffer_tail) {
        printf("Buffer full\n");
    }

    // Print valid reading
    if (buffer_head != buffer_tail) {
        printf("CO2: %d ppm, Temperature: %.1f °C, Humidity: %.1f %%, Timestamp: %s\n",
               data->co2, data->temperature, data->humidity, ctime(&data->timestamp));
    }

    // Stop periodic measurement
    if (write_i2c(0x3F86) < 0) {
        return -1;
    }

    return 0;
}

int main() {
    int ret;
    gpio_t *g_gpio = NULL;
    int *g_i2c_fd = NULL;

    if (init_pigpio() < 0) {
        return 1;
    }

    g_gpio = pigpio_get_os_interface();
    g_i2c_fd = mmap(NULL, sizeof(int), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    if (g_i2c_fd == MAP_FAILED) {
        perror("mmap");
        return 1;
    }
    *g_i2c_fd = -1;

    if (init_i2c() < 0) {
        return 1;
    }

    *g_i2c_fd = g_i2c_fd[0];

    while (1) {
        if (read_data() < 0) {
            perror("read_data");
            continue;
        }

        if (buffer_head != buffer_tail) {
            if (data->co2 > 1000) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }

        usleep(5000000);
    }

    close_i2c();
    munmap(g_i2c_fd, sizeof(int));
    gpioTerm(LED_GPIO);
    gpioTerm();

    return 0;
}

void close_i2c() {
    if (*g_i2c_fd >= 0) {
        close(*g_i2c_fd);
        *g_i2c_fd = -1;
    }
}

