        if (gpioRead(GPIO_SENSOR) == GPIO_HIGH) {
            gpioTick(last_high_time);
            total_time = gpioTickDiff(last_total_time, gpioTick());
            high_time = gpioTickDiff(last_high_time, last_total_time);

            if (total_time > 0 && high_time > 0) {
