                    fprintf(fd, "%s %.1f °C\n", timestamp, temperature);
                    failures = 0;
                }
            }
        }

        if (gpioRead(GPIO_SENSOR) == GPIO_LOW) {
            if (gpioWaitForEdge(GPIO_SENSOR, PI_EDGE_RISING, TIMEOUT) >= 0) {
                last_total_time = gpioTick();
                last_high_time = last_total_time;
            } else {
