                failures++;
                if (failures >= MAX_FAILURES) {
                    fprintf(fd, "SENSOR MALFUNCTION\n");
                    break;
                }
            }
        }

        usleep(SAMPLE_INTERVAL - (gpioTickDiff(gpioTick(), last_total_time)));
    }

