#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define SHT35_CMD_MEASURE_HIGH_RH 0x24
#define SHT35_CRC_LEN 1
#define SHT35_DATA_LEN 6
#define SHT35_MAX_RETRIES 3
#define SIMULATED_OFFSET_PERIOD_SECONDS 3600
#define SIMULATED_OFFSET_AMPLITUDE_C 2.0
#define SIMULATED_OFFSET_AMPLITUDE_RH 5.0

static double simulated_offset_c = 0.0;
static double simulated_offset_rh = 0.0;

void update_simulated_offset(void) {
    time_t now = time(NULL);
    double seconds_elapsed = now % SIMULATED_OFFSET_PERIOD_SECONDS;
    simulated_offset_c = SIMULATED_OFFSET_AMPLITUDE_C * sin(2 * M_PI * seconds_elapsed / SIMULATED_OFFSET_PERIOD_SECONDS);
    simulated_offset_rh = SIMULATED_OFFSET_AMPLITUDE_RH * sin(2 * M_PI * seconds_elapsed / SIMULATED_OFFSET_PERIOD_SECONDS);
}

uint16_t crc16_ccitt(const uint8_t *data, size_t len) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc >> 1) ^ (crc & 1 ? 0x8005 : 0);
            crc &= 0xFFFF;
            crc ^= data[i] << 8;
        }
    }
    return crc;
}

int read_sht35(uint8_t *data) {
    static const uint8_t cmd[] = {SHT35_CMD_MEASURE_HIGH_RH, 0x00};
    static const uint8_t expected_crc[] = {0x5A, 0xAA};
    static const uint8_t expected_rh_crc[] = {0x5A, 0x5A};
    int retries = SHT35_MAX_RETRIES;
    int i2c_fd = -1;

    while (retries > 0) {
        i2c_fd = pigpio_i2c_open(I2C_BUS, SHT35_ADDR, 0);
        if (i2c_fd < 0) {
            fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(i2c_fd));
            --retries;
            usleep(1000000);
            continue;
        }

        if (pigpio_i2c_write_read(i2c_fd, cmd, sizeof(cmd), data, SHT35_DATA_LEN + SHT35_CRC_LEN) < 0) {
            fprintf(stderr, "I2C read/write failed\n");
            --retries;
            pigpio_i2c_close(i2c_fd);
            usleep(1000000);
            continue;
        }

        if (crc16_ccitt(data, SHT35_DATA_LEN) != expected_crc[data[SHT35_DATA_LEN]] ||
            crc16_ccitt(data + 2, SHT35_DATA_LEN - 2) != expected_rh_crc[data[SHT35_DATA_LEN]]) {
            fprintf(stderr, "Invalid CRC\n");
            --retries;
            pigpio_i2c_close(i2c_fd);
            usleep(1000000);
            continue;
        }

        break;
    }

    if (i2c_fd >= 0) {
        pigpio_i2c_close(i2c_fd);
    }

    return retries > 0;
}

void log_data(const char *format, ...) {
    static const char *log_file = "environmental_data.txt";
    static FILE *log_fp = NULL;
    static struct timespec last_log_time = {0};
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    double seconds_since_last_log = now.tv_sec - last_log_time.tv_sec;

    if (log_fp == NULL || seconds_since_last_log >= 5.0) {
        if (log_fp != NULL) {
            fclose(log_fp);
        }
        log_fp = fopen(log_file, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return;
        }
        last_log_time = now;
    }

    va_list args;
    va_start(args, format);
    vfprintf(log_fp, format, args);
    va_end(args);
    fputc('\n', log_fp);
    fflush(log_fp);
}

int main(void) {
    int i2c_fd = -1;
    double temperature = NAN;
    double humidity = NAN;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    while (1) {
        update_simulated_offset();
        if (!read_sht35(data)) {
            int16_t raw_temperature = ((data[0] << 8) | data[1]) & 0xFFFC;
            int16_t raw_humidity = ((data[3] << 8) | data[4]) & 0xFFFC;

            temperature = (raw_temperature / 16.0) - 45 + simulated_offset_c;
            humidity = (raw_humidity / 16.0) + simulated_offset_rh;

            log_data(
                "%sT%fC H%f%% R%fC S%f%%\n",
                ctime(&time(NULL)),
                temperature,
                humidity,
                simulated_offset_c,
                simulated_offset_rh
            );
        }

        usleep(5000000);
    }

cleanup:
    if (i2c_fd >= 0) {
        pigpio_i2c_close(i2c_fd);
    }
    gpioTerminate();
    return 0;
}

