#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/mman.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

struct i2c_data {
    uint8_t pressure;
    uint8_t temperature;
    uint8_t scale_factor;
    uint8_t crc;
};

int i2c_file;
struct i2c_data data;
FILE *csv_file;
gpiod_line_request_linestate_cb_t gpio_cb;
gpiod_line_request_data_cb_t gpio_data_cb;
gpiod_line_request_data_cb_data_t gpio_data_cb_data;
gpiod_line_request_data_cb_data_t *gpio_data_cb_data_ptr;

void gpio_cb(struct gpiod_line_request *request, int event, void *data) {
    (void)request;
    (void)event;
    (void)data;
}

int crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j > 0; --j) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x00FF) << 8 | data[i];
        }
    }
    return crc;
}

int read_sensor() {
    if (i2c_file < 0) {
        i2c_file = open("/dev/i2c-1", O_RDWR);
        if (i2c_file < 0) {
            perror("Failed to open I2C device");
            return -1;
        }

        if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0) {
            perror("Failed to acquire bus access");
            close(i2c_file);
            return -1;
        }
    }

    if (write_reg(0x362F) < 0) {
        perror("Failed to send command");
        return -1;
    }

    usleep(45 * 1000);

    if (read_reg(0, &data.pressure, 1) != 1 ||
        read_reg(1, &data.temperature, 1) != 1 ||
        read_reg(2, &data.scale_factor, 1) != 1 ||
        read_reg(3, &data.crc, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }

    uint8_t calculated_crc = crc8(&data.pressure, 3);
    if (data.crc != calculated_crc) {
        perror("Invalid CRC");
        return -1;
    }

    return 0;
}

int write_reg(uint8_t reg, uint8_t value) {
    if (i2c_file < 0) {
        return -1;
