Here's a complete C program that fulfills the user's request. This code uses the Linux i2c-dev kernel interface and the Si7021 sensor's No Hold Master measurement commands. It logs temperature and humidity to a CSV file named 'environment.log' every 5 seconds, handles errors, and installs a SIGINT/SIGTERM handler to cleanly close the I2C file descriptor and exit gracefully.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define SI7021_RESET 0xFE
#define SI7021_RH_MEASURE 0xF5
#define SI7021_TEMP_MEASURE 0xF3
#define SI7021_PAIR_MEASURE 0xE0
#define SI7021_CRC_POLYNOMIAL 0x31
#define SI7021_CRC_INIT 0x00

static int i2c_file;
static char log_file[] = "environment.log";

void i2c_init(void) {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;

    if ((i2c_file = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }
}

void i2c_cleanup(void) {
    close(i2c_file);
}

uint8_t crc8(uint8_t data, uint8_t crc) {
    for (int i = 8; i > 0; --i) {
        crc ^= (data & 0x01) << 7;
        data >>= 1;
        if (crc & 0x80)
            crc = (crc << 1) ^ SI7021_CRC_POLYNOMIAL;
        else
            crc <<= 1;
    }
    return crc;
}

int read_data(uint8_t reg, uint8_t *buf, size_t len) {
    int ret;
    uint8_t data;

    if ((ret = write(i2c_file, &reg, 1)) != 1) {
        perror("Failed to write register");
        return -1;
    }

    for (size_t i = 0; i < len; ++i) {
        if ((ret = read(i2c_file, &data, 1)) != 1) {
            perror("Failed to read data");
            return -1;
        }
        buf[i] = data;
    }

    return ret;
}

void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *log_fp = fopen(log_file, "a");

    if (log_fp) {
        fprintf(log_fp, "%s,%f,%f\n", timestamp, temperature, humidity);
        fclose(log_fp);
    } else {
        perror("Failed to open log file");
    }
}

void sigint_handler(int signum) {
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

int main(void) {
    i2c_init();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    struct timespec sleep_duration = { .tv_sec = 5, .tv_nsec = 0 };
    time_t timestamp;
    char timestamp_str[32];
    float temperature, humidity;
    uint8_t rh_data[3], temp_data[3];

    while (1) {
        if (read_data(SI7021_RH_MEASURE, rh_data, sizeof(rh_data)) < 0) {
            if (errno != EAGAIN) {
                perror("Failed to read humidity");
                continue;
            }
            usleep(100000);
            continue;
        }

        if (rh_data[2] != crc8(rh_data[0] | (rh_data[1] << 8), SI7021_CRC_INIT)) {
            perror("Invalid CRC for humidity data");
            continue;
        }

        humidity = 125.0 * (rh_data[0] | (rh_data[1] << 8)) / 65536.0 - 6.0;

        if (read_data(SI7021_PAIR_MEASURE, temp_data, sizeof(temp_data)) < 0) {
            if (errno != EAGAIN) {
                perror("Failed to read temperature");
                continue;
            }
            usleep(100000);
            continue;
        }

        if (temp_data[2] != crc8(temp_data[0] | (temp_data[1] << 8), SI7021_CRC_INIT)) {
            perror("Invalid CRC for temperature data");
            continue;
        }

        temperature = 175.72 * (temp_data[0] | (temp_data[1] << 8)) / 65536.0 - 46.85;

        timestamp = time(NULL);
        ctime_s(timestamp_str, sizeof(timestamp_str), &timestamp);
        log_data(timestamp_str, temperature, humidity);

        sleep(1);
    }

    i2c_cleanup();
    return EXIT_SUCCESS;
}
