            fan_duty = convert_slpm_to_fan_duty(flow_rate);
            set_fan_duty(fan_duty);
            last_sample = time(NULL);
            log_entry(&(LogEntry){ .timestamp = last_sample, .flow_rate = flow_rate });
        }
        usleep(10000);
    }

    gpioTerm(NULL);
    return 0;
