#define WHO_AM_I_REG 0x0F
#define CTRL_REG1_REG 0x10
#define PRESS_OUT_XL_REG 0x28
#define PRESS_OUT_L_REG 0x29
#define PRESS_OUT_H_REG 0x2A
#define TEMP_OUT_L_REG 0x2B
#define TEMP_OUT_H_REG 0x2C

volatile sig_atomic_t exit_flag = 0;

void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "[%s] Error: %s\n", timestamp, message);
    fprintf(logfile, "[%s] Error: %s\n", timestamp, message);
    fflush(logfile);
}

int i2c_write_read(int bus, uint8_t addr, uint8_t reg, uint8_t *write_data, size_t write_len, uint8_t *read_data, size_t read_len) {
    int ret;
    int i2c_fd = pigpio_i2c_open(bus, addr, 0);

    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    ret = pigpio_i2c_write_read(i2c_fd, reg, write_data, write_len, read_data, read_len);
    pigpio_i2c_close(i2c_fd);

    if (ret < 0) {
        log_error("I2C read/write failed");
        return -1;
    }

    return 0;
}

int main() {
    int ret;
    uint8_t who_am_i_data[1];
    uint8_t ctrl_reg1_data[1] = {0xB0};
    uint8_t pressure_data[4];
    uint8_t temperature_data[2];
    int32_t pressure;
    int16_t temperature;
    FILE *logfile;

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return 1;
    }

    logfile = fopen("environmental_data.txt", "w");
    if (!logfile) {
        log_error("Failed to open log file");
        goto cleanup;
    }

    ret = i2c_write_read(I2C_BUS, LPS33HW_ADDR, WHO_AM_I_REG, NULL, 0, who_am_i_data, 1);
    if (ret < 0) {
        goto cleanup;
    }

    if (who_am_i_data[0] != 0xB1) {
        log_error("Invalid WHO_AM_I register value");
        goto cleanup;
    }

    ret = i2c_write_read(I2C_BUS, LPS33HW_ADDR, CTRL_REG1_REG, ctrl_reg1_data, 1, NULL, 0);
    if (ret < 0) {
        goto cleanup;
    }

