        ret = i2c_write_read(I2C_BUS, LPS33HW_ADDR, PRESS_OUT_XL_REG, NULL, 0, pressure_data, 4);
        if (ret < 0) {
            continue;
        }

        pressure = (pressure_data[0] << 16) | (pressure_data[1] << 8) | pressure_data[2];
        pressure = (pressure >> 4) & 0x7FFFFF;
        pressure /= 4096.0;

        ret = i2c_write_read(I2C_BUS, LPS33HW_ADDR, TEMP_OUT_L_REG, NULL, 0, temperature_data, 2);
        if (ret < 0) {
            continue;
        }

        temperature = (temperature_data[0] << 8) | temperature_data[1];
        temperature = (temperature >> 4) & 0xFFF;
        temperature = 42.5 + temperature * 480.0 / 1024.0;

        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[32];
        char line[128];

        time(&rawtime);
        timeinfo = localtime_r(&rawtime, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        snprintf(line, sizeof(line), "%s, Pressure: %.2f hPa, Temperature: %.1f °C\n", timestamp, pressure, temperature);
        fputs(line, logfile);
        fflush(logfile);

        gpioDelay(1000000); // 1 second delay
    }

cleanup:
    fclose(logfile);
    gpioTerminate();
    return 0;

    // Handle SIGINT signal
    void sigint_handler(int signum) {
        exit_flag = 1;
    }

    signal(SIGINT, sigint_handler);
}

