#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define STLM75_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10

static uint16_t temp_buffer[BUFFER_SIZE];
static volatile size_t buffer_head = 0;
static volatile size_t buffer_tail = 0;
static double running_avg = 0.0;
static double temp_sum = 0.0;
static double temp_count = 0.0;

void i2c_read_temp(void) {
    uint16_t raw_temp;

    if (i2cReadWordData(I2C_BUS, STLM75_ADDR, STLM75_REG, &raw_temp) < 0) {
        perror("i2cReadWordData");
        return;
    }

    raw_temp = (raw_temp >> 1) & 0x07FF; // Swap bytes and right-shift by 7
    raw_temp = (raw_temp * 2) - 512; // Convert to degrees Celsius

    temp_sum += raw_temp;
    temp_count++;

    if (buffer_head == buffer_tail) {
        temp_buffer[buffer_head] = raw_temp;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    }
}

void update_running_avg(void) {
    if (temp_count > 0) {
        running_avg = temp_sum / temp_count;
    }
}

void check_temp_threshold(void) {
    if (running_avg > 28.0) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

void sigint_handler(int signum) {
    gpioWrite(LED_GPIO, 0);
    i2cClose(I2C_BUS);
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return 1;
    }

    gpioWrite(LED_GPIO, 0);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (i2cOpen(I2C_BUS, &I2C_ADDR) < 0) {
        perror("i2cOpen");
        return 1;
    }

    while (1) {
        i2c_read_temp();
        update_running_avg();
        check_temp_threshold();
        sleep(1);
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

