#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define I2C_RD_BUF_SIZE 9
#define I2C_WR_CMD_LEN 2

static const uint8_t CONTINUOUS_MEASUREMENT_CMD[] = {0x36, 0x2F};

static void i2c_read(uint8_t addr, uint8_t *buf, size_t len) {
    if (i2c_readBuffer(I2C_BUS, addr, buf, len, 1000) != len) {
        fprintf(stderr, "I2C read error\n");
        exit(1);
    }
}

static void i2c_write(uint8_t addr, const uint8_t *buf, size_t len) {
    if (i2c_writeBuffer(I2C_BUS, addr, buf, len, 1000) != len) {
        fprintf(stderr, "I2C write error\n");
        exit(1);
    }
}

static uint16_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc ^= (crc & 0x80) >> 7;
            crc = (crc << 1) ^ (crc & 0x80 ? 0x31 : 0x00);
            crc ^= data[i];
        }
    }
    return crc;
}

static bool verify_crc(const uint8_t *data, size_t len) {
    return crc8(data, len - 1) == data[len - 1];
}

static void log_reading(const char *tag, const uint8_t *data) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    printf("%02d:%02d:%02d.%03d %s: ", tm->tm_hour, tm->tm_min, tm->tm_sec,
           (int)(tm->tm_usec / 1000), tag);

    for (size_t i = 0; i < sizeof(data); ++i) {
        printf("%02X ", data[i]);
    }
    printf("\n");
}

static void sdp32_read(void) {
    uint8_t buf[I2C_RD_BUF_SIZE];

    i2c_write(SDP32_ADDR, CONTINUOUS_MEASUREMENT_CMD, I2C_WR_CMD_LEN);
    usleep(100000); // Wait for the sensor to start measuring

    i2c_read(SDP32_ADDR, buf, I2C_RD_BUF_SIZE);

    if (verify_crc(buf, I2C_RD_BUF_SIZE)) {
        uint32_t raw_pressure = (buf[0] << 8) | buf[1];
        uint32_t raw_temperature = (buf[2] << 8) | buf[3];
        uint32_t raw_scale_factor = (buf[4] << 8) | buf[5];

        float pressure_pa = (float)raw_pressure / (1 << (raw_scale_factor & 0x0F));
        float temperature = (float)raw_temperature / 16.0;

        log_reading("Pressure", buf);
        log_reading("Temperature", buf + 2);
        log_reading("Scale factor", buf + 4);
        printf("Pressure (Pa): %.2f\n", pressure_pa);
    } else {
        log_reading("Error", buf);
        fprintf(stderr, "Invalid CRC\n");
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if (gpioSetMode(I2C_BUS, PI_OUTPUT) < 0 ||
        gpioSetMode(I2C_BUS | PI_MODE_IN, PI_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set I2C pins\n");
        exit(1);
    }

    if (gpioPeripheralI2CInit(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        exit(1);
    }

    if (gpioI2CDevOpen(SDP32_ADDR, 0, &g_i2c_handle) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(1);
    }

    int interval = 1000;
    if (argc > 1) {
        interval = atoi(argv[1]);
    }

    signal(SIGINT, [](int) {
        gpioI2CDevClose(g_i2c_handle);
        gpioTerminate();
        exit(0);
    });
    signal(SIGTERM, [](int) {
        gpioI2CDevClose(g_i2c_handle);
        gpioTerminate();
        exit(0);
    });

    while (1) {
        sdp32_read();
        usleep(interval * 1000);
    }

    gpioI2CDevClose(g_i2c_handle);
    gpioTerminate();
    return 0;
}

