#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SENSOR_ADDR 0x25
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR_PRESSURE 0.0000625
#define SCALE_FACTOR_TEMPERATURE 0.05

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc << 1) ^ (crc & 0x80 ? CRC_POLYNOMIAL : 0);
            crc ^= data[i];
        }
    }
    return crc;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_fd = -1;
    if ((i2c_fd = gpioI2COpen(I2C_BUS, SDA_PIN, SCL_PIN, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to address sensor\n");
        goto i2c_close;
    }

    uint8_t cmd[] = {0x36, 0x15, 0x00};
    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "Failed to send command\n");
        goto i2c_close;
    }

    usleep(45000); // Wait at least 45 ms for the conversion

    uint8_t buf[9];
    if (read(i2c_fd, buf, sizeof(buf)) != sizeof(buf)) {
        fprintf(stderr, "Failed to read data\n");
        goto i2c_close;
    }

    // Validate CRC-8 on each 3-byte data word
    for (size_t i = 0; i < sizeof(buf) - 1; i += 3) {
        if (crc8(buf + i, 3) != buf[i + 3]) {
            fprintf(stderr, "CRC-8 validation failed\n");
            goto i2c_close;
        }
    }

    // Convert raw values using the per-reading scale factors
    double raw_pressure = (double)buf[0] | ((double)buf[1] << 8) | ((double)buf[2] << 16);
    double raw_temperature = (double)buf[3] | ((double)buf[4] << 8) | ((double)buf[5] << 16);
    double pressure = raw_pressure * SCALE_FACTOR_PRESSURE;
    double temperature = raw_temperature / 200.0 * SCALE_FACTOR_TEMPERATURE;

    printf("Pressure: %.4f Pa\n", pressure);
    printf("Temperature: %.2f °C\n", temperature);

    // Log results every 1 second
    while (1) {
        usleep(1000000); // Sleep for 1 second
        pressure = raw_pressure * SCALE_FACTOR_PRESSURE;
        temperature = raw_temperature / 200.0 * SCALE_FACTOR_TEMPERATURE;
        printf("Pressure: %.4f Pa\n", pressure);
        printf("Temperature: %.2f °C\n", temperature);
    }

i2c_close:
    if (i2c_fd >= 0) {
        gpioI2CClose(i2c_fd);
    }

cleanup:
    gpioTerminate();
    return 0;

    // Handle SIGINT and SIGTERM for graceful shutdown
    void sigint_handler(int signum) {
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
}

