#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define HDC1000_ADDR 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define BUFFER_SIZE 4

static void sigint_handler(int signum) {
    printf("\nExiting...\n");
    close(i2c_fd);
    exit(0);
}

int main() {
    int i2c_fd, ret;
    char buffer[BUFFER_SIZE];
    struct i2c_rdwr_ioctl_data i2c_msg[2];

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C device file
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device file");
        exit(1);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Configure HDC1000 for combined temperature-and-humidity measurement at 14-bit resolution
    i2c_msg[0].addr = HDC1000_ADDR;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &CONFIG_REG;
    i2c_msg[0].buf[0] |= (1 << 12);

    i2c_msg[1].addr = HDC1000_ADDR;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = BUFFER_SIZE;
    i2c_msg[1].buf = buffer;

    // Perform I2C read transaction
    if (ioctl(i2c_fd, I2C_RDWR, i2c_msg) < 0) {
        perror("Failed to perform I2C read transaction");
        close(i2c_fd);
        exit(1);
    }

    // Calculate and print temperature and humidity
    float temp_raw = (buffer[0] << 8 | buffer[1]) * 256.0 + buffer[2];
    float hum_raw = (buffer[3] << 8 | buffer[4]) * 256.0 + buffer[5];

    float temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
    float humidity = (hum_raw / 65536.0) * 100.0;

    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

    // Wait 5 seconds before the next reading
    sleep(5);

    // Continue the loop indefinitely
    while (1) {
        // Repeat the I2C read transaction and print readings
        if (ioctl(i2c_fd, I2C_RDWR, i2c_msg) < 0) {
            perror("Failed to perform I2C read transaction");
            fprintf(stderr, "Error reading sensor data\n");
        } else {
            temperature = (buffer[0] << 8 | buffer[1]) * 256.0 + buffer[2];
            humidity = (buffer[3] << 8 | buffer[4]) * 256.0 + buffer[5];

            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        }

        sleep(5);
    }

    // Close I2C file descriptor and exit
    close(i2c_fd);
    return 0;
}

