    int ret;
    uint16_t raw_temp, raw_humidity;
    double temp_c, humidity;
    struct timespec delay;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (i2cOpen(0, SI7051_I2C_ADDR, &i2c_handle) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
