#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90833_ADDR 0x60
#define MLX90833_REG_PRESS_MSB 0x2A
#define MLX90833_REG_PRESS_LSB 0x2B

static int g_pi_handle;
static volatile int g_running = 1;

void sigint_handler(int signum) {
    g_running = 0;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (gpioSetMode(PI_MODE_WRONLY) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    if (gpioSetOutputOptions(PI_OUTPUT_HIGH_SPEED) < 0) {
        perror("gpioSetOutputOptions");
        return -1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    return 0;
}

int i2c_write_read(int bus, unsigned char addr, unsigned char reg, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    int ret;
    i2c_adapter_t *i2c_adapter;
    i2c_config_t i2c_config;
    i2c_rdwr_t i2c_msg[2];

    i2c_adapter = pigpio_i2c_open(bus, 1000000);
    if (!i2c_adapter) {
        perror("pigpio_i2c_open");
        return -1;
    }

    i2c_config.mode = PI_I2C_MODE_WR | PI_I2C_MODE_RD;
    i2c_config.slave_address = addr << 1;

    i2c_msg[0].addr = i2c_config.slave_address;
    i2c_msg[0].flags = 0;
    i2c_msg[0].buf = tx_buf;
    i2c_msg[0].len = len;

    i2c_msg[1].addr = i2c_config.slave_address;
    i2c_msg[1].flags = PI_I2C_MST_RD;
    i2c_msg[1].buf = rx_buf;
    i2c_msg[1].len = len;

    ret = pigpio_i2c_rdwr_timeout(i2c_adapter, &i2c_msg, 2, 100);
    if (ret < 0) {
        perror("pigpio_i2c_rdwr_timeout");
    }

    pigpio_i2c_close(i2c_adapter);
    return ret;
}

unsigned short read_pressure() {
    unsigned char buf[2];
    int ret;

    ret = i2c_write_read(I2C_BUS, MLX90833_ADDR, MLX90833_REG_PRESS_MSB, &buf[0], &buf[1], 2);
    if (ret < 0) {
        return 0;
    }

    return (buf[0] << 8) | buf[1];
}

int main() {
    if (init_pigpio() < 0) {
        return 1;
    }

    while (g_running) {
        unsigned short pressure = read_pressure();
        if (pressure == 0) {
            fprintf(stderr, "Error reading pressure\n");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char time_str[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        printf("%s: Pressure = %u\n", time_str, pressure);
        sleep(0.5);
    }

    gpioTerm();
    return 0;
}

