#define I2C_BUS 1
#define MLX90819_ADDR 0x60
#define MLX90819_REG_PRESS_MSB 0xAA
#define MLX90819_REG_PRESS_LSB 0xAB
#define SCALING_FACTOR 0.1
#define GPIO_RESET 18

static gpiod_line_request_lines(1, &gpio_reset, GPIOD_IN_CHNG_EDGE | GPIOD_ACTIVE_LOW, "mlx90819_reset");

int i2c_file;

void i2c_init() {
    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, MLX90819_ADDR << 1) < 0) {
        perror("Failed to acquire I2C address");
        exit(EXIT_FAILURE);
    }
}

void i2c_deinit() {
    if (i2c_file >= 0) {
        close(i2c_file);
        i2c_file = -1;
    }

    gpiod_line_release_request(gpio_reset);
    gpiod_release_lines(1, &gpio_reset);
}

uint16_t read_pressure() {
    uint8_t data[2];
    ssize_t bytes_read;

    gpiod_set_value_cansleep(gpio_reset, 1);
    usleep(100000);
    gpiod_set_value_cansleep(gpio_reset, 0);
    usleep(100000);

    if ((bytes_read = read(i2c_file, data, sizeof(data))) != sizeof(data)) {
        perror("Failed to read pressure data");
        return 0;
    }

    return (data[0] << 8) | data[1];
}

float convert_pressure(uint16_t raw) {
    return raw * SCALING_FACTOR;
}

void log_pressure(const char *prefix, float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: Pressure: %.2f kPa\n", prefix, pressure);
}

void sigint_handler(int signum) {
    i2c_deinit();
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_init();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        uint16_t raw_pressure = read_pressure();
        if (raw_pressure == 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            continue;
        }

        float pressure = convert_pressure(raw_pressure);
        log_pressure("Measurement:", pressure);
        sleep(1);
    }

    i2c_deinit();
    return EXIT_SUCCESS;
}

