#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define SENSOR_ADDR 0x25
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

struct i2c_rdwr_ioctl_data {
    __u16 words_num;
    __u16 words[];
};

int main() {
    int i2c_fd, gpio_fd;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t buf[9];
    uint16_t pressure, temperature, crc_calculated, crc_received;
    struct timespec ts;
    FILE *log_file;
    gpiod_line_request_lines(1, "gpio2_sdad", GPIOD_IN, &gpio_fd, NULL);
    gpiod_line_request_lines(1, "gpio3_scl", GPIOD_IN, &gpio_fd, NULL);

    if (gpio_fd < 0) {
        perror("Failed to request GPIO lines");
        exit(EXIT_FAILURE);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        goto cleanup_gpio;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        goto cleanup_i2c;
    }

    i2c_data.words_num = 1;
    i2c_data.words[0] = 0x362F;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to send command");
        goto cleanup_i2c;
    }

    usleep(45 * 1000);

    i2c_data.words_num = 9;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read data");
        goto cleanup_i2c;
    }

    for (size_t i = 0; i < 9; ++i) {
        buf[i] = i2c_data.words[i];
    }

    pressure = buf[0] * 256 + buf[1];
    temperature = buf[2] * 256 + buf[3];
    crc_calculated = crc8(buf + 4, 4, CRC_POLYNOMIAL, CRC_INITIAL_VALUE);
    crc_received = buf[7] * 256 + buf[8];

    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC error\n");
        goto cleanup_i2c;
    }

    pressure /= 60.0;
    temperature /= 200.0;

    clock_gettime(CLOCK_REALTIME, &ts);
    log_file = fopen("pressure_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup_i2c;
    }

    fprintf(log_file, "%lld,%.2f,%.2f\n", ts.tv_sec, pressure, temperature);
    fclose(log_file);

cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpiod_line_release_lines(gpio_fd, 2);
    close(gpio_fd);

    return 0;
}

uint8_t crc8(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc >> 1) ^ (crc & 0x01 ? poly : 0);
            data[i] >>= 1;
            crc = (crc & 0x80) ? (crc ^ poly) : crc;
        }
    }
    return crc;
}

