    uint8_t crc = CRC_INITIAL_VALUE;

    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j > 0; --j) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x00FF) << 8 | (data[i] & 0x00FF);
        }
    }

    return crc;
}

int read_pressure(uint16_t *pressure) {
    int ret;
    uint8_t buf[data_len];

    ret = pigpio_i2c_writeRead(gpio_i2c_open(I2C_BUS, SDP800_ADDR, 0), command, 1, buf, data_len);
