    ret = pigpio_i2c_writeRead(gpio_i2c_open(I2C_BUS, SDP800_ADDR, 0), NULL, 0, buf, data_len);
    if (ret < 0) {
        perror("pigpio_i2c_writeRead");
        return -1;
    }

    uint16_t raw = (buf[0] << 8) | buf[1];
    uint8_t crc = crc8(buf, data_len - 1);

    if (crc != buf[2]) {
        fprintf(stderr, "Invalid CRC\n");
        return -1;
    }

    *pressure = raw / 60;
    return 0;
}

