    } else {
        FILE *file = fopen(csv_file, "w");
        if (file) {
            fprintf(file, "timestamp,pressure\n");
            fclose(file);
            printf("Created CSV file %s\n", csv_file);
        }
    }

    if ((ret = pigpio_init()) < 0) {
        perror("pigpio_init");
        return 1;
    }

    while (1) {
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            last_log = time(NULL);
        }

        usleep(1000000); // Sleep for 1 second

        if (difftime(time(NULL), last_log) >= 1) {
            break;
        }
    }

    pigpio_stop();
    return 0;
