code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define SAFE_TIRE_MIN 200
#define SAFE_TIRE_MAX 250
#define SCALE_FACTOR 0.01
#define LOG_FILE "pressure_log.csv"

static int i2c_handle = -1;
static FILE *log_file = NULL;

void log_pressure(uint16_t pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    char line[64];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL || ftell(log_file) == 0) {
        log_file = fopen(LOG_FILE, "w");
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    snprintf(line, sizeof(line), "%s,%.2f\n", timestamp, pressure * SCALE_FACTOR);
    fprintf(log_file, line);
    fflush(log_file);
}

void i2c_read_and_log(void) {
    uint16_t pressure;
    int ret;

    ret = i2cReadI2CBlockData(i2c_handle, 0x00, 2, &pressure);
    if (ret < 0) {
        perror("i2cReadI2CBlockData");
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
            i2c_handle = -1;
        }
        usleep(100000);
        if (i2c_handle < 0) {
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, PI_I2C_RDWR);
        }
    }

    if (i2c_handle >= 0) {
        if (pressure < SAFE_TIRE_MIN || pressure > SAFE_TIRE_MAX) {
            fprintf(stderr, "Warning: Tire pressure out of safe range: %.2f kPa\n", pressure * SCALE_FACTOR);
        }
        log_pressure(pressure);
    }
}

void sigint_handler(int signum) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

int main(void) {
    int ret;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, PI_I2C_RDWR);
    if (i2c_handle < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    while (1) {
        i2c_read_and_log();
        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    return 0;
}

