code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27

#define T_REG 0x00
#define H_REG 0x01
#define CMD_REG 0x02

#define BUFFER_SIZE 4

static int g_i2c_fd = -1;
static char g_log_file[64] = "environmental_data.log";

void log_timestamped_data(float temp, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);
    printf("%s,Temperature: %.2f°C, Humidity: %.2f%%\n", time_str, temp, humidity);

    FILE *log_file = fopen(g_log_file, "a");
    if (log_file) {
        fprintf(log_file, "%s,Temperature: %.2f°C, Humidity: %.2f%%\n", time_str, temp, humidity);
        fclose(log_file);

        struct stat st;
        if (stat(g_log_file, &st) == 0 && st.st_size > (1024 * 1024)) {
            unlink(g_log_file);
            log_file = fopen(g_log_file, "w");
        }
    }
}

int i2c_write_read(int i2c_fd, uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret = 0;
    i2c_rdwr_data_t msg[2];

    msg[0].addr = addr << 1;
    msg[0].flags = 0;
    msg[0].buf = &reg;
    msg[0].nbytes = 1;

    msg[1].addr = addr << 1 | I2C_RD;
    msg[1].flags = 0;
    msg[1].buf = data;
    msg[1].nbytes = len;

    ret = i2c_master_rdwr_blocking(i2c_fd, msg, 2);
    if (ret < 0) {
        perror("i2c_master_rdwr_blocking");
        return -1;
    }

    return ret == 2 ? 0 : -1;
}

float i2c_read_temperature(int i2c_fd) {
    uint8_t data[BUFFER_SIZE];
    int ret = i2c_write_read(i2c_fd, I2C_ADDR, T_REG, data, BUFFER_SIZE);

    if (ret < 0) {
        return NAN;
    }

    if ((data[0] & 0x01) != 0x01) {
        return NAN;
    }

    return data[1] * 165.0 / 16383.0 - 40.0;
}

float i2c_read_humidity(int i2c_fd) {
    uint8_t data[BUFFER_SIZE];
    int ret = i2c_write_read(i2c_fd, I2C_ADDR, H_REG, data, BUFFER_SIZE);

    if (ret < 0) {
        return NAN;
    }

    if ((data[0] & 0x01) != 0x01) {
        return NAN;
    }

    return data[1] * 100.0 / 16383.0;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    g_i2c_fd = i2c_open(I2C_BUS, 1);
    if (g_i2c_fd < 0) {
        perror("i2c_open");
        gpioTerm();
        return 1;
    }

    signal(SIGINT, [](int sig) {
        i2c_close(g_i2c_fd);
        gpioTerm();
        exit(0);
    });

    while (1) {
        float temp = i2c_read_temperature(g_i2c_fd);
        float humidity = i2c_read_humidity(g_i2c_fd);

        if (!isnan(temp) && !isnan(humidity)) {
            log_timestamped_data(temp, humidity);
        }

        sleep(5);
    }

    i2c_close(g_i2c_fd);
    gpioTerm();

    return 0;
}

