    uint8_t data[BUFFER_SIZE];
    int ret = i2c_write_read(i2c_fd, I2C_ADDR, H_REG, data, BUFFER_SIZE);

    if (ret < 0) {
        return NAN;
    }

    if ((data[0] & 0x01) != 0x01) {
        return NAN;
    }

    return data[1] * 100.0 / 16383.0;
}

