#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define PULSE_WIDTH_MIN 36
#define PULSE_WIDTH_MAX 813
#define SCALE 0.00025
#define OFFSET 1000

static volatile int running = 1;
static FILE *log_file;

void sigint_handler(int signum) {
    running = 0;
}

void log_pressure(time_t timestamp, uint16_t pressure) {
    char buffer[64];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S, Pressure: %.2f Pa", localtime(&timestamp));
    fprintf(log_file, "%s\n", buffer);
    fprintf(log_file, "Pressure: %d\n", pressure);
}

int main() {
    int ret;
    time_t timestamp;
    uint32_t sync_pulse_start, pulse_width, checksum, data;
    uint16_t pressure;

    if ((log_file = fopen("pressure_log.txt", "w")) == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUp(GPIO_PIN);

    while (running) {
        timestamp = time(NULL);

        ret = gpioRead(GPIO_PIN);
        if (ret < 0) {
            perror("gpioRead");
            continue;
        }

        if (ret == 0) {
            sync_pulse_start = gpioGetTickCount();
            while (gpioRead(GPIO_PIN) == 0 && (gpioGetTickCount() - sync_pulse_start) < SYNC_PULSE_TICKS * TICK_TIME_US) {}

            if ((gpioGetTickCount() - sync_pulse_start) >= SYNC_PULSE_TICKS * TICK_TIME_US) {
                log_pressure(timestamp, 0);
                continue;
            }

            pulse_width = gpioGetTickCount() - sync_pulse_start;
            if (pulse_width < PULSE_WIDTH_MIN || pulse_width > PULSE_WIDTH_MAX) {
                log_pressure(timestamp, -1);
                continue;
            }

            checksum = 0;
            data = (pulse_width - SYNC_PULSE_TICKS) / (TICK_TIME_US * 4);
            checksum ^= (data >> 4);
            checksum ^= (data & 0xF);
            checksum ^= (data >> 8) & 0xF;
            checksum ^= (data >> 12) & 0xF;

            if (checksum != (data & 0xF)) {
                log_pressure(timestamp, -2);
                continue;
            }

            pressure = (data << 4) | ((data >> 12) & 0xF);
            pressure = (pressure * SCALE) + OFFSET;
            log_pressure(timestamp, pressure);
        }

        usleep(TICK_TIME_US * 1000);
    }

    gpioTerm();
    fclose(log_file);
    return 0;
}

