#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_LSB 0.0078125

static const char *filename = "greenhouse_temps.dat";

int i2c_init(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }

    if (i2cOpen(I2C_BUS, TMP117_ADDR, &i2c_handle) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    return 0;
}

int read_temp(void) {
    int16_t raw_temp = 0;

    if (i2cReadRegister16(i2c_handle, TEMP_REG, &raw_temp) < 0) {
        perror("Failed to read temperature from TMP117");
        return -1;
    }

    return raw_temp * 100 * TEMP_LSB;
}

void write_temp_to_file(float temp) {
    int fd = open(filename, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        perror("Failed to open file for writing");
        return;
    }

    union {
        float f;
        uint32_t i;
    } temp_union;
    temp_union.f = temp;

    write(fd, &temp_union.i, sizeof(temp_union.i));
    close(fd);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, exiting gracefully...\n");
    i2cClose(i2c_handle);
    gpioTerm();
    exit(0);
}

int main(void) {
    int ret;
    struct sigaction sa;

    ret = i2c_init();
    if (ret < 0) {
        return ret;
    }

    if (read_temp() != 0x0117) {
        printf("Device ID does not match TMP117 (0x0117), check the address!\n");
        return -1;
    }

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return -1;
    }

    while (1) {
        float temp = (float)read_temp() * TEMP_LSB;
        write_temp_to_file(temp);
        sleep(60);
    }

    return 0;
}

