#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define SHT40_CMD_MEASURE_HIGH_RES 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

static int gpio_handle = -1;
static FILE *log_file = NULL;

void sigint_handler(int signum) {
    if (gpio_handle != -1) {
        gpioTerm(gpio_handle);
        gpio_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpio_handle = gpioOpen(0, GPIODirection_IN, 0);
    if (gpio_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (i2cWriteReadData(gpio_handle, SHT40_ADDR, &SHT40_CMD_MEASURE_HIGH_RES, 1,
                             SHT40_DATA_LENGTH, i2cData) < 0) {
            fprintf(stderr, "Failed to write or read from I2C\n");
            continue;
        }

        uint8_t temp_crc = crc8(SHT40_DATA_LENGTH - 1, i2cData, SHT40_CRC_INIT, SHT40_CRC_POLYNOMIAL);
        uint8_t hum_crc = crc8(1, &i2cData[SHT40_DATA_LENGTH - 2], SHT40_CRC_INIT, SHT40_CRC_POLYNOMIAL);

        if (temp_crc != i2cData[SHT40_DATA_LENGTH - 1] || hum_crc != i2cData[SHT40_DATA_LENGTH - 2]) {
            fprintf(stderr, "Invalid CRC checksum\n");
            continue;
        }

        time_t rawtime;
        struct tm *timeinfo;
        char time_str[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        float temp_celsius = -45.0 + 175.0 * (i2cData[0] + (i2cData[1] << 8) / 65535.0);
        float humidity = -6.0 + 125.0 * (i2cData[2] + (i2cData[3] << 8) / 65535.0) % 100.0;

        fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%RH\n", time_str, temp_celsius, humidity);
        fflush(log_file);

        sleep(5);
    }

    if (gpio_handle != -1) {
        gpioTerm(gpio_handle);
        gpio_handle = -1;
    }

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    return 0;
}

int i2cWriteReadData(int gpio_handle, uint8_t addr, const uint8_t *write_data, size_t write_len,
                      size_t read_len, uint8_t *read_data) {
    int ret = i2cWriteReadBlocking(gpio_handle, addr, write_data, write_len, read_data, read_len);

    if (ret < 0) {
        fprintf(stderr, "I2C write or read failed: %s\n", gpioStrerror(gpio_last_error()));
        return -1;
    }

    return ret;
}

uint8_t crc8(size_t len, const uint8_t *data, uint8_t init, uint16_t poly) {
    uint8_t crc = init;

    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc << 1) | (crc >> 7 & 1);
            if ((crc & 0x80) == 1) {
                crc = (crc << 1) ^ poly;
            }
            crc &= 0xFF;
        }

        crc ^= data[i];
    }

    return crc;
}

