#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SHTC3_ADDR 0x70
#define SHTC3_VDD_PIN 1
#define SHTC3_VSS_PIN 6
#define SHTC3_SDA_PIN 3
#define SHTC3_SCL_PIN 4
#define SHTC3_CRC_POLYNOMIAL 0x31
#define SHTC3_CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "shtc3_environment.log"
#define LOG_INTERVAL 5

int main(void) {
    int i2c_bus = 1;
    int i2c_handle;
    int gpio_vdd_handle, gpio_sda_handle, gpio_scl_handle;
    uint8_t data[6];
    double temperature, humidity;
    time_t current_time;
    struct tm *time_info;
    char log_line[100];
    FILE *log_file;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpio_vdd_handle = gpioSetMode(SHTC3_VDD_PIN, PI_OUTPUT);
    gpio_sda_handle = gpioSetMode(SHTC3_SDA_PIN, PI_INPUT_PULL_UP);
    gpio_scl_handle = gpioSetMode(SHTC3_SCL_PIN, PI_INPUT_PULL_UP);

    gpioWrite(SHTC3_VDD_PIN, 1);

    if ((i2c_handle = pigpio_i2c_open(i2c_bus, SHTC3_ADDR, 1000000)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    while (1) {
        usleep(12400); // Wait at least 12.4 ms for the conversion

        if (pigpio_i2cWriteRead(i2c_handle, 0x7866, data, 6) < 0) {
            perror("I2C write/read error");
            goto cleanup;
        }

        if (!validate_crc(data, 6)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        temperature = calculate_temperature(data[0], data[1]);
        humidity = calculate_humidity(data[2], data[3]);

        if (temperature < -40 || temperature > 125 || humidity < 0 || humidity > 100) {
            fprintf(stderr, "Out-of-range value\n");
            continue;
        }

        current_time = time(NULL);
        time_info = localtime(&current_time);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S,%.2f,%.2f", time_info, temperature, humidity);

        if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
            perror("File open error");
            goto cleanup;
        }

        fprintf(log_file, "%s\n", log_line);
        fflush(log_file);
        fprintf(stdout, "%s\n", log_line);

        sleep(LOG_INTERVAL);
    }

cleanup:
    if (log_file) fclose(log_file);
    pigpio_i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

bool validate_crc(const uint8_t *data, size_t length) {
    uint8_t crc = SHTC3_CRC_INITIAL_VALUE;

    for (size_t i = 0; i < length; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc & 0x80) ? (crc << 1) ^ SHTC3_CRC_POLYNOMIAL : crc << 1;
            crc ^= data[i] & 0x01;
            data[i] >>= 1;
        }
    }

    return crc == 0;
}

double calculate_temperature(uint16_t msb, uint16_t lsb) {
    return 175.0 * (msb + (lsb / 256.0)) / 65535.0 - 45.0;
}

double calculate_humidity(uint16_t msb, uint16_t lsb) {
    return 100.0 * (msb + (lsb / 256.0)) / 65535.0;
}

