#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_RESOLUTION 0.0078125

static int i2c_init(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }

    if (gpioSetMode(I2C_BUS, PI_MODE_INOUT) < 0) {
        perror("Failed to set I2C bus mode");
        return -1;
    }

    if (gpioSetPeripheralMode(I2C_BUS, PI_PERIPHERAL_I2C_FAST) < 0) {
        perror("Failed to set I2C bus speed");
        return -1;
    }

    if (i2cOpen(I2C_BUS, TMP117_ADDR, &g_i2c_fd) < 0) {
        perror("Failed to open I2C connection to TMP117");
        return -1;
    }

    return 0;
}

static void i2c_deinit(void) {
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    gpioTerminate();
}

static int16_t read_temp(void) {
    uint8_t data[2];
    int ret;

    ret = i2cReadReg16(g_i2c_fd, TMP117_REG_TEMP, data);
    if (ret < 0) {
        perror("Failed to read temperature from TMP117");
        return -1;
    }

    return (int16_t)data[0] | (int16_t)data[1] << 8;
}

static void log_temp(const char *timestamp, int16_t temp) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open temperature log file");
        return;
    }

    fprintf(log_file, "%s, Temperature: %d C\n", timestamp, temp);
    fclose(log_file);
}

static void signal_handler(int sig) {
    i2c_deinit();
    gpioTerminate();
    exit(0);
}

int main(void) {
    int ret;
    int i = 0;
    time_t now;
    char timestamp[32];
    int16_t temp;

    signal(SIGINT, signal_handler);

    if (i2c_init() < 0) {
        i++;
        if (i < 3) {
            sleep(1);
            printf("Failed to initialize I2C bus. Retrying...\n");
            continue;
        }

        fprintf(stderr, "Failed to initialize I2C bus after 3 attempts. Exiting.\n");
        return 1;
    }

    while (1) {
        time(&now);
        ctime_r(&now, timestamp);
        temp = read_temp();
        if (temp < 0) {
            perror("Failed to read temperature from TMP117");
            continue;
        }

        log_temp(timestamp, (int)(temp * TMP117_RESOLUTION));

        sleep(1);
    }

    i2c_deinit();
    gpioTerminate();
    return 0;
}

