    return (int16_t)data[0] | (int16_t)data[1] << 8;
}

static void log_temp(const char *timestamp, int16_t temp) {
    FILE *log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open temperature log file");
        return;
    }

    fprintf(log_file, "%s, Temperature: %d C\n", timestamp, temp);
    fclose(log_file);
}

static void signal_handler(int sig) {
    i2c_deinit();
    gpioTerminate();
    exit(0);
}

int main(void) {
    int ret;
    int i = 0;
    time_t now;
    char timestamp[32];
    int16_t temp;

    signal(SIGINT, signal_handler);

    if (i2c_init() < 0) {
        i++;
        if (i < 3) {
            sleep(1);
            printf("Failed to initialize I2C bus. Retrying...\n");
            continue;
        }

        fprintf(stderr, "Failed to initialize I2C bus after 3 attempts. Exiting.\n");
        return 1;
    }

    while (1) {
        time(&now);
        ctime_r(&now, timestamp);
        temp = read_temp();
        if (temp < 0) {
            perror("Failed to read temperature from TMP117");
            continue;
        }

        log_temp(timestamp, (int)(temp * TMP117_RESOLUTION));

        sleep(1);
    }

    i2c_deinit();
    gpioTerminate();
    return 0;
}
