#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define DHT11_PIN 4
#define DHT11_START_LOW 18000
#define DHT11_BIT_LOW 50000
#define DHT11_BIT_HIGH 26000
#define DHT11_RESPONSE_LOW 80000
#define DHT11_RESPONSE_HIGH 80000
#define DHT11_DATA_LOW 40000
#define DHT11_DATA_HIGH 70000
#define DHT11_TIMEOUT 500000
#define CHECKSUM_MODULO 256

static const char *LOG_FILE = "dht11_readings.txt";
static const char *ERROR_LOG_FILE = "dht11_errors.txt";

void log_error(int status_code, const char *message) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    FILE *error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log) {
        fprintf(error_log, "%s: %s\n", timestamp, message);
        fclose(error_log);
    }

    perror(message);
}

void log_reading(time_t timestamp, uint8_t temperature, uint8_t humidity) {
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&timestamp));

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s,%d,%d\n", timestamp_str, temperature, humidity);
        fclose(log_file);
    }
}

int main(void) {
    int gpio_fd = -1;
    int status_code = 0;

    if (gpioInitialise() < 0) {
        log_error(-1, "gpioInitialise failed");
        goto cleanup;
    }

    gpio_fd = pigpio_open_wrap(&status_code);
    if (gpio_fd < 0) {
        log_error(status_code, "pigpio_open_wrap failed");
        goto cleanup;
    }

    gpioSetMode(DHT11_PIN, PI_OUTPUT);
    gpioWrite(DHT11_PIN, 0);
    sleep(1);

    while (1) {
        gpioWrite(DHT11_PIN, 0);
        usleep(DHT11_START_LOW);
        gpioWrite(DHT11_PIN, 1);

        uint64_t start_time = pigpio_get_tick_us(gpio_fd);
        uint64_t response_time = start_time;
        uint8_t data = 0;
        uint8_t checksum = 0;

        if (gpioRead(DHT11_PIN) == 1) {
            log_error(-2, "Sensor absent");
            goto cleanup;
        }

        usleep(DHT11_RESPONSE_LOW);
        if (gpioRead(DHT11_PIN) != 1) {
            log_error(-3, "No response from sensor");
            goto cleanup;
        }

        usleep(DHT11_RESPONSE_HIGH);
        if (gpioRead(DHT11_PIN) != 1) {
            log_error(-4, "No response from sensor");
            goto cleanup;
        }

        for (int i = 0; i < 8; ++i) {
            usleep(DHT11_DATA_LOW);
            if (gpioRead(DHT11_PIN) != 1) {
                usleep(DHT11_DATA_HIGH);
                if (gpioRead(DHT11_PIN) == 1) {
                    log_error(-5, "Timeout reading data bit");
                    goto cleanup;
                }
                data |= (1 << (7 - i));
            }
        }

        checksum = data[0] + data[1] + data[2] + data[3];
        if (checksum != data[4]) {
            log_error(-6, "Checksum error");
            goto cleanup;
        }

        int temperature = (data[2] << 8) | data[3];
        int humidity = (data[0] << 8) | data[1];
        log_reading(time(NULL), temperature / 10.0, humidity / 10.0);

        usleep(2000000);
    }

cleanup:
    gpioTerminate();
    close(gpio_fd);
    return status_code;
}

