code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SHT31D_ADDR 0x44
#define SDA_PIN 2
#define SCL_PIN 3
#define CRC_POLY 0x31
#define LOG_FILE "sht31d_data.log"

static void log_timestamped(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t bit = 8; bit > 0; --bit) {
            crc = (crc << 1) ^ (crc & 0x80 ? CRC_POLY : 0);
            crc &= 0xFF;
            crc ^= data[i] << (7 - bit);
        }
    }
    return crc;
}

static int i2c_write_read(int bus, uint8_t addr, const uint8_t *write_data, size_t write_len, uint8_t *read_data, size_t read_len) {
    int retries = 3;
    while (retries > 0) {
        int result = igpiod_i2c_write_read(bus, addr, write_data, write_len, read_data, read_len);
        if (result >= 0) {
            return result;
        }
        --retries;
        log_timestamped("I2C transaction failed, retrying...");
        usleep(15000);
    }
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_timestamped("Failed to initialize pigpio library.");
        return 1;
    }

    if (igpiod_i2c_open(0, SDA_PIN, SCL_PIN) < 0) {
        log_timestamped("Failed to open I2C bus.");
        goto cleanup;
    }

    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        log_timestamped("Failed to open log file.");
        goto cleanup_i2c;
    }

    uint8_t cmd[] = {0x2C, 0x06, 0x00};
    uint8_t data[8];

    while (1) {
        if (i2c_write_read(0, SHT31D_ADDR, cmd, sizeof(cmd), data, sizeof(data)) < 0) {
            log_timestamped("Failed to read data from SHT31D sensor.");
            continue;
        }

        if (data[0] != 0x50 || data[1] != 0x31 || data[2] != 0x0D || data[3] != crc8(data, 3)) {
            log_timestamped("Invalid CRC-8 checksum.");
            continue;
        }

        float temperature = -45.0 + 175.0 * data[4] / 65535;
        float humidity = 100.0 * data[5] / 65535;

        if (data[6] != crc8(data + 4, 2)) {
            log_timestamped("Invalid CRC-8 checksum.");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
        fprintf(fd, "%s,%f,%f\n", timestamp, temperature, humidity);

        log_timestamped("Temperature:");
        log_timestamped(temperature < 0 ? "N/A" : itoa(temperature, 10, 6));
        log_timestamped(", Humidity:");
        log_timestamped(humidity < 0 ? "N/A" : itoa(humidity * 100, 10, 2));
        log_timestamped("\n");

        sleep(5);
    }

cleanup_i2c:
    igpiod_i2c_close(0);
cleanup:
    close(fd);
    gpioTerminate();
    return 0;
}

