        log_timestamped("Failed to initialize pigpio library.");
        return 1;
    }

    if (igpiod_i2c_open(0, SDA_PIN, SCL_PIN) < 0) {
        log_timestamped("Failed to open I2C bus.");
        goto cleanup;
    }

    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        log_timestamped("Failed to open log file.");
        goto cleanup_i2c;
    }

    uint8_t cmd[] = {0x2C, 0x06, 0x00};
    uint8_t data[8];

    while (1) {
        if (i2c_write_read(0, SHT31D_ADDR, cmd, sizeof(cmd), data, sizeof(data)) < 0) {
            log_timestamped("Failed to read data from SHT31D sensor.");
            continue;
        }

        if (data[0] != 0x50 || data[1] != 0x31 || data[2] != 0x0D || data[3] != crc8(data, 3)) {
            log_timestamped("Invalid CRC-8 checksum.");
            continue;
        }

        float temperature = -45.0 + 175.0 * data[4] / 65535;
        float humidity = 100.0 * data[5] / 65535;

        if (data[6] != crc8(data + 4, 2)) {
            log_timestamped("Invalid CRC-8 checksum.");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
        fprintf(fd, "%s,%f,%f\n", timestamp, temperature, humidity);

        log_timestamped("Temperature:");
        log_timestamped(temperature < 0 ? "N/A" : itoa(temperature, 10, 6));
        log_timestamped(", Humidity:");
        log_timestamped(humidity < 0 ? "N/A" : itoa(humidity * 100, 10, 2));
        log_timestamped("\n");

        sleep(5);
    }

cleanup_i2c:
    igpiod_i2c_close(0);
cleanup:
    close(fd);
    gpioTerminate();
    return 0;
}
