static int i2c_init(void);
static void i2c_read_data(uint8_t addr, uint16_t *r, uint16_t *g, uint16_t *b);
static double compute_cct(uint16_t r, uint16_t g, uint16_t b);
static void log_cct(double cct);
static void cleanup(int sig);

int main(void) {
    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    FILE *file = fopen(CCT_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open or create %s\n", CCT_FILE);
        return 1;
    }

    if (fprintf(file, "Timestamp,Average_CCT\n") < 0) {
        perror("Failed to write header");
    }

    time_t current_time;
    double average_cct = 0.0;
    int samples = 0;

    sigset_t sigint_mask, sigterm_mask;
    sigemptyset(&sigint_mask);
    sigemptyset(&sigterm_mask);
    sigaddset(&sigint_mask, SIGINT);
    sigaddset(&sigterm_mask, SIGTERM);

    struct sigaction sa = {
        .sa_handler = cleanup,
        .sa_mask = sigint_mask | sigterm_mask,
        .sa_flags = SA_RESTART
    };

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    while (1) {
        uint16_t r1, g1, b1, r2, g2, b2;

        i2c_read_data(SENSOR_ADDR1, &r1, &g1, &b1);
        i2c_read_data(SENSOR_ADDR2, &r2, &g2, &b2);

        if (r1 == -1 || g1 == -1 || b1 == -1 ||
            r2 == -1 || g2 == -1 || b2 == -1) {
            continue;
        }

        double cct1 = compute_cct(r1, g1, b1);
        double cct2 = compute_cct(r2, g2, b2);

        average_cct = (average_cct * samples + (cct1 + cct2)) / (samples + 2);
        samples++;

        current_time = time(NULL);
        if (fprintf(file, "%ld,%f\n", current_time, average_cct) < 0) {
            perror("Failed to write log entry");
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(file);
    gpioTerm();
    return 0;
}

static int i2c_init(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }

    if (gpioI2CInit(I2C_BUS) < 0) {
        perror("Failed to initialize I2C");
        return -1;
    }

    return 0;
}

static void i2c_read_data(uint8_t addr, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t data[6];

    if (gpioI2CReadReg16(addr, REG_DEVICE_ID) != 0x2A) {
        fprintf(stderr, "Invalid device ID at address 0x%02X\n", addr);
        *r = *g = *b = -1;
        return;
    }

    if (gpioI2CReadI2CBlockData(addr, REG_R_DATA, 2, data) != 2) {
        perror("Failed to read R data from address 0x%02X");
        *r = *g = *b = -1;
        return;
    }

    *r = (data[0] << 8) | data[1];

    if (gpioI2CReadI2CBlockData(addr, REG_G_DATA, 2, data) != 2) {
        perror("Failed to read G data from address 0x%02X");
        *r = *g = *b = -1;
        return;
    }

    *g = (data[0] << 8) | data[1];

    if (gpioI2CReadI2CBlockData(addr, REG_B_DATA, 2, data) != 2) {
        perror("Failed to read B data from address 0x%02X");
        *r = *g = *b = -1;
        return;
    }

    *b = (data[0] << 8) | data[1];
}

static double compute_cct(uint16_t r, uint16_t g, uint16_t b) {
    double r_adj = r / 100.0;
    double g_adj = g / 100.0;
    double b_adj = b / 100.0;

    double X = r_adj / (r_adj + g_adj + b_adj);
    double Y = (116 * (Y_n(X) - Y_n(X / 3.0)) + 16) / 100.0;
    double Z = (903.3 * X * Y) / (X * Y + 17.93 * Y - 5.5);

    return (1 / (X * (116 * Z - 16)) + 4.6 * Y) * 100;
}

static double Y_n(double x) {
    if (x > 0.008856) {
        return Math.pow(x, 1.0 / 3.0);
    }
    return (7.787 * x) + 16 / 116;
}

static void log_cct(double cct) {
    if (fprintf(stderr, "CCT: %f\n", cct) < 0) {
        perror("Failed to write error message");
    }
}

static void cleanup(int sig) {
    log_cct(average_cct);
    gpioTerm();
    exit(0);
}

