#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define DEVICE_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define PRESSURE_MIN 0
#define PRESSURE_MAX 800000
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0

static int i2c_file;
static FILE *log_file;

void i2c_read(uint8_t reg, uint16_t *data) {
    uint8_t buf[2];
    if (i2cReadReg16(i2c_file, DEVICE_ADDR, reg, buf) < 0) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(stderr, "Error reading register 0x%04X: %s\n", reg, timestamp);
    } else {
        *data = (buf[0] << 8) | buf[1];
    }
}

void log_data(time_t timestamp, uint16_t pressure, float temperature) {
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&timestamp));
    fprintf(log_file, "%s,%d,%.2f\n", timestamp_str, pressure, temperature);
}

int main(void) {
    int ret;
    uint16_t pressure, temperature;

    if ((ret = pigpio_init()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", strerror(-ret));
        return 1;
    }

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        goto cleanup;
    }

    if (ioctl(i2c_file, I2C_SLAVE, DEVICE_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        goto cleanup;
    }

    if ((log_file = fopen("pressure_log.txt", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup;
    }

    while (1) {
        i2c_read(PRESSURE_REG, &pressure);
        i2c_read(TEMPERATURE_REG, &temperature);

        pressure = (pressure - 0) * (PRESSURE_MAX - PRESSURE_MIN) / (0xFFFF - 0) + PRESSURE_MIN;
        temperature = temperature * 0.01 - TEMP_MIN;

        log_data(time(NULL), pressure, temperature);
        sleep(2);
    }

cleanup:
    if (log_file) fclose(log_file);
    if (i2c_file >= 0) close(i2c_file);
    gpioTerminate();
    return 0;
}

