code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define LM75B_REG_TEMP 0x00
#define GPIO_FAN 18
#define BUFFER_SIZE 60
#define HYSTERESIS 2.0

static uint16_t buffer[BUFFER_SIZE];
static size_t head = 0;
static size_t tail = 0;

void log_error(const char *msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
}

int i2c_read(uint8_t addr, uint8_t reg, uint8_t *data, size_t len) {
    int ret = pigpio_i2c_read_device(gpio_i2c_num, addr, &reg, 1, data, len);
    if (ret < 0) {
        log_error("I2C read error");
        return -1;
    }
    return ret;
}

int gpio_write(uint gpio, int value) {
    int ret = gpioWrite(gpio, value);
    if (ret < 0) {
        log_error("GPIO write error");
        return -1;
    }
    return ret;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_FAN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
    }

    gpio_write(GPIO_FAN, 0);
}

void init_i2c() {
    if (gpio_i2c_open(I2C_BUS, &gpio_i2c_handle) < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
}

void read_temperature() {
    uint8_t data[2];
    int ret = i2c_read(LM75B_ADDR, LM75B_REG_TEMP, data, sizeof(data));
    if (ret < 0) {
        return;
    }

    uint16_t temp = (data[0] << 8) | data[1];
    temp >>= 1; // Shift out D0
    buffer[head] = temp;
    head = (head + 1) % BUFFER_SIZE;
}

float compute_average() {
    size_t count = (BUFFER_SIZE + tail - head) % BUFFER_SIZE;
    float sum = 0.0;
    for (size_t i = 0; i < count; ++i) {
        sum += buffer[(head + i) % BUFFER_SIZE];
    }
    return sum / count;
}

void control_fan() {
    float avg = compute_average();
    if (avg > 28.0) {
        gpio_write(GPIO_FAN, 1);
    } else if (avg < 26.0) {
        gpio_write(GPIO_FAN, 0);
    }
}

void signal_handler(int sig) {
    gpio_write(GPIO_FAN, 0);
    pigpio_stop();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_i2c();

    while (1) {
        read_temperature();
        control_fan();
        sleep(1);
    }

    pigpio_i2c_close(gpio_i2c_handle);
    gpioTerm();

    return EXIT_SUCCESS;
}

