#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR_PRESSURE 60.0
#define SCALE_FACTOR_TEMPERATURE 200.0
#define LOG_FILE "airflow.log"
#define LOG_INTERVAL 1000 // Logging interval in milliseconds
#define MAX_PRESSURE 5.0

typedef union {
    uint8_t bytes[10];
    struct {
        uint16_t pressure;
        int16_t temperature;
        uint8_t status;
        uint8_t crc;
    } data;
} sensor_data_t;

uint16_t crc8(uint8_t *data, size_t len, uint8_t poly)
{
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc << 1) ^ (crc & 0x8000 ? poly : 0);
            crc = (crc << 1) ^ data[i];
        }
    }
    return crc;
}

int read_sensor(sensor_data_t *data)
{
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (i2cOpen(I2C_BUS, SENSOR_ADDR, 0) < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return -1;
    }

    if (i2cWriteRead(I2C_BUS, SENSOR_ADDR, 0x362F, 0, 9, data->bytes, 0) < 0) {
        perror("i2cWriteRead");
        i2cClose(I2C_BUS, SENSOR_ADDR);
        gpioTerminate();
        return -1;
    }

    uint16_t calculated_crc = crc8(data->bytes, 8, CRC_POLYNOMIAL);
    if (data->crc != calculated_crc) {
        fprintf(stderr, "CRC mismatch\n");
        i2cClose(I2C_BUS, SENSOR_ADDR);
        gpioTerminate();
        return -1;
    }

    i2cClose(I2C_BUS, SENSOR_ADDR);
    gpioTerminate();
    return 0;
}

void log_data(const sensor_data_t *data)
{
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s,%f,%d\n", time_str, data->data.pressure * SCALE_FACTOR_PRESSURE, data->data.temperature * SCALE_FACTOR_TEMPERATURE);
    fclose(log_file);
}

void signal_handler(int signum)
{
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nShutting down...\n");
        fclose(log_file);
        gpioTerminate();
        exit(0);
    }
}

int main()
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        return -1;
    }

    sensor_data_t data;
    while (1) {
        if (read_sensor(&data) < 0) {
            fprintf(stderr, "Sensor not found or error reading data\n");
            continue;
        }

        if (data.data.pressure > MAX_PRESSURE) {
            fprintf(stderr, "Warning: Differential pressure exceeds %f Pa\n", MAX_PRESSURE);
        }

        log_data(&data);
        usleep(45 * 1000);
    }

    fclose(log_file);
    return 0;
}

