#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x4A
#define GPIO_LINE 17
#define TEMP_Hysteresis 1.0

int main(void) {
    int i2c_fd, ret;
    unsigned char data[2];
    double temperature;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int gpio_fd;

    // Open I2C bus
    char i2c_dev_name[32];
    snprintf(i2c_dev_name, sizeof(i2c_dev_name), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_name, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_put(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_request_output(line, "led", GPIOD_LINE_ACTIVE_HIGH);
    if (gpio_fd < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_put(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set initial LED state
    gpiod_line_set_value(line, 0);

    while (1) {
        // Read temperature from STTS2004 sensor
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, SENSOR_ADDR, 2, data);
        if (ret < 0) {
            perror("Failed to read temperature");
            if (errno != EAGAIN) {
                break;
            }
            continue;
        }

        // Combine MSB and LSB, right-shift the result by 4 bits, and convert to Celsius
        temperature = (data[0] & 0x0F) * 0.0625 + (data[1] & 0xFF) * 0.0625 * 16;

        // Log temperature to stdout once per second
        static long last_log = 0;
        if (time(NULL) - last_log >= 1) {
            printf("%.2f °C\n", temperature);
            last_log = time(NULL);
        }

        // Drive the LED based on temperature hysteresis
        if (temperature > 28.0 + TEMP_Hysteresis) {
            gpiod_line_set_value(line, 1);
        } else if (temperature < 27.0 - TEMP_Hysteresis) {
            gpiod_line_set_value(line, 0);
        }

        usleep(100000); // Sleep for 100ms before the next iteration
    }

    // Handle SIGINT/SIGTERM
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_put(chip);
    close(i2c_fd);
    close(gpio_fd);

    return EXIT_SUCCESS;
}

