#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x25
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR_OFFSET 16

static const char *LOG_FILE = "flow_data.txt";

void log_data(const char *timestamp, uint16_t pressure, int16_t temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s,%d,%d\n", timestamp, pressure, temperature);
        fclose(file);
    }
}

int crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc << 1) ^ (crc & 0x80 ? CRC_POLYNOMIAL : 0);
            crc ^= data[i];
        }
    }
    return crc;
}

int read_sensor(void) {
    int fd = pigpio_open();
    if (fd < 0) {
        perror("pigpio_open");
        return -1;
    }

    if (gpioInitialise(fd, NULL) < 0) {
        perror("gpioInitialise");
        pigpio_terminate(fd);
        return -1;
    }

    if (i2cOpen(fd, I2C_BUS, 1000000) < 0) {
        perror("i2cOpen");
        gpioTerminate(fd);
        return -1;
    }

    if (i2cWriteReadData(fd, SENSOR_ADDR, 0x362F, 0, 9, NULL, NULL) < 0) {
        perror("i2cWriteReadData");
        i2cClose(fd, I2C_BUS);
        gpioTerminate(fd);
        return -1;
    }

    uint8_t data[9];
    if (i2cWriteReadData(fd, SENSOR_ADDR, 0, 0, 9, data, NULL) < 0) {
        perror("i2cWriteReadData");
        i2cClose(fd, I2C_BUS);
        gpioTerminate(fd);
        return -1;
    }

    int pressure_crc = crc8(data, 2);
    int temperature_crc = crc8(data + 2, 2);
    if (pressure_crc != data[4] || temperature_crc != data[6]) {
        fprintf(stderr, "Invalid CRC for pressure or temperature\n");
        i2cClose(fd, I2C_BUS);
        gpioTerminate(fd);
        return -1;
    }

    int16_t pressure = (data[0] << 8) | data[1];
    int scale_factor = (data[7] << 8) | data[8];
    int16_t pressure_raw = pressure * scale_factor >> SCALE_FACTOR_OFFSET;

    int16_t temperature = (data[3] << 8) | data[2];
    temperature /= 200;

    log_data(ctime(&time(NULL)), pressure_raw, temperature);

    i2cClose(fd, I2C_BUS);
    gpioTerminate(fd);

    return 0;
}

void signal_handler(int signum) {
    printf("\nExiting...\n");
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);

    while (1) {
        if (read_sensor() < 0) {
            perror("read_sensor");
            sleep(5);
        }
        sleep(45);
    }

    return 0;
}

