#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HDC1080_ADDR 0x40
#define CONFIG_REG 0x02
#define MEAS_REG 0x00
#define TEMP_REG 0x01
#define HUM_REG 0x03
#define TEMP_RES 14
#define HUM_RES 14
#define TEMP_OFFSET -40.0
#define HUM_SCALE 100.0

void log_env_data(const char *timestamp, float temperature, float humidity) {
    FILE *log_file = fopen("enviro_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
        fclose(log_file);
    }
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    return 0;
}

int open_i2c_bus(int bus) {
    if (gpioI2CInit(bus) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

void close_i2c_bus(int bus) {
    gpioI2CDelete(bus);
}

void terminate_pigpio() {
    gpioTerm();
}

float read_temp_and_humidity(int bus, uint8_t addr) {
    uint16_t raw_temp, raw_humidity;
    float temperature, humidity;

    if (gpioI2CWriteRead(bus, addr, &MEAS_REG, 1, TEMP_REG, 2) < 0) {
        perror("Failed to read temperature and humidity");
        return NAN;
    }

    raw_temp = (uint16_t)(gpioI2CRead(bus, TEMP_REG) << 8 | gpioI2CRead(bus, TEMP_REG + 1));
    raw_humidity = (uint16_t)(gpioI2CRead(bus, HUM_REG) << 8 | gpioI2CRead(bus, HUM_REG + 1));

    temperature = (raw_temp / (float)pow(2, TEMP_RES)) * 165.0 - TEMP_OFFSET;
    humidity = (raw_humidity / (float)pow(2, HUM_RES)) * HUM_SCALE;

    return temperature;
}

int main() {
    int bus = I2C_BUS;
    uint8_t addr = HDC1080_ADDR;

    if (init_pigpio() != 0) {
        return 1;
    }

    if (open_i2c_bus(bus) != 0) {
        terminate_pigpio();
        return 1;
    }

    if (gpioI2CWrite(bus, addr, &CONFIG_REG, 1, CONFIG_REG) != 1) {
        perror("Failed to write configuration register");
        close_i2c_bus(bus);
        terminate_pigpio();
        return 1;
    }

    while (1) {
        float temperature = read_temp_and_humidity(bus, addr);
        if (!isnan(temperature)) {
            char timestamp[20];
            time_t rawtime;
            struct tm *timeinfo;

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            log_env_data(timestamp, temperature, read_temp_and_humidity(bus, addr + 1));
        }
        sleep(5);
    }

    close_i2c_bus(bus);
    terminate_pigpio();

    return 0;
}

