#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>
#include <bcm2835.h>

#define SENSOR_ADDR 0x44
#define POLYNOMIAL 0x31
#define T_OFFSET -45.0
#define T_SCALE 175.0
#define T_INTERVAL 5

static int i2c_fd;
static FILE *log_file;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        bcm2835_i2c_close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int main() {
    if (bcm2835_init()) {
        fprintf(stderr, "Failed to initialize bcm2835 library\n");
        return 1;
    }

    i2c_fd = bcm2835_i2c_open(1, SENSOR_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        goto cleanup;
    }

    log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    time_t current_time;
    struct tm *time_info;
    while (1) {
        if (write(i2c_fd, (const char*) &cmd, 2) != 2) {
            perror("Failed to write command");
            continue;
        }
        usleep(10000);

        uint8_t data[3];
        if (read(i2c_fd, data, 3) != 3) {
            perror("Failed to read data");
            continue;
        }

        uint8_t crc = data[2];
        uint8_t calculated_crc = 0;
        for (int i = 0; i < 3; ++i) {
            calculated_crc = (calculated_crc >> 1) ^ (calculated_crc & 1 ? POLYNOMIAL : 0) ^ data[i];
        }

        if (crc != calculated_crc) {
            fprintf(stderr, "CRC mismatch\n");
            continue;
        }

        double ticks = (data[0] | data[1] << 8);
        double temperature = T_OFFSET + T_SCALE * ticks / 65535.0;

        current_time = time(NULL);
        time_info = localtime(&current_time);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);
        fprintf(log_file, "%s %f°C\n", timestamp, temperature);

        sleep(T_INTERVAL);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        bcm2835_i2c_close(i2c_fd);
    }
    bcm2835_deinit();
    return 0;
}

