#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define SCD40_ADDR 0x62
#define SCD40_I2C_BUS 1
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} Reading;

volatile sig_atomic_t running = 1;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_t logging_thread;
int i2c_file;

uint16_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x00FF) << 8 | (data[i] & 0x00FF);
        }
    }
    return crc;
}

int read_scd40(uint8_t *buf) {
    if (i2c_writeReadData(i2c_file, SCD40_ADDR, 0x21B1, 0, 1, buf, 9, 100) < 0) {
        fprintf(stderr, "Error reading SCD40: %s\n", strerror(errno));
        return -1;
    }

    if (crc8(buf, 9) != buf[8] + (buf[9] << 8)) {
        fprintf(stderr, "Error: Invalid CRC from SCD40\n");
        return -1;
    }

    return 0;
}

void *logging_thread_func(void *arg) {
    time_t now;
    FILE *file;
    char log_dir[256];
    char log_path[256];

    while (running) {
        time(&now);

        pthread_mutex_lock(&buffer_mutex);
        if (buffer_isEmpty()) {
            pthread_mutex_unlock(&buffer_mutex);
            usleep(500000);
            continue;
        }

        Reading *reading = buffer_peek();
        pthread_mutex_unlock(&buffer_mutex);

        snprintf(log_dir, sizeof(log_dir), "/var/log/scd40_data");
        mkdir(log_dir, 0755);
        snprintf(log_path, sizeof(log_path), "%s/%s", log_dir, LOG_FILE);

        file = fopen(log_path, "a");
        if (!file) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            continue;
        }

        fprintf(file, "%ld,%f,%f,%f\n", now, reading->co2, reading->temperature, reading->humidity);
        fclose(file);

        pthread_mutex_lock(&buffer_mutex);
        buffer_shift();
        pthread_mutex_unlock(&buffer_mutex);

        usleep(4000000);
    }

    return NULL;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioStrError(gpioGetError()));
        return 1;
    }

    i2c_file = pigpio_i2c_open(SCD40_I2C_BUS, SCD40_ADDR, 0);
    if (i2c_file < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", gpioStrError(gpioGetError()));
        return 1;
    }

    pthread_create(&logging_thread, NULL, logging_thread_func, NULL);

    Reading buffer[BUFFER_SIZE];
    uint8_t data[9];
    time_t last_log = 0;

    while (running) {
        if (read_scd40(data) < 0) {
            continue;
        }

        Reading *reading = buffer_append(buffer, BUFFER_SIZE);
        if (!reading) {
            fprintf(stderr, "Error: Buffer full\n");
            continue;
        }

        reading->co2 = (data[0] << 8 | data[1]) / 65535.0 * 175.0 - 45.0;
        reading->temperature = (data[2] << 8 | data[3]) / 65535.0;
        reading->humidity = (data[4] << 8 | data[5]) / 65535.0 * 100.0;

        time(&reading->timestamp);
        if (difftime(reading->timestamp, last_log) > 60) {
            last_log = reading->timestamp;
            logData(reading);
        }
    }

    // Stop periodic measurement
    uint8_t stop_cmd[] = {0x3F, 0x86};
    if (i2c_writeData(i2c_file, SCD40_ADDR, stop_cmd, 2) < 0) {
        fprintf(stderr, "Error stopping periodic measurement: %s\n", gpioStrError(gpioGetError()));
    }

    pthread_join(logging_thread, NULL);

    // Write remaining buffer data to a final CSV file
    logData(buffer_peek());
    buffer_clear();

    pigpio_i2c_close(i2c_file);
    gpioTerm();

    return 0;
}

