#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x63
#define GPIO_LINE 17

struct gpiod_line_request *gpio_line_request;
int i2c_file;

void i2c_error_handler(int error) {
    close(i2c_file);
    gpiod_line_release(gpio_line_request);
    exit(error);
}

void gpio_line_error_handler(int error) {
    gpiod_line_release(gpio_line_request);
    i2c_error_handler(error);
}

void read_calibration_coefficients() {
    uint8_t buf[2];
    if (read(i2c_file, buf, 2) != 2)
        i2c_error_handler(1);

    printf("Calibration coefficients: 0x%04x, 0x%04x\n", buf[0], buf[1]);
}

void read_pressure_and_temperature() {
    uint8_t buf[6];
    if (read(i2c_file, buf, 6) != 6)
        i2c_error_handler(1);

    uint16_t pressure = (buf[0] << 8) | buf[1];
    uint16_t temperature = (buf[2] << 8) | buf[3];
    uint16_t crc = (buf[4] << 8) | buf[5];

    if (crc != (pressure + temperature + 0x13B))
        i2c_error_handler(1);

    printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
}

void blink_led(int on_ms, int off_ms) {
    gpiod_line_set_value(gpio_line_request, 1);
    usleep(on_ms * 1000);
    gpiod_line_set_value(gpio_line_request, 0);
    usleep(off_ms * 1000);
}

void handle_pressure_warning(uint16_t pressure) {
    static uint64_t last_blink = 0;
    uint64_t now = time(NULL);

    if (pressure < 95000) {
        if (now - last_blink > 100000000) {
            blink_led(100, 100);
            last_blink = now;
        }
    } else {
        if (now - last_blink > 500000000) {
            blink_led(500, 500);
            last_blink = now;
        }
    }
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config = GPIOD_LINE_REQUEST_CONFIG_INACTIVE_HIGH;

    signal(SIGINT, gpio_line_error_handler);

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0)
        i2c_error_handler(1);

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0)
        i2c_error_handler(1);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip)
        gpio_line_error_handler(1);

    gpio_line_request = gpiod_chip_get_line_request(chip, GPIO_LINE);
    if (!gpio_line_request)
        gpio_line_error_handler(1);

    ret = gpiod_line_request_configure_flags(gpio_line_request, GPIOD_LINE_RELEASE_DEBOUNCE, &config);
    if (ret < 0)
        gpio_line_error_handler(1);

    read_calibration_coefficients();

    while (1) {
        write(i2c_file, (uint8_t[]) {0x4011}, 2);
        usleep(20000);
        read_pressure_and_temperature();
        handle_pressure_warning(read_pressure_and_temperature()->pressure);
        sleep(1);
    }

    return 0;
}

