#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x5A
#define AMBIENT_REG 0x06
#define OBJECT_REG 0x07
#define FAN_GPIO 18
#define FAN_ON 1
#define FAN_OFF 0
#define HYSTERESIS 2

static const char *LOG_FILE = "temperature_log.txt";

void log_temperature(const char *tag, uint16_t temp) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s %s: %d°C\n", tag, time_str, temp);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s %s: %d°C\n", tag, time_str, temp);
        fclose(log_file);
    }
}

int i2c_read_word_data(int bus, uint8_t addr, uint8_t reg) {
    uint8_t data[2];
    int ret;

    for (int i = 0; i < 3; i++) {
        ret = i2cWriteRead(bus, addr, &reg, 1, data, 2);
        if (ret >= 0)
            break;
        usleep(10000);
    }

    if (ret < 0) {
        perror("i2cWriteRead");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

int main(void) {
    int i2c_fd, fan_gpio;
    uint16_t ambient, object;
    double fan_threshold_high = 30.0;
    double fan_threshold_low = 28.0;
    int fan_state = FAN_OFF;

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 0);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        goto cleanup_gpio;
    }

    fan_gpio = gpioInitialise(FAN_GPIO);
    if (fan_gpio < 0) {
        perror("gpioInitialise");
        goto cleanup_i2c;
    }

    while (1) {
        ambient = i2c_read_word_data(I2C_BUS, SENSOR_ADDR, AMBIENT_REG);
        if (ambient < 0) {
            perror("i2c_read_word_data");
            continue;
        }

        object = i2c_read_word_data(I2C_BUS, SENSOR_ADDR, OBJECT_REG);
        if (object < 0) {
            perror("i2c_read_word_data");
            continue;
        }

        double temp_ambient = ambient * 0.02 - 273.15;
        double temp_object = object * 0.02 - 273.15;

        log_temperature("Ambient", (int)temp_ambient);
        log_temperature("Object", (int)temp_object);

        if (temp_object > fan_threshold_high) {
            if (fan_state == FAN_OFF) {
                gpioWrite(fan_gpio, FAN_ON);
                fan_state = FAN_ON;
            }
        } else if (temp_object < fan_threshold_low) {
            if (fan_state == FAN_ON) {
                gpioWrite(fan_gpio, FAN_OFF);
                fan_state = FAN_OFF;
            }
        }

        sleep(2);
    }

cleanup_gpio:
    gpioTerm();
cleanup_i2c:
    close(i2c_fd);

cleanup_gpio:
    gpioTerm();

    return 0;
}

