#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48

static const char *csv_file = "temperature_log.csv";
static const char *log_format = "%Y-%m-%d %H:%M:%S,%.2f\n";

int main(void) {
    FILE *csv_file_ptr;
    int i2c_fd, i2c_status;
    uint16_t temp_raw;
    float temp_celsius;
    time_t rawtime;
    struct tm *time_info;
    char time_str[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        if (gpioTerminate() < 0) {
            fprintf(stderr, "Failed to terminate pigpio: %s\n", strerror(errno));
        }
        return 1;
    }

    csv_file_ptr = fopen(csv_file, "w");
    if (!csv_file_ptr) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        if (gpioTerminate() < 0) {
            fprintf(stderr, "Failed to terminate pigpio: %s\n", strerror(errno));
        }
        if (close(i2c_fd) < 0) {
            fprintf(stderr, "Failed to close I2C bus: %s\n", strerror(errno));
        }
        return 1;
    }

    while (1) {
        i2c_status = pigpio_i2c_read_word_data(i2c_fd, 0x00, &temp_raw);
        if (i2c_status < 0) {
            perror("I2C read error");
            continue;
        }

        temp_raw &= 0x0FFF; // Clear MSB set by left-justified value
        temp_celsius = (temp_raw >> 4) * 0.0625;

        time(&rawtime);
        time_info = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), log_format, time_info);
        fprintf(csv_file_ptr, "%s%f\n", time_str, temp_celsius);

        sleep(5);
    }

    fclose(csv_file_ptr);
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio: %s\n", strerror(errno));
    }
    if (close(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C bus: %s\n", strerror(errno));
    }

    return 0;
}

