#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define HDC2010_ADDR 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define HEATER_DISABLED (1 << 7)
#define RESOLUTION_14BIT (1 << 6)
#define MEASUREMENT_READY_BIT 0

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int i2c_write_reg(int bus, int addr, int reg, int value) {
    int ret = pigpio_i2c_write_reg8(bus, addr, reg, value);
    if (ret < 0) {
        fprintf(stderr, "i2c_write_reg failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int bus, int addr, int reg, int *data) {
    int ret = pigpio_i2c_read_reg16_le(bus, addr, reg, data);
    if (ret < 0) {
        fprintf(stderr, "i2c_read_reg16 failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_measure(int bus, int addr) {
    int ret;
    uint16_t temp_raw, hum_raw;
    int timeout_us = 500 * 1000;

    ret = i2c_write_reg(bus, addr, MEASUREMENT_CONFIG, 0x01);
    if (ret < 0) {
        return -1;
    }

    while (1) {
        ret = i2c_read_reg16(bus, addr, MEASUREMENT_CONFIG, NULL);
        if (ret < 0) {
            return -1;
        }
        if ((MEASUREMENT_CONFIG & MEASUREMENT_READY_BIT) == MEASUREMENT_READY_BIT) {
            break;
        }
        usleep(1000);
        if (timeout_us <= 0) {
            fprintf(stderr, "Measurement timeout\n");
            return -1;
        }
        timeout_us -= 1000;
    }

    ret = i2c_read_reg16(bus, addr, 0x00, &temp_raw);
    if (ret < 0) {
        return -1;
    }

    ret = i2c_read_reg16(bus, addr, 0x02, &hum_raw);
    if (ret < 0) {
        return -1;
    }

    int temp = (temp_raw / 65536 * 165) - 40;
    int hum = (hum_raw / 65536 * 100);

    printf("Temperature: %d.%02d°C, Humidity: %d.%02d%%\n", temp / 10, temp % 10, hum / 100, hum % 100);
    return 0;
}

int main() {
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    ret = pigpio_i2c_open(I2C_BUS, HDC2010_ADDR, &g_i2c_handle);
    if (ret < 0) {
        fprintf(stderr, "i2c_open failed: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = i2c_write_reg(I2C_BUS, HDC2010_ADDR, CONFIG, HEATER_DISABLED | RESOLUTION_14BIT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set configuration: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        ret = i2c_measure(I2C_BUS, HDC2010_ADDR);
        if (ret < 0) {
            if (errno == EIO && errno != EAGAIN) {
                fprintf(stderr, "Sensor or bus error, retrying...\n");
                continue;
            }
            goto cleanup;
        }
        sleep(5);
    }

cleanup:
    if (g_i2c_handle != -1) {
        pigpio_i2c_close(g_i2c_handle);
    }
    gpioTerminate();
    return 0;
}

