        fprintf(stderr, "i2c_open failed: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = i2c_write_reg(I2C_BUS, HDC2010_ADDR, CONFIG, HEATER_DISABLED | RESOLUTION_14BIT);
    if (ret < 0) {
        fprintf(stderr, "Failed to set configuration: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        ret = i2c_measure(I2C_BUS, HDC2010_ADDR);
        if (ret < 0) {
            if (errno == EIO && errno != EAGAIN) {
                fprintf(stderr, "Sensor or bus error, retrying...\n");
                continue;
            }
            goto cleanup;
        }
        sleep(5);
    }

