#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <time.h>

#define MAX6675_CS_GPIO 17
#define MAX6675_MOSI_GPIO 11
#define MAX6675_MISO_GPIO 9
#define MAX6675_SCK_GPIO 10
#define RELAY_GPIO 17

#define SPI_DEV "/dev/spidev0.0"
#define BUFFER_SIZE 3

struct profile_entry {
    double time_seconds;
    double target_temp_celsius;
};

void sigint_handler(int signum) {
    printf("\nExiting...\n");
    gpiod_set_value_cansleep(relay_gpio, 0);
    gpiod_close(relay_gpio);
    close(spi_fd);
    exit(0);
}

int read_max6675() {
    int ret;
    unsigned char buffer[BUFFER_SIZE];
    struct spi_ioc_transfer transfer = {
        .tx_buf = {0, 0, 0},
        .rx_buf = buffer,
        .len = BUFFER_SIZE,
        .delay_usecs = 0,
        .speed_hz = 100000,
    };

    transfer.tx_buf[0] = 0x93; // Read thermocouple
    transfer.tx_buf[1] = 0x03;
    transfer.tx_buf[2] = 0x00;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 1) {
        perror("Failed to read MAX6675");
        return -1;
    }

    unsigned int temperature = (buffer[1] << 8) | buffer[2];
    if (buffer[0] & (1 << 2)) {
        fprintf(stderr, "Open-circuit error\n");
        return -1;
    }

    return temperature;
}

double pid_controller(double setpoint, double process_value, double kp, double ki, double kd) {
    static double integral = 0.0;
    double error = setpoint - process_value;
    double derivative = error - integral;
    integral += error * 0.01;
    double output = kp * error + ki * integral + kd * derivative;

    if (output < 0.0)
        output = 0.0;
    if (output > 1.0)
        output = 1.0;

    return output;
}

int main() {
    signal(SIGINT, sigint_handler);

    int spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    relay_gpio = gpiod_chip_open_named_gpio_with_consumer(NULL, "gpiochip0", RELAY_GPIO, "reflow_oven");
    if (IS_ERR(relay_gpio)) {
        perror("Failed to open GPIO");
        close(spi_fd);
        return 1;
    }

    struct timespec sleep_time = {1, 0};
    FILE *log_file = fopen("reflow_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_close(relay_gpio);
        close(spi_fd);
        return 1;
    }

    fprintf(log_file, "Time(s),Temperature(°C)\n");

    FILE *profile_file = fopen("profile.txt", "r");
    if (!profile_file) {
        perror("Failed to open profile file");
        fclose(log_file);
        gpiod_close(relay_gpio);
        close(spi_fd);
        return 1;
    }

    double kp = 1.0, ki = 0.0, kd = 0.0;
    double current_temp = 0.0;
    double setpoint = 0.0;
    double prev_time = 0.0;
    double integral_time = 0.0;

    struct profile_entry entry;
    while (fscanf(profile_file, "%lf,%lf", &entry.time_seconds, &entry.target_temp_celsius) == 2) {
        prev_time = time(NULL);
        setpoint = entry.target_temp_celsius;
        integral_time += entry.time_seconds - prev_time;
        prev_time = entry.time_seconds;

        while (time(NULL) - prev_time < entry.time_seconds) {
            current_temp = read_max6675() / 16.0;
            double output = pid_controller(setpoint, current_temp, kp, ki * integral_time, kd * (time(NULL) - prev_time));
            gpiod_set_value_cansleep(relay_gpio, output);
            nanosleep(&sleep_time, NULL);
        }

        fprintf(log_file, "%.6f,%.2f\n", prev_time, current_temp);
        integral_time = 0.0;
    }

    fclose(log_file);
    fclose(profile_file);

    gpiod_close(relay_gpio);
    close(spi_fd);

    return 0;
}

