    double temp = atof(temp_str);

    close(fd);
    return temp;
}

void relay_cb(struct gpiod_line *line, int event, void *user_data) {
    if (event == LINE_EVENT_ACTIVE_LOW && line == relay) {
        gpiod_line_set_value(line, 1);
    }
}

int main(int argc, char **argv) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s setpoint Kp Ki\n", argv[0]);
        return 1;
    }

    setpoint = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    relay = gpiod_chip_get_line_byname(chip, RELAY_GPIO_LINE);
    if (!relay) {
        perror("Failed to get relay line");
        goto cleanup;
    }

    pwm = gpiod_chip_get_line_byname(chip, PWM_GPIO_LINE);
    if (!pwm) {
        perror("Failed to get PWM line");
        goto cleanup;
    }

    gpiod_line_request_callback(relay, GPIOD_LINE_REQUEST_DIRECTION_OUT, relay_cb, NULL);
    gpiod_line_set_value(relay, 0);

    const char *temp_device_path = TEMP_FILE_PREFIX "28-xxxxxxxxxxxxxxxxxx";
    double temp, average_temp = 0.0;
    while (1) {
        current_time = time(NULL);
        temp = read_temp_raw(temp_device_path);
        if (temp < 0) {
            perror("Failed to read temperature");
            continue;
        }

        average_temp = (average_temp * 4 + temp) / 5.0;
        double error = setpoint - temp;
        double derivative = (error - prev_error) / (current_time - prev_time);
        integral += error * (current_time - prev_time);

        double output = Kp * error + Ki * integral + Kd * derivative;
        duty_cycle = output > 100.0 ? 100.0 : (output < 0.0 ? 0.0 : output);
        gpiod_line_set_value(pwm, duty_cycle / 100.0);

        prev_error = error;
        prev_time = current_time;

        FILE *log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            perror("Failed to open log file");
            continue;
        }

        fprintf(log_file, "%lu, %f, %f, %f, %f\n", current_time, average_temp, setpoint, output, duty_cycle);
        fclose(log_file);

        sleep(5);
    }

cleanup:
    gpiod_line_release(pwm);
    gpiod_line_release(relay);
    gpiod_chip_close(chip);

    return 0;
}
