code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <string.h>
#include <syslog.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <openssl/sha.h>

#define I2C_BUS 1
#define HTU21D_ADDR 0x40
#define BUFFER_SIZE 256
#define JSON_BUFFER_SIZE 256

static void log_error(const char *message) {
    openlog("humidity_poster", LOG_PID, LOG_USER);
    syslog(LOG_ERR, "%s", message);
    closelog();
}

static int i2c_read_reg(int file, uint8_t reg, uint8_t *data, int len) {
    int ret;
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    i2c_msg[0].addr = HTU21D_ADDR << 1;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &reg;
    i2c_msg[1].addr = HTU21D_ADDR << 1;
    i2c_msg[1].flags = I2C_M_RD;
    i2c_msg[1].len = len;
    i2c_msg[1].buf = data;

    if ((ret = ioctl(file, I2C_RDWR, i2c_msg)) < 0) {
        log_error("I2C read error");
        return -1;
    }

    return ret;
}

static int i2c_write_reg(int file, uint8_t reg, uint8_t data) {
    int ret;
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    i2c_msg[0].addr = HTU21D_ADDR << 1;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &reg;
    i2c_msg[1].addr = HTU21D_ADDR << 1;
    i2c_msg[1].flags = I2C_M_NOSTART;
    i2c_msg[1].len = 1;
    i2c_msg[1].buf = &data;

    if ((ret = ioctl(file, I2C_RDWR, i2c_msg)) < 0) {
        log_error("I2C write error");
        return -1;
    }

    return ret;
}

static uint16_t read_checksum(const uint8_t *data, size_t len) {
    uint16_t checksum = 0;
    for (size_t i = 0; i < len; ++i) {
        checksum += data[i];
    }
    return checksum;
}

static int read_humidity(int i2c_file) {
    uint8_t buffer[10];
    int ret;

    // Reset the sensor
    ret = i2c_write_reg(i2c_file, 0xE5, 0x00);
    if (ret < 0) {
        return -1;
    }

    // Wait for the sensor to be ready
    usleep(200000);

    // Read humidity and temperature data
    ret = i2c_read_reg(i2c_file, 0xE5, buffer, 10);
    if (ret < 0) {
        return -1;
    }

    // Check the checksum
    uint16_t checksum = read_checksum(buffer + 2, 8);
    if (checksum != ((buffer[0] << 8) | buffer[1])) {
        log_error("CRC mismatch");
        return -1;
    }

    // Extract humidity value
    uint16_t humidity = (buffer[4] << 8) | buffer[5];
    humidity /= 10;

    return humidity;
}

static int post_humidity(const char *url, uint16_t humidity) {
    int sockfd, ret;
    struct sockaddr_in serv_addr;
    char json[JSON_BUFFER_SIZE];
    snprintf(json, JSON_BUFFER_SIZE, "{\"humidity\": %d}", humidity);

    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        log_error("Socket creation error");
        return -1;
    }

    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);
    if (inet_pton(AF_INET, url, &serv_addr.sin_addr) <= 0) {
        log_error("Invalid URL");
        close(sockfd);
        return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        log_error("Connection error");
        close(sockfd);
        return -1;
    }

    if (send(sockfd, json, strlen(json), 0) <= 0) {
        log_error("Send error");
        close(sockfd);
        return -1;
    }

    char response[BUFFER_SIZE];
    ssize_t response_len = recv(sockfd, response, BUFFER_SIZE - 1, 0);
    if (response_len <= 0) {
        log_error("Receive error");
        close(sockfd);
        return -1;
    }
    response[response_len] = '\0';

    close(sockfd);

    if (strstr(response, "200 OK") == NULL) {
        log_error("HTTP error");
        return -1;
    }

    return 0;
}

int main(void) {
    int i2c_file;
    int ret;

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        log_error("I2C device open error");
        return 1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, HTU21D_ADDR) < 0) {
        log_error("I2C slave address error");
        close(i2c_file);
        return 1;
    }

    while (1) {
        uint16_t humidity = read_humidity(i2c_file);
        if (humidity < 0) {
            log_error("Failed to read humidity");
            break;
        }

        ret = post_humidity("http://api.example.com/humidity", humidity);
        if (ret < 0) {
            log_error("Failed to POST humidity");
        }

        sleep(60);
    }

    if (ioctl(i2c_file, I2C_DISABLE, I2C_BUS) < 0) {
        log_error("I2C bus disable error");
    }

    close(i2c_file);

    return 0;
}

