#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <sys/stat.h>
#include <sys/mman.h>

#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17

#define I2C_BUS 1
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000

struct i2c_data {
    int fd;
    char *buf;
};

void i2c_write(struct i2c_data *data, uint8_t reg, uint8_t *buf, size_t len) {
    int retries = I2C_RETRIES;
    while (retries > 0) {
        if (write(data->fd, &reg, 1) != 1) {
            perror("Failed to write register");
            usleep(I2C_RETRY_DELAY_US);
            retries--;
            continue;
        }

        if (write(data->fd, buf, len) != len) {
            perror("Failed to write data");
            usleep(I2C_RETRY_DELAY_US);
            retries--;
            continue;
        }

        if (ioctl(data->fd, I2C_SLAVE, reg) >= 0)
            return;

        perror("Failed to select slave");
        usleep(I2C_RETRY_DELAY_US);
        retries--;
    }

    perror("I2C write failed");
    exit(EXIT_FAILURE);
}

uint16_t read_16_be(const uint8_t *buf) {
    return (buf[0] << 8) | buf[1];
}

void i2c_read(struct i2c_data *data, uint8_t reg, size_t len, uint8_t *buf) {
    if (ioctl(data->fd, I2C_SLAVE, reg) < 0) {
        perror("Failed to select slave");
        exit(EXIT_FAILURE);
    }

    if (write(data->fd, &reg, 1) != 1) {
        perror("Failed to write register");
        exit(EXIT_FAILURE);
    }

    if (read(data->fd, buf, len) != len) {
        perror("Failed to read data");
        exit(EXIT_FAILURE);
    }
}

void init_sensors(struct i2c_data *tmp117, struct i2c_data *aht20) {
    if ((tmp117->fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(tmp117->fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to select TMP117 slave");
        exit(EXIT_FAILURE);
    }

    if ((aht20->fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(aht20->fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to select AHT20 slave");
        exit(EXIT_FAILURE);
    }

    uint8_t init_cmd[] = {0xBE, 0x08, 0x00};
    i2c_write(aht20, 0, init_cmd, sizeof(init_cmd));
}

void check_sensor_presence(struct i2c_data *tmp117, struct i2c_data *aht20) {
    uint8_t tmp117_id = 0;
    i2c_read(tmp117, 0x01, 1, &tmp117_id);
    if (tmp117_id != 0x5C) {
        printf("Warning: TMP117 not found\n");
    }

    uint8_t aht20_id = 0;
    i2c_read(aht20, 0x0F, 1, &aht20_id);
    if (aht20_id != 0x5C) {
        printf("Warning: AHT20 not found\n");
    }
}

void log_data(const char *filename, int temp, int humidity, int motion) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(file, "%s,%d.%03d,%d.%03d,%d\n", timestamp, temp / 10, temp % 10, humidity / 1000, (humidity % 1000) / 10, motion);
    fclose(file);
}

void gpio_setup(gpiod_chip *chip, gpiod_line *line) {
    if (gpiod_chip_open_byname(chip, "gpiochip4") < 0) {
        perror("Failed to open gpiochip4");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request(line, "pir") < 0) {
        perror("Failed to request PIR line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_debounce(line, 100);
    gpiod_line_set_direction(line, GPIOD_LINE_INPUT);
}

int main() {
    struct i2c_data tmp117 = {0};
    struct i2c_data aht20 = {0};
    struct i2c_data *sensors[] = {&tmp117, &aht20};
    gpiod_chip *chip = NULL;
    gpiod_line *line = NULL;

    signal(SIGINT, [](int signum) {
        printf("Received SIGINT, exiting gracefully...\n");
        for (size_t i = 0; i < sizeof(sensors) / sizeof(struct i2c_data *); i++) {
            if (sensors[i]->buf)
                free(sensors[i]->buf);
            if (sensors[i]->fd >= 0)
                close(sensors[i]->fd);
        }

        if (chip)
            gpiod_chip_close(chip);

        if (line)
            gpiod_line_release(line);

        exit(EXIT_SUCCESS);
    });

    signal(SIGTERM, [](int signum) {
        printf("Received SIGTERM, exiting gracefully...\n");
        for (size_t i = 0; i < sizeof(sensors) / sizeof(struct i2c_data *); i++) {
            if (sensors[i]->buf)
                free(sensors[i]->buf);
            if (sensors[i]->fd >= 0)
                close(sensors[i]->fd);
        }

        if (chip)
            gpiod_chip_close(chip);

        if (line)
            gpiod_line_release(line);

        exit(EXIT_SUCCESS);
    });

    check_sensor_presence(sensors[0], sensors[1]);
    init_sensors(sensors[0], sensors[1]);

    char logfile[32];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(logfile, sizeof(logfile), "log_%Y-%m-%d.csv", tm);

    FILE *log = fopen(logfile, "w");
    if (!log) {
        perror("Failed to create log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    fclose(log);

    gpiod_chip_get_byname("gpiochip4", &chip);
    gpio_setup(chip, gpiod_get_line(chip, PIR_GPIO));

    while (1) {
        uint8_t aht20_buf[8];
        i2c_read(sensors[1], 0xAC, sizeof(aht20_buf), aht20_buf);

        if (!(aht20_buf[0] & (1 << 7))) {
            int temp = (read_16_be(&aht20_buf[2]) - 4685) * 0.0078125;
            int humidity = read_16_be(&aht20_buf[4]) * 10;
            int motion = gpiod_line_get_value(line);

            log_data(logfile, temp, humidity, motion);
        }

        usleep(1000000);
    }

    return 0;
}

