code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_RED 17
#define GPIO_GREEN 22
#define GPIO_BLUE 27
#define SAMPLE_INTERVAL_MS 500
#define CPU_LOAD_THRESHOLDS {0, 50, 100}
#define NUM_THRESHOLDS sizeof(CPU_LOAD_THRESHOLDS) / sizeof(int)

static int g_pwm_channels[3] = {-1, -1, -1};
static int g_prev_cpu_load[NUM_THRESHOLDS] = {0};

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpioWrite(GPIO_RED, 0);
        gpioWrite(GPIO_GREEN, 0);
        gpioWrite(GPIO_BLUE, 0);
        gpioTerminate();
        exit(0);
    }
}

int init_pwm(int gpio) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pin %d\n", gpio);
        return -1;
    }

    g_pwm_channels[gpio - GPIO_RED] = gpioHardwarePWM(gpio, 50, 0);
    if (g_pwm_channels[gpio - GPIO_RED] < 0) {
        fprintf(stderr, "Failed to set up PWM for pin %d\n", gpio);
        return -1;
    }

    return 0;
}

void set_led_color(int r, int g, int b) {
    r = (r < 0) ? 0 : (r > 255) ? 255 : r;
    g = (g < 0) ? 0 : (g > 255) ? 255 : g;
    b = (b < 0) ? 0 : (b > 255) ? 255 : b;

    gpioWrite(GPIO_RED, 255 - r);
    gpioWrite(GPIO_GREEN, 255 - g);
    gpioWrite(GPIO_BLUE, 255 - b);
}

int main() {
    struct timespec ts;
    int cpu_load[NUM_THRESHOLDS] = {0};
    int i;

    if (init_pwm(GPIO_RED) || init_pwm(GPIO_GREEN) || init_pwm(GPIO_BLUE)) {
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += SAMPLE_INTERVAL_MS / 1000;
        ts.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000;

        if (nanosleep(&ts, &ts) < 0) {
            perror("nanosleep");
            break;
        }

        int cpu_stat_fd = open("/proc/stat", O_RDONLY);
        if (cpu_stat_fd < 0) {
            perror("open");
            continue;
        }

        char cpu_stat_buf[128];
        ssize_t nread = read(cpu_stat_fd, cpu_stat_buf, sizeof(cpu_stat_buf));
        close(cpu_stat_fd);

        if (nread <= 0) {
            continue;
        }

        char cpu_user[32] = {0};
        char cpu_nice[32] = {0};
        char cpu_system[32] = {0};
        char cpu_idle[32] = {0};
        char cpu_iowait[32] = {0};
        char cpu_irq[32] = {0};
        char cpu_softirq[32] = {0};
        char cpu_steal[32] = {0};
        char cpu_guest[32] = {0};
        char cpu_gnice[32] = {0};

        sscanf(cpu_stat_buf,
               "cpu   : %31s %31s %31s %31s %31s %31s %31s %31s %31s %31s",
               cpu_user, cpu_nice, cpu_system, cpu_idle, cpu_iowait, cpu_irq,
               cpu_softirq, cpu_steal, cpu_guest, cpu_gnice);

        int total_cpu = atoi(cpu_user) + atoi(cpu_nice) + atoi(cpu_system) +
                       atoi(cpu_idle) + atoi(cpu_iowait) + atoi(cpu_irq) +
                       atoi(cpu_softirq) + atoi(cpu_steal) + atoi(cpu_guest) +
                       atoi(cpu_gnice);

        for (i = 0; i < NUM_THRESHOLDS; ++i) {
            cpu_load[i] = (g_prev_cpu_load[i] * (total_cpu - g_prev_cpu_load[i]) +
                           cpu_load[i] * g_prev_cpu_load[i]) / total_cpu;
        }

        int color_index = 0;
        for (i = 1; i < NUM_THRESHOLDS; ++i) {
            if (cpu_load[i] > cpu_load[color_index]) {
                color_index = i;
            }
        }

        int r = (color_index == 0) ? 255 : (color_index == NUM_THRESHOLDS - 1) ? 0 :
                                       (CPU_LOAD_THRESHOLDS[color_index] -
                                        cpu_load[color_index]) * 255 /
                                           (CPU_LOAD_THRESHOLDS[color_index + 1] -
                                            CPU_LOAD_THRESHOLDS[color_index - 1]);
        int g = (color_index == 0) ? 0 : (color_index == NUM_THRESHOLDS - 1) ? 255 :
                                       (CPU_LOAD_THRESHOLDS[color_index] -
                                        cpu_load[color_index]) * 255 /
                                           (CPU_LOAD_THRESHOLDS[color_index + 1] -
                                            CPU_LOAD_THRESHOLDS[color_index - 1]);
        int b = 255 - r - g;

        set_led_color(r, g, b);

        for (i = 0; i < NUM_THRESHOLDS; ++i) {
            g_prev_cpu_load[i] = cpu_load[i];
        }
    }

    gpioTerminate();
    return 0;
}

