#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/mman.h>

#define GPIO_FAN 18
#define SPI_CE0 8
#define SPI_MODE 0
#define SPI_SPEED 500000
#define MAX_TEMP_BUFFER_SIZE 20
#define TEMP_RESOLUTION 0.25

typedef struct {
    time_t timestamp;
    int16_t temperature;
    uint8_t pwm_duty;
} TempData;

TempData temp_buffer[MAX_TEMP_BUFFER_SIZE];
volatile size_t buffer_head = 0;
volatile size_t buffer_tail = 0;

int spi_fd;

void log_temp_data(time_t timestamp, int16_t temperature, uint8_t pwm_duty) {
    TempData *data = &temp_buffer[buffer_head];
    data->timestamp = timestamp;
    data->temperature = temperature;
    data->pwm_duty = pwm_duty;
    buffer_head = (buffer_head + 1) % MAX_TEMP_BUFFER_SIZE;
}

void print_temp_buffer() {
    for (size_t i = buffer_tail; i != buffer_head; i = (i + 1) % MAX_TEMP_BUFFER_SIZE) {
        const TempData *data = &temp_buffer[i];
        printf("%ld, %d, %d\n", data->timestamp, data->temperature, data->pwm_duty);
    }
}

int read_max31855() {
    uint8_t buf[4];
    int ret = spiXfer(spi_fd, buf, 4, 0);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    int16_t temperature = (buf[0] << 8) | buf[1];
    int fault = (buf[2] & 0x3F) << 8 | buf[3];

    if (fault & (1 << 16)) {
        fprintf(stderr, "MAX31855 fault: ");
        if (fault & (1 << 0)) fprintf(stderr, "OC ");
        if (fault & (1 << 1)) fprintf(stderr, "SCG ");
        if (fault & (1 << 2)) fprintf(stderr, "SCV ");
        fprintf(stderr, "\n");
        return -1;
    }

    return temperature;
}

void set_fan_pwm(uint8_t duty) {
    gpioPWM(GPIO_FAN, duty);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_FAN, PI_OUTPUT) < 0 ||
        gpioSetPWMfrequency(GPIO_FAN, 1000) < 0 ||
        spiOpen(&spi_fd, SPI_CE0, SPI_MODE, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to initialise SPI or GPIO\n");
        goto cleanup;
    }

    signal(SIGINT, [](int sig) {
        set_fan_pwm(0);
        spiClose(spi_fd);
        print_temp_buffer();
        gpioTerm();
        exit(0);
    });

    while (1) {
        int temperature = read_max31855();
        if (temperature < 0) continue;

        double celsius = temperature * TEMP_RESOLUTION;
        uint8_t pwm_duty = 0;

        if (celsius < 25.0) {
            pwm_duty = 0;
        } else if (celsius <= 40.0) {
            pwm_duty = (uint8_t) ((celsius - 25.0) * 50 / 15.0);
        } else if (celsius <= 60.0) {
            pwm_duty = 50 + (uint8_t) ((celsius - 40.0) * 150 / 20.0);
        } else {
            pwm_duty = 255;
        }

        log_temp_data(time(NULL), (int16_t) celsius, pwm_duty);
        set_fan_pwm(pwm_duty);

        usleep(1000000); // Sleep for 1 second
    }

cleanup:
    gpioTerm();
    return 0;
}

