#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define MAX_RTD_READ_ATTEMPTS 10
#define SPI_BUS 0
#define SPI_DEVICE 0
#define CS_LINE_MAX31865 8
#define LOG_FILE "rtd_log.csv"

int spi_fd;
gpiod_line_request_lines_data_v1 lines_data = { .lines = { { .direction = GPIOD_IN, .edge_detected_callback = NULL } } };
gpiod_line_request_lines_data_v1* lines_data_ptr = &lines_data;
gpiod_line_request* request;
struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 5 * 1000 * 1000 * 1000 };

void log_error(const char* message) {
    fprintf(stderr, "%s\n", message);
    fflush(stderr);
}

void log_temperature(double temperature) {
    time_t rawtime;
    struct tm* timeinfo;
    char time_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s,%f\n", time_str, temperature);
    fflush(log_file);
    fclose(log_file);
}

int read_rtd(int spi_fd, int cs_line) {
    int retries = MAX_RTD_READ_ATTEMPTS;
    uint8_t buf[4];
    int r;

    gpiod_line_request_set_request_err_cb(request, NULL);
    gpiod_line_request_set_request_err_data(request, "MAX31865 CS line error");

    while (retries > 0) {
        gpiod_line_set_value(lines_data_ptr->lines[CS_LINE_MAX31865].consumer, !lines_data_ptr->lines[CS_LINE_MAX31865].value);
        usleep(10000);

        r = write(spi_fd, &buf, 4);
        if (r == 4) {
            r = read(spi_fd, buf, 4);
            if (r == 4) {
                if ((buf[0] & 0x01) == 0x01) {
                    // Fault status register bit 0 is set, return error
                    log_error("MAX31865: Fault status register error");
                    return -1;
                }

                double temperature = (double)buf[1] * 256.0 + (double)buf[2];
                double r0 = (double)buf[3];

                // Calculate temperature using the Callendar-Van Dusen equation
                double a = 0.0000238;
                double b = 0.00000022;
                double c = 0.99994;
                double d = 0.001724;
                double e = 0.000000087;
                double f = 0.000209;
                double g = 0.0000000069;
                double h = 0.00000000042;

                double r1 = r0 * (1.0 + a * r0 + b * r0 * r0 + c * r0 * r0 * r0);
                double t = 1.0 / (d + r1 * (e + r1 * (f + r1 * (g + r1 * h))));
                temperature *= t - 273.15;

                log_temperature(temperature);
                return (int)temperature;
            }
        }

        retries--;
        if (retries > 0) {
            usleep(sleep_time.tv_nsec);
        }
    }

    log_error("MAX31865: SPI communication error");
    return -1;
}

int main() {
    int spi_bus, spi_device;
    char spi_dev_path[32];
    int cs_line;
    struct spi_device_id id;
    struct spi_device* spi_dev;

    if (gpiod_library_init() < 0) {
        log_error("Failed to initialize libgpiod");
        return 1;
    }

    request = gpiod_chip_get_request_line(gpiod_chip_get_by_label("gpiochip0"), CS_LINE_MAX31865, lines_data_ptr, NULL);
    if (request == NULL) {
        log_error("Failed to request MAX31865 CS line");
        goto cleanup;
    }

    snprintf(spi_dev_path, sizeof(spi_dev_path), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_dev_path, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        goto cleanup;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE_0) != 0) {
        log_error("Failed to set SPI mode");
        goto cleanup;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_NUM_CHIPS, &id.num_devs) < 1 || id.num_devs != 1) {
        log_error("Failed to get SPI device count");
        goto cleanup;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_DEVICE, &id) < 0) {
        log_error("Failed to get SPI device ID");
        goto cleanup;
    }

    if (strncmp(id.name, "MAX31865", 7) != 0) {
        log_error("Connected device is not MAX31865");
        goto cleanup;
    }

    cs_line = id.max_speed_hz / 1000000;
    if (cs_line != CS_LINE_MAX31865) {
        log_error("Connected MAX31865 does not support the expected clock speed");
        goto cleanup;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &id.max_speed_hz) != 0) {
        log_error("Failed to set SPI clock speed");
        goto cleanup;
    }

    while (1) {
        int temperature = read_rtd(spi_fd, CS_LINE_MAX31865);
        if (temperature < 0) {
            continue;
        }

        usleep(sleep_time.tv_nsec);
    }

cleanup:
    if (request != NULL) {
        gpiod_line_request_release(request);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    gpiod_library_exit();
    return 0;
}

