#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define COEF_REG 0xAA
#define OSS 0
#define GPIO_ALERT 24
#define BUFFER_SIZE (60 * 50)

typedef struct {
    uint32_t timestamp;
    float pressure;
} Sample;

Sample buffer[BUFFER_SIZE];
size_t head = 0, tail = 0;

void i2c_read_coefficients(int fd) {
    uint8_t buf[22];

    if (i2cReadByteData(fd, COEF_REG, 22, buf) < 0) {
        perror("i2cReadByteData");
        exit(EXIT_FAILURE);
    }
}

float bmp180_read_pressure(int fd) {
    uint8_t data[3];
    int ret;

    // OSS = 0 (ultra-low power)
    ret = i2cWriteByteData(fd, 0xF4, OSS << 6);
    if (ret < 0) {
        perror("i2cWriteByteData");
        exit(EXIT_FAILURE);
    }
    usleep(5000);

    // Read pressure data
    ret = i2cReadByteData(fd, 0xF6, 3, data);
    if (ret < 0) {
        perror("i2cReadByteData");
        exit(EXIT_FAILURE);
    }

    // Calculate pressure using calibration coefficients
    float pressure = 1.0 * ((data[0] << 8) | data[1]) / 256.0 * (1.0 - 768 / (1.0 * ((data[2] << 8) | data[3])));

    return pressure;
}

void log_sample(Sample sample) {
    if ((head + 1) % BUFFER_SIZE == tail) {
        fprintf(stderr, "Buffer overflow\n");
        exit(EXIT_FAILURE);
    }

    buffer[head] = sample;
    head = (head + 1) % BUFFER_SIZE;
}

float rolling_average(float* data, size_t size) {
    float sum = 0.0;

    for (size_t i = 0; i < size; ++i) {
        sum += data[i];
    }

    return sum / size;
}

float pressure_deviation(float current, float average) {
    return (current - average) / 100.0;
}

void setup_gpio(void) {
    gpioInitialise();
    gpioSetMode(GPIO_ALERT, PI_INPUT);
    gpioSetPullUp(GPIO_ALERT);
}

void cleanup_gpio(void) {
    gpioTerminate();
}

void setup_timer(uint32_t period_us, void (*callback)(void*), void* user_data) {
    gpioSetTimerFuncEx(0, period_us, callback, user_data);
}

void timer_callback(void* user_data) {
    Sample sample;
    int fd;

    time_t now = time(NULL);
    sample.timestamp = (uint32_t)now;

    fd = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (fd < 0) {
        perror("i2cOpen");
        fprintf(stderr, "Sensor not found\n");
        exit(EXIT_FAILURE);
    }

    i2c_read_coefficients(fd);
    sample.pressure = bmp180_read_pressure(fd);
    i2cClose(fd);

    log_sample(sample);

    float average = rolling_average(buffer + tail, BUFFER_SIZE - tail);
    float deviation = pressure_deviation(sample.pressure, average);

    if (deviation > 5.0) {
        fprintf(stderr, "Pressure deviation: %.2f hPa\n", deviation * 100.0);
        gpioWrite(GPIO_ALERT, 1);
    } else {
        gpioWrite(GPIO_ALERT, 0);
    }
}

int main(void) {
    int fd;
    setup_gpio();

    fd = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (fd < 0) {
        perror("i2cOpen");
        fprintf(stderr, "Sensor not found\n");
        exit(EXIT_FAILURE);
    }

    i2c_read_coefficients(fd);
    i2cClose(fd);

    fd = pigpio_init(NULL);
    if (fd < 0) {
        perror("pigpio_init");
        exit(EXIT_FAILURE);
    }

    setup_timer(50 * 1000, timer_callback, NULL);

    while (1) {
        usleep(100000);
    }

    cleanup_gpio();
    pigpio_terminate();

    return EXIT_SUCCESS;
}

