    int i;

    for (i = 0; i < sizeof(*calib_data); i++) {
        if (read(fd, &((char *)calib_data)[i], 1) != 1) {
            perror("Error reading calibration data");
            exit(EXIT_FAILURE);
        }
    }

    if (calib_data->ID != BMP180_ID) {
        fprintf(stderr, "Invalid BMP180 ID\n");
        exit(EXIT_FAILURE);
