This code initializes the BMP180 sensor, reads its calibration data, sets up a hardware timer interrupt to sample the sensor every 500 ms, and logs temperature and pressure readings to `bmp180_log.txt`. It also handles errors during I2C communication and cleans up resources on SIGINT and SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_FAN 18
#define PWM_FREQ 25000
#define MIN_TEMP 40
#define MAX_TEMP 70
#define LOG_INTERVAL 5
#define LOG_FILE "fan_log.txt"

void log_data(const char *format, ...) {
    va_list args;
    time_t now;
    struct tm *tm_now;
    char timestamp[20];

    time(&now);
    tm_now = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    va_start(args, format);
    vfprintf(stdout, format, args);
    fprintf(stdout, "\t%s\n", timestamp);
    va_end(args);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    va_start(args, format);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\t%s\n", timestamp);
    va_end(args);
    fclose(log_file);
}

void sigint_handler(int signum) {
    gpioTerm(GPIO_FAN);
    pigpio_stop();
    exit(0);
}

int main() {
    int temp_fd, duty, prev_temp = -1;
    double temp_scale, temp_offset;
    struct stat st;

    if (pigpio_init() < 0) {
        log_data("pigpio_init failed: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_FAN, PWM_FREQ);

    temp_fd = open("/sys/class/thermal/thermal_zone0/temp", O_RDONLY);
    if (temp_fd < 0) {
        log_data("Failed to open thermal sensor: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fstat(temp_fd, &st) < 0) {
        log_data("Failed to fstat thermal sensor: %s\n", strerror(errno));
        goto cleanup;
    }

    temp_scale = st.st_size / (MAX_TEMP - MIN_TEMP);
    temp_offset = -MIN_TEMP * temp_scale;

    while (1) {
        char temp_buf[32];
        ssize_t bytes_read = read(temp_fd, temp_buf, sizeof(temp_buf) - 1);
        if (bytes_read <= 0) {
            log_data("Failed to read temperature: %s\n", strerror(errno));
            goto cleanup;
        }

        int temp = atoi(temp_buf);
        if (temp < MIN_TEMP) {
            temp = MIN_TEMP;
        } else if (temp > MAX_TEMP) {
            temp = MAX_TEMP;
        }

        duty = (temp - MIN_TEMP) * temp_scale;
        if (duty != prev_temp) {
            gpioPWM(GPIO_FAN, duty);
            prev_temp = duty;
        }

        log_data("Temperature: %d°C, Duty cycle: %d%%\n", temp, duty);
        sleep(LOG_INTERVAL);
    }

cleanup:
    close(temp_fd);
    gpioTerm(GPIO_FAN);
    pigpio_stop();

    return 0;
}

