        if (temp < MIN_TEMP) {
            temp = MIN_TEMP;
        } else if (temp > MAX_TEMP) {
            temp = MAX_TEMP;
        }

        duty = (temp - MIN_TEMP) * temp_scale;
        if (duty != prev_temp) {
            gpioPWM(GPIO_FAN, duty);
            prev_temp = duty;
        }

        log_data("Temperature: %d°C, Duty cycle: %d%%\n", temp, duty);
        sleep(LOG_INTERVAL);
    }

cleanup:
    close(temp_fd);
    gpioTerm(GPIO_FAN);
    pigpio_stop();

    return 0;
}
