code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define LM75_ADDR 0x48
#define GPIO_LINE_LED 18
#define BUFFER_SIZE 60

struct buffer {
    int head;
    int tail;
    double samples[BUFFER_SIZE];
    pthread_mutex_t lock;
};

void i2c_read(int fd, uint8_t reg, uint16_t *data) {
    int ret;
    uint8_t buf[2];

    buf[0] = reg;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }

    ret = read(fd, buf, 2);
    if (ret != 2) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }

    *data = (buf[0] << 8) | buf[1];
}

double lm75_get_temp(int fd) {
    uint16_t temp;
    i2c_read(fd, 0x00, &temp);
    return (double)(temp >> 5) / 256.0;
}

void gpio_setup(int gpio_line) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_get_byname("gpiochip0" GPIOD_LINE_SPECIFIER(gpio_line));
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "temp_led");
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0);
}

void gpio_cleanup(int gpio_line) {
    struct gpiod_line *line;

    line = gpiod_get_byname("gpiochip0" GPIOD_LINE_SPECIFIER(gpio_line));
    if (line) {
        gpiod_line_release(line);
    }
}

void buffer_init(struct buffer *buf) {
    buf->head = buf->tail = 0;
    pthread_mutex_init(&buf->lock, NULL);
}

void buffer_push(struct buffer *buf, double sample) {
    pthread_mutex_lock(&buf->lock);

    buf->samples[buf->head] = sample;
    buf->head = (buf->head + 1) % BUFFER_SIZE;

    if ((buf->head - buf->tail) >= BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    }

    pthread_mutex_unlock(&buf->lock);
}

double buffer_get_avg(const struct buffer *buf) {
    int i, count = (buf->head - buf->tail + BUFFER_SIZE) % BUFFER_SIZE;
    double sum = 0.0;

    for (i = 0; i < count; ++i) {
        sum += buf->samples[(buf->tail + i) % BUFFER_SIZE];
    }

    return sum / count;
}

void *data_acquisition(void *arg) {
    int i2c_fd, ret;
    struct buffer *buf = arg;
    double temp;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Failed to talk to LM75");
        exit(EXIT_FAILURE);
    }

    while (1) {
        temp = lm75_get_temp(i2c_fd);
        buffer_push(buf, temp);
        usleep(1000000);
    }

    close(i2c_fd);
    return NULL;
}

int main() {
    int i2c_fd, ret;
    struct buffer temp_buffer;
    double avg_temp;
    pthread_t daemon_thread;

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("Failed to talk to LM75");
        exit(EXIT_FAILURE);
    }

    gpio_setup(GPIO_LINE_LED);

    buffer_init(&temp_buffer);
    pthread_create(&daemon_thread, NULL, data_acquisition, &temp_buffer);

    while (1) {
        avg_temp = buffer_get_avg(&temp_buffer);
        if (avg_temp > 28.0) {
            gpiod_line_set_value_by_index(gpiochip, GPIO_LINE_LED, 1);
        } else {
            gpiod_line_set_value_by_index(gpiochip, GPIO_LINE_LED, 0);
        }
        sleep(1);
    }

    pthread_join(daemon_thread, NULL);
    gpio_cleanup(GPIO_LINE_LED);
    close(i2c_fd);
    pthread_mutex_destroy(&temp_buffer.lock);

    return 0;
}

