#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <spidev.h>

#define MAX31865_CONFIG_REG 0x80
#define MAX31865_DATA_REG_MSB 0x01
#define MAX31865_DATA_REG_LSB 0x02
#define MAX31865_FAULT_REG 0x07
#define PT100_R_REF 430.0
#define CVD_A 3.9083E-3
#define CVD_B 5.775E-7
#define PWM_FREQ 1000
#define PWM_RES 1000
#define PID_SAMPLE_TIME_MS 100
#define SPI_DEVICE_0 0
#define SPI_MODE 1
#define SPI_SPEED_HZ 500000

struct config {
    double target;
    double Kp;
    double Ki;
    double Kd;
};

void log_error(const char *msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
    exit(EXIT_FAILURE);
}

int read_config(const char *filename, struct config *config) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        log_error("Failed to open config file");
    }

    char line[256];
    struct config default_config = {25.0, 1.0, 0.1, 0.01};
    struct config parsed_config = default_config;

    while (fgets(line, sizeof(line), file)) {
        char key[64], value[64];
        sscanf(line, "%[^:]= %s", key, value);

        if (strcmp(key, "target") == 0) {
            parsed_config.target = atof(value);
        } else if (strcmp(key, "Kp") == 0) {
            parsed_config.Kp = atof(value);
        } else if (strcmp(key, "Ki") == 0) {
            parsed_config.Ki = atof(value);
        } else if (strcmp(key, "Kd") == 0) {
            parsed_config.Kd = atof(value);
        }
    }

    fclose(file);
    if (parsed_config.target == default_config.target &&
        parsed_config.Kp == default_config.Kp &&
        parsed_config.Ki == default_config.Ki &&
        parsed_config.Kd == default_config.Kd) {
        log_error("Missing or invalid config file");
    }

    *config = parsed_config;
    return 0;
}

double pt100_to_resistance(int code) {
    return (code / 32768.0) * PT100_R_REF;
}

double pt100_to_temperature(double resistance) {
    double R0 = 100.0;
    double A = CVD_A * R0;
    double B = CVD_B * R0 * R0;
    double t = log((R0 / resistance - 1) / (A + B * (R0 / resistance)));
    return t;
}

void set_max31865_config(int spi_fd) {
    uint8_t config_data[] = {0xC1};
    write(spi_fd, config_data, sizeof(config_data));
}

int read_max31865_data(int spi_fd, uint16_t *rtd_code, uint8_t *fault_status) {
    uint8_t data[3];

    if (x exchange(data, sizeof(data), spi_fd, MAX31865_DATA_REG_MSB) < 0) {
        return -1;
    }

    *rtd_code = (data[0] << 8) | data[1];
    *fault_status = data[2] & 0x01;
    return 0;
}

void pid_control_loop(double *setpoint, double *pwm_duty, double *error, double *integral, double Kp, double Ki, double Kd) {
    static double prev_error = 0.0;
    double derivative = (*error - prev_error) / PID_SAMPLE_TIME_MS;
    *integral += *error * PID_SAMPLE_TIME_MS;
    double output = Kp * *error + Ki * *integral + Kd * derivative;
    *pwm_duty = output * PWM_RES;
    prev_error = *error;
    *error = *setpoint - *pwm_duty / PWM_RES;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        log_error("Usage: heater_control <config_file>");
    }

    struct config config;
    if (read_config(argv[1], &config) != 0) {
        return EXIT_FAILURE;
    }

    int spi_fd = spi_open(SPI_DEVICE_0, SPI_MODE, SPI_SPEED_HZ);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
    }

    int max31865_spi_handle = spi_setup(spi_fd);
    if (!max31865_spi_handle) {
        log_error("Failed to setup SPI for MAX31865");
    }

    gpioInitialise();
    gpioSetMode(GPIO18, PI_OUTPUT);

    int fault_status;
    uint16_t rtd_code;
    double temperature, error, integral = 0.0, pwm_duty = 0.0;

    while (1) {
        if (read_max31865_data(spi_fd, &rtd_code, &fault_status) != 0) {
            log_error("Failed to read RTD data");
            break;
        }

        if (fault_status & 0x01) {
            log_error("MAX31865 fault detected");
            break;
        }

        temperature = pt100_to_temperature(pt100_to_resistance(rtd_code));
        error = config.target - temperature;
        pid_control_loop(&config.target, &pwm_duty, &error, &integral, config.Kp, config.Ki, config.Kd);

        if (temperature > 80.0 || fault_status & 0x01) {
            pwm_duty = 0.0;
            break;
        }

        gpioHardwarePWM(GPIO18, PWM_FREQ, pwm_duty);
        usleep(PID_SAMPLE_TIME_MS * 1000);
    }

    gpioTerminate();
    spi_close(spi_fd);
    spi_close(max31865_spi_handle);
    exit(EXIT_SUCCESS);
}

