#define BMP180_I2C_ADDR 0x77
#define BMP180_CAL_REG 0xAA
#define BMP180_OSS_0 0x00
#define GPIO_FAN 18
#define BUFFER_SIZE 60

typedef struct {
    uint32_t timestamp;
    int16_t temperature;
    uint16_t pressure;
} Sample;

Sample buffer[BUFFER_SIZE];
volatile int buffer_head = 0;
volatile int buffer_tail = 0;

int bmp180_read_calibration(uint8_t *calibration) {
    int ret;
    if ((ret = i2cWriteRead(BMP180_I2C_ADDR, BMP180_CAL_REG, 1, calibration, 11)) != 11) {
        perror("i2cWriteRead");
        return -1;
    }
    return 0;
}

int bmp180_read_data(int16_t *temperature, uint16_t *pressure) {
    uint8_t data[6];
    int ret;

    // Reset the sensor
    if ((ret = i2cWrite(BMP180_I2C_ADDR, 0xF4, 1)) != 1) {
        perror("i2cWrite");
        return -1;
    }

    // Wait for the sensor to stabilize
    usleep(17);

    // Read the data
    if ((ret = i2cWriteRead(BMP180_I2C_ADDR, 0xF5, 1, data, 6)) != 6) {
        perror("i2cWriteRead");
        return -1;
    }

    // Calculate temperature and pressure
    uint32_t ac1, ac2, ac3, ac4, ac5, ac6;
    int16_t b1, b2, b5, mb, mc, m_bsl;
    uint32_t b6, b7, b8, b9, b10, b11;
    uint32_t x1, x2, x3, x4, x5, x6, x7, b3, p;
    uint32_t temp_fine;

    memcpy(calibration, data, 11);

    ac1 = calibration[0] << 8 | calibration[1];
    ac2 = calibration[2] << 8 | calibration[3];
    ac3 = calibration[4] << 8 | calibration[5];
    ac4 = calibration[6] << 8 | calibration[7];
    ac5 = calibration[8] << 8 | calibration[9];
    ac6 = calibration[10];

    b1 = data[0];
    b2 = data[1];
    m_bsl = data[2];
    mb = data[3];
    mc = data[4];
    b5 = data[5];

    b6 = (b2 & 0x0F) << 8 | b3;
    b7 = (b2 & 0xF0) << 4 | (b4 & 0x0F);
    b8 = (b4 & 0xF0) >> 4;
    b9 = b5;

    b10 = (data[6] & 0x0F) << 8 | b11;
    b11 = (data[6] & 0xF0) >> 4;

    temp_fine = (b6 << 16) | (b7 << 8) | b8;
    x1 = (temp_fine / 2097152L) * 62503L;
    x2 = temp_fine - x1;
    x3 = x1 * x1 * x1 >> 15;
    x4 = x3 * 2L;
    x5 = (x2 * x2 * x2 >> 15) * 2L;
    x6 = x4 + x5;
    x7 = (x6 * 2L) >> 15;
    temp_fine = (x1 + x7) * 5 + 128;

    *temperature = (temp_fine * 100) / 100;

    b6 = b10 >> 8;
    b7 = b10 & 0xFF;
    b8 = b11 >> 4;
    b9 = b11 & 0xF0;

    p = (b6 << 24) | (b7 << 18) | (b8 << 12) | (b9 << 4);
    p = p >> (8 - BMP180_OSS_0);
    p = p * 266625L / 1024;
    *pressure = p;

    return 0;
}

void timer_cb(int gpio, uint32_t tick) {
    int16_t temperature, pressure;
    if (bmp180_read_data(&temperature, &pressure) == 0) {
        buffer[buffer_head].timestamp = time(NULL);
        buffer[buffer_head].temperature = temperature;
        buffer[buffer_head].pressure = pressure;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        if (temperature > 30000) {
            gpioWrite(GPIO_FAN, 1);
        } else {
            gpioWrite(GPIO_FAN, 0);
