Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>

#define MAX_TEMP 25.0
#define MAX_DUTY 80
#define SPI_BUS 0
#define SPI_DEVICE 0
#define RELAY_GPIO 17
#define CS_GPIO 8
#define MISO_GPIO 9
#define MOSI_GPIO 10
#define SCLK_GPIO 11

static const char *log_file = "heater_log.csv";

void log_data(double temp, uint16_t duty) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    FILE *log = fopen(log_file, "a");
    fprintf(log, "%s,%f,%u\n", timestamp, temp, duty);
    fclose(log);
}

void spi_init() {
    int spi_fd = open("/dev/spidev" SPI_BUS, O_RDWR);
    if (spi_fd < 0) {
        perror("Cannot open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfers[] = {
        {
            .tx_buf = (unsigned char *) &CS_GPIO,
            .len = 1,
            .speed_hz = 2000000,
        },
        {
            .rx_buf = (unsigned char *) &CS_GPIO,
            .len = 1,
            .speed_hz = 2000000,
        },
        {
            .tx_buf = (unsigned char *) &MAX31855_READ,
            .len = 1,
            .speed_hz = 2000000,
        },
        {
            .rx_buf = (unsigned char *) &data,
            .len = 4,
            .speed_hz = 2000000,
        },
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 1) {
        perror("Cannot configure SPI transfer");
        exit(EXIT_FAILURE);
    }
}

double max31855_read() {
    int16_t raw = ((int16_t)data[0] << 8) | data[1];
    double temp = 100.0 * (raw - 32768) / 16384.0;
    if (temp < -273.15) {
        // MAX31855 fault
        return NAN;
    }
    return temp;
}

void heater_control(double setpoint) {
    double kp = 10.0, ki = 0.0, prev_error = 0.0;
    double error, duty;

    while (1) {
        double temp = max31855_read();
        if (isnan(temp)) {
            duty = 0;
            log_data(temp, duty);
            continue;
        }

        error = setpoint - temp;
        double integral = error + prev_error;
        double output = kp * error + ki * integral;
        if (output > MAX_DUTY) {
            output = MAX_DUTY;
        }
        if (output < 0) {
            output = 0;
        }
        prev_error = error;

        gpio_set_PWM_dutycycle(RELAY_GPIO, 0, output * 1000);
        log_data(temp, output);
    }
}

int main(int argc, char **argv) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    spi_init();

    double setpoint = MAX_TEMP;
    if (argc > 1) {
        setpoint = atof(argv[1]);
    }

    heater_control(setpoint);

    gpioTerminate();
    close(spi_fd);
    return 0;
}
```

This code initializes the SPI bus, reads temperature from the MAX31855, and controls the heater using a PI controller. It logs temperature and PWM duty cycle to a CSV file with ISO-8601 timestamps. The heater is turned off on SIGINT and SIGTERM signals.

You'll need to define `MAX31855_READ` as a constant with the appropriate value for your thermocouple amplifier. Also, don't forget to include the necessary header files for your specific development environment.

Compile the code with:

```bash
gcc -o heater heater.c -lrt -lpthread -lpigpio -o heater
```

Run the compiled program with:

```bash
./heater [target_temperature]
```

Replace `[target_temperature]` with the desired temperature in Celsius. If no temperature is provided, the default value of 25.0°C will be used.

