#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_RED 17
#define GPIO_GREEN 18
#define GPIO_BLUE 27
#define THRESHOLD_LOW 40000
#define THRESHOLD_MID 59999
#define THRESHOLD_HIGH 60000

volatile sig_atomic_t sig_received = 0;

void signal_handler(int signum) {
    sig_received = 1;
}

void set_rgb(int r, int g, int b) {
    gpioPWM(GPIO_RED, r);
    gpioPWM(GPIO_GREEN, g);
    gpioPWM(GPIO_BLUE, b);
}

int read_temp_file(const char *filename, int *value) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open temperature file");
        return -1;
    }

    char buffer[10];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read <= 0) {
        if (ferror(fd)) {
            perror("Failed to read temperature file");
        }
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0';
    *value = atoi(buffer);
    close(fd);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!sig_received) {
        int temp_mdegC;
        if (read_temp_file("/sys/class/thermal/thermal_zone0/temp", &temp_mdegC) < 0) {
            continue;
        }

        int r = 0, g = 0, b = 0;
        if (temp_mdegC < THRESHOLD_LOW) {
            r = 0;
            g = 0;
            b = 255;
        } else if (temp_mdegC < THRESHOLD_MID) {
            r = 0;
            g = 255;
            b = 0;
        } else if (temp_mdegC <= THRESHOLD_HIGH) {
            r = 255;
            g = 0;
            b = 0;
        } else {
            fprintf(stderr, "Temperature value out of range: %d m°C\n", temp_mdegC);
            continue;
        }

        set_rgb(255 - r, 255 - g, 255 - b);
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp_mdegC, r, g, b);
        usleep(500000); // Sleep for 0.5 seconds
    }

    set_rgb(255, 255, 255); // Turn off all channels on exit
    gpioTerminate();
    return 0;
}

