#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_PIN 4
#define DHT22_DATA_PIN 23
#define DHT22_PULSE_LEN 50
#define DHT22_RETRY_COUNT 3

static size_t write_data(void *ptr, size_t size, size_t nmemb, void *userp)
{
    size_t remain = *((size_t *)userp);
    size_t result = size * nmemb;
    if (result > remain)
        result = remain;

    memcpy(userp, ptr, result);
    remain -= result;
    *(size_t *)userp = remain;

    return result;
}

int main()
{
    int ret, i;
    gpioInit();
    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioSetMode(DHT22_DATA_PIN, PI_INPUT);
    piThreadDelay(1); // Delay 1ms to ensure the data line is low
    gpioWrite(DHT22_PIN, 0);
    piThreadDelay(DHT22_PULSE_LEN);
    gpioWrite(DHT22_PIN, 1);

    unsigned char data[5];
    for (i = 0; i < DHT22_RETRY_COUNT; ++i) {
        unsigned char bit;
        for (int j = 0; j < 40; ++j) {
            piThreadDelay(DHT22_PULSE_LEN / 2);
            gpioToggle(DHT22_DATA_PIN);
            piThreadDelay(DHT22_PULSE_LEN / 2);
            bit = gpioRead(DHT22_DATA_PIN);
            data[j / 8] <<= 1;
            data[j / 8] |= bit;
        }

        unsigned char checksum = data[0] ^ data[1] ^ data[2] ^ data[3];
        if (checksum == data[4]) {
            float humidity = (data[0] << 8) | data[1];
            humidity /= 10;
            float temperature = (data[2] << 8) | data[3];
            temperature = (temperature / 10.0) - 45;

            CURL *curl;
            CURLcode res;
            curl_global_init(CURL_GLOBAL_DEFAULT);
            curl = curl_easy_init();
            if (curl) {
                char json[100];
                snprintf(json, sizeof(json), "{\"humidity\": %.2f, \"temperature\": %.2f}", humidity, temperature);
                curl_easy_setopt(curl, CURLOPT_URL, "http://yourserver.com/api/humidity");
                curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
                curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
                curl_easy_setopt(curl, CURLOPT_WRITEDATA, &json);
                res = curl_easy_perform(curl);
                if (res != CURLE_OK)
                    fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
                curl_easy_cleanup(curl);
            }
            curl_global_cleanup();
            break;
        }
    }

    gpioTerm();
    return 0;
}

void signal_handler(int signum)
{
    gpioTerm();
    exit(0);
}

int main(int argc, char *argv[])
{
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    return main();
}

