#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define DHT22_PIN 7
#define MIN_HIGH_US 20
#define MAX_HIGH_US 40
#define MIN_LOW_US 1000
#define MAX_LOW_US 1000
#define CHECKSUM_ERROR 0x50
#define CURL_RETRY_COUNT 3
#define SLEEP_INTERVAL 10
#define DEFAULT_URL "http://your-server.com/api/humidity"

static char *url = DEFAULT_URL;
static CURL *curl;
static int retry_count = CURL_RETRY_COUNT;

static void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

static int dht22_read(void) {
    int data[5];
    int i, j, low_us, high_us, checksum;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    sleep_us(18);
    gpioWrite(DHT22_GPIO, 1);
    sleep_us(40);
    gpioWrite(DHT22_GPIO, 0);

    for (i = 0; i < 40; i++) {
        low_us = gpioRead(DHT22_GPIO);
        if (low_us < MIN_LOW_US || low_us > MAX_LOW_US) {
            return -1;
        }
        sleep_us(1);
        high_us = gpioRead(DHT22_GPIO);
        if (high_us < MIN_HIGH_US || high_us > MAX_HIGH_US) {
            return -1;
        }
        sleep_us(48);
    }

    for (i = 0; i < 40; i++) {
        low_us = gpioRead(DHT22_GPIO);
        if (low_us < MIN_LOW_US || low_us > MAX_LOW_US) {
            return -1;
        }
        data[i / 8] <<= 1;
        if (low_us > (MAX_LOW_US - MIN_LOW_US) / 2) {
            data[i / 8] |= 1;
        }
        sleep_us(48);
    }

    checksum = data[0] + data[1] + data[2] + data[3];
    if (data[4] != checksum) {
        return -1;
    }

    float humidity = (data[0] * 256 + data[1]) / 10;
    float temperature = (data[2] * 256 + data[3]) / 10;

    return (int)(humidity * 100);
}

static size_t write_data(void *ptr, size_t size, size_t nmemb, void *userp) {
    char *buffer = userp;
    size_t remaing = buffer_size(buffer);
    size_t to_copy = size * nmemb < remaing ? size * nmemb : remaing;
    memcpy(buffer, ptr, to_copy);
    buffer += to_copy;
    remaing -= to_copy;
    return to_copy;
}

int main(int argc, char **argv) {
    int humidity;
    int ret;
    int gpio_init_ret;
    int curl_init_ret;

    if (argc > 1 && !strcmp(argv[1], "-s")) {
        if (argc != 3) {
            log_message(LOG_ERR, "Invalid URL specified: %s", argv[2]);
            return 1;
        }
        url = argv[2];
    }

    gpio_init_ret = gpioInitialise();
    if (gpio_init_ret < 0) {
        log_message(LOG_ERR, "Failed to initialize pigpio: %s", gpioStrerror(gpio_init_ret));
        return 1;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl_init_ret = curl_global_init();
    if (curl_init_ret != CURLE_OK) {
        log_message(LOG_ERR, "Failed to initialize libcurl: %s", curl_easy_strerror(curl_init_ret));
        return 1;
    }
    curl = curl_easy_init();
    if (!curl) {
        log_message(LOG_ERR, "Failed to create libcurl handle");
        return 1;
    }

    while (1) {
        humidity = dht22_read();
        if (humidity < 0) {
            log_message(LOG_ERR, "Failed to read DHT22 sensor");
            sleep(2);
            continue;
        }

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, "{ \"humidity\": ");
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, malloc(100));
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, 15);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, dlistAppend(NULL, "Content-Type: application/json", true));

        ret = curl_easy_perform(curl);
        if (ret != CURLE_OK) {
            log_message(LOG_ERR, "Failed to POST data to server: %s", curl_easy_strerror(ret));
            retry_count--;
            if (retry_count <= 0) {
                log_message(LOG_ERR, "Maximum retries exceeded");
                break;
            }
            sleep(2);
            continue;
        }

        retry_count = CURL_RETRY_COUNT;
        log_message(LOG_INFO, "Humidity: %d%%", humidity);
        sleep(SLEEP_INTERVAL);
    }

    free(curl_easy_get_writefunction(curl));
    curl_easy_cleanup(curl);
    curl_global_cleanup();
    gpioTerminate();

    return 0;
}

