#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

#define MAX_FAN_STATE 3

struct timeval last_log_time;

void log_fan_state(int fan_state) {
    struct timeval current_time;
    gettimeofday(&current_time, NULL);

    if (difftime(current_time.tv_sec, last_log_time.tv_sec) > 1) {
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fprintf(log_file, "%ld.%06ld: Fan state changed to %d\n",
                    current_time.tv_sec, current_time.tv_usec, fan_state);
            fclose(log_file);
            last_log_time = current_time;
        }
    }
}

int read_temp_file(char *buf) {
    int fd = open(TEMP_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening temperature file");
        return -1;
    }

    ssize_t bytes_read = read(fd, buf, sizeof(buf));
    if (bytes_read < 0) {
        perror("Error reading temperature file");
        close(fd);
        return -1;
    }

    close(fd);
    buf[bytes_read] = '\0';
    return bytes_read;
}

int read_fan_file(char *buf) {
    int fd = open(FAN_FILE, O_RDONLY);
    if (fd < 0) {
        perror("Error opening fan file");
