#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>

#define MAX_TEMP 100.0
#define MIN_TEMP 0.0
#define TARGET_TEMP 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define SPI_DEVICE_ID 0
#define SPI_MODE 0
#define SPI_SPEED_HZ 500000
#define GPIO_HEATER 18
#define GPIO_HEATER_MIN 0
#define GPIO_HEATER_MAX 100
#define GPIO_HEARTBEAT 13
#define HEARTBEAT_INTERVAL 1000
#define LOG_FILE "heater_log.txt"

volatile sig_atomic_t running = 1;

double temperature = 0.0;
double prev_error = 0.0;
double integral = 0.0;
double derivative = 0.0;
double setpoint = TARGET_TEMP;
double pwm_duty_cycle = 0.0;
int spi_fd = -1;

void sigint_handler(int signum) {
    running = 0;
}

void spi_write(const unsigned char *data, int len) {
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (write(spi_fd, data, len) != len) {
        perror("Failed to write to SPI device");
        exit(EXIT_FAILURE);
    }
}

unsigned char spi_read(int len) {
    unsigned char buf[len];
    if (read(spi_fd, buf, len) != len) {
        perror("Failed to read from SPI device");
        exit(EXIT_FAILURE);
    }
    return buf[0];
}

void log_data(const char *message, double temperature, double pwm_duty_cycle, double pid_output) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s: %.2f°C, PWM %.0f%%, PID %.4f\n", message, temperature, pwm_duty_cycle * 100.0, pid_output);
    fclose(log_file);
}

void handle_thermocouple_fault(unsigned char data) {
    if ((data & 0x04) != 0) {
        log_data("Open circuit", temperature, pwm_duty_cycle, 0.0);
        pwm_duty_cycle = 0.0;
        setpoint = TARGET_TEMP;
    } else if ((data & 0x02) != 0) {
        log_data("Short to GND", temperature, pwm_duty_cycle, 0.0);
        pwm_duty_cycle = 0.0;
        setpoint = TARGET_TEMP;
    } else if ((data & 0x01) != 0) {
        log_data("Short to VCC", temperature, pwm_duty_cycle, 0.0);
        pwm_duty_cycle = 0.0;
        setpoint = TARGET_TEMP;
    }
}

int main() {
    int ret;
    unsigned char data[4];
    double error, prev_temperature = 0.0;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_HEATER, PI_OUTPUT);
    gpioSetMode(GPIO_HEARTBEAT, PI_OUTPUT);

    while (running) {
        spi_write((const unsigned char[]) {0x00, 0x00, 0x00, 0x00}, 4);
        usleep(10000);
        spi_write((const unsigned char[]) {0x01, 0x00, 0x00, 0x00}, 4);
        data[0] = spi_read(1);
        data[1] = spi_read(1);
        data[2] = spi_read(1);
        data[3] = spi_read(1);

        if (data[0] & 0x80) {
            handle_thermocouple_fault(data[0]);
            continue;
        }

        temperature = (data[1] | (data[2] << 8) | (data[3] << 16)) * 0.01;

        if (temperature > MAX_TEMP || temperature < MIN_TEMP) {
            log_data("Temperature out of range", temperature, pwm_duty_cycle, 0.0);
            pwm_duty_cycle = 0.0;
            setpoint = TARGET_TEMP;
        }

        error = setpoint - temperature;
        integral += error;
        derivative = error - prev_error;
        double pid_output = Kp * error + Ki * integral + Kd * derivative;

        if (pid_output < GPIO_HEATER_MIN) {
            pid_output = GPIO_HEATER_MIN;
        } else if (pid_output > GPIO_HEATER_MAX) {
            pid_output = GPIO_HEATER_MAX;
        }

        pwm_duty_cycle = pid_output / (GPIO_HEATER_MAX - GPIO_HEATER_MIN);
        gpioWrite(GPIO_HEATER, pwm_duty_cycle);

        prev_temperature = temperature;
        log_data("Temperature", temperature, pwm_duty_cycle, pid_output);

        usleep(1000000);
        gpioWrite(GPIO_HEARTBEAT, !gpioRead(GPIO_HEARTBEAT));
    }

    gpioTerm();
    close(spi_fd);
    return 0;
}

