#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR_MAP 0x08, 0x09
#define NUM_SENSORS 2
#define CRC_POLYNOMIAL 0x31
#define BUFFER_SIZE 6

static int i2c_write_read(int bus, uint8_t addr, uint8_t *write_buf, size_t write_len, uint8_t *read_buf, size_t read_len) {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteRead(bus, addr, write_buf, write_len, read_buf, read_len) >= 0)
            return 1;
        usleep(100000);
        retries--;
    }
    return 0;
}

static uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        for (uint8_t j = 8; j > 0; j--) {
            crc = (crc << 1) ^ (crc & 0x80 ? CRC_POLYNOMIAL : 0);
            crc ^= data[i];
        }
    }
    return crc;
}

static int validate_crc(uint8_t *data, size_t len) {
    return crc8(data, len - 1) == data[len - 1];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    int i2c_fd = pigpio_i2c_open(I2C_BUS, -1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    struct timespec ts = { 1, 0 };
    FILE *log_file = fopen("flow_log.txt", "w+");
    if (!log_file) {
        perror("Failed to open flow_log.txt");
        goto cleanup;
    }

    while (1) {
        for (size_t i = 0; i < NUM_SENSORS; i++) {
            uint8_t addr = SENSOR_ADDR_MAP[i];
            uint8_t cmd[] = { 0x36, 0x08 };
            uint8_t data[BUFFER_SIZE];

            if (!i2c_write_read(I2C_BUS, addr, cmd, sizeof(cmd), data, sizeof(data))) {
                fprintf(stderr, "I2C error reading sensor %zu\n", i);
                continue;
            }

            if (!validate_crc(data, sizeof(data))) {
                fprintf(stderr, "CRC error for sensor %zu\n", i);
                continue;
            }

            double flow_rate = data[1] * 0x100 + data[2];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
