#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

#define ADPD144RI_I2C_BUS 1
#define ADPD144RI_I2C_ADDR 0x39
#define GPIO_LINE_LED 17

static const char *adpd144ri_log_path = "adpd144ri_log.txt";
static gpiod_line_request_lines_data_v1 _gpio_led_request_data = { .lines = { { .direction = GPIOD_LINE_DIR_OUT, .active_low = 0 } } };
static gpiod_line_request_data_v1 _gpio_led_request_data_v1 = { .version = GPIOD_LINE_REQUEST_DATA_VERSION, .lines = &_gpio_led_request_data };
static gpiod_line_request *_gpio_led_request = NULL;

void log_timestamped_data(int red, int ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stdout, "%s,%d,%d\n", timestamp, red, ir);
    fprintf(stderr, "%s,%d,%d\n", timestamp, red, ir);

    FILE *log_file = fopen(adpd144ri_log_path, "a");
    if (log_file) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
        fclose(log_file);
    }
}

int read_adpd144ri(int fd) {
    char data[2];
    int ret;

    ret = ioctl(fd, I2C_SLAVE, ADPD144RI_I2C_ADDR << 1);
    if (ret < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    ret = read(fd, data, 2);
    if (ret != 2) {
        perror("read");
        return -1;
    }

    return ((data[0] << 8) | data[1]);
}

void handle_signal(int signum) {
    if (_gpio_led_request) {
        gpiod_line_release(_gpio_led_request, _gpio_led_request_data_v1);
        _gpio_led_request = NULL;
    }

    if (access(adpd144ri_log_path, F_OK)) {
        unlink(adpd144ri_log_path);
    }

    exit(0);
}

int main() {
    int i2c_fd = -1;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open(/dev/i2c-1)");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_I2C_ADDR << 1) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(i2c_fd);
        return -1;
    }

    _gpio_led_request = gpiod_chip_get_line_request_data(_gpio_led_request, "gpiochip0", GPIO_LINE_LED);
    if (!_gpio_led_request) {
        perror("gpiod_chip_get_line_request_data");
        close(i2c_fd);
        return -1;
    }

    ret = gpiod_line_request_enable(_gpio_led_request, &_gpio_led_request_data_v1);
    if (ret < 0) {
        perror("gpiod_line_request_enable");
        gpiod_line_release(_gpio_led_request, _gpio_led_request_data_v1);
        _gpio_led_request = NULL;
        close(i2c_fd);
        return -1;
    }

    while (1) {
        int red = 0, ir = 0;
        int reading = read_adpd144ri(i2c_fd);
        if (reading < 0) {
            perror("read_adpd144ri");
            continue;
        }

        red = (reading >> 8) & 0xFF;
        ir = reading & 0xFF;

        if (ir > 2000) {
            gpiod_line_set_value(_gpio_led_request, _gpio_led_request_data_v1, 1);
        } else {
            gpiod_line_set_value(_gpio_led_request, _gpio_led_request_data_v1, 0);
        }

        log_timestamped_data(red, ir);
        usleep(100000);
    }

    gpiod_line_release(_gpio_led_request, _gpio_led_request_data_v1);
    _gpio_led_request = NULL;
    close(i2c_fd);

    return 0;
}

