#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 10000000 // 1 second in nanoseconds
#define RPM_LOG_BUFFER_SIZE 1024

volatile uint32_t pulse_counter = 0;
pthread_mutex_t pulse_counter_mutex = PTHREAD_MUTEX_INITIALIZER;

void signal_handler(int sig) {
    (void)sig;
    pigpio_stop();
    fclose(log_file);
    pthread_mutex_destroy(&pulse_counter_mutex);
    exit(0);
}

void isr(int gpio, uint32_t events, void *user_data) {
    (void)user_data;

    if (events & PI_EDGE_RISING) {
        pthread_mutex_lock(&pulse_counter_mutex);
        pulse_counter++;
        pthread_mutex_unlock(&pulse_counter_mutex);
    }
}

void log_rpm() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double elapsed_seconds = ts.tv_sec + ts.tv_nsec / 1_ billion;
    double rpm = (double)pulse_counter * 60.0 / elapsed_seconds;

    char log_line[RPM_LOG_BUFFER_SIZE];
    snprintf(log_line, RPM_LOG_BUFFER_SIZE, "%lf RPM\n", rpm);

    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT | O_NOCTTY, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_fd < 0) {
        perror("Failed to open log file");
        return;
    }

    if (write(log_fd, log_line, strlen(log_line)) < 0) {
        perror("Failed to write to log file");
    }

    fsync(log_fd);
    close(log_fd);

    pulse_counter = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        return 1;
    }

    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    if (gpioSetAlertFunc(GPIO_PIN, false, isr, NULL) < 0) {
        perror("Failed to set ISR");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct timespec sleep_ts;
    clock_gettime(CLOCK_MONOTONIC, &sleep_ts);
    sleep_ts.tv_sec += SAMPLE_INTERVAL / 1_ billion;

    while (1) {
        nanosleep(&sleep_ts, &sleep_ts);
        log_rpm();
    }

    return 0;
}

