#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

static char log_file[] = "flow_log.csv";
static FILE *log_fp;

void log_flow_rate(double flow_rate) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char time_str[32];
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_fp, "%s,%f\n", time_str, flow_rate);
    fflush(log_fp);
}

uint16_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc >> 1) ^ (crc & 0x01 ? CRC_POLYNOMIAL : 0);
            crc = (crc & 0x00FF) << 8 | (data[i] & 0x00FF);
        }
    }
    return crc;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return -1;
    }
    return 0;
}

int init_i2c(int bus) {
    if (i2cOpen(bus, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", bus);
        return -1;
    }
    return 0;
}

int write_i2c(const uint8_t *data, size_t len) {
    if (i2cWriteRead(I2C_BUS, I2C_ADDR, data, len, NULL, 0) < (int)len) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }
    return 0;
}

int read_i2c(uint8_t *buf, size_t len) {
    if (i2cWriteRead(I2C_BUS, I2C_ADDR, NULL, 0, buf, len) < (int)len) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }
    return 0;
}

int main() {
    if (init_pigpio() < 0) {
        return 1;
    }

    if (log_fp = fopen(log_file, "a")) {
        if (setvbuf(log_fp, NULL, _IOLBF, 0)) {
            perror("Failed to set vbuf on log file");
            fclose(log_fp);
            log_fp = NULL;
        }
    } else {
        perror("Failed to open log file");
        goto cleanup;
    }

    if (init_i2c(I2C_BUS) < 0) {
        goto cleanup;
    }

    uint8_t command[] = {0x36, 0x08};
    if (write_i2c(command, sizeof(command)) < 0) {
        goto cleanup;
    }

    while (1) {
        uint8_t data[3];
        if (read_i2c(data, sizeof(data)) < 0) {
            continue;
        }

        uint16_t raw_flow = (data[0] << 8) | data[1];
        uint8_t crc = data[2];
        uint16_t calculated_crc = crc8(&data[0], sizeof(data) - 1);

        if (calculated_crc != crc) {
            fprintf(stderr, "Invalid CRC from sensor\n");
            continue;
        }

        double flow_rate = (double)raw_flow / 1000.0;
        log_flow_rate(flow_rate);
    }

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    gpioTerminate();
    return 0;
}

