Here's a complete, compilable C code for a Raspberry Pi Zero W using the pigpio library to interface with a Honeywell MICS-VZ-89TE VOC sensor connected on I2C bus 1 at address 0x70. The code logs the IAQ, TVOC, and eCO2 values to 'air_quality_log.csv' every 5 seconds.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x70
#define REG_DATA 0x00

static int g_i2c_fd = -1;
static time_t g_last_log_time = 0;

void i2c_write_read(uint8_t addr, uint8_t reg, uint8_t *write_buf, size_t write_len, uint8_t *read_buf, size_t read_len) {
    int ret;
    if ((ret = i2cWriteRead(g_i2c_fd, addr << 1, &reg, 1, write_buf, write_len, read_buf, read_len)) < 0) {
        perror("i2cWriteRead");
        exit(EXIT_FAILURE);
    }
}

float clamp(float value, float min, float max) {
    return value < min ? min : (value > max ? max : value);
}

void log_air_quality(float iq, float tvoc, float eco2) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log_file = fopen("air_quality_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "%s,IAQ,TVOC,eCO2\n", timestamp);
    fprintf(log_file, "%s,%.1f,%.0f,%.0f\n", timestamp, iq, tvoc, eco2);
    fflush(log_file);
    fclose(log_file);

    g_last_log_time = now;
}

int main(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if ((g_i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR)) < 0) {
        perror("pigpio_i2c_open");
        exit(EXIT_FAILURE);
    }

    uint8_t data[8] = {0};
    while (1) {
        i2c_write_read(SENSOR_ADDR, REG_DATA, NULL, 0, data, 8);

        if (data[0] != 0x71 || data[1] != 0x01) {
            fprintf(stderr, "Invalid sensor response\n");
            continue;
        }

        float tvoc = (data[1] << 8 | data[2]) / 10.0;
        float eco2 = (data[5] << 8 | data[6]) / 10.0;
        float iq = clamp(100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0), 0, 100);

        if (difftime(time(NULL), g_last_log_time) > 5) {
            log_air_quality(iq, tvoc, eco2);
            g_last_log_time = time(NULL);
        }

        usleep(500000); // Sleep for 500ms before the next read
    }

    pigpio_i2c_close(g_i2c_fd);
    gpioTerm();
    return 0;
}
