    if (line_fd < 0) {
        perror("Failed to request line");
        gpiod_chip_close(chip_fd);
        exit(EXIT_FAILURE);
    }

    _line_data = gpiod_line_get_data(line_fd);

    clock_gettime(CLOCK_MONOTONIC, &_touch_start);

    while (1) {
        int value = gpiod_line_get_value(line_fd);
        if (value < 0) {
            perror("Failed to read line value");
            gpiod_line_release_request(line_fd);
            gpiod_chip_close(chip_fd);
            exit(EXIT_FAILURE);
        }

        if (value == 1) {
            clock_gettime(CLOCK_MONOTONIC, &_touch_end);
            if ((_touch_end.tv_sec - _touch_start.tv_sec) * 1000 + (_touch_end.tv_nsec - _touch_start.tv_nsec) / 1_000_000 >= TOUCH_THRESHOLD) {
                printf("Intrusion alert\n");
                _touch_count++;
                clock_gettime(CLOCK_MONOTONIC, &_touch_start);
            }
        }

        usleep(POLL_INTERVAL);
    }

    gpiod_line_release_request(line_fd);
    gpiod_chip_close(chip_fd);

    return EXIT_SUCCESS;
}

