#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>
#include <string.h>
#include <sys/ioctl.h>
#include <alsa/asoundlib.h>
#include <linux/types.h>
#include <gpiod.h>

#define GPIO_LINE_WIDTH_RAW 32
#define GPIO_LINE_WIDTH_BITS 5
#define GPIO_LINE_WIDTH (1 << GPIO_LINE_WIDTH_BITS)
#define GPIO_LINE_NUM 17

static int g_i2s_fd = -1;
static snd_pcm_t *g_handle = NULL;
static gpio_line_request_data_t *g_gpio_line_request = NULL;

void gpio_line_cb(struct gpiod_line_event *ev, void *data) {
    (void) ev;
    gpiod_line_set_value_cansleep(g_gpio_line_request, !gpio_line_get_value(g_gpio_line_request));
}

int init_gpio(void) {
    int ret;
    g_gpio_line_request = gpiod_chip_get_line_request(gpiod_chip_get_by_name("gpiochip0"), GPIO_LINE_NUM);
    if (!g_gpio_line_request) {
        perror("Failed to get line request");
        return -1;
    }

    ret = gpiod_line_request_direction_output(g_gpio_line_request, GPIOD_LINE_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to set direction");
        return -1;
    }

    gpiod_line_add_event_callback(g_gpio_line_request, gpio_line_cb, NULL);
    gpiod_line_request_enable(g_gpio_line_request, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);

    return 0;
}

int init_i2s(void) {
    int ret;
    snd_pcm_hw_params_t *params;
    ret = snd_pcm_open(&g_handle, "plughw:1,0", SND_PCM_STREAM_CAPTURE, 0);
    if (ret < 0) {
        perror("Failed to open ALSA I2S device");
        return -1;
    }

    ret = snd_pcm_hw_params_malloc(sizeof(*params));
    if (ret < 0) {
        perror("Failed to allocate hardware parameters object");
        goto close_device;
    }

    params = params_malloc(sizeof(*params));
    if (!params) {
        perror("Failed to allocate hardware parameters object");
        ret = -1;
        goto free_params;
    }

    ret = snd_pcm_hw_params_any(g_handle, params);
    if (ret < 0) {
        perror("Failed to initialize hardware parameters");
        goto free_params;
    }

    ret = snd_pcm_hw_params_set_access(g_handle, params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (ret < 0) {
        perror("Failed to set access type");
        goto free_params;
    }

    ret = snd_pcm_hw_params_set_format(g_handle, params, SND_PCM_FORMAT_S16_LE);
    if (ret < 0) {
        perror("Failed to set sample format");
        goto free_params;
    }

    ret = snd_pcm_hw_params_set_channels(g_handle, params, 1);
    if (ret < 0) {
        perror("Failed to set channel count");
        goto free_params;
    }

    ret = snd_pcm_hw_params_set_rate_near(g_handle, params, &g_sample_rate, 0);
    if (ret < 0) {
        perror("Failed to set sample rate");
        goto free_params;
    }

    ret = snd_pcm_hw_params(g_handle, params);
    if (ret < 0) {
        perror("Failed to apply hardware parameters");
        goto free_params;
    }

    ret = snd_pcm_prepare(g_handle);
    if (ret < 0) {
        perror("Failed to prepare for recording");
        goto free_params;
    }

free_params:
    snd_pcm_hw_params_free(params);

close_device:
    snd_pcm_close(g_handle);

    return ret;
}

void cleanup(void) {
    if (g_handle != NULL) {
        snd_pcm_drain(g_handle);
        snd_pcm_close(g_handle);
        g_handle = NULL;
    }

    if (g_gpio_line_request != NULL) {
        gpiod_line_request_dispose(g_gpio_line_request);
        g_gpio_line_request = NULL;
    }
}

int main(void) {
    int ret;

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_i2s() < 0) {
        return 1;
    }

    FILE *file = fopen("audio_capture.pcm", "wb");
    if (!file) {
        perror("Failed to open output file");
        goto cleanup;
    }

    while (1) {
        unsigned int frames;
        void *buffer;
        ret = snd_pcm_readi(g_handle, &buffer, 1024);
        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Failed to read audio data");
            goto cleanup;
        }

        frames = ret / GPIO_LINE_WIDTH;
        for (unsigned int i = 0; i < frames; ++i) {
            unsigned int sample = ((*(unsigned int*)(buffer + i * GPIO_LINE_WIDTH)) >> 8) & 0xFFFF;
            fwrite(&sample, sizeof(sample), 1, file);
        }
    }

cleanup:
    fclose(file);
    cleanup();

    return 0;
}

