    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, event);
    fprintf(stderr, "%s\n", time_string);
    fflush(stderr);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_string, event);
        fclose(log_file);
    }
}

int main() {
    int ret;
    uint32_t sensor_state;
    uint32_t prev_state = 1;
    uint32_t flame_duration = 0;
    uint32_t duty_cycle = 0;
    struct pigpio *pi;

    if ((pi = pigpio_init(NULL)) == NULL) {
        log_event("Failed to initialize pigpio library");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_event("Failed to initialize GPIO");
        pigpio_stop(pi);
        return 1;
    }

    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        log_event("Failed to set PWM frequency");
        gpioTerm(pi);
        return 1;
    }

    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        log_event("Failed to open log file");
        gpioTerm(pi);
        return 1;
    }
    close(fd);

    while (1) {
        usleep(DEBOUNCE_DELAY * 1000);

        if (gpioRead(SENSOR_GPIO) == 0 && prev_state == 1) {
            flame_duration += DEBOUNCE_DELAY;
            duty_cycle = PWM_MIN_DUTY + (PWM_MAX_DUTY - PWM_MIN_DUTY) * exp((float)flame_duration / 1000);
            gpioHardwarePWM(FAN_GPIO, PWM_FREQ, duty_cycle);
            log_event("Flame detected");
        } else if (gpioRead(SENSOR_GPIO) == 1 && prev_state == 0) {
            log_event("Flame ended");
            gpioHardwarePWM(FAN_GPIO, 0, 0);
            flame_duration = 0;
        }

        prev_state = gpioRead(SENSOR_GPIO);
    }

    gpioTerm(pi);
    return 0;
}
