#define FLAME_SENSOR_LINE_GPIO_LINE 20
#define LOG_FILE "flame_log.txt"

static gpiod_line_event_cb_t flame_sensor_cb;
static gpiod_line_handle *flame_sensor_line;
static FILE *log_file;

void flame_sensor_cb(struct gpiod_chan *chan, unsigned int value,
                     unsigned int event, void *data) {
    time_t now = time(NULL);
    char timestamp[30];
    struct tm *tm_now = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_now);

    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        fprintf(log_file, "%s: Flame detected\n", timestamp);
    } else if (event == GPIOD_LINE_EVENT_EDGE_RISING) {
        fprintf(log_file, "%s: Flame cleared\n", timestamp);
    }
}

int init_gpio() {
    int ret;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    flame_sensor_line = gpiod_chip_get_line_bylabel(chip, FLAME_SENSOR_LINE_GPIO_REQUEST_LABEL);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_put(chip);
        return -1;
    }

    ret = gpiod_line_request_event_interrupt_edge_rising(flame_sensor_line, GPIOD_LINE_REQUEST_DIRECTION_IN);
    if (ret < 0) {
        perror("Failed to request event interrupt");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_put(chip);
        return -1;
    }

    flame_sensor_cb.data = NULL;
    flame_sensor_cb.callback = flame_sensor_cb;
    ret = gpiod_line_set_event_callback(flame_sensor_line, &flame_sensor_cb);
    if (ret < 0) {
        perror("Failed to set event callback");
        gpiod_line_release_event_interrupt(flame_sensor_line);
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_put(chip);
        return -1;
    }

    return 0;
}

