#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x44
#define REG_DATA 0x00

static int g_i2c_fd = -1;
static FILE *g_file = NULL;

void i2c_init() {
    g_i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, &g_err);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", g_err);
        exit(EXIT_FAILURE);
    }

    if (pigpio_i2c_write_read_data(g_i2c_fd, REG_COMMAND, 0x80, &g_err) < 0) {
        fprintf(stderr, "Failed to configure sensor: %s\n", g_err);
        exit(EXIT_FAILURE);
    }
}

void log_data(uint16_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S.000Z", timeinfo);

    fprintf(g_file, "%s,%05d\n", time_str, data);
}

void i2c_read_data(uint16_t *data) {
    int ret;

    do {
        ret = pigpio_i2c_read_16(g_i2c_fd, REG_DATA, data);
    } while (ret < 0 && errno == EAGAIN);

    if (ret < 0) {
        fprintf(stderr, "Failed to read data from sensor: %s\n", strerror(errno));
    }
}

void cleanup() {
    if (g_i2c_fd >= 0) {
        pigpio_i2c_close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    if (g_file != NULL) {
        fclose(g_file);
        g_file = NULL;
    }

    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio library: %s\n", g_err);
    }

    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    uint16_t data;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library: %s\n", g_err);
        return EXIT_FAILURE;
    }

    g_file = fopen("light_data.txt", "w");
    if (g_file == NULL) {
        fprintf(stderr, "Failed to open 'light_data.txt': %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_init();

    while (1) {
        i2c_read_data(&data);
        if (data >= 0) {
            uint8_t exponent = (data >> 12) & 0x0F;
            uint16_t mantissa = data & 0x0FFF;
            float lux = 0.01 * pow(2, exponent) * mantissa;
            log_data((uint32_t)lux);
        }
        usleep(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

void signal_handler(int signum) {
    cleanup();
}

int main(int argc, char *argv[]) {
    struct sigaction sa;

    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sa.sa_handler = signal_handler;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return main(argc, argv);
}

