```

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <signal.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define TIMEOUT_MS 1000

volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_data *line_data;
    int ret;

    // Initialize signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request the GPIO line
    request = gpiod_chip_request_lines(chip, 1, GPIO_ASIS, "flame_detect");
    if (!request) {
        perror("gpiod_chip_request_lines");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure the GPIO line as input with pull-up
    line_data = gpiod_line_request_get_data(request, 0);
    ret = gpiod_line_config_set_input(line_data, GPIOD_LINE_ACTIVE_HIGH, GPIOD_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_config_set_input");
        gpiod_line_release(request, 0);
        gpiod_chip_release_request(chip, request);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        // Read the GPIO line value
        uint32_t value;
        ret = gpiod_line_get_value(line_data, TIMEOUT_MS, &value);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            continue;
        }

        // Print the flame detection status
        if (value == 0) {
            printf("%04d-%02d-%02d %02d:%02d:%02d Flame Detected: YES\n",
                   (int)time(NULL) % 100,
                   (int)(time(NULL) / 100) % 32,
                   (int)(time(NULL) / 10000) % 12,
                   (int)(time(NULL) / 3600) % 24,
                   (int)(time(NULL) / 60) % 60,
                   (int)time(NULL) % 60);
        } else {
            printf("%04d-%02d-%02d %02d:%02d:%02d Flame Detected: NO\n",
                   (int)time(NULL) % 100,
                   (int)(time(NULL) / 100) % 32,
                   (int)(time(NULL) / 10000) % 12,
                   (int)(time(NULL) / 3600) % 24,
                   (int)(time(NULL) / 60) % 60,
                   (int)time(NULL) % 60);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Release the GPIO line request
    gpiod_line_release(request, 0);

