static void gpiod_chip_release(struct gpiod_chip *chip) {
    gpiod_chip_put(chip);
    gpiod_chip_free(chip);
}

static void handle_error(const char *msg, int errnum) {
    fprintf(stderr, "%s: %s\n", msg, strerror(errnum));
    exit(EXIT_FAILURE);
}

