#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_BASE 2
#define NUM_SENSORS 8

static void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    for (int gpio = GPIO_BASE; gpio < GPIO_BASE + NUM_SENSORS; ++gpio) {
        if (gpioSetMode(gpio, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode for pin %d\n", gpio);
            gpioTerminate();
            return 1;
        }

        if (gpioSetPullUpDown(gpio, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor for pin %d\n", gpio);
            gpioTerminate();
            return 1;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start = time(NULL);
    while (1) {
        int states[NUM_SENSORS] = {0};

        for (int gpio = GPIO_BASE; gpio < GPIO_BASE + NUM_SENSORS; ++gpio) {
            states[gpio - GPIO_BASE] = gpioRead(gpio);
        }

        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "[+%Y-%m-%d %H:%M:%S]", localtime(&now));
        printf("%s CH1=%d CH2=%d ... CH8=%d\n", timestamp, states[0], states[1], states[NUM_SENSORS - 1]);

        gpioDelay(100000);
    }

    gpioTerminate();
    return 0;
}

