#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 5

static volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void log_sensor_state(const char *label, int gpio) {
    if (gpio == GPIO_OK) {
        printf("%s: HIGH\n", label);
    } else {
        printf("%s: LOW\n", label);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != GPIO_OK ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != GPIO_OK) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        goto cleanup;
    }

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, sensor_reader, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor reader thread\n");
        goto cleanup;
    }

    struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 500 * 1e6 };
    while (running) {
        nanosleep(&sleep_time, NULL);

        int sensor_1_state = gpioRead(SENSOR_1_GPIO);
        int sensor_2_state = gpioRead(SENSOR_2_GPIO);

        log_sensor_state("Sensor 1", sensor_1_state);
        log_sensor_state("Sensor 2", sensor_2_state);
    }

cleanup:
    gpioTerm();
    pthread_join(thread_id, NULL);
    return 0;
}

void *sensor_reader(void *arg) {
    for (;;) {
        usleep(100000); // Yield CPU to main thread
    }
}

void log_sensor_state(const char *label, int gpio) {
    if (gpio == GPIO_OK) {
        printf("%s: HIGH\n", label);
    } else {
        printf("%s: LOW\n", label);
    }
}

