#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define NUM_SENSORS 8
#define POLL_INTERVAL_MS 50

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = {-1},
    .count = NUM_SENSORS,
};

static gpiod_line_data_v1 lines[NUM_SENSORS];

static void sigint_handler(int signum) {
    printf("\nShutting down...\n");
    gpiod_chip_put(gpiod_chip_get_by_name(GPIO_CHIP_NAME));
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    gpiod_chip *chip = gpiod_chip_get_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to get gpiochip");
        return 1;
    }

    if (gpiod_chip_request_lines(chip, &lines_data, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DISABLE_PULL) < 0) {
        perror("Failed to request lines");
        gpiod_chip_put(chip);
        return 1;
    }

    for (size_t i = 0; i < NUM_SENSORS; ++i) {
        lines[i].consumer = "TTP226_sensor";
        lines[i].flags = GPIOD_LINE_FLAG_INPUT;
        if (gpiod_line_request_get_by_index(chip, i, &lines[i]) < 0) {
            perror("Failed to get line");
            gpiod_chip_release_lines(&lines_data);
            gpiod_chip_put(chip);
            return 1;
        }
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%ld-%02d-%02dT%02d:%02d:%02d.%09ldZ",
             ts.tv_sec, ts.tv_mon + 1, ts.tv_mday, ts.tv_hour, ts.tv_min, ts.tv_sec, ts.tv_nsec);

    while (1) {
        for (size_t i = 0; i < NUM_SENSORS; ++i) {
            int value = gpiod_line_get_value_cansleep(&lines[i]);
            printf("%s,%d", timestamp, value);
        }
        printf("\n");

        clock_gettime(CLOCK_REALTIME, &ts);
        ts.tv_nsec += POLL_INTERVAL_MS * 1e6;
        while (ts.tv_nsec >= 1e9) {
            ts.tv_sec++;
            ts.tv_nsec -= 1e9;
        }
        nanosleep(&ts, NULL);
    }

    for (size_t i = 0; i < NUM_SENSORS; ++i) {
        gpiod_line_release(&lines[i]);
    }
    gpiod_chip_release_lines(&lines_data);
    gpiod_chip_put(chip);

    return 0;
}

