#define DEBOUNCE_MS 10

static void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    printf("Tilt Sensor Monitor\n");

    signal(SIGINT, sigint_handler);

    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUp(TILT_SENSOR_GPIO, 1);

    int last_state = gpioRead(TILT_SENSOR_GPIO);
    time_t last_change = time(NULL);

    while (1) {
        int current_state = gpioRead(TILT_SENSOR_GPIO);

        if (last_state != current_state) {
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("%s: Tilt state changed: %s\n", timestamp, (current_state == 0) ? "Tilted" : "Not Tilted");
            fflush(stdout);
            last_change = now;
        }

        last_state = current_state;
        usleep(100000); // 100 ms delay

        if (difftime(time(NULL), last_change) > DEBOUNCE_MS) {
            continue;
        }

        // If the state hasn't stabilized yet, exit the loop and wait for the next iteration
        break;
    }

    gpioTerminate();
    return 0;
}
```

This code initializes the pigpio library, sets up a SIGINT handler, configures the specified GPIO pin as an input with an internal pull-up resistor, and enters a loop to poll the tilt sensor every 100 ms. When the tilt state changes, it logs a timestamped message to the console. The program also includes a debouncing mechanism to ensure that the state change is stable before logging the message. The program exits cleanly when receiving a SIGINT signal and always calls `gpioTerminate()` on every exit path.

