#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR1 0x36
#define SENSOR_ADDR2 0x37
#define GPIO_ALARM 17
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR 0.036

static gpiod_line_request_linestate_t gpio_alarm_state;
static gpiod_line_data_flags_t gpio_alarm_flags = GPIOD_LINE_REPORT_ACTIVE_HIGH;

uint16_t crc16(uint8_t *data, size_t len) {
    uint16_t crc = 0xFFFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc >> 1) ^ (crc & 1 ? CRC_POLYNOMIAL : 0);
            crc &= 0xFFFF;
            crc ^= data[i] << 8;
        }
    }
    return crc;
}

int read_sensor(int fd, uint8_t addr) {
    uint8_t buf[10];
    if (write(fd, &addr, 1) != 1) {
        perror("Failed to write start-measurement command");
        return -1;
    }
    usleep(100000);

    if (read(fd, buf, 9) != 9) {
        perror("Failed to read sensor data");
        return -1;
    }

    uint16_t flow = (buf[0] << 8) | buf[1];
    uint16_t crc = (buf[2] << 8) | buf[3];

    if (crc != crc16(buf, 3)) {
        fprintf(stderr, "CRC error for sensor at 0x%02X\n", addr);
        return -1;
    }

    return flow;
}

void log_flow(double flow1, double flow2) {
    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: Average flow rate: %.2f ml/min\n", timestamp, (flow1 + flow2) / 2);
    fclose(log_file);
}

void alarm_callback(struct gpiod_line_event_info *info, void *user_data) {
    gpiod_line_set_value(info->line, info->value ? 0 : 1);
}

int main() {
    int i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR1) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    int gpio_fd = gpiod_open_name("gpiochip0", GPIO_ALARM);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    if (gpiod_line_request_dt_byname(gpio_fd, "gpio-alarm", flags, &gpio_alarm_state) < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(gpio_alarm_state, 0);
    gpiod_line_add_event_callback(gpio_alarm_state, alarm_callback, NULL);

    double flow_sum = 0.0;
    double flow_count = 0.0;
    double last_update = 0.0;

    while (1) {
        double flow1 = read_sensor(i2c_fd, SENSOR_ADDR1) * SCALE_FACTOR;
        double flow2 = read_sensor(i2c_fd, SENSOR_ADDR2) * SCALE_FACTOR;

        if (flow1 >= 0.0 && flow2 >= 0.0) {
            flow_sum += flow1 + flow2;
            flow_count++;
        }

        double current_time = time(NULL);
        if (current_time - last_update >= 1.0) {
            log_flow(flow_sum / flow_count, flow_sum / flow_count);
            flow_sum = 0.0;
            flow_count = 0.0;
            last_update = current_time;

            double average_flow = flow_sum / flow_count;
            if (average_flow < 0.5) {
                gpiod_line_set_value(gpio_alarm_state, 1);
            } else {
                gpiod_line_set_value(gpio_alarm_state, 0);
            }
        }

        usleep(100000);
    }

    gpiod_line_release(gpio_alarm_state);
    close(gpio_fd);
    close(i2c_fd);

    return 0;
}

