#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_SENSOR 4
#define BUFFER_SIZE 100

struct entry {
    time_t timestamp;
    int reading;
};

volatile sig_atomic_t running = 1;
struct entry buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void signal_handler(int sig) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    gpioSetMode(GPIO_SENSOR, PI_INPUT);
    gpioSetPullUp(GPIO_SENSOR, 1);
}

void record_reading(int reading) {
    struct entry *entry_ptr = &buffer[buffer_head];
    entry_ptr->timestamp = time(NULL);
    entry_ptr->reading = reading;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

void print_buffer() {
    for (int i = buffer_tail; i != buffer_head; i = (i + 1) % BUFFER_SIZE) {
        struct entry *entry_ptr = &buffer[i];
        char timestamp_str[20];
        ctime_r(&entry_ptr->timestamp, timestamp_str);
        timestamp_str[strlen(timestamp_str) - 1] = 0;
        printf("%s: Reading: %d\n", timestamp_str, entry_ptr->reading);
    }
}

int main() {
    init_gpio();

    signal(SIGINT, signal_handler);

    while (running) {
        int reading = gpioRead(GPIO_SENSOR);
        if (reading == 0) {
            record_reading(reading);
            printf("Obstacle detected!\n");
        }
        usleep(50000);
    }

    gpioTerm();
    print_buffer();

    return 0;
}

