#define ACC_REG_Z_LSB 0x2E
#define ACC_REG_Z_MSB 0x2F
#define SCALE_FACTOR 0.0009765625
#define SAMPLE_INTERVAL_MS 500
#define MAX_ATTEMPTS 10

