            }
            fprintf(stderr, "Failed to write to I2C device after %d attempts\n", MAX_ATTEMPTS);
            break;
        }

        ret = read(i2c_fd, data, 2);
        if (ret != 2) {
            perror("Failed to read from I2C device");
            if (++attempts < MAX_ATTEMPTS) {
                continue;
            }
            fprintf(stderr, "Failed to read from I2C device after %d attempts\n", MAX_ATTEMPTS);
            break;
        }

        int16_t acc_z = (data[0] | (data[1] << 8)) * SCALE_FACTOR;

        clock_gettime(CLOCK_REALTIME, &sleep_time);
        snprintf(timestamp, sizeof(timestamp), "%lld-W%02u-%02uT%02u:%02u:%02u.%06uZ",
                 sleep_time.tv_sec / 60 / 60 / 24 + 1970,
                 (sleep_time.tv_sec / 60 / 60) % 24 / 24 + 1,
                 (sleep_time.tv_sec / 60) % 60,
                 sleep_time.tv_sec % 60,
                 sleep_time.tv_nsec / 1000000,
                 (sleep_time.tv_nsec % 1000000000) / 1000000);

