        sleep_time.tv_sec = sleep_time.tv_nsec / 1000000000 + SAMPLE_INTERVAL_MS;
        sleep_time.tv_nsec = (SAMPLE_INTERVAL_MS % 1000000000) * 1000000;
        nanosleep(&sleep_time, NULL);
    }

