#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 23
#define SENSOR2_GPIO 24
#define LED_GPIO 25
#define DELAY_MS 100

static volatile int running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR2_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (gpioRead(SENSOR1_GPIO) == 0 || gpioRead(SENSOR2_GPIO) == 0) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }
        usleep(DELAY_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

