#define STALL_DURATION 2000 // stall duration in milliseconds
#define LOG_FILE "stall_log.txt"

static int sensor_1_state = 0;
static int sensor_2_state = 0;
static time_t last_stall_time = 0;

void log_stall(time_t current_time) {
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[20];
    ctime_r(&current_time, timestamp);
    timestamp[strlen(timestamp) - 1] = 0; // remove newline character

    if (write(fd, timestamp, strlen(timestamp)) < 0) {
        perror("Failed to write to log file");
    }

    close(fd);
}

void check_stall() {
    time_t current_time = time(NULL);

    if (current_time - last_stall_time >= STALL_DURATION && sensor_1_state == 0 && sensor_2_state == 0) {
        last_stall_time = current_time;
        log_stall(current_time);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0 || gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        goto cleanup;
    }

    while (1) {
        sensor_1_state = gpioRead(SENSOR_1_GPIO);
        sensor_2_state = gpioRead(SENSOR_2_GPIO);

        check_stall();

        usleep(100000); // sleep for 100ms
    }

cleanup:
    gpioTerminate();
    return 0;
}

