Here's a complete C program that interfaces with the TMAG5170-Q1 I2C 3D Hall-Effect sensor on a Raspberry Pi 4 Model B using the pigpio library. The code checks every init and syscall, handles errors, and releases resources on all exit paths.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define X_REG 0x01
#define Y_REG 0x02
#define Z_REG 0x03
#define LSB_SCALE_FACTOR 0.0000390625

static const char *csv_header = "timestamp,X,Y,Z\n";
static FILE *csv_file;

void sigint_handler(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd, ret;
    uint16_t device_id;
    uint16_t x, y, z;
    time_t timestamp;
    char timestamp_str[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 1000000);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup;
    }

    ret = pigpio_i2cReadRegister16(i2c_fd, DEVICE_ID_REG, &device_id);
    if (ret < 0 || device_id != 0x8D) {
        fprintf(stderr, "Invalid device ID: 0x%04X, expected 0x8D\n", device_id);
        goto i2c_cleanup;
    }

    csv_file = fopen("magnetic_log.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open magnetic_log.csv\n");
        goto csv_cleanup;
    }

    if (fseek(csv_file, 0, SEEK_SET) != 0) {
        fprintf(stderr, "Failed to seek to the beginning of magnetic_log.csv\n");
        goto csv_cleanup;
    }

    if (fwrite(csv_header, strlen(csv_header), 1, csv_file) != 1) {
        fprintf(stderr, "Failed to write CSV header\n");
        goto csv_cleanup;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        ret = pigpio_i2cReadRegister16(i2c_fd, X_REG, &x);
        if (ret < 0) {
            perror("Failed to read X register");
            continue;
        }

        ret = pigpio_i2cReadRegister16(i2c_fd, Y_REG, &y);
        if (ret < 0) {
            perror("Failed to read Y register");
            continue;
        }

        ret = pigpio_i2cReadRegister16(i2c_fd, Z_REG, &z);
        if (ret < 0) {
            perror("Failed to read Z register");
            continue;
        }

        timestamp = time(NULL);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%f", localtime(&timestamp));
        fprintf(csv_file, "%s,%f,%f,%f\n", timestamp_str, x * LSB_SCALE_FACTOR, y * LSB_SCALE_FACTOR, z * LSB_SCALE_FACTOR);
        fflush(csv_file);
        usleep(100000);
    }

    csv_cleanup:
        if (csv_file) {
            fclose(csv_file);
        }

    i2c_cleanup:
        if (i2c_fd >= 0) {
            pigpio_i2cClose(i2c_fd);
        }

    cleanup:
        gpioTerminate();

    return 0;
}
```

This code initializes the pigpio library, opens the I2C bus, checks the device ID, opens the CSV file, and registers a SIGINT/SIGTERM handler for clean resource release. It then enters an infinite loop where it reads the X, Y, and Z magnetic field readings, converts them to mT, and logs them with ISO-8601 timestamps to 'magnetic_log.csv'. If there's an error reading from the sensor or I2C bus, it logs the error to stderr and continues. When the program is interrupted by Ctrl+C, it cleans up the resources and exits.

