#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SENSOR_GPIO 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1000
#define RPM_SCALE_FACTOR 60

static volatile int pulse_counter = 0;
static int log_file;
static bool log_file_opened = false;

void signal_handler(int signum) {
    (void)signum;
    gpioTerminate();
    if (log_file >= 0) {
        close(log_file);
        log_file = -1;
    }
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0 ||
        gpioSetPullUp(SENSOR_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to configure GPIO %d\n", SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 ||
        sigaction(SIGTERM, &sa, NULL)) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR)) < 0) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }
    log_file_opened = true;

    unsigned long long last_sample_time = 0;
    while (1) {
        unsigned long long current_time = time(NULL);
        if (current_time - last_sample_time >= SAMPLE_INTERVAL) {
            last_sample_time = current_time;

            int state = gpioRead(SENSOR_GPIO);
            if (state == 0) {
                atomic_add(&pulse_counter, 1);
            }

            unsigned long long rpm = (unsigned long long)atomic_read(&pulse_counter) * RPM_SCALE_FACTOR;
            char log_line[64];
            snprintf(log_line, sizeof(log_line), "%04d-%02d-%02d %02d:%02d:%02d <%llu>\n",
                     (int)current_time / 10000, (int)(current_time / 100) % 100,
                     (int)current_time % 100, (int)(current_time % 60),
                     (int)((current_time % 60) * 60 / SAMPLE_INTERVAL),
                     (int)((current_time % 60) % 60 * 100 / SAMPLE_INTERVAL), rpm);

            if (fwrite(log_line, 1, strlen(log_line), log_file) != strlen(log_line)) {
                perror("Failed to write to log file");
                log_file_opened = false;
            }
            fflush(log_file);

            printf("%llu RPM\n", rpm);
            atomic_set(&pulse_counter, 0);
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    gpioTerminate();
    return 0;
}

