#include <errno.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE "rotation_log.txt"
#define MUTEX_KEY 123456

volatile int state_a = 0;
volatile int state_b = 0;
pthread_mutex_t mutex;

void signal_handler(int sig) {
    (void)sig;
    pthread_mutex_lock(&mutex);
    printf("Shutting down...\n");
    pthread_mutex_unlock(&mutex);
    gpioTerm();
    exit(0);
}

void log_rotation(int direction) {
    pthread_mutex_lock(&mutex);
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[25];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S.", timeinfo);
    snprintf(time_str + 16, sizeof(time_str) - 16, "%03d", (int)(1000 * (double)clock() / CLOCKS_PER_SEC));
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        pthread_mutex_unlock(&mutex);
        return;
    }
    fprintf(log_file, "%s Rotation: %s\n", time_str, direction > 0 ? "CW" : "CCW");
    fflush(log_file);
    fclose(log_file);
    pthread_mutex_unlock(&mutex);
}

void sensor_a_alert_cb(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    state_a = level;
    pthread_mutex_unlock(&mutex);
}

void sensor_b_alert_cb(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    state_b = level;
    pthread_mutex_unlock(&mutex);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) < 0 ||
        gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) < 0 ||
        gpioSetAlertFunc(SENSOR_A_GPIO, PI_EDGE_BOTH, sensor_a_alert_cb) < 0 ||
        gpioSetMode(SENSOR_B_GPIO, PI_INPUT) < 0 ||
        gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) < 0 ||
        gpioSetAlertFunc(SENSOR_B_GPIO, PI_EDGE_BOTH, sensor_b_alert_cb) < 0) {
        perror("gpioSetMode/gpioSetPullUpDown/gpioSetAlertFunc");
        gpioTerm();
        return 1;
    }

    pthread_mutex_init(&mutex, NULL);

    int prev_state_a = 0;
    int prev_state_b = 0;
    int direction = 0;

    while (1) {
        pthread_mutex_lock(&mutex);
        if (state_a != prev_state_a || state_b != prev_state_b) {
            int new_state_a = state_a;
            int new_state_b = state_b;
            pthread_mutex_unlock(&mutex);

            if (new_state_a != prev_state_a) {
                if (new_state_a == 1 && prev_state_a == 0) {
                    if (new_state_b == prev_state_b) {
                        direction = -direction;
                    }
                }
                prev_state_a = new_state_a;
            }

            if (new_state_b != prev_state_b) {
                if (new_state_b == 1 && prev_state_b == 0) {
                    if (new_state_a == prev_state_a) {
                        direction = -direction;
                    }
                }
                prev_state_b = new_state_b;
            }

            if (direction != 0) {
                log_rotation(direction);
                direction = 0;
            }
        } else {
            pthread_mutex_unlock(&mutex);
            usleep(100000); // Sleep for 100ms to reduce CPU usage
        }
    }

    pthread_mutex_destroy(&mutex);
    gpioTerm();
    return 0;
}

