#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <libgpiod.h>

#define TOUCH_GPIO_LINE "gpiochip0/gpio17"
#define LED_GPIO_LINE "gpiochip0/gpio18"
#define DEBOUNCE_MS 50
#define MAX_DEBOUNCE_COUNT 5

static gpiod_line_request_lines_data_v1 _touch_request_data = {
    .lines = (const gpiod_line_info_v1[]) {
        { .number = 17, .flags = GPIOD_LINE_REQUEST_INPUT },
    },
    .n_lines = 1,
};

static gpiod_line_request_lines_data_v1 _led_request_data = {
    .lines = (const gpiod_line_info_v1[]) {
        { .number = 18, .flags = GPIOD_LINE_REQUEST_OUTPUT },
    },
    .n_lines = 1,
};

int main(void) {
    int ret;
    gpiod_line *touch_line = NULL;
    gpiod_line *led_line = NULL;
    unsigned int touch_state = 0;
    unsigned int debounce_count = 0;
    struct timespec debounce_timeout;

    // Initialize the LED line as output and drive it LOW at startup
    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_request_dt_byname(gpiod_chip_get_data(gpiod_chip_open_byname("gpiochip0")), LED_GPIO_LINE, &_led_request_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %s: %s\n", LED_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_line_get_byname(gpiod_chip_get_data(gpiod_chip_open_byname("gpiochip0")), LED_GPIO_LINE);
    gpiod_line_set_value(led_line, 0);

    // Request the touch line
    ret = gpiod_line_request_dt_byname(gpiod_chip_get_data(gpiod_chip_open_byname("gpiochip0")), TOUCH_GPIO_LINE, &_touch_request_data);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %s: %s\n", TOUCH_GPIO_LINE, strerror(errno));
        goto cleanup;
    }

    touch_line = gpiod_line_get_byname(gpiod_chip_get_data(gpiod_chip_open_byname("gpiochip0")), TOUCH_GPIO_LINE);

    // Set up debouncing
    debounce_timeout.tv_sec = DEBOUNCE_MS / 1000;
    debounce_timeout.tv_nsec = (DEBOUNCE_MS % 1000) * 1000000000;

    while (1) {
        ret = gpiod_line_get_value(touch_line);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line %s: %s\n", TOUCH_GPIO_LINE, strerror(errno));
            goto cleanup;
        }

        if (touch_state == 0 && ret > 0) {
            debounce_count = 0;
            gpiod_line_set_value(led_line, 1);
            printf("Touch detected\n");
        }

        touch_state = ret;
        nanosleep(&debounce_timeout, NULL);

        if (touch_state == 0 && debounce_count >= MAX_DEBOUNCE_COUNT) {
            gpiod_line_set_value(led_line, 0);
            printf("Touch released\n");
        } else {
            debounce_count++;
        }
    }

cleanup:
    if (touch_line) gpiod_line_release(touch_line);
    if (led_line) gpiod_line_release(led_line);
    if (gpiod_chip_get_data(gpiod_chip_open_byname("gpiochip0"))) gpiod_chip_close(gpiod_chip_get_data(gpiod_chip_open_byname("gpiochip0")));

    return 0;
}

