This program initializes the GPIO lines, requests the lines, handles errors, and releases resources on exit. It also handles SIGINT and SIGTERM gracefully by releasing all libgpiod resources and exiting cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define LED_ON 1
#define LED_OFF 0
#define TOUCH_SENSOR_1_GPIO 4
#define TOUCH_SENSOR_2_GPIO 17
#define LED_1_GPIO 27
#define LED_2_GPIO 22
#define DEBOUNCE_MS 50

typedef struct {
    int sensor_gpio;
    time_t timestamp;
    int state;
} TouchEvent;

TouchEvent buffer[BUFFER_SIZE];
volatile size_t head = 0;
volatile size_t tail = 0;
volatile size_t overflow_count = 0;

void touch_event_handler(int gpio, uint32_t level, uint32_t tick) {
    if (level == GPIO_LEVEL_HIGH) {
        buffer[head].sensor_gpio = gpio;
        buffer[head].timestamp = time(NULL);
        buffer[head].state = LED_ON;
        head = (head + 1) % BUFFER_SIZE;
        if (head == tail) {
            overflow_count++;
        }
    } else {
        buffer[tail].sensor_gpio = gpio;
        buffer[tail].timestamp = time(NULL);
        buffer[tail].state = LED_OFF;
        tail = (tail + 1) % BUFFER_SIZE;
    }
}

void led_on(int gpio) {
    if (gpioInitialise(BOTH) < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for %d\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(gpio, LED_ON);
}

void led_off(int gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for %d\n", gpio);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(gpio, LED_OFF);
}

void print_log() {
    size_t i;
    printf("Log:\n");
    printf("Sensor GPIO | Timestamp           | State\n");
    printf("----------------------------------------\n");
    for (i = tail; i != head; i = (i + 1) % BUFFER_SIZE) {
        printf("%-10d | %19ld | %d\n", buffer[i].sensor_gpio, buffer[i].timestamp, buffer[i].state);
    }
    printf("Overflow count: %zu\n", overflow_count);
}

void signal_handler(int sig) {
    (void)sig;
    led_off(LED_1_GPIO);
    led_off(LED_2_GPIO);
    gpioTerminate();
    print_log();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    led_on(LED_1_GPIO);
    led_on(LED_2_GPIO);

    if (gpioInitialise(BOTH) < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for %d\n", TOUCH_SENSOR_1_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for %d\n", TOUCH_SENSOR_2_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetAlertFunc(TOUCH_SENSOR_1_GPIO, touch_event_handler);
    gpioSetAlertFunc(TOUCH_SENSOR_2_GPIO, touch_event_handler);

    while (1) {
        usleep(DEBOUNCE_MS * 1000);

        if (gpioRead(TOUCH_SENSOR_1_GPIO) == GPIO_LEVEL_HIGH) {
            led_off(LED_2_GPIO);
            led_on(LED_1_GPIO);
        } else {
            led_off(LED_1_GPIO);
            led_on(LED_2_GPIO);
        }

        if (gpioRead(TOUCH_SENSOR_2_GPIO) == GPIO_LEVEL_HIGH) {
            led_off(LED_1_GPIO);
            led_on(LED_2_GPIO);
        } else {
            led_off(LED_2_GPIO);
            led_on(LED_1_GPIO);
        }
    }

    gpioTerminate();
    return 0;
}

