    }

    gpioWrite(gpio, LED_OFF);
}

void print_log() {
    size_t i;
    printf("Log:\n");
    printf("Sensor GPIO | Timestamp           | State\n");
    printf("----------------------------------------\n");
    for (i = tail; i != head; i = (i + 1) % BUFFER_SIZE) {
        printf("%-10d | %19ld | %d\n", buffer[i].sensor_gpio, buffer[i].timestamp, buffer[i].state);
    }
    printf("Overflow count: %zu\n", overflow_count);
}

void signal_handler(int sig) {
    (void)sig;
    led_off(LED_1_GPIO);
    led_off(LED_2_GPIO);
    gpioTerminate();
    print_log();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    led_on(LED_1_GPIO);
    led_on(LED_2_GPIO);

    if (gpioInitialise(BOTH) < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_SENSOR_1_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for %d\n", TOUCH_SENSOR_1_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TOUCH_SENSOR_2_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for %d\n", TOUCH_SENSOR_2_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetAlertFunc(TOUCH_SENSOR_1_GPIO, touch_event_handler);
    gpioSetAlertFunc(TOUCH_SENSOR_2_GPIO, touch_event_handler);

    while (1) {
        usleep(DEBOUNCE_MS * 1000);

        if (gpioRead(TOUCH_SENSOR_1_GPIO) == GPIO_LEVEL_HIGH) {
            led_off(LED_2_GPIO);
            led_on(LED_1_GPIO);
        } else {
            led_off(LED_1_GPIO);
            led_on(LED_2_GPIO);
        }

        if (gpioRead(TOUCH_SENSOR_2_GPIO) == GPIO_LEVEL_HIGH) {
            led_off(LED_1_GPIO);
            led_on(LED_2_GPIO);
        } else {
            led_off(LED_2_GPIO);
            led_on(LED_1_GPIO);
        }
    }

    gpioTerminate();
    return 0;
}
