#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_MS 5
#define RPM_CONVERSION_FACTOR 60000.0

static void log_timestamp_and_state(const char *filename, int state1, int state2) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *file = fopen(filename, "a");

    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,%d,%d\n", timestamp, state1, state2);
    fclose(file);
}

static void debounce(int gpio) {
    int previous_state = gpioRead(gpio);
    usleep(DEBOUNCE_MS * 1000);

    int current_state = gpioRead(gpio);

    if (previous_state != current_state) {
        log_timestamp_and_state("shaft_log.txt", previous_state, current_state);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    int last_elapsed_ms = 0;
    double elapsed_ms = 0.0;
    double rpm = 0.0;
    int sensor1_state = gpioRead(SENSOR_1_GPIO);
    int sensor2_state = gpioRead(SENSOR_2_GPIO);

    while (1) {
        debounce(SENSOR_1_GPIO);
        debounce(SENSOR_2_GPIO);

        int current_sensor1_state = gpioRead(SENSOR_1_GPIO);
        int current_sensor2_state = gpioRead(SENSOR_2_GPIO);

        if (current_sensor1_state != sensor1_state ||
            current_sensor2_state != sensor2_state) {
            elapsed_ms = (double)(clock() - last_elapsed_ms) / CLOCKS_PER_SEC * 1000;
            rpm = (2.0 * RPM_CONVERSION_FACTOR) / elapsed_ms;
            printf("RPM: %.2f\n", rpm);

            sensor1_state = current_sensor1_state;
            sensor2_state = current_sensor2_state;
            last_elapsed_ms = clock();
        }

        usleep(10000);
    }

    gpioTerminate();
    return 0;
}

void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    return main();
}

