#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <pigpio.h>

#define SI1182_I2C_BUS 1
#define SI1182_I2C_ADDR 0x28

#define SI1182_PART_ID_REG 0x00
#define SI1182_CONFIG_REG 0x30
#define SI1182_HR_REG 0x02
#define SI1182_SP02_REG 0x04

#define BUFFER_SIZE 10

void log_biometric_data(const char *timestamp, uint16_t heart_rate, uint16_t sp02) {
    FILE *log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Heart Rate: %u BPM, SpO2: %u%%\n", timestamp, heart_rate, sp02);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    int i2c_fd;
    uint8_t part_id;
    uint16_t heart_rate, sp02;
    time_t rawtime;
    struct tm *time_info;
    char timestamp[30];

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(SI1182_I2C_BUS, SI1182_I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup_pigpio;
    }

    if (i2cWriteReadRegister16(i2c_fd, SI1182_PART_ID_REG, &part_id, 1, NULL, 0) < 0) {
        perror("Failed to read PART_ID register");
        goto cleanup_i2c;
    }

    if (part_id != 0x1182) {
        fprintf(stderr, "Invalid Si1182 sensor detected\n");
        goto cleanup_i2c;
    }

    if (i2cWriteReadRegister16(i2c_fd, SI1182_CONFIG_REG, (uint16_t)0x0001, 1, NULL, 0) < 0) {
        perror("Failed to configure sensor for continuous measurement");
        goto cleanup_i2c;
    }

    while (1) {
        if (i2cWriteReadRegister16(i2c_fd, SI1182_HR_REG, NULL, 0, &heart_rate, BUFFER_SIZE) < 0) {
            perror("Failed to read heart rate data");
            continue;
        }

        if (i2cWriteReadRegister16(i2c_fd, SI1182_SP02_REG, NULL, 0, &sp02, BUFFER_SIZE) < 0) {
            perror("Failed to read SpO2 data");
            continue;
        }

        rawtime = time(NULL);
        time_info = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
        log_biometric_data(timestamp, heart_rate, sp02);

        sleep(1);
    }

cleanup_i2c:
    pigpio_i2c_close(i2c_fd);

cleanup_pigpio:
    gpioTerminate();

    return 0;
}

int i2cWriteReadRegister16(int i2c_fd, uint8_t reg, uint16_t value, uint16_t len_write, uint16_t *buf_write, uint16_t len_read, uint16_t *buf_read) {
    int ret;

    ret = pigpio_i2cWriteRead(i2c_fd, reg, &value, len_write, buf_write, len_read, buf_read);
    if (ret < 0) {
        perror("I2C read/write error");
        return ret;
    }

    if (len_read > 0 && buf_read) {
        if (buf_read[0] != (uint16_t)len_read) {
            fprintf(stderr, "I2C read error: expected %u bytes, received %u bytes\n", len_read, buf_read[0]);
            return -1;
        }
    }

    return ret;
}

