#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27
#define LOG_FILE "bridge_integrity.log"
#define THRESHOLD_MS 2000
#define POLL_INTERVAL_MS 100

static time_t last_log_time = 0;
static int sensor_1_state = 0;
static int sensor_2_state = 0;
static int alarm_active = 0;

void log_event(const char *event) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char log_line[100];
    snprintf(log_line, sizeof(log_line), "%4d-%02d-%02dT%02d:%02d:%02d %s\n",
             time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
             time_info->tm_hour, time_info->tm_min, time_info->tm_sec, event);

    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_fd < 0) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (write(log_fd, log_line, strlen(log_line)) < 0) {
        perror("Failed to write to log file");
        exit(EXIT_FAILURE);
    }

    close(log_fd);
}

int main(void) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO modes");
        exit(EXIT_FAILURE);
    }

    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN);

    int prev_sensor_1_state = gpioRead(SENSOR_1_GPIO);
    int prev_sensor_2_state = gpioRead(SENSOR_2_GPIO);

    while (1) {
        gpioDelay(POLL_INTERVAL_MS);

        int current_sensor_1_state = gpioRead(SENSOR_1_GPIO);
        int current_sensor_2_state = gpioRead(SENSOR_2_GPIO);

        if (current_sensor_1_state != prev_sensor_1_state) {
            if (current_sensor_1_state) {
