#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define SDA_PIN 2
#define SCL_PIN 3
#define LED_PIN 17
#define SENSOR_ADDR 0x1D
#define REG_CTRL1 0x1F
#define REG_ACCEL_X 0x28
#define REG_ACCEL_Y 0x2A
#define REG_ACCEL_Z 0x2C
#define THRESHOLD 500
#define LOG_FILE "seismic_events.log"

static pthread_t log_thread;
static FILE *log_file;

static int i2c_read(uint8_t addr, uint8_t *buf, size_t len) {
    int retries = 3;
    int r;
    while (retries--) {
        r = i2cWriteRead(gpiod_to_fd(SDA_PIN, SCL_PIN, 0), addr, buf, len);
        if (r == len)
            return r;
        usleep(100000);
    }
    return -1;
}

static void log_event(time_t timestamp, uint16_t magnitude) {
    char timestamp_str[32];
    struct tm *tm = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S.%f", tm);
    fprintf(log_file, "%s,%u\n", timestamp_str, magnitude);
    fflush(log_file);
}

static void *log_thread_func(void *arg) {
    while (1) {
        sleep(1);
    }
}

int main() {
    int i2c_fd, ret;
    uint8_t buf[6];
    uint16_t x, y, z, magnitude;
    time_t timestamp;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (pthread_create(&log_thread, NULL, log_thread_func, NULL) != 0) {
        fprintf(stderr, "Failed to create log thread\n");
        goto cleanup;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        goto cleanup;
    }

    i2c_fd = gpiod_to_fd(SDA_PIN, SCL_PIN, 0);
    if (i2c_read(SENSOR_ADDR, &buf, 1) != 1) {
        fprintf(stderr, "Failed to communicate with sensor\n");
        goto cleanup;
    }

    if (buf[0] != 0x71) {
        fprintf(stderr, "Sensor not present or incorrect address\n");
        goto cleanup;
    }

    ret = i2c_read(SENSOR_ADDR, &buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to read CTRL1 register\n");
        goto cleanup;
    }
    buf[1] &= ~(1 << 7);
    ret = i2c_write(SENSOR_ADDR, &buf, 2);
    if (ret != 2) {
        fprintf(stderr, "Failed to write to CTRL1 register\n");
        goto cleanup;
    }

    while (1) {
        ret = i2c_read(SENSOR_ADDR, buf, 6);
        if (ret != 6) {
            fprintf(stderr, "Failed to read acceleration registers\n");
            continue;
        }

        x = (buf[REG_ACCEL_X] << 8) | buf[REG_ACCEL_X + 1];
        y = (buf[REG_ACCEL_Y] << 8) | buf[REG_ACCEL_Y + 1];
        z = (buf[REG_ACCEL_Z] << 8) | buf[REG_ACCEL_Z + 1];
        magnitude = (uint16_t)sqrt((double)(x * x + y * y + z * z));

        if (magnitude > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            timestamp = time(NULL);
            log_event(timestamp, magnitude);
            usleep(1000000);
            gpioWrite(LED_PIN, 0);
        }

        usleep(100000);
    }

cleanup:
    if (log_file)
        fclose(log_file);
    if (gpioTerminate() < 0)
        fprintf(stderr, "Failed to terminate pigpio library\n");
    pthread_join(log_thread, NULL);
    return 0;
}

