#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE_SENSOR_0 4
#define GPIO_LINE_SENSOR_1 17
#define GPIO_LINE_SENSOR_2 27
#define GPIO_LINE_SENSOR_3 22
#define GPIO_LED 18

gpiod_line_request_lines_data_v1 lines_data = { .lines = {
    [GPIO_LINE_SENSOR_0] = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING,
    [GPIO_LINE_SENSOR_1] = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING,
    [GPIO_LINE_SENSOR_2] = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING,
    [GPIO_LINE_SENSOR_3] = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_FALLING,
}, .consumer = "obstacle_detection" };

int main() {
    int fd, ret;
    gpiod_line_handle_v1 *lines[4];
    gpiod_line_value_v1 values[4];
    struct sigaction sa;

    fd = gpiod_chip_open(GPIO_CHIP);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_request_lines_data_v1(fd, &lines_data, &lines);
    if (ret < 0) {
        perror("Failed to request lines");
        close(fd);
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        gpiod_chip_release_lines_data_v1(fd, &lines_data);
        close(fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        ret = gpiod_line_get_value_v1(lines[GPIO_LINE_SENSOR_0], &values[GPIO_LINE_SENSOR_0]);
        if (ret < 0) {
            perror("Failed to get value of sensor 0");
            continue;
        }

        ret = gpiod_line_get_value_v1(lines[GPIO_LINE_SENSOR_1], &values[GPIO_LINE_SENSOR_1]);
        if (ret < 0) {
            perror("Failed to get value of sensor 1");
            continue;
        }

        ret = gpiod_line_get_value_v1(lines[GPIO_LINE_SENSOR_2], &values[GPIO_LINE_SENSOR_2]);
        if (ret < 0) {
            perror("Failed to get value of sensor 2");
            continue;
        }

        ret = gpiod_line_get_value_v1(lines[GPIO_LINE_SENSOR_3], &values[GPIO_LINE_SENSOR_3]);
        if (ret < 0) {
            perror("Failed to get value of sensor 3");
            continue;
        }

        if (values[GPIO_LINE_SENSOR_0] == 0 || values[GPIO_LINE_SENSOR_1] == 0 ||
            values[GPIO_LINE_SENSOR_2] == 0 || values[GPIO_LINE_SENSOR_3] == 0) {
            gpiod_line_set_value_v1(lines[GPIO_LED], 1);
        } else {
            gpiod_line_set_value_v1(lines[GPIO_LED], 0);
        }

        usleep(50000); // 50 ms delay
    }

    gpiod_line_release_v1(lines[GPIO_LINE_SENSOR_0]);
    gpiod_line_release_v1(lines[GPIO_LINE_SENSOR_1]);
    gpiod_line_release_v1(lines[GPIO_LINE_SENSOR_2]);
    gpiod_line_release_v1(lines[GPIO_LINE_SENSOR_3]);
    gpiod_chip_release_lines_data_v1(fd, &lines_data);
    close(fd);

    return 0;
}

void sigint_handler(int signum) {
    printf("Received SIGINT or SIGTERM, exiting...\n");
    exit(EXIT_SUCCESS);
}

