#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>

#define NUM_SENSORS 5
#define GPIO_BASE 2
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"
#define LOG_FACILITY LOG_USER
#define PROGRAM_IDENT "flame_monitor"

volatile sig_atomic_t exit_flag = 0;
gpiod_chip *chip;
gpiod_line *lines[NUM_SENSORS];

void sigint_handler(int signum) {
    exit_flag = 1;
}

void sigterm_handler(int signum) {
    exit_flag = 1;
}

void log_syslog(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

void log_error(const char *function, int line, const char *message) {
    char buf[LOG_LINE_MAX];
    snprintf(buf, sizeof(buf), "%s:%d: %s: %s", __FILE__, line, function, message);
    log_syslog(LOG_ERR, "%s", buf);
}

int open_chip(const char *label) {
    int ret;
    chip = gpiod_chip_open_by_label(label);
    if (!chip) {
        log_error("gpiod_chip_open_by_label", __LINE__, strerror(errno));
        return -1;
    }
    return 0;
}

void close_chip() {
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int request_line(gpiod_line *line, unsigned int flags, unsigned int consumer) {
    int ret;
    ret = gpiod_line_request_with_consumer(line, flags, consumer);
    if (ret < 0) {
