#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define NUM_SENSORS 8

static int gpio_fd;
static gpiod_line_array_iter_t iter;

void gpio_cleanup(void) {
    gpiod_line_iter_release(&iter);
    close(gpio_fd);
}

int gpio_init(void) {
    gpio_fd = open("/dev/gpiod", O_RDWR | O_NONBLOCK);
    if (gpio_fd < 0) {
        perror("Failed to open gpiod device");
        return 1;
    }

    if (gpiod_chip_open_sync(gpio_fd, GPIO_CHIP_NAME) < 0) {
        perror("Failed to open gpio chip");
        goto cleanup;
    }

    if (gpiod_line_request_array_iter(&iter, gpio_fd, GPIO_CHIP_NAME, NUM_SENSORS) < 0) {
        perror("Failed to request line array iter");
        goto chip_close;
    }

    return 0;

chip_close:
    gpiod_chip_close(gpio_fd);
cleanup:
    gpio_cleanup();
    return 1;
}

int main(void) {
    int ret, i, prev_states[NUM_SENSORS] = {-1};
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if (gpio_init()) {
        return 1;
    }

    while (1) {
        gpiod_line_value_array_t states;
        ret = gpiod_line_iter_get_values_sync(&iter, &states, NUM_SENSORS);
        if (ret < 0) {
            perror("Failed to get line values");
            goto cleanup;
        }

        for (i = 0; i < NUM_SENSORS; ++i) {
            int state = states.lines[i];
            if (state != prev_states[i]) {
                clock_gettime(CLOCK_REALTIME, &ts);
                printf("%s Sensor %d, BCM Pin %d: State changed to %d\n",
                       ctime(&ts.tv_sec), i, GPIO_GPIO_TO_BCM(i + 1), state);
                prev_states[i] = state;
            }
        }

        usleep(50 * 1000);
    }

cleanup:
    gpio_cleanup();
    return 0;
}

int GPIO_GPIO_TO_BCM(int gpio) {
    switch (gpio) {
        case 1: return 5;
        case 2: return 6;
        case 3: return 13;
        case 4: return 19;
        case 5: return 26;
        case 6: return 12;
        case 7: return 16;
        case 8: return 20;
        default: return -1;
    }
}

