This program initializes the GPIO chip, requests the line array iter, and polls the 8 touch sensors every 50 milliseconds. It logs state changes to the console with ISO-8601 timestamps and the sensor index plus BCM pin number. The program handles errors and releases resources on all exit paths, including graceful shutdown on SIGINT (Ctrl+C).

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x10
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LUX_THRESHOLD_1 100
#define LUX_THRESHOLD_2 500
#define LUX_THRESHOLD_3 1000
#define LOG_FILE "grow_log.txt"

typedef struct {
    time_t timestamp;
    uint16_t lux;
    uint8_t brightness;
    int error_code;
} LogEntry;

int init_pigpio(void);
int i2c_open(void);
int i2c_write_reg(uint8_t reg, uint16_t value);
uint16_t i2c_read_reg(uint8_t reg);
int pwm_setup(void);
void pwm_set_duty(uint32_t duty);
void log_entry(const LogEntry *entry);
void signal_handler(int signum);

int main(void) {
    if (init_pigpio() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2c_open() < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        goto cleanup_pigpio;
    }

    if (i2c_write_reg(0x00, 0x0080) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        goto cleanup_i2c;
    }

    if (pwm_setup() < 0) {
        fprintf(stderr, "Failed to setup PWM\n");
        goto cleanup_i2c;
    }

    while (1) {
        uint16_t lux = i2c_read_reg(0x04);
        float adjusted_lux = lux * 0.0576f;
        uint8_t brightness = 100;

        if (adjusted_lux < LUX_THRESHOLD_1) {
            brightness = 100;
        } else if (adjusted_lux < LUX_THRESHOLD_2) {
            brightness = 75;
        } else if (adjusted_lux < LUX_THRESHOLD_3) {
            brightness = 50;
        } else {
            brightness = 25;
        }

        pwm_set_duty((uint32_t)(brightness * PWM_RANGE / 100.0));

        LogEntry entry = {
            .timestamp = time(NULL),
            .lux = lux,
            .brightness = brightness,
            .error_code = 0
        };

        log_entry(&entry);
        sleep(1);
    }

cleanup_pwm:
    gpioTerm(LED_GPIO);
cleanup_i2c:
    i2cClose(i2c_fd);
cleanup_pigpio:
    pigpioTerm();

    return 0;
}

int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        return -1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

int i2c_open(void) {
    int i2c_fd = i2cOpen(I2C_BUS, 1);

    if (i2c_fd < 0) {
        perror("i2cOpen");
        return -1;
    }

    return i2c_fd;
}

int i2c_write_reg(uint8_t reg, uint16_t value) {
    uint8_t data[2];
    data[0] = reg;
    data[1] = value & 0xFF;
    data[1] |= (value >> 8) << 4;

    if (i2cWriteRead(i2c_fd, SENSOR_ADDR, data, 2, NULL, 0) < 2) {
        perror("i2cWriteRead");
        return -1;
    }

    return 0;
}

uint16_t i2c_read_reg(uint8_t reg) {
    uint8_t data[2];
    data[0] = reg;

    if (i2cWriteRead(i2c_fd, SENSOR_ADDR, data, 1, data, 2) < 2) {
        perror("i2cWriteRead");
        return 0;
    }

    return (data[1] << 8) | data[0];
}

int pwm_setup(void) {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    if (gpioHardwarePWM(LED_GPIO, PWM_FREQ, 0) < 0) {
        perror("gpioHardwarePWM");
        return -1;
    }

    return 0;
}

void pwm_set_duty(uint32_t duty) {
    gpioHardwarePWM(LED_GPIO, PWM_FREQ, duty);
}

void log_entry(const LogEntry *entry) {
    FILE *log_file = fopen(LOG_FILE, "a");

    if (!log_file) {
        perror("fopen");
        entry->error_code = -1;
    } else {
        fprintf(log_file, "%s %u %u %d\n", ctime(&entry->timestamp), entry->lux, entry->brightness, entry->error_code);
        fflush(log_file);
        fclose(log_file);
    }
}

void signal_handler(int signum) {
    gpioTerm(LED_GPIO);
    i2cClose(i2c_fd);
    fclose(log_file);
    pigpioTerm();
    exit(0);
}

