#define GPIO_SENSORS_START 2
#define GPIO_SENSORS_END 9
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "touch_log.txt"

static void signal_handler(int signum) {
    (void)signum;
    gpioTerm();
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerm();
        return 1;
    }

    for (int gpio = GPIO_SENSORS_START; gpio <= GPIO_SENSORS_END; ++gpio) {
        if (gpioSetMode(gpio, PI_INPUT_PULL_DOWN) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input with pull-down resistor\n", gpio);
            gpioTerm();
            return 1;
        }
    }

    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        gpioTerm();
        return 1;
    }

    int last_touched_channels[GPIO_SENSORS_END - GPIO_SENSORS_START + 1] = {-1};
    time_t last_log_time = 0;

    while (1) {
        for (int gpio = GPIO_SENSORS_START; gpio <= GPIO_SENSORS_END; ++gpio) {
            int state = gpioRead(gpio);
            if (state == 0) { // Untouched
                if (last_touched_channels[gpio - GPIO_SENSORS_START] != -1) {
                    gpioWrite(GPIO_LED, 1);
                    time_t now = time(NULL);
                    if (difftime(now, last_log_time) > 1) {
                        char log_str[64];
                        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
                        snprintf(log_str + strlen(log_str), sizeof(log_str) - strlen(log_str), " - Channel %d Touched\n", gpio);
                        FILE *log_file = fopen(LOG_FILE, "a");
                        if (log_file) {
                            fputs(log_str, log_file);
                            fclose(log_file);
                            last_log_time = now;
                        } else {
                            perror("Failed to open log file");
                        }
                    }
                }
                last_touched_channels[gpio - GPIO_SENSORS_START] = -1;
            } else { // Touched
                if (last_touched_channels[gpio - GPIO_SENSORS_START] == -1) {
                    last_touched_channels[gpio - GPIO_SENSORS_START] = gpio;
                    if (gpioWrite(GPIO_LED, 1) < 0) {
                        perror("Failed to turn on LED");
                    }
                }
            }
        }

        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    return 0;
}

