#define OPT3001_CONFIG_REG 0x01
#define OPT3001_RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define I2C_BUS 1

static int g_i2c_fd = -1;
static time_t g_last_log_time = 0;

void sigint_handler(int signum) {
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

void log_lux(double lux) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char log_line[64];

    strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S, ", tm_now);
    snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), "%.2f\n", lux);

    if (fwrite(log_line, 1, strlen(log_line), stdout) != strlen(log_line)) {
        perror("fwrite");
    }

    if (fwrite(log_line, 1, strlen(log_line), log_file) != strlen(log_line)) {
        perror("fwrite");
    }

    fflush(stdout);
    fflush(log_file);

    g_last_log_time = now;
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    signal(SIGINT, sigint_handler);

    return 0;
}

int init_i2c() {
    g_i2c_fd = i2cOpen(I2C_BUS, 1000);

    if (g_i2c_fd < 0) {
        perror("i2cOpen");
        return -1;
    }

    return 0;
}

void configure_opt3001() {
    uint16_t config_word_be = htons(CONFIG_WORD);
    uint16_t config_word_le;

    if (i2cWriteWordData(g_i2c_fd, OPT3001_ADDR, OPT3001_CONFIG_REG, config_word_be) < 0) {
        perror("i2cWriteWordData");
    }

    if (i2cReadWordData(g_i2c_fd, OPT3001_ADDR, OPT3001_CONFIG_REG, &config_word_le) < 0) {
        perror("i2cReadWordData");
    }

    if (config_word_le != config_word_be) {
        fprintf(stderr, "Failed to write correct configuration word to OPT3001\n");
    }

    usleep(100000); // Wait at least 100 ms for the first conversion
}

double read_lux() {
    uint16_t result_reg_be;
    uint16_t result_reg_le;
    double lux;

    if (i2cReadWordData(g_i2c_fd, OPT3001_ADDR, OPT3001_RESULT_REG, &result_reg_be) < 0) {
        perror("i2cReadWordData");
        return NAN;
    }

    result_reg_le = ntohs(result_reg_be);

    int exponent = (result_reg_le >> 12) & 0x0F;
    int mantissa = result_reg_le & 0x0FFF;

    lux = mantissa * 0.01 * pow(2, exponent);

    return lux;
}

int main() {
    int init_result = init_pigpio();

    if (init_result < 0) {
        return 1;
    }

    int i2c_init_result = init_i2c();

    if (i2c_init_result < 0) {
        return 1;
    }

    configure_opt3001();

    FILE *log_file = fopen("light_data.txt", "w");

    if (log_file == NULL) {
        perror("fopen");
        return 1;
    }

    while (1) {
        double lux = read_lux();

        if (!isnan(lux)) {
            log_lux(lux);
            printf("Lux: %.2f\n", lux);
        }

        if (difftime(time(NULL), g_last_log_time) >= 1) {
            fflush(log_file);
            g_last_log_time = time(NULL);
        }

        usleep(1000000); // Sleep for 1 second
    }

    fclose(log_file);

    i2cClose(g_i2c_fd);
    gpioTerminate();

    return 0;
}

