#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL 500

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *message) {
    fprintf(stderr, "%s: error\n", message);
}

void log_event(const char *message, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, message);
    fprintf(stderr, "%s: state = %d\n", time_string, state);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: %s\n", time_string, message);
    fprintf(log_file, "%s: state = %d\n", time_string, state);
    fclose(log_file);
}

int main(void) {
    int ret;
    int sensor_state;
    int alert_state = 0;

    if ((ret = pigpio_init()) < 0) {
        log_error("Failed to initialize pigpio library");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        log_error("Failed to set sensor GPIO mode");
        goto cleanup;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set alert GPIO mode");
        goto cleanup;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        goto cleanup;
    }
    fclose(log_file);

    while (running) {
        usleep(POLL_INTERVAL * 1000);

        sensor_state = gpioRead(SENSOR_GPIO);
        if (sensor_state < 0) {
            log_error("Failed to read sensor GPIO");
            continue;
        }

        if (sensor_state == 0) {
            if (alert_state == 0) {
                log_event("Flame detected", sensor_state);
                gpioWrite(ALERT_GPIO, 1);
                usleep(1000000);
                gpioWrite(ALERT_GPIO, 0);
                alert_state = 1;
            }
        } else {
            if (alert_state == 1) {
                log_event("Flame no longer detected", sensor_state);
                alert_state = 0;
            }
        }
    }

cleanup:
    gpioTerm();
    pigpio_terminate();
    return 0;
}

