#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x08
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

static char *log_file = "cooling_log.csv";
static FILE *log_fp;

int init_i2c() {
    int file = open("/dev/i2c-1", O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        close(file);
        return -1;
    }

    return file;
}

int read_sensor(int i2c_file) {
    uint8_t buf[3];
    int ret;

    ret = i2c_master_send(i2c_file, (const uint8_t[]) {0x36, 0x08}, 2);
    if (ret != 2) {
        perror("Failed to send command");
        return -1;
    }

    usleep(2000); // Wait at least 2 ms before the first read

    ret = i2c_master_recv(i2c_file, buf, 3);
    if (ret != 3) {
        perror("Failed to receive data");
        return -1;
    }

    uint16_t raw_flow = (buf[0] << 8) | buf[1];
    uint8_t crc = buf[2];
    uint8_t calculated_crc = crc8(raw_flow, 2, CRC_POLYNOMIAL, CRC_INIT);

    if (crc != calculated_crc) {
        fprintf(stderr, "CRC error\n");
        return -1;
    }

    return raw_flow;
}

float convert_flow(int raw_flow) {
    if (raw_flow < 0 || raw_flow > 65535) {
        fprintf(stderr, "Out-of-range flow value\n");
        return NAN;
    }

    return (float)raw_flow / 90.0;
}

uint8_t crc8(uint8_t *data, int len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;

    for (int i = 0; i < len; ++i) {
        for (int bit = 8; bit > 0; --bit) {
            crc = (crc >> 1) ^ (crc & 0x01 ? poly : 0);
            if ((data[i] & (1 << (7 - bit))) != 0) {
                crc = (crc >> 1) ^ poly;
            }
        }
    }

    return crc;
}

void log_row(time_t timestamp, float flow_rate, const char *status) {
    if (log_fp == NULL) {
        log_fp = fopen(log_file, "w");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return;
        }

        fprintf(log_fp, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    char timestamp_str[20];
    ctime_r(&timestamp, timestamp_str);
    timestamp_str[19] = '\0';

    fprintf(log_fp, "%s,%.2f,%s\n", timestamp_str, flow_rate, status);
}

void sigint_handler(int sig) {
    fprintf(stderr, "Received SIGINT, exiting gracefully...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    if (gpioTerm() < 0) {
        perror("Failed to terminate pigpio");
    }

    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_file = init_i2c();
    if (i2c_file < 0) {
        return 1;
    }

    time_t last_log_time = 0;
    float last_flow_rate = NAN;
    char status[32];

    while (1) {
        int raw_flow = read_sensor(i2c_file);
        if (raw_flow < 0) {
            if (i2c_file != -1) {
                close(i2c_file);
                i2c_file = init_i2c();
            }
            continue;
        }

        float flow_rate = convert_flow(raw_flow);
        if (isnan(flow_rate)) {
            snprintf(status, sizeof(status), "INVALID");
        } else {
            snprintf(status, sizeof(status), "%.2f ml/min", flow_rate);
        }

        time_t now = time(NULL);
        if (difftime(now, last_log_time) > 1) {
            log_row(now, last_flow_rate, last_status);
            last_log_time = now;
        }

        last_flow_rate = flow_rate;
        last_status[0] = '\0';
        strncat(last_status, status, sizeof(last_status) - 1);
    }

    if (i2c_file != -1) {
        close(i2c_file);
    }

    if (log_fp != NULL) {
        fclose(log_fp);
    }

    if (gpioTerm() < 0) {
        perror("Failed to terminate pigpio");
    }

    return 0;
}

