#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <stdbool.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>

#define LEFT_GPIO 17
#define MIDDLE_GPIO 27
#define RIGHT_GPIO 22
#define LOG_FILE "path_log.csv"

static gpiod_chip *chip;
static gpiod_line_request_linestate_vlinestate_cb left_cb;
static gpiod_line_request_linestate_vlinestate_cb middle_cb;
static gpiod_line_request_linestate_vlinestate_cb right_cb;

void gpio_cb(struct gpiod_line *line, int value, void *user_data) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%lu.%06lu", tv.tv_sec, tv.tv_usec);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, line == gpiod_get_line_by_number(chip, LEFT_GPIO) ? value : -1,
                                          line == gpiod_get_line_by_number(chip, MIDDLE_GPIO) ? value : -1,
                                          line == gpiod_get_line_by_number(chip, RIGHT_GPIO) ? value : -1);
    fclose(log_file);
}

int main(void) {
    int ret;

    if ((ret = gpiod_library_open()) < 0) {
        perror("gpiod_library_open");
        return EXIT_FAILURE;
    }

    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("gpiochip_open_byname");
        goto cleanup_libgpiod;
    }

    if (gpiod_line_request_array(chip, 3, GPIOD_LINE_REQUEST_INPUT, NULL, NULL) < 0) {
        perror("gpiod_line_request_array");
        goto cleanup_gpiochip;
    }

    left_cb.callback = gpio_cb;
    left_cb.user_data = NULL;
    ret = gpiod_line_request_event_cb(gpiod_get_line_by_number(chip, LEFT_GPIO), &left_cb);
    if (ret < 0) {
        perror("gpiod_line_request_event_cb (left)");
        goto cleanup_gpio_lines;
    }

    middle_cb.callback = gpio_cb;
    middle_cb.user_data = NULL;
    ret = gpiod_line_request_event_cb(gpiod_get_line_by_number(chip, MIDDLE_GPIO), &middle_cb);
    if (ret < 0) {
        perror("gpiod_line_request_event_cb (middle)");
        goto cleanup_gpio_lines;
    }

    right_cb.callback = gpio_cb;
    right_cb.user_data = NULL;
    ret = gpiod_line_request_event_cb(gpiod_get_line_by_number(chip, RIGHT_GPIO), &right_cb);
    if (ret < 0) {
        perror("gpiod_line_request_event_cb (right)");
        goto cleanup_gpio_lines;
    }

    while (true) {
        usleep(50000);
    }

cleanup_gpio_lines:
    gpiod_line_release(gpiod_get_line_by_number(chip, LEFT_GPIO));
    gpiod_line_release(gpiod_get_line_by_number(chip, MIDDLE_GPIO));
    gpiod_line_release(gpiod_get_line_by_number(chip, RIGHT_GPIO));

cleanup_gpiochip:
    gpiod_chip_close(chip);

cleanup_libgpiod:
    gpiod_library_close();

    return EXIT_SUCCESS;
}

void sigint_handler(int sig) {
    gpiod_line_release(gpiod_get_line_by_number(chip, LEFT_GPIO));
    gpiod_line_release(gpiod_get_line_by_number(chip, MIDDLE_GPIO));
    gpiod_line_release(gpiod_get_line_by_number(chip, RIGHT_GPIO));
    gpiod_chip_close(chip);
    gpiod_library_close();

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fputc('\n', log_file);
        fclose(log_file);
    }

    exit(EXIT_SUCCESS);
}

int main(void) {
    signal(SIGINT, sigint_handler);
    return main();
}

