#include <sys/types.h>
#include <fcntl.h>
#include <linux/types.h>
#include <gpiod.h>

#define FLAME_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "alert_log.txt"

static gpiod_chip *chip;
static gpiod_line *flame_sensor, *buzzer;
static FILE *log_file;

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: %s\n", time_string, message);
}

void buzzer_on(void) {
    gpiod_line_set_value(buzzer, 1);
}

void buzzer_off(void) {
    gpiod_line_set_value(buzzer, 0);
}

int init_gpio(void) {
    int ret;

    if (!(chip = gpiod_chip_open_by_name("gpiochip0"))) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    if (!(flame_sensor = gpiod_chip_get_line(chip, FLAME_SENSOR_GPIO))) {
        perror("Failed to get line for flame sensor");
        goto close_chip;
    }

    if (!(buzzer = gpiod_chip_get_line(chip, BUZZER_GPIO))) {
        perror("Failed to get line for buzzer");
        goto release_flame_sensor;
    }

    if (gpiod_line_request_input(flame_sensor, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW) < 0) {
        perror("Failed to request input for flame sensor");
        goto release_buzzer;
    }

    if (gpiod_line_request_output(buzzer, GPIOD_LINE_REQUEST_OUTPUT_HIGH) < 0) {
        perror("Failed to request output for buzzer");
        goto release_flame_sensor;
    }

    return 0;

release_buzzer:
    gpiod_line_release(buzzer);

release_flame_sensor:
    gpiod_line_release(flame_sensor);

close_chip:
    gpiod_chip_close(chip);

    return -1;
}

void cleanup(void) {
    buzzer_off();
    gpiod_line_release(flame_sensor);
    gpiod_line_release(buzzer);
    gpiod_chip_close(chip);
    fclose(log_file);

    exit(0);
}

void signal_handler(int signum) {
    (void)signum;
    cleanup();
}

int main(void) {
    int ret;
    uint32_t value;
    struct timespec delay = { .tv_sec = 0, .tv_nsec = 500 * 1000000 };

    if (log_file = fopen(LOG_FILE, "w")) {
        log_event("System started");
    } else {
        perror("Failed to open log file");
        return -1;
    }

    if (init_gpio() < 0) {
        return -1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        ret = gpiod_line_get_value(flame_sensor, &value);
        if (ret < 0) {
            perror("Failed to get value from flame sensor");
            goto cleanup;
        }

        if (value == 0) {
            log_event("Flame detected");
            buzzer_on();

            nanosleep(&delay, NULL);

            buzzer_off();

            for (int i = 0; i < 20; i++) {
                nanosleep(&delay, NULL);
                ret = gpiod_line_get_value(flame_sensor, &value);
                if (ret < 0) {
                    perror("Failed to get value from flame sensor");
                    goto cleanup;
                }

                if (value != 0) {
                    break;
                }
            }
        }

        nanosleep(&delay, NULL);
    }

cleanup:
    cleanup();

    return 0;
}

