#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define LED_GPIO 17
#define DEBOUNCE_DELAY 200
#define LOG_FILE "touch_log.txt"

int main(void) {
    int touch_state = 0;
    int fd;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if ((fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    while (1) {
        touch_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch_state == 0) {
            if (!gpioRead(TOUCH_SENSOR_GPIO)) {
                gpioWrite(LED_GPIO, !gpioRead(LED_GPIO));
                rawtime = time(NULL);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                dprintf(fd, "%s: Touch detected\n", timestamp);

                usleep(DEBOUNCE_DELAY * 1000);
            }
        }

        usleep(10000);
    }

    close(fd);
    gpioTerminate();
    return 0;
}

void signal_handler(int signum) {
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    return main();
}

