    fprintf(g_log_file, "%s,%d,%d\n", timestamp, sensor, state);
}

int init_gpio() {
    if ((g_pi_fd = pigpio_init()) < 0) {
        log_error("Failed to initialize pigpio library");
        return -1;
    }

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO_1, PI_INPUT) != 0) {
        log_error("Failed to set GPIO mode for sensor 1");
        return -1;
    }
    if (gpioSetPullUpResistor(SENSOR_GPIO_1, 1) != 0) {
        log_error("Failed to set pull-up resistor for sensor 1");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO_2, PI_INPUT) != 0) {
        log_error("Failed to set GPIO mode for sensor 2");
        return -1;
    }
    if (gpioSetPullUpResistor(SENSOR_GPIO_2, 1) != 0) {
        log_error("Failed to set pull-up resistor for sensor 2");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO_3, PI_INPUT) != 0) {
        log_error("Failed to set GPIO mode for sensor 3");
        return -1;
    }
    if (gpioSetPullUpResistor(SENSOR_GPIO_3, 1) != 0) {
        log_error("Failed to set pull-up resistor for sensor 3");
        return -1;
    }

    return 0;
}

void cleanup() {
    if (g_log_file) {
        fclose(g_log_file);
    }
    if (g_pi_fd >= 0) {
        gpioTerminate();
        pigpio_stop();
    }
}

void signal_handler(int signum) {
    cleanup();
    exit(0);
}

int main() {
    struct timespec ts;
    int sensor_states[3] = {-1, -1, -1};
    int i;

    if (init_gpio() != 0) {
        return 1;
    }

