#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x4A
#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG 0x04
#define REG_ENABLE 0x01
#define REG_HR 0x2A
#define HR_MIN 30
#define HR_MAX 220
#define SAMPLES_FOR_AVERAGE 5
#define LOG_FILE "heart_rate.csv"

int main() {
    int i2c_fd, ret;
    uint16_t raw_hr, filtered_hr[SAMPLES_FOR_AVERAGE] = {0};
    uint8_t part_id, hw_rev;
    FILE *log_file;
    time_t rawtime;
    struct tm *time_info;
    char log_line[32];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 1000000);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        return 1;
    }

    ret = i2cReadReg16(i2c_fd, REG_PART_ID, &part_id);
    if (ret < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        goto cleanup;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Wrong PART_ID (expected 0x02, got 0x%02X)\n", part_id);
        goto cleanup;
    }

    ret = i2cReadReg16(i2c_fd, REG_HW_REV, &hw_rev);
    if (ret < 0) {
        fprintf(stderr, "Failed to read HW_REV register\n");
        goto cleanup;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Wrong HW_REV (expected 0x01, got 0x%02X)\n", hw_rev);
        goto cleanup;
    }

    ret = i2cWriteReg16(i2c_fd, REG_LED_CURRENT, 0x3F);
    if (ret < 0) {
        fprintf(stderr, "Failed to write LED_CURRENT register\n");
        goto cleanup;
    }

    ret = i2cWriteReg16(i2c_fd, REG_AVG, 0x04);
    if (ret < 0) {
        fprintf(stderr, "Failed to write AVG register\n");
        goto cleanup;
    }

    ret = i2cWriteReg16(i2c_fd, REG_ENABLE, 0x01);
    if (ret < 0) {
        fprintf(stderr, "Failed to write ENABLE register\n");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (1) {
        raw_hr = i2cReadWordData(i2c_fd, REG_HR);
        if (raw_hr < 0) {
            fprintf(stderr, "I2C read error, retrying\n");
            continue;
        }

        filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE] = raw_hr;
        rawtime.tv_sec++;
        filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE] = raw_hr * 0.5;

        for (size_t i = 0; i < SAMPLES_FOR_AVERAGE; i++) {
            filtered_hr[i] += filtered_hr[(i + 1) % SAMPLES_FOR_AVERAGE];
        }
        filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE] /= SAMPLES_FOR_AVERAGE;

        if (filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE] < HR_MIN ||
            filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE] > HR_MAX) {
            fprintf(stderr, "Invalid heart rate: %d\n", filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE]);
            continue;
        }

        time_info = localtime(&rawtime);
        snprintf(log_line, sizeof(log_line), "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
                 time_info->tm_year + 1900, time_info->tm_mon + 1, time_info->tm_mday,
                 time_info->tm_hour, time_info->tm_min, time_info->tm_sec,
                 filtered_hr[rawtime.tv_sec % SAMPLES_FOR_AVERAGE]);
        fputs(log_line, log_file);
        fflush(log_file);
    }

cleanup:
    fclose(log_file);
    pigpio_i2c_close(i2c_fd);
    gpioTerminate();
    return 0;
}

