    gpiod_line_release(requests[SENSOR_2]);
    gpiod_line_release(requests[SENSOR_3]);
    gpiod_line_release(requests[SENSOR_4]);

    if (csv_file) {
        fclose(csv_file);
        csv_file = NULL;
    }

    gpiod_chip_put(chip);
    exit(0);
}

