    signal(SIGTERM, handle_signal);

    if ((csv_file = fopen("tracking_log.csv", "a")) == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (fseek(csv_file, 0, SEEK_SET) != 0) {
        perror("fseek");
        exit(EXIT_FAILURE);
    }

    if (fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n") < 0) {
        perror("fprintf");
        exit(EXIT_FAILURE);
    }

    if ((chip = gpiod_chip_open(GPIO_BASE)) == NULL) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    for (int i = SENSOR_1; i <= SENSOR_4; ++i) {
        gpiod_line_request_config config = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        requests[i] = gpiod_line_request_get(chip, i);
        if (gpiod_line_request_configure_async(requests[i], &config, req_data + i) != 0) {
