#include <libgpiod.h>
#include <pthread.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_18 18
#define DEBOUNCE_WINDOW_MS 50
#define POLL_INTERVAL_MS 100
#define LOG_FILE "/var/log/tilt_events.log"

static gpiod_chip *chip;
static gpiod_line *line_17, *line_18;
static pthread_t thread_id;
static int debounce_timer;
static FILE *log_file;

void log_event(int sensor, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[26];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d tilted\n", time_string, sensor);
    fflush(log_file);
}

void debounce_handler(unsigned int data, unsigned int event, void *user_data) {
    if (event == GPIOD_LINE_EVENT_EDGE_FALLING) {
        debounce_timer = 0;
        log_event(GPIOD_LINE_GET_NUMBER(line_17), "GPIO17");
        log_event(GPIOD_LINE_GET_NUMBER(line_18), "GPIO18");
    }
}

void *poll_sensors(void *arg) {
    struct timespec ts;
    int prev_state_17 = 1, prev_state_18 = 1;

    while (1) {
        gpiod_line_get_value(line_17);
        gpiod_line_get_value(line_18);

        if (GPIOD_LINE_GET_VALUE(line_17) != prev_state_17) {
            prev_state_17 = GPIOD_LINE_GET_VALUE(line_17);
            debounce_timer = POLL_INTERVAL_MS;
        }

        if (GPIOD_LINE_GET_VALUE(line_18) != prev_state_18) {
            prev_state_18 = GPIOD_LINE_GET_VALUE(line_18);
            debounce_timer = POLL_INTERVAL_MS;
        }

        if (debounce_timer > 0) {
            debounce_timer--;
        } else {
            gpiod_line_request_event(line_17, GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_BOTH | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ENABLED, debounce_handler, NULL);
            gpiod_line_request_event(line_18, GPIOD_LINE_REQUEST_DIRECTION_IN | GPIOD_LINE_REQUEST_EDGE_BOTH | GPIOD_LINE_REQUEST_ACTIVE_LOW | GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ENABLED, debounce_handler, NULL);
        }

        ts.tv_sec = POLL_INTERVAL_MS / 1000;
        ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&ts, NULL);
    }

    return NULL;
}

int main() {
    int ret;

    if ((ret = gpiod_library_open()) < 0) {
        fprintf(stderr, "Failed to open libgpiod: %s\n", strerror(errno));
        return 1;
    }

    if ((chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME)) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        goto cleanup_libgpiod;
    }

    if ((line_17 = gpiod_chip_get_line(chip, GPIO_LINE_17)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line 17: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    if ((line_18 = gpiod_chip_get_line(chip, GPIO_LINE_18)) == NULL) {
        fprintf(stderr, "Failed to get GPIO line 18: %s\n", strerror(errno));
        goto cleanup_line_17;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup_line_18;
    }

    if (pthread_create(&thread_id, NULL, poll_sensors, NULL) != 0) {
        perror("Failed to create thread");
        goto cleanup_log_file;
    }

    pthread_detach(thread_id);

    while (1) {
        usleep(100000);
    }

cleanup_log_file:
    fclose(log_file);

cleanup_line_18:
    gpiod_line_release(line_18);

cleanup_chip:
    gpiod_chip_release(chip);

cleanup_libgpiod:
    gpiod_library_close();

    return 0;
}

