}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct timespec ts;
    int sensor1, sensor2, led_state;
    FILE *log_file;
    int ret;

    clock_gettime(CLOCK_MONOTONIC, &ts);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_put(chip);
        return 1;
    }

    fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");

    request = gpiod_line_request_parse(SENSOR1_LINE_NAME, "in");
    if (!request) {
        perror("Failed to request sensor1 line");
        goto error;
    }
    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable sensor1 line");
        goto error;
    }

    request = gpiod_line_request_parse(SENSOR2_LINE_NAME, "in");
    if (!request) {
        perror("Failed to request sensor2 line");
        goto error;
    }
    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable sensor2 line");
        goto error;
    }

    request = gpiod_line_request_parse(LED_LINE_NAME, "out");
    if (!request) {
        perror("Failed to request LED line");
        goto error;
    }
    ret = gpiod_line_request_enable(request);
    if (ret < 0) {
        perror("Failed to enable LED line");
        goto error;
    }

    while (1) {
        sensor1 = gpiod_line_get_value(gpiod_line_get_by_name(request, SENSOR1_LINE_NAME));
        sensor2 = gpiod_line_get_value(gpiod_line_get_by_name(request, SENSOR2_LINE_NAME));
        led_state = sensor1 + sensor2;

        gpiod_line_set_value(gpiod_line_get_by_name(request, LED_LINE_NAME), led_state);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%lld,%d,%d,%d\n", (long long)ts.tv_sec * 1000 + ts.tv_nsec / 1000000, sensor1, sensor2, led_state);
        fflush(log_file);

        usleep(100000);
    }

error:
    gpiod_line_request_free(request);
    gpiod_chip_put(chip);
    fclose(log_file);

    return 0;
}

void signal_handler(int sig) {
    gpiod_line_set_value(gpiod_line_get_by_name(request, LED_LINE_NAME), 0);
    gpiod_line_request_free(request);
    gpiod_chip_put(chip);
    fclose(log_file);
    exit(0);
}

int main(void) {
    signal(SIGINT, signal_handler);
    return main();
}

