This program initializes the GPIO chip, requests the lines for the two sensors and the LED, and sets up a signal handler for SIGINT. It then enters a loop where it reads the sensor values, sets the LED state, logs the data, and sleeps for 100ms. In case of errors, it frees the resources and exits gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MIC_GPIO 4
#define LED_GPIO 17
#define SAMPLE_RATE 8000
#define SAMPLE_PERIOD_US 125
#define LED_ON_MS 100
#define BUFFER_SIZE (SAMPLE_RATE * (LED_ON_MS * 1000 / SAMPLE_PERIOD_US))

volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int main(void) {
    int ret;
    unsigned long long last_sample = 0;
    unsigned long long buffer[BUFFER_SIZE];
    unsigned int samples_in_buffer = 0;
    unsigned int peak_index = 0;
    unsigned int led_state = 0;

    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", gpioStrerror(ret));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(MIC_GPIO, PI_INPUT);
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    while (running) {
        gpioDelayUs(SAMPLE_PERIOD_US);

        if (gpioRead(MIC_GPIO) == GPIO_HIGH) {
            unsigned long long now = (unsigned long long)(time(NULL) * 1000000);
            buffer[samples_in_buffer++] = now - last_sample;

            if (samples_in_buffer >= BUFFER_SIZE) {
                unsigned int max_index = 0;
                for (unsigned int i = 1; i < BUFFER_SIZE; ++i) {
                    if (buffer[max_index] < buffer[i]) {
                        max_index = i;
                    }
                }
                peak_index = max_index;
                samples_in_buffer = 0;
                last_sample = buffer[peak_index];
            }
        }

        if (samples_in_buffer >= BUFFER_SIZE / 2 && led_state == 0) {
            gpioWrite(LED_GPIO, GPIO_HIGH);
            led_state = 1;
            gpioDelay(LED_ON_MS * 1000);
            gpioWrite(LED_GPIO, GPIO_LOW);
            led_state = 0;
        }
    }

    gpioTerminate();
    return 0;
}

