#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define LEFT_GPIO 17
#define CENTER_GPIO 27
#define RIGHT_GPIO 22
#define DELAY_MS 100

gpiod_line_request_linestate_cb_t sensor_cb;
gpiod_line_request *requests[3];

void sensor_cb(struct gpiod_line_request *request, int value, void *data) {
    int gpio = request - requests;
    printf("Sensor %d: %s\n", gpio + 1, value ? "Active" : "Inactive");
}

int init_gpio(void) {
    int ret;
    gpiod_line_request_config cfg = GPIOD_LINE_REQUEST_CONFIG_DIRECTION_INPUT |
                                     GPIOD_LINE_REQUEST_CONFIG_EDGE_RISING |
                                     GPIOD_LINE_REQUEST_CONFIG_PULL_UP;

    for (int i = 0; i < 3; i++) {
        requests[i] = gpiod_request_line(0, gpio_get_chip_data(gpio_get_byname("gpio" + itoa(i + 1))), i + 1, &cfg);
        if (!requests[i]) {
            perror("Failed to request line");
            return -1;
        }

        ret = gpiod_line_request_enable(requests[i]);
        if (ret < 0) {
            perror("Failed to enable line request");
            return -1;
        }

        gpiod_line_request_set_callback(requests[i], sensor_cb, NULL);
    }

    return 0;
}

void cleanup_gpio(void) {
    for (int i = 0; i < 3; i++) {
        if (requests[i]) {
            gpiod_line_request_set_callback(requests[i], NULL, NULL);
            gpiod_line_request_disable(requests[i]);
            gpiod_line_request_free(requests[i]);
        }
    }
}

void signal_handler(int sig) {
    printf("\nReceived signal %d, cleaning up and exiting...\n", sig);
    cleanup_gpio();
    exit(sig);
}

int main(void) {
