            gpiod_line_request_disable(requests[i]);
            gpiod_line_request_free(requests[i]);
        }
    }
}

void signal_handler(int sig) {
    printf("\nReceived signal %d, cleaning up and exiting...\n", sig);
    cleanup_gpio();
    exit(sig);
}

