#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define SI1175_ADDR 0x49
#define ALS_LSB_REG 0x24
#define ALS_MSB_REG 0x25

int i2c_file;

void i2c_init() {
    const char *i2c_dev = "/dev/i2c-" + std::to_string(I2C_BUS);

    if ((i2c_file = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SI1175_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_als(uint16_t *als_data) {
    char read_buf[2];
    char write_buf;

    write_buf = 0x03; // ALS_LOW_RES_MODE
    if (write(i2c_file, &write_buf, 1) != 1) {
        perror("Failed to write to the sensor");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_file, read_buf, 2) != 2) {
        perror("Failed to read from the sensor");
        exit(EXIT_FAILURE);
    }

    *als_data = (read_buf[0] << 8) | read_buf[1];
}

void i2c_cleanup() {
    if (i2c_file >= 0) {
        if (ioctl(i2c_file, I2C_CLOSE) < 0) {
            perror("Failed to release bus");
        }
        close(i2c_file);
    }
}

void signal_handler(int sig) {
    i2c_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_init();

    uint16_t als_data;
    while (1) {
        i2c_read_als(&als_data);
        printf("ALS data: 0x%04x\n", als_data);
        usleep(100000); // Sleep for 100 ms
    }

    i2c_cleanup();
    return EXIT_SUCCESS;
}

