#define MIDDLE_GPIO 3
#define RIGHT_GPIO 4
#define POLL_INTERVAL_MS 100

static gpiod_line_handle_t left_line, middle_line, right_line;

void handle_signal(int sig) {
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    exit(0);
}

int main(void) {
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, handle_signal);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_GPIO);
    if (!left_line) {
        perror("Failed to get line for GPIO");
        gpiod_chip_close(chip);
        return 1;
    }

    middle_line = gpiod_chip_get_line(chip, MIDDLE_GPIO);
    if (!middle_line) {
        perror("Failed to get line for GPIO");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    right_line = gpiod_chip_get_line(chip, RIGHT_GPIO);
    if (!right_line) {
        perror("Failed to get line for GPIO");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(left_line, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW) < 0) {
        perror("Failed to request input for GPIO");
        gpiod_line_release(right_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(middle_line, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW) < 0) {
        perror("Failed to request input for GPIO");
        gpiod_line_release(left_line);
        gpiod_line_release(right_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(right_line, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW) < 0) {
        perror("Failed to request input for GPIO");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        int left_state, middle_state, right_state;

        left_state = gpiod_line_get_value(left_line);
        middle_state = gpiod_line_get_value(middle_line);
        right_state = gpiod_line_get_value(right_line);

        printf("L: %s M: %s R: %s\n", left_state ? "1" : "0", middle_state ? "1" : "0", right_state ? "1" : "0");
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

