#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_COUNT 8

static void sigint_handler(int signum) {
    gpiod_chip_put(chip);
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request *requests[GPIO_LINE_COUNT];
    struct timespec ts;
    int ret, i;

    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open gpiochip0
    if ((chip = gpiod_chip_open(GPIO_CHIP_NAME)) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request all lines as inputs
    for (i = 0; i < GPIO_LINE_COUNT; ++i) {
        if ((requests[i] = gpiod_chip_get_line_request_byindex(chip, i)) == NULL) {
            perror("gpiod_chip_get_line_request_byindex");
            goto cleanup;
        }

        if (gpiod_line_request_direction_input(requests[i]) < 0) {
            perror("gpiod_line_request_direction_input");
            goto cleanup;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &ts);
    while (1) {
        for (i = 0; i < GPIO_LINE_COUNT; ++i) {
            if (gpiod_line_get_value(requests[i]) < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }

            ret = gpiod_line_get_value(requests[i]);
            printf("[%lld.%06lds] CH%d=%d ",
                ts.tv_sec, ts.tv_nsec / 1000000, i + 1, ret);
        }
        printf("\n");

        clock_gettime(CLOCK_MONOTONIC, &ts);
        usleep(200 * 1000); // Sleep for 200ms
    }

cleanup:
    for (i = 0; i < GPIO_LINE_COUNT; ++i) {
        if (requests[i]) {
            gpiod_line_request_free(requests[i]);
        }
    }

    if (chip) {
        gpiod_chip_put(chip);
    }

    return ret < 0 ? 1 : 0;
}

