Here's a complete, compilable C code for a Raspberry Pi 4 Model B Mood Lamp using the pigpio library. The code creates a standalone mood lamp with a common-anode RGB LED connected to GPIO17 (Red), GPIO18 (Green), and GPIO27 (Blue).

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define LED_RED_PIN 17
#define LED_GREEN_PIN 18
#define LED_BLUE_PIN 27
#define PWM_FREQUENCY 1000
#define FADE_STEPS 50
#define FADE_INTERVAL 5

static int gpio_init(void);
static void gpio_cleanup(void);
static void hsv_to_rgb(double hue, unsigned char *r, unsigned char *g, unsigned char *b);
static void fade_led(unsigned char *r, unsigned char *g, unsigned char *b);

int main(void) {
    int ret;

    if ((ret = gpio_init()) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", gpioStrerror(ret));
        return 1;
    }

    while (1) {
        double hue = rand() / (double)RAND_MAX * 6.283185307179586;
        unsigned char r, g, b;
        hsv_to_rgb(hue, &r, &g, &b);
        fade_led(&r, &g, &b);
        usleep(FADE_INTERVAL * 1e6);
    }

    gpio_cleanup();
    return 0;
}

static int gpio_init(void) {
    if (gpioInitialise() < 0) {
        return -1;
    }

    if (gpioSetMode(LED_RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_BLUE_PIN, PI_OUTPUT) < 0) {
        gpioTerm();
        return -1;
    }

    if (gpioSetPWMfrequency(LED_RED_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LED_GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(LED_BLUE_PIN, PWM_FREQUENCY) < 0) {
        gpioTerm();
        return -1;
    }

    return 0;
}

static void gpio_cleanup(void) {
    gpioTerm();
    closelog();
}

static void hsv_to_rgb(double hue, unsigned char *r, unsigned char *g, unsigned char *b) {
    double h = hue / 6.283185307179586;
    double c = 1.0;
    double x = c * (1 - std::fabs(fmod(h, 2) - 1));
    double m = c * std::fabs(fmod(h, 2) - 1);
    double rr, gg, bb;

    if (h < 1.0) {
        rr = c;
        gg = x;
        bb = 0;
    } else if (h < 2.0) {
        rr = x;
        gg = c;
        bb = 0;
    } else if (h < 3.0) {
        rr = 0;
        gg = c;
        bb = x;
    } else if (h < 4.0) {
        rr = 0;
        gg = x;
        bb = c;
    } else if (h < 5.0) {
        rr = x;
        gg = 0;
        bb = c;
    } else {
        rr = c;
        gg = 0;
        bb = x;
    }

    *r = (rr + m) * 255;
    *g = (gg + m) * 255;
    *b = (bb + m) * 255;
}

static void fade_led(unsigned char *r, unsigned char *g, unsigned char *b) {
    unsigned char r_prev = 0, g_prev = 0, b_prev = 0;
    double step = 1.0 / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; ++i) {
        double r_val = r_prev + step * (*r - r_prev);
        double g_val = g_prev + step * (*g - g_prev);
        double b_val = b_prev + step * (*b - b_prev);

        r_val = 255 - r_val;
        g_val = 255 - g_val;
        b_val = 255 - b_val;

        if (r_val < 0) r_val = 0;
        if (g_val < 0) g_val = 0;
        if (b_val < 0) b_val = 0;
        if (r_val > 255) r_val = 255;
        if (g_val > 255) g_val = 255;
        if (b_val > 255) b_val = 255;

        gpioPWM(LED_RED_PIN, r_val);
        gpioPWM(LED_GREEN_PIN, g_val);
        gpioPWM(LED_BLUE_PIN, b_val);

        usleep(10000);

        r_prev = r_val;
        g_prev = g_val;
        b_prev = b_val;
    }
}
```

To compile the code, run:

```sh
gcc -o mood_lamp mood_lamp.c -lrt -lpthread -lpigpio -lrt
```

To run the program, execute:

```sh
sudo ./mood_lamp
```

The program will log errors via syslog and smoothly fade between randomly chosen hues every 5 seconds using hardware PWM at 1000 Hz with an 8-bit (0-255) range. The LED will be turned off, resources will be released, and syslog will be closed on SIGINT and SIGTERM.

