#define GPIO_LINE "gpiochip0"
#define GPIO_LINE_NUM 17
#define RED_THRESHOLD 200

int init_i2c(void) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

int init_gpio(void) {
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    gpiod_line_request_data_t data = { .consumer = "color_sensor" };
    gpiod_line_request_cb_t cb = NULL;

    struct gpiod_chip *chip = gpiod_chip_open_byname(GPIO_LINE);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpiod_line_request_devdata(chip, GPIO_LINE_NUM, &data, flags, cb);
    gpiod_line_set_value(chip, GPIO_LINE_NUM, 0);

    return 0;
}

int init_sensor(int fd) {
    uint8_t sensor_id;
    uint8_t control = 0x00;
    uint8_t atime = 0x00;

    if (write(fd, &control, 1) != 1) {
        perror("Failed to write control register");
        goto cleanup_i2c;
    }

    if (write(fd, &atime, 1) != 1) {
        perror("Failed to write ATIME register");
        goto cleanup_i2c;
    }

    if (read(fd, &sensor_id, 1) != 1) {
        perror("Failed to read sensor ID");
        goto cleanup_i2c;
    }

    if (sensor_id != 0x44) {
        fprintf(stderr, "Invalid sensor ID: 0x%02x\n", sensor_id);
        goto cleanup_i2c;
    }

    return 0;

cleanup_i2c:
    close(fd);
    return -1;
}

void read_sensor(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t data[4];

    if (read(fd, data, 4) != 4) {
        perror("Failed to read sensor data");
        init_sensor(fd);
    }

    *clear = (data[0] << 8) | data[1];
    *red = (data[2] << 8) | data[3];
    *green = (data[4] << 8) | data[5];
    *blue = (data[6] << 8) | data[7];
}

void apply_calibration(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    // Apply per-channel gain and offset calibration here
}

void display_values(const char *prefix, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    printf("%s: Clear: 0x%04x, R: 0x%04x, G: 0x%04x, B: 0x%04x\n", prefix, clear, red, green, blue);
}

void drive_led(int gpio_fd, uint16_t red) {
    if (red > RED_THRESHOLD) {
        gpiod_line_set_value(gpio_chip, GPIO_LINE_NUM, 1);
    } else {
        gpiod_line_set_value(gpio_chip, GPIO_LINE_NUM, 0);
    }
}

int main(void) {
    int i2c_fd = -1;
    int gpio_fd = -1;
    uint16_t clear, red, green, blue;
    struct gpiod_chip *gpio_chip;

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    gpio_fd = init_gpio();
    if (gpio_fd < 0) {
        close(i2c_fd);
        return 1;
    }

    gpio_chip = gpiod_chip_open_byname(GPIO_LINE);

    if (init_sensor(i2c_fd) < 0) {
        goto cleanup_gpio;
    }

    for (int i = 0; i < 10; i++) {
        read_sensor(i2c_fd, &clear, &red, &green, &blue);
        apply_calibration(&clear, &red, &green, &blue);
        display_values("Sensor", clear, red, green, blue);
        drive_led(gpio_fd, red);
        usleep(200000); // 200 ms delay
    }

cleanup_gpio:
    gpiod_chip_close(gpio_chip);
    gpiod_line_release(gpio_fd, GPIO_LINE_NUM);
    close(gpio_fd);

cleanup_i2c:
    if (i2c_fd > 0) {
        i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x01); // Power down sensor
        close(i2c_fd);
    }

    return 0;
}

