#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define LED_COUNT 10
#define LED_PIN 18
#define I2C_ADDR 0x23

double lux_to_brightness(double lux) {
    // Logarithmic brightness mapping (0-1000 lux)
    return 1 - log10(lux / 1000);
}

int read_lux(int fd) {
    char cmd[2] = {0x10, 0x00};
    char data[2];
    int retries = 3;

    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write command to sensor");
        return -1;
    }

    usleep(180000); // Wait 180 ms for the sensor to take a measurement

    while (retries > 0 && read(fd, data, 2) != 2) {
        if (errno != EAGAIN) {
            perror("Failed to read data from sensor");
        }
        usleep(100000); // Wait 100 ms and try again
        retries--;
    }

    if (retries == 0) {
        perror("Failed to read data from sensor after retries");
        return -1;
    }

    return (data[0] << 8 | data[1]) / 1.2;
}

void set_led_strip(double *colors, int count, double brightness) {
    for (int i = 0; i < count; ++i) {
        double r = colors[i * 3 + 0];
        double g = colors[i * 3 + 1];
        double b = colors[i * 3 + 2];

        double intensity = r * brightness + g * brightness + b * brightness;
        if (intensity > 1.0) intensity = 1.0;

        gpioWrite(LED_PIN, (int)(intensity * 255));
        gpioHardwarePWM(LED_PIN, 10000, (int)(intensity * 600));
        usleep(500);
        gpioWrite(LED_PIN, 0);
    }
}

int main() {
    int i2c_fd, ret;
    double lux;
    double led_colors[] = {
        255, 0, 0, // Red
        0, 255, 0, // Green
        0, 0, 255, // Blue
        255, 255, 0, // Yellow
        0, 255, 255, // Cyan
        255, 0, 255, // Magenta
        128, 128, 0, // Orange
        0, 128, 128, // Teal
        128, 0, 128, // Purple
        128, 128, 128 // Gray
    };

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        exit(1);
    }

    if ((gpioInitialise() < 0)) {
        perror("Failed to initialise pigpio library");
        exit(1);
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(LED_PIN, 1000);

    while (1) {
        lux = read_lux(i2c_fd);
        if (lux < 0) {
            perror("Failed to read light sensor data");
            continue;
        }

        double brightness = lux_to_brightness(lux);
        set_led_strip(led_colors, LED_COUNT, brightness);
        usleep(500000); // Update LED strip every 500 ms
    }

    gpioTerminate();
    close(i2c_fd);

    return 0;
}

