#include <spidev.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define SPI_DEV "/dev/spidev0.0"
#define LED_COUNT 64
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000

struct i2c_data {
    int fd;
    void *map_base;
};

struct spi_data {
    int fd;
};

void i2c_init(struct i2c_data *i2c) {
    i2c->fd = open("/dev/i2c-1", O_RDWR);
    if (i2c->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c->fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to acquire address");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c->fd, I2C_MEMADD, 0x23) < 0) {
        perror("Failed to set memory address");
