#define FADE_TIME_MS 500
#define DELAY_MS 100
#define MAX_SENSOR_READ_ATTEMPTS 3

int bh1750_read_lux(int addr, int *lux) {
    char buf[2];
    int file, i;

    file = open((char *)("/dev/i2c-" + std::to_string(I2C_BUS)), O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, addr) < 0) {
        perror("Failed to address BH1750 sensor");
        close(file);
        return -1;
    }

    for (i = 0; i < MAX_SENSOR_READ_ATTEMPTS; ++i) {
        if (write(file, (char *)0x21, 1) != 1) {
            perror("Failed to send One-Time High-Resolution Mode 2 command");
            close(file);
            return -1;
        }

        usleep(180 * 1000);

        if (read(file, buf, 2) != 2) {
            perror("Failed to read BH1750 sensor data");
            close(file);
            return -1;
        }

        *lux = (buf[0] << 8) | buf[1];
        if (*lux < 0x8000) {
            break;
        }
    }

    if (i == MAX_SENSOR_READ_ATTEMPTS) {
        perror("Failed to read valid lux value from BH1750 sensor");
    }

    close(file);
    return i == MAX_SENSOR_READ_ATTEMPTS ? -1 : *lux;
}

