    int i;
    uint32_t data[3];

    for (i = 0; i < 3; ++i) {
        data[i] = (brightness << 6) | (brightness << 1) | brightness;
    }

    for (i = 0; i < 32; ++i) {
        gpioWrite(LED_MOSI, data[i % 3]);
        gpioWrite(LED_SCLK, 0);
        gpioWrite(LED_SCLK, 1);
    }
}

