            lux_sum += *lux_values[i];
            num_valid_sensors++;
        }
    }

    if (num_valid_sensors > 0) {
        lux_avg = (double)lux_sum / num_valid_sensors;
        brightness = (int)(LUX_TO_BRIGHTNESS_FACTOR * log(lux_avg));
    }

    gpioSetMode(LED_MOSI, PI_OUTPUT);
    gpioSetMode(LED_SCLK, PI_OUTPUT);

