        usleep(DELAY_MS * 1000);
    }

    set_led_brightness(brightness);

    while (1) {
        usleep(DELAY_MS * 1000);

        for (i = 0; i < NUM_SENSORS; ++i) {
            lux_values[i] = malloc(sizeof(int));
            if (bh1750_read_lux(bh1750_addrs[i], lux_values[i]) >= 0) {
