            brightness = (int)(LUX_TO_BRIGHTNESS_FACTOR * log(lux_avg));
        }

        for (i = 0; i < FADE_TIME_MS; ++i) {
            set_led_brightness(brightness + i * (31 - brightness) / FADE_TIME_MS);
            usleep(DELAY_MS * 1000);
        }

        set_led_brightness(brightness);
    }

    return 0;
}

