code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <gpiod.h>
#include <signal.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define WS2812B_GPIO 18
#define DELAY_MS 200
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_MS 100

static gpiod_line_request_lines_data_v1 lines_data = { .lines = { { .direction = GPIOD_LINE_DIR_OUT } }, .count = 1 };
static gpiod_line_handle *ws2812b_gpio;

static int i2c_file;
static int i2c_retries = I2C_RETRIES;

void i2c_write_byte_data(uint8_t addr, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = (addr << 1) | (0x01 & ~(1 << 0));
    buf[1] = reg | (value << 1);

    while (i2c_retries > 0) {
        if (write(i2c_file, buf, 2) != 2) {
            perror("I2C write error");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            i2c_retries--;
        } else {
            break;
        }
    }
}

uint16_t i2c_read_word_data(uint8_t addr, uint8_t reg) {
    char buf[2];
    buf[0] = (addr << 1) | (0x00 & ~(1 << 0));
    buf[1] = reg;

    uint16_t data = 0;
    while (i2c_retries > 0) {
        if (write(i2c_file, buf, 2) != 2) {
            perror("I2C write error");
            usleep(I2C_RETRY_DELAY_MS * 1000);
            i2c_retries--;
        } else {
            if (read(i2c_file, &buf, 2) != 2) {
                perror("I2C read error");
                usleep(I2C_RETRY_DELAY_MS * 1000);
                i2c_retries--;
            } else {
                data = (buf[1] << 8) | buf[0];
                break;
            }
        }
    }

    return data;
}

double lux_to_brightness(double lux) {
    return 255 * pow(lux / 120000.0, 1.0/2.2);
}

void setup() {
    i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }

    i2c_write_byte_data(VEML7700_ADDR, 0x00, 0x00);

    gpiod_line_request_lines(&lines_data, 1, GPIOD_LINE_REQUEST_DIRECTION_OUT, "ws2812b");
    ws2812b_gpio = gpiod_get_lines(&lines_data, GPIOD_LINE_STATE_GET);
}

void cleanup() {
    gpiod_line_release_lines(&lines_data, 1);
    close(i2c_file);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup();

    uint16_t als;
    double lux, brightness;

    while (1) {
        als = i2c_read_word_data(VEML7700_ADDR, 0x04);
        lux = als * 0.0288;
        brightness = lux_to_brightness(lux);

        printf("Lux: %.2f, Brightness: %.0f\n", lux, brightness);

        if (gpiod_line_get_value(ws2812b_gpio, 0) != (int)(brightness / 255.0)) {
            gpiod_line_set_value(ws2812b_gpio, (int)(brightness / 255.0));
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}

