    i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(EXIT_FAILURE);
    }

    i2c_write_byte_data(VEML7700_ADDR, 0x00, 0x00);

    gpiod_line_request_lines(&lines_data, 1, GPIOD_LINE_REQUEST_DIRECTION_OUT, "ws2812b");
    ws2812b_gpio = gpiod_get_lines(&lines_data, GPIOD_LINE_STATE_GET);
}

void cleanup() {
    gpiod_line_release_lines(&lines_data, 1);
    close(i2c_file);
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup();

    uint16_t als;
    double lux, brightness;

    while (1) {
        als = i2c_read_word_data(VEML7700_ADDR, 0x04);
        lux = als * 0.0288;
        brightness = lux_to_brightness(lux);

        printf("Lux: %.2f, Brightness: %.0f\n", lux, brightness);

        if (gpiod_line_get_value(ws2812b_gpio, 0) != (int)(brightness / 255.0)) {
            gpiod_line_set_value(ws2812b_gpio, (int)(brightness / 255.0));
        }

        usleep(DELAY_MS * 1000);
    }

    return 0;
}
```

This code initializes the VEML7700 sensor and WS2812B LED strip, reads the ALS data, converts it to lux and brightness, controls the LED strip's brightness using bit-banging, and handles I2C errors by retrying up to 3 times with a 100 ms delay between retries. It also uses signal handlers for SIGINT and SIGTERM to cleanly release GPIO lines, close I2C file descriptors, and turn off the LED strip. The program runs in an infinite loop with a 200 ms delay between iterations, printing the current lux and brightness values to stdout.

