#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x23
#define GPIO_PIN 17

#define BUFFER_SIZE 60
#define DUTY_CYCLE_MIN 0.5
#define DUTY_CYCLE_MAX 5.0
#define LINEAR_FACTOR 4.5

volatile sig_atomic_t running = 1;

struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[2];
};

int i2c_fd;
int gpio_fd;
unsigned char tx_buf[2];
unsigned char rx_buf[2];
unsigned int gpio_pwm_period;
unsigned int gpio_pwm_duty;
unsigned int buffer[BUFFER_SIZE];
unsigned int buffer_head = 0;
unsigned int buffer_tail = 0;

void i2c_read(void) {
    struct i2c_rdwr_ioctl_data data;
    data.msgs[0].addr = SENSOR_ADDR << 1;
    data.msgs[0].flags = 0;
    data.msgs[0].len = 1;
    data.msgs[0].buf = tx_buf;
    data.msgs[1].addr = SENSOR_ADDR << 1;
    data.msgs[1].flags = I2C_M_RD;
    data.msgs[1].len = 2;
    data.msgs[1].buf = rx_buf;

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        perror("I2C read error");
        memset(rx_buf, 0, 2);
    }
}

void gpio_setup(void) {
    char gpio_path[32];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/export");
    int ret = open(gpio_path, O_WRONLY);
    if (ret < 0) {
        perror("Failed to open gpio export file");
        exit(EXIT_FAILURE);
    }

    ret = write(gpio_fd, GPIO_PIN < 16 ? "17" : ("102" + GPIO_PIN - 16), 3);
    if (ret != 3) {
        perror("Failed to write gpio number");
        exit(EXIT_FAILURE);
    }

    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/direction", GPIO_PIN);
    ret = open(gpio_path, O_WRONLY);
    if (ret < 0) {
        perror("Failed to open gpio direction file");
        exit(EXIT_FAILURE);
    }

    ret = write(gpio_fd, "out", 3);
    if (ret != 3) {
        perror("Failed to write gpio direction");
        exit(EXIT_FAILURE);
    }

    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/edge", GPIO_PIN);
    ret = open(gpio_path, O_WRONLY);
    if (ret < 0) {
        perror("Failed to open gpio edge file");
        exit(EXIT_FAILURE);
    }

    ret = write(gpio_fd, "both", 4);
    if (ret != 4) {
        perror("Failed to write gpio edge");
        exit(EXIT_FAILURE);
    }

    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/active_low", GPIO_PIN);
    ret = open(gpio_path, O_WRONLY);
    if (ret < 0) {
        perror("Failed to open gpio active_low file");
        exit(EXIT_FAILURE);
    }

    ret = write(gpio_fd, "0", 2);
    if (ret != 2) {
        perror("Failed to write gpio active_low");
        exit(EXIT_FAILURE);
    }

    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/blink_period", GPIO_PIN);
    ret = open(gpio_path, O_WRONLY);
    if (ret < 0) {
        perror("Failed to open gpio blink_period file");
        exit(EXIT_FAILURE);
    }

    gpio_pwm_period = sysconf(_SC_CLK_TCK) * 1000;
    ret = write(gpio_fd, (char *) &gpio_pwm_period, sizeof(gpio_pwm_period));
    if (ret != sizeof(gpio_pwm_period)) {
        perror("Failed to write gpio blink_period");
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);
}

void gpio_cleanup(void) {
    char gpio_path[32];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/export", GPIO_PIN);
    int ret = open(gpio_path, O_WRONLY);
    if (ret >= 0) {
        write(gpio_fd, "unexport", 7);
        close(gpio_fd);
    }
}

double lux_from_raw(unsigned short raw) {
    return (double) raw / 1.2;
}

double average_lux(void) {
    unsigned int sum = 0;
    for (int i = buffer_head; i != buffer_tail; ++i) {
        sum += buffer[i];
    }
    return (double) sum / BUFFER_SIZE;
}

void blink_led(double avg_lux) {
    unsigned int duty = (unsigned int) (DUTY_CYCLE_MIN + (avg_lux / 1000) * LINEAR_FACTOR);
    duty = (duty > DUTY_CYCLE_MAX) ? DUTY_CYCLE_MAX : (duty < DUTY_CYCLE_MIN) ? DUTY_CYCLE_MIN : duty;
    unsigned int period = gpio_pwm_period / duty;

    char gpio_path[32];
    snprintf(gpio_path, sizeof(gpio_path), "/sys/class/gpio/gpio%d/blink_period", GPIO_PIN);
    int ret = open(gpio_path, O_WRONLY);
    if (ret < 0) {
        perror("Failed to open gpio blink_period file");
        exit(EXIT_FAILURE);
    }

    ret = write(gpio_fd, (char *) &period, sizeof(period));
    if (ret != sizeof(period)) {
        perror("Failed to write gpio blink_period");
        exit(EXIT_FAILURE);
    }

    close(gpio_fd);
}

void signal_handler(int signum) {
    running = 0;
}

int main(void) {
    signal(SIGINT, signal_handler);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open i2c device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set i2c slave address");
        exit(EXIT_FAILURE);
    }

    gpio_setup();

    while (running) {
        i2c_read();
        double lux = lux_from_raw(rx_buf[0] << 8 | rx_buf[1]);
        buffer[buffer_head] = lux;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        double avg_lux = average_lux();
        blink_led(avg_lux);

        sleep(1);
    }

    gpio_cleanup();
    close(i2c_fd);

    return 0;
}

