#define CLOCK_GPIO 18
#define LATCH_GPIO 27

static gpiod_chip *gpiod_chip;
static gpiod_line_request_data lines[3];

void setup_gpio(void) {
    int ret;

    gpiod_chip = gpiod_chip_open_byname("gpiochip0");
    if (!gpiod_chip) {
        perror("Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line_bylabel(gpiod_chip, "gpio17");
    if (ret < 0) {
        perror("Failed to get GPIO17");
        exit(EXIT_FAILURE);
    }
    lines[0].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_chip_request_line(gpiod_chip, ret, "data");
    if (ret < 0) {
        perror("Failed to request GPIO17");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line_bylabel(gpiod_chip, "gpio18");
    if (ret < 0) {
        perror("Failed to get GPIO18");
        exit(EXIT_FAILURE);
    }
    lines[1].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_chip_request_line(gpiod_chip, ret, "clock");
    if (ret < 0) {
        perror("Failed to request GPIO18");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line_bylabel(gpiod_chip, "gpio27");
    if (ret < 0) {
        perror("Failed to get GPIO27");
        exit(EXIT_FAILURE);
    }
    lines[2].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_chip_request_line(gpiod_chip, ret, "latch");
    if (ret < 0) {
        perror("Failed to request GPIO27");
        exit(EXIT_FAILURE);
    }
}

void shift_out(unsigned char data) {
    int i;

    gpiod_line_set_value(lines[1], 0); // Set clock low

    for (i = 7; i >= 0; i--) {
        gpiod_line_set_value(lines[0], (data >> i) & 1); // Send data bit
        gpiod_line_set_value(lines[1], 1); // Set clock high
        usleep(1); // Delay for clock pulse
        gpiod_line_set_value(lines[1], 0); // Set clock low
    }

    gpiod_line_set_value(lines[2], 1); // Set latch high
    usleep(1); // Delay for latch pulse
    gpiod_line_set_value(lines[2], 0); // Set latch low
}

void display_digit(void) {
    shift_out(0b11110000); // dp off
    shift_out(0b01100000); // segment a
    shift_out(0b10110000); // segment b
    shift_out(0b10111000); // segment c
    shift_out(0b01100000); // segment d
    shift_out(0b10011000); // segment e
    shift_out(0b10011100); // segment f
    shift_out(0b10000000); // segment g
}

int main(void) {
    setup_gpio();

    while (1) {
        display_digit();
        sleep(0.5);
        gpiod_line_set_value(lines[0], 0); // Turn off data
        sleep(0.5);
        display_digit();
    }

    gpiod_chip_release_lines(gpiod_chip, lines, ARRAY_SIZE(lines));
    gpiod_chip_close(gpiod_chip);

    return 0;
}

