#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

static gpiod_line_callback_t button_cb;
static gpiod_line_event_t button_event;
static gpiod_line_handle_t button_line;
static gpiod_chip_handle_t gpiochip;
static int led_state = 0;

void handle_signal(int sig) {
    gpiod_line_set_value(button_line, 1);
    gpiod_line_set_value(gpiochip, "17", led_state);
    gpiod_chip_close(gpiochip);
    exit(0);
}

int main() {
    signal(SIGINT, handle_signal);

    if ((gpiochip = gpiod_chip_open_byname("gpiochip0")) < 0) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    if (gpiod_line_request_array(&gpiochip, 2, "17 out,18 in,pu,edge=falling", &led_state, &button_line) < 0) {
        perror("Failed to request lines");
        goto cleanup;
    }

    gpiod_line_set_value(gpiochip, "17", led_state);

    while (1) {
        int ret = gpiod_line_event_wait(button_line, &button_event, GPIOD_LINE_EVENT_EDGE_FALLING, GPIOD_LINE_EVENT_LEVEL_LOW, 1000000);
        if (ret < 0) {
            perror("Failed to wait for button event");
            goto cleanup;
        }

        if (ret == 0) {
            printf("Button pressed\n");
            gpiod_line_set_value(gpiochip, "17", 0);
            break;
        }

        led_state = !led_state;
        gpiod_line_set_value(gpiochip, "17", led_state);
        usleep(1000000);
    }

cleanup:
    gpiod_line_release(button_line);
    gpiod_chip_close(gpiochip);
    return 0;
}

