#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <linux/types.h>
#include <sys/ioctl.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define LED_LINE_NAME "gpio24"
#define BUTTON_LINE_NAME "gpio22"
#define DEBOUNCE_MS 50

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int count,
                                const char *const lines[], unsigned int flags)
{
    return gpiod_chip_request_lines(chip, count, lines, flags);
}

static void gpiod_line_release(struct gpiod_line *line)
{
    gpiod_line_release(line);
}

static int gpiod_line_get_value(struct gpiod_line *line)
{
    int value;
    int ret = gpiod_line_get_value_cansleep(line, &value);
    if (ret < 0) {
        perror("gpiod_line_get_value_cansleep");
        exit(EXIT_FAILURE);
    }
    return value;
}

static void gpiod_line_set_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("gpiod_line_set_value");
        exit(EXIT_FAILURE);
    }
}

static void gpiod_line_set_direction(struct gpiod_line *line, unsigned int direction)
{
    int ret = gpiod_line_set_direction(line, direction);
    if (ret < 0) {
        perror("gpiod_line_set_direction");
        exit(EXIT_FAILURE);
    }
}

int main(void)
{
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int led_value = 0;
    int button_value;
    unsigned long long debounce_start;
    int ret;

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_line_get_byname(chip, LED_LINE_NAME);
    if (!led_line) {
        perror("gpiod_line_get_byname");
        exit(EXIT_FAILURE);
    }

    button_line = gpiod_line_get_byname(chip, BUTTON_LINE_NAME);
    if (!button_line) {
        perror("gpiod_line_get_byname");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request(button_line, "button");
    if (ret < 0) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request(led_line, "output");
    if (ret < 0) {
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_direction(led_line, GPIOD_LINE_DIR_OUT);
    gpiod_line_set_value(led_line, led_value);

    while (1) {
        button_value = gpiod_line_get_value(button_line);

        if (button_value == 0) {
            debounce_start = get_monotonic_ns();
            while (gpiod_line_get_value(button_line) == 0 &&
                   (get_monotonic_ns() - debounce_start) < DEBOUNCE_MS * NSEC_PER_MSEC)
                usleep(1000);

            if (gpiod_line_get_value(button_line) == 0)
                continue;
        }

        for (;;) {
            gpiod_line_set_value(led_line, led_value);
            sleep(0.5);
            led_value = !led_value;
            gpiod_line_set_value(led_line, led_value);
            sleep(0.5);

            button_value = gpiod_line_get_value(button_line);
            if (button_value != 0)
                break;
            usleep(1000);
        }
    }

    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

