#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define GPIO_PIN 17

#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28

#define G_THRESHOLD (2.0f)
#define SAMPLE_RATE (0.1f)

static int i2c_fd;
static uint8_t data[6];
static float g_x, g_y, g_z;
static FILE *log_file;
static volatile sig_atomic_t running = 1;

void i2c_read(void) {
    if (i2c_readi2c_data(i2c_fd, I2C_ADDR, OUT_X_L_A, data, 6) < 0) {
        perror("i2c_readi2c_data");
        running = 0;
    }
}

void i2c_write(uint8_t reg, uint8_t value) {
    data[0] = reg | 0x80;
    data[1] = value;

    if (i2c_writei2c_data(i2c_fd, I2C_ADDR, data, 2) < 0) {
        perror("i2c_writei2c_data");
        running = 0;
    }
}

void log_data(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %f, %f, %f\n", time_str, g_x, g_y, g_z);
}

void sigint_handler(int signum) {
    running = 0;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        exit(EXIT_FAILURE);
    }

    if (argc > 1) {
        G_THRESHOLD = atof(argv[1]);
    }

    i2c_write(CTRL_REG1_A, 0x27);
    i2c_write(CTRL_REG4_A, 0x00);

    log_file = fopen("impact_log.txt", "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        i2c_read();

        g_x = (data[1] | data[2] << 8) / 16384.0f;
        g_y = (data[3] | data[4] << 8) / 16384.0f;
        g_z = (data[5] | data[6] << 8) / 16384.0f;

        if (sqrtf(g_x * g_x + g_y * g_y + g_z * g_z) > G_THRESHOLD) {
            gpioWrite(GPIO_PIN, 1);
            usleep(50 * 1000);
            gpioWrite(GPIO_PIN, 0);
            log_data();
        }

        usleep(1000000.0f / SAMPLE_RATE);
    }

    close(i2c_fd);
    gpioTerm();
    fclose(log_file);

    return 0;
}

