#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x39
#define LED_GPIO 18
#define CSV_FILE "color_log.csv"

static volatile int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void i2c_write_reg(uint8_t addr, uint16_t reg, uint16_t value) {
    if (i2c_master_write_read(pigpio_i2c_open(I2C_BUS, addr, 0), &reg, 1, &value, 1) < 0) {
        perror("i2c_write_reg");
        sleep(0.1);
    }
}

uint16_t i2c_read_reg(uint8_t addr, uint16_t reg) {
    uint16_t data;
    if (i2c_master_write_read(pigpio_i2c_open(I2C_BUS, addr, 0), &reg, 1, (uint8_t*)&data, 2) < 0) {
        perror("i2c_read_reg");
        sleep(0.1);
        data = 0xffff;
    }
    return data;
}

void setup_sensor() {
    i2c_write_reg(SENSOR_ADDR, 0x0D, 0x01);
}

void setup_led() {
    gpioInitialise();
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, 5000);
}

void log_data(const char *tag, uint16_t data) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(file, "%s,%s,ALS,R,G,B\n", timestamp, tag);
    fprintf(file, "%s,%s,%u,%u,%u,%u\n", timestamp, tag,
            i2c_read_reg(SENSOR_ADDR, 0x64) | (i2c_read_reg(SENSOR_ADDR, 0x65) << 8),
            i2c_read_reg(SENSOR_ADDR, 0x66) | (i2c_read_reg(SENSOR_ADDR, 0x67) << 8),
            i2c_read_reg(SENSOR_ADDR, 0x68) | (i2c_read_reg(SENSOR_ADDR, 0x69) << 8),
            i2c_read_reg(SENSOR_ADDR, 0x6A) | (i2c_read_reg(SENSOR_ADDR, 0x6B) << 8));
    fclose(file);
}

int main() {
    int i2c_fd = -1;
    setup_led();

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if ((i2c_fd = pigpio_i2c_open(I2C_BUS, SENSOR_ADDR, 0)) < 0) {
        perror("pigpio_i2c_open");
        goto cleanup;
    }

    setup_sensor();

    while (running) {
        uint16_t als = (i2c_read_reg(SENSOR_ADDR, 0x64) | (i2c_read_reg(SENSOR_ADDR, 0x65) << 8));
        uint16_t rgb[3] = {
            i2c_read_reg(SENSOR_ADDR, 0x66) | (i2c_read_reg(SENSOR_ADDR, 0x67) << 8),
            i2c_read_reg(SENSOR_ADDR, 0x68) | (i2c_read_reg(SENSOR_ADDR, 0x69) << 8),
            i2c_read_reg(SENSOR_ADDR, 0x6A) | (i2c_read_reg(SENSOR_ADDR, 0x6B) << 8)
        };

        log_data("", als);
        log_data("ALS", als);
        log_data("R", rgb[0]);
        log_data("G", rgb[1]);
        log_data("B", rgb[2]);

        uint8_t duty_cycle = (als > 65535) ? 255 : (als * 255) / 65535;
        gpioHardwarePWM(LED_GPIO, duty_cycle);

        usleep(500000);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerm();
    return 0;
}

