            i2c_read_reg(SENSOR_ADDR, 0x68) | (i2c_read_reg(SENSOR_ADDR, 0x69) << 8),
            i2c_read_reg(SENSOR_ADDR, 0x6A) | (i2c_read_reg(SENSOR_ADDR, 0x6B) << 8)
        };

        log_data("", als);
        log_data("ALS", als);
        log_data("R", rgb[0]);
        log_data("G", rgb[1]);
        log_data("B", rgb[2]);

        uint8_t duty_cycle = (als > 65535) ? 255 : (als * 255) / 65535;
        gpioHardwarePWM(LED_GPIO, duty_cycle);

        usleep(500000);
    }

cleanup:
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerm();
    return 0;
}
