code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F

#define OUT_X_MSB 0x01
#define OUT_X_LSB 0x02
#define OUT_Y_MSB 0x03
#define OUT_Y_LSB 0x04
#define OUT_Z_MSB 0x05
#define OUT_Z_LSB 0x06
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E

#define SENSITIVITY 4096.0
#define GRAVITY 9.81
#define THRESHOLD (19.62 * SENSITIVITY * GRAVITY)

static int g_i2c_fd = -1;
static time_t g_last_impact = 0;

void log_impact(const char *format, ...) {
    char buffer[256];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    va_list args;

    va_start(args, format);
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    strftime(buffer + 16, sizeof(buffer) - 16, "%Y-%m-%d %H:%M:%S", tm);
    buffer[sizeof(buffer) - 1] = '\0';

    FILE *log_file = fopen("impact_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", buffer);
        fclose(log_file);
    }
}

int i2c_read(uint8_t reg, uint16_t *data) {
    uint16_t msb, lsb;

    if (i2cReadRegister16(g_i2c_fd, I2C_ADDR, reg, &msb, &lsb) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    *data = (msb << 8) | lsb;
    return 0;
}

void i2c_write(uint8_t reg, uint16_t data) {
    if (i2cWriteRegister16(g_i2c_fd, I2C_ADDR, reg, data) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
}

int init_sensor() {
    if (i2c_read(WHO_AM_I, &g_who_am_i) < 0) {
        return -1;
    }

    if (g_who_am_i != 0xC7) {
        fprintf(stderr, "Sensor ID mismatch: expected 0xC7, got 0x%02X\n", g_who_am_i);
        return -1;
    }

    i2c_write(CTRL_REG1, 0x01);
    usleep(100000); // Wait for the sensor to enter standby mode
    i2c_write(XYZ_DATA_CFG, 0x00);
    i2c_write(CTRL_REG1, 0x03);

    return 0;
}

void cleanup() {
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    gpioTerminate();
    exit(0);
}

void signal_handler(int signum) {
    cleanup();
}

int main() {
    int ret;
    uint16_t x, y, z;
    double x_scaled, y_scaled, z_scaled, magnitude;
    struct timespec ts;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    g_i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C connection\n");
        goto cleanup;
    }

    if (init_sensor() < 0) {
        goto cleanup;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        if (i2c_read(OUT_X_MSB, &x) < 0 ||
            i2c_read(OUT_X_LSB, &x) < 0 ||
            i2c_read(OUT_Y_MSB, &y) < 0 ||
            i2c_read(OUT_Y_LSB, &y) < 0 ||
            i2c_read(OUT_Z_MSB, &z) < 0 ||
            i2c_read(OUT_Z_LSB, &z) < 0) {
            continue;
        }

        x_scaled = (double)(x >> 2) / SENSITIVITY;
        y_scaled = (double)(y >> 2) / SENSITIVITY;
        z_scaled = (double)(z >> 2) / SENSITIVITY;
        magnitude = sqrt(x_scaled * x_scaled + y_scaled * y_scaled + z_scaled * z_scaled);

        if (magnitude > THRESHOLD) {
            clock_gettime(CLOCK_REALTIME, &ts);
            log_impact("%4d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f,%.3f",
                       ts.tv_year - 1900, ts.tv_mon + 1, ts.tv_mday,
                       ts.tv_hour, ts.tv_min, ts.tv_sec,
                       x_scaled, y_scaled, z_scaled, magnitude);
            g_last_impact = time(NULL);
        }

        usleep(50000);
    }

cleanup:
    cleanup();
    return 0;
}

