This code initializes the sensor, reads acceleration data, computes the magnitude, and logs impacts exceeding the 2g threshold. It also handles errors, gracefully shuts down on SIGINT, and uses modern libraries (pigpio).

code:
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <time.h>
#include <sys/mman.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <sys/stat.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define SA0_GPIO 17
#define SA0_ACTIVE_LOW
#define LOG_FILE "gyro_log.txt"
#define SAMPLES_PER_SEC 20
#define SAMPLES_PER_PERIOD (1000 / SAMPLES_PER_SEC)
#define FS_DPS 250.0
#define SENSITIVITY 0.00875

struct gyro_data {
    time_t timestamp;
    int16_t x, y, z;
};

void setup_gpio(gpiod_line_request_data_t *request_data) {
    gpiod_line_request_dt_set_consumer_label(request_data, "GY-50 SA0");
    gpiod_line_request_dt_set_consumer_name(request_data, "gyro");
    gpiod_line_request_dt_set_direction(request_data, GPIOD_LINE_REQ_DIR_IN);
    gpiod_line_request_dt_set_active_low(request_data, SA0_ACTIVE_LOW);
    gpiod_line_request_dt_set_debounce(request_data, 10);
}

int init_i2c(int bus, int addr) {
    int file = open("/dev/i2c-" + std::to_string(bus), O_RDWR);
    if (file < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(file, I2C_SLAVE, addr) < 0) {
        perror("Failed to acquire bus access");
        close(file);
        return -1;
    }

    return file;
}

int write_reg(int file, uint8_t reg, uint8_t value) {
    uint8_t data[2] = {reg, value};
    if (write(file, data, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

int read_reg(int file, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(file, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    if (read(file, buf, len) != (int)len) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int check_who_am_i(int file) {
    uint8_t buf[1];
    if (read_reg(file, 0x0F, buf, 1) < 0) {
        return -1;
    }

    if (buf[0] != 0xD3) {
        fprintf(stderr, "Sensor not found (WHO_AM_I = 0x%02X)\n", buf[0]);
        return -1;
    }

    return 0;
}

void calibrate(struct gyro_data *data, size_t samples) {
    int i;
    double x_offset = 0.0, y_offset = 0.0, z_offset = 0.0;

    for (i = 0; i < samples; ++i) {
        if (read_gyro_data(data) < 0) {
            break;
        }

        x_offset += data->x;
        y_offset += data->y;
        z_offset += data->z;
    }

    x_offset /= samples;
    y_offset /= samples;
    z_offset /= samples;

    fprintf(stderr, "Calibrated zero-rate offsets: X=%.3f dps, Y=%.3f dps, Z=%.3f dps\n", x_offset, y_offset, z_offset);
}

int read_gyro_data(struct gyro_data *data) {
    uint8_t buf[6];
    if (read_reg(data->file, 0x28, buf, 6) < 0) {
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]) * SENSITIVITY - data->x_offset;
    data->y = (int16_t)((buf[2] << 8) | buf[3]) * SENSITIVITY - data->y_offset;
    data->z = (int16_t)((buf[4] << 8) | buf[5]) * SENSITIVITY - data->z_offset;

    data->timestamp = time(NULL);

    return 0;
}

void log_gyro_data(struct gyro_data *data) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    char timestamp_str[32];
    ctime_r(&data->timestamp, timestamp_str);
    timestamp_str[strlen(timestamp_str) - 1] = '\0';

    fprintf(file, "%s X=%.3f dps Y=%.3f dps Z=%.3f dps\n", timestamp_str, data->x, data->y, data->z);
    fclose(file);
}

void handle_signal(int signum) {
    fprintf(stderr, "Exiting...\n");
    gpiod_line_release(data.sa0_line);
    close(data.file);
    fclose(data.log_file);
    exit(0);
}

int main() {
    struct gyro_data data = {0};
    int i2c_file = -1;
    FILE *log_file = NULL;
    gpiod_line_data_t sa0_line;
    gpiod_line_request_data_t sa0_request_data = GPIOD_LINE_REQUEST_DATA_INITIALIZER;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_get_array_size() < SA0_GPIO) {
        fprintf(stderr, "GPIO number %d not found\n", SA0_GPIO);
        return 1;
    }

    data.sa0_line = gpiod_get_line_byname("gpio" + std::to_string(SA0_GPIO));
    if (!data.sa0_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    setup_gpio(&sa0_request_data);
    gpiod_line_request_func(data.sa0_line, &setup_gpio, &sa0_request_data);
    gpiod_line_request(data.sa0_line, &sa0_request_data);
    gpiod_line_set_value(data.sa0_line, 1);

    i2c_file = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_file < 0) {
        return 1;
    }

    if (check_who_am_i(i2c_file) < 0) {
        return 1;
    }

    if (write_reg(i2c_file, 0x20, 0x0F) < 0) {
        perror("Failed to write to CTRL_REG1");
        goto cleanup;
    }

    if (write_reg(i2c_file, 0x23, 0x00) < 0) {
        perror("Failed to write to CTRL_REG4");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to create log file");
        goto cleanup;
    }

    calibrate(&data, 100);

    struct timespec period = {0, SAMPLES_PER_PERIOD * 1000000};
    while (1) {
        nanosleep(&period, NULL);

        if (read_gyro_data(&data) < 0) {
            continue;
        }

        if (data.x > 50.0 || data.y > 50.0 || data.z > 50.0) {
            fprintf(stderr, "Warning: Axis exceeded 50 dps\n");
            log_gyro_data(&data);
        }

        log_gyro_data(&data);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }

    gpiod_line_release(data.sa0_line);
    close(i2c_file);

    return 0;
}

