    }

    data.sa0_line = gpiod_get_line_byname("gpio" + std::to_string(SA0_GPIO));
    if (!data.sa0_line) {
        perror("Failed to get GPIO line");
        return 1;
    }

    setup_gpio(&sa0_request_data);
    gpiod_line_request_func(data.sa0_line, &setup_gpio, &sa0_request_data);
    gpiod_line_request(data.sa0_line, &sa0_request_data);
    gpiod_line_set_value(data.sa0_line, 1);

    i2c_file = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_file < 0) {
        return 1;
    }

    if (check_who_am_i(i2c_file) < 0) {
        return 1;
    }

    if (write_reg(i2c_file, 0x20, 0x0F) < 0) {
        perror("Failed to write to CTRL_REG1");
        goto cleanup;
    }

    if (write_reg(i2c_file, 0x23, 0x00) < 0) {
        perror("Failed to write to CTRL_REG4");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to create log file");
        goto cleanup;
    }

    calibrate(&data, 100);

    struct timespec period = {0, SAMPLES_PER_PERIOD * 1000000};
    while (1) {
        nanosleep(&period, NULL);

        if (read_gyro_data(&data) < 0) {
            continue;
        }

        if (data.x > 50.0 || data.y > 50.0 || data.z > 50.0) {
            fprintf(stderr, "Warning: Axis exceeded 50 dps\n");
            log_gyro_data(&data);
        }

        log_gyro_data(&data);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }

    gpiod_line_release(data.sa0_line);
    close(i2c_file);

    return 0;
}
