#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATAX0 0x32
#define GPIO_LED 17

static const char *LOG_FILE = "accel_log.txt";

void log_data(double x, double y, double z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    char timestamp_str[32];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp_str, x, y, z);
    fclose(log_file);
}

int read_adxl345(int fd, uint8_t *buf, size_t len) {
    int ret = i2c_read_i2c_block_data(fd, 0, len, buf);
    if (ret < 0) {
        perror("Failed to read from ADXL345");
        return -1;
    }
    return ret;
}

void check_device_id(int fd) {
    uint8_t devid[1];
    if (read_adxl345(fd, devid, 1) != 1 || devid[0] != 0xE5) {
        fprintf(stderr, "Invalid DEVID 0x%02X, check the ADXL345 address\n", devid[0]);
        exit(1);
    }
}

void configure_adxl345(int fd) {
    uint8_t data[4];

    // Power control (0x2D)
    data[0] = 0x08; // Measurement range: ±2g
    data[1] = 0x06; // Data rate: 100Hz
    data[2] = 0x00; // Power control: Measurement enabled, self-test disabled
    if (write_i2c_block_data(fd, 0x2D, 3, data) != 3) {
        perror("Failed to write to ADXL345");
        exit(1);
    }

    // Data format (0x31)
    data[0] = 0x08; // Full-resolution
    if (write_i2c_block_data(fd, 0x31, 1, data) != 1) {
        perror("Failed to write to ADXL345");
        exit(1);
    }
}

int main(void) {
    int i2c_bus = 1;
    int i2c_fd = -1;
    int gpio_led = -1;

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(1);
    }

    i2c_fd = pigpio_i2c_open(i2c_bus, ADXL345_I2C_ADDR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    if (gpio_led = gpioInitialise(GPIO_LED) < 0) {
        perror("Failed to initialize GPIO");
        goto cleanup;
    }

    if (i2c_fd = pigpio_i2c_open(i2c_bus, ADXL345_I2C_ADDR) < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    check_device_id(i2c_fd);
    configure_adxl345(i2c_fd);

    double last_x = 0.0, last_y = 0.0, last_z = 0.0;
    double x, y, z;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_sec += 100 * ts.tv_nsec / 1_ billion;
    ts.tv_nsec = (100 * ts.tv_nsec) % 1_ billion;
    while (1) {
        if (read_adxl345(i2c_fd, (uint8_t *)&x, 2) != 2 ||
            read_adxl345(i2c_fd, (uint8_t *)&y, 2) != 2 ||
            read_adxl345(i2c_fd, (uint8_t *)&z, 2) != 2) {
            perror("Failed to read from ADXL345");
            continue;
        }

        x = (x * 16.384) / 32768;
        y = (y * 16.384) / 32768;
        z = (z * 16.384) / 32768;

        if (fabs(x - last_x) > 2.0 || fabs(y - last_y) > 2.0 || fabs(z - last_z) > 2.0) {
            gpioWrite(gpio_led, 1);
        } else {
            gpioWrite(gpio_led, 0);
        }

        log_data(x, y, z);
        last_x = x;
        last_y = y;
        last_z = z;

        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_sec += 100 * ts.tv_nsec / 1_ billion;
        ts.tv_nsec = (100 * ts.tv_nsec) % 1_ billion;
        usleep((ts.tv_sec - ts.tv_nsec / 1_ billion) * 1_ million);
    }

cleanup:
    if (gpio_led >= 0) gpioTerminate();
    if (i2c_fd >= 0) pigpio_i2c_close(i2c_fd);

    signal(SIGINT, [](int signum) {
        fprintf(stderr, "Received SIGINT, exiting gracefully\n");
        goto cleanup;
    });

    signal(SIGTERM, [](int signum) {
        fprintf(stderr, "Received SIGTERM, exiting gracefully\n");
        goto cleanup;
    });

    return 0;
}

