#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ACC_ADDR 0x19
#define MAG_ADDR 0x1E
#define ACC_CTRL_REG1_A 0x20
#define ACC_OUT_X_L_A 0x28
#define ACC_OUT_X_H_A (ACC_OUT_X_L_A + 1)
#define ACC_OUT_Y_L_A (ACC_OUT_X_L_A + 2)
#define ACC_OUT_Y_H_A (ACC_OUT_X_H_A + 1)
#define ACC_OUT_Z_L_A (ACC_OUT_Y_L_A + 2)
#define ACC_OUT_Z_H_A (ACC_OUT_Y_H_A + 1)
#define MAG_MR_REG_M 0x02
#define MAG_OUT_X_H_M 0x03
#define MAG_OUT_Y_H_M (MAG_OUT_X_H_M + 1)
#define MAG_OUT_Z_H_M (MAG_OUT_Y_H_M + 1)

static const char *log_file = "compass_log.txt";

void i2c_write_reg(int bus, int addr, int reg, int value) {
    if (i2c_master_write_read(bus, (char *)&addr, 1, (char *)&value, 0) < 0) {
        perror("i2c_master_write_read");
        exit(EXIT_FAILURE);
    }
    if (i2c_master_write_read(bus, (char *)&reg, 1, NULL, 0) < 0) {
        perror("i2c_master_write_read");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_reg(int bus, int addr, int reg, int len, char *buf) {
    if (i2c_master_write_read(bus, (char *)&addr, 1, (char *)&reg, 0) < 0) {
        perror("i2c_master_write_read");
        exit(EXIT_FAILURE);
    }
    if (i2c_master_read(bus, buf, len) != len) {
        perror("i2c_master_read");
        exit(EXIT_FAILURE);
    }
}

double get_heading(int16_t acc_x, int16_t acc_y, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    double roll, pitch, heading;

    // Calculate roll and pitch
    roll = atan2((double)acc_y, sqrt(acc_x * acc_x + acc_z * acc_z)) * 180 / M_PI;
    pitch = atan2((double)acc_x, sqrt(acc_y * acc_y + acc_z * acc_z)) * 180 / M_PI;

    // Calculate heading
    heading = atan2((double)mag_y * cos(roll * M_PI / 180) + mag_z * sin(roll * M_PI / 180),
                    mag_x * cos(pitch * M_PI / 180)) * 180 / M_PI;

    // Adjust for magnetic declination (assuming 5 degrees)
    heading -= 5;

    // Normalize heading (0 to 360)
    if (heading < 0)
        heading += 360;

    return heading;
}

int main(void) {
    int bus = pi_open(I2C_BUS, 0);
    if (bus < 0) {
        perror("pi_open");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    i2c_write_reg(bus, ACC_ADDR, ACC_CTRL_REG1_A, 0x27);
    usleep(100000); // Delay for sensor to initialize
    i2c_write_reg(bus, MAG_ADDR, MAG_MR_REG_M, 0x00);

    FILE *log_file_ptr = fopen(log_file, "a");
    if (log_file_ptr == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    if (fprintf(log_file_ptr, "Timestamp,Heading,AccX,AccY,AccZ,MagX,MagY,MagZ\n") < 0) {
        perror("fprintf");
        exit(EXIT_FAILURE);
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

    while (1) {
        char acc_data[6];
        char mag_data[3];

        i2c_read_reg(bus, ACC_ADDR, ACC_OUT_X_L_A, 6, acc_data);
        i2c_read_reg(bus, MAG_ADDR, MAG_OUT_X_H_M, 3, mag_data);

        int16_t acc_x = (acc_data[0] << 8) | acc_data[1];
        int16_t acc_y = (acc_data[2] << 8) | acc_data[3];
        int16_t acc_z = (acc_data[4] << 8) | acc_data[5];

        int16_t mag_x = (mag_data[0] << 8) | mag_data[1];
        int16_t mag_y = (mag_data[2] << 8) | mag_data[3];
        int16_t mag_z = 0; // Assuming Z-axis is not used in this example

        double heading = get_heading(acc_x, acc_y, mag_x, mag_y, mag_z);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1000000;

        if (fprintf(log_file_ptr, "%lld,%f,%d,%d,%d,%d,%d,%d\n", timestamp, heading, acc_x, acc_y, acc_z, mag_x, mag_y, mag_z) < 0) {
            perror("fprintf");
            exit(EXIT_FAILURE);
        }

        usleep(100000); // Sample every 100 ms
    }

    fclose(log_file_ptr);
    gpioTerminate();
    pi_close(bus);

    return 0;
}

