#define I2C_BUS 1
#define VL6180X_ADDR 0x29
#define RANGE_STATUS_REG 0x04D
#define SAMPLE_INTERVAL_MS 100

char *log_file = "distance_log.txt";

void log_timestamped_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: DOOR_%s (distance: %d mm)\n", time_string,
            distance < 100 ? "OPEN" : "CLOSED", distance);

    FILE *log_file_ptr = fopen(log_file, "a");
    if (log_file_ptr) {
        fprintf(log_file_ptr, "%s: DOOR_%s (distance: %d mm)\n", time_string,
                distance < 100 ? "OPEN" : "CLOSED", distance);
        fclose(log_file_ptr);
    }
}

