        perror("i2cWriteReadRegister16");
        i2cClose(I2C_BUS, VL6180X_ADDR);
        gpioTerm();
        return -1;
    }

    if (i2cWriteReadRegister16(I2C_BUS, VL6180X_ADDR, 0x043, 0x0000) < 0) {
        perror("i2cWriteReadRegister16");
        i2cClose(I2C_BUS, VL6180X_ADDR);
        gpioTerm();
        return -1;
    }

    if (i2cWriteReadRegister16(I2C_BUS, VL6180X_ADDR, 0x044, 0x0000) < 0) {
        perror("i2cWriteReadRegister16");
        i2cClose(I2C_BUS, VL6180X_ADDR);
        gpioTerm();
        return -1;
    }

    if (i2cWriteReadRegister16(I2C_BUS, VL6180X_ADDR, 0x045, 0x0000) < 0) {
        perror("i2cWriteReadRegister16");
        i2cClose(I2C_BUS, VL6180X_ADDR);
        gpioTerm();
        return -1;
    }

    if (i2cWriteReadRegister16(I2C_BUS, VL6180X_ADDR, 0x046, 0x0000) < 0) {
