    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if ((i2c_fd = i2cOpen(I2C_BUS, VL6180X_ADDR)) < 0) {
        perror("i2cOpen");
        gpioTerm();
        return 1;
    }

    if (init_sensor() < 0) {
        gpioTerm();
        return 1;
    }

    while (1) {
        if (i2cWriteReadRegister16(I2C_BUS, VL6180X_ADDR, RANGE_STATUS_REG, 0) < 0) {
            perror("i2cWriteReadRegister16");
            i2cClose(I2C_BUS, VL6180X_ADDR);
            gpioTerm();
            break;
