```

Don't forget to connect the VL6180X sensor to the Raspberry Pi's I2C bus 1 (SDA and SCL pins) and power it accordingly.

This code assumes that the Raspberry Pi has the I2C bus enabled and the correct I2C address (0x3F) is set in the boot configuration. If not, you may need to modify the I2C_BUS and VL6180X_ADDR constants accordingly.

code:
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define REG_CTRL 0x00
#define REG_DATA 0x01
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static pthread_t thread_id;
static FILE *log_file;
static int i2c_file_desc[2];

void sigint_handler(int signum) {
    printf("\nExiting...\n");
    close(i2c_file_desc[0]);
    close(i2c_file_desc[1]);
    gpioTerm();
    fclose(log_file);
    pthread_exit(NULL);
}

int init_i2c(int addr) {
    int ret = -1;
    if ((i2c_file_desc[addr] = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return ret;
    }

    if (i2c_master_setup(i2c_file_desc[addr], addr << 1, 100000) < 0) {
        perror("Failed to setup I2C master");
        close(i2c_file_desc[addr]);
        return ret;
    }

    ret = 0;
    return ret;
}

int read_sensor(int addr) {
    int ret = -1;
    uint16_t data = 0;

    if (i2c_master_write_read(i2c_file_desc[addr], REG_CTRL, &data, 1, REG_DATA, &data, 2) < 0) {
        perror("Failed to read sensor data");
        return ret;
    }

    ret = data;
    return ret;
}

void log_data(struct timespec timestamp, int sensor1, int sensor2, int tdoa) {
    char line[256];
    snprintf(line, sizeof(line), "%lld.%09ld,%d,%d,%d,%d\n", timestamp.tv_sec, timestamp.tv_nsec, sensor1, sensor2, tdoa, sensor1 - sensor2);
    fputs(line, log_file);
}

void *sample_and_log(void *arg) {
    int sensor1, sensor2, tdoa;
    struct timespec timestamp;

    while (1) {
        if (init_i2c(0) && init_i2c(1)) {
            sensor1 = read_sensor(0);
            sensor2 = read_sensor(1);

            if (sensor1 >= 0 && sensor2 >= 0) {
                clock_gettime(CLOCK_REALTIME, &timestamp);
                tdoa = sensor1 - sensor2;
                log_data(timestamp, sensor1, sensor2, tdoa);
            }
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    return NULL;
}

int main() {
    int ret = -1;

    signal(SIGINT, sigint_handler);

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    if (pigpio_quickstart() < 0) {
        perror("Failed to start pigpio");
        goto cleanup;
    }

    if (pthread_create(&thread_id, NULL, sample_and_log, NULL) != 0) {
        perror("Failed to create sample thread");
        goto cleanup;
    }

    pthread_join(thread_id, NULL);

    ret = 0;

cleanup:
    gpioTerm();
    return ret;
}

