#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUD_RATE 1000000
#define SPI_MODE 3
#define SPI_FLAGS (SPI_CPOL_HIGH | SPI_CPHA_1 | SPI_MODE_3 | SPI_NO_CS)
#define CE_GPIO 8
#define REG_X_GYRO 0x04
#define REG_Y_GYRO 0x06
#define REG_Z_GYRO 0x08
#define REG_X_ACCEL 0x0A
#define REG_Y_ACCEL 0x0C
#define REG_Z_ACCEL 0x0E
#define SENSITIVITY_GYRO 0.005
#define SENSITIVITY_ACCEL 0.00025
#define SAMPLE_INTERVAL 100
#define DUMMY_DELAY_US 40

static FILE *file;
static int spi_handle;

static void cleanup(int signum) {
    if (spi_handle != -1) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    if (file) {
        fclose(file);
        file = NULL;
    }

    gpioTerm();
    exit(signum);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if ((spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD_RATE, SPI_MODE, SPI_FLAGS)) < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        goto cleanup;
    }

    if ((file = fopen("imu_data.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        goto cleanup;
    }

    fprintf(file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    alarm(SAMPLE_INTERVAL / 1000.0);
    int running = 1;
    while (running) {
        uint16_t data[7];
        uint16_t gyro_x, gyro_y, gyro_z;
        uint16_t accel_x, accel_y, accel_z;

        // Send register address and read response
        if (spiXfer(spi_handle, &data[0], 2, &data[1], 4) < 0) {
            perror("spiXfer");
            continue;
        }

        // Dummy delay
        usleep(DUMMY_DELAY_US * 1000);

        // Read gyroscope data
        gyro_x = data[1] << 8 | data[2];
        gyro_y = data[3] << 8 | data[4];
        gyro_z = data[5] << 8 | data[6];

        // Read accelerometer data
        accel_x = data[1] << 8 | data[2];
        accel_y = data[3] << 8 | data[4];
        accel_z = data[5] << 8 | data[6];

        // Convert and log the data
        time_t timestamp = time(NULL);
