#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define CS_GPIO 8
#define MODE_3 3
#define MAX_SPEED_HZ 1000000
#define DELAY_MS 100
#define SCALE_GYRO 0.02
#define SCALE_ACCEL 0.00025

int spi_fd;
struct spi_ioc_transfer transfers[8];
gpiod_line_request_lines_data lines_data = {0};
gpiod_line_request *line_request;

void spi_init() {
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Can't open spi device");
        exit(EXIT_FAILURE);
    }

    struct spi_device_interface spi_interface = {
        .mode = MODE_3,
        .max_speed_hz = MAX_SPEED_HZ,
        .bits_per_word = 16,
    };

    if (ioctl(spi_fd, SPI_IOC_WRITE_INTERFACE, &spi_interface) < 1) {
        perror("Can't set spi mode");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    line_request = gpiod_chip_get_line_request_array(gpiod_chip_open_with_label("gpiochip0", "rpi-gpio"), &lines_data, GPIOD_LINE_REQUEST_ARRAY_SIZE);

    if (!line_request) {
        perror("Can't get line request");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_enable_line(line_request[CS_GPIO], GPIOD_LINE_REQUEST_ENABLE_ACTIVE_LOW);
    gpiod_line_request_set_debounce(line_request[CS_GPIO], 10);
    gpiod_line_request_set_direction(line_request[CS_GPIO], GPIOD_LINE_REQUEST_DIRECTION_OUT);
    gpiod_line_request_set_value(line_request[CS_GPIO], 1);
}

void spi_transfer(uint16_t addr, uint16_t *data) {
    transfers[0].tx_buf = &addr;
    transfers[0].len = 2;
    transfers[1].rx_buf = data;
    transfers[1].len = 2;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 0) {
        perror("Can't transfer data");
        exit(EXIT_FAILURE);
    }
}

float read_sensor(uint16_t reg) {
    uint16_t data[2];
    spi_transfer(reg | 0x80, data);
    return (data[0] & 0xFF) * SCALE_GYRO * (reg == 0x04 || reg == 0x0A) +
           (data[1] & 0xFF) * SCALE_GYRO * (reg == 0x06 || reg == 0x0C || reg == 0x0E) +
           (data[0] >> 8) * SCALE_ACCEL * (reg == 0x0A || reg == 0x0C || reg == 0x0E) +
           (data[1] >> 8) * SCALE_ACCEL * (reg == 0x06 || reg == 0x08 || reg == 0x0E);
}

void log_data(float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    printf("Gyroscope: X=%.3f, Y=%.3f, Z=%.3f\n", gyro_x, gyro_y, gyro_z);
    printf("Accelerometer: X=%.6f, Y=%.6f, Z=%.6f\n", accel_x, accel_y, accel_z);
}

void sigint_handler(int signum) {
    close(spi_fd);
    gpiod_line_release(line_request[CS_GPIO]);
    gpiod_chip_close(line_request->chip);
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    spi_init();
    gpio_init();

    while (1) {
        float gyro_x = read_sensor(0x04);
        float gyro_y = read_sensor(0x06);
        float gyro_z = read_sensor(0x08);
        float accel_x = read_sensor(0x0A);
        float accel_y = read_sensor(0x0C);
        float accel_z = read_sensor(0x0E);

        log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        usleep(DELAY_MS * 1000);
    }

    return 0;
}

