#include <stdio.h>
#include <stdint.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define MPU_6886_ADDR 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACC_DATA_REG 0x3B
#define GYRO_DATA_REG 0x43

int main() {
    int fd, ret;
    char bus_num;
    char *dev_name;
    char buf[2];
    int i;

    // Get I2C bus number
    bus_num = I2C_BUS;
    dev_name = sprintf(NULL, "/dev/i2c-%d", bus_num);
    fd = open(dev_name, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Check if the sensor is present
    if (ioctl(fd, I2C_SLAVE, MPU_6886_ADDR) < 0) {
        perror("Failed to talk to slave");
        close(fd);
        return 1;
    }

    buf[0] = WHO_AM_I_REG;
    ret = write(fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write to slave");
        close(fd);
        return 1;
    }

    ret = read(fd, buf, 1);
    if (ret != 1) {
        perror("Failed to read from slave");
        close(fd);
        return 1;
    }

    if (buf[0] != 0x86) {
        printf("Wrong sensor ID, expected 0x86, got 0x%02X\n", buf[0]);
        close(fd);
        return 1;
    }

    // Initialize the sensor
    buf[0] = PWR_MGMT_1_REG;
    buf[1] = 0x00;
    ret = write(fd, buf, 2);
    if (ret != 2) {
        perror("Failed to write to slave");
        close(fd);
        return 1;
    }

    buf[0] = ACCEL_CONFIG_REG;
    buf[1] = 0x00;
    ret = write(fd, buf, 2);
    if (ret != 2) {
        perror("Failed to write to slave");
        close(fd);
        return 1;
    }

    buf[0] = GYRO_CONFIG_REG;
    buf[1] = 0x00;
    ret = write(fd, buf, 2);
    if (ret != 2) {
        perror("Failed to write to slave");
        close(fd);
        return 1;
    }

    // Main loop
    while (1) {
        usleep(50000); // 50 ms delay

        // Read accelerometer data
        buf[0] = ACC_DATA_REG;
        ret = read(fd, buf + 1, 7);
        if (ret < 7) {
            if (errno == EAGAIN || errno == EBUSY) {
                continue;
            }
            perror("Failed to read from slave");
            close(fd);
            return 1;
        }

        int16_t acc_x = (buf[1] << 8) | buf[0];
        int16_t acc_y = (buf[3] << 8) | buf[2];
        int16_t acc_z = (buf[5] << 8) | buf[4];

        // Read gyroscope data
        buf[0] = GYRO_DATA_REG;
        ret = read(fd, buf + 1, 6);
        if (ret < 6) {
            if (errno == EAGAIN || errno == EBUSY) {
                continue;
            }
            perror("Failed to read from slave");
            close(fd);
            return 1;
