#include <unistd.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define ADXL345_I2C_ADDR 0x53
#define ADXL345_REG_ID 0x00
#define ADXL345_REG_DATA_X_LSB 0x32
#define ADXL345_REG_DATA_Y_LSB 0x34
#define ADXL345_REG_DATA_Z_LSB 0x36
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"
#define SAMPLE_INTERVAL_US 10000
#define IMPACT_THRESHOLD 2.5
#define LED_ON_MS 500

int init_i2c(int bus, uint16_t addr) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }

    if (i2cOpen(bus, &addr, 0) < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    return 0;
}

int read_adxl345(int16_t *x, int16_t *y, int16_t *z) {
    int ret;
    uint8_t data[6];

    ret = i2cReadRegisters(bus, ADXL345_REG_DATA_X_LSB, 6, data);
    if (ret < 0) {
        perror("Failed to read data from ADXL345");
        return -1;
    }

    *x = (data[1] << 8) | data[0];
    *y = (data[3] << 8) | data[2];
    *z = (data[5] << 8) | data[4];

    return 0;
}

void write_adxl345(uint8_t reg, uint8_t value) {
    if (i2cWriteRead(bus, ADXL345_REG_ID, &reg, 1, &value, 0) < 0) {
        perror("Failed to write to ADXL345");
    }
}

void setup_adxl345() {
    write_adxl345(0x2C, 0x08); // Power control, set to 0010 (measurement mode)
    write_adxl345(0x2D, 0x08); // Data rate, set to 0010 (100 Hz)
    write_adxl345(0x20, 0x00); // Data format, set to 0000 (full-resolution, +-2g)
}

void setup_led(int gpio) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
}

void log_impact(double magnitude, int16_t x, int16_t y, int16_t z) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, %f, %d, %d, %d\n", timestamp, magnitude, x, y, z);
    fclose(log_file);
}

void handle_impact(int16_t x, int16_t y, int16_t z) {
    double magnitude = sqrt(pow(x, 2) + pow(y, 2) + pow(z, 2)) / 256.0;

    if (magnitude > IMPACT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
        usleep(LED_ON_MS * 1000);
        gpioWrite(LED_GPIO, 0);
        log_impact(magnitude, x, y, z);
    }
}

int main() {
    int bus = 1;
    int16_t x, y, z;
    int ret;

    if (init_i2c(bus, ADXL345_I2C_ADDR) < 0) {
        return 1;
    }

    if (read_adxl345(&x, &y, &z) < 0 || read_adxl345(&x, &y, &z) < 0) {
        perror("Failed to read device ID from ADXL345");
        return 1;
    }

    if (x != 0xE5) {
        fprintf(stderr, "Invalid device ID from ADXL345\n");
        return 1;
    }

    setup_adxl345();
    setup_led(LED_GPIO);

    while (1) {
        if (read_adxl345(&x, &y, &z) < 0) {
            perror("Failed to read data from ADXL345");
            continue;
        }

        handle_impact(x, y, z);
        usleep(SAMPLE_INTERVAL_US);
    }

    i2cClose(bus);
    gpioTerm();

    return 0;
}

