void log_imu_data(const char *tag, const uint8_t *data) {
    static FILE *file = NULL;
    static int first_write = 1;
    time_t now;
    char timestamp[20];

    if (!file) {
        file = fopen(csv_file, "w");
        if (!file) {
            perror("Failed to open CSV file");
            exit(EXIT_FAILURE);
        }
    }

    if (first_write) {
        first_write = 0;
        fprintf(file, "Time,%s_x,%s_y,%s_z\n", tag, tag, tag);
    }

    now = time(NULL);
    ctime_r(&now, timestamp);
    timestamp[strlen(timestamp) - 1] = '\0';
    fprintf(file, "%s,%d,%d,%d\n", timestamp, data[0], data[1], data[2]);
}

int main(void) {
    int i2c_fd, ret;
    uint8_t who_am_i;
    uint8_t data[BUFFER_SIZE];

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        goto cleanup_pigpio;
    }

    ret = i2cWriteReadRegister16(i2c_fd, WHO_AM_I_REG, 0, 1, &who_am_i, 1);
    if (ret < 0 || who_am_i != 0x12) {
        perror("Failed to communicate with the sensor or incorrect WHO_AM_I");
        goto cleanup_i2c;
    }

    ret = i2cWriteReadRegister8(i2c_fd, 0x6B, ACCEL_CONFIG, 0, NULL, 0);
    if (ret < 0) {
        perror("Failed to set accelerometer configuration");
        goto cleanup_i2c;
    }

    ret = i2cWriteReadRegister8(i2c_fd, 0x1B, GYRO_CONFIG, 0, NULL, 0);
    if (ret < 0) {
        perror("Failed to set gyroscope configuration");
        goto cleanup_i2c;
    }

    while (1) {
        ret = i2cReadI2CBlockData(i2c_fd, ACCEL_DATA_START, 6, data + ACCEL_DATA_START - ACCEL_DATA_START);
        if (ret != 6) {
            perror("Failed to read accelerometer data");
            continue;
        }

        ret = i2cReadI2CBlockData(i2c_fd, GYRO_DATA_START, 6, data + GYRO_DATA_START - GYRO_DATA_START);
        if (ret != 6) {
            perror("Failed to read gyroscope data");
            continue;
        }

        log_imu_data("accel", data + ACCEL_DATA_START);
        log_imu_data("gyro", data + GYRO_DATA_START);

        usleep(100000);
    }

cleanup_i2c:
    pigpio_i2cClose(i2c_fd);

cleanup_pigpio:
    gpioTerm();

    return 0;
}

