#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define ACC_ADDR 0x1D
#define LED_GPIO 17
#define THRESHOLD 2.0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "impact_log.txt"

int i2c_fd;
struct gpiod_line *led_line;

void i2c_init() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    if ((i2c_fd = open(i2c_dev, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ACC_ADDR) < 0) {
        perror("Failed to acquire I2C bus");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    struct gpiod_chip *chip;
    struct gpiod_line_request_data request_data;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    request_data.consumer_data = NULL;
    request_data.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    if (gpiod_chip_claim_line(chip, LED_GPIO, &request_data, &led_line) < 0) {
        perror("Failed to claim GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(led_line, 0);
}

uint8_t read_reg(uint8_t reg) {
    uint8_t data;
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, &data, 1) != 1) {
        perror("Failed to read from I2C device");
        exit(EXIT_FAILURE);
    }

    return data;
}

void write_reg(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        exit(EXIT_FAILURE);
    }
}

bool check_sensor_id() {
    return read_reg(0x0D) == 0x1A;
}

void log_impact(time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    char timestamp_str[20];
