#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define ADXL345_I2C_ADDR 0x53
#define GPIO_LINE_INT 17

static const char *i2c_dev_name = "/dev/i2c-1";
static const char *gpio_line_name = "gpiochip0\0gpiochip1\0gpiochip2\0gpiochip3\0gpiochip4\0gpiochip5\0gpiochip6\0gpiochip7\0gpiochip8\0gpiochip9\0gpiochip10\0gpiochip11\0gpiochip12\0gpiochip13\0gpiochip14\0gpiochip15\0gpiochip16\0gpiochip17\0gpiochip18\0gpiochip19\0gpiochip20\0gpiochip21\0gpiochip22\0gpiochip23\0gpiochip24\0gpiochip25\0gpiochip26\0gpiochip27\0gpiochip28\0gpiochip29\0gpiochip30\0gpiochip31";

int i2c_fd, gpio_fd;
struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[1];
};

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int open_i2c_dev() {
    i2c_fd = open(i2c_dev_name, O_RDWR);
    if (i2c_fd < 0) {
        die("Failed to open I2C device");
    }

    return i2c_fd;
}

int open_gpio_line(int line) {
    gpio_fd = gpiod_open_name_with_label(gpio_line_name, line);
    if (gpio_fd < 0) {
        die("Failed to open GPIO line");
    }

    gpiod_line_request_dt(gpio_fd, GPIOD_LINE_REQUEST_DIRECTION_IN, "adxl345_int");

    return gpio_fd;
}

void close_i2c_dev() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void close_gpio_line() {
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_fd);
        gpiod_close(gpio_fd);
        gpio_fd = -1;
    }
}

int read_reg(uint8_t reg) {
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg = {
        .addr = ADXL345_I2C_ADDR << 1,
        .flags = 0,
        .len = 1,
        .buf = &reg,
    };
    char buf[1];

    data.msgs[0] = msg;
    data.msgs[0].len = 1;
    data.msgs[0].buf = buf;

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        die("Failed to read register");
    }

    return buf[0];
}

void write_reg(uint8_t reg, uint8_t value) {
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msg = {
        .addr = ADXL345_I2C_ADDR << 1,
        .flags = 0,
        .len = 2,
        .buf = malloc(2),
    };

    if (!msg.buf) {
        die("Failed to allocate buffer");
    }

    msg.buf[0] = reg;
    msg.buf[1] = value;

    data.msgs[0] = msg;
    data.msgs[0].len = 2;

    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        die("Failed to write register");
    }

    free(msg.buf);
}

int check_device_id() {
    return read_reg(0x00) == 0xE5;
}

void configure_adxl345() {
    write_reg(0x2D, 0x08); // Power Control
    write_reg(0x2E, 0x02); // Interrupt Enable
    write_reg(0x2F, 0x00); // Interrupt Map
    write_reg(0x31, 0x0A); // THRESH_FF
    write_reg(0x32, 0x20); // TIME_FF
}

