    FILE *log_file = fopen("freefall_log.csv", "a");
    if (!log_file) {
        die("Failed to open log file");
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file);
    fclose(log_file);
}

void handle_interrupt() {
    int16_t data[3];
    int i2c_ret;
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%03d",
             ts.tv_sec, ts.tv_nsec / 1000000, ts.tv_nsec % 1000000,
             ts.tv_nsec / 1000000, ts.tv_nsec / 100000 % 100,
             ts.tv_nsec / 1000 % 100, ts.tv_nsec % 1000);

    i2c_ret = read_i2c_block_data(i2c_fd, 0x32, sizeof(data));
    if (i2c_ret != sizeof(data)) {
        die("Failed to read data from ADXL345");
    }

    if ((read_reg(0x30) & 0x04) == 0x04) { // Check freefall bit
        log_data(timestamp, data[0], data[1], data[2]);
    }

    write_reg(0x30, read_reg(0x30) & ~0x04); // Clear interrupt
}

int main() {
    int i2c_fd, gpio_fd;

    if ((i2c_fd = open_i2c_dev()) < 0) {
        die("Failed to open I2C device");
    }

    if (!check_device_id()) {
        die("ADXL345 not found");
    }

    configure_adxl345();

    if ((gpio_fd = open_gpio_line(GPIO_LINE_INT)) < 0) {
        die("Failed to open GPIO line");
    }

    gpiod_line_request_dt(gpio_fd, GPIOD_LINE_REQUEST_EDGE_FALLING, "adxl345_int");

    struct pollfd poll_fds[1] = {
        { .fd = gpio_fd, .events = POLLIN }
    };

    while (1) {
        int poll_ret = poll(poll_fds, 1, -1);
        if (poll_ret < 0) {
            die("Failed to poll GPIO line");
        }

        if (poll_fds[0].revents & POLLIN) {
            handle_interrupt();
        }
    }

    close_i2c_dev();
    close_gpio_line();

    return 0;
}

