        return -1;
    }

    return 0;
}

int i2c_read_reg(int bus, int addr, int reg, uint16_t *value) {
    char data[2];

    if (gpio_i2c_read_polled(bus, addr, &data, 2, TIMEOUT_US) < 2) {
        perror("i2c_read_reg");
        return -1;
    }

