        perror("gpioInitialise");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (check_who_am_i(bus, IMU_ADDR) < 0) {
        gpioTerminate();
        return 1;
    }

    if (i2c_write_reg(bus, IMU_ADDR, 0x19, ACC_FS_2G | GYRO_FS_250DPS | ODR_104HZ) < 0) {
        perror("i2c_write_reg");
        gpioTerminate();
        return 1;
    }

    time_t last_state_change = 0;
    time_t current_timestamp;
    float acc_magnitude;
    uint16_t acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z;

    while (running) {
        current_timestamp = time(NULL);

        if (i2c_read_reg(bus, IMU_ADDR, ACC_X_REG, &acc_x) < 0 ||
            i2c_read_reg(bus, IMU_ADDR, ACC_Y_REG, &acc_y) < 0 ||
