            perror("i2c_read_reg");
            continue;
        }

        acc_magnitude = sqrt(acc_x * acc_x + acc_y * acc_y + acc_z * acc_z);

        if (acc_magnitude < FREEFALL_THRESHOLD) {
            if (last_state_change != 0 && current_timestamp - last_state_change < 1) {
                log_data("FREEFALL", acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z, current_timestamp);
            }
            last_state_change = current_timestamp;
        } else if (acc_magnitude > IMPACT_THRESHOLD) {
            if (last_state_change != current_timestamp) {
                log_data("IMPACT", acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z, current_timestamp);
            }
            last_state_change = current_timestamp;
        }
    }

    gpioTerminate();
    return 0;
}

