#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define CS_PIN GPIO8
#define X_GYRO_OUT_REG 0x14
#define SCALE_FACTOR 0.0305

static const char *csv_header = "timestamp,x_gyro_out\n";
FILE *log_file;

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int main(void) {
    if (gpioInitialise() < 0)
        die("Failed to initialise pigpio");

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0)
        die("Failed to set CS pin mode");

    gpioWrite(CS_PIN, 1);

    if (gpioSetMode(SPI_BUS, PI_MODE_0_3) < 0 ||
        gpioSetSpeed(SPI_BUS, 1000000) < 0 ||
        gpioSetChanAttr(SPI_DEVICE, GPIO_CF_SPISLOW, 0) < 0)
        die("Failed to configure SPI bus");

    if (gpioSPIWriteRead(SPI_DEVICE, 0x80 | X_GYRO_OUT_REG, NULL, 0) < 0)
        die("Failed to read WHO_AM_I register");

    uint16_t who_am_i = *((uint16_t *)(&gpioSPIWriteRead(SPI_DEVICE, 0, NULL, 0)));
    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "Wrong WHO_AM_I value: 0x%04X\n", who_am_i);
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen("gyro_log.csv", "w")) == NULL)
        die("Failed to open log file");

    fprintf(log_file, "%s", csv_header);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint16_t x_gyro_out;

    while (1) {
        gpioWrite(CS_PIN, 0);
        if (gpioSPIWriteRead(SPI_DEVICE, 0x80 | X_GYRO_OUT_REG, (uint8_t *)&x_gyro_out, 2) < 0)
            die("Failed to read X_GYRO_OUT register");
        gpioWrite(CS_PIN, 1);

        double x_gyro_rate = SCALE_FACTOR * x_gyro_out;

        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%lld,%f\n", ts.tv_sec * 1000 + ts.tv_nsec / 1000000, x_gyro_rate);

        usleep(10000);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

