#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 8.75
#define SAMPLE_INTERVAL 10000000 // 10 ms in nanoseconds
#define MAX_I2C_RETRIES 3

static int i2c_file;
static FILE *log_file;

void i2c_write_reg(uint8_t reg, uint8_t value) {
    for (int i = 0; i < MAX_I2C_RETRIES; ++i) {
        if (i2cWrite(i2c_file, (const uint8_t *)&reg, 1) != 1 ||
            i2cWrite(i2c_file, &value, 1) != 1) {
            if (i == MAX_I2C_RETRIES - 1) {
                fprintf(stderr, "I2C write failed\n");
                exit(1);
            }
            usleep(100000);
        } else {
            break;
        }
    }
}

uint8_t i2c_read_reg(uint8_t reg) {
    uint8_t data;
    if (i2cRead(i2c_file, &reg, 1) != 1 || i2cRead(i2c_file, &data, 1) != 1) {
        fprintf(stderr, "I2C read failed\n");
        exit(1);
    }
    return data;
}

void init_gyro() {
    if ((i2c_file = pigpio_open_wr(I2C_BUS, RPI_I2C_SLOW_MODE)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    if (i2c_read_reg(GYRO_ADDR) != 0x00) {
        fprintf(stderr, "GY-50 L3G4200D not found at 0x%02X\n", GYRO_ADDR);
        exit(1);
    }

    i2c_write_reg(CTRL_REG1, 0x0F); // Normal mode, all axes enabled
    i2c_write_reg(CTRL_REG4, 0x00); // +-250 dps full-scale range

    uint8_t who_am_i = i2c_read_reg(0x0F);
    if (who_am_i != 0xD3) {
        fprintf(stderr, "Invalid WHO_AM_I register value 0x%02X\n", who_am_i);
        exit(1);
    }
}

void log_sample(uint16_t x, uint16_t y, uint16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", time_str, x, y, z);
}

void sigint_handler(int signum) {
    if (signum == SIGINT) {
        close(i2c_file);
        fclose(log_file);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        perror("Failed to open gyro_log.csv");
        exit(1);
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");

    init_gyro();

    uint16_t x, y, z;
    uint8_t data[6];

    while (1) {
        if (i2cRead(i2c_file, data, 6) != 6) {
            fprintf(stderr, "I2C read failed\n");
            exit(1);
        }

        x = (data[1] << 8) | data[0];
        y = (data[3] << 8) | data[2];
        z = (data[5] << 8) | data[4];

        x /= 114.285;
        y /= 114.285;
        z /= 114.285;

        log_sample(x, y, z);
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

