    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: %s - %d\n", time_str, sensor_name, state);
}

void handle_interrupt(int sig) {
    gpiod_line_put_raw(sensor_1, 1);
    gpiod_line_put_raw(sensor_2, 1);
    fprintf(log_file, "Interrupted, conveyor halted\n");
    exit(0);
}

int main() {
    int ret;
    struct gpiod_chip *chip;

    signal(SIGINT, handle_interrupt);
    signal(SIGTERM, handle_interrupt);

    if ((chip = gpiod_chip_open(GPIO_CHIP_NAME)) == NULL) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    if ((sensor_1 = gpiod_chip_get_line(chip, SENSOR_1_LINE_REQUEST)) == NULL) {
        perror("Failed to get line request for sensor 1");
        exit(1);
    }

    if ((sensor_2 = gpiod_chip_get_line(chip, SENSOR_2_LINE_REQUEST)) == NULL) {
        perror("Failed to get line request for sensor 2");
        exit(1);
