    gpiod_line_request_enable(sensor_1, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_HIGH);
    gpiod_line_request_enable(sensor_2, GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING | GPIOD_LINE_REQUEST_ACTIVE_HIGH);

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    while (1) {
        int state_1 = gpiod_line_get_value(sensor_1);
        int state_2 = gpiod_line_get_value(sensor_2);

        if (state_1 == 1 && state_2 == 1) {
            fprintf(log_file, "Conveyor halted\n");
        }

        log_timestamped_state("Sensor 1", state_1);
        log_timestamped_state("Sensor 2", state_2);
        usleep(50000);
    }

    gpiod_line_release(sensor_1);
    gpiod_line_release(sensor_2);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
