#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1_REG 0x2A
#define DATA_REG_X 0x01
#define DATA_REG_Y 0x02
#define DATA_REG_Z 0x03
#define DATA_REG_TEMP 0x04
#define DATA_REG_STATUS 0x05
#define DATA_REG_INT_SOURCE 0x06

#define PI 3.14159265358979323846

static int i2c_fd;
static FILE *log_file;

static void i2c_init() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        exit(EXIT_FAILURE);
    }
}

static void i2c_deinit() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int read_reg(uint8_t reg) {
    uint8_t data[2];
    ssize_t bytes_read;

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write I2C register address");
        return -1;
    }

    if ((bytes_read = read(i2c_fd, data, 2)) != 2) {
        perror("Failed to read I2C register data");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

static void write_reg(uint8_t reg, uint16_t value) {
    uint8_t data[2];

    data[0] = reg;
    data[1] = value >> 8;
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write I2C register data");
    }

    data[0] = value;
    if (write(i2c_fd, data, 1) != 1) {
        perror("Failed to write I2C register data");
    }
}

static void sensor_init() {
    uint16_t ctrl_reg1 = read_reg(CTRL_REG1_REG);
    ctrl_reg1 &= ~(1 << 0);
    ctrl_reg1 |= (1 << 3) | (1 << 4) | (1 << 5);
    ctrl_reg1 |= (1 << 0);
    write_reg(CTRL_REG1_REG, ctrl_reg1);
}

static int check_sensor_id() {
    uint16_t id = read_reg(WHO_AM_I_REG);
    return id == 0x2A;
}

static void log_data(int16_t x, int16_t y, int16_t z) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);
}

static double atan2_scaled(double y, double x) {
    return atan2(y, x) * (180 / PI);
}

static void process_data() {
    int16_t x, y, z;
    uint16_t data[6];
    ssize_t bytes_read;

    if ((bytes_read = read(i2c_fd, data, 6)) != 6) {
        perror("Failed to read I2C data");
        return;
    }

    x = ((data[0] << 4) | (data[1] >> 4)) - 2048;
    y = ((data[2] << 4) | (data[3] >> 4)) - 2048;
    z = ((data[4] << 4) | (data[5] >> 4)) - 2048;

    double angle = atan2_scaled(y, x);
    if (fabs(angle) > 45.0) {
        log_data(x, y, z);
    }
}

int main() {
    i2c_init();

    if (!check_sensor_id()) {
        perror("Invalid sensor ID");
        i2c_deinit();
        exit(EXIT_FAILURE);
    }

    sensor_init();

    log_file = fopen("fall_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_deinit();
        exit(EXIT_FAILURE);
    }

    struct sigaction sa;
    sa.sa_handler = i2c_deinit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGINT/SIGTERM handler");
        i2c_deinit();
        exit(EXIT_FAILURE);
    }

    const int interval_us = 10000;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    ts.tv_nsec += interval_us * 1000;
    if (ts.tv_nsec >= 1000000000) {
        ts.tv_sec++;
        ts.tv_nsec -= 1000000000;
    }

    while (1) {
        nanosleep(&ts, &ts);
        process_data();
        clock_gettime(CLOCK_MONOTONIC, &ts);
        ts.tv_nsec += interval_us * 1000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
    }

    i2c_deinit();
    fclose(log_file);
    return 0;
}
