#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define LIS3MDL_ADDR 0x1E
#define LOG_FILE "magnetic_log.txt"
#define MAG_SENSITIVITY 0.146
#define MAG_THRESHOLD 800.0
#define MAX_RETRIES 3

int i2c_write_reg(int fd, unsigned char reg, unsigned char value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    return write(fd, buf, 2);
}

int i2c_read_reg(int fd, unsigned char reg, unsigned char *data, int len) {
    char buf[len + 1];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg: write");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("i2c_read_reg: read");
        return -1;
    }
    for (int i = 0; i < len; ++i) {
        data[i] = buf[i];
    }
    return len;
}

int init_sensor(int *fd) {
    int retries = MAX_RETRIES;
    int i2c_file;

    while (retries > 0) {
        i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR);
        if (i2c_file < 0) {
            perror("Failed to open I2C bus");
            --retries;
            continue;
        }

        if (ioctl(i2c_file, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            perror("Failed to acquire bus access");
            --retries;
            close(i2c_file);
            continue;
        }

        if (i2c_write_reg(i2c_file, 0x20, 0x70) < 0 ||
            i2c_write_reg(i2c_file, 0x21, 0x0C) ||
            i2c_write_reg(i2c_file, 0x22, 0x00)) {
            perror("Failed to write configuration");
            --retries;
            i2c_file = -1;
            continue;
        }

        unsigned char who_am_i;
        if (i2c_read_reg(i2c_file, 0x0F, &who_am_i, 1) != 1 || who_am_i != 0x3D) {
            perror("Wrong sensor ID");
            --retries;
            i2c_file = -1;
            continue;
        }

        *fd = i2c_file;
        return 0;
    }

    if (i2c_file >= 0) {
        close(i2c_file);
    }
    return -1;
}

void magnetic_field_to_mG(float *magnetic_field, unsigned char *data) {
    magnetic_field[0] = (data[1] | (data[0] << 8)) * MAG_SENSITIVITY;
    magnetic_field[1] = (data[3] | (data[2] << 8)) * MAG_SENSITIVITY;
    magnetic_field[2] = (data[5] | (data[4] << 8)) * MAG_SENSITIVITY;
}

void metal_detector_alert(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > MAG_THRESHOLD) {
        fprintf(stderr, "Metal detector alert: %f mG\n", magnitude);
    }
}

int main() {
    int i2c_file;
    int fd_log = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd_log < 0) {
        perror("Failed to open log file");
        return 1;
    }

    if (init_sensor(&i2c_file) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        goto cleanup;
    }

    float magnetic_field[3];
    unsigned char data[6];
    while (1) {
        if (i2c_read_reg(i2c_file, 0x28, data, 6) != 6) {
            perror("Failed to read data");
            continue;
        }

        magnetic_field_to_mG(magnetic_field, data);
        fprintf(fd_log, "%f,%f,%f\n", magnetic_field[0], magnetic_field[1], magnetic_field[2]);
        fflush(fd_log);

        metal_detector_alert(magnetic_field[0], magnetic_field[1], magnetic_field[2]);

        usleep(100000); // 10 Hz update rate
    }

cleanup:
    if (i2c_file >= 0) {
        close(i2c_file);
    }
    if (fd_log >= 0) {
        close(fd_log);
    }
    return 0;
}

