#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define ADXL354B_CS_GPIO          8
#define ADXL354B_RESET            1F
#define ADXL354B_POWER_CTL        2D
#define ADXL354B_STATUS           4
#define ADXL354B_XDATA            8
#define ADXL354B_YDATA            1B
#define ADXL354B_ZDATA            1E
#define ADXL354B_PARTID           1
#define ADXL354B_SPI_SPEED        1000000
#define ADXL354B_SPI_MODE         0
#define ADXL354B_SPI_BITS         8
#define SLEEP_TIME_MS             1
#define LOG_INTERVAL_MS           100
#define LOG_FILE_PATH             "vibration_log.txt"

static int spi_xfer(uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    int retries = 5;
    while (retries > 0) {
        if (spiWriteRead(ADXL354B_CS_GPIO, tx_buf, len, rx_buf, len) == len) {
            return 1;
        }
        retries--;
        usleep(100000); // 100 microseconds delay between retries
    }
    return 0;
}

static int check_sensor_presence() {
    uint8_t partid[1];
    if (spi_xfer((uint8_t*)&ADXL354B_PARTID, partid, 1) == 1 && partid[0] == 0x1D) {
        return 1;
    }
    return 0;
}

static void reset_sensor() {
    uint8_t reset_val = 0x52;
    spi_xfer((uint8_t*)&reset_val, NULL, 1);
    usleep(SLEEP_TIME_MS * 1000);
}

static void configure_sensor() {
    uint8_t reg_val;

    // Reset the sensor
    reset_sensor();

    // Check if the sensor is present
    if (!check_sensor_presence()) {
        fprintf(stderr, "ADXL354B not found.\n");
        exit(1);
    }

    // Write to the POWER_CTL register to set the measurement mode
    reg_val = 0x08; // Clear the RUN bit
    spi_xfer((uint8_t*)&ADXL354B_POWER_CTL, &reg_val, 1);

    // Wait for the STABLE bit in STATUS to be set
    while (spi_xfer((uint8_t*)&ADXL354B_STATUS, &reg_val, 1) == 1 && !(reg_val & 0x01)) {
        usleep(10000);
    }

    // Set the RUN bit in POWER_CTL
    reg_val = 0x09; // Set the RUN bit
    spi_xfer((uint8_t*)&ADXL354B_POWER_CTL, &reg_val, 1);
}

static void log_data(uint16_t x, uint16_t y, uint16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE_PATH, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", time_str, x, y, z);
    fclose(log_file);
}

static void read_acceleration_data() {
    uint8_t xdata[3];
    uint8_t ydata[3];
    uint8_t zdata[3];

    // Read X-axis data
    if (spi_xfer((uint8_t*)&ADXL354B_XDATA, xdata, 3) == 3) {
        int16_t x = (xdata[0] << 16) | (xdata[1] << 8) | xdata[2];
        x = (x >> 4) * ADXL354B_SENSITIVITY;
        log_data(x, ydata_to_int16(ydata), zdata_to_int16(zdata));
    }

    // Read Y-axis data
    if (spi_xfer((uint8_t*)&ADXL354B_YDATA, ydata, 3) == 3) {
        int16_t y = (ydata[0] << 16) | (ydata[1] << 8) | ydata[2];
        y = (y >> 4) * ADXL354B_SENSITIVITY;
        log_data(xdata_to_int16(xdata), y, zdata_to_int16(zdata));
    }

    // Read Z-axis data
    if (spi_xfer((uint8_t*)&ADXL354B_ZDATA, zdata, 3) == 3) {
        int16_t z = (zdata[0] << 16) | (zdata[1] << 8) | zdata[2];
        z = (z >> 4) * ADXL354B_SENSITIVITY;
        log_data(xdata_to_int16(xdata), ydata_to_int16(ydata), z);
    }
}

static int16_t ydata_to_int16(const uint8_t *ydata) {
    return (ydata[0] << 16) | (ydata[1] << 8) | ydata[2];
}

static int16_t zdata_to_int16(const uint8_t *zdata) {
    return (zdata[0] << 16) | (zdata[1] << 8) | zdata[2];
}

static int16_t xdata_to_int16(const uint8_t *xdata) {
    return (xdata[2] << 16) | (xdata[1] << 8) | xdata[0];
}

int main(int argc, char *argv[]) {
    int spi_handle;
    int ret;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    spi_handle = gpioOpen(ADXL354B_CS_GPIO, GPIO_SPI, ADXL354B_SPI_SPEED, ADXL354B_SPI_MODE, ADXL354B_SPI_BITS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        goto cleanup;
    }

    configure_sensor();

    while (1) {
        read_acceleration_data();
        usleep(LOG_INTERVAL_MS * 1000);
    }

cleanup:
    gpioTerm();
    close(spi_handle);
    return 0;
}

