#include <sys/time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define CE_PIN 8
#define ADIS16362_ADDR 0x68
#define GYRO_REG_X 0x04
#define GYRO_REG_Y 0x06
#define GYRO_REG_Z 0x08
#define ACCL_REG_X 0x0A
#define ACCL_REG_Y 0x0C
#define ACCL_REG_Z 0x0E
#define SAMPLE_RATE_HZ 100
#define LSB_TO_DEG_S 0.05
#define LSB_TO_G 0.0025

static int gpiod_init(void);
static void gpiod_cleanup(void);
static int spi_init(void);
static void spi_cleanup(void);
static void signal_handler(int signum);
static void log_imu_data(const char *timestamp, int16_t x_gyro, int16_t y_gyro, int16_t z_gyro, int16_t x_accel, int16_t y_accel, int16_t z_accel);

int main(void) {
    if (gpiod_init() != 0) {
        fprintf(stderr, "Failed to initialize gpiod\n");
        return 1;
    }

    if (spi_init() != 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        gpiod_cleanup();
        return 1;
    }

    signal(SIGINT, signal_handler);

    FILE *log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spi_cleanup();
        gpiod_cleanup();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long timestamp = tv.tv_sec * 1000000000LL + tv.tv_usec * 1000;

    while (1) {
        int16_t data[6];

        if (spiXfer(SPI_BUS, CE_PIN, &ADIS16362_ADDR, 1, &data[0], 0, NULL, 0) != 5) {
            perror("spiXfer error");
            continue;
        }

        if (spiXfer(SPI_BUS, CE_PIN, &data[0], 1, &data[1], 0, NULL, 0) != 2) {
            perror("spiXfer error");
            continue;
        }

        data[0] &= 0x7F; // Clear MSB for ADIS16362 read protocol

        int16_t x_gyro = (data[GYRO_REG_X] << 8) | data[GYRO_REG_X + 1];
        int16_t y_gyro = (data[GYRO_REG_Y] << 8) | data[GYRO_REG_Y + 1];
        int16_t z_gyro = (data[GYRO_REG_Z] << 8) | data[GYRO_REG_Z + 1];

        int16_t x_accel = (data[ACCL_REG_X] << 8) | data[ACCL_REG_X + 1];
        int16_t y_accel = (data[ACCL_REG_Y] << 8) | data[ACCL_REG_Y + 1];
        int16_t z_accel = (data[ACCL_REG_Z] << 8) | data[ACCL_REG_Z + 1];

        gettimeofday(&tv, NULL);
        timestamp = tv.tv_sec * 1000000000LL + tv.tv_usec * 1000;

        log_imu_data(&timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    fclose(log_file);
    spi_cleanup();
    gpiod_cleanup();
    gpioTerminate();

    return 0;
}

static int gpiod_init(void) {
    if (gpioInitialise() < 0) {
        return -1;
    }

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0) {
        return -1;
    }

    return 0;
}

static void gpiod_cleanup(void) {
    gpioTerminate();
}

static int spi_init(void) {
    if (spiOpen(SPI_BUS, &gpiod_handle) < 0) {
        return -1;
    }

    if (spiSetDataMode(SPI_BUS, SPI_MODE_3) < 0) {
        return -1;
    }

    if (spiSetBitsPerWord(SPI_BUS, 16) < 0) {
        return -1;
    }

    if (spiSetMaxSpeed(SPI_BUS, 1000000) < 0) {
        return -1;
    }

    return 0;
}

static void spi_cleanup(void) {
    if (gpiod_handle >= 0) {
        spiClose(gpiod_handle);
        gpiod_handle = -1;
    }
}

static void signal_handler(int signum) {
    spi_cleanup();
    gpiod_cleanup();
    gpioTerminate();
    exit(0);
}

static void log_imu_data(const char *timestamp, int16_t x_gyro, int16_t y_gyro, int16_t z_gyro, int16_t x_accel, int16_t y_accel, int16_t z_accel) {
