#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define SENSOR_1_LINE_NAME "gpio-17"
#define SENSOR_2_LINE_NAME "gpio-27"

static gpiod_line_callback_t sensor_callback;
static gpiod_line_data_callback_t sensor_data_callback;

void sensor_callback(struct gpiod_chip *chip, struct gpiod_line *line,
                     unsigned int value, unsigned int event) {
    printf("%s: Sensor %s: Obstacle detected: %s\n", ctime(&time(NULL)),
           line->label, value == 0 ? "yes" : "no");
}

void sensor_data_callback(struct gpiod_chip *chip, struct gpiod_line_data *data,
                          unsigned int n_lines) {
    for (unsigned int i = 0; i < n_lines; ++i) {
        struct gpiod_line *line = data->lines + i;
        printf("%s: Sensor %s: Value: %d\n", ctime(&time(NULL)), line->label,
               line->value);
    }
}

int main(void) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line_request *request;
    struct gpiod_line_data data;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip");
        return 1;
    }

    request = gpiod_chip_request_lines(chip, 2, GPIOD_ASIS,
                                       SENSOR_1_LINE_NAME, SENSOR_2_LINE_NAME);
    if (!request) {
        perror("Failed to request lines");
        gpiod_chip_close(chip);
        return 1;
    }

    sensor_callback = sensor_callback;
    ret = gpiod_line_request_set_debounce(request->lines[0], 10);
    if (ret < 0) {
        perror("Failed to set debounce for sensor 1");
        goto cleanup;
    }
    ret = gpiod_line_request_set_debounce(request->lines[1], 10);
    if (ret < 0) {
        perror("Failed to set debounce for sensor 2");
        goto cleanup;
    }

    sensor_data_callback = sensor_data_callback;
    ret = gpiod_line_request_set_callback(request->lines[0], GPIOD_EDGE_FALLING,
                                          sensor_callback);
    if (ret < 0) {
        perror("Failed to set callback for sensor 1");
        goto cleanup;
    }
    ret = gpiod_line_request_set_callback(request->lines[1], GPIOD_EDGE_FALLING,
                                          sensor_callback);
    if (ret < 0) {
        perror("Failed to set callback for sensor 2");
        goto cleanup;
    }

    ret = gpiod_line_request_set_data_callback(request, sensor_data_callback);
    if (ret < 0) {
        perror("Failed to set data callback");
        goto cleanup;
    }

    while (1) {
        ret = gpiod_line_request_get_values(request, &data, 100000);
        if (ret < 0) {
            perror("Failed to read sensor values");
            continue;
        }

        printf("Read sensor values: Sensor 1: %d, Sensor 2: %d\n",
               data.lines[0].value, data.lines[1].value);
        usleep(100000);
    }

cleanup:
    gpiod_line_request_free(request);
    gpiod_chip_close(chip);

    return 0;
}

