#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO_LINE "gpio8"
#define SPI_MODE 3
#define SPI_LSB_FIRST 0
#define SPI_MAX_HZ 1000000
#define DATA_REG_ADDR_MASK 0x03
#define SCALE_FACTOR 0.02f

int spi_fd, gpio_fd;
struct spi_ioc_transfer transfers[4];
struct gpiod_line *cs_line;

void die(const char *msg) {
    perror(msg);
    if (spi_fd >= 0) close(spi_fd);
    if (gpio_fd >= 0) gpiod_line_put_request(cs_line, 0);
    gpiod_line_release(cs_line);
    exit(EXIT_FAILURE);
}

int init_gpio() {
    cs_line = gpiod_get(NULL, CS_GPIO_LINE, GPIOD_INPUT_HIGH | GPIOD_ACTIVE_LOW);
    if (!cs_line) return -1;

    gpiod_line_request_index(cs_line, 0);
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) return -1;

    struct spi_ioc_transfer zero_transfer = {
        .tx_buf = (unsigned char*) &zero,
        .len = sizeof(zero),
        .speed_hz = SPI_MAX_HZ,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    transfers[0] = zero_transfer;

    struct spi_ioc_transfer setup_transfer = {
        .tx_buf = (unsigned char*) &setup,
        .len = sizeof(setup),
        .speed_hz = SPI_MAX_HZ,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    transfers[1] = setup_transfer;

    struct spi_ioc_transfer addr_transfer = {
        .tx_buf = (unsigned char*) &addr,
        .len = sizeof(addr),
        .speed_hz = SPI_MAX_HZ,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    transfers[2] = addr_transfer;

    struct spi_ioc_transfer data_transfer = {
        .rx_buf = data,
        .len = sizeof(data),
        .speed_hz = SPI_MAX_HZ,
        .bits_per_word = 8,
        .cs_change = 0,
    };

    transfers[3] = data_transfer;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 1) return -1;

    return 0;
}

void write_msc_ctrl(uint8_t value) {
    transfers[1].tx_buf[0] = value;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 0) die("Failed to write MSC_CTRL");
}

void read_data(uint8_t addr) {
    addr_transfer.tx_buf[0] = (addr & DATA_REG_ADDR_MASK) | 0x80;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 0) die("Failed to write data address");

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfers) < 1) die("Failed to read data");
}

int16_t read_signed_data(uint8_t *buf) {
    int16_t value = (buf[0] << 8) | buf[1];
    if (value & 0x8000) value |= 0xFFFF0000;
    return value;
}

