static const double GYRO_SENSITIVITY = 8.75e-3;
static const double ACC_SENSITIVITY = 6.1e-5;

int init_pigpio(int *pi) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }
    *pi = pigpio;
    return 0;
}

int open_i2c(int *i2c_fd, int bus, int addr) {
    char filename[32];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", bus);
    *i2c_fd = open(filename, O_RDWR | O_NONBLOCK);
    if (*i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }
    if (ioctl(*i2c_fd, I2C_SLAVE, addr << 1) < 0) {
        perror("Failed to address I2C slave");
        return 1;
    }
    return 0;
}

void close_i2c(int i2c_fd) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

