    uint8_t data[2] = {reg, value};
    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write I2C register");
        return 1;
    }
    return 0;
}

int read_reg(int i2c_fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[len];
    if (read(i2c_fd, &buf[0], len) != len) {
