        return 1;
    }

    if (open_i2c(&i2c_fd, I2C_BUS, LSM6DSR_ADDR)) {
        goto cleanup;
    }

    if (read_reg(i2c_fd, WHO_AM_I, &who_am_i, 1)) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        goto cleanup;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x6B, got 0x%02X\n", who_am_i);
        goto cleanup;
    }

    if (write_reg(i2c_fd, CTRL1_XL, 0x42)) {
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        goto cleanup;
    }
    if (write_reg(i2c_fd, CTRL2_G, 0x42)) {
        fprintf(stderr, "Failed to write CTRL2_G register\n");
        goto cleanup;
