        if (read_reg(i2c_fd, OUTX_L_G, gyro_data, sizeof(gyro_data))) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }
        if (read_reg(i2c_fd, OUTZ_L_G, acc_data, sizeof(acc_data))) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        for (size_t i = 0; i < 3; ++i) {
            gyro_data[i] *= GYRO_SENSITIVITY;
            acc_data[i] *= ACC_SENSITIVITY;
        }

        printf("Gyro X: %.6f, Y: %.6f, Z: %.6f\tAccel X: %.6f, Y: %.6f, Z: %.6f\n",
               gyro_data[0], gyro_data[1], gyro_data[2],
               acc_data[0], acc_data[1], acc_data[2]);

        usleep(100000);
    }

cleanup:
    close_i2c(i2c_fd);
    gpioTerminate();
    return 0;
}

