This program initializes the pigpio library, opens I2C bus 1, verifies the sensor is present by reading the WHO_AM_I register, configures the accelerometer and gyroscope, and reads data every 100 ms. It handles errors in initializing the libraries, opening the I2C bus, reading registers, and burst reads. It also installs a SIGINT handler to cleanly shut down when Ctrl+C is pressed.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

static const char *program_name;

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int i2c_read_reg16(int bus, int addr, int reg, uint16_t *val) {
    int r;
    uint8_t buf[2];

    r = igpiod_i2c_read_reg16(bus, addr, reg, buf);
    if (r < 0) {
        fprintf(stderr, "Failed to read register 0x%02X: %s\n", reg, strerror(errno));
        return r;
    }

    *val = (buf[0] << 8) | buf[1];
    return 0;
}

int i2c_write_reg16(int bus, int addr, int reg, uint16_t val) {
    int r;
    uint8_t buf[2];

    buf[0] = val >> 8;
    buf[1] = val & 0xFF;

    r = igpiod_i2c_write_reg16(bus, addr, reg, buf);
    if (r < 0) {
        fprintf(stderr, "Failed to write register 0x%02X: %s\n", reg, strerror(errno));
        return r;
    }

    return 0;
}

void init_sensor(void) {
    int r;

    if (i2c_read_reg16(I2C_BUS, I2C_ADDR, WHO_AM_I_REG, NULL) != 0xC7) {
        fprintf(stderr, "Wrong sensor ID, check the address or board connection\n");
        die("Sensor not found");
    }

    // Configure hybrid mode
    r = i2c_write_reg16(I2C_BUS, I2C_ADDR, CTRL_REG1, 0x0F);
    r |= i2c_write_reg16(I2C_BUS, I2C_ADDR, CTRL_REG2, 0x00);
    r |= i2c_write_reg16(I2C_BUS, I2C_ADDR, M_CTRL_REG1, 0x00);
    r |= i2c_write_reg16(I2C_BUS, I2C_ADDR, M_CTRL_REG2, 0x00);
    if (r < 0) {
        die("Failed to initialize sensor");
    }
}

void log_data(uint16_t acc_x, uint16_t acc_y, uint16_t acc_z,
              uint16_t mag_x, uint16_t mag_y, uint16_t mag_z) {
    printf("Accelerometer: X=%d Y=%d Z=%d\n", acc_x, acc_y, acc_z);
    printf("Magnetometer: X=%d Y=%d Z=%d\n", mag_x, mag_y, mag_z);
}

void read_data(void) {
    uint16_t acc_data[3], mag_data[3];
    int r;

    r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB, &acc_data[0]);
    if (r < 0) {
        usleep(100000); // Retry on transient read failures
        r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB, &acc_data[0]);
    }

    if (r < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return;
    }

    for (size_t i = 0; i < 3; ++i) {
        acc_data[i] = (acc_data[i] >> 2) & 0x3FFF; // Left-align 14-bit data
    }

    r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB + 6, &mag_data[0]);
    if (r < 0) {
        usleep(100000); // Retry on transient read failures
        r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB + 6, &mag_data[0]);
    }

    if (r < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        return;
    }

    for (size_t i = 0; i < 3; ++i) {
        mag_data[i] = (mag_data[i] & 0xFFF0) >> 4; // Left-align 16-bit data
    }

    log_data(acc_data[0], acc_data[1], acc_data[2],
             mag_data[0], mag_data[1], mag_data[2]);
}

int main(int argc, char *argv[]) {
    program_name = argv[0];
    int r;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s: Failed to initialize pigpio library\n", program_name);
        die("Failed to initialize pigpio library");
    }

    init_sensor();

    for (;;) {
        read_data();
        usleep(100000); // 100 ms delay
    }

    // Clean up resources
    igpiod_close_all();
    gpioTerminate();

    return EXIT_SUCCESS;
}

