    printf("Accelerometer: X=%d Y=%d Z=%d\n", acc_x, acc_y, acc_z);
    printf("Magnetometer: X=%d Y=%d Z=%d\n", mag_x, mag_y, mag_z);
}

void read_data(void) {
    uint16_t acc_data[3], mag_data[3];
    int r;

    r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB, &acc_data[0]);
    if (r < 0) {
        usleep(100000); // Retry on transient read failures
        r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB, &acc_data[0]);
    }

    if (r < 0) {
        fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
        return;
    }

    for (size_t i = 0; i < 3; ++i) {
        acc_data[i] = (acc_data[i] >> 2) & 0x3FFF; // Left-align 14-bit data
    }

    r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB + 6, &mag_data[0]);
    if (r < 0) {
        usleep(100000); // Retry on transient read failures
        r = i2c_read_reg16(I2C_BUS, I2C_ADDR, OUT_X_MSB + 6, &mag_data[0]);
    }

    if (r < 0) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        return;
    }

    for (size_t i = 0; i < 3; ++i) {
        mag_data[i] = (mag_data[i] & 0xFFF0) >> 4; // Left-align 16-bit data
    }

    log_data(acc_data[0], acc_data[1], acc_data[2],
             mag_data[0], mag_data[1], mag_data[2]);
}

int main(int argc, char *argv[]) {
    program_name = argv[0];
    int r;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s: Failed to initialize pigpio library\n", program_name);
        die("Failed to initialize pigpio library");
    }

    init_sensor();

    for (;;) {
        read_data();
        usleep(100000); // 100 ms delay
    }

    // Clean up resources
    igpiod_close_all();
    gpioTerminate();

    return EXIT_SUCCESS;
}
