#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>

#define ADXL345_ADDR 0x53
#define XOUT_H 0x32
#define XOUT_L 0x33
#define YOUT_H 0x34
#define YOUT_L 0x35
#define ZOUT_H 0x36
#define ZOUT_L 0x37
#define THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

struct timespec last_log_time = {0, 0};
gpiod_line_request_linenum_t line_request;

int i2c_fd;

void i2c_init() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(1);
    }
}

void i2c_read(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to i2c");
        exit(1);
    }

    if (read(i2c_fd, buf, len) != len) {
        perror("Failed to read from i2c");
        exit(1);
    }
}

double read_angle(int16_t x, int16_t y, int16_t z) {
    double x_rad = (x / 32768.0) * M_PI * 2.0;
    double y_rad = (y / 32768.0) * M_PI * 2.0;
    double z_rad = (z / 32768.0) * M_PI * 2.0;

    double roll = atan2(sin(x_rad - y_rad) * cos(z_rad), cos(x_rad) * cos(y_rad) + sin(x_rad) * sin(y_rad) * cos(z_rad));
    double pitch = atan2(sin(y_rad), cos(y_rad) * cos(z_rad));

    return (roll * 180.0 / M_PI + 360.0) % 360.0;
}

void log_event(double roll, double pitch) {
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);

    if (current_time.tv_sec - last_log_time.tv_sec >= 100 || current_time.tv_nsec >= 100000000) {
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%lu.%09lu: Roll: %.2f, Pitch: %.2f\n", (unsigned long)current_time.tv_sec, current_time.tv_nsec, roll, pitch);
            fclose(log_file);
            last_log_time = current_time;
        }
    }

    if (fabs(roll) > THRESHOLD || fabs(pitch) > THRESHOLD) {
        printf("Tilt event detected: Roll: %.2f, Pitch: %.2f\n", roll, pitch);
    }
}

void gpio_init() {
    gpiod_line_request_config config = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_configure_async(line_request, config);
    if (ret < 0) {
        perror("Failed to configure GPIO line");
        exit(1);
    }
}

void gpio_cleanup() {
    gpiod_line_release(line_request);
    gpiod_line_request_free(line_request);
}

void signal_handler(int sig) {
    gpio_cleanup();
    close(i2c_fd);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);

    i2c_init();

    gpiod_controller_spidev_data_request_linenum_t controller_data = {
        .name = "spidev",
        .linenum = GPIOD_LINE_REQUEST_DEFAULT_LINE,
        .consumer = "tilt_detector",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_IN,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
    };

    line_request = gpiod_line_request_create(0, &controller_data);
    if (!line_request) {
        perror("Failed to create GPIO line request");
        exit(1);
    }

    int16_t x, y, z;
    while (1) {
        i2c_read(XOUT_H, (uint8_t *)&x, 2);
        i2c_read(YOUT_H, (uint8_t *)&y, 2);
        i2c_read(ZOUT_H, (uint8_t *)&z, 2);

        double roll = read_angle(x, y, z);
        double pitch = atan2(sin(y * M_PI * 2.0 / 32768.0), cos(y * M_PI * 2.0 / 32768.0) * cos(z * M_PI * 2.0 / 32768.0));
        log_event(roll, pitch);

        usleep(100000);
    }

    gpio_cleanup();
    close(i2c_fd);

    return 0;
}

