#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLES_PER_WINDOW 1000
#define WINDOW_DURATION 5000
#define THREAD_SLEEP 1000
#define SIG_INT 2
#define SIG_TERM 15

void usage(const char *progname) {
    fprintf(stderr, "Usage: %s threshold\n", progname);
    fprintf(stderr, "  threshold: positive integer representing the minimum number of high-readings per 5-second window required to trigger an alert\n");
    exit(EXIT_FAILURE);
}

int is_number(const char *str) {
    int i;
    for (i = 0; str[i]; ++i) {
        if (!isdigit(str[i])) {
            return 0;
        }
    }
    return 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        usage(argv[0]);
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        usage(argv[0]);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        perror("gpioSetMode");
        exit(EXIT_FAILURE);
    }

    time_t start_time, end_time, current_time;
    int high_count = 0;
    int samples_taken = 0;

    while (1) {
        start_time = time(NULL);
        while (samples_taken < SAMPLES_PER_WINDOW) {
            if (gpioRead(GPIO_PIN) == 1) {
                ++high_count;
            }
            usleep(1000);
            ++samples_taken;
        }

        end_time = time(NULL);
        current_time = end_time;
        if (difftime(end_time, start_time) < WINDOW_DURATION) {
            usleep(WINDOW_DURATION - difftime(end_time, start_time) * 1000000);
        }

        if (high_count >= threshold) {
            current_time = time(NULL);
            printf("%s ALERT: High noise level detected (%d high readings in the last 5 seconds)\n", ctime(&current_time), high_count);
        } else {
            current_time = time(NULL);
            printf("%s Normal: %d high readings in the last 5 seconds\n", ctime(&current_time), high_count);
        }

        high_count = 0;
        samples_taken = 0;
        sleep(THREAD_SLEEP);

        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            perror("signal");
        }
    }

    gpioTerm();
    exit(EXIT_SUCCESS);
}

