#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <signal.h>
#include <linux/types.h>
#include <libgpiod.h>

#define RELAY_GPIO_A 17
#define RELAY_GPIO_B 27
#define RELAY_VCC 5
#define RELAY_GND 6
#define RELAY_EN 13
#define SECURITY_CODE_LEN 6
#define MAX_ATTEMPTS 3

volatile sig_atomic_t sigint_received = 0;

void sigint_handler(int signum) {
    sigint_received = 1;
}

void die(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

int setup_gpio(struct gpiod_chip *chip, unsigned int gpio) {
    int ret;
    struct gpiod_line *line;

    line = gpiod_chip_get_line(chip, gpio);
    if (!line) {
        fprintf(stderr, "Failed to get line for GPIO%d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_request_output(line, "door_access", GPIOD_LINE_REQUEST_DIRECTION_OUT);
    if (ret < 0) {
        fprintf(stderr, "Failed to request output for GPIO%d: %s\n", gpio, strerror(errno));
        return -1;
    }

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set GPIO%d to LOW: %s\n", gpio, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *relay_a, *relay_b;
    FILE *access_log;
    int ret, i, attempts = 0;
    char security_code[SECURITY_CODE_LEN + 1];
    unsigned int random_code;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (setup_gpio(chip, RELAY_GPIO_A) < 0 || setup_gpio(chip, RELAY_GPIO_B) < 0) {
        goto cleanup;
    }

    ret = gpiod_chip_get_lines_by_names(chip, "gpio", RELAY_VCC, RELAY_GND, RELAY_EN);
    if (ret < 0) {
        fprintf(stderr, "Failed to get lines for VCC, GND, and EN: %s\n", strerror(errno));
        goto cleanup;
    }

    access_log = fopen("access_log.txt", "w");
    if (!access_log) {
        fprintf(stderr, "Failed to open access_log.txt: %s\n", strerror(errno));
        goto cleanup;
    }

    srand(time(NULL));
    random_code = rand() % 1000000 + 100000;
    printf("Generated security code: %06d\n", random_code);

    while (!sigint_received) {
        printf("Enter security code: ");
        fflush(stdout);
        fgets(security_code, sizeof(security_code), stdin);

        if (security_code[0] == '\n') {
            continue;
        }

        for (i = 0; i < SECURITY_CODE_LEN; i++) {
            if (!isdigit(security_code[i])) {
                printf("Invalid input. Please enter a numeric code.\n");
                fflush(stdin);
                break;
            }
            security_code[i] -= '0';
        }

        if (i < SECURITY_CODE_LEN) {
            continue;
        }

        if (security_code[0] != random_code % 10) {
            printf("Access denied\n");
            attempts++;
            if (attempts >= MAX_ATTEMPTS) {
                printf("Maximum attempts reached. Exiting...\n");
                break;
            }
            continue;
        }

        printf("Access granted\n");
        gpiod_line_set_value(relay_a, 1);
        sleep(5);
        gpiod_line_set_value(relay_a, 0);

        fprintf(access_log, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
                localtime(&time(NULL))->tm_year + 1900,
                localtime(&time(NULL))->tm_mon + 1,
                localtime(&time(NULL))->tm_mday,
                localtime(&time(NULL))->tm_hour,
                localtime(&time(NULL))->tm_min,
                localtime(&time(NULL))->tm_sec,
                random_code);

        random_code = rand() % 1000000 + 100000;
        printf("New security code: %06d\n", random_code);
        attempts = 0;
    }

cleanup:
    if (access_log) {
        fclose(access_log);
    }

    gpiod_chip_release(chip);

    return EXIT_SUCCESS;
}

