        perror("Failed to read data from sensor");
        fclose(log_file);
        close(i2c_fd);
        exit(1);
    }

    // Calculate illuminance in lux
    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (raw_value * 5.0) / 6.0;

    // Log sensor readings
    while (1) {
        gettimeofday(&tv, NULL);
        rawtime = tv.tv_sec;
        timeinfo = localtime(&rawtime);
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
