        // Check for SIGINT (Ctrl+C)
        if (fflush(log_file) == EOF) {
            perror("Failed to flush log file");
            break;
        }
    }

    // Close log file and I2C bus
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

