    if (server_fd < 0) {
        perror("socket");
        goto cleanup;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        goto cleanup;
    }

    if (listen(server_fd, 1) < 0) {
        perror("listen");
        goto cleanup;
    }

    printf("Theremin server started on port 12345\n");

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            perror("accept");
            continue;
        }

        handle_client(client_fd);
        close(client_fd);
    }

cleanup:
    close(server_fd);
    pigpio_stop();
    pigpio_terminate();
    return 0;
}

int mpr121_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    gpioSetMode(GPIO_MODE_BCM);
    gpioWrite(GPIO_IGPD_SDA_N, 1);
    gpioWrite(GPIO_IGPD_SCL_N, 1);

    if (i2cOpen(0, MPR121_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C connection to MPR121\n");
        return -1;
    }

    uint8_t reset_cmd[] = {0x00, 0x07, 0x00};
    if (i2cWriteRead(0, MPR121_ADDR, reset_cmd, sizeof(reset_cmd), NULL, 0) < 0) {
        fprintf(stderr, "Failed to send soft reset command to MPR121\n");
        return -1;
    }

    uint8_t config_cmd[] = {0x00, 0x0F, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (i2cWrite(0, MPR121_ADDR, config_cmd, sizeof(config_cmd)) < 0) {
        fprintf(stderr, "Failed to configure MPR121\n");
        return -1;
    }

    return 0;
}

int i2c_read(uint8_t *buf, size_t len) {
    if (i2cRead(0, MPR121_ADDR, buf, len) < 0) {
        fprintf(stderr, "Failed to read from I2C\n");
        return -1;
    }
    return 0;
}

void pwm_setup(void) {
    gpioSetMode(PWM_GPIO, GPIO_MODE_BCM_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, 1000000);
}

void play_tone(int frequency) {
    int duty_cycle = (int) (500000 * log(frequency / 220));
    gpioSetPWMrange(PWM_GPIO, duty_cycle * 2 + 1);
    gpioPWM(PWM_GPIO, duty_cycle);
}

void log_frequency(int frequency) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %d Hz\n", timestamp, frequency);
    fclose(log_file);
}

void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer), 0);
    if (n <= 0) {
        perror("recv");
        return;
    }

    if (strncmp(buffer, "MOTION_DETECTED:", 15) == 0 &&
        strcmp(buffer + 15, SHARED_SECRET) == 0) {
        int frequency;
        int last_frequency = -1;
        struct timespec ts = {0, SAMPLE_INTERVAL};
        while (last_frequency == -1 || clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            if (i2c_read(buffer, sizeof(buffer)) < 0) {
                perror("i2c_read");
                break;
            }

            int electrode_data = buffer[0] & 0x0F;
            if (electrode_data > last_frequency) {
                frequency = (int) (220 * pow(2, (electrode_data - 1) / 4.0));
                last_frequency = frequency;
            }

            if (last_frequency != -1) {
                play_tone(last_frequency);
                log_frequency(last_frequency);
            }

            nanosleep(&ts, NULL);
        }

        close(client_fd);
    }
}

