code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS 1
#define SDA_PIN 0
#define SCL_PIN 1
#define LED_GPIO 17
#define MAG_ADDR 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08

static int i2c_fd;
static gpio_handle_t led_gpio;

void i2c_init() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    i2c_fd = open(i2c_dev, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAG_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    int ret;
    struct gpiod_line_request_data led_req = {
        .consumer = "magnetometer_led",
        .direction = GPIOD_IN,
        .flags = GPIOD_LINE_REQUEST_INPUT,
    };

    ret = gpiod_chip_open_byname("gpiochip0");
    if (ret < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    led_gpio = gpiod_get_line(ret, LED_GPIO);
    if (led_gpio < 0) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_dt(led_gpio, &led_req);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(led_gpio, 0);
}

void i2c_write_byte(uint8_t reg, uint8_t data) {
    uint8_t buf[2] = {reg, data};
    write(i2c_fd, buf, sizeof(buf));
}

void i2c_read_bytes(uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t read_buf[len];
    if (read(i2c_fd, read_buf, len) != len) {
        perror("Failed to read from I2C device");
    } else {
        memcpy(buf, read_buf, len);
    }
}

void init_magnetometer() {
    i2c_write_byte(CTRL_REG1_M, 0x18); // 10 Hz continuous conversion
}

float read_magnetic_field_magnitude() {
    uint8_t data[6];
    i2c_read_bytes(OUT_X_L_M, data, 6);

    float x = (data[1] << 8 | data[0]) * 0.00875;
    float y = (data[3] << 8 | data[2]) * 0.00875;
    float z = (data[5] << 8 | data[4]) * 0.00875;

    return z;
}

