#define CONFIG_REG_B 0x0B
#define MODE_REG 0x00
#define NUM_SAMPLES_FOR_OFFSET 100
#define SAMPLE_INTERVAL_MS 16
#define OFFSET_UPDATE_INTERVAL_MS 500
#define OFFSET_WINDOW_SIZE NUM_SAMPLES_FOR_OFFSET

typedef struct {
    int16_t x, y, z;
} magnetometer_data_t;

magnetometer_data_t offsets[OFFSET_WINDOW_SIZE];
int offset_index = 0;

int i2c_write_reg(int bus, int addr, int reg, int value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = value;

    if (i2c_master_writeRead(bus, addr, buf, 2, NULL, 0) < 2) {
        perror("i2c_master_writeRead");
        return -1;
    }

    return 0;
}

int i2c_read_reg(int bus, int addr, int reg, int *value) {
    char buf[2];
    buf[0] = reg;

    if (i2c_master_writeRead(bus, addr, buf, 1, buf + 1, 1) != 1) {
        perror("i2c_master_writeRead");
        return -1;
    }

    *value = buf[1];
    return 0;
}

void configure_hmc5883l() {
    int ret;

    ret = i2c_write_reg(I2C_BUS, HMC5883L_ADDR, CONFIG_REG_A, 0x70);
    if (ret < 0) {
        exit(EXIT_FAILURE);
    }

    ret = i2c_write_reg(I2C_BUS, HMC5883L_ADDR, CONFIG_REG_B, 0x20);
    if (ret < 0) {
        exit(EXIT_FAILURE);
    }

    ret = i2c_write_reg(I2C_BUS, HMC5883L_ADDR, MODE_REG, 0x00);
    if (ret < 0) {
        exit(EXIT_FAILURE);
    }
}

void collect_offsets() {
    magnetometer_data_t data;
    int i;

    for (i = 0; i < OFFSET_WINDOW_SIZE; i++) {
        if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x03, (int *)&data.x) < 0) {
            perror("i2c_read_reg");
            continue;
        }
        if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x05, (int *)&data.y) < 0) {
            perror("i2c_read_reg");
            continue;
        }
        if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x07, (int *)&data.z) < 0) {
            perror("i2c_read_reg");
            continue;
        }

        offsets[i] = data;
    }
}

void print_offset_corrected_values() {
    magnetometer_data_t data;
    int16_t x_offset = 0, y_offset = 0, z_offset = 0;
    int i;

    if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x03, (int *)&data.x) < 0) {
        perror("i2c_read_reg");
        return;
    }
    if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x05, (int *)&data.y) < 0) {
        perror("i2c_read_reg");
        return;
    }
    if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x07, (int *)&data.z) < 0) {
        perror("i2c_read_reg");
        return;
    }

    for (i = 0; i < OFFSET_WINDOW_SIZE; i++) {
        x_offset += offsets[i].x - data.x;
        y_offset += offsets[i].y - data.y;
        z_offset += offsets[i].z - data.z;
    }

    x_offset /= OFFSET_WINDOW_SIZE;
    y_offset /= OFFSET_WINDOW_SIZE;
    z_offset /= OFFSET_WINDOW_SIZE;

    printf("Offset-corrected values: X=%d, Y=%d, Z=%d\n", data.x - x_offset, data.y - y_offset, data.z - z_offset);
}

int main(int argc, char *argv[]) {
    int ret;
    struct pigpio *pi;

    if ((pi = pigpio_init(NULL)) == NULL) {
        fprintf(stderr, "pigpio_init failed\n");
        return EXIT_FAILURE;
    }

    configure_hmc5883l();
    collect_offsets();

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000);

        if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x03, (int *)&offsets[offset_index].x) < 0) {
            perror("i2c_read_reg");
            continue;
        }
        if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x05, (int *)&offsets[offset_index].y) < 0) {
            perror("i2c_read_reg");
            continue;
        }
        if (i2c_read_reg(I2C_BUS, HMC5883L_ADDR, 0x07, (int *)&offsets[offset_index].z) < 0) {
            perror("i2c_read_reg");
            continue;
        }

        offset_index = (offset_index + 1) % OFFSET_WINDOW_SIZE;

        if (offset_index == 0) {
            print_offset_corrected_values();
        }
    }

    pigpio_stop(pi);
    pigpio_terminate();

    return EXIT_SUCCESS;
}

