code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define LSM303D_ADDR 0x1D
#define LSM303D_WHO_AM_I 0x0F
#define LSM303D_CTRL_REG1 0x20
#define LSM303D_INT1_CFG 0x2A
#define LSM303D_OUT_X_L_A 0x28
#define LSM303D_ODR_50HZ 0x57
#define LSM303D_FS_2G 0x00
#define LSM303D_THRESHOLD_2000MG 0x7D
#define LSM303D_INT_DURATION_0 0x00
#define BUFFER_SIZE 64
#define GPIO_LINE_INT1 23

static gpiod_line_request_data_t gpio_request_data = { .direction = GPIOD_IN, .edge_detected_callback = NULL, .flags = GPIOD_LINE_REQUEST_INPUT };
static gpiod_line_data_t gpio_line_data;
static int i2c_fd;
static uint8_t buffer[BUFFER_SIZE][6];
static size_t head = 0, tail = 0;

void gpio_int_cb(struct gpiod_chan *chan, uint32_t value, uint32_t event) {
    if (event & GPIOD_LINE_EVENT_RISING_EDGE) {
        printf("INT1: Rising edge\n");
        for (size_t i = 0; i < 10 && head != tail; ++i) {
            printf("Sample %ld: X=%d Y=%d Z=%d\n", i, buffer[(tail + i) % BUFFER_SIZE][0], buffer[(tail + i) % BUFFER_SIZE][1], buffer[(tail + i) % BUFFER_SIZE][2]);
            tail = (tail + 1) % BUFFER_SIZE;
        }
    }
}

int init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        perror("Failed to acquire bus access");
        close(i2c_fd);
        return 1;
    }

    uint8_t who_am_i = 0;
    if (i2c_smbus_read_byte_data(i2c_fd, LSM303D_WHO_AM_I) != LSM303D_WHO_AM_I) {
        perror("Wrong LSM303D address");
        close(i2c_fd);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_CTRL_REG1, LSM303D_ODR_50HZ) < 0) {
        perror("Failed to set ODR");
        close(i2c_fd);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_CTRL_REG4, LSM303D_FS_2G) < 0) {
        perror("Failed to set full-scale");
        close(i2c_fd);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, LSM303D_INT1_CFG, LSM303D_THRESHOLD_2000MG | LSM303D_INT_DURATION_0) < 0) {
        perror("Failed to set INT1 configuration");
        close(i2c_fd);
        return 1;
    }

    return 0;
}

int init_gpio() {
    gpio_t gpio_handle = gpiod_get_index(GPIO_LINE_INT1);
    if (gpio_handle < 0) {
        perror("Failed to get GPIO handle");
        return 1;
    }

    if (gpiod_line_request_dup(gpio_handle, &gpio_request_data, &gpio_line_data) < 0) {
        perror("Failed to request GPIO line");
        gpiod_put_index(gpio_handle);
        return 1;
    }

    gpiod_line_enable_edge_detected(gpio_line_data, GPIOD_EDGE_RISING);
    gpiod_line_get_value(gpio_line_data, &gpio_line_data.value);

    return 0;
}

void read_accel_data() {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, LSM303D_OUT_X_L_A, 6, data) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
    } else {
        buffer[head][0] = data[0];
        buffer[head][1] = data[1];
        buffer[head][2] = data[2];
        head = (head + 1) % BUFFER_SIZE;
    }
}

void handle_sigint(int sig) {
    close(i2c_fd);
    gpiod_line_release(gpio_line_data);
    gpiod_put_index(gpio_handle);
    exit(0);
}

int main() {
    if (init_i2c()) {
        return 1;
    }

    if (init_gpio()) {
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        read_accel_data();
        usleep(100000);
    }

    return 0;
}

