#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <linux/gpio/consumer.h>
#include <libgpiod.h>

#define SOLENOID1_GPIO 17
#define SOLENOID2_GPIO 27
#define FLYBACK_DIODE_ENABLED 1
#define DELAY_MS 500

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data_v1[]) {
        {
            .consumer = "solenoid1",
            .direction = GPIOD_LINE_DIR_OUT,
            .active_low = FLYBACK_DIODE_ENABLED,
        },
        {
            .consumer = "solenoid2",
            .direction = GPIOD_LINE_DIR_OUT,
            .active_low = FLYBACK_DIODE_ENABLED,
        },
    },
    .n_lines = 2,
};

static gpiod_chip *chip;

void solenoid_set_low(struct gpiod_line_request_data_v1 *line) {
    int ret;

    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to set solenoid %s low: %s\n", line->consumer, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void solenoid_set_high(struct gpiod_line_request_data_v1 *line) {
    int ret;

    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to set solenoid %s high: %s\n", line->consumer, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void solenoid_init() {
    int ret;

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_request_lines(chip, &lines_data, NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    solenoid_set_low(&lines_data.lines[0]);
    solenoid_set_low(&lines_data.lines[1]);
}

void solenoid_cleanup() {
    gpiod_line_release(lines_data.lines);
    gpiod_chip_close(chip);
}

void sigint_handler(int signum) {
    solenoid_set_low(&lines_data.lines[0]);
    solenoid_set_low(&lines_data.lines[1]);
    solenoid_cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec delay;
    struct sigaction sa;

    solenoid_init();

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handlers");
        exit(EXIT_FAILURE);
    }

    while (1) {
        solenoid_set_high(&lines_data.lines[0]);
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = DELAY_MS * 1000000}, NULL);
        solenoid_set_low(&lines_data.lines[0]);
        solenoid_set_high(&lines_data.lines[1]);
        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = DELAY_MS * 1000000}, NULL);
        solenoid_set_low(&lines_data.lines[1]);
    }

    solenoid_cleanup();
    return 0;
}

