#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO_1 GPIO_17
#define RELAY_GPIO_2 GPIO_27
#define SERIAL_BAUD_RATE 9600
#define SERIAL_PORT_0 "/dev/serial0"
#define SERIAL_PORT_1 "/dev/serial1"
#define CODE_LENGTH 6
#define TIMEOUT 5000
#define UNLOCK_DURATION 2000
#define MAX_BUFFER_SIZE 1024

static char code[CODE_LENGTH];
static char buffer[MAX_BUFFER_SIZE];
static int buffer_index = 0;
static int serial_fd[2];
static pthread_t serial_thread_id[2];
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
}

void *serial_reader(void *arg) {
    int port_index = *(int *)arg;
    struct termios options;

    tcgetattr(serial_fd[port_index], &options);
    cfsetispeed(&options, B9600);
    cfsetospeed(&options, B9600);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = TIMEOUT / 10;
    tcsetattr(serial_fd[port_index], TCSANOW, &options);

    while (running) {
        memset(buffer, 0, MAX_BUFFER_SIZE);
        int bytes_read = read(serial_fd[port_index], buffer, MAX_BUFFER_SIZE - 1);
        if (bytes_read > 0) {
            for (int i = 0; i < bytes_read; ++i) {
                if (isdigit(buffer[i])) {
                    buffer[buffer_index++] = buffer[i];
                    if (buffer_index == CODE_LENGTH) {
                        break;
                    }
                } else {
                    buffer_index = 0;
                }
            }

            if (buffer_index == CODE_LENGTH) {
                for (int i = 0; i < CODE_LENGTH; ++i) {
                    if (buffer[i] != code[i]) {
                        buffer_index = 0;
                        break;
                    }
                }

                if (buffer_index == CODE_LENGTH) {
                    gpioWrite(RELAY_GPIO_1, 1);
                    gpioWrite(RELAY_GPIO_2, 1);
                    usleep(UNLOCK_DURATION * 1000);
                    gpioWrite(RELAY_GPIO_1, 0);
                    gpioWrite(RELAY_GPIO_2, 0);
                }

                buffer_index = 0;
            }
        }
    }

    close(serial_fd[port_index]);
    pthread_detach(pthread_self());
    pthread_exit(NULL);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO_1, PI_OUTPUT);
    gpioSetMode(RELAY_GPIO_2, PI_OUTPUT);
    gpioWrite(RELAY_GPIO_1, 0);
    gpioWrite(RELAY_GPIO_2, 0);

    for (int i = 0; i < CODE_LENGTH; ++i) {
        code[i] = '0' + i;
    }

    for (int i = 0; i < 2; ++i) {
        serial_fd[i] = open(SERIAL_PORT_0 + i, O_RDONLY | O_NOCTTY);
        if (serial_fd[i] < 0) {
            fprintf(stderr, "Failed to open serial port %s\n", SERIAL_PORT_0 + i);
            return 1;
        }

        pthread_create(&serial_thread_id[i], NULL, serial_reader, &i);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        usleep(100000);
    }

    gpioTerminate();

    for (int i = 0; i < 2; ++i) {
        pthread_join(serial_thread_id[i], NULL);
        close(serial_fd[i]);
    }

    return 0;
}

