code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <linux/types.h>
#include <libgpiod.h>
#include <syslog.h>
#include <signal.h>

#define RELAY_GPIO 17
#define PIR_GPIO 4
#define POLL_INTERVAL_MS 50
#define FAILSAFE_TIMEOUT_S 10

static gpiod_line_request_data_t relay_req = { .direction = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, .flags = GPIOD_LINE_REQUEST_FLAGS_NONE };
static gpiod_line_request_data_t pir_req = { .direction = GPIOD_LINE_REQUEST_DIRECTION_INPUT, .flags = GPIOD_LINE_REQUEST_FLAGS_EDGE_RISING | GPIOD_LINE_REQUEST_FLAGS_DEBOUNCE };

static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct gpiod_line *pir_line;

void log_syslog(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(priority, format, args);
    va_end(args);
}

void handle_signal(int signum) {
    log_syslog(LOG_INFO, "Received signal %d, shutting down...", signum);
    gpiod_line_set_value(relay_line, 0);
    gpiod_line_release(relay_line);
    gpiod_line_release(pir_line);
    gpiod_chip_release(chip);
    exit(0);
}

int main(void) {
    int ret;
    struct timespec ts;
    int pir_state = 0;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_syslog(LOG_ERR, "Failed to open gpiochip0: %s", gpiod_strerror(gpiod_get_last_error()));
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_GPIO);
    if (!pir_line) {
        log_syslog(LOG_ERR, "Failed to get line %d: %s", PIR_GPIO, gpiod_strerror(gpiod_get_last_error()));
        goto cleanup;
    }

    ret = gpiod_line_request_kbdev(pir_line, &pir_req);
    if (ret < 0) {
        log_syslog(LOG_ERR, "Failed to request line %d: %s", PIR_GPIO, gpiod_strerror(gpiod_get_last_error()));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_GPIO);
    if (!relay_line) {
        log_syslog(LOG_ERR, "Failed to get line %d: %s", RELAY_GPIO, gpiod_strerror(gpiod_get_last_error()));
        goto cleanup;
    }

    ret = gpiod_line_request_kbdev(relay_line, &relay_req);
    if (ret < 0) {
        log_syslog(LOG_ERR, "Failed to request line %d: %s", RELAY_GPIO, gpiod_strerror(gpiod_get_last_error()));
        goto cleanup;
    }

    while (1) {
        gpiod_line_get_value(pir_line, &pir_state);
        if (pir_state) {
            log_syslog(LOG_INFO, "Motion detected");
            gpiod_line_set_value(relay_line, 1);
            clock_gettime(CLOCK_MONOTONIC, &ts);
            ts.tv_sec += 1;
            while (gpiod_line_get_value(pir_line, &pir_state) && ts.tv_sec - ts.tv_nsec / 1_E9 < ts.tv_sec) {
                nanosleep((const struct timespec[]){{0, POLL_INTERVAL_MS * 1_E6}}, NULL);
            }
            if (pir_state) {
                log_syslog(LOG_WARNING, "Potential malfunction: PIR sensor remains HIGH for more than 10 seconds");
                gpiod_line_set_value(relay_line, 0);
            }
        }
        nanosleep((const struct timespec[]){{0, POLL_INTERVAL_MS * 1_E6}}, NULL);
    }

cleanup:
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_release(chip);
    return 0;
}

