            syslog(LOG_ERR, "Failed to initialize GPIO %d", relays[i]);
            goto cleanup;
        }

        gpioSetMode(pi, GPIO_MODE_OUTPUT, relays[i]);
        gpioWrite(pi, relays[i], GPIO_HIGH);
        log_relay_state_change(relays[i], 0);
    }

