}

static void irrigation_timer_cb(struct pigpio *pi, uint32_t gpio, uint32_t event) {
    static int current_relay = -1;
    static int current_state = 0; // 0: activation, 1: deactivation, 2: pause
    static time_t last_state_change = 0;

    if (current_state == 0) {
        if (current_relay < 3) {
            current_relay++;
        } else {
