        current_state = 2;
        last_state_change = time(NULL);
    } else if (current_state == 2) {
        struct timespec ts;
        ts.tv_sec = TIMER_PERIOD / 1000;
        ts.tv_nsec = (TIMER_PERIOD % 1000) * 1000000;
        nanosleep(&ts, NULL);

        current_state = current_relay < 3 ? 1 : 0;
    }
