#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <sys/time.h>
#include <sys/resource.h>
#include <sys/signalfd.h>
#include <linux/i2c-bit.h>
#include <gpiod.h>

#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define ACCEL_CONFIG 0x0C
#define PWR_MGMT_1 0x6B
#define BUFFER_SIZE 1024
#define SCALE_FACTOR 16384.0

struct mpu6050_data {
    int16_t x, y, z;
};

struct mpu6050_buffer {
    struct mpu6050_data buffer[BUFFER_SIZE];
    size_t head, tail;
};

int i2c_file;
struct mpu6050_buffer buffer;
struct signalfd_siginfo siginfo;

void mpu6050_init(void) {
    gpiod_set_value_cansleep(gpiod_get("gpiochip0", 10), 1); // SCL
    gpiod_set_value_cansleep(gpiod_get("gpiochip0", 11), 1); // SDA

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    i2c_smbus_write_byte_data(i2c_file, PWR_MGMT_1, 0x00);
    usleep(100000); // Wait for the sensor to wake up
    i2c_smbus_write_byte_data(i2c_file, ACCEL_CONFIG, 0x00);
}

void mpu6050_read_accel(struct mpu6050_data *data) {
    int16_t raw[3];

    if (i2c_smbus_read_i2c_block_data(i2c_file, ACCEL_XOUT_H, 6, (char *)raw) != 6) {
        perror("Failed to read acceleration data");
        exit(EXIT_FAILURE);
    }

    data->x = (int16_t)((raw[0] << 8) | raw[1]) * SCALE_FACTOR;
    data->y = (int16_t)((raw[2] << 8) | raw[3]) * SCALE_FACTOR;
    data->z = (int16_t)((raw[4] << 8) | raw[5]) * SCALE_FACTOR;
}

void timer_callback(int sig, siginfo_t *si, void *ucontext) {
    struct mpu6050_data data;
    mpu6050_read_accel(&data);
    buffer.buffer[buffer.head] = data;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
}

void create_sysfs_file(void) {
    int fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        perror("Failed to create sysfs file");
        exit(EXIT_FAILURE);
    }
    close(fd);
}

void sysfs_write_latest(const char *data, size_t len) {
    int fd = open("/sys/kernel/mpu6050_accel/latest", O_WRONLY);
    if (fd < 0) {
        perror("Failed to open sysfs file");
        exit(EXIT_FAILURE);
    }

    if (write(fd, data, len) != len) {
        perror("Failed to write to sysfs file");
        exit(EXIT_FAILURE);
    }

    close(fd);
}

int main(void) {
    struct itimerspec it_value, it_interval;
    struct sigaction sa;
    struct mpu6050_data data;

    mpu6050_init();

    create_sysfs_file();

    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_callback;

    it_value.it_interval.tv_sec = 0;
    it_value.it_interval.tv_nsec = 100 * 1e6; // 100 Hz
    it_value.it_value = it_value.it_interval;

    itimer_set(&it_value, &it_interval);

    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    buffer.head = buffer.tail = 0;

    while (1) {
        siginfo.si_signo = SIGEV_SIGNAL;
        siginfo.si_code = SI_TIMER;
        siginfo.si_value.sival_int = 0;

        if (signalfd_siginfo(&siginfo, sizeof(siginfo), 0) < 0) {
            perror("Failed to create signalfd");
            exit(EXIT_FAILURE);
        }

        if (read(siginfo.fd, &sa, sizeof(sa)) != sizeof(sa)) {
            perror("Failed to read signalfd");
            exit(EXIT_FAILURE);
        }

        mpu6050_read_accel(&data);

        if (buffer.head != buffer.tail) {
            sysfs_write_latest(&data, sizeof(data));
        }
    }

    close(i2c_file);
    gpiod_set_value_cansleep(gpiod_get("gpiochip0", 10), 0);
    gpiod_set_value_cansleep(gpiod_get("gpiochip0", 11), 0);
    unlink("/sys/kernel/mpu6050_accel/latest");

    return 0;
}

