#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <linux/types.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define RELAY_PIN_18 18
#define RELAY_PIN_23 23
#define RELAY_PIN_24 24
#define RELAY_PIN_25 25

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data_v1[]) {
        [RELAY_PIN_18] = { .direction = GPIOD_IN | GPIOD_OUT, },
        [RELAY_PIN_23] = { .direction = GPIOD_IN | GPIOD_OUT, },
        [RELAY_PIN_24] = { .direction = GPIOD_IN | GPIOD_OUT, },
        [RELAY_PIN_25] = { .direction = GPIOD_IN | GPIOD_OUT, },
    },
    .n_lines = ARRAY_SIZE(lines_data),
};

static gpiod_line_request *relay_requests[ARRAY_SIZE(lines_data)];

void handle_signal(int sig) {
    for (size_t i = 0; i < ARRAY_SIZE(relay_requests); ++i) {
        if (relay_requests[i]) {
            gpiod_line_release(relay_requests[i]);
            relay_requests[i] = NULL;
        }
    }
    exit(0);
}

int main(void) {
    struct timespec delay;
    struct gpiod_chip *chip;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    for (size_t i = 0; i < ARRAY_SIZE(relay_requests); ++i) {
        ret = gpiod_chip_request_lines(chip, &lines_data, &relay_requests[i]);
        if (ret < 0) {
            perror("Failed to request GPIO lines");
            goto cleanup;
        }
    }

    while (1) {
        for (size_t i = 0; i < ARRAY_SIZE(relay_requests); ++i) {
            gpiod_line_set_value(relay_requests[i], !!(i + 1 % 2));
            nanosleep((const struct timespec[]) {
                { .tv_sec = (i + 1) / 2, .tv_nsec = (i + 1) % 2 ? 500000000 : 0 },
                { .tv_sec = 0, .tv_nsec = 0 }
            }, NULL);
        }
    }

cleanup:
    for (size_t i = 0; i < ARRAY_SIZE(relay_requests); ++i) {
        if (relay_requests[i]) {
            gpiod_line_release(relay_requests[i]);
            relay_requests[i] = NULL;
        }
    }
    gpiod_chip_release(chip);
    return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

