#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <endian.h>

#define I2C_BUS 1
#define MPU_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_SENSITIVITY 131.0f
#define SAMPLE_THRESHOLD 50.0f
#define BUFFER_SIZE 100

typedef struct {
    float x, y, z;
} GyroData;

volatile sig_atomic_t running = 1;
GyroData buffer[BUFFER_SIZE];
size_t buffer_head = 0;
size_t buffer_tail = 0;

void handle_signal(int sig) {
    running = 0;
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    char data[2];
    data[0] = reg;
    data[1] = value;
    if (write(fd, data, 2) != 2) {
        perror("write");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    char data[1];
    if (write(fd, &reg, 1) != 1) {
        perror("write");
        exit(EXIT_FAILURE);
    }
    if (read(fd, data, 1) != 1) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    return data[0];
}

float i2c_read_float(int fd, uint8_t reg, size_t len) {
    char data[len];
    if (read(fd, data, len) != len) {
        perror("read");
        exit(EXIT_FAILURE);
    }
    union {
        uint8_t bytes[len];
        float f;
    } u;
    u.bytes[0] = be32toh(htole32(ntohl(data[0]) | (ntohl(htole32(data[1]) << 8) | (ntohl(htole32(data[2]) << 16) | (ntohl(htole32(data[3]) << 24)))));
    u.bytes[len - 1] = be32toh(htole32(ntohl(data[len - 1]) | (ntohl(htole32(data[len - 2]) << 8) | (ntohl(htole32(data[len - 3]) << 16) | (ntohl(htole32(data[len - 4]) << 24)))));
    for (size_t i = 1; i < len - 1; ++i) {
        u.bytes[i] = be32toh(htole32(ntohl(data[i]) | (ntohl(htole32(data[i + 1]) << 8) | (ntohl(htole32(data[i + 2]) << 16) | (ntohl(htole32(data[i + 3]) << 24)))));
    }
    return u.f;
}

void read_gyro_data(int fd) {
    uint8_t who_am_i = i2c_read_byte(fd, WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "Wrong device at address 0x%02X\n", who_am_i);
        exit(EXIT_FAILURE);
    }

    i2c_write_byte(fd, PWR_MGMT_1, 0);

    GyroData data;
    for (size_t i = 0; running && buffer_head != buffer_tail; ++i) {
        data.x = i2c_read_float(fd, GYRO_XOUT_H, 6) * GYRO_SENSITIVITY;
        data.y = i2c_read_float(fd, GYRO_YOUT_H, 6) * GYRO_SENSITIVITY;
        data.z = i2c_read_float(fd, GYRO_ZOUT_H, 6) * GYRO_SENSITIVITY;

        float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
        if (magnitude > SAMPLE_THRESHOLD) {
            printf("Absolute angular velocity exceeded: %.2f deg/s\n", magnitude);
        }

