        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    read_gyro_data(i2c_fd);

    close(i2c_fd);
    return 0;
}

