#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define BAUD 9600
#define UART_TX_PIN 14
#define UART_RX_PIN 15
#define TIMEOUT 1000000
#define JSON_FILE "co2_log.json"
#define ERROR_FILE "co2_error.log"

typedef struct {
    uint64_t timestamp;
    uint16_t ppm;
    int error;
} Co2Data;

void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp_str[32];
    char error_log_path[64];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(error_log_path, sizeof(error_log_path), "%s/%s", ERROR_FILE, timestamp_str);

    FILE *error_log = fopen(error_log_path, "a");
    if (error_log) {
        fprintf(error_log, "%s\n", message);
        fclose(error_log);
    }
}

int main() {
    int uart_fd, pigpio_fd;
    uint8_t read_buf[9];
    uint16_t co2;
    int ret, i;
    time_t rawtime;
    struct tm *timeinfo;
    struct pigpio *pi;
    const char *json_file_path = JSON_FILE;

    if ((pi = pigpio_init(NULL)) == NULL) {
        log_error("Failed to initialize pigpio library");
        return 1;
    }

    uart_fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        log_error("Failed to open serial port");
        goto cleanup;
    }

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        goto cleanup;
    }

    if (gpioSetMode(UART_TX_PIN, PI_OUTPUT) < 0 || gpioSetMode(UART_RX_PIN, PI_INPUT) < 0) {
        log_error("Failed to set GPIO modes");
        goto cleanup;
    }

    if (serialSetBaud(uart_fd, BAUD) < 0) {
        log_error("Failed to set UART baud rate");
        goto cleanup;
    }

    while (1) {
        // Send command
        for (i = 0; i < 9; i++) {
            read_buf[i] = i == 8 ? ~(sum8(read_buf, 7) + 1) : (i == 0) ? 0xFF : 0x00;
        }
        for (i = 0; i < 9; i++) {
            gpioWrite(UART_TX_PIN, read_buf[i]);
            usleep(10000);
        }
        usleep(100000);

        // Read response
        time_t start_time = time(NULL);
        int bytes_read = 0;
        while (bytes_read < 9 && (time(NULL) - start_time) < TIMEOUT / 1000.0) {
            if (serialDataAvail(uart_fd) > 0) {
                ret = read(uart_fd, &read_buf[bytes_read], 1);
                if (ret < 0) {
                    log_error("Failed to read from serial port");
                    goto cleanup;
                }
                bytes_read++;
            }
        }
        if (bytes_read != 9) {
            log_error("Incomplete response received");
            continue;
        }

        // Validate checksum
        if (read_buf[8] != ~(sum8(read_buf, 7) + 1)) {
            log_error("Invalid checksum");
            continue;
        }

        // Extract CO2
        co2 = (read_buf[2] << 8) | read_buf[3];

        // Log and print data
        rawtime = time(NULL);
        timeinfo = localtime(&rawtime);
        printf("%s,%u,%d\n", asctime(timeinfo), co2, (read_buf[8] == ~(sum8(read_buf, 7) + 1)));

        Co2Data data = {
            .timestamp = rawtime,
            .ppm = co2,
            .error = (read_buf[8] == ~(sum8(read_buf, 7) + 1))
        };

        FILE *json_file = fopen(json_file_path, "a");
        if (json_file) {
            fprintf(json_file, "%s,%u,%d\n", ctime(&data.timestamp), data.ppm, data.error);
            fflush(json_file);
        }

        sleep(5);
    }

cleanup:
    close(uart_fd);
    gpioTerm();
    pigpio_stop(pi);
    fclose(json_file);
    return 0;
}

uint8_t sum8(const uint8_t *data, size_t len) {
    uint8_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum += data[i];
    }
    return sum;
}

