            .error = (read_buf[8] == ~(sum8(read_buf, 7) + 1))
        };

        FILE *json_file = fopen(json_file_path, "a");
        if (json_file) {
            fprintf(json_file, "%s,%u,%d\n", ctime(&data.timestamp), data.ppm, data.error);
            fflush(json_file);
        }

        sleep(5);
    }

cleanup:
