    gpioTerm();
    pigpio_stop(pi);
    fclose(json_file);
    return 0;
}

uint8_t sum8(const uint8_t *data, size_t len) {
    uint8_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum += data[i];
    }
    return sum;
}
