#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define I2C_BUS 1
#define I2C_ADDR 0x23

struct bh1750_data {
    uint16_t lux;
    uint8_t error;
};

void i2c_write_byte_data(int fd, uint8_t reg, uint8_t value) {
    if (fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to talk to the I2C slave");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &value, 1) != 1) {
        perror("Failed to write value");
        exit(EXIT_FAILURE);
    }
}

int i2c_read_word_data(int fd, uint8_t reg) {
    uint8_t data[2];

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to talk to the I2C slave");
        exit(EXIT_FAILURE);
    }

    if (read(fd, &data, 2) != 2) {
        perror("Failed to read data");
        exit(EXIT_FAILURE);
    }

    data[1] = (data[1] << 8) | data[0];

    return data[1];
}

void bh1750_init(int *fd) {
    *fd = open("/dev/i2c-" I2C_BUS, O_RDWR);

    if (*fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    i2c_write_byte_data(*fd, 0x23, 0x10); // Set to continuous high-resolution mode
    usleep(120000); // Wait at least 120 ms for the first conversion
}

void log_data(const char *tag, const struct bh1750_data *data) {
    FILE *log_file = fopen("lighting_log.txt", "a");

    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s: lux=%d, R=%d G=%d B=%d\n", timestamp, data->lux,
            data->error & (1 << RED_GPIO) ? 1 : 0,
            data->error & (1 << GREEN_GPIO) ? 1 : 0,
            data->error & (1 << BLUE_GPIO) ? 1 : 0);

    fclose(log_file);
}

void gpio_setup(gpiod_line_request_flags_t flags) {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line[3];

    chip = gpiod_chip_open_byname("gpiochip0");

    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line[RED_GPIO] = gpiod_chip_get_line(chip, RED_GPIO);
    line[GREEN_GPIO] = gpiod_chip_get_line(chip, GREEN_GPIO);
    line[BLUE_GPIO] = gpiod_chip_get_line(chip, BLUE_GPIO);

    ret = gpiod_line_request_dt(line[RED_GPIO], "red_relay", flags);
    if (ret < 0) {
        perror("Failed to request red relay line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_dt(line[GREEN_GPIO], "green_relay", flags);
    if (ret < 0) {
        perror("Failed to request green relay line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_dt(line[BLUE_GPIO], "blue_relay", flags);
    if (ret < 0) {
        perror("Failed to request blue relay line");
        exit(EXIT_FAILURE);
    }
}

void gpio_cleanup(gpiod_line_set_value_cb_t cb, gpiod_line_get_value_cb_t get_cb,
                  gpiod_line_request_data_t *lines, unsigned int count) {
    unsigned int i;

    for (i = 0; i < count; ++i) {
        gpiod_line_release(lines[i].line);
    }

    gpiod_chip_close(lines[0].chip);
    gpiod_line_set_value_free(cb);
    gpiod_line_get_value_free(get_cb);
    free(lines);
}

void sigint_handler(int signum) {
    printf("Received SIGINT, exiting gracefully...\n");
    gpio_cleanup(NULL, NULL, gpio_lines, 3);
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int signum) {
    printf("Received SIGTERM, exiting gracefully...\n");
    gpio_cleanup(NULL, NULL, gpio_lines, 3);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd;
    struct bh1750_data data;
    gpiod_line_set_value_cb_t set_cb;
    gpiod_line_get_value_cb_t get_cb;
    gpiod_line_request_data_t gpio_lines[3];
    struct timespec delay;
    int ret;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    bh1750_init(&i2c_fd);

    gpio_setup(GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);

    set_cb = gpiod_line_set_value_callback(gpio_lines[RED_GPIO].line, 1, NULL);
    get_cb = gpiod_line_get_value_callback(gpio_lines[RED_GPIO].line, NULL);
    gpiod_line_request_dt(gpio_lines[RED_GPIO].line, "red_relay",
                          GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);

    set_cb = gpiod_line_set_value_callback(gpio_lines[GREEN_GPIO].line, 1, NULL);
    get_cb = gpiod_line_get_value_callback(gpio_lines[GREEN_GPIO].line, NULL);
    gpiod_line_request_dt(gpio_lines[GREEN_GPIO].line, "green_relay",
                          GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);

    set_cb = gpiod_line_set_value_callback(gpio_lines[BLUE_GPIO].line, 1, NULL);
    get_cb = gpiod_line_get_value_callback(gpio_lines[BLUE_GPIO].line, NULL);
    gpiod_line_request_dt(gpio_lines[BLUE_GPIO].line, "blue_relay",
                          GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING);

    while (1) {
        data.lux = i2c_read_word_data(i2c_fd, 0x23);
        data.error = (data.lux == 0) ? 1 : 0;

        if (data.lux < 50) {
            gpiod_line_set_value(gpio_lines[RED_GPIO].line, 1);
        } else if (data.lux >= 50 && data.lux <= 150) {
            gpiod_line_set_value(gpio_lines[GREEN_GPIO].line, 1);
            gpiod_line_set_value(gpio_lines[RED_GPIO].line, 0);
        } else if (data.lux >= 150 && data.lux <= 300) {
            gpiod_line_set_value(gpio_lines[BLUE_GPIO].line, 1);
            gpiod_line_set_value(gpio_lines[GREEN_GPIO].line, 0);
            gpiod_line_set_value(gpio_lines[RED_GPIO].line, 0);
        } else {
            gpiod_line_set_value(gpio_lines[RED_GPIO].line, 1);
            gpiod_line_set_value(gpio_lines[GREEN_GPIO].line, 1);
            gpiod_line_set_value(gpio_lines[BLUE_GPIO].line, 1);
        }

        log_data("Lux", &data);

        delay.tv_sec = 1;
        delay.tv_nsec = 0;
        nanosleep(&delay, NULL);
    }

    gpio_cleanup(set_cb, get_cb, gpio_lines, 3);
    close(i2c_fd);

    return EXIT_SUCCESS;
}

