    gpioSetMode(STEP_MOTOR_1, PI_OUTPUT);
    gpioSetMode(STEP_MOTOR_2, PI_OUTPUT);
    gpioSetMode(STEP_MOTOR_3, PI_OUTPUT);
    gpioSetMode(STEP_MOTOR_4, PI_OUTPUT);

    motor_initialized = 1;
}

void stepper_deinit(void) {
    if (!motor_initialized) {
        return;
    }

    gpioTerminate();
    motor_initialized = 0;
}

void stepper_rotate(int steps, int direction) {
    if (!motor_initialized) {
        return;
    }

    int sequence[QUARTER_TURN_STEPS][4] = {
        {1, 0, 0, 0},
        {1, 1, 0, 0},
        {0, 1, 0, 0},
        {0, 1, 1, 0},
        {0, 0, 1, 0},
        {0, 0, 1, 1},
        {0, 0, 0, 1},
