        gpioWrite(STEP_MOTOR_2, sequence[i % QUARTER_TURN_STEPS][1]);
        gpioWrite(STEP_MOTOR_3, sequence[i % QUARTER_TURN_STEPS][2]);
        gpioWrite(STEP_MOTOR_4, sequence[i % QUARTER_TURN_STEPS][3]);
        usleep(STEP_DELAY * 1000);
    }

