#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <signal.h>
#include <time.h>
#include <sys/stat.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>

#define MPU_ADDR 0x68
#define PWM_FILE "/sys/class/pwm/pwmchip2/pwm0"
#define PWM_MIN 0
#define PWM_MAX 100
#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define BUFFER_SIZE 14

struct mpu_data {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t temp;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
};

void log_data(const char *format, ...) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];
    char log_line[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    va_list args;
    va_start(args, format);
    vsnprintf(log_line, sizeof(log_line), format, args);
    va_end(args);

    strcat(log_line, ",");
    strcat(log_line, time_string);
    strcat(log_line, ",");

    FILE *log_file = fopen("solar_tracker.log", "a");
    if (log_file) {
        fputs(log_line, log_file);
        fclose(log_file);
    }
}

int i2c_write_read(int file, uint8_t reg, uint8_t *write_buf, size_t write_len, uint8_t *read_buf, size_t read_len) {
    int retries = 5;
    int result;

    while (retries > 0) {
        if ((result = write(file, write_buf, write_len)) < 0) {
            if (errno != EBUSY && errno != EAGAIN) {
                log_data("I2C write error: %s\n", strerror(errno));
                return -1;
            }
            usleep(100000 * retries);
            retries--;
            continue;
        }

        if (read_len > 0) {
            if (read(file, read_buf, read_len) < 0) {
                log_data("I2C read error: %s\n", strerror(errno));
                return -1;
            }
        }

        break;
    }

    return result;
}

int mpu_init() {
    int i2c_file;
    if ((i2c_file = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        log_data("Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, MPU_ADDR) < 0) {
        log_data("Failed to acquire I2C device: %s\n", strerror(errno));
        close(i2c_file);
        return -1;
    }

    return i2c_file;
}

void mpu_exit(int i2c_file) {
    if (i2c_file >= 0) {
        if (ioctl(i2c_file, I2C_DISABLE) < 0) {
            log_data("Failed to release I2C device: %s\n", strerror(errno));
        }
        close(i2c_file);
    }
}

int pwm_set_duty(int duty) {
    int pwm_fd;
    struct pwm_config config;

    if ((pwm_fd = open(PWM_FILE, O_WRONLY)) < 0) {
        log_data("Failed to open PWM device: %s\n", strerror(errno));
        return -1;
    }

    config.period_ns = 1000000; // 1ms period
    config.enable_polarity = 1;
    config.enable_edge = 2;
    config.duty_ns = duty * config.period_ns / PWM_MAX;

    if (ioctl(pwm_fd, PWM_SET_CONFIG, &config) < 0) {
        log_data("Failed to set PWM configuration: %s\n", strerror(errno));
        close(pwm_fd);
        return -1;
    }

    if (ioctl(pwm_fd, PWM_ENABLE, 1) < 0) {
        log_data("Failed to enable PWM: %s\n", strerror(errno));
        close(pwm_fd);
        return -1;
    }

    return pwm_fd;
}

void pwm_exit(int pwm_fd) {
    if (pwm_fd >= 0) {
        if (ioctl(pwm_fd, PWM_ENABLE, 0) < 0) {
            log_data("Failed to disable PWM: %s\n", strerror(errno));
        }
        close(pwm_fd);
    }
}

void *mpu_read_loop(void *arg) {
    int i2c_file = (int) arg;
    struct mpu_data data;
    int retries = 5;

    while (!g_exit) {
        if (i2c_write_read(i2c_file, 0x3B, (uint8_t *) &data, sizeof(data), NULL, 0) < 0) {
            if (errno != EBUSY && errno != EAGAIN) {
                usleep(100000 * retries);
                retries--;
                continue;
            }
            retries = 5;
        }

        log_data("%d,%d,%d\n", data.accel_x, data.accel_y, data.accel_z);

        // Adjust servo position based on pitch and roll values
        // ...

        usleep(100000); // 100ms loop interval
    }

    return NULL;
}

int main() {
    int i2c_file;
    pthread_t mpu_thread;
    int pwm_fd;
    gid_t gid;
    uid_t uid;

    gid = getgid();
    uid = getuid();

    if (setgid(gid) || setuid(uid)) {
        log_data("Failed to set user and group: %s\n", strerror(errno));
        return 1;
    }

    i2c_file = mpu_init();
    if (i2c_file < 0) {
        return 1;
    }

    if (pthread_create(&mpu_thread, NULL, mpu_read_loop, (void *) i2c_file) != 0) {
        log_data("Failed to create MPU thread: %s\n", strerror(errno));
        mpu_exit(i2c_file);
        return 1;
    }

    pwm_fd = pwm_set_duty(PWM_MAX / 2); // Initialize servo at center position
    if (pwm_fd < 0) {
        log_data("Failed to set PWM duty: %s\n", strerror(errno));
        mpu_exit(i2c_file);
        return 1;
    }

    signal(SIGINT, [](int signum) {
        g_exit = true;
        mpu_exit(i2c_file);
        pwm_exit(pwm_fd);
        exit(0);
    });

    signal(SIGTERM, [](int signum) {
        g_exit = true;
        mpu_exit(i2c_file);
        pwm_exit(pwm_fd);
        exit(0);
    });

    pthread_join(mpu_thread, NULL);

    mpu_exit(i2c_file);
    pwm_exit(pwm_fd);

    return 0;
}

