#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_COUNT 4
#define PWM_FREQUENCY 100
#define TRANSITION_DURATION 1800
#define SCHEDULE_FILE "lighting_schedule.txt"

static int g_relay_pins[RELAY_COUNT] = {GPIO4, GPIO17, GPIO27, GPIO22};
static int g_pwm_channels[RELAY_COUNT];
static int g_pwm_duties[RELAY_COUNT];

void sigint_handler(int signum) {
    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpioTerm(g_relay_pins[i]);
        gpioSetMode(g_relay_pins[i], 0);
    }

    gpioTermAll();
    exit(0);
}

void read_schedule() {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (!file) {
        perror("Error opening schedule file");
        return;
    }

    char line[100];
    while (fgets(line, sizeof(line), file)) {
        char time_str[10];
        char relay_str[3];
        char state[3];
        sscanf(line, "%s %s %s", time_str, relay_str, state);

        struct tm schedule_time;
        strptime(time_str, "%H:%M:%S", &schedule_time);
        int relay_number = atoi(relay_str) - 1;

        if (relay_number >= 0 && relay_number < RELAY_COUNT) {
            g_pwm_channels[relay_number] = -1;
            g_pwm_duties[relay_number] = state[0] == 'o' ? 100 : 0;
            time_t schedule_timestamp = mktime(&schedule_time);
            if (schedule_timestamp > time(NULL)) {
                struct itimerval pwm_timer;
                pwm_timer.it_interval.tv_usec = 10000;
                pwm_timer.it_value.tv_usec = pwm_timer.it_interval.tv_usec;
                setitimer(ITIMER_REAL, &pwm_timer, NULL);
                schedule_transition(relay_number);
            }
        }
    }

    fclose(file);
}

void schedule_transition(int relay_number) {
    g_pwm_channels[relay_number] = gpioSetPWM(g_relay_pins[relay_number], PWM_FREQUENCY, g_pwm_duties[relay_number]);
    if (g_pwm_channels[relay_number] < 0) {
        perror("Error setting PWM channel");
        return;
    }

    int start_duty = g_pwm_duties[relay_number];
    int end_duty = start_duty == 0 ? 100 : 0;
    int transition_steps = TRANSITION_DURATION * PWM_FREQUENCY;

    for (int i = 0; i < transition_steps; ++i) {
        g_pwm_duties[relay_number] = start_duty + (end_duty - start_duty) * i / transition_steps;
        gpioSetPWMduty(g_pwm_channels[relay_number], g_pwm_duties[relay_number]);
        usleep(10000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Error initializing GPIO");
        return 1;
    }

    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpioSetMode(g_relay_pins[i], 0);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    read_schedule();

    while (1) {
        // Your main loop logic here
    }

    return 0;
}

