#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQUENCY 200
#define MAX_FREQUENCY 2000
#define SAMPLE_RATE 50
#define GAP_TIME 60000000 // 60 ms in microseconds

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
    gpioTerm();
    exit(0);
}

void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

uint32_t echo_pulse_width() {
    uint32_t start = gpioTick();
    gpioWrite(ECHO_PIN, 1);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(ECHO_PIN, 0);
    uint32_t end = gpioTick();

    return end - start;
}

float map_distance(uint32_t pulse_width) {
    float distance = pulse_width * 17150 / 2; // Speed of sound in cm/us
    if (distance < MIN_DISTANCE) {
        return MIN_DISTANCE;
    }
    if (distance > MAX_DISTANCE) {
        return MAX_DISTANCE;
    }
    return distance;
}

float map_frequency(float distance) {
    float frequency = (MAX_FREQUENCY - MIN_FREQUENCY) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQUENCY;
    if (frequency < MIN_FREQUENCY) {
        return MIN_FREQUENCY;
    }
    if (frequency > MAX_FREQUENCY) {
        return MAX_FREQUENCY;
    }
    return frequency;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    while (running) {
        trigger_pulse();
        usleep(GAP_TIME);

        uint32_t pulse_width = echo_pulse_width();
        if (pulse_width == 0) {
            fprintf(stderr, "Failed to read echo pulse width\n");
            continue;
        }

        float distance = map_distance(pulse_width);
        float frequency = map_frequency(distance);
        gpioPWM(BUZZER_PIN, frequency);
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
    }

    gpioTerm();
    return 0;
}

