#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_RED_PIN 17
#define LED_GREEN_PIN 22
#define LED_BLUE_PIN 27
#define PWM_FREQ 1000
#define PWM_RESOLUTION 16
#define MAX_PROXIMITY 1.0

void setup_pwm(int gpio, uint32_t period_us, uint16_t duty_cycle) {
    gpio_set_mode(gpio, PI_OUTPUT);
    gpio_set_pwmfunction(gpio, PI_GPIO_HW_PWM, 0);
    gpio_set_pwmrange(gpio, PWM_RESOLUTION);
    gpio_set_pwmfrequency(gpio, PWM_FREQ);
    gpio_pwm_range(gpio, duty_cycle);
    gpio_pwm_write(gpio, 0);
}

double sine_wave(double time_us) {
    return sin(2 * M_PI * time_us / (2 * M_PI * 1000));
}

void set_color(double proximity) {
    int red = proximity * MAX_PROXIMITY;
    int green = (1 - proximity) * MAX_PROXIMITY;
    int blue = 0;

    gpio_pwm_write(LED_RED_PIN, red);
    gpio_pwm_write(LED_GREEN_PIN, green);
    gpio_pwm_write(LED_BLUE_PIN, blue);
}

void cleanup() {
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        cleanup();
    }

    setup_pwm(LED_RED_PIN, 100000, 0);
    setup_pwm(LED_GREEN_PIN, 100000, 0);
    setup_pwm(LED_BLUE_PIN, 100000, 0);

    double time_us = 0;
    while (1) {
        double proximity = sine_wave(time_us);
        set_color(proximity);
        time_us += 10000;
        usleep(10000);
    }

    // Handle SIGINT
    signal(SIGINT, cleanup);

    return 0;
}

