#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_DATA_X_LSB 0x43
#define GYRO_DATA_Y_LSB 0x45
#define GYRO_DATA_Z_LSB 0x47
#define SENSITIVITY 131.0f

struct i2c_rdwr_ioctl_data {
    struct i2c_msg msgs[2];
};

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(i2c_fd);
        gpiod_set_value_cansleep(gpio_wake, 0);
        exit(0);
    }
}

int main() {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data rdwr;
    unsigned char buf[6];
    int gpio_wake;
    struct gpiod_line_request line_req;

    gpio_wake = gpiod_get_index("gpio", "gpio2");
    if (gpio_wake < 0) {
        perror("Failed to get GPIO wake pin");
        return 1;
    }

    ret = gpiod_direction_output(gpio_wake, GPIOD_OUT_INIT_HIGH);
    if (ret < 0) {
        perror("Failed to set GPIO wake pin direction");
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    rdwr.msgs[0].addr = MPU_ADDR;
    rdwr.msgs[0].flags = 0;
    rdwr.msgs[0].len = 1;
    rdwr.msgs[0].buf = (char *)&PWR_MGMT_1;

    rdwr.msgs[1].addr = MPU_ADDR;
    rdwr.msgs[1].flags = I2C_M_RD;
    rdwr.msgs[1].len = 6;
    rdwr.msgs[1].buf = buf;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to wake up MPU-6050 or read gyro data");
        close(i2c_fd);
        gpiod_set_value_cansleep(gpio_wake, 0);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open gyro_log.txt");
        close(i2c_fd);
        gpiod_set_value_cansleep(gpio_wake, 0);
        return 1;
    }

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

    while (1) {
        ret = read(i2c_fd, buf, 6);
        if (ret != 6) {
            perror("Failed to read gyro data");
            close(i2c_fd);
            fclose(log_file);
            gpiod_set_value_cansleep(gpio_wake, 0);
            return 1;
        }

        float x = (buf[0] | buf[1] << 8) / SENSITIVITY;
        float y = (buf[2] | buf[3] << 8) / SENSITIVITY;
        float z = (buf[4] | buf[5] << 8) / SENSITIVITY;

        clock_gettime(CLOCK_MONOTONIC, &ts);
        timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

        fprintf(log_file, "%lld,%f,%f,%f\n", timestamp, x, y, z);

        usleep(100000);
    }

    close(i2c_fd);
    fclose(log_file);
    gpiod_set_value_cansleep(gpio_wake, 0);

    return 0;
}

