#define BUFFER_SIZE 4096
#define EVENT_WINDOW_SIZE 5

volatile sig_atomic_t sigint_received = 0;
struct gpiod_line *line;
struct gpiod_event_context *ctx;
struct gpiod_line_event *event;
struct timespec ts;
int log_fd;
int buffer[EVENT_WINDOW_SIZE];

void sigint_handler(int signum) {
    sigint_received = 1;
}

void log_event(int value) {
    char timestamp[32];
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%N", localtime(&now.tv_sec));

    if (log_fd < 0) {
        log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (log_fd < 0) {
            perror("Failed to open log file");
            return;
        }
    }

    if (write(log_fd, timestamp, strlen(timestamp)) < 0 ||
        write(log_fd, " ", 1) < 0 ||
        write(log_fd, &value, sizeof(value)) < 0 ||
        write(log_fd, "\n", 1) < 0) {
        perror("Failed to write to log file");
        close(log_fd);
        log_fd = -1;
    }

    if (fsync(log_fd) < 0) {
        perror("Failed to fsync log file");
    }
}

int main(int argc, char **argv) {
    int poll_timeout_ms = 1000;
    int ret;

    if (signal(SIGINT, sigint_handler) == SIG_ERR || signal(SIGTERM, sigint_handler) == SIG_ERR) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    line = gpiod_chip_get_line(gpiod_chip_get_by_name(GPIO_CHIP_NAME), GPIO_LINE_NAME);
    if (!line) {
        perror("Failed to get line");
        return 1;
    }

    ret = gpiod_line_request_input(line, GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH);
    if (ret < 0) {
        perror("Failed to request input");
        goto cleanup;
    }

    ctx = gpiod_line_get_event_context(line);
    if (!ctx) {
        perror("Failed to get event context");
        goto cleanup;
    }

    ret = gpiod_line_event_context_set_debounce(ctx, 10);
    if (ret < 0) {
        perror("Failed to set debounce");
        goto cleanup;
    }

    log_fd = -1;

    while (!sigint_received) {
        ret = gpiod_line_event_wait(ctx, GPIOD_LINE_EVENT_EDGE_RISING | GPIOD_LINE_EVENT_EDGE_FALLING, poll_timeout_ms);
        if (ret < 0) {
            perror("Failed to wait for event");
            continue;
        }

        event = gpiod_line_event_get(ctx);
        if (!event) {
            perror("Failed to get event");
            continue;
        }

        log_event(event->value);
        buffer[event->value ? (EVENT_WINDOW_SIZE - 1) : 0] = event->value;
        int count = 0;
        for (int i = 0; i < EVENT_WINDOW_SIZE; ++i) {
            if (buffer[i]) {
                ++count;
            }
        }
        if (count >= 3) {
            printf("EARTHQUAKE ALERT: %s\n", timestamp);
        }

        gpiod_line_event_put(event);
    }

    gpiod_line_release(line);
    gpiod_line_event_context_put(ctx);
    if (log_fd >= 0) {
        close(log_fd);
    }

    return 0;

cleanup:
    if (log_fd >= 0) {
        close(log_fd);
    }
    gpiod_line_release(line);
    gpiod_line_event_context_put(ctx);
    return ret < 0 ? 1 : 0;
}

