#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>

#define I2C_BUS 1
#define MAG_ADDR 0x1E
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20
#define SAMPLE_RATE 15
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define X_MSB_REG 0x03
#define X_LSB_REG 0x04
#define Z_MSB_REG 0x06
#define Z_LSB_REG 0x07
#define Y_MSB_REG 0x05
#define Y_LSB_REG 0x08

static int i2c_fd;
static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int init_i2c() {
    const char *dev_name = "/dev/i2c-" I2C_BUS;
    i2c_fd = open(dev_name, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MAG_ADDR << 1) < 0) {
        perror("Failed to acquire I2C slave address");
        close(i2c_fd);
        return -1;
    }

    if (ioctl(i2c_fd, I2C_CLIENT_FD, i2c_fd) < 0) {
        perror("Failed to register I2C client");
        close(i2c_fd);
        return -1;
    }

    if (write_reg16(MR_REG_M, 0x00) < 0) {
        perror("Failed to configure continuous-conversion mode");
        return -1;
    }

    if (write_reg16(CRA_REG_M, SAMPLE_RATE << 3) < 0) {
        perror("Failed to set output data rate");
        return -1;
    }

    return 0;
}

int write_reg16(uint8_t reg, uint16_t value) {
    uint8_t data[2];
    data[0] = (reg << 1) | 0x01;
    data[1] = value;
    return write(i2c_fd, data, sizeof(data));
}

int read_reg16(uint8_t reg, uint16_t *value) {
    uint8_t data[2];
    data[0] = (reg << 1);
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to write I2C register");
        return -1;
    }

    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read I2C register");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

float calibrate_value(int16_t value, int offset) {
    return value + offset;
}

float atan2_degrees(float y, float x) {
    float radians = atan2f(y, x);
    return (radians * 180.0) / M_PI;
}

void log_data(const char *filename, uint32_t timestamp, int16_t x, int16_t y, int16_t z, float heading) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    if (fprintf(file, "%lu,%d,%d,%d,%f,%f\n", timestamp, x, y, z, heading, heading) < 0) {
        perror("Failed to write to CSV file");
    }
    fclose(file);
}

int main() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint32_t last_timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;
    int16_t x, y, z;
    float heading;
    char mag_log_path[32] = "mag_log.csv";

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_i2c() < 0) {
        return 1;
    }

    if (access(mag_log_path, F_OK) == -1) {
        FILE *file = fopen(mag_log_path, "w");
        if (!file) {
            perror("Failed to create CSV file");
            return 1;
        }

        if (fprintf(file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n") < 0) {
            perror("Failed to write header to CSV file");
        }
        fclose(file);
    }

    while (running) {
        if (read_reg16(X_MSB_REG, &x) < 0 || read_reg16(X_LSB_REG, &x) < 0 ||
            read_reg16(Z_MSB_REG, &z) < 0 || read_reg16(Z_LSB_REG, &z) < 0 ||
            read_reg16(Y_MSB_REG, &y) < 0 || read_reg16(Y_LSB_REG, &y) < 0) {
            perror("Failed to read I2C registers");
            continue;
        }

        x = calibrate_value(x, X_OFFSET);
        y = calibrate_value(y, Y_OFFSET);
        z = calibrate_value(z, Z_OFFSET);

        heading = atan2_degrees(y, x);
        if (heading < 0) {
            heading += 360;
        }

        log_data(mag_log_path, last_timestamp, x, y, z, heading);
        last_timestamp += 1000000000;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        usleep((1000000000 / SAMPLE_RATE) - (ts.tv_nsec));
    }

    close(i2c_fd);
    return 0;
}

