#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEBOUNCE_TIME_MS 200
#define JSON_BUFFER_SIZE 256

typedef struct {
    char timestamp[32];
    char state[9];
} RelayLogEntry;

int main(void) {
    int fd;
    char json_buffer[JSON_BUFFER_SIZE];
    RelayLogEntry log_entry;
    uint32_t last_touch_time = 0;
    int touch_state = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    gpioSetMode(TOUCH_GPIO, PI_INPUT);
    gpioSetPullUpDown(TOUCH_GPIO, PI_PUD_DOWN);
    gpioSetISRFunc(TOUCH_GPIO, handleTouchISR);
    gpioSetAlertFunc(TOUCH_GPIO, handleTouchISR);

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    fd = open("relay_log.json", O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        perror("Failed to open relay_log.json");
        return 1;
    }

    signal(SIGINT, handleSIGINT);

    while (1) {
        usleep(100000); // Sleep for 100 ms to reduce CPU usage

        if (gpioRead(TOUCH_GPIO) == 1 && (time(NULL) - last_touch_time) > DEBOUNCE_TIME_MS) {
            last_touch_time = time(NULL);
            touch_state = !touch_state;
            gpioWrite(RELAY_GPIO, touch_state);

            snprintf(log_entry.timestamp, sizeof(log_entry.timestamp), "%s", ctime(&last_touch_time));
            snprintf(log_entry.state, sizeof(log_entry.state), "%s", touch_state ? "ON" : "OFF");

            write(fd, &log_entry, sizeof(RelayLogEntry));
        }
    }

    close(fd);
    gpioTerminate();
    return 0;
}

void handleTouchISR(int gpio, uint32_t event) {
    (void)event; // Unused parameter

    if (gpio != TOUCH_GPIO)
        return;

    if (gpioRead(TOUCH_GPIO) == 0) {
        gpioSetISRFunc(TOUCH_GPIO, handleTouchISR);
        return;
    }

    gpioSetISRFunc(TOUCH_GPIO, NULL);
}

void handleSIGINT(int sig) {
    gpioWrite(RELAY_GPIO, 0);
    gpioSetISRFunc(TOUCH_GPIO, NULL);
    gpioTerminate();
    exit(0);
}

