#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <sys/time.h>
#include <signal.h>
#include <libgpiod.h>

#define RELAY_COUNT 4
#define RELAY_GPIO_CHIPS {1, 2, 3, 4}
#define RELAY_GPIO_LINES {17, 23, 24, 25}
#define LOG_FILE "irrigation_log.txt"

static gpiod_chip *gpios[ARRAY_SIZE(RELAY_GPIO_CHIPS)];
static gpiod_line_request_lines_data_v1 lines_data;
static gpiod_line_request_flags_v1 lines_flags = GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
static int log_fd;

void log_message(const char *format, ...) {
    va_list args;
    time_t now;
    struct tm *tm_now;
    char timestamp[32];

    time(&now);
    tm_now = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    va_start(args, format);
    vfprintf(stderr, timestamp, args);
    vfprintf(stderr, format, args);
    va_end(args);
    fprintf(stderr, "\n");
}

void log_irrigation_event(int relay, int moisture) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s relay %d: moisture %d\n", timestamp, relay, moisture);
    fflush(log_file);
    fclose(log_file);
}

void activate_relay(int relay) {
    gpiod_line_set_value(gpios[RELAY_GPIO_CHIPS[relay]], RELAY_GPIO_LINES[relay], 0);
    usleep(5000000);
    gpiod_line_set_value(gpios[RELAY_GPIO_CHIPS[relay]], RELAY_GPIO_LINES[relay], 1);
    usleep(1000000);
}

void irrigate(int *moisture) {
    for (int i = 0; i < RELAY_COUNT; ++i) {
        if (*moisture < 30) {
            activate_relay(i);
            log_irrigation_event(i, *moisture);
        }
        usleep(1000000);
        *moisture = rand() % 101;
    }
}

void setup_gpios() {
    int ret;
    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpios[i] = gpiod_chip_open_by_name(RELAY_GPIO_CHIPS[i]);
        if (!gpios[i]) {
            perror("gpiod_chip_open_by_name");
            exit(EXIT_FAILURE);
        }

        ret = gpiod_line_request_get_request_lines_data_v1(gpios[i], &lines_data);
        if (ret < 0) {
            perror("gpiod_line_request_get_request_lines_data_v1");
            exit(EXIT_FAILURE);
        }

        lines_data.lines = RELAY_GPIO_LINES[i];
        lines_data.count = 1;
        lines_data.flags = lines_flags;

        ret = gpiod_line_request_set_request_lines_data_v1(gpios[i], &lines_data);
        if (ret < 0) {
            perror("gpiod_line_request_set_request_lines_data_v1");
            exit(EXIT_FAILURE);
        }
    }
}

void teardown_gpios() {
    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_release(gpios[i], RELAY_GPIO_LINES[i]);
    }

    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpiod_chip_close(gpios[i]);
    }
}

void teardown_log() {
    if (log_fd >= 0) {
        fclose(log_fd);
    }
}

void signal_handler(int signum) {
    log_message("Received signal %d, deactivating relays and exiting...", signum);
    teardown_gpios();
    teardown_log();
    exit(EXIT_SUCCESS);
}

int main() {
    int moisture = rand() % 101;
    srand(time(NULL));

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    setup_gpios();

    while (1) {
        irrigate(&moisture);
        sleep(10);
    }

    teardown_gpios();
    teardown_log();

    return EXIT_SUCCESS;
}

