#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define MOISTURE_THRESHOLD 50
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_SWEEP_DELAY 2000
#define SERVO_RETRY_DELAY 100
#define WAIT_BEFORE_READING 5000
#define MOISTURE_CYCLE_VALUES_COUNT 5

volatile sig_atomic_t sigint_received = 0;
volatile sig_atomic_t sigterm_received = 0;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioServo(VALVE_PIN, 0);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    int moisture_values[MOISTURE_CYCLE_VALUES_COUNT] = {20, 40, 60, 80, 100};
    int moisture_index = 0;
    int ret;

    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialise pigpio library: %s\n", gpioStrerror(ret));
        exit(1);
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        if (sigint_received || sigterm_received) {
            break;
        }

        if (moisture_values[moisture_index] < MOISTURE_THRESHOLD) {
            printf("Watering...\n");

            ret = gpioServo(VALVE_PIN, SERVO_MAX);
            if (ret < 0 && gpioTerm(ret) < 0) {
                fprintf(stderr, "Failed to open valve servo: %s\n", gpioStrerror(ret));
                exit(1);
            }

            for (int angle = 0; angle < MOISTURE_CYCLE_VALUES_COUNT; angle++) {
                ret = gpioServo(NOZZLE_PIN, angle * (SERVO_MAX - SERVO_MIN) / MOISTURE_CYCLE_VALUES_COUNT + SERVO_MIN);
                if (ret < 0 && gpioTerm(ret) < 0) {
                    fprintf(stderr, "Failed to set nozzle servo to angle %d: %s\n", angle, gpioStrerror(ret));
                    continue;
                }
                usleep(SERVO_SWEEP_DELAY);
            }

            usleep(5 * 1000000);

            ret = gpioServo(VALVE_PIN, SERVO_MIN);
            if (ret < 0 && gpioTerm(ret) < 0) {
                fprintf(stderr, "Failed to close valve servo: %s\n", gpioStrerror(ret));
                fprintf(stderr, "Warning: watering cycle may not have completed properly.\n");
            }

            usleep(5 * 1000000);
        } else {
            printf("Skipping watering...\n");
            usleep(WAIT_BEFORE_READING);
        }

        moisture_index = (moisture_index + 1) % MOISTURE_CYCLE_VALUES_COUNT;
        usleep(WAIT_BEFORE_READING);
    }

    gpioTerminate();
    return 0;
}

