#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <gpiod.h>

#define I2C_BUS 1
#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define SENSITIVITY 131.0f

struct gyro_data {
    uint16_t x;
    uint16_t y;
    uint16_t z;
};

void sigint_handler(int signum) {
    printf("\nExiting...\n");
    close(i2c_fd);
    gpiod_release(gpio_chip);
    exit(0);
}

int main() {
    int i2c_fd, ret;
    struct i2c_rdwr_ioctl_data i2c_msg[2];
    struct gyro_data gyro_data;
    struct timespec ts;
    FILE *log_file;
    gpiod_line_callback_t callback;
    gpiod_line_data_t line_data;
    gpiod_chip *gpio_chip;
    gpiod_line *gpio_line;
    int gpio_line_num = 18; // GPIO18 for wake-up signal

    // Open I2C device
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU_ADDR) < 0) {
        perror("Failed to set slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO for wake-up signal
    gpio_chip = gpiod_chip_open_byname("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, gpio_line_num);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_put(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_line_request_dt(gpio_line, "wake_up");
    gpiod_line_set_value(gpio_line, 1);

    // Set wake-up signal callback
    callback.line = gpio_line;
    callback.edge = GPIOD_EDGE_RISING;
    callback.debounce = 10;
    callback.consumer = "MPU-6050 wake-up";
    gpiod_line_set_debounce(gpio_line, &callback);
    gpiod_line_add_callback(gpio_line, &callback);

    // Configure I2C messages
    i2c_msg[0].addr = MPU_ADDR;
    i2c_msg[0].flags = 0;
    i2c_msg[0].len = 1;
    i2c_msg[0].buf = &PWR_MGMT_1;

    i2c_msg[1].addr = MPU_ADDR;
    i2c_msg[1].flags = I2C_M_RD | I2C_M_CONT;
    i2c_msg[1].len = 6;
    i2c_msg[1].buf = (char *)&gyro_data;

    // Signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_remove_callback(gpio_line, &callback);
        gpiod_line_set_value(gpio_line, 0);
        gpiod_line_release(gpio_line);
        gpiod_chip_put(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    clock_gettime(CLOCK_MONOTONIC, &ts);
    float last_timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

    while (1) {
        // Write wake-up command
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg);
        if (ret < 0) {
            perror("Failed to write wake-up command");
            continue;
        }

        // Read gyroscope data with burst read
        ret = ioctl(i2c_fd, I2C_RDWR, i2c_msg + 1);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            continue;
        }

        // Convert raw data to degrees/second
        gyro_data.x = ((gyro_data.x << 8) | gyro_data.x >> 8) * SENSITIVITY;
        gyro_data.y = ((gyro_data.y << 8) | gyro_data.y >> 8) * SENSITIVITY;
        gyro_data.z = ((gyro_data.z << 8) | gyro_data.z >> 8) * SENSITIVITY;

        // Calculate timestamp
        clock_gettime(CLOCK_MONOTONIC, &ts);
        float timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

        // Log data
        fprintf(log_file, "%f,%f,%f\n", timestamp - last_timestamp, gyro_data.x, gyro_data.y, gyro_data.z);
        last_timestamp = timestamp;

        // Wait for 100ms (10 Hz)
        usleep(100000);
    }

    fclose(log_file);
    gpiod_line_remove_callback(gpio_line, &callback);
    gpiod_line_set_value(gpio_line, 0);
    gpiod_line_release(gpio_line);
    gpiod_chip_put(gpio_chip);
    close(i2c_fd);

    return 0;
}

