#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define STEPS_PER_REVOLUTION 2048
#define STEPS_PER_QUARTER_TURN (STEPS_PER_REVOLUTION / 4)
#define DEBOUNCE_DELAY 50
#define STEP_DELAY 3

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
    gpioTerminate();
}

void stepper_rotate(int steps, int direction) {
    int coil_pins[4] = {GPIO4, GPIO17, GPIO27, GPIO22};

    for (int i = 0; i < steps; ++i) {
        gpioSetMode(coil_pins[direction], PI_OUTPUT);
        gpioWrite(coil_pins[direction], GPIO_HIGH);
        gpioSetMode(coil_pins[(direction + 1) % 4], PI_OUTPUT);
        gpioWrite(coil_pins[(direction + 1) % 4], GPIO_LOW);
        usleep(STEP_DELAY * 1000);
        gpioSetMode(coil_pins[direction], PI_INPUT);
        gpioSetMode(coil_pins[(direction + 1) % 4], PI_INPUT);
    }
}

int main(void) {
    int lock_pin = GPIO24;
    int unlock_pin = GPIO23;
    int status;

    if ((status = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialise pigpio library: %s\n", gpioStrerror(status));
        return 1;
    }

    gpioSetMode(lock_pin, PI_INPUT);
    gpioSetPullUpDown(lock_pin, PI_PUD_UP);
    gpioSetMode(unlock_pin, PI_INPUT);
    gpioSetPullUpDown(unlock_pin, PI_PUD_UP);

    signal(SIGINT, signal_handler);

    while (running) {
        usleep(DEBOUNCE_DELAY * 1000);

        if (gpioRead(lock_pin) == GPIO_LOW) {
            printf("Locking...\n");
            stepper_rotate(STEPS_PER_QUARTER_Turn, 0);
        }

        usleep(DEBOUNCE_DELAY * 1000);

        if (gpioRead(unlock_pin) == GPIO_LOW) {
            printf("Unlocking...\n");
            stepper_rotate(STEPS_PER_QUARTER_TURN, 2);
        }
    }

    gpioTerminate();
    return 0;
}

