#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_LINE_GPIO 17
#define ECHO_LINE_GPIO 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 50000
#define DURATION_US_TO_CM (343.0 / (2 * 1000000.0))
#define GUARD_TIME_US 60000

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request *trigger_req, *echo_req;
    struct timespec start, end;
    long duration_us;
    double distance_cm;
    int fd;
    int ret;

    // Initialize GPIO
    if (!(chip = gpiod_chip_open_by_name("gpiochip0"))) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    // Request trigger line as output with active-high polarity
    if (!(trigger_req = gpiod_line_request_create(chip, TRIGGER_LINE_GPIO))) {
        fprintf(stderr, "Failed to create trigger line request: %s\n", strerror(errno));
        goto cleanup_chip;
    }
    if (gpiod_line_request_direction_output(trigger_req, GPIOD_LINE_ACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to set trigger line direction: %s\n", strerror(errno));
        goto cleanup_request_trigger;
    }

    // Request echo line as input with active-high polarity
    if (!(echo_req = gpiod_line_request_create(chip, ECHO_LINE_GPIO))) {
        fprintf(stderr, "Failed to create echo line request: %s\n", strerror(errno));
        goto cleanup_request_trigger;
    }
    if (gpiod_line_request_direction_input(echo_req, GPIOD_LINE_ACTIVE_HIGH) < 0) {
        fprintf(stderr, "Failed to set echo line direction: %s\n", strerror(errno));
        goto cleanup_request_echo;
    }

    // Open log file
    fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        goto cleanup_request_echo;
    }

    // Main loop
    while (1) {
        // Generate a 10 microsecond high pulse on the trigger line
        gpiod_line_set_value(trigger_req, 1);
        usleep(10);
        gpiod_line_set_value(trigger_req, 0);

        // Wait for the echo line to go high
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_req) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0 || (end.tv_sec - start.tv_sec) * 1000000 + end.tv_nsec / 1000 >= TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo line to go high\n");
                goto log_and_cleanup;
            }
        }

        // Measure the echo pulse width
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_req) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) < 0 || (end.tv_sec - start.tv_sec) * 1000000 + end.tv_nsec / 1000 >= TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo line to go low\n");
                goto log_and_cleanup;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + end.tv_nsec / 1000 - (start.tv_sec * 1000000 + start.tv_nsec / 1000);

        // Calculate and log the distance
        if (duration_us > 0) {
            distance_cm = duration_us * DURATION_US_TO_CM;
            if (fprintf(fd, "%.2f\n", distance_cm) < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                goto log_and_cleanup;
            }
        } else {
            if (fprintf(fd, "-1\n") < 0) {
                fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
                goto log_and_cleanup;
            }
        }

        // Wait for the guard time
        usleep(GUARD_TIME_US);
    }

log_and_cleanup:
    // Close log file
    if (fd >= 0) {
        close(fd);
    }

cleanup_request_echo:
    // Release echo line request
    if (echo_req) {
        gpiod_line_request_release(echo_req);
    }

cleanup_request_trigger:
    // Release trigger line request
    if (trigger_req) {
        gpiod_line_request_release(trigger_req);
    }

cleanup_chip:
    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Exit on SIGINT/SIGTERM
    return 0;
}

