#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RELAY_GPIO 18

static int i2c_file;
static int i2c_status;
static int i2c_data[2];

void vl53l1x_soft_reset() {
    i2c_data[0] = 0x00;
    i2c_data[1] = 0x00;
    i2c_status = i2c_smbus_i2c_write_data(i2c_file, VL53L1X_ADDR, 2, i2c_data);
    if (i2c_status < 0) {
        perror("i2c_smbus_i2c_write_data");
        exit(EXIT_FAILURE);
    }
}

void vl53l1x_init() {
    i2c_data[0] = 0x01;
    i2c_data[1] = 0x00;
    i2c_data[2] = 0x00;
    i2c_data[3] = 0x00;
    i2c_data[4] = 0x00;
    i2c_data[5] = 0x00;
    i2c_data[6] = 0x00;

    i2c_status = i2c_smbus_i2c_write_data(i2c_file, VL53L1X_ADDR, 7, i2c_data);
    if (i2c_status < 0) {
        perror("i2c_smbus_i2c_write_data");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int gpio_status;
    uint16_t distance;

    if ((i2c_file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("ioctl");
        exit(EXIT_FAILURE);
    }

    vl53l1x_soft_reset();
    vl53l1x_init();

    gpioInitialise();
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(RELAY_GPIO, 50); // Set PWM frequency for smooth relay operation

    while (1) {
        usleep(100000); // Wait 100 ms

        i2c_data[0] = 0x00;
        i2c_status = i2c_smbus_read_byte_data(i2c_file, 0x0044);
        if (i2c_status < 0) {
            perror("i2c_smbus_read_byte_data");
            continue;
        }

        if ((i2c_data[0] & 0x01) == 0x01) { // Data ready
            i2c_status = i2c_smbus_read_word_data(i2c_file, 0x0096);
            if (i2c_status < 0) {
                perror("i2c_smbus_read_word_data");
                continue;
            }
            distance = (i2c_data[0] << 8) | i2c_data[1];
            printf("Distance: %d cm\n", distance);

            if (distance <= 50) {
                gpioWrite(RELAY_GPIO, 1);
            } else {
                gpioWrite(RELAY_GPIO, 0);
            }
        }
    }

    gpioTerm();
    close(i2c_file);
    gpioTerm();
    return 0;
}

