#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B

int main() {
    int file;
    int ret;
    char buf[14];
    ssize_t bytes_read;
    struct i2c_rdwr_ioctl_data data;
    struct i2c_msg msgs[2];

    gpiod_line_request_dt(NULL, "rpi,gpio-gpio", GPIO_REQUEST_DIR_OUTPUT, "mpu_reset", NULL);
    gpiod_set_value_cansleep(gpio_get_line(0, "rpi,gpio-gpio"), 1);
    usleep(100000);
    gpiod_set_value_cansleep(gpio_get_line(0, "rpi,gpio-gpio"), 0);
    usleep(100000);

    if ((file = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open i2c device");
        exit(1);
    }

    if (ioctl(file, I2C_SLAVE, MPU_ADDR) < 0) {
        perror("Failed to acquire bus access");
        exit(1);
    }

    msgs[0].addr = MPU_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &PWR_MGMT_1;

    msgs[1].addr = MPU_ADDR;
    msgs[1].flags = I2C_M_NOSTART;
    msgs[1].len = 1;
    msgs[1].buf = &PWR_MGMT_1;
    msgs[1].buf[0] = 0x00; // Wake up the sensor

    data.wr_msgs = &msgs[0];
    data.n_msgs = 2;
    ret = ioctl(file, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to write to MPU-6050");
        exit(1);
    }

    usleep(4000); // Wait for the sensor to wake up

    msgs[0].addr = MPU_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &GYRO_CONFIG;
    msgs[0].buf[0] = 0x18; // Set the gyroscope full-scale range to ±250 dps

    data.wr_msgs = &msgs[0];
    data.n_msgs = 1;
    ret = ioctl(file, I2C_RDWR, &data);
    if (ret < 0) {
        perror("Failed to write to MPU-6050");
        exit(1);
    }

    while (1) {
        msgs[0].addr = MPU_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 6;
        msgs[0].buf = buf;
        msgs[1].addr = MPU_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 6;
        msgs[1].buf = buf + 6;

        data.wr_msgs = &msgs[0];
        data.rd_msgs = &msgs[1];
        data.n_msgs = 2;
        ret = ioctl(file, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read from MPU-6050");
            exit(1);
        }

        if (msgs[1].len != 6) {
            fprintf(stderr, "Unexpected number of bytes read from MPU-6050\n");
            exit(1);
        }

        int16_t x = (buf[0] << 8) | buf[1];
        int16_t y = (buf[2] << 8) | buf[3];
        int16_t z = (buf[4] << 8) | buf[5];

        printf("x: %d dps, y: %d dps, z: %d dps\n", x * 131.0, y * 131.0, z * 131.0);

        usleep(10000); // Sample rate of 100 Hz
    }

    close(file);
    gpiod_line_release(gpio_get_line(0, "rpi,gpio-gpio"));

    return 0;
}

