#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <libgpiod.h>

#define RELAY_COUNT 4
#define DELAY_BETWEEN_WATERINGS 86400
#define POLL_INTERVAL 60

static gpiod_chip *chip;
static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = {
        [0] = { .direction = GPIOD_IN, .edge_detected_callback = NULL },
        [1] = { .direction = GPIOD_IN, .edge_detected_callback = NULL },
        [2] = { .direction = GPIOD_IN, .edge_detected_callback = NULL },
        [3] = { .direction = GPIOD_IN, .edge_detected_callback = NULL },
    },
    .request_lines_flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW,
};

static gpiod_line_array relay_lines[RELAY_COUNT];

static void sigint_handler(int signum) {
    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_set_value(relay_lines[i], 1);
    }

    gpiod_line_request_release(relay_lines[0]);
    gpiod_line_request_release(relay_lines[1]);
    gpiod_line_request_release(relay_lines[2]);
    gpiod_line_request_release(relay_lines[3]);

    gpiod_chip_release(chip);
    exit(0);
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpiod_library_init() < 0) {
        perror("gpiod_library_init");
        return 1;
    }

    if ((chip = gpiod_chip_open_byname("gpiochip0")) == NULL) {
        perror("gpiod_chip_open_byname");
        gpiod_library_exit();
        return 1;
    }

    if (gpiod_line_request_array_configure(chip, RELAY_COUNT, &lines_data, NULL) < 0) {
        perror("gpiod_line_request_array_configure");
        gpiod_chip_release(chip);
        gpiod_library_exit();
        return 1;
    }

    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        relay_lines[i] = lines_data.lines[i].request_line;
        gpiod_line_set_value(relay_lines[i], 1);
    }

    time_t last_watering = time(NULL);
    while (1) {
        time_t current_time = time(NULL);

        if (difftime(current_time, last_watering) >= DELAY_BETWEEN_WATERINGS) {
            for (size_t i = 0; i < RELAY_COUNT; ++i) {
                gpiod_line_set_value(relay_lines[i], 0);
                sleep(5);
                gpiod_line_set_value(relay_lines[i], 1);
            }

            last_watering = current_time;
            char log_time[32];
            strftime(log_time, sizeof(log_time), "%Y-%m-%d %H:%M:%S", localtime(&last_watering));
            FILE *log_file = fopen("watering_log.txt", "a");
            if (log_file) {
                fprintf(log_file, "%s\n", log_time);
                fclose(log_file);
            } else {
                perror("fopen");
            }
        }

        sleep(POLL_INTERVAL);
    }

    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_request_release(relay_lines[i]);
    }

    gpiod_chip_release(chip);
    gpiod_library_exit();

    return 0;
}

