    }

    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        relay_lines[i] = lines_data.lines[i].request_line;
        gpiod_line_set_value(relay_lines[i], 1);
    }

    time_t last_watering = time(NULL);
    while (1) {
        time_t current_time = time(NULL);

        if (difftime(current_time, last_watering) >= DELAY_BETWEEN_WATERINGS) {
            for (size_t i = 0; i < RELAY_COUNT; ++i) {
                gpiod_line_set_value(relay_lines[i], 0);
                sleep(5);
                gpiod_line_set_value(relay_lines[i], 1);
            }

            last_watering = current_time;
            char log_time[32];
            strftime(log_time, sizeof(log_time), "%Y-%m-%d %H:%M:%S", localtime(&last_watering));
            FILE *log_file = fopen("watering_log.txt", "a");
            if (log_file) {
                fprintf(log_file, "%s\n", log_time);
                fclose(log_file);
            } else {
                perror("fopen");
            }
        }

        sleep(POLL_INTERVAL);
    }

    for (size_t i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_request_release(relay_lines[i]);
    }

    gpiod_chip_release(chip);
    gpiod_library_exit();

    return 0;
}
