#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE 20
#define FS_RANGE 250.0

typedef struct {
    int16_t x, y, z;
    uint64_t timestamp;
} GyroData;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
GyroData buffer[BUFFER_SIZE];
int buffer_head = 0, buffer_tail = 0;

volatile int running = 1;

void *gyro_read_thread(void *arg) {
    while (running) {
        uint8_t data[6];
        int ret;

        for (int i = 0; i < 3; i++) {
            ret = i2cReadReg16_Rep(I2C_BUS, 0x68, 0x43 + i * 2, data + i * 2, 2);
            if (ret != 2) {
                usleep(500000); // Retry after 0.5ms
                if (ret != 2) {
                    fprintf(stderr, "Failed to read gyro data\n");
                    running = 0;
                    break;
                }
            }
        }

        GyroData *data_ptr = &buffer[buffer_head];
        data_ptr->x = (int16_t)((data[0] << 8) | data[1]);
        data_ptr->y = (int16_t)((data[2] << 8) | data[3]);
        data_ptr->z = (int16_t)((data[4] << 8) | data[5]);
        data_ptr->timestamp = get_monotonic_time_us();
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;

        pthread_mutex_lock(&buffer_mutex);
        if ((buffer_head - buffer_tail) >= BUFFER_SIZE) {
            // Buffer overflow, discard old data
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }
        pthread_mutex_unlock(&buffer_mutex);
    }

    return NULL;
}

void check_led(void) {
    int16_t x = buffer[buffer_tail].x, y = buffer[buffer_tail].y, z = buffer[buffer_tail].z;
    if (abs(x) > FS_RANGE || abs(y) > FS_RANGE || abs(z) > FS_RANGE) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

uint64_t get_monotonic_time_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

int i2cReadReg16_Rep(int bus, uint8_t address, uint8_t reg, uint8_t *data, int len) {
    int ret = i2cReadRegisters(bus, address, reg, data, len);
    if (ret < 0) {
        fprintf(stderr, "Failed to read I2C data: %s\n", gpioStrerror(gpioLastError()));
        return -1;
    }
    return ret;
}

void sigint_handler(int signum) {
    running = 0;
    gpioWrite(LED_PIN, 0);
    i2cClose(I2C_BUS);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library: %s\n", gpioStrerror(gpioLastError()));
        return 1;
    }

    if (gpioSetMode(SCL_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SDA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes: %s\n", gpioStrerror(gpioLastError()));
        gpioTerminate();
        return 1;
    }

    gpioSetMode(SCL_PIN, PI_INPUT);
    gpioSetMode(SDA_PIN, PI_INPUT);

    if (i2cOpen(I2C_BUS, 0, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpioStrerror(gpioLastError()));
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg16(I2C_BUS, 0x68, 0x6B, 0x00) < 0 ||
        i2cWriteReg16(I2C_BUS, 0x68, 0x19, 0x07) < 0 ||
        i2cWriteReg16(I2C_BUS, 0x68, 0x1B, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MPU-6050 registers: %s\n", gpioStrerror(gpioLastError()));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    if (i2cReadReg16(I2C_BUS, 0x68, 0x75) != 0x68) {
        fprintf(stderr, "Wrong WHO_AM_I value, MPU-6050 not found\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, gyro_read_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create gyro read thread: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct timespec period;
    period.tv_sec = 0;
    period.tv_nsec = 50000000; // 50ms

    while (running) {
        nanosleep(&period, NULL);
        check_led();
    }

    pthread_join(thread_id, NULL);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

