        .delay_usecs = 0,
    },
};

int spi_fd, gpio_cs_fd;
gpiod_line_request_data gpio_cs_req;

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) != 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_SPEED) != 0) {
        perror("Failed to get max SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) != 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) != 0) {
        perror("Failed to set SPI bits per word");
        exit(EXIT_FAILURE);
   }

    gpio_cs_fd = gpiod_chip_open_named_global(CS_GPIO_CHIP);
    if (gpio_cs_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_configure(&gpio_cs_req, gpio_cs_fd, CS_GPIO_LINE, GPIOD_IN | GPIOD_ACTIVE_LOW, "MPU-9250 CS");
    gpiod_line_request_enable(&gpio_cs_req);
}

void spi_transfer(const uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    gpiod_line_set_value(gpio_cs_fd, CS_GPIO_LINE, 0);
    if (write(spi_fd, tx_buf, len) != len) {
        perror("Failed to write to SPI device");
    }
    if (read(spi_fd, rx_buf, len) != len) {
        perror("Failed to read from SPI device");
    }
    gpiod_line_set_value(gpio_cs_fd, CS_GPIO_LINE, 1);
}

int16_t spi_read_reg16(uint8_t reg) {
    uint8_t buf[2];
    spi_transfer(&reg, buf, 1);
    spi_transfer(NULL, buf + 1, 1);
    return (buf[0] << 8) | buf[1];
}

