code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <math.h>
#include <time.h>
#include <pigpio.h>

#define MPU_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C

#define GPIO_LED 21

static char log_file[] = "tilt_log.txt";

void log_data(const char *format, ...) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];
    FILE *log_fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_fp = fopen(log_file, "a");
    if (log_fp == NULL) {
        perror("fopen");
        return;
    }

    va_list args;
    va_start(args, format);
    vfprintf(log_fp, format, args);
    va_end(args);
    fputc('\n', log_fp);
    fclose(log_fp);
}

int i2c_read(int bus, int addr, int reg, uint8_t *buf, int len) {
    int ret;
    i2c_rdwr_data_t data[2];

    data[0].addr = addr << 1;
    data[0].flags = 0;
    data[0].r_len = 0;
    data[0].w_len = 1;
    data[0].w_buf = &reg;

    data[1].addr = addr << 1 | I2C_ADDR_FLAG_READWRITE;
    data[1].flags = 0;
    data[1].r_len = len;
    data[1].w_len = 0;
    data[1].r_buf = buf;

    ret = i2cWriteReadBlocking(bus, data, 2);
    if (ret < 0) {
        log_data("I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return ret == 2 ? len : -1;
}

void setup_sensor(int bus) {
    uint8_t data[2];

    if (i2c_read(bus, MPU_ADDR, PWR_MGMT_1, data, 1) < 0) {
        return;
    }

    data[0] |= 0x00; // Wake up the sensor
    if (i2c_write(bus, MPU_ADDR, PWR_MGMT_1, &data, 1) < 0) {
        return;
    }

    if (i2c_read(bus, MPU_ADDR, ACCEL_CONFIG, data, 1) < 0) {
        return;
    }

    data[0] = 0x00; // Set the accelerometer full-scale range to ±2g
    if (i2c_write(bus, MPU_ADDR, ACCEL_CONFIG, &data, 1) < 0) {
        return;
    }
}

void setup_gpio(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
}

void cleanup_gpio(void) {
    gpioTerminate();
}

void setup_logging(void) {
    FILE *log_fp = fopen(log_file, "w");
    if (log_fp == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fclose(log_fp);
}

void cleanup_logging(void) {
    // No cleanup needed for logging as we overwrite the file on each run
}

void print_tilt(float roll, float pitch) {
    printf("Roll: %.2f degrees, Pitch: %.2f degrees\n", roll, pitch);
}

int main(void) {
    int bus = -1;
    uint8_t data[14];
    float roll, pitch;
    float last_roll = 0.0f, last_pitch = 0.0f;
    float roll_threshold = 45.0f;
    float pitch_threshold = 45.0f;
    int i;

    setup_gpio();
    setup_logging();

    if ((bus = pi_i2c_open(0, MPU_ADDR, 0)) < 0) {
        perror("pi_i2c_open");
        cleanup_gpio();
        cleanup_logging();
        exit(EXIT_FAILURE);
    }

    setup_sensor(bus);

    while (1) {
        if (i2c_read(bus, MPU_ADDR, 0x3B, data, 14) < 0) {
            continue;
        }

        roll = atan2(data[0] * 131.0f, data[1] * 131.0f) * 180.0f / M_PI;
        pitch = atan2(-data[2] * 131.0f, sqrt(data[0] * data[0] + data[1] * data[1])) * 180.0f / M_PI;

        if (fabs(roll - last_roll) > roll_threshold || fabs(pitch - last_pitch) > pitch_threshold) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        last_roll = roll;
        last_pitch = pitch;

        log_data("%s,%f,%f\n", time_str, roll, pitch);
        print_tilt(roll, pitch);

        usleep(100000);
    }

    i2cClose(bus);
    cleanup_gpio();
    cleanup_logging();

    return 0;
}

