#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x5A
#define REG_AMBIENT_LIGHT 0x20
#define REG_PROXIMITY 0x22
#define LED_GPIO 17

static int i2c_file;
static gpiod_line_info_t led_line_info;
static gpiod_line_request_data_t led_line_request_data;
static gpiod_line_state_callback_t led_state_cb;
static FILE *log_file;

void i2c_read(uint8_t reg, uint8_t *buf, size_t len) {
    int retries = 3;
    while (retries > 0) {
        if (ioctl(i2c_file, I2C_SMBUS_READ_I2C_BLOCK_DATA, reg) == len) {
            break;
        }
        usleep(10000);
        retries--;
    }
    if (retries == 0) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
    read(i2c_file, buf, len);
}

void log_sensor_reading(const char *timestamp, uint16_t ambient_light, uint16_t proximity) {
    char line[100];
    snprintf(line, sizeof(line), "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient_light, proximity);
    fputs(line, log_file);
}

void led_state_cb_func(struct gpiod_line *line, int value, void *user_data) {
    (void)line;
    (void)user_data;
    gpiod_line_set_value(led_line, value);
}

int main() {
    int ret;

    i2c_file = open("/dev/i2c-1", O_RDWR);
    if (i2c_file < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_file, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_claim_line_with_label(0, "rpi-led-builtin", LED_GPIO, &led_line_info, &led_line_request_data);
    if (ret < 0) {
        perror("Failed to claim GPIO line");
        exit(EXIT_FAILURE);
    }

    led_line_request_data.flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    led_line_request_data.consumer = "Si1145 optical sensor";
    ret = gpiod_request_line(led_line, &led_line_request_data);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }

    led_state_cb.callback = led_state_cb_func;
    led_state_cb.data = NULL;
    ret = gpiod_set_line_value(led_line, 0);
    if (ret < 0) {
        perror("Failed to set initial GPIO line value");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_set_line_debounce(led_line, 10);
    if (ret < 0) {
        perror("Failed to set GPIO line debounce");
        exit(EXIT_FAILURE);
    }
    ret = gpiod_set_line_state_callback(led_line, &led_state_cb);
    if (ret < 0) {
        perror("Failed to set GPIO line state callback");
        exit(EXIT_FAILURE);
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d",
             tv.tv_year, tv.tv_mon, tv.tv_mday, tv.tv_hour, tv.tv_min, tv.tv_sec);

    while (1) {
        uint16_t ambient_light, proximity;
        i2c_read(REG_AMBIENT_LIGHT, (uint8_t *)&ambient_light, sizeof(ambient_light));
        i2c_read(REG_PROXIMITY, (uint8_t *)&proximity, sizeof(proximity));
        ambient_light = (ambient_light << 8) | (i2c_read(REG_AMBIENT_LIGHT + 1, (uint8_t *)&ambient_light, sizeof(ambient_light)) & 0xFF);
        proximity = (proximity << 8) | (i2c_read(REG_PROXIMITY + 1, (uint8_t *)&proximity, sizeof(proximity)) & 0xFF);

        log_sensor_reading(timestamp, ambient_light, proximity);

        if (proximity > 100) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000);
        gettimeofday(&tv, NULL);
        snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d",
                 tv.tv_year, tv.tv_mon, tv.tv_mday, tv.tv_hour, tv.tv_min, tv.tv_sec);
    }

    close(i2c_file);
    fclose(log_file);
    gpiod_release_line(led_line);

    return 0;
}

