#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_DEVICE 0
#define CS_GPIO 8
#define X_REG 0x02
#define Y_REG 0x04
#define SENSITIVITY 200.0
#define SAMPLE_RATE 100
#define DELAY_US 10000

static volatile sig_atomic_t running = 1;

void sigint_handler(int signum) {
    running = 0;
}

int init_gpio(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (gpioSetMode(CS_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        return -1;
    }

    gpioWrite(CS_GPIO, 1);

    return 0;
}

int init_spi(void) {
    struct spi_config spi_cfg = {
        .mode = SPI_MODE_0,
        .max_speed_hz = 1000000,
        .bits_per_word = 16
    };

    if (spiOpen(SPI_BUS, SPI_DEVICE, &spi_cfg) < 0) {
        perror("spiOpen");
        return -1;
    }

    return 0;
}

uint16_t read_register(uint8_t addr) {
    uint8_t data[2];
    data[0] = (addr | 0x80);
    data[1] = 0;

    if (spiXfer(SPI_BUS, CS_GPIO, data, data + 1, 1) != 1) {
        perror("spiXfer");
        return 0;
    }

    gpioWrite(CS_GPIO, 1);

    return (data[1] << 8) | data[0];
}

void log_data(const char *filename, uint32_t timestamp, int16_t x_rate, int16_t y_rate) {
    FILE *file = fopen(filename, "a");

    if (!file) {
        perror("fopen");
        return;
    }

    fprintf(file, "%lu,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(file);
    fclose(file);
}

int main(void) {
    int ret;
    uint32_t timestamp;
    uint16_t x_rate, y_rate;
    int attempts = 0;

    signal(SIGINT, sigint_handler);

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_spi() < 0) {
        goto cleanup_gpio;
    }

    while (running) {
        gpioWrite(CS_GPIO, 0);

        x_rate = read_register(X_REG);
        y_rate = read_register(Y_REG);

        if (x_rate == 0 || y_rate == 0) {
            if (attempts < 3) {
                attempts++;
                if (init_spi() < 0) {
                    continue;
                }
            } else {
                fprintf(stderr, "Failed to read gyro data after 3 attempts\n");
                goto cleanup_spi;
            }
        }

        timestamp = (uint32_t)(clock() * 1000 / CLOCKS_PER_SEC);
        log_data("gyro_data.csv", timestamp, x_rate, y_rate);

        usleep(DELAY_US * 1000);
    }

cleanup_spi:
    spiClose(SPI_BUS, SPI_DEVICE);

cleanup_gpio:
    gpioTerm();

    return 0;
}

