code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define LOG_FILE "seismic_events.txt"

static int log_fd;
static time_t last_seismic_event = 0;

void log_seismic_event(const char *message) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    dprintf(log_fd, "%s - Seismic event detected!\n", timestamp);
    last_seismic_event = current_time;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerm(0);
        if (log_fd >= 0) {
            close(log_fd);
        }
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm(0);
        return 1;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("Failed to open log file");
        gpioTerm(0);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint32_t debounce_us = 100000; // 100 ms debounce
    uint32_t seismic_duration_us = 500000; // 500 ms seismic duration

    uint32_t last_sensor_1_state = gpioRead(SENSOR_1_PIN);
    uint32_t last_sensor_2_state = gpioRead(SENSOR_2_PIN);

    while (1) {
        uint32_t current_sensor_1_state = gpioRead(SENSOR_1_PIN);
