Here's a complete, compilable C code for the Raspberry Pi 3 Model B+ using the pigpio library to detect seismic activity with two Omron D7E-2 tilt sensors on BCM GPIO23 and GPIO24. The code checks for errors, handles signals, and logs seismic events to `seismic_events.txt`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define LOG_FILE "seismic_events.txt"

static int log_fd;
static time_t last_seismic_event = 0;

void log_seismic_event(const char *message) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    dprintf(log_fd, "%s - Seismic event detected!\n", timestamp);
    last_seismic_event = current_time;
}

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerm(0);
        if (log_fd >= 0) {
            close(log_fd);
        }
        exit(0);
    }
}

int main() {
