        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm(0);
        return 1;
    }

    if ((log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("Failed to open log file");
        gpioTerm(0);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint32_t debounce_us = 100000; // 100 ms debounce
    uint32_t seismic_duration_us = 500000; // 500 ms seismic duration

    uint32_t last_sensor_1_state = gpioRead(SENSOR_1_PIN);
    uint32_t last_sensor_2_state = gpioRead(SENSOR_2_PIN);

    while (1) {
        uint32_t current_sensor_1_state = gpioRead(SENSOR_1_PIN);
        uint32_t current_sensor_2_state = gpioRead(SENSOR_2_PIN);

        if (current_sensor_1_state == last_sensor_1_state &&
            current_sensor_2_state == last_sensor_2_state) {
            continue;
        }

        if (current_sensor_1_state == 1 && current_sensor_2_state == 1) {
            time_t elapsed_time = difftime(time(NULL), last_seismic_event);
