#define SPI_BUS 0
#define SPI_DEVICE 0
#define CE_PIN 8
#define SCLK_PIN 11
#define MOSI_PIN 10
#define MISO_PIN 9
#define LED_PIN 17
#define BUFFER_SIZE 100
#define LSB_PER_DEG_S 200

typedef struct {
    uint16_t x;
    uint64_t timestamp;
} reading_t;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
reading_t buffer[BUFFER_SIZE];
size_t head = 0;
size_t tail = 0;

void gyro_read(void) {
    uint16_t xl, xh;
    uint16_t x;
    uint8_t addr;

    while (1) {
        addr = (0x02 | (1 << 7));
        if (gpioSPIWriteRead(SPI_BUS, SPI_DEVICE, &addr, 1, &xl, 1) != 1) {
            fprintf(stderr, "Failed to read XL register\n");
            return;
        }
        if (gpioSPIWriteRead(SPI_BUS, SPI_DEVICE, &addr, 1, &xh, 1) != 1) {
            fprintf(stderr, "Failed to read XH register\n");
            return;
        }
        x = (xh << 8) | xl;
        double deg_per_s = (double)x * LSB_PER_DEG_S / 65536.0;

        pthread_mutex_lock(&buffer_mutex);
        buffer[head].x = x;
        buffer[head].timestamp = clock_gettime(CLOCK_MONOTONIC, NULL);
        head = (head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        if (fabs(deg_per_s) > 20.0) {
            gpioWrite(LED_PIN, 1);
        }
        usleep(100000); // 100 ms between readings
    }
}

void signal_handler(int sig) {
    gpioWrite(LED_PIN, 0);
    gpioTerm();
    exit(0);
}

