    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SCLK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOSI_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MISO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm();
        return 1;
    }

    gpioSetSPIMode(SPI_BUS, SPI_MODE_0, 1000000); // 1 MHz clock

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, gyro_read, NULL) != 0) {
        fprintf(stderr, "Failed to create gyro read thread\n");
        gpioTerm();
        return 1;
    }

    while (1) {
        usleep(100000); // Main loop runs at 10 Hz
    }

    pthread_join(thread_id, NULL);
    gpioTerm();
    return 0;
}

