#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <wiringPi.h>
#include <pigpio.h>

#define GPIO_PIN_17 11
#define GPIO_PIN_18 12
#define GPIO_PIN_27 13
#define PWM_FREQ 100
#define PWM_RANGE 255
#define MAX_DURATION 3600

static int gpio_init(void);
static void lamp_fade(int gpio);
static void signal_handler(int signum);

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_in_seconds> (1-3600)\n", argv[0]);
        return 1;
    }

    int fade_duration = atoi(argv[1]);
    if (fade_duration < 1 || fade_duration > MAX_DURATION) {
        fprintf(stderr, "Invalid fade duration. Please provide a value between 1 and 3600.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    printf("Initializing lamps...\n");
    lamp_fade(GPIO_PIN_17);
    lamp_fade(GPIO_PIN_18);
    lamp_fade(GPIO_PIN_27);

    printf("Lamps initialized. Fading out...\n");
    sleep(fade_duration);
    printf("Fade complete.\n");

    close_pigpio();
    return 0;
}

static int gpio_init(void) {
    if (wiringPiSetup() == -1) {
        perror("wiringPiSetup");
        return -1;
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    return 0;
}

static void lamp_fade(int gpio) {
    int duty_cycle = PWM_RANGE;
    int pwm_handle = gpioHardwarePWM(gpio, PWM_FREQ, duty_cycle);

    if (pwm_handle < 0) {
        perror("gpioHardwarePWM");
        return;
    }

    struct timespec start, end;
    double duration = fade_duration / (PWM_RANGE * 3.0);

    clock_gettime(CLOCK_MONOTONIC, &start);

    while (duty_cycle > 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1_ billion;

        if (elapsed >= duration) {
            duty_cycle--;
            start = end;
            gpioHardwarePWM(gpio, PWM_FREQ, duty_cycle * PWM_RANGE);
            printf("Lamp %d: %d%%\n", gpio, 100 - duty_cycle);
        }

        usleep(1000);
    }

    gpioHardwarePWM(gpio, 0, 0);
    gpioTerm(gpio);
}

static void signal_handler(int signum) {
    printf("Received signal %d. Turning off lamps and cleaning up...\n", signum);

    gpioTerm(GPIO_PIN_17);
    gpioTerm(GPIO_PIN_18);
    gpioTerm(GPIO_PIN_27);

    close_pigpio();
    exit(0);
}

void close_pigpio(void) {
    if (piThreadIsRunning()) {
        piThreadStop();
    }

    if (gpioTerm(GPIO_PIN_17) < 0 || gpioTerm(GPIO_PIN_18) < 0 || gpioTerm(GPIO_PIN_27) < 0) {
        perror("gpioTerm");
    }

    if (gpioTermAll() < 0) {
        perror("gpioTermAll");
    }

    if (gpioTermLib() < 0) {
        perror("gpioTermLib");
    }
}

void pigpio_cleanup(void) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
}

int main(void) {
    pigpio_cleanup();
    return main(1, (char*[]){"./sunset_simulator", "10"});
}

