#define BLACK_GPIO 24

static gpiod_line_request_lines_data_v1 lines_data = {
    .lines = (struct gpiod_line_request_data_v1[]) {
        [RED_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 1 },
        [YELLOW_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 1 },
        [GREEN_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 1 },
        [BLACK_GPIO] = { .direction = GPIOD_LINE_DIR_OUT, .active_low = 1 },
    },
    .n_lines = ARRAY_SIZE(lines_data.lines),
};

static struct gpiod_chip *chip;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpiod_chip_close(chip);
        exit(0);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((chip = gpiod_chip_open_by_name("gpiochip0")) == NULL) {
        perror("Failed to open gpiochip0");
        exit(1);
    }

    if (gpiod_line_request_dt_tree_get(chip, NULL, &lines_data) < 0) {
        perror("Failed to request lines");
        exit(1);
    }

    for (int i = 0; true; i++) {
        gpiod_line_set_value(lines_data.lines[RED_GPIO].line, 1);
        gpiod_line_set_value(lines_data.lines[YELLOW_GPIO].line, 1);
        gpiod_line_set_value(lines_data.lines[GREEN_GPIO].line, 0);
        gpiod_line_set_value(lines_data.lines[BLACK_GPIO].line, 1);
