Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>

#define FLAME_SENSOR_LINE "gpiochip0"
#define FLAME_SENSOR_LINE_OFFSET 17
#define BUZZER_LINE "gpiochip0"
#define BUZZER_LINE_OFFSET 18
#define LED_LINE "gpiochip0"
#define LED_LINE_OFFSET 23
#define LOG_FILE "flame_log.txt"

static int flame_sensor_fd = -1;
static int buzzer_fd = -1;
static int led_fd = -1;

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

void setup_gpio(const char *line, int offset, int *fd) {
    int gpio_fd = gpiod_open_name_with_label(line, "default");
    if (gpio_fd < 0) {
        perror("gpiod_open_name_with_label");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line_request request = {
        .offset = offset,
        .flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_DEBOUNCE,
        .consumer = "fire_alarm",
    };

    if (gpiod_line_request_dump(gpio_fd, &request) < 0) {
        perror("gpiod_line_request_dump");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_enable(gpio_fd, &request) < 0) {
        perror("gpiod_line_request_enable");
        exit(EXIT_FAILURE);
    }

    *fd = gpio_fd;
}

void cleanup_gpio(int *fd) {
    if (*fd >= 0) {
        if (gpiod_line_request_disable((*fd)) < 0) {
            perror("gpiod_line_request_disable");
        }

        if (gpiod_line_request_free((*fd)) < 0) {
            perror("gpiod_line_request_free");
        }

        if (gpiod_close((*fd)) < 0) {
            perror("gpiod_close");
        }

        *fd = -1;
    }
}

int main() {
    setup_gpio(FLAME_SENSOR_LINE, FLAME_SENSOR_LINE_OFFSET, &flame_sensor_fd);
    setup_gpio(BUZZER_LINE, BUZZER_LINE_OFFSET, &buzzer_fd);
    setup_gpio(LED_LINE, LED_LINE_OFFSET, &led_fd);

    int last_state = -1;
    int debounce_count = 0;

    while (1) {
        int state = gpiod_line_get_value(flame_sensor_fd);

        if (state != last_state) {
            debounce_count = 0;
        }

        if (state == 0) { // Flame detected
            if (debounce_count < 3) {
                debounce_count++;
            } else {
                gpiod_line_set_value(buzzer_fd, 1);
                gpiod_line_set_value(led_fd, 1);
                log_event("Flame Detected");
            }
        } else { // No flame detected
            if (gpiod_line_get_value(buzzer_fd)) {
                gpiod_line_set_value(buzzer_fd, 0);
            }
            if (gpiod_line_get_value(led_fd)) {
                gpiod_line_set_value(led_fd, 0);
            }
        }

        usleep(50000); // 50 ms delay
        last_state = state;

        // Handle SIGINT/SIGTERM
        if (signal(SIGINT, cleanup_and_exit) != SIG_ERR) {
            signal(SIGTERM, cleanup_and_exit);
        }
    }

    return 0;
}

void cleanup_and_exit(int signum) {
    printf("Received signal %d, cleaning up and exiting...\n", signum);
    cleanup_gpio(&flame_sensor_fd);
    cleanup_gpio(&buzzer_fd);
    cleanup_gpio(&led_fd);

    if (flame_sensor_fd >= 0) {
        close(flame_sensor_fd);
    }
    if (buzzer_fd >= 0) {
        close(buzzer_fd);
    }
    if (led_fd >= 0) {
        close(led_fd);
    }

    if (flame_sensor_fd < 0 && buzzer_fd < 0 && led_fd < 0) {
        remove(LOG_FILE);
    }

    exit(EXIT_SUCCESS);
}
```

This code initializes the flame sensor, buzzer, and LED on the specified GPIO pins, debounces the sensor reading, and logs flame detection events to a file. It also handles SIGINT and SIGTERM signals by releasing the GPIO lines and closing the log file before exiting.

