#define DISPENSE_DURATION 1000
#define DISPENSE_INTERVAL 5000
#define LOG_FILE "dispense_log.txt"

int init_pigpio(void);
int setup_gpio(uint32_t gpio);
int log_dispense(const char *solenoid_pins, uint32_t duration_ms);

