    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (setup_gpio(SOLENOID1_GPIO) != 0 || setup_gpio(SOLENOID2_GPIO) != 0) {
        fprintf(stderr, "Failed to set up GPIO pins\n");
        goto cleanup;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    uint64_t last_dispense = tv.tv_sec * 1000 + tv.tv_usec / 1000;

    while (1) {
        gettimeofday(&tv, NULL);
        uint64_t current_time = tv.tv_sec * 1000 + tv.tv_usec / 1000;
        if (current_time - last_dispense >= DISPENSE_INTERVAL) {
            last_dispense = current_time;

            gpioWrite(SOLENOID1_GPIO, 1);
            gpioDelay(DISPENSE_DURATION / 2);
            gpioWrite(SOLENOID1_GPIO, 0);
            gpioWrite(SOLENOID2_GPIO, 1);
            gpioDelay(DISPENSE_DURATION / 2);
            gpioWrite(SOLENOID2_GPIO, 0);

            if (log_dispense("1,2", DISPENSE_DURATION) != 0) {
                perror("Failed to log dispense event");
            }
        }

        usleep(100000);
    }

cleanup:
    gpioTerm(0);
    return 0;
}

int init_pigpio(void) {
    if (gpioInitialise() < 0) {
        return 1;
    }
    if (gpioSetMode(0, PI_MODE_BCM) < 0) {
        return 1;
    }
    return 0;
}

int setup_gpio(uint32_t gpio) {
    if (gpioSetMode(gpio, PI_OUTPUT) < 0) {
        return 1;
    }
    return 0;
}

int log_dispense(const char *solenoid_pins, uint32_t duration_ms) {
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        return 1;
    }

    char log_line[100];
    snprintf(log_line, sizeof(log_line), "%lu,%s,%d\n", time(NULL), solenoid_pins, duration_ms);
    if (write(fd, log_line, strlen(log_line)) != strlen(log_line)) {
        close(fd);
        return 1;
    }
    close(fd);
    return 0;
}

void signal_handler(int signum) {
    gpioWrite(SOLENOID1_GPIO, 0);
    gpioWrite(SOLENOID2_GPIO, 0);
    gpioTerm(0);
    exit(0);
}

int main(void) {
    // Add signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Rest of the code remains the same
}

