#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENABLE_A 24
#define ENABLE_B 25
#define ULTRASONIC_TRIG 15
#define ULTRASONIC_ECHO 14
#define LOG_FILE "balance_log.txt"

double Kp = 1.0, Ki = 0.01, Kd = 0.1;
int motor_speeds[2] = {0, 0};
double tilt_error = 0.0, prev_error = 0.0, integral = 0.0, derivative = 0.0, last_time = 0.0;

void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        halt_motors();
        gpioTerminate();
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n", timestamp, tilt_error, distance, motor_speeds[0], motor_speeds[1]);
    fclose(log_file);
}

void halt_motors() {
    motor_speeds[0] = motor_speeds[1] = 0;
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
}

double ultrasonic_distance() {
    double duration, distance;

    gpioWrite(ULTRASONIC_TRIG, 1);
    usleep(10000);
    gpioWrite(ULTRASONIC_TRIG, 0);

    duration = gpioRead(ULTRASONIC_ECHO);
    duration /= 58;
    distance = duration * 34300;

    return distance;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialise pigpio.\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);
    gpioWrite(ENABLE_A, 1);
    gpioWrite(ENABLE_B, 1);

