    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        halt_motors();
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, halt_motors);
    signal(SIGTERM, halt_motors);

    while (1) {
        double tilt_error_random = (rand() % 201) / 100.0 - 10.0;
        double distance = ultrasonic_distance();

        if (distance < 20.0) {
            motor_speeds[0] = motor_speeds[1] = 128;
        } else {
            derivative = (tilt_error - prev_error) / (last_time - gmtime(&now)->tm_sec);
