        } else {
            derivative = (tilt_error - prev_error) / (last_time - gmtime(&now)->tm_sec);
            integral += (tilt_error + prev_error) * 0.02;
            double control_output = Kp * tilt_error + Ki * integral + Kd * derivative;
            motor_speeds[0] = control_output > 255 ? 255 : (control_output < -255 ? -255 : control_output);
            motor_speeds[1] = -motor_speeds[0];
        }

        gpioPWM(MOTOR_A_FORWARD, motor_speeds[0]);
        gpioPWM(MOTOR_A_BACKWARD, abs(motor_speeds[0]));
        gpioPWM(MOTOR_B_FORWARD, motor_speeds[1]);
        gpioPWM(MOTOR_B_BACKWARD, abs(motor_speeds[1]));

        log_data(tilt_error, distance, motor_speeds[0], motor_speeds[1]);
        last_time = gmtime(&now)->tm_sec;
        prev_error = tilt_error;
        usleep(50000);
    }

    halt_motors();
    gpioTerminate();
    fclose(log_file);
    return 0;
