#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define DEBOUNCE_DELAY 50

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set the mode of the sensor GPIO as input with internal pull-down
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);

    // Set the mode of the relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay off

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read the state of the sensor GPIO
        int sensor_state = gpioRead(SENSOR_GPIO);

        // Debounce delay
        usleep(DEBOUNCE_DELAY * 1000);

        // Check if the sensor is touched (HIGH) and the relay is off
        if (sensor_state && !gpioRead(RELAY_GPIO)) {
            gpioWrite(RELAY_GPIO, 1); // Toggle relay on
            printf("Relay toggled on\n");
        }
        // Check if the sensor is not touched (LOW) and the relay is on
        else if (!sensor_state && gpioRead(RELAY_GPIO)) {
            gpioWrite(RELAY_GPIO, 0); // Toggle relay off
            printf("Relay toggled off\n");
        }
    }

    // Clean up resources
    gpioTerm();

    return 0;
}

