static void alsa_init() {
    int err;
    snd_pcm_hw_params_t *params;

    if (alsa_initialized)
        return;

    if ((err = snd_pcm_open(&handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Cannot open ALSA audio device: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    snd_pcm_hw_params_alloca(&params);
    if ((err = snd_pcm_hw_params_any(handle, params)) < 0) {
        fprintf(stderr, "Cannot initialize hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_access(handle, params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Cannot set access type: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_format(handle, params, SAMPLE_FORMAT)) < 0) {
        fprintf(stderr, "Cannot set sample format: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_channels(handle, params, 1)) < 0) {
        fprintf(stderr, "Cannot set channel count: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_set_rate_near(handle, params, &RATE, 0)) < 0) {
        fprintf(stderr, "Cannot set sample rate: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params(handle, params)) < 0) {
        fprintf(stderr, "Cannot set hardware parameters: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    if ((err = snd_pcm_hw_params_get_period_size(params, &BUFFER_SIZE, 0)) < 0) {
        fprintf(stderr, "Cannot get period size: %s\n", snd_strerror(err));
        exit(EXIT_FAILURE);
    }

    alsa_initialized = 1;
}

static void alsa_cleanup() {
    if (!alsa_initialized)
        return;

    snd_pcm_drain(handle);
    snd_pcm_close(handle);
    alsa_initialized = 0;
}

static void *alsa_capture_thread(void *arg) {
    int err;
    unsigned int i;
    unsigned short *buffer;

    while (running) {
        snd_pcm_prepare(handle);
        if ((err = snd_pcm_readi(handle, (char *)buffer, BUFFER_SIZE)) < 0) {
            if (err == -EPIPE) {
                fprintf(stderr, "Read error: EPIPE\n");
                snd_pcm_prepare(handle);
            } else if (err == -ESTRPIPE) {
                fprintf(stderr, "Read error: ESTRPIPE\n");
                snd_pcm_resume(handle);
            } else {
                fprintf(stderr, "Read error: %s\n", snd_strerror(err));
                exit(EXIT_FAILURE);
            }
        }

        for (i = 0; i < BUFFER_SIZE; i++)
            buffer[i] = (short)(SENSITIVITY * sqrt(buffer[i] * buffer[i]));

        pthread_exit(NULL);
    }

    return NULL;
}

