        printf("ALSA support disabled\n");
        #define ALSA_AVAILABLE 0
    }

    if (ALSA_AVAILABLE)
        alsa_init();

    buffer = mmap(NULL, BUFFER_SIZE * SAMPLE_SIZE, PROT_READ, MAP_SHARED, fileno(stdin), 0);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Failed to map ALSA buffer\n");
        exit(EXIT_FAILURE);
    }

    if (pthread_create(&capture_thread, NULL, alsa_capture_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create capture thread\n");
        exit(EXIT_FAILURE);
    }

    while (running) {
