                pigpio_pwm_config(BLUE_PIN, PWM_FREQ, 0) < 0) {
                fprintf(stderr, "Failed to configure PWM\n");
                exit(EXIT_FAILURE);
            }

            for (i = 0; i < BUFFER_SIZE; i++) {
                r = (unsigned int)(255 * (1 - (buffer[i] / 32768.0)));
                g = (unsigned int)(255 * (buffer[i] / 32768.0));
                b = 0;

                if (g > r) {
                    double temp = r;
                    r = g;
                    g = temp;
                }

                pigpio_hardware_PWM(RED_PIN, r);
                pigpio_hardware_PWM(GREEN_PIN, g);
                pigpio_hardware_PWM(BLUE_PIN, b);

                usleep(DELAY_US);
            }
        } else {
            for (i = 0; i < BUFFER_SIZE; i++) {
                r = (unsigned int)(255 * sin(i / (2 * M_PI * 0.005)));
                g = (unsigned int)(255 * sin((i + 1) / (2 * M_PI * 0.005)));
                b = (unsigned int)(255 * sin((i + 2) / (2 * M_PI * 0.005)));

