                pigpio_hardware_PWM(BLUE_PIN, b);

                usleep(DELAY_US);
            }
        }
    }

    if (ALSA_AVAILABLE)
        alsa_cleanup();

    munmap(buffer, BUFFER_SIZE * SAMPLE_SIZE);
    gpioTerm();

    return 0;
}

