        i2c_fd = -1;
    }
    fprintf(stderr, "%s\n", msg);
}

int init_i2c() {
    if ((i2c_fd = wiringPiI2CSetup(1, TCS34725_ADDR)) < 0) {
        i2c_error_handler("Failed to open I2C bus");
        return 1;
