    if (wiringPiI2CWriteReg16(i2c_fd, TCS34725_REG_CONTROL, 0x03) != 0) {
        i2c_error_handler("Failed to write control register");
        return 1;
    }

    if (wiringPiI2CWriteReg16(i2c_fd, TCS34725_REG_ATIME, 0xD5) != 0) {
        i2c_error_handler("Failed to write integration time register");
        return 1;
    }

    return 0;
