        data[0] = (data[0] << 8) | data[1];
        data[1] = (data[2] << 8) | data[3];
        data[2] = (data[4] << 8) | data[5];

        timestamp = time(NULL);
        fprintf(file, "%lu,%d,%d,%d,%d\n", timestamp, data[0], data[1], data[2], data[3]);
    }

    return NULL;
}

void sigint_handler(int signum) {
    if (i2c_fd > 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    if (file) {
        fclose(file);
        file = NULL;
    }

    pthread_cancel(thread_id);
    pthread_join(thread_id, NULL);

    wiringPiI2CWriteReg16(i2c_fd, TCS34725_REG_CONTROL, 0x00);
    wiringPiI2CWriteReg16(i2c_fd, TCS34725_REG_ATIME, 0x00);

    exit(0);
}

int main() {
    int ret;

    if ((ret = init_i2c()) != 0) {
        return ret;
    }

    if ((file = fopen("color_data.csv", "w")) == NULL) {
        i2c_error_handler("Failed to open file");
        return 1;
    }

    if (fprintf(file, "timestamp,clear,red,green,blue\n") < 5) {
        i2c_error_handler("Failed to write header to file");
        return 1;
    }

    if ((ret = pthread_create(&thread_id, NULL, sensor_read_loop, NULL)) != 0) {
        i2c_error_handler("Failed to create sensor read thread");
        return ret;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioDelay(500000); // 500 ms delay

    while (1) {
        gpioDelay(500000); // 500 ms delay
    }

    return 0;
}

