#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define RELAY_PIN_COUNT 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 14400
#define DUTY_CYCLE_STEP 25

static gpiod_chip *g_chip;
static gpiod_line_array *g_lines;
static int g_relay_pins[RELAY_PIN_COUNT] = {GPIO_PIN_NUMBER_17, GPIO_PIN_NUMBER_27, GPIO_PIN_NUMBER_22, GPIO_PIN_NUMBER_23};

void signal_handler(int signum) {
    for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
        gpiod_line_set_value(g_lines->lines[i], 1);
        gpiod_line_release(g_lines->lines[i]);
    }

    gpiod_chip_close(g_chip);
    free(g_lines);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (libgpiod_init() < 0) {
        fprintf(stderr, "Failed to initialize libgpiod\n");
        return 1;
    }

    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip0\n");
        libgpiod_exit();
        return 1;
    }

    g_lines = calloc(RELAY_PIN_COUNT, sizeof(gpiod_line));
    for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
        gpiod_line *line = &g_lines->lines[i];
        line->gpio = g_relay_pins[i];

        if (gpiod_line_get(g_chip, line) < 0) {
            fprintf(stderr, "Failed to get line %d\n", line->gpio);
            goto cleanup;
        }

        if (gpiod_line_request_output(line, GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0) {
            fprintf(stderr, "Failed to request output for line %d\n", line->gpio);
            goto cleanup;
        }
    }

    time_t sunrise_start = time(NULL);
    time_t sunset_start = sunrise_start + SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION;
    time_t nighttime_start = sunset_start + NIGHTTIME_DURATION;

    while (1) {
        time_t now = time(NULL);

        if (now >= sunrise_start) {
            for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
                int duty_cycle = (now - sunrise_start) * DUTY_CYCLE_STEP / SUNRISE_DURATION;
                if (duty_cycle > 100) {
                    duty_cycle = 100;
                }
                gpiod_line_set_value(g_lines->lines[i], duty_cycle > 0);
            }

            if (now >= sunrise_start + SUNRISE_DURATION) {
                sunrise_start = sunset_start;
            }
        } else if (now >= sunset_start) {
            for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
                int duty_cycle = (sunset_start - now) * DUTY_CYCLE_STEP / SUNSET_DURATION;
                if (duty_cycle < 0) {
                    duty_cycle = 0;
                }
                gpiod_line_set_value(g_lines->lines[i], duty_cycle > 0);
            }

            if (now >= sunset_start + SUNSET_DURATION) {
                sunset_start = nighttime_start;
            }
        } else if (now >= nighttime_start) {
            for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
                gpiod_line_set_value(g_lines->lines[i], 0);
            }

            if (now >= sunrise_start) {
                sunrise_start = now;
            }
        }

        usleep(100000);
    }

cleanup:
    for (int i = 0; i < RELAY_PIN_COUNT; ++i) {
        gpiod_line_release(g_lines->lines[i]);
    }
    free(g_lines);
    gpiod_chip_close(g_chip);
    libgpiod_exit();

    return 0;
}

