I'll provide you with a basic example of the requested C program. This code uses the pigpio library to detect motion from a Keyes KY-033 IR Obstacle Avoidance Sensor on GPIO 17 (physical pin 11). It records a 5-second video using raspivid when motion is detected, saves the video with a timestamp-based filename, and logs each event with an ISO 8601 timestamp to `/home/pi/logs/motion_log.txt`.

Please note that you'll need to install the pigpio library on your Raspberry Pi before compiling this code. You can do this by running:

```
sudo apt-get update
sudo apt-get install pigpio
```

Here's the C code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define SENSOR_GPIO 17
#define VIDEO_DIR "/home/pi/videos"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_MS 200

static time_t last_trigger_time = 0;
static int last_trigger_state = -1;

void sigint_handler(int signum) {
    gpioTerm();
    fclose(log_file);
    exit(0);
}

int main() {
    struct timespec ts;
    int ret, log_file_fd;
    char video_filename[64];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerm();
        return 1;
    }

    log_file_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (log_file_fd < 0) {
        perror("Failed to open log file");
        gpioTerm();
        return 1;
    }

    while (1) {
        if (gpioRead(SENSOR_GPIO) == GPIO_LOW) {
            if (last_trigger_state == GPIO_LOW) {
                ts.tv_sec = time(NULL);
                ts.tv_nsec = (last_trigger_time + DEBOUNCE_MS - time(NULL)) * 1e9;
                nanosleep(&ts, NULL);
                if (gpioRead(SENSOR_GPIO) == GPIO_LOW) {
                    last_trigger_time = time(NULL);

                    snprintf(video_filename, sizeof(video_filename), "%s/%04d%02d%02d_%02d%02d%02d.h264", VIDEO_DIR,
                             localtime(&last_trigger_time)->tm_year + 1900, localtime(&last_trigger_time)->tm_mon + 1,
                             localtime(&last_trigger_time)->tm_mday, localtime(&last_trigger_time)->tm_hour,
                             localtime(&last_trigger_time)->tm_min, localtime(&last_trigger_time)->tm_sec);

                    ret = system(raspivid_command.c_str());
                    if (ret < 0) {
                        perror("Failed to execute raspivid");
                    }

                    fprintf(log_file, "%s: Motion detected\n", ctime(&last_trigger_time));
                }
            }
        }

        last_trigger_state = gpioRead(SENSOR_GPIO);
    }

    gpioTerm();
    fclose(log_file_fd);
    return 0;
}
```

