#define LOG_FILE "gyro_log.csv"

void sigint_handler(int signum) {
    i2cClose(i2c_fd);
    fclose(log_file);
    exit(0);
}

int init_mpu() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (i2cOpen(I2C_BUS, MPU_ADDR, &i2c_fd) < 0) {
        perror("i2cOpen");
        gpioTerm();
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, MPU_ADDR, 0x6B, 0x00) < 0) {
        perror("i2cWriteByteData");
        i2cClose(i2c_fd);
        gpioTerm();
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, MPU_ADDR, 0x19, SAMPLE_RATE_DIVIDER) < 0) {
        perror("i2cWriteByteData");
        i2cClose(i2c_fd);
        gpioTerm();
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, MPU_ADDR, 0x1B, 0x00) < 0) {
        perror("i2cWriteByteData");
        i2cClose(i2c_fd);
        gpioTerm();
        return -1;
    }

    return 0;
}

int read_gyro_values(int16_t *gyro_values) {
    uint8_t data[7];

    if (i2cReadI2CBlockData(i2c_fd, MPU_ADDR, 0x43, data, 7) < 0) {
        perror("i2cReadI2CBlockData");
        return -1;
    }

    gyro_values[0] = (int16_t)((int16_t)data[0] << 8 | data[1]);
    gyro_values[1] = (int16_t)((int16_t)data[2] << 8 | data[3]);
    gyro_values[2] = (int16_t)((int16_t)data[4] << 8 | data[5]);

    return 0;
}

void convert_to_degps(int16_t *gyro_values, float *degps) {
    degps[0] = gyro_values[0] * SENSITIVITY;
    degps[1] = gyro_values[1] * SENSITIVITY;
    degps[2] = gyro_values[2] * SENSITIVITY;
}

int main() {
    int i, ret, fd, attempts = 3;
    time_t timestamp;
    struct timespec ts;
    float gyro_degps[3];
    int16_t gyro_values[3];
    char log_str[128];

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (init_mpu() < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050\n");
        return -1;
    }

    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        perror("open");
        i2cClose(i2c_fd);
        gpioTerm();
        return -1;
    }

    while (1) {
        if (read_gyro_values(gyro_values) < 0) {
            if (attempts > 0) {
                attempts--;
                if (init_mpu() < 0) {
                    fprintf(stderr, "Failed to re-initialize MPU-6050\n");
                    continue;
                }
            } else {
                fprintf(stderr, "Gyroscope read failure, giving up\n");
            }
        } else {
            clock_gettime(CLOCK_REALTIME, &ts);
            timestamp = (time_t)ts.tv_sec + (ts.tv_nsec / 1000000000);

            convert_to_degps(gyro_values, gyro_degps);

            snprintf(log_str, sizeof(log_str), "%lld,%.6f,%.6f,%.6f\n", timestamp * 1000, gyro_degps[0], gyro_degps[1], gyro_degps[2]);
            write(fd, log_str, strlen(log_str));

            attempts = 3;
        }

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    close(fd);
    i2cClose(i2c_fd);
    gpioTerm();

    return 0;
}
```

This code initializes the MPU-6050 gyroscope, reads the raw gyroscope values, converts them to degrees per second, logs the readings to `gyro_log.csv`, and runs indefinitely until interrupted by a SIGINT or SIGTERM signal. The code checks every pigpio call and handles errors by re-initializing the sensor up to 3 times before giving up. The log file is closed and the I2C handle is released on SIGINT or SIGTERM.

