#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define ADXL345_ADDR 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define DELAY_MS 100
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define GPIO_ALARM 27
#define LOG_FILE "freefall.log"

void sigint_handler(int sig) {
    gpioTerm(0);
    exit(0);
}

void write_reg(int addr, uint8_t value) {
    if (i2cWriteByteData(addr, DATA_FORMAT_REG, value) < 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", DATA_FORMAT_REG);
    }

    if (i2cWriteByteData(addr, POWER_CTL_REG, 0x08) < 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", POWER_CTL_REG);
    }
}

int read_data(int addr, uint8_t *data) {
    if (i2cReadReg16(addr, DATAX0_REG, data, 6) < 0) {
        fprintf(stderr, "Error reading data from registers\n");
        return -1;
    }

    return 0;
}

void convert_data(uint16_t *data, float *values) {
    values[0] = (float)data[0] / 256.0;
    values[1] = (float)data[1] / 256.0;
    values[2] = (float)data[2] / 256.0;
}

void log_freefall(const char *timestamp, float x, float y, float z) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(log_file, "%s,%f,%f,%f\n", timestamp, x, y, z);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    write_reg(ADXL345_ADDR, 0x0B);

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    while (1) {
        if (read_data(ADXL345_ADDR, (uint8_t *)data) < 0) {
            continue;
        }

        float x, y, z;
        convert_data(data, &x);
        float abs_x = fabsf(x);
        float abs_y = fabsf(y);
        float abs_z = fabsf(z);

        if (abs_x < FREEFALL_THRESHOLD && abs_y < FREEFALL_THRESHOLD && abs_z < FREEFALL_THRESHOLD) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (gpioRead(GPIO_ALARM) == 0) {
                gpioWrite(GPIO_ALARM, 1);
                sleep(5);
                gpioWrite(GPIO_ALARM, 0);

                log_freefall(timestamp, x, y, z);
            }

            time_t start_time = rawtime;
            while ((rawtime - start_time) < FREEFALL_DURATION) {
                time(&rawtime);
                if (read_data(ADXL345_ADDR, (uint8_t *)data) < 0) {
                    continue;
                }

                convert_data(data, &x);
                if (fabsf(x) > FREEFALL_THRESHOLD || fabsf(y) > FREEFALL_THRESHOLD || fabsf(z) > FREEFALL_THRESHOLD) {
                    break;
                }
            }
        }

        usleep(DELAY_MS * 1000);
    }

    gpioTerm(0);
    return 0;
}

