#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/time.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>

#include <pigpio.h>

#define TRIG_GPIO 4
#define ECHO_GPIO 18
#define SAMPLE_INTERVAL_MS 200
#define MAX_DISTANCE_US 23200
#define TIMEOUT_US 100000
#define LOG_FILE "distance_log.txt"

static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static uint32_t pulse_start = 0;
static uint32_t pulse_end = 0;
static uint32_t pulse_duration = 0;
static uint32_t last_trigger_time = 0;
static uint32_t last_echo_time = 0;
static uint32_t last_valid_time = 0;
static FILE *log_file = NULL;

void trigger_callback(int gpio, uint32_t tick) {
    if (tick - last_trigger_time < SAMPLE_INTERVAL_MS * 1000) {
        return;
    }

    last_trigger_time = tick;
    gpioWrite(TRIG_GPIO, 1);
    gpioDelayUs(10);
    gpioWrite(TRIG_GPIO, 0);

    pthread_mutex_lock(&pulse_mutex);
    pulse_start = tick;
    pthread_mutex_unlock(&pulse_mutex);
}

void echo_callback(int gpio, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_end = tick;
    pthread_mutex_unlock(&pulse_mutex);

    if (pulse_end - pulse_start > MAX_DISTANCE_US || pulse_end - pulse_start > last_trigger_time - last_echo_time) {
        return;
    }

    pulse_duration = pulse_end - pulse_start;
    last_echo_time = last_trigger_time;

    double distance_cm = (pulse_duration * 0.017 / 2) * 100;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;

    if (log_file) {
        fprintf(log_file, "%llu,%f\n", timestamp_ns, distance_cm);
        fflush(log_file);
    }

    last_valid_time = ts.tv_sec * 1000000000 + ts.tv_nsec;
}

void sigint_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerm();
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIG_GPIO, PI_OUTPUT) < 0 || gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm();
        return 1;
    }

    if (gpioSetInterrupt(TRIG_GPIO, INT_EDGE_RISING, trigger_callback) < 0 ||
        gpioSetInterrupt(ECHO_GPIO, INT_EDGE_RISING | INT_EDGE_FALLING, echo_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO interrupts\n");
        gpioTerm();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerm();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        usleep(100000);

        if (pulse_duration > 0 && last_valid_time + TIMEOUT_US < (uint64_t)time(NULL) * 1000000000) {
            pulse_duration = 0;
        }
    }

    gpioTerm();
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}

