    pthread_mutex_lock(&pulse_mutex);
    pulse_end = tick;
    pthread_mutex_unlock(&pulse_mutex);

    if (pulse_end - pulse_start > MAX_DISTANCE_US || pulse_end - pulse_start > last_trigger_time - last_echo_time) {
        return;
    }

    pulse_duration = pulse_end - pulse_start;
    last_echo_time = last_trigger_time;

    double distance_cm = (pulse_duration * 0.017 / 2) * 100;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    uint64_t timestamp_ns = ts.tv_sec * 1000000000 + ts.tv_nsec;

    if (log_file) {
        fprintf(log_file, "%llu,%f\n", timestamp_ns, distance_cm);
        fflush(log_file);
    }

    last_valid_time = ts.tv_sec * 1000000000 + ts.tv_nsec;
}

void sigint_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerm();
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIG_GPIO, PI_OUTPUT) < 0 || gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm();
        return 1;
    }

    if (gpioSetInterrupt(TRIG_GPIO, INT_EDGE_RISING, trigger_callback) < 0 ||
        gpioSetInterrupt(ECHO_GPIO, INT_EDGE_RISING | INT_EDGE_FALLING, echo_callback) < 0) {
        fprintf(stderr, "Failed to set GPIO interrupts\n");
        gpioTerm();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerm();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        usleep(100000);

        if (pulse_duration > 0 && last_valid_time + TIMEOUT_US < (uint64_t)time(NULL) * 1000000000) {
            pulse_duration = 0;
        }
    }

    gpioTerm();
    pthread_mutex_destroy(&pulse_mutex);
    return 0;
}
```

This code initializes the pigpio library, sets up the TRIG and ECHO pins, sets up the rising and falling edge interrupts for the ECHO pin, and opens the log file. It also handles SIGINT signals to clean up resources when the program is terminated. The main loop checks for valid distance measurements and discards them if they are too old or exceed the maximum distance.

