#define LOG_FILE "/var/log/high_acceleration.log"

float threshold = THRESHOLD_DEFAULT;
uint8_t i2c_address = LIS3DH_ADDR_MIN;

void sigint_handler(int signum) {
    close_i2c();
    exit(0);
}

int init_pigpio() {
    if (wiringPiSetup() == -1) {
        perror("Failed to initialize pigpio library");
        return 1;
    }
    return 0;
}

int open_i2c(uint8_t address) {
    int file = i2cOpen(address, 1);
    if (file < 0) {
        perror("Failed to open I2C device");
        return 1;
    }
    return file;
}

void close_i2c() {
    i2cClose(i2c_fd);
}

int write_byte_data(uint8_t reg, uint8_t value) {
    if (i2c_fd < 0) {
        perror("I2C not open");
        return 1;
    }
    if (i2cWriteByteData(i2c_fd, reg, value) < 0) {
        perror("Failed to write byte data");
        return 1;
    }
    return 0;
}

int write_i2c_block_data(uint8_t reg, uint8_t *data, size_t len) {
    if (i2c_fd < 0) {
        perror("I2C not open");
        return 1;
    }
    if (i2cWriteI2CBlockData(i2c_fd, reg, data, len) < 0) {
        perror("Failed to write I2C block data");
        return 1;
    }
    return 0;
}

int read_i2c_block_data(uint8_t reg, uint8_t *data, size_t len) {
    if (i2c_fd < 0) {
        perror("I2C not open");
        return 1;
    }
    if (i2cReadI2CBlockData(i2c_fd, reg, data, len) < 0) {
        perror("Failed to read I2C block data");
        return 1;
    }
    return 0;
}

void log_high_acceleration(float x, float y, float z) {
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s: x=%.3f y=%.3f z=%.3f\n", timestamp, x, y, z);
    fclose(log_file);
}

float read_acceleration(uint8_t x_l, uint8_t x_h, uint8_t y_l, uint8_t y_h, uint8_t z_l, uint8_t z_h) {
    int16_t x = (int16_t)(((int16_t)x_h << 8) | x_l);
    int16_t y = (int16_t)(((int16_t)y_h << 8) | y_l);
    int16_t z = (int16_t)(((int16_t)z_h << 8) | z_l);

    float g_x = (float)x >> 4;
    float g_y = (float)y >> 4;
    float g_z = (float)z >> 4;

    float g = sqrt(g_x * g_x + g_y * g_y + g_z * g_z);
    return g;
}

void* accelerometer_thread(void *arg) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    float x, y, z, g;

    while (1) {
        if (read_i2c_block_data(LIS3DH_OUT_X_L, &x_l, 1) ||
            read_i2c_block_data(LIS3DH_OUT_X_H, &x_h, 1) ||
            read_i2c_block_data(LIS3DH_OUT_Y_L, &y_l, 1) ||
            read_i2c_block_data(LIS3DH_OUT_Y_H, &y_h, 1) ||
            read_i2c_block_data(LIS3DH_OUT_Z_L, &z_l, 1) ||
            read_i2c_block_data(LIS3DH_OUT_Z_H, &z_h, 1)) {
            x = y = z = 0.0f;
        } else {
            g = read_acceleration(x_l, x_h, y_l, y_h, z_l, z_h);
            if (g > threshold) {
                log_high_acceleration(x, y, z);
                system("sudo shutdown -h now");
            }
        }

        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    int pigpio_init_result = init_pigpio();
    if (pigpio_init_result) {
        return pigpio_init_result;
    }

    if (argc < 3 || argc > 4) {
        fprintf(stderr, "Usage: %s [-a <I2C address>] [-t <threshold>]\n", argv[0]);
        return 1;
    }

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-a") == 0 && (i + 1) < argc) {
            i2c_address = strtol(argv[++i], NULL, 16);
            if (i2c_address < LIS3DH_ADDR_MIN || i2c_address > LIS3DH_ADDR_MAX) {
                fprintf(stderr, "Invalid I2C address\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-t") == 0 && (i + 1) < argc) {
            threshold = strtof(argv[++i], NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Invalid threshold\n");
                return 1;
            }
        }
    }

    if (write_byte_data(LIS3DH_CTRL_REG1, 0x57) ||
        write_byte_data(LIS3DH_CTRL_REG4, 0x88)) {
        perror("Failed to configure LIS3DH");
        return 1;
    }

    i2c_fd = open_i2c(i2c_address);
    if (i2c_fd < 0) {
        return 1;
    }

    signal(SIGINT, sigint_handler);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, accelerometer_thread, NULL) != 0) {
        perror("Failed to create accelerometer thread");
        return 1;
    }

    pthread_join(thread_id, NULL);

    close_i2c();
    return 0;
}
```

To run the program, make sure you have the pigpio library installed on your Raspberry Pi, and then execute the following command:

```sh
sudo pigpiod
./accelerometer_monitor -a 0x18 -t 2.5
```

Replace `0x18` with the desired I2C address and `2.5` with the desired threshold in g. If you don't specify an address or threshold, it will use the default values (0x18 and 2.0g).

