#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define RASPBERRY_GPIO_17 17
#define SI7210_I2C_BUS 1
#define SI7210_I2C_ADDR 0x30
#define MAGNETIC_FIELD_THRESHOLD 500
#define MAGNETIC_FIELD_SCALE_FACTOR 25

static char magnetic_events_file[] = "magnetic_events.txt";
static FILE *magnetic_events_file_ptr;

void sigint_handler(int signum) {
    i2cClose(i2c_fd);
    gpioTerm(pi);
    fclose(magnetic_events_file_ptr);
    exit(0);
}

int main() {
    int i, ret, field_raw, field_mT_x100, relay_state;
    uint8_t reg_data[2];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    if ((magnetic_events_file_ptr = fopen(magnetic_events_file, "a")) == NULL) {
        perror("fopen");
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    if ((pi = pigpio_init()) < 0) {
        perror("pigpio_init");
        exit(1);
    }

    if (gpioInitialise(pi, 0, 0) < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    if ((i2c_fd = i2cOpen(pi, SI7210_I2C_BUS, SI7210_I2C_ADDR, 0)) < 0) {
        perror("i2cOpen");
        exit(1);
    }

    relay_state = gpioRead(pi, RASPBERRY_GPIO_17);
    fprintf(magnetic_events_file_ptr, "%s Relay state at startup: %s\n", ts.tv_sec == ts.tv_nsec ? ts.tv_sec : ts->tm_year + 1900, relay_state ? "ON" : "OFF");

    while (1) {
        if (i2cWriteByteData(i2c_fd, 0xC1, 0x01) < 0) {
            perror("i2cWriteByteData");
            continue;
        }

        for (i = 0; i < 50; ++i) {
            if (i2cReadByte(i2c_fd) == 0x00) {
                break;
            }
        }

        if (i == 50) {
            fprintf(magnetic_events_file_ptr, "%s Timeout waiting for conversion to complete\n", ts.tv_sec == ts.tv_nsec ? ts.tv_sec : ts->tm_year + 1900);
            continue;
        }

        if (i2cReadByteData(i2c_fd, 0xC0, reg_data, 2) != 2) {
            perror("i2cReadByteData");
            continue;
        }

        field_raw = (reg_data[0] << 8) | reg_data[1];
        field_mT_x100 = field_raw * MAGNETIC_FIELD_SCALE_FACTOR / 1000;

        if (field_mT_x100 >= MAGNETIC_FIELD_THRESHOLD * 100) {
            if (relay_state == 0) {
                gpioWrite(pi, RASPBERRY_GPIO_17, 1);
                relay_state = 1;
                fprintf(magnetic_events_file_ptr, "%s Relay activated: %d mT\n", ts.tv_sec == ts.tv_nsec ? ts.tv_sec : ts->tm_year + 1900, field_mT_x100);
            }
        } else if (relay_state == 1) {
            gpioWrite(pi, RASPBERRY_GPIO_17, 0);
            relay_state = 0;
            fprintf(magnetic_events_file_ptr, "%s Relay deactivated\n", ts.tv_sec == ts.tv_nsec ? ts.tv_sec : ts->tm_year + 1900);
        }

        clock_gettime(CLOCK_REALTIME, &ts);
    }

    i2cClose(i2c_fd);
    gpioTerm(pi);
    fclose(magnetic_events_file_ptr);

    return 0;
}

