#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define LOG_FILE "relay_log.txt"

static void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, event);
    fprintf(stderr, "%s\n", time_string);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_string, event);
        fclose(log_file);
    }
}

static int handle_command(const char *command) {
    if (strcmp(command, "on") && strcmp(command, "ON") && strcmp(command, "off") && strcmp(command, "OFF")) {
        log_event("Invalid command");
        return -1;
    }

    if (!strcmp(command, "on") || !strcmp(command, "ON")) {
        gpioWrite(RELAY_GPIO, 1);
