#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR1 0x08
#define SENSOR_ADDR2 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR 1.0 / 1500.0

volatile sig_atomic_t shutdown = 0;

void sigint_handler(int signum) {
    shutdown = 1;
}

uint16_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; ++i) {
        for (uint8_t j = 8; j; --j) {
            crc = (crc << 1) ^ (crc & 0x80 ? 0x31 : 0);
            crc = (crc << 1) ^ (data[i] & 0x01 ? 0x31 : 0);
            data[i] >>= 1;
        }
    }
    return crc;
}

int init_i2c(int bus, int addr) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return -1;
    }

    if (pi_i2c_open(bus, &addr, 0, &i2c_handle) < 0) {
        perror("pi_i2c_open");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int main() {
    sig(SIGINT, sigint_handler);
    sig(SIGTERM, sigint_handler);

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    gpioWrite(RELAY_GPIO, 0);

    if (init_i2c(I2C_BUS, SENSOR_ADDR1) < 0 ||
        init_i2c(I2C_BUS, SENSOR_ADDR2) < 0) {
        gpioTerminate();
        return 1;
    }

    if (pi_i2c_write_read_data(I2C_BUS, SENSOR_ADDR1, (const uint8_t[]) {0x36, 0x08}, 2, NULL, 0) < 0) {
        perror("pi_i2c_write_read_data");
        goto cleanup;
    }

    if (pi_i2c_write_read_data(I2C_BUS, SENSOR_ADDR2, (const uint8_t[]) {0x36, 0x08}, 2, NULL, 0) < 0) {
        perror("pi_i2c_write_read_data");
        goto cleanup;
    }

    FILE *log_file = fopen("flow_log.txt", "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    while (!shutdown) {
        uint8_t data1[3], data2[3];
        if (pi_i2c_write_read_data(I2C_BUS, SENSOR_ADDR1, NULL, 0, data1, 3) < 0 ||
            pi_i2c_write_read_data(I2C_BUS, SENSOR_ADDR2, NULL, 0, data2, 3) < 0) {
            perror("pi_i2c_write_read_data");
            continue;
        }

        if (crc8(data1, 2) != data1[2] || crc8(data2, 2) != data2[2]) {
            fprintf(stderr, "CRC error: %02X %02X %02X\n", data1[0], data1[1], data1[2]);
            fprintf(stderr, "          %02X %02X %02X\n", data2[0], data2[1], data2[2]);
            continue;
        }

        float flow1 = SCALE_FACTOR * ((data1[0] << 8) | data1[1]);
        float flow2 = SCALE_FACTOR * ((data2[0] << 8) | data2[1]);

        time_t timestamp = time(NULL);
        struct tm *tm = localtime(&timestamp);
        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, %5.2f ml/min, %5.2f ml/min\n", timestamp_str, flow1, flow2);
        fflush(log_file);

        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            gpioWrite(RELAY_GPIO, 1);
        } else if (flow1 >= FLOW_THRESHOLD && flow2 >= FLOW_THRESHOLD) {
            gpioWrite(RELAY_GPIO, 0);
        }
    }

cleanup:
    fclose(log_file);
    gpioTerminate();
    pi_i2c_close(I2C_BUS, &i2c_handle);
    pi_i2c_close(I2C_BUS, &i2c_handle);
    printf("Shutting down...\n");
    return 0;
}

