#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24
#define POLL_INTERVAL 200000
#define DRY_CONSECUTIVE_POLLS 3
#define MOTOR_RUN_TIME 5000000

static int rain_detected = 0;
static int dry_consecutive_count = 0;
static time_t last_rain_detected = 0;

void log_info(const char *message) {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

void log_warning(const char *message) {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_WARNING, "%s", message);
    closelog();
}

void log_error(const char *message) {
    openlog("rain_window", LOG_PID, LOG_USER);
    syslog(LOG_ERR, "%s", message);
    closelog();
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialise gpio");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_GPIO, 1);

    gpioSetMode(MOTOR_ENA_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT);

    return 0;
}

void motor_start() {
    gpioWrite(MOTOR_ENA_GPIO, 1);
    gpioWrite(MOTOR_IN1_GPIO, 1);
    gpioWrite(MOTOR_IN2_GPIO, 0);
}

void motor_stop() {
    gpioWrite(MOTOR_ENA_GPIO, 0);
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
}

void handle_rain_sensor() {
    int state = gpioRead(RAIN_SENSOR_GPIO);

    if (state == 0 && !rain_detected) {
        rain_detected = 1;
        last_rain_detected = time(NULL);
        log_info("Rain detected");
    }

    if (rain_detected && state == 1) {
        time_t current_time = time(NULL);
        int elapsed_time = current_time - last_rain_detected;

        if (elapsed_time >= POLL_INTERVAL) {
            dry_consecutive_count = 1;
        } else if (elapsed_time >= POLL_INTERVAL * (DRY_CONSECUTIVE_POLLS - 1)) {
            if (dry_consecutive_count < DRY_CONSECUTIVE_POLLS) {
                dry_consecutive_count++;
            } else {
                motor_start();
                log_info("Motor started");
            }
        }
    }
}

void handle_motor() {
    time_t current_time = time(NULL);

    if (rain_detected && current_time - last_rain_detected >= MOTOR_RUN_TIME) {
        motor_stop();
        rain_detected = 0;
        dry_consecutive_count = 0;
        last_rain_detected = 0;
        log_info("Motor stopped");
    }
}

int main() {
    if (init_gpio() != 0) {
        return 1;
    }

    log_info("Startup");

    while (1) {
        handle_rain_sensor();
        handle_motor();

        usleep(POLL_INTERVAL);

        if (gpioTerminate() < 0) {
            log_warning("Failed to terminate gpio");
        }

        if (signal(SIGINT, SIG_IGN) == SIG_ERR || signal(SIGTERM, SIG_IGN) == SIG_ERR) {
            log_warning("Failed to ignore signals");
        }
    }

    motor_stop();
    gpioTerminate();

    return 0;
}

