#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define BUTTON_1_PIN 21
#define BUTTON_2_PIN 22
#define DEBOUNCE_DELAY 50

static volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
