    unsigned long last_press = 0;
    unsigned long debounce_end = 0;

    while (running) {
        unsigned int current_state = gpioRead(pin);

        if (state != current_state) {
            if (!current_state) {
                last_press = time(NULL);
                debounce_end = last_press + DEBOUNCE_DELAY;
            }
        }

        if (current_state && debounce_end <= last_press) {
            if (pin == BUTTON_1_PIN) {
                gpioServo(SERVO_PIN, 2000);
            } else if (pin == BUTTON_2_PIN) {
                gpioServo(SERVO_PIN, 1000);
            }
        }

        state = current_state;
        usleep(100000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_1_PIN, PI_INPUT) < 0 ||
