#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define PIR_GPIO 4
#define LED_GPIO 17
#define LOG_FILE "security_log.txt"
#define TIMEOUT 60

static int g_running = 1;
static time_t g_start_time;
static FILE *g_log_file;

void sigint_handler(int signum) {
    g_running = 0;
    gpioWrite(LED_GPIO, 0);
    pigpio_stop();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR GPIO mode\n");
        goto cleanup;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        goto cleanup;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (g_running) {
        if (gpioRead(PIR_GPIO) == 1) {
            if (gpioWrite(LED_GPIO, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                goto cleanup;
            }

            g_start_time = time(NULL);
        }

        usleep(100000);
    }

    time_t end_time = time(NULL);
    double duration = difftime(end_time, g_start_time);

    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to turn off LED\n");
        goto cleanup;
    }

    fprintf(g_log_file, "Activation at %s\n", ctime(&g_start_time));
    fprintf(g_log_file, "Deactivation at %s, duration: %.2f seconds\n", ctime(&end_time), duration);

cleanup:
    if (g_log_file) {
        fclose(g_log_file);
    }
    pigpio_terminate();
    return 0;
}

