#define SERVO_MAX_PULSE_US 2000
#define SERVO_FREQ_HZ 50
#define PIR_GPIO 4
#define SERVO_GPIO 17

static gpiod_line_request_lines(struct gpiod_chip *chip, unsigned int nlines,
                                const char *const *lines, unsigned int flags) {
    int ret;
    struct gpiod_line_request *request;

    ret = gpiod_chip_get_request_array(chip, nlines, &request);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to get GPIO request array: %m");
        return NULL;
    }

    for (unsigned int i = 0; i < nlines; ++i) {
        ret = gpiod_line_request_set_direction(request[i], GPIOD_IN | GPIOD_ASIS);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to set direction for GPIO%u: %m", lines[i]);
            gpiod_chip_release_request_array(chip, nlines, request);
            return NULL;
        }
    }

    ret = gpiod_chip_request_lines(chip, nlines, lines, flags, "gpio_servo_pir");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO lines: %m");
        gpiod_chip_release_request_array(chip, nlines, request);
        return NULL;
    }

    return request;
}

static void servo_pwm(struct gpiod_line_request *request, unsigned int pulse_us) {
    struct timespec ts;
    long long int us_to_ns = 1000ULL;

    while (1) {
        gpiod_line_set_value(request, 1);
        ts.tv_sec = pulse_us / us_to_ns;
        ts.tv_nsec = (pulse_us % us_to_ns) * 1000;
        nanosleep(&ts, NULL);
        gpiod_line_set_value(request, 0);
        ts.tv_sec = 1 / SERVO_FREQ_HZ;
        ts.tv_nsec = (1000000000 / SERVO_FREQ_HZ) % 1000000000;
        nanosleep(&ts, NULL);
    }
}

static void log_message(int facility, const char *format, ...) {
    va_list args;
    char timestamp[32];
    time_t now;

    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    va_start(args, format);
    vsyslog(facility, timestamp ": " format, args);
    va_end(args);
}

int main(void) {
    int sockfd, new_fd, addrlen, n;
    struct sockaddr_in serv_addr, cli_addr;
    struct gpiod_chip *chip;
    struct gpiod_line_request *pir_request, *servo_request;
    unsigned int servo_pulse_us;
    char buffer[1024];
    ssize_t read_len;
    int ret;

    openlog("gpio_servo_pir", LOG_PID | LOG_NDELAY, LOG_USER);

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %m");
        exit(EXIT_FAILURE);
    }

    servo_request = gpio_servo_pir(chip, 1, &SERVO_GPIO, GPIOD_OUTPUT);
    if (!servo_request) {
        syslog(LOG_ERR, "Failed to request servo GPIO: %m");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    servo_pulse_us = (SERVO_MAX_PULSE_US + SERVO_MIN_PULSE_US) / 2;
    servo_pwm(servo_request, servo_pulse_us);

    pir_request = gpio_servo_pir(chip, 1, &PIR_GPIO, GPIOD_IN);
    if (!pir_request) {
        syslog(LOG_ERR, "Failed to request PIR GPIO: %m");
        gpiod_line_release(servo_request);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to create socket: %m");
        gpiod_line_release(servo_request);
        gpiod_line_release(pir_request);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    memset((void *)&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    serv_addr.sin_port = htons(5000);

    ret = bind(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr));
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to bind socket: %m");
        close(sockfd);
        gpiod_line_release(servo_request);
        gpiod_line_release(pir_request);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = listen(sockfd, 10);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to listen on socket: %m");
        close(sockfd);
        gpiod_line_release(servo_request);
        gpiod_line_release(pir_request);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    addrlen = sizeof(cli_addr);
    while (1) {
        new_fd = accept(sockfd, (struct sockaddr *)&cli_addr, &addrlen);
        if (new_fd < 0) {
            syslog(LOG_ERR, "Failed to accept connection: %m");
            continue;
        }

        if (fork() == 0) {
            close(sockfd);

            while ((read_len = read(new_fd, buffer, sizeof(buffer))) > 0) {
                buffer[read_len] = '\0';
                if (strncmp(buffer, "SERVO", 5) == 0) {
                    char *endptr;
                    unsigned int angle = strtoul(buffer + 5, &endptr, 10);
                    if (*endptr) {
                        log_message(LOG_WARNING, "Invalid SERVO command: %s", buffer);
                    } else if (angle < 0 || angle > 180) {
                        log_message(LOG_WARNING, "Invalid SERVO angle: %u", angle);
                    } else {
                        servo_pulse_us = (angle * (SERVO_MAX_PULSE_US - SERVO_MIN_PULSE_US) / 180 + SERVO_MIN_PULSE_US);
                        log_message(LOG_INFO, "Setting servo angle to %u", angle);
                    }
                } else if (strncmp(buffer, "PIR", 3) == 0) {
                    int pir_value = gpiod_line_get_value(pir_request);
                    snprintf(buffer, sizeof(buffer), "PIR:%s", pir_value ? "1" : "0");
                    write(new_fd, buffer, strlen(buffer));
                } else {
                    log_message(LOG_WARNING, "Unknown command: %s", buffer);
                }
                write(new_fd, buffer, read_len);
            }

            close(new_fd);
            exit(0);
        }
    }

    close(new_fd);
}

