#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define SENSOR_ADDR 0x23
#define RELAY_PIN 23
#define LUX_THRESHOLD 150
#define SAMPLE_INTERVAL 2000 // Sample interval in milliseconds
#define LOG_FILE "grow_log.txt"

int i2c_init(void);
void i2c_write_command(int handle, uint8_t command);
uint16_t i2c_read_data(int handle, uint8_t *buf, size_t len);
void log_timestamp_and_lux(const char *lux_str);
void setup_relay(int gpio);
void cleanup(void);

int main(void) {
    int i2c_fd, gpio_fd;
    uint16_t lux;
    char lux_str[10];
    time_t timestamp;

    if (i2c_init() < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    gpio_fd = pigpio_start(NULL, NULL);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        return 1;
    }

    setup_relay(RELAY_PIN);

    while (1) {
        usleep(120000); // Wait 120 ms for the conversion
        lux = i2c_read_data(i2c_fd, (uint8_t *)&lux, sizeof(lux));
        if (lux == 0) {
            fprintf(stderr, "Sensor not found or bus error\n");
            continue;
        }

        lux /= 1.2;
        snprintf(lux_str, sizeof(lux_str), "%d\n", lux);
        log_timestamp_and_lux(lux_str);

        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        usleep(SAMPLE_INTERVAL * 1000); // Wait for the sample interval
    }

    cleanup();
    return 0;
}

int i2c_init(void) {
    int i2c_fd = i2cOpen(I2C_BUS, 1);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        return -1;
    }

    if (i2cWriteByte(i2c_fd, SDA_PIN, SCL_PIN, SENSOR_ADDR, 0) < 0) {
        perror("i2cWriteByte");
        i2cClose(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

void i2c_write_command(int handle, uint8_t command) {
    if (i2cWriteByte(handle, SDA_PIN, SCL_PIN, SENSOR_ADDR, command) < 0) {
        perror("i2cWriteByte");
    }
}

uint16_t i2c_read_data(int handle, uint8_t *buf, size_t len) {
    ssize_t bytes_read = i2cReadDevice(handle, buf, len);
    if (bytes_read < 0) {
        perror("i2cReadDevice");
        return 0;
    }

    return bytes_read == len ? *(uint16_t *)buf : 0;
}

void log_timestamp_and_lux(const char *lux_str) {
    time(&timestamp);
    struct tm *tm_ptr = localtime(&timestamp);
    FILE *log_file = fopen(LOG_FILE, "a");

    if (!log_file) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%02d:%02d:%02d %s", tm_ptr->tm_hour, tm_ptr->tm_min, tm_ptr->tm_sec, lux_str);
    fflush(log_file);
    fclose(log_file);
}

void setup_relay(int gpio) {
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
}

void cleanup(void) {
    gpioTerminate();
    i2cClose(i2c_fd);
    remove(LOG_FILE);
}
