#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <time.h>
#include <sys/time.h>
#include <syslog.h>
#include <getopt.h>
#include <linux/gpio/consumer.h>

#define GPIO_DOUT 23
#define GPIO_SCK  24
#define GPIO_LOCK 25

#define BIT_DELAY_US 10
#define NUM_BITS 24
#define NUM_READINGS_TARE 10
#define NUM_READINGS_AVERAGE 5
#define NUM_RETRIES 3
#define SOLENOID_ON_MS 200

struct gpiod_line *dout_line;
struct gpiod_line *sck_line;
struct gpiod_line *lock_line;

int tare_offset = 0;
int scale = 1;
int threshold = 1000;
int duration = 500;

int read_hx711(void) {
    int data = 0;
    int bit;

    gpiod_line_set_value_cansleep(sck_line, 1);
    usleep(BIT_DELAY_US * 8);

    for (int i = 0; i < NUM_BITS; ++i) {
        gpiod_line_set_value_cansleep(sck_line, 0);
        usleep(BIT_DELAY_US);

        gpiod_line_get_value_cansleep(dout_line, &bit);
        data <<= 1;
        data |= bit;

        gpiod_line_set_value_cansleep(sck_line, 1);
        usleep(BIT_DELAY_US);
    }

    gpiod_line_set_value_cansleep(sck_line, 1);
    usleep(BIT_DELAY_US * 3); // Extra clock pulses for Channel A / Gain 128

    return data;
}

void log_error(const char *msg) {
    openlog("hx711_solenoid", LOG_PERROR | LOG_NDELAY, LOG_ERR);
    syslog(LOG_ERR, "%s", msg);
    closelog();
}

int main(int argc, char *argv[]) {
    int opt;
    int retries = 0;
    int raw_readings[NUM_READINGS_TARE];
    int raw_average[NUM_READINGS_AVERAGE];
    double weight;

    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 's':
                scale = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s --threshold <grams> --scale <factor> --duration <ms>\n", argv[0]);
                return 1;
        }
    }

    if (libgpiod_library_open() < 0) {
        log_error("Failed to open libgpiod library");
        return 1;
    }

    dout_line = gpiod_chip_get_line_byname(libgpiod_get_chip_byname("gpiochip0"), "gpio23");
    if (!dout_line) {
        log_error("Failed to get DOUT line");
        goto cleanup;
    }

    sck_line = gpiod_chip_get_line_byname(libgpiod_get_chip_byname("gpiochip0"), "gpio24");
    if (!sck_line) {
        log_error("Failed to get SCK line");
        goto cleanup;
    }

    lock_line = gpiod_chip_get_line_byname(libgpiod_get_chip_byname("gpiochip0"), "gpio25");
    if (!lock_line) {
        log_error("Failed to get LOCK line");
        goto cleanup;
    }

    if (gpiod_line_request_active_cansleep(dout_line, GPIOD_LINE_REQUEST_DIRECTION_IN) < 0) {
        log_error("Failed to request DOUT line direction");
        goto cleanup;
    }

    if (gpiod_line_request_active_cansleep(sck_line, GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0) {
        log_error("Failed to request SCK line direction");
        goto cleanup;
    }

    if (gpiod_line_request_active_cansleep(lock_line, GPIOD_LINE_REQUEST_DIRECTION_OUT) < 0) {
        log_error("Failed to request LOCK line direction");
        goto cleanup;
    }

    gpiod_line_set_value_cansleep(lock_line, 0);

    for (int i = 0; i < NUM_READINGS_TARE; ++i) {
        raw_readings[i] = read_hx711();
    }

    for (int i = 0; i < NUM_READINGS_TARE; ++i) {
        tare_offset += raw_readings[i];
    }

    tare_offset /= NUM_READINGS_TARE;

    while (1) {
        for (int i = 0; i < NUM_READINGS_AVERAGE; ++i) {
            raw_average[i] = read_hx711();
            usleep(duration * 1000);
        }

        int sum = 0;
        for (int i = 0; i < NUM_READINGS_AVERAGE; ++i) {
            sum += raw_average[i];
        }

        weight = (sum - tare_offset) * scale / (double)NUM_READINGS_AVERAGE;

        if (weight > threshold) {
            gpiod_line_set_value_cansleep(lock_line, 1);
            usleep(SOLENOID_ON_MS * 1000);
            gpiod_line_set_value_cansleep(lock_line, 0);
        }

        openlog("hx711_solenoid", LOG_PERROR | LOG_NDELAY, LOG_INFO);
        syslog(LOG_INFO, "Weight: %.2f grams", weight);
        closelog();
    }

cleanup:
    gpiod_line_release(dout_line);
    gpiod_line_release(sck_line);
    gpiod_line_release(lock_line);
    libgpiod_library_release();

    gpiod_line_set_value_cansleep(lock_line, 0);

    return 0;
}

