#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define CLIENT_ID "relay_controller_1"
#define TOPIC "home/lights/control"
#define KEEPALIVE 60
#define RETRY_DELAY 5
#define LOG_TAG "mqtt_relay"

static mosquitto_t *mosq;
static pigpio_t *pi;
static int gpio_state = LOW;

void mqtt_on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        mosquitto_subscribe(mosq, NULL, TOPIC, 0);
        syslog(LOG_INFO, "Connected to MQTT broker");
    } else {
        char connack[100];
        snprintf(connack, sizeof(connack), "Connack: %d", result);
        syslog(LOG_ERR, "%s", connack);
    }
}

void mqtt_on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    char *payload = (char *)message->payload;
    size_t payload_len = message->len;

    if (payload_len > 0 && (payload[payload_len - 1] == '\0')) {
        const char *state = strdup(payload);
        if (strcmp(state, "ON") == 0) {
            gpio_state = HIGH;
            gpioWrite(GPIO_PIN, gpio_state);
            syslog(LOG_INFO, "Received ON command, setting relay state to ON");
        } else if (strcmp(state, "OFF") == 0) {
            gpio_state = LOW;
            gpioWrite(GPIO_PIN, gpio_state);
            syslog(LOG_INFO, "Received OFF command, setting relay state to OFF");
        } else {
            syslog(LOG_ERR, "Received invalid command: %s", state);
            free(state);
        }
        free(state);
    } else {
        syslog(LOG_ERR, "Received message with invalid format");
    }
}

void mqtt_on_disconnect(struct mosquitto *mosq, void *userdata, int reason) {
    char disconn[100];
    snprintf(disconn, sizeof(disconn), "Disconnected: %d", reason);
    syslog(LOG_INFO, "%s", disconn);
    mosquitto_reconnect(mosq);
}

void mqtt_on_publish(struct mosquitto *mosq, void *userdata, int mid) {
    (void)mosq;
    (void)userdata;
    (void)mid;
    syslog(LOG_ERR, "Unexpected publish event");
}

void mqtt_on_log(struct mosquitto *mosq, void *userdata, int level, const char *str) {
    syslog(level >= LOG_ERR ? LOG_ERR : LOG_INFO, "%s", str);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, gpio_state);
}

void cleanup_gpio() {
    gpioTerminate();
}

void setup_mosquitto() {
    mosquitto_lib_init(NULL);

    mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        exit(EXIT_FAILURE);
    }

    mosquitto_set_log_function(mosq, mqtt_on_log);
    mosquitto_connect_callback_set(mosq, mqtt_on_connect);
    mosquitto_message_callback_set(mosq, mqtt_on_message);
    mosquitto_disconnect_callback_set(mosq, mqtt_on_disconnect);
    mosquitto_publish_callback_set(mosq, mqtt_on_publish);

    int opts = MOSQ_OPT_CLEAN_SESSION | MOSQ_OPT_KEEPALIVE;
    int rc = mosquitto_connect(mosq, "localhost", 1883, KEEPALIVE, opts);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
    }
}

void cleanup_mosquitto() {
    mosquitto_disconnect(mosq, 0);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT, shutting down");
    gpio_state = LOW;
    gpioWrite(GPIO_PIN, gpio_state);
    mosquitto_loop_stop(mosq, 0);
    cleanup_mosquitto();
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

int main() {
    openlog(LOG_TAG, LOG_PID | LOG_NDELAY, LOG_USER);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_gpio();
    setup_mosquitto();

    mosquitto_loop_start(mosq);

    while (1) {
        usleep(100000);
    }

    return 0;
}

