void cleanup_mosquitto() {
    mosquitto_disconnect(mosq, 0);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT, shutting down");
    gpio_state = LOW;
    gpioWrite(GPIO_PIN, gpio_state);
    mosquitto_loop_stop(mosq, 0);
    cleanup_mosquitto();
    cleanup_gpio();
    exit(EXIT_SUCCESS);
}

int main() {
    openlog(LOG_TAG, LOG_PID | LOG_NDELAY, LOG_USER);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    setup_gpio();
    setup_mosquitto();

    mosquitto_loop_start(mosq);

    while (1) {
        usleep(100000);
    }

    return 0;
}
