#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define Kp 0.5
#define Ki 0.05
#define PWM_FREQ 10000
#define TICKS_PER_REV 64
#define TIMEOUT 2000 // 2 seconds
#define MAX_DUTY 255

volatile int encoder_a_a[2] = {0, 0};
volatile int encoder_a_b[2] = {0, 0};
volatile int encoder_b_a[2] = {0, 0};
volatile int encoder_b_b[2] = {0, 0};

void encoder_isr(int gpio, uint32_t events, void *user_data) {
    if (events & PI_EDGE_RISING_EDGE) {
        *(int *)user_data += 1;
    }
}

void motor_control(int motor, int *counter, int *duty) {
    int dir = *counter < 0 ? HIGH : LOW;
    *duty = abs(*counter) * (MAX_DUTY / TICKS_PER_REV);
    gpio_write(motor + 2, dir);
    gpio_pwm_range(motor + 1, 0, MAX_DUTY);
    gpio_pwm_frequency(motor + 1, PWM_FREQ);
    gpio_pwm(motor + 1, *duty);
}

void pi_controller(int *counter, int *duty) {
    static double prev_error = 0;
    static double integral = 0;
    double error = 50.0 - (*counter * 60.0 / abs(*counter) / TICKS_PER_REV);
    integral += error * 0.01;
    if (integral > 1.0) integral = 1.0;
    if (integral < -1.0) integral = -1.0;
    *duty += (Kp * error + Ki * integral) * 255.0 / 2.0;
    if (*duty > MAX_DUTY) *duty = MAX_DUTY;
    if (*duty < 0) *duty = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, [](int signum) {
        gpioTerm();
        exit(0);
    });

    gpio_set_mode(17, PI_OUTPUT);
    gpio_set_mode(18, PI_INPUT);
    gpio_set_mode(22, PI_OUTPUT);
    gpio_set_mode(23, PI_INPUT);

    gpio_set_pwmfunction(17, 0);
    gpio_set_pwmfunction(22, 0);

    gpio_pwm_range(17, 0, MAX_DUTY);
    gpio_pwm_range(22, 0, MAX_DUTY);
    gpio_pwm_frequency(17, PWM_FREQ);
    gpio_pwm_frequency(22, PWM_FREQ);

    gpio_set_alertfunc(4, PI_EDGE_RISING_EDGE, encoder_isr, &encoder_a_a[0]);
    gpio_set_alertfunc(5, PI_EDGE_RISING_EDGE, encoder_isr, &encoder_a_b[0]);
    gpio_set_alertfunc(6, PI_EDGE_RISING_EDGE, encoder_isr, &encoder_b_a[0]);
    gpio_set_alertfunc(12, PI_EDGE_RISING_EDGE, encoder_isr, &encoder_b_b[0]);

    int motor_a_counter = 0;
    int motor_b_counter = 0;
    int motor_a_duty = 0;
    int motor_b_duty = 0;

    while (1) {
        motor_control(17, &motor_a_counter, &motor_a_duty);
        motor_control(22, &motor_b_counter, &motor_b_duty);

        pi_controller(&motor_a_counter, &motor_a_duty);
        pi_controller(&motor_b_counter, &motor_b_duty);

        printf("Motor A: RPM=%.2f, Duty=%d\n", motor_a_counter * 60.0 / abs(motor_a_counter) / TICKS_PER_REV, motor_a_duty);
        printf("Motor B: RPM=%.2f, Duty=%d\n", motor_b_counter * 60.0 / abs(motor_b_counter) / TICKS_PER_REV, motor_b_duty);

        usleep(100000); // 100 ms control period
    }

    gpioTerm();
    return 0;
}

