#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 17
#define HYSTERESIS 50
#define SAMPLE_INTERVAL 5000
#define ONE_TIME_HIGH_RES_MODE 0x21
#define LUX_CONVERSION_FACTOR 1.2

static int i2c_file;
static int relay_gpio;
static FILE *log_file;

void log_error(const char *message) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

int init_i2c() {
    const char *i2c_dev = "/dev/i2c-" I2C_BUS;
    if ((i2c_file = open(i2c_dev, O_RDWR)) < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_file, I2C_SLAVE, BH1750_ADDR) < 0) {
        log_error("Failed to acquire I2C bus access");
        close(i2c_file);
        return -1;
    }

    return 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio library");
        return -1;
    }

    if ((relay_gpio = gpioCreate(RELAY_GPIO)) < 0) {
        log_error("Failed to create GPIO handle");
        gpioTerm();
        return -1;
    }

    gpioSetMode(relay_gpio, PI_OUTPUT);
    gpioWrite(relay_gpio, 0);

    return 0;
}

int init_log() {
    if ((log_file = fopen("chicken_coop_log.txt", "w")) == NULL) {
        log_error("Failed to open log file");
        return -1;
    }

    return 0;
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }

    if (i2c_file >= 0) {
        ioctl(i2c_file, I2C_CLOSE);
    }

    if (relay_gpio >= 0) {
        gpioTerm();
    }

    if (gpioTerm() < 0) {
        log_error("Failed to terminate pigpio library");
    }
}

void handle_sigint(int sig) {
    cleanup();
    exit(0);
}

int main() {
    if (init_log() < 0) {
        return 1;
    }

    if (init_i2c() < 0 || init_gpio() < 0) {
        cleanup();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    time_t last_sample = time(NULL);
    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_sample >= SAMPLE_INTERVAL) {
            if (i2cWriteReadData(i2c_file, ONE_TIME_HIGH_RES_MODE, 0, 2, 0) < 0) {
                log_error("Failed to send One-Time High-Resolution Mode command");
                cleanup();
                return 1;
            }

            usleep(180000); // Wait 180 ms after sending the command

            unsigned char data[2];
            if (i2cReadData(i2c_file, data, 2) < 0) {
                log_error("Failed to read sensor data");
                cleanup();
                return 1;
            }

            int lux = (data[0] << 8 | data[1]) / LUX_CONVERSION_FACTOR;
            time_t now = time(NULL);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s: Lux = %d\n", timestamp, lux);

            int relay_state = lux < 50;
            if (relay_state != gpioRead(relay_gpio)) {
                gpioWrite(relay_gpio, relay_state);
                fprintf(log_file, "%s: Relay = %s\n", timestamp, relay_state ? "ON" : "OFF");
            }

            last_sample = current_time;
        }

        usleep(500000); // Sleep for the remaining time in the sample interval
    }

    cleanup();
    return 0;
}

int i2cWriteReadData(int file, unsigned char command, unsigned char *write_data, int write_len, int read_len) {
    if (write_data) {
        if (write(file, &command, 1) != 1) {
            return -1;
        }
        if (write(file, write_data, write_len) != write_len) {
            return -1;
        }
    }

    unsigned char read_buffer[read_len];
    if (read(file, read_buffer, read_len) != read_len) {
        return -1;
    }

    return read_len;
}

int i2cReadData(int file, unsigned char *data, int len) {
    return read(file, data, len);
}

