#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define DEBOUNCE_DELAY 50
#define MAIN_LOOP_DELAY 10

static void handle_interrupt(int sig) {
    gpioWrite(RELAY_GPIO, 0);
    gpioTerm();
    printf("Exiting...\n");
    exit(0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, handle_interrupt);

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0 ||
        gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerm();
        return 1;
    }

    uint32_t last_state = gpioRead(RELAY_GPIO);
    time_t last_change = time(NULL);

    while (1) {
        uint32_t current_state = gpioRead(SENSOR_GPIO);

        if (current_state == 1) {
            if (last_state == 0) {
                time_t now = time(NULL);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
                printf("%s: RELAY: TOGGLE (ON)\n", timestamp);
                gpioWrite(RELAY_GPIO, !last_state);
                last_change = now;
            }
        } else if (last_state == 1) {
            time_t now = time(NULL);
            char timestamp[30];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            printf("%s: RELAY: TOGGLE (OFF)\n", timestamp);
            last_change = now;
