#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450
#define HYSTERESIS 0.5
#define SAMPLE_INTERVAL 1000
#define LOG_FILE "water_flow.log"

volatile sig_atomic_t running = 1;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
unsigned long long pulse_count = 0;
double lpm = 0.0;
int solenoid_state = 1;
FILE *log_file = NULL;

void isr(int gpio, uint32_t events, void *user_data) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void log_event(const char *event, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: LPM=%.2f, Solenoid=%s\n", time_str, lpm, solenoid_state ? "OPEN" : "CLOSED");
}

void handle_signal(int sig) {
    running = 0;
    log_event("Signal received", solenoid_state);
    gpioWrite(SOLENOID_GPIO, 1);
    if (log_file) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(sig);
}

int main() {
    int ret;

    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioStrerror(ret));
        return 1;
    }

    if ((ret = gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode: %s\n", gpioStrerror(ret));
        goto cleanup;
    }

    if ((ret = gpioSetISRFuncEx(FLOW_SENSOR_GPIO, 1, isr, NULL)) < 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor GPIO: %s\n", gpioStrerror(ret));
        goto cleanup;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        goto cleanup;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        usleep(SAMPLE_INTERVAL * 1000);

        pthread_mutex_lock(&pulse_mutex);
        double new_lpm = (pulse_count / (double)PULSES_PER_LITER) * 60.0;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

