                solenoid_state = 1;
            }
        } else if (new_lpm < 4.5 - HYSTERESIS && solenoid_state == 1) {
            log_event("Solenoid closed", 0);
            solenoid_state = 0;
        }

        log_event("LPM", lpm);
        lpm = new_lpm;
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return ret < 0 ? 1 : 0;
}

