#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netinet/in.h>
#include <pigpio.h>

#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define HX711_DATA_GPIO 23
#define HX711_SCK_GPIO 24
#define SERVO_GPIO 18
#define TIMEOUT_ATTEMPTS 1000
#define TIMEOUT_US 1000
#define SERVER_PORT 12345
#define BUFFER_SIZE 1024

typedef struct {
    char calibration_factor[10];
    char server_ip[16];
    int server_port;
} Config;

void sigint_handler(int signum) {
    gpioTerm();
    close(sockfd);
    exit(0);
}

int read_hx711(double *data) {
    int data_bit = 0;
    int sck_state = 0;
    int attempts = 0;

    gpioWrite(HX711_SCK_GPIO, 1);
    usleep(1);

    while (attempts < TIMEOUT_ATTEMPTS) {
        gpioWrite(HX711_SCK_GPIO, 0);
        usleep(1);
        gpioWrite(HX711_SCK_GPIO, 1);
        usleep(1);

        sck_state = gpioRead(HX711_SCK_GPIO);
        if (sck_state == 0) {
            usleep(1);
            data_bit = gpioRead(HX711_DATA_GPIO);
            if (data_bit == 1) {
                *data |= 1 << attempts;
            }
        }

        attempts++;
    }

    if (attempts == TIMEOUT_ATTEMPTS) {
        return -1;
    }

    *data = (*data >> 8) * 268.4354375;
    return 0;
}

void servo_pulse(int pulse_width_us) {
    gpioServo(SERVO_GPIO, pulse_width_us);
}

void log_event(const char *event_type, double target_weight, double actual_weight, const char *error_message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];
    FILE *log_file;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("dispensing_log.json", "a");
    if (log_file) {
        fprintf(log_file, "{\"date\":\"%s\",\"time\":\"%s\",\"target_weight\":%.2f,\"actual_weight\":%.2f,\"error_message\":\"%s\"}\n", time_str, time_str, target_weight, actual_weight, error_message);
        fclose(log_file);
    }
}

int main() {
    int ret;
    double calibration_factor = 1.0;
    double target_weight = 0.0;
    double actual_weight = 0.0;
    double servo_pulse_width = 0.0;
    int sockfd;
    struct sockaddr_in serv_addr;
    Config config;
    char buffer[BUFFER_SIZE];

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    ret = read_config("config.ini", &config);
    if (ret < 0) {
        fprintf(stderr, "Failed to read config.ini\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_GPIO, PI_INPUT);
    gpioSetMode(HX711_SCK_GPIO, PI_OUTPUT);
    gpioSetMode(SERVO_GPIO, PI_SERVO_OUTPUT);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(config.server_port);
    inet_pton(AF_INET, config.server_ip, &serv_addr.sin_addr);

    ret = bind(sockfd, (struct sockaddr*)&serv_addr, sizeof(serv_addr));
    if (ret < 0) {
        perror("bind");
        return 1;
    }

    ret = listen(sockfd, 1);
    if (ret < 0) {
        perror("listen");
        return 1;
    }

    while (1) {
        int client_sockfd = accept(sockfd, NULL, NULL);
        if (client_sockfd < 0) {
            perror("accept");
            continue;
        }

        memset(buffer, 0, BUFFER_SIZE);
        ret = recv(client_sockfd, buffer, BUFFER_SIZE - 1, 0);
        if (ret <= 0) {
            perror("recv");
            close(client_sockfd);
            continue;
        }

        target_weight = atof(buffer);

        servo_pulse_width = SERVO_MIN_PULSE_WIDTH + (target_weight / 100.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH);
        servo_pulse(servo_pulse_width);
        usleep(1000000);

        ret = read_hx711(&actual_weight);
        if (ret < 0) {
            log_event("Sensor error", target_weight, 0.0, "HX711 timeout");
            continue;
        }

        snprintf(buffer, BUFFER_SIZE, "%.2f", actual_weight);
        send(client_sockfd, buffer, strlen(buffer), 0);
        close(client_sockfd);

        log_event("Dispensing event", target_weight, actual_weight, "");
    }

    gpioTerm();
    close(sockfd);
    return 0;
}

int read_config(const char *filename, Config *config) {
    FILE *file;
    char line[256];
    int ret = 1;

    file = fopen(filename, "r");
    if (file) {
        while (fgets(line, sizeof(line), file)) {
            if (strncmp(line, "calibration_factor=", 17) == 0) {
                strcpy(config->calibration_factor, line + 17);
            } else if (strncmp(line, "server_ip=", 9) == 0) {
                strcpy(config->server_ip, line + 9);
            } else if (strncmp(line, "server_port=", 10) == 0) {
                sscanf(line + 10, "%d", &config->server_port);
            }
        }
        fclose(file);

        if (strlen(config->calibration_factor) > 0 && strlen(config->server_ip) > 0 && config->server_port > 0) {
            ret = 0;
        }
    }

    if (ret < 0) {
        config->calibration_factor[0] = '1';
        config->server_ip[0] = '127';
        config->server_port = SERVER_PORT;
    }

    return ret;
}

