        debounce_ms = atoi(argv[1]);
        if (debounce_ms <= 0) {
            fprintf(stderr, "Invalid debounce time. Using default value: %d ms\n", DEBOUNCE_MS_DEFAULT);
            debounce_ms = DEBOUNCE_MS_DEFAULT;
        }

        if (atoi(argv[2]) == 1) {
