#include <stdio.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define SERVO_MIN_PULSE_WIDTH_US 500
#define SERVO_MAX_PULSE_WIDTH_US 2500
#define SERVO_PERIOD_US 20000
#define SERVO_ANGLE_STEP 10
#define SERVO_START_ANGLE 90

static struct termios orig_termios;
static int servo_angle = SERVO_START_ANGLE;
static int servo_pulse_width_us;

void handle_sigint(int sig) {
    gpioTerminate();
    tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios);
    exit(0);
}

void set_servo_pulse_width(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return;
    }

    servo_angle = angle;
    servo_pulse_width_us = (SERVO_PERIOD_US * angle + 500 * (180 - angle)) / 180;

    if (servo_pulse_width_us < SERVO_MIN_PULSE_WIDTH_US || servo_pulse_width_us > SERVO_MAX_PULSE_WIDTH_US) {
        fprintf(stderr, "Invalid servo pulse width: %d\n", servo_pulse_width_us);
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    tcgetattr(STDIN_FILENO, &orig_termios);
    atexit(tcsetattr(STDIN_FILENO, TCSANOW, &orig_termios));
    signal(SIGINT, handle_sigint);

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, SERVO_PERIOD_US);
    gpioServo(SERVO_PIN, servo_pulse_width_us);

    while (1) {
        int c = getchar();
        if (c == EOF)
            continue;

        switch (c) {
            case '+':
                set_servo_pulse_width(servo_angle + SERVO_ANGLE_STEP);
                break;
            case '-':
                set_servo_pulse_width(servo_angle - SERVO_ANGLE_STEP);
                break;
            case 'q':
                gpioTerminate();
                return 0;
            default:
                break;
        }

        gpioServo(SERVO_PIN, servo_pulse_width_us);
        printf("Servo angle: %d\n", servo_angle);
        fflush(stdout);
    }

    return 0;
}

