#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <sys/time.h>
#include <errno.h>
#include <linux/types.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE "line17"
#define LOG_FILE "motor_rpm.log"

static gpiod_line_event_cb_t event_cb;
static gpiod_line_data_callback_t data_cb;
static gpiod_line *line;
static gpiod_chip *chip;
static FILE *log_file;

void handle_event(struct gpiod_line *line, unsigned int value, unsigned int event) {
    if (event & GPIOD_LINE_EVENT_EDGE_RISING) {
        gpiod_line_event_acknowledge(line, event);
    }
}

void handle_data(struct gpiod_line *line, unsigned int value) {
    static uint64_t last_timestamp = 0;
    static uint32_t pulse_count = 0;
    struct timespec now;

    if (value) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - last_timestamp > 2 * 1e6) { // 2 ms debounce window
            pulse_count++;
            last_timestamp = now.tv_sec;
        }
    }
}

void log_rpm(const char *timestamp, double rpm) {
    fprintf(log_file, "%s,%f\n", timestamp, rpm);
    fflush(log_file);
}

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpiod_line_remove_event_callback(line, event_cb);
        gpiod_line_remove_data_callback(line, data_cb);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(0);
    }
}

int main() {
    struct timespec sleep_interval = { 0, 500 * 1e6 }; // 500 ms (0.5 s) sleep interval
    struct timespec debounce_interval = { 0, 2 * 1e6 }; // 2 ms debounce window
    int ret;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input_flags(line, GPIOD_LINE_REQUEST_FLAG_INPUT |
                                          GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW |
                                          GPIOD_LINE_REQUEST_FLAG_WAKEUP |
                                          GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        perror("gpiod_line_request_input_flags");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    event_cb = handle_event;
    data_cb = handle_data;

    gpiod_line_add_event_callback(line, event_cb);
    gpiod_line_add_data_callback(line, data_cb);

    double rpm;
    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &now);
        pulse_count = 0;
        gpiod_line_event_wait(line, debounce_interval);

        if (pulse_count > 0) {
            rpm = (pulse_count / 5.0) * 60.0;
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now.tv_sec));
            log_rpm(timestamp, rpm);
            printf("RPM: %.2f\n", rpm);
        }

        nanosleep(&sleep_interval, NULL);
    }

    return 0;
}

