Here's a complete, compilable C code for a Raspberry Pi 5 that uses the pigpio library to control a 5V relay on GPIO17 based on a TTP223 capacitive touch sensor on GPIO4. The program polls the sensor every 50 ms, toggles the relay state on the rising edge of a touch, and implements a failsafe: if the touch sensor remains continuously HIGH for more than 10 seconds, it forces the relay OFF and ignores further toggles until the sensor is released.

```c
#include <stdio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define SENSOR_GPIO 4
#define TOUCH_POLL_INTERVAL_MS 50
#define TOUCH_TIMEOUT_S 10
#define MAX_TOUCH_CHECKS (TOUCH_TIMEOUT_S * 1000 / TOUCH_POLL_INTERVAL_MS)

volatile sig_atomic_t g_interrupt_received = 0;

void touch_sensor_handler(int sig) {
    g_interrupt_received = 1;
}

void relay_init(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        exit(EXIT_FAILURE);
    }

    gpioWrite(RELAY_GPIO, 0);
}

void touch_sensor_init(void) {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        perror("gpioSetMode");
        exit(EXIT_FAILURE);
    }
}

int main(void) {
    int touch_count = 0;
    int last_touch_time = 0;
    int touch_state = 0;

    signal(SIGINT, touch_sensor_handler);
    signal(SIGTERM, touch_sensor_handler);

    relay_init();
    touch_sensor_init();

    while (!g_interrupt_received) {
        int current_touch_state = gpioRead(SENSOR_GPIO);

        if (current_touch_state == PI_BAD_GPIO) {
            perror("gpioRead");
            exit(EXIT_FAILURE);
        }

        if (current_touch_state != touch_state) {
            touch_state = current_touch_state;
            touch_count = 0;
            last_touch_time = time(NULL);

            if (touch_state) {
                gpioWrite(RELAY_GPIO, !gpioRead(RELAY_GPIO));
            }
        }

        if (touch_count++ >= MAX_TOUCH_CHECKS) {
            if (touch_state) {
                gpioWrite(RELAY_GPIO, 0);
                touch_count = 0;
            }
            last_touch_time = time(NULL);
        }

        usleep(TOUCH_POLL_INTERVAL_MS * 1000);

        if (difftime(time(NULL), last_touch_time) > TOUCH_TIMEOUT_S) {
            gpioWrite(RELAY_GPIO, 0);
            break;
        }
    }

    gpioTerminate();

    return 0;
}
