#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>

#define PWM_GPIO 18
#define DIRECTION_GPIO 23
#define SENSOR_GPIO 24
#define KP 1.0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.csv"

struct flow_data {
    double target_flow_rate;
    double flow_rate;
    int valve_position;
    time_t last_sample_time;
};

void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    static long long pulse_count = 0;

    if (level == HIGH) {
        pulse_count++;
    }
}

void log_flow_data(struct flow_data *data) {
    FILE *log_file = fopen(LOG_FILE, "a");

    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s,%f,%d\n", timestamp, data->flow_rate, data->valve_position);
    fclose(log_file);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
        exit(1);
    }

    double target_flow_rate = atof(argv[1]);

    if (target_flow_rate <= 0.0) {
        fprintf(stderr, "Invalid target flow rate. Must be positive.\n");
        exit(1);
    }

    if (wiringPiSetup() == -1) {
        perror("Failed to initialize wiringPi");
        exit(1);
    }

    pinMode(DIRECTION_GPIO, OUTPUT);
    digitalWrite(DIRECTION_GPIO, HIGH);
    pinMode(PWM_GPIO, OUTPUT);
    pwmSetMode(PWM_GPIO, PWM_MODE_MS);
    pwmSetClock(500);
    pwmSetRange(255);
    pwmSetMode(PWM_GPIO, PWM_MODE_MS);
    pwmSetChannel(PWM_GPIO, 0);
    pwmWrite(PWM_GPIO, 255);

    if (wiringPiISR(SENSOR_GPIO, INT_EDGE_RISING, flow_sensor_isr) == 0) {
        perror("Failed to register flow sensor ISR");
        exit(1);
    }

    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd == -1) {
        perror("Failed to open log file");
        exit(1);
    }

    struct flow_data data = {
        .target_flow_rate = target_flow_rate,
        .flow_rate = 0.0,
        .valve_position = 255,
        .last_sample_time = 0,
    };

    while (1) {
        time_t now = time(NULL);
        double elapsed_ms = (now - data.last_sample_time) * 1000;
        data.last_sample_time = now;

        if (elapsed_ms < SAMPLE_INTERVAL_MS) {
            usleep(static_cast<useconds_t>(SAMPLE_INTERVAL_MS * 1000 - elapsed_ms));
        }

        long long pulse_count_since_last_sample = pulseIn(SENSOR_GPIO, HIGH, SAMPLE_INTERVAL_MS * 1000);
        data.flow_rate = pulse_count_since_last_sample * 1.0 / 450.0;
        int valve_position = static_cast<int>(KP * (data.target_flow_rate - data.flow_rate));
        valve_position = clamp(valve_position, 0, 255);
        data.valve_position = valve_position;
        pwmWrite(PWM_GPIO, valve_position);

        log_flow_data(&data);
    }

    close(fd);
    pwmWrite(PWM_GPIO, 0);
    digitalWrite(DIRECTION_GPIO, LOW);
    wiringPiISR(SENSOR_GPIO, INT_EDGE_RISING, NULL);
    wiringPiTerminate();

    return 0;
}

int clamp(int value, int min, int max) {
    if (value < min) {
        return min;
    }

    if (value > max) {
        return max;
    }

    return value;
}

