#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define RFID_SPI_CH 0
#define RFID_SPI_FREQ 100000
#define RFID_READ_LEN 10
#define BUTTON_GPIO 22
#define LOCK_GPIO_1 17
#define LOCK_GPIO_2 27
#define DEBOUNCE_MS 50
#define UNLOCK_MS 5000
#define LOG_FILE "/var/log/door_access.log"

static char valid_tag[RFID_READ_LEN] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

void log_access(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(stderr, "%s: %s\n", time_string, message);
    fprintf(stderr, "%s\n", time_string);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", time_string, message);
        fclose(log_file);
    }
}

int rfid_read() {
    int fd = spiOpen(RFID_SPI_CH, RFID_SPI_FREQ);
    if (fd < 0) {
        log_access("RFID read failure");
        return -1;
    }

    uint8_t buffer[RFID_READ_LEN];
    int bytes_read = spiXfer(fd, buffer, RFID_READ_LEN);
    if (bytes_read != RFID_READ_LEN) {
        log_access("RFID read failure");
        spiClose(fd);
        return -1;
    }

    if (memcmp(buffer, valid_tag, RFID_READ_LEN) != 0) {
        log_access("Invalid tag");
        return -1;
    }

    spiClose(fd);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        log_access("gpioInitialise failure");
        return 1;
    }

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUp(BUTTON_GPIO, 1);
    gpioSetMode(LOCK_GPIO_1, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO_2, PI_OUTPUT);

    int button_state = gpioRead(BUTTON_GPIO);
    int locked = 1;

    while (1) {
        if (!locked && gpioRead(BUTTON_GPIO) == 0) {
            gpioWrite(LOCK_GPIO_1, 0);
            gpioWrite(LOCK_GPIO_2, 0);
            usleep(UNLOCK_MS * 1000);
            gpioWrite(LOCK_GPIO_1, 1);
            gpioWrite(LOCK_GPIO_2, 1);
            log_access("Successful authentication");
        } else if (rfid_read() == 0) {
            button_state = gpioRead(BUTTON_GPIO);
            if (button_state == 0) {
                locked = !locked;
                log_access("Authentication started");
            }
        }

        gpioDelay(100);

        if (gpioTerminate() != 0) {
            log_access("gpioTerminate failure");
            break;
        }
    }

    gpioTerminate();
    return 0;
}

