#include <gpiod.h>
#include <wiringPi.h>

#define MOTOR_A_A 5
#define MOTOR_A_B 6
#define MOTOR_B_A 26
#define MOTOR_B_B 19
#define MOTOR_1_ENA 23
#define MOTOR_1_IN1 24
#define MOTOR_1_IN2 25
#define MOTOR_2_ENB 12
#define MOTOR_2_IN3 16
#define MOTOR_2_IN4 20
#define LOG_FILE "motor_log.csv"
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100
#define PWM_FREQ 100
#define TARGET_RPM 60
#define NUM_SAMPLES 10

gpiod_chip *chip;
gpiod_line_request_linestate_cb_t encoder_cb;
gpiod_line_request_data_t encoder_req;
gpiod_line_request_data_t motor_req;
pthread_t encoder_thread;
pthread_mutex_t encoder_mutex;
int encoder_count[2] = {0, 0};
int motor_pwm_duty[2] = {0, 0};
double motor_speed[2] = {0.0, 0.0};
double error[2] = {0.0, 0.0};
double integral[2] = {0.0, 0.0};
double derivative[2] = {0.0, 0.0};
double prev_error[2] = {0.0, 0.0};
double prev_integral[2] = {0.0, 0.0};

void encoder_cb(struct gpiod_line_request *req, unsigned int value, unsigned int event, void *user_data) {
    pthread_mutex_lock(&encoder_mutex);
    if (event == GPIOD_EDGE_RISING) {
        if (req->number == MOTOR_A_A) {
            encoder_count[0] += value ? -1 : 1;
        } else if (req->number == MOTOR_B_A) {
            encoder_count[1] += value ? -1 : 1;
        }
    }
    pthread_mutex_unlock(&encoder_mutex);
}

void motor_pwm(int motor, int duty) {
    gpiod_line_set_value(motor_req[motor], duty);
    usleep((1000000000 / PWM_FREQ) - (duty * (1000000000 / PWM_FREQ) / 100));
    gpiod_line_set_value(motor_req[motor], !duty);
}

void control_loop(int motor) {
    double sample_time = SAMPLE_TIME_MS / 1000.0;
    double dt = 0.0;
    double setpoint = TARGET_RPM * 2 * M_PI / 60;
    double error_sum = 0.0;

    while (1) {
        pthread_mutex_lock(&encoder_mutex);
        double current_speed = encoder_count[motor] * (TARGET_RPM * 2 * M_PI / 60) / NUM_SAMPLES;
        pthread_mutex_unlock(&encoder_mutex);

        dt = sample_time - dt;
        error[motor] = setpoint - current_speed;
        derivative[motor] = (error[motor] - prev_error[motor]) / dt;
        integral[motor] += error[motor] * dt;
        double output = KP * error[motor] + KI * integral[motor] + KD * derivative[motor];
        motor_pwm_duty[motor] = output * 100;
        motor_pwm(motor, motor_pwm_duty[motor]);

        prev_error[motor] = error[motor];
        prev_integral[motor] = integral[motor];
        usleep(sample_time * 1000000);
    }
}

void log_data(void) {
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "Motor,Speed(RPM),P,I,D,Output(%)\n");

    while (1) {
        pthread_mutex_lock(&encoder_mutex);
        double motor_speeds[2] = {encoder_count[0] * (TARGET_RPM * 2 * M_PI / 60) / NUM_SAMPLES,
                                  encoder_count[1] * (TARGET_RPM * 2 * M_PI / 60) / NUM_SAMPLES};
        pthread_mutex_unlock(&encoder_mutex);

        fprintf(log_file, "%d,%.2f,%.2f,%.2f,%.2f,%.0f\n", motor_speeds[0] > motor_speeds[1] ? 1 : 2,
                motor_speeds[0], error[0], integral[0], derivative[0], motor_pwm_duty[0]);
        fflush(log_file);
        usleep(SAMPLE_TIME_MS * 1000);
    }
}

void sigint_handler(int sig) {
    gpiod_line_release(chip, &motor_req[0]);
    gpiod_line_release(chip, &motor_req[1]);
    gpiod_chip_close(chip);
    fclose(log_file);
    pthread_join(encoder_thread, NULL);
    pthread_mutex_destroy(&encoder_mutex);
    exit(0);
}

