    signal(SIGTERM, sigint_handler);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    pthread_mutex_init(&encoder_mutex, NULL);

