    encoder_req[MOTOR_A_B].flags = GPIOD_LINE_REQUEST_INPUT;
    encoder_req[MOTOR_B_A].flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_BOTH;
    encoder_req[MOTOR_B_B].flags = GPIOD_LINE_REQUEST_INPUT;

    if (gpiod_line_request_array(chip, 4, encoder_req) < 0) {
        perror("Failed to request GPIO lines for encoders");
        return 1;
    }

    encoder_req[MOTOR_A_A].callback = &encoder_cb;
    encoder_req[MOTOR_A_B].callback = &encoder_cb;
    encoder_req[MOTOR_B_A].callback = &encoder_cb;
    encoder_req[MOTOR_B_B].callback = &encoder_cb;

    if (gpiod_line_request_array(chip, 4, encoder_req) < 0) {
        perror("Failed to set callbacks for encoders");
        return 1;
    }

    motor_req[0].flags = GPIOD_LINE_REQUEST_DIR_OUT | GPIOD_LINE_REQUEST_FUNCTION_GPIO;
    motor_req[1].flags = GPIOD_LINE_REQUEST_DIR_OUT | GPIOD_LINE_REQUEST_FUNCTION_GPIO;

    if (gpiod_line_request_array(chip, 6, motor_req) < 0) {
