#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define MPR121_I2C_BUS 1
#define MPR121_I2C_ADDR 0x5A
#define RELAY_GPIO 17

static const char *LOG_FILE = "relay_log.txt";

void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];
    FILE *log_file = fopen(LOG_FILE, "a");

    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: Relay state: %s\n", time_string, state ? "ON" : "OFF");
    fclose(log_file);
}

int mpr121_init(void) {
    int i2c_fd, ret;

    i2c_fd = pigpio_i2c_open(MPR121_I2C_BUS, MPR121_I2C_ADDR, 0);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    // Soft reset
    ret = pigpio_i2c_write_byte_data(i2c_fd, MPR121_I2C_ADDR, 0x00);
    if (ret < 0) {
        perror("Failed to write soft reset command");
        goto cleanup_i2c;
    }

    // Configure filtering
    ret = pigpio_i2c_write_byte_data(i2c_fd, MPR121_I2C_ADDR, 0x0F);
    if (ret < 0) {
        perror("Failed to write filtering configuration");
        goto cleanup_i2c;
    }

    // Set touch and release thresholds
    for (int i = 0; i < 12; ++i) {
        ret = pigpio_i2c_write_byte_data(i2c_fd, MPR121_I2C_ADDR, 0x02 + i);
        if (ret < 0) {
            perror("Failed to write touch threshold");
            goto cleanup_i2c;
        }

        ret = pigpio_i2c_write_byte_data(i2c_fd, MPR121_I2C_ADDR, 0x03 + i);
        if (ret < 0) {
            perror("Failed to write release threshold");
            goto cleanup_i2c;
        }
    }

    // Enable run mode
    ret = pigpio_i2c_write_byte_data(i2c_fd, MPR121_I2C_ADDR, 0x08);
    if (ret < 0) {
        perror("Failed to enable run mode");
        goto cleanup_i2c;
    }

    return i2c_fd;

cleanup_i2c:
    close(i2c_fd);
    return -1;
}

void mpr121_deinit(int i2c_fd) {
    close(i2c_fd);
}

int main(void) {
    int i2c_fd, gpio_fd, relay_state = 0;
    unsigned char touch_status[2];

    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return 1;
    }

    i2c_fd = mpr121_init();
    if (i2c_fd < 0) {
        goto cleanup_gpio;
    }

    gpio_fd = gpioOpen(RELAY_GPIO, GPIODIR_OUT, 0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO");
        goto cleanup_mpr121;
    }

    while (1) {
        usleep(50000);

        ret = pigpio_i2c_read_i2c_block_data(i2c_fd, MPR121_I2C_ADDR, 2, touch_status);
        if (ret < 0) {
            perror("Failed to read touch status");
            goto cleanup_gpio;
        }

        if ((touch_status[0] & 0x0F) != 0) {
            relay_state = 1;
            gpioWrite(RELAY_GPIO, 1);
            log_relay_state(1);
        } else if (relay_state) {
            gpioWrite(RELAY_GPIO, 0);
            log_relay_state(0);
            relay_state = 0;
        }
    }

cleanup_gpio:
    gpioTerm();
cleanup_mpr121:
    mpr121_deinit(i2c_fd);

cleanup_gpio:
    gpioTerm();

    return 0;
}

