#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/ioctl.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define LOG_FILE "valve_log.txt"

static gpiod_line_request_data_v1 request_data = {
    .direction = GPIOD_LINE_DIR_OUT,
    .debounce = GPIOD_DEBOUNCE_24MS,
    .flags = GPIOD_LINE_FLAG_ACTIVE_HIGH,
};

void log_valve_event(const char *valve, int on) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%dT%H:%M:%S", timeinfo);
    fprintf(stderr, "%s: Valve %s: %s\n", time_string, valve, on ? "ON" : "OFF");
    fprintf(stderr, "%s: Valve %s: %s\n", LOG_FILE, valve, on ? "ON" : "OFF");
}

int main(void) {
    int fd_valve1, fd_valve2, ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;

    fd_valve1 = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd_valve1 < 0) {
        perror("Failed to open log file");
        return 1;
    }

    chip = gpiod_chip_open_byname("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!line1) {
        perror("Failed to get GPIO line 1");
        goto cleanup_chip;
    }

    line2 = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!line2) {
        perror("Failed to get GPIO line 2");
        goto cleanup_line1;
    }

    ret = gpiod_line_request_output_flags(line1, &request_data, GPIOD_LINE_REQUEST_DIRECTION_INPUT_OUTPUT);
    if (ret < 0) {
        perror("Failed to request output for GPIO line 1");
        goto cleanup_line2;
    }

    ret = gpiod_line_request_output_flags(line2, &request_data, GPIOD_LINE_REQUEST_DIRECTION_INPUT_OUTPUT);
    if (ret < 0) {
        perror("Failed to request output for GPIO line 2");
        goto cleanup_line1;
    }

    for (;;) {
        gpiod_line_set_value(line1, 1);
        log_valve_event("Valve 1", 1);
        usleep(500 * 1000);
        gpiod_line_set_value(line1, 0);
        log_valve_event("Valve 1", 0);
        sleep(5);

        gpiod_line_set_value(line2, 1);
        log_valve_event("Valve 2", 1);
        usleep(1000 * 1000);
        gpiod_line_set_value(line2, 0);
        log_valve_event("Valve 2", 0);
        sleep(10);
    }

cleanup_line2:
    gpiod_line_release(line2);
cleanup_line1:
    gpiod_line_release(line1);
cleanup_chip:
    gpiod_chip_put(chip);

    close(fd_valve1);

    return 0;
}

