#define MPR121_ADDR 0x5A
#define SDA_PIN 2
#define SCL_PIN 3
#define RELAY_PIN 17

int i2c_file;
int i2c_result;

void i2c_init() {
    const char *i2c_bus = "/dev/i2c-1";
    if ((i2c_file = open(i2c_bus, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_file, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Failed to acquire I2C address");
        exit(1);
    }
}

void mpr121_init() {
    i2c_result = pigpio_i2cWrite(i2c_file, 0x00, 0x00);
    if (i2c_result != 2) {
        perror("Failed to write to MPR121");
        exit(1);
    }

    i2c_result = pigpio_i2cWrite(i2c_file, 0x01, 0x10 | (0x0A << 4));
    if (i2c_result != 4) {
        perror("Failed to write to MPR121");
        exit(1);
    }

    i2c_result = pigpio_i2cWrite(i2c_file, 0x02, 0x20);
    if (i2c_result != 2) {
        perror("Failed to write to MPR121");
        exit(1);
    }

    i2c_result = pigpio_i2cWrite(i2c_file, 0x03, 0x01);
    if (i2c_result != 2) {
        perror("Failed to write to MPR121");
        exit(1);
    }

    i2c_result = pigpio_i2cWrite(i2c_file, 0x00, 0x20 | (1 << 7));
    if (i2c_result != 2) {
        perror("Failed to write to MPR121");
        exit(1);
    }

    usleep(100000); // Wait 100 ms for stabilization
}

void relay_init() {
    gpioInitialise();
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);
}

int main() {
    i2c_init();
    mpr121_init();
    relay_init();

    while (1) {
        usleep(100000); // 100 ms delay

        uint8_t touch_status = 0;
        i2c_result = pigpio_i2cRead(i2c_file, 0x00, &touch_status, 1);
        if (i2c_result != 1) {
            perror("Failed to read from MPR121");
            exit(1);
        }

        if (touch_status > 0) {
            gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
            printf("Relay status: %s\n", gpioRead(RELAY_PIN) ? "ON" : "OFF");
        }
    }

    gpioTerm();
    close(i2c_file);
    return 0;
}

void signal_handler(int sig) {
    gpioTerm();
    close(i2c_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return main();
}

