#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define RELAY_GPIO 18
#define PIR_GPIO 17
#define LOG_FILE "door_events.log"
#define RATE_LIMIT 2000 // 2 seconds in milliseconds
#define POLL_INTERVAL 50 // 50 ms polling interval

time_t last_event_time = 0;
time_t rate_limit_time = 0;
int relay_state = 0;

void log_event(const char *event) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(stderr, "%s: %s\n", timestamp, event);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fclose(log_file);
    }
}

void unlock_door() {
    gpioWrite(RELAY_GPIO, 1);
    usleep(500000); // 500 ms
    gpioWrite(RELAY_GPIO, 0);
    rate_limit_time = time(NULL) + RATE_LIMIT;
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        exit(1);
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file) {
        fclose(log_file);
    } else {
        perror("Failed to create log file");
        exit(1);
    }

    while (1) {
        if (gpioRead(PIR_GPIO) == 1 && time(NULL) > rate_limit_time) {
            if (!relay_state) {
                log_event("Motion detected");
                unlock_door();
                log_event("Door unlocked");
            }
            relay_state = 1;
            rate_limit_time = time(NULL) + RATE_LIMIT;
        }

        usleep(POLL_INTERVAL * 1000); // 50 ms polling interval
    }

    gpioTerminate();
    return 0;
}

