#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR_1_PIN 17
#define MOTOR_2_PIN 27
#define MIN_PWM_DUTY 0
#define MAX_PWM_DUTY 255
#define MIN_DURATION 50
#define MAX_DURATION 200
#define MIN_STEPS 5
#define MAX_STEPS 15
#define STEP_DELAY 1000000

volatile sig_atomic_t shutdown = 0;

void signal_handler(int sig) {
    shutdown = 1;
}

void play_pattern(int steps, int* pwm_duties_1, int* pwm_duties_2, int* durations) {
    for (int i = 0; i < steps; ++i) {
        gpioPWM(MOTOR_1_PIN, pwm_duties_1[i]);
        gpioPWM(MOTOR_2_PIN, pwm_duties_2[i]);
        gpioDelay(durations[i]);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    if (gpioSetMode(MOTOR_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return 1;
    }

    gpioSetPWMfrequency(MOTOR_1_PIN, 800);
    gpioSetPWMfrequency(MOTOR_2_PIN, 800);

    srand(time(NULL));

    while (!shutdown) {
        int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        int* pwm_duties_1 = malloc(steps * sizeof(int));
        int* pwm_duties_2 = malloc(steps * sizeof(int));
        int* durations = malloc(steps * sizeof(int));

        if (!pwm_duties_1 || !pwm_duties_2 || !durations) {
            fprintf(stderr, "Failed to allocate memory\n");
            continue;
        }

        for (int i = 0; i < steps; ++i) {
            pwm_duties_1[i] = rand() % (MAX_PWM_DUTY - MIN_PWM_DUTY + 1) + MIN_PWM_DUTY;
            pwm_duties_2[i] = rand() % (MAX_PWM_DUTY - MIN_PWM_DUTY + 1) + MIN_PWM_DUTY;
            durations[i] = rand() % ((MAX_DURATION - MIN_DURATION) / 2) * 2 + MIN_DURATION;
        }

        play_pattern(steps, pwm_duties_1, pwm_duties_2, durations);

        free(pwm_duties_1);
        free(pwm_duties_2);
        free(durations);
    }

    gpioTerm();
    return 0;
}

