#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define THRESHOLD 10.0
#define CAL_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define READ_INTERVAL 500000
#define TIMEOUT 500000

static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file;

int init_pigpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return -1;
    }
    return 0;
}

void cleanup_pigpio() {
    gpioTerminate();
}

int read_hx711(int32_t *data) {
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0 ||
        gpioWrite(HX711_CLOCK_PIN, 0) < 0 ||
        gpioWrite(HX711_DATA_PIN, 0) < 0 ||
        gpioWrite(HX711_CLOCK_PIN, 1) < 0 ||
        gpioWrite(HX711_DATA_PIN, 1) < 0 ||
        gpioWrite(HX711_CLOCK_PIN, 0) < 0 ||
        gpioRead(HX711_DATA_PIN, data) < 0) {
        perror("Failed to read HX711 data");
        return -1;
    }
    return 0;
}

double hx711_to_weight(int32_t data) {
    return (double)(data - offset) * scale_factor;
}

void log_weight(double weight) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s: %.4f kg\n", time_str, weight);
}

int load_calibration() {
    FILE *cal_file = fopen(CAL_FILE, "r");
    char line[128];
    int ret = 1;

    if (cal_file) {
        while (fgets(line, sizeof(line), cal_file)) {
            if (sscanf(line, "%lf %lf", &scale_factor, &offset) == 2) {
                ret = 0;
                break;
            }
        }
        fclose(cal_file);
    }

    if (ret) {
        fprintf(stderr, "Missing or invalid calibration data. Using defaults.\n");
    }

    return ret;
}

void save_calibration() {
    FILE *cal_file = fopen(CAL_FILE, "w");

    if (cal_file) {
        fprintf(cal_file, "%.4f %.4f\n", scale_factor, offset);
        fclose(cal_file);
    }
}

int main(int argc, char *argv[]) {
    int32_t data;
    double weight;
    int calibrate = 1;
    int i;
    double avg_offset = 0.0;

    if (init_pigpio() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    if (load_calibration()) {
        if (calibrate) {
            for (i = 0; i < 100; i++) {
                if (read_hx711(&data) < 0) {
                    continue;
                }
                avg_offset += hx711_to_weight(data);
                usleep(READ_INTERVAL);
            }
            avg_offset /= 100;
            scale_factor = 1.0;
            offset = avg_offset;
            save_calibration();
            calibrate = 0;
        }
    }

    while (1) {
        if (read_hx711(&data) < 0) {
            usleep(TIMEOUT);
            continue;
        }
        weight = hx711_to_weight(data);
        log_weight(weight);

        if (weight > THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Lock engaged: %.4f kg\n", weight);
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        usleep(READ_INTERVAL);
    }

cleanup:
    fclose(log_file);
    cleanup_pigpio();
    return 0;
}

