#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define HX711_DT_PIN 23
#define HX711_SCK_PIN 24
#define SOLENOID_PIN 17
#define LOG_FILE "stock_events.txt"

static int g_file;

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
    dprintf(g_file, "%s: %s\n", time_string, message);
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio library");
        return -1;
    }

    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0 ||
        gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO modes");
        return -1;
    }

    return 0;
}

int open_log_file() {
    if ((g_file = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        perror("Failed to open log file");
        return -1;
    }

    return 0;
}

void close_log_file() {
    if (g_file >= 0) {
        close(g_file);
        g_file = -1;
    }
}

int hx711_read(int *data) {
    int i;
    unsigned long long sum = 0;
    unsigned long long product = 1;

    gpioWrite(HX711_SCK_PIN, 0);
    usleep(10);

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        usleep(10);

        if (gpioRead(HX711_DT_PIN) == 0) {
            sum += product;
        }

        product *= 2;
        gpioWrite(HX711_SCK_PIN, 0);
        usleep(10);
    }

    *data = (int)(sum >> 8);

    return 0;
}

int main() {
    int data, previous_data = 0, solenoid_on = 0;
    struct sigaction sa;

    if (init_gpio() < 0) {
        return 1;
    }

    if (open_log_file() < 0) {
        return 1;
    }

    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    sa.sa_handler = SIG_IGN;
    sigaction(SIGPIPE, &sa, NULL);

    while (1) {
        if (hx711_read(&data) < 0) {
            perror("Failed to read HX711 data");
            continue;
        }

        if (data == 0xFFFF) {
            perror("Data line stuck high");
            continue;
        }

        if (data < previous_data) {
            if (solenoid_on == 0 && data - previous_data < 100) {
                gpioWrite(SOLENOID_PIN, 1);
                solenoid_on = 1;
                log_event("Solenoid activated");
                usleep(5 * 1000 * 1000);
            }
        }

        previous_data = data;
        sleep(1);
    }

    close_log_file();
    gpioTerm();

    return 0;
}

