#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define TIMEOUT_MS 100
#define KNOWN_WEIGHT 5.0

static double calibration_factor = 0.0;
static time_t last_log_time = 0;

void sigint_handler(int signum) {
    printf("Unlocking solenoid and terminating...\n");
    gpioTerm(SOLENOID_PIN);
    pigpio_stop();
    exit(0);
}

int read_hx711(int32_t *data) {
    uint32_t data_bits = 0;
    uint32_t bit_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    gpioWrite(HX711_CLOCK_PIN, 0);
    usleep(1000); // Clock low delay

    gpioWrite(HX711_CLOCK_PIN, 1);
    usleep(1); // Clock high delay

    gpioWrite(HX711_DATA_PIN, 1);
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);

    while (bit_count < 24) {
        if (gpioRead(HX711_DATA_PIN)) {
            if (bit_count > 0) {
                data_bits |= (1 << (23 - bit_count));
            }
            usleep(100000); // Data high timeout
            return 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        usleep(1); // Clock low delay
        gpioWrite(HX711_CLOCK_PIN, 1);
        usleep(1); // Clock high delay
        if (gpioRead(HX711_DATA_PIN)) {
            data_bits |= (1 << bit_count);
        }
        bit_count++;
    }

    *data = data_bits;
    return 0;
}

