    FILE *log_file = fopen(LOG_FILE, "a");

    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    char timestamp[20];
    ctime_r(&current_time, timestamp);
    timestamp[16] = '\0';

    fprintf(log_file, "%s Weight: %.2f kg\n", timestamp, weight);
    fclose(log_file);
}

