    int ret;
    double known_weight_kg;
    int32_t data;
    time_t current_time;

    if ((ret = pigpio_init()) < 0) {
        fprintf(stderr, "pigpio_init: %s\n", strerror(-ret));
        return 1;
    }

    signal(SIGINT, sigint_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise: %s\n", strerror(gpioLastError()));
        pigpio_stop();
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    printf("Enter the known weight in kilograms: ");
