    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() < 0) {
        return 1;
    }

    int last_state = relay_state;
    while (1) {
        int state = gpiod_line_get_value(sensor_line);
        if (state != last_state) {
            relay_state = !relay_state;
            gpiod_line_set_value(relay_line, relay_state);
            log_event("Relay state changed");
            last_state = state;
        }
        sleep(0.1);
    }

    cleanup_gpio();
    return 0;
}

