#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>
#include <errno.h>
#include <linux/types.h>
#include <libgpiod.h>

#define PIR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "motion_log.txt"

static gpiod_chip *chip;
static gpiod_line *pir_line;
static gpiod_line *buzzer_line;
static FILE *log_file;

void sigint_handler(int signum) {
    gpiod_line_set_value(buzzer_line, 0);
    fclose(log_file);
    gpiod_line_release(pir_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_release(chip);
    exit(0);
}

void sigterm_handler(int signum) {
    sigint_handler(signum);
}

int main() {
    struct stat st;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Open the GPIO chip
    if (gpiod_chip_open_by_name("gpiochip0", &chip) < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request PIR line as input
    if (gpiod_line_request_input(chip, PIR_GPIO, "pir", GPIOD_LINE_REQUEST_INPUT_ACTIVE_HIGH, NULL) < 0) {
        perror("Failed to request PIR line");
        exit(EXIT_FAILURE);
    }
    pir_line = gpiod_get_line_by_number(chip, PIR_GPIO);

    // Request buzzer line as output
    if (gpiod_line_request_output(chip, BUZZER_GPIO, "buzzer", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_HIGH, NULL) < 0) {
        perror("Failed to request buzzer line");
        exit(EXIT_FAILURE);
    }
    buzzer_line = gpiod_get_line_by_number(chip, BUZZER_GPIO);

    // Set buzzer off initially
    gpiod_line_set_value(buzzer_line, 0);

    time_t current_time;
    while (1) {
        // Check if PIR line is active
        int value = gpiod_line_get_value(pir_line);
        if (value > 0) {
            // Log the timestamp
            time(&current_time);
            char timestamp[25];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));
            fprintf(log_file, "%s: Motion detected\n", timestamp);

            // Turn on the buzzer for 2 seconds
            gpiod_line_set_value(buzzer_line, 1);
            usleep(2 * 1_000_000); // 2 seconds
            gpiod_line_set_value(buzzer_line, 0);
        }

        // Check if log file size exceeds 1 MB
        if (fstat(fileno(log_file), &st) == 0 && st.st_size > (1024 * 1024)) {
            ftruncate(fileno(log_file), 0);
        }
    }

    // Cleanup on exit
    fclose(log_file);
    gpiod_line_release(pir_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_release(chip);

    return 0;
}

