#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_LINE "gpiochip0/gpio18"
#define CONFIG_FILE "watering.conf"
#define VALVE_OFF 0
#define VALVE_ON  1

volatile sig_atomic_t sig_received = 0;
struct gpiod_chip *chip;
struct gpiod_line *line;

void sigint_handler(int signum) {
    sig_received = 1;
}

void sigterm_handler(int signum) {
    sig_received = 1;
}

int read_watering_duration(const char *filename) {
    FILE *file = fopen(filename, "r");
    char line[256];
    int duration = 0;

    if (!file) {
        perror("Error opening configuration file");
        return -1;
    }

    if (fgets(line, sizeof(line), file) == NULL) {
        perror("Error reading configuration line");
        fclose(file);
        return -1;
    }

    char *token = strtok(line, "=");
    if (!token) {
        perror("Malformed configuration line");
        fclose(file);
        return -1;
    }

    token = strtok(NULL, "\n");
    if (!token) {
        perror("Malformed configuration line");
        fclose(file);
        return -1;
    }

    duration = atoi(token);
    if (duration <= 0 || duration > 3600) {
        perror("Invalid watering duration");
        fclose(file);
        return -1;
    }

    fclose(file);
    return duration;
}

int main(void) {
    int duration = read_watering_duration(CONFIG_FILE);
    if (duration < 0) {
        return 1;
    }

    if (libgpiod_init() < 0) {
        perror("Error initializing libgpiod");
        return 1;
    }

    chip = libgpiod_chip_get_bylabel("gpiochip0");
    if (!chip) {
        perror("Error getting gpiochip0");
        goto cleanup;
    }

    line = libgpiod_get_line_byname(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        goto cleanup;
    }

    if (libgpiod_line_request_output(line, GPIOD_LINE_REQUEST_DIRECTION_OUT | GPIOD_LINE_REQUEST_ACTIVE_LOW) < 0) {
        perror("Error requesting GPIO line output");
        goto cleanup;
    }

    printf("Watering duration: %d seconds\n", duration);
    printf("Valve off\n");

    libgpiod_line_set_value(line, VALVE_OFF);
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += duration;

    while (!sig_received) {
        if (ts.tv_nsec < 1000000000L) {
            ts.tv_sec++;
            ts.tv_nsec = 0;
        }

        if (libgpiod_line_set_value(line, VALVE_ON) < 0) {
            perror("Error setting GPIO line value");
            goto cleanup;
        }

        nanosleep(&ts, NULL);

        if (libgpiod_line_set_value(line, VALVE_OFF) < 0) {
            perror("Error setting GPIO line value");
            goto cleanup;
        }

        printf("Valve off\n");
        sleep(1);
        printf("Valve on\n");
    }

    printf("Valve off (SIGINT or SIGTERM received)\n");

cleanup:
    if (line) {
        libgpiod_line_release(line);
    }
    if (chip) {
        libgpiod_chip_put(chip);
    }
    libgpiod_exit();

    return 0;
}

