#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <pigpio.h>

#define LEFT_SENSOR_GPIO 4
#define CENTER_SENSOR_GPIO 17
#define RIGHT_SENSOR_GPIO 27
#define LEFT_MOTOR_PWM_GPIO 22
#define RIGHT_MOTOR_PWM_GPIO 23
#define LEFT_MOTOR_DIR_GPIO 24
#define RIGHT_MOTOR_DIR_GPIO 25
#define PWM_FREQ 1000
#define PWM_RES 255
#define DELAY_MS 10
#define LOG_FILE "trace_log.txt"

static int g_left_motor_speed = 0;
static int g_right_motor_speed = 0;
static int g_left_sensor_state = 0;
static int g_center_sensor_state = 0;
static int g_right_sensor_state = 0;
static FILE *g_log_file = NULL;

void log_control_cycle(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_str[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_str, sizeof(time_str), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n", time_str, g_left_sensor_state,
            g_center_sensor_state, g_right_sensor_state, g_left_motor_speed,
            g_right_motor_speed);
}

void setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(LEFT_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_PWM_GPIO, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM_GPIO, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR_GPIO, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR_GPIO, PI_OUTPUT);

    gpioSetPWMfrequency(LEFT_MOTOR_PWM_GPIO, PWM_FREQ);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM_GPIO, PWM_FREQ);
}

void cleanup_gpio(void) {
    gpioTerminate();
    gpioTerm(0);
}

void setup_log_file(void) {
    int flags = O_WRONLY | O_CREAT | O_APPEND;
    int mode = S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH;

    g_log_file = fopen(LOG_FILE, "a", _FOPEN_MAX);
    if (g_log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    if (fchmod(fileno(g_log_file), mode) < 0) {
        perror("Failed to set log file permissions");
        exit(EXIT_FAILURE);
    }
}

void cleanup_log_file(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

void control_loop(void) {
    while (1) {
        g_left_sensor_state = gpioRead(LEFT_SENSOR_GPIO);
        g_center_sensor_state = gpioRead(CENTER_SENSOR_GPIO);
        g_right_sensor_state = gpioRead(RIGHT_SENSOR_GPIO);

        if (!g_left_sensor_state && g_center_sensor_state && !g_right_sensor_state) {
            g_left_motor_speed = 150;
            g_right_motor_speed = 150;
        } else if (!g_left_sensor_state && !g_center_sensor_state && g_right_sensor_state) {
            g_left_motor_speed = 75;
            g_right_motor_speed = 150;
        } else if (!g_left_sensor_state && g_center_sensor_state && !g_right_sensor_state) {
            g_left_motor_speed = 150;
            g_right_motor_speed = 75;
        } else {
            g_left_motor_speed = 0;
            g_right_motor_speed = 0;
