#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x23
#define SENSOR_CMD_CONTINUOUS_HIGH_RES 0x10
#define RELAY_GPIO 23
#define LOG_FILE "grow_log.txt"

int main() {
    int i2c_fd, relay_gpio;
    uint16_t lux;
    char log_buf[128];
    time_t timestamp;
    struct pigpio *pi;

    if ((pi = pigpio_init(NULL)) == NULL) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop(pi);
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        goto cleanup;
    }

    if (i2c_master_setup(i2c_fd, false, 100000) < 0) {
        perror("Failed to configure I2C bus");
        goto cleanup;
    }

    if (i2c_writeByteData(i2c_fd, SENSOR_ADDR, SENSOR_CMD_CONTINUOUS_HIGH_RES, 1) < 0) {
        perror("Failed to write command to sensor");
        goto cleanup;
    }

    relay_gpio = gpioInitialise();
    gpioSetMode(relay_gpio, PI_OUTPUT);
    gpioWrite(relay_gpio, 0);

    while (1) {
        if (i2c_readWordData(i2c_fd, SENSOR_ADDR, 0, &lux) < 0) {
            perror("Failed to read data from sensor");
            continue;
        }

        timestamp = time(NULL);
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S.%3N", localtime(&timestamp));
        snprintf(log_buf + strlen(log_buf), sizeof(log_buf) - strlen(log_buf), " lux=%d, relay=%s\n", lux, gpioRead(relay_gpio) ? "ON" : "OFF");
        fputs(log_buf, stdout);
        fputs(log_buf, fopen(LOG_FILE, "a"));

        if (lux < 150) {
            gpioWrite(relay_gpio, 1);
        }

        usleep(180 * 1000); // 180 ms delay
    }

cleanup:
    close(i2c_fd);
    gpioTerm(relay_gpio);
    pigpio_stop(pi);

    return 0;
}

