    running = 0;
}

void servo_set_pwm(int gpio, int pwm) {
    if (pwm < SERVO_MIN_PWM || pwm > SERVO_MAX_PWM) {
        fprintf(stderr, "Invalid servo PWM value: %d\n", pwm);
        return;
    }

    gpio_set_mode(gpio, PI_OUTPUT);
    gpio_set_PWMfunction(gpio, 0, 0);
    gpio_set_PWMrange(gpio, SERVO_MIN_PWM, SERVO_MAX_PWM);
    gpio_set_PWMdutycycle(gpio, pwm);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpio_set_mode(LOCK_BUTTON_GPIO, PI_INPUT);
    gpio_set_pull_up(LOCK_BUTTON_GPIO);
    gpio_set_mode(UNLOCK_BUTTON_GPIO, PI_INPUT);
    gpio_set_pull_up(UNLOCK_BUTTON_GPIO);
    gpio_set_mode(SERVO_GPIO, PI_OUTPUT);
    gpio_set_mode(SERVO_GPIO, PI_MODE_PWM);

    while (running) {
        int lock_button_state = gpioRead(LOCK_BUTTON_GPIO);
        int unlock_button_state = gpioRead(UNLOCK_BUTTON_GPIO);

        if (lock_button_state == 0) {
            servo_set_pwm(SERVO_GPIO, SERVO_LOCK_PWM);
            usleep(DEBOUNCE_DELAY);
        }

        if (unlock_button_state == 0) {
            servo_set_pwm(SERVO_GPIO, SERVO_UNLOCK_PWM);
            usleep(DEBOUNCE_DELAY);
        }
    }

    gpioTerminate();
    return 0;
}

