#define MOTOR1_LINE "gpiochip0\0/gpio17"
#define MOTOR2_LINE "gpiochip0\0/gpio27"
#define DUTY_CYCLE 50

static gpiod_line_request_flags_t gpio_flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_DEBOUNCE;

void motor_control(int motor, int on) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_get_line_byname(NULL, motor);
    if (IS_ERR(line)) {
        perror("Failed to get line");
        return;
    }

    ret = gpiod_line_request(line, gpio_flags);
    if (ret < 0) {
        perror("Failed to request line");
        goto release_line;
    }

    ret = gpiod_line_set_value(line, on);
    if (ret < 0) {
        perror("Failed to set line value");
        goto release_line;
    }

    usleep(1000 * (on ? 200 : 300));

release_line:
    gpiod_line_release(line);
}

void signal_handler(int sig) {
    motor_control(MOTOR1_LINE, 0);
    motor_control(MOTOR2_LINE, 0);
    exit(0);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    for (int i = 0; i < 1000; i++) {
        motor_control(MOTOR1_LINE, 1);
        motor_control(MOTOR2_LINE, 0);
        motor_control(MOTOR1_LINE, 0);
        motor_control(MOTOR2_LINE, 1);
        usleep(1000 * DUTY_CYCLE);
    }

    motor_control(MOTOR1_LINE, 0);
    motor_control(MOTOR2_LINE, 0);

