#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/types.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_PORT "tcp://*:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"

static void gpio_cleanup(struct gpiod_chip *chip, gpiod_line_request_data_t *request) {
    gpiod_line_release(request);
    gpiod_chip_deinitialize(chip);
}

static void zmq_cleanup(void *context, void *socket) {
    zmq_close(socket);
    zmq_ctx_term(context);
}

int main(int argc, char *argv[]) {
    if (argc != 2 && argc != 3) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *mode = argv[1];
    int use_sound_sensor = !strcmp(mode, "sound_sensor");
    int use_alarm_node = !strcmp(mode, "alarm_node");

    int ret;
    gpiod_chip *chip;
    gpiod_line_request_data_t request;
    void *context = NULL;
    void *socket = NULL;
    struct sockaddr_in addr;

    ret = gpiod_chip_open_byname("gpiochip0", &chip);
    if (ret < 0) {
        perror("gpiod_chip_open_byname");
        goto cleanup;
    }

    ret = gpiod_line_request_dt_byname(chip, "gpio-17", &request);
    if (ret < 0) {
        perror("gpiod_line_request_dt_byname");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_input(&request, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("gpiod_line_request_direction_input");
        goto cleanup;
    }

    if (use_sound_sensor) {
        struct timespec ts = { 0, 10 * 1e6 };
        while (1) {
            ret = gpiod_line_get_value(&request);
            if (ret < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }

            if (!ret) {
                context = zmq_ctx_new();
                if (!context) {
                    perror("zmq_ctx_new");
                    goto cleanup;
                }

                socket = zmq_socket(context, ZMQ_PUB);
                if (!socket) {
                    perror("zmq_socket");
                    goto cleanup;
                }

                ret = zmq_bind(socket, ZMQ_PORT);
                if (ret < 0) {
                    perror("zmq_bind");
                    goto cleanup;
                }

                ret = zmq_msg_init_size(&msg, strlen(ZMQ_TOPIC));
                if (ret < 0) {
                    perror("zmq_msg_init_size");
                    goto cleanup;
                }

                ret = zmq_msg_copy(&msg, ZMQ_TOPIC, strlen(ZMQ_TOPIC), 0);
                if (ret < 0) {
                    perror("zmq_msg_copy");
                    goto cleanup;
                }

                ret = zmq_msg_send(socket, &msg, 0);
                if (ret < 0) {
                    perror("zmq_msg_send");
                    goto cleanup;
                }

                zmq_msg_close(&msg);
            }

            nanosleep(&ts, NULL);
        }
    } else if (use_alarm_node) {
        context = zmq_ctx_new();
        if (!context) {
            perror("zmq_ctx_new");
            goto cleanup;
        }

        socket = zmq_socket(context, ZMQ_SUB);
        if (!socket) {
            perror("zmq_socket");
            goto cleanup;
        }

        memset(&addr, 0, sizeof(addr));
        addr.sin_family = AF_INET;
        addr.sin_port = htons(5555);
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);

        ret = zmq_connect(socket, (const char *) &addr, sizeof(addr));
        if (ret < 0) {
            perror("zmq_connect");
            goto cleanup;
        }

        ret = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
        if (ret < 0) {
            perror("zmq_setsockopt");
            goto cleanup;
        }

        while (1) {
            zmq_msg_t msg;
            ret = zmq_msg_recv(&msg, socket, 0);
            if (ret < 0) {
                perror("zmq_msg_recv");
                goto cleanup;
            }

            ret = gpiod_line_set_value(&request, 1);
            if (ret < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }

