#define ZMQ_TOPIC "SOUND_ALERTS"

static void gpio_cleanup(struct gpiod_chip *chip, gpiod_line_request_data_t *request) {
    gpiod_line_release(request);
    gpiod_chip_deinitialize(chip);
}

static void zmq_cleanup(void *context, void *socket) {
    zmq_close(socket);
    zmq_ctx_term(context);
}

int main(int argc, char *argv[]) {
    if (argc != 2 && argc != 3) {
        fprintf(stderr, "Usage: %s [sound_sensor|alarm_node]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *mode = argv[1];
    int use_sound_sensor = !strcmp(mode, "sound_sensor");
    int use_alarm_node = !strcmp(mode, "alarm_node");

    int ret;
    gpiod_chip *chip;
    gpiod_line_request_data_t request;
    void *context = NULL;
    void *socket = NULL;
    struct sockaddr_in addr;

    ret = gpiod_chip_open_byname("gpiochip0", &chip);
    if (ret < 0) {
        perror("gpiod_chip_open_byname");
        goto cleanup;
    }

    ret = gpiod_line_request_dt_byname(chip, "gpio-17", &request);
    if (ret < 0) {
        perror("gpiod_line_request_dt_byname");
        goto cleanup;
    }

    ret = gpiod_line_request_direction_input(&request, GPIOD_LINE_REQUEST_INPUT_ACTIVE_LOW);
    if (ret < 0) {
        perror("gpiod_line_request_direction_input");
        goto cleanup;
    }

