        struct timespec ts = { 0, 10 * 1e6 };
        while (1) {
            ret = gpiod_line_get_value(&request);
            if (ret < 0) {
                perror("gpiod_line_get_value");
                goto cleanup;
            }

            if (!ret) {
                context = zmq_ctx_new();
                if (!context) {
                    perror("zmq_ctx_new");
                    goto cleanup;
                }

                socket = zmq_socket(context, ZMQ_PUB);
                if (!socket) {
                    perror("zmq_socket");
                    goto cleanup;
                }

                ret = zmq_bind(socket, ZMQ_PORT);
                if (ret < 0) {
                    perror("zmq_bind");
                    goto cleanup;
                }

                ret = zmq_msg_init_size(&msg, strlen(ZMQ_TOPIC));
                if (ret < 0) {
                    perror("zmq_msg_init_size");
                    goto cleanup;
                }

                ret = zmq_msg_copy(&msg, ZMQ_TOPIC, strlen(ZMQ_TOPIC), 0);
                if (ret < 0) {
                    perror("zmq_msg_copy");
                    goto cleanup;
                }

                ret = zmq_msg_send(socket, &msg, 0);
