#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>
#include <evdev.h>

#define I2C_BUS 1
#define SENSOR_ADDRS {0x23, 0x24, 0x25, 0x26}
#define UDP_PORT 5005
#define UDP_MCAST_IP "239.255.255.250"

struct sensor {
    int fd;
    int addr;
};

void i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("i2c_write_byte");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("i2c_read_bytes");
        exit(EXIT_FAILURE);
    }
}

double bh1750_read_lux(int fd) {
    unsigned char data[2];

    i2c_write_byte(fd, 0x20);
    usleep(180 * 1000);
    i2c_read_bytes(fd, data, 2);

    return ((double)(data[0] << 8) | data[1]) / 1.2;
}

void *sensor_thread(void *arg) {
    struct sensor *sensor = arg;
    int lux;

    while (1) {
        lux = bh1750_read_lux(sensor->fd);
        if (lux == NAN)
            continue;

        printf("%d,%f\n", sensor->addr, lux);
    }

    close(sensor->fd);
    free(sensor);
    return NULL;
}

int main() {
    int i, sockfd, addrlen, n;
    struct sockaddr_in mcast_addr;
    struct i2c_rdwr_ioctl_data rw;
    struct i2c_msg msg[2];
    struct sensor *sensors = malloc(sizeof(struct sensor) * (sizeof(SENSOR_ADDRS) / sizeof(int)));
    pthread_t threads[sizeof(SENSOR_ADDRS)];

    for (i = 0; i < sizeof(SENSOR_ADDRS); i++) {
        sensors[i] = malloc(sizeof(struct sensor));
        sensors[i]->fd = open("/dev/i2c-1", O_RDWR);
        if (sensors[i]->fd < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }

        if (ioctl(sensors[i]->fd, I2C_SLAVE, SENSOR_ADDRS[i]) < 0) {
            perror("ioctl(I2C_SLAVE)");
            exit(EXIT_FAILURE);
        }

        msg[0].addr = SENSOR_ADDRS[i];
        msg[0].flags = 0;
        msg[0].len = 1;
        msg[0].buf = (char *)&(0x20);

        msg[1].addr = SENSOR_ADDRS[i];
        msg[1].flags = I2C_M_RD;
        msg[1].len = 2;
        msg[1].buf = (char *)data;

        rw.wr_buf = &msg[0];
        rw.wr_len = 1;
        rw.rd_buf = &msg[1];
        rw.rd_len = 2;

        if (ioctl(sensors[i]->fd, I2C_RDWR, &rw) < 0) {
            perror("ioctl(I2C_RDWR)");
            exit(EXIT_FAILURE);
        }

        pthread_create(&threads[i], NULL, sensor_thread, sensors[i]);
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    mcast_addr.sin_family = AF_INET;
    mcast_addr.sin_addr.s_addr = inet_addr(UDP_MCAST_IP);
    mcast_addr.sin_port = htons(UDP_PORT);

    addrlen = sizeof(mcast_addr);

    while (1) {
        char buf[1024];
        char *ptr;

        if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &TTL, sizeof(TTL)) < 0) {
            perror("setsockopt(IP_MULTICAST_TTL)");
            exit(EXIT_FAILURE);
        }

        if (bind(sockfd, (struct sockaddr *)&mcast_addr, addrlen) < 0) {
            perror("bind");
            exit(EXIT_FAILURE);
        }

        n = recvfrom(sockfd, buf, sizeof(buf), 0, NULL, NULL);
        if (n > 0) {
            printf("Received: %s\n", buf);
        }

        memset(buf, 0, sizeof(buf));
        for (i = 0; i < sizeof(SENSOR_ADDRS); i++) {
            snprintf(ptr = buf + strlen(buf), sizeof(buf) - strlen(buf), "%d,%f;", SENSOR_ADDRS[i], sensors[i]->lux);
            if (ptr - buf >= sizeof(buf) - 1)
                break;
        }

        if (sendto(sockfd, buf, strlen(buf), 0, (struct sockaddr *)&mcast_addr, addrlen) < 0) {
            perror("sendto");
            exit(EXIT_FAILURE);
        }

        usleep(1000 * 1000);
    }

    for (i = 0; i < sizeof(SENSOR_ADDRS); i++)
        pthread_join(threads[i], NULL);

    close(sockfd);

    return 0;
}

