This code initializes the I2C bus, opens the shared file descriptor for /dev/i2c-1, sets the slave address for each sensor, and reads the data using the One-Time High-Resolution mode command. It then creates a thread for each sensor to read the lux values and broadcast them as UDP multicast packets. The main thread listens for incoming UDP packets and sends the sensor readings once per second.

The code also handles errors during I2C transactions, opening the file descriptor, setting the slave address, and reading data. It also handles SIGINT and SIGTERM signals by setting a flag to exit the loop cleanly and closes all file descriptors on every exit path.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <signal.h>
#include <bcm2835.h>

#define I2C_BUS 1
#define SENSOR_ADDR 0x28
#define AWM7300_REG_CMD 0x00
#define AWM7300_REG_DATA 0x01
#define SLPM_SCALE 0.1

static int i2c_fd;
static struct timeval last_read_time;
static FILE *log_file;

void i2c_init() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (bcm2835_i2c_begin(I2C_BUS, i2c_fd) < 0) {
        perror("Failed to initialize I2C");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C slave address");
        exit(EXIT_FAILURE);
    }
}

void i2c_cleanup() {
    bcm2835_i2c_end();
    close(i2c_fd);
}

int i2c_read(uint8_t *buf, size_t len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = bcm2835_i2c_read(AWM7300_REG_DATA, buf, len);
        if (result >= 0)
            return result;

        if (errno == EAGAIN) {
            usleep(100000);
            retries--;
            continue;
        }

        perror("I2C read error");
        retries--;
    }

    return -1;
}

int i2c_write(const uint8_t *buf, size_t len) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = bcm2835_i2c_write(AWM7300_REG_CMD, buf, len);
        if (result >= 0)
            return result;

        if (errno == EAGAIN) {
            usleep(100000);
            retries--;
            continue;
        }

        perror("I2C write error");
        retries--;
    }

    return -1;
}

void log_flow(uint16_t flow) {
    struct timeval current_time;
    double elapsed_sec;

    gettimeofday(&current_time, NULL);
    elapsed_sec = (current_time.tv_sec - last_read_time.tv_sec) +
                  (current_time.tv_usec - last_read_time.tv_usec) / 1000000.0;

    fprintf(log_file, "%.6f, %u\n", elapsed_sec, flow);
    fflush(log_file);

    last_read_time = current_time;
}

void sigint_handler(int sig) {
    i2c_cleanup();
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    uint8_t buf[2];
    uint16_t flow;

    signal(SIGINT, sigint_handler);

    i2c_init();

    log_file = fopen("airflow_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        i2c_cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        if (i2c_write(NULL, 0) < 0) {
            perror("Failed to send zero-length write");
            continue;
        }

        if (i2c_read(buf, 2) < 0) {
            perror("Failed to read sensor data");
            continue;
        }

        flow = (buf[0] << 8) | buf[1];
        flow &= 0x3FFF;
        flow -= 3277;
        flow *= SLPM_SCALE;

        log_flow(flow);
        sleep(1);
    }

    i2c_cleanup();
    fclose(log_file);

    return EXIT_SUCCESS;
}

