                                const char *const names[], unsigned int flags)
{
    return gpiod_chip_get_lines_request_array(chip, nlines, names, flags);
}

int main() {
    int i2c_fd, ret;
    char log_file[] = "spectral_log.csv";
    FILE *log_fp;
    struct timespec ts;
    struct i2c_rdwr_ioctl_data i2c_data;
    char write_buf[2] = {0};
    char read_buf[11] = {0};
    struct gpiod_line_request *gpio_req;
    struct gpiod_line_state *gpio_state;

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_req = gpiod_chip_get_request(gpiod_chip_get_byname("gpiochip0"), "gpio18");
    if (!gpio_req) {
        perror("Failed to get GPIO request for GPIO18");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_state = gpiod_line_get_value(gpio_req->lines[0]);
    gpiod_line_set_value(gpio_req->lines[0], 1);

    if (gpio_state->value != 1) {
        fprintf(stderr, "GPIO18 is not in high state\n");
        gpiod_line_put_request(gpio_req);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    write_buf[0] = ENABLE_REG | (1 << 7); // Set PON bit to power on the sensor
    ret = write(i2c_fd, write_buf, 1);
    if (ret != 1) {
        perror("Failed to write to ENABLE register");
        gpiod_line_put_request(gpio_req);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    write_buf[0] = CFG6_REG;
    write_buf[1] = 0x00; // Set SMUX for spectral readings
    ret = write(i2c_fd, write_buf, 2);
    if (ret != 2) {
        perror("Failed to write to CFG6 register");
        gpiod_line_put_request(gpio_req);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_fp = fopen(log_file, "w");
    if (!log_fp) {
        perror("Failed to open log file");
        gpiod_line_put_request(gpio_req);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        i2c_data.wr_buf = &write_buf;
        i2c_data.wr_len = 0;
        i2c_data.rd_buf = &read_buf;
        i2c_data.rd_len = 11;

        ret = ioctl(i2c_fd, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("Failed to read from AS7341");
            fclose(log_fp);
            gpiod_line_put_request(gpio_req);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (i2c_data.rd_len != 11) {
            fprintf(stderr, "Unexpected number of bytes read from AS7341\n");
            fclose(log_fp);
            gpiod_line_put_request(gpio_req);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        if (read_buf[0] != 0x19) {
            fprintf(stderr, "AS7341 ID register does not match expected value\n");
            fclose(log_fp);
            gpiod_line_put_request(gpio_req);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        double lux = 0;
        for (int i = 0; i < 10; ++i) {
            lux += read_buf[DATA_REG_START + i] * LUX_SCALE;
        }
        lux /= 10;

        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_fp, "%lld,%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
                ts.tv_sec, read_buf[DATA_REG_START], read_buf[DATA_REG_START + 1],
                read_buf[DATA_REG_START + 2], read_buf[DATA_REG_START + 3],
                read_buf[DATA_REG_START + 4], read_buf[DATA_REG_START + 5],
                read_buf[DATA_REG_START + 6], read_buf[DATA_REG_START + 7],
                read_buf[DATA_REG_START + 8], read_buf[DATA_REG_START + 9], lux);

        sleep(5);
    }

    fclose(log_fp);
    gpiod_line_put_request(gpio_req);
    close(i2c_fd);

    return 0;
}

