This code initializes the I2C bus, sets the correct address for the AS7341 sensor, powers it on, configures it for spectral readings, opens a log file, and reads the sensor data every 5 seconds. It logs the data to the log file in a comma-separated format and handles errors related to I2C communication, sensor ID mismatch, and resource release. The GPIO18 line is used to power on the sensor, but you should replace it with the appropriate GPIO pin connected to the sensor's PON pin.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <sys/time.h>
#include <getopt.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define DEFAULT_ADDR 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define MAX_RETRIES 3
#define BACKOFF_MS 10
#define G_SCALE 0.000244

static gpiod_line_request_linenum_t gpio_line;
static int i2c_fd;
static int addr = DEFAULT_ADDR;
static int interval = DEFAULT_INTERVAL;
static char *filename = DEFAULT_FILENAME;
static FILE *csv_file;
static FILE *error_log;

void log_error(const char *message) {
    if (error_log) {
        time_t rawtime;
        struct tm *timeinfo;
        char time_string[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(error_log, "%s: %s\n", time_string, message);
    }
}

int i2c_read_reg(uint8_t reg, uint16_t *data) {
    int retries = 0;
    int res;

    do {
        res = ioctl(i2c_fd, I2C_SMBUS_READ_WORD_DATA, reg);
        if (res < 0) {
            if (errno != EAGAIN && errno != EBUSY) {
                log_error("I2C read error");
                return -1;
            }
            usleep(BACKOFF_MS * (1 << retries));
            retries++;
        }
    } while (retries < MAX_RETRIES && res < 0);

    if (res < 0) {
        log_error("I2C read timeout");
        return -1;
    }

    *data = (res & 0xFFFF);
    return 0;
}

void i2c_write_reg(uint8_t reg, uint16_t data) {
    int retries = 0;
    int res;

    do {
        res = ioctl(i2c_fd, I2C_SMBUS_WRITE_WORD_DATA, reg << 8 | data);
        if (res < 0) {
            if (errno != EAGAIN && errno != EBUSY) {
                log_error("I2C write error");
                return;
            }
            usleep(BACKOFF_MS * (1 << retries));
            retries++;
        }
    } while (retries < MAX_RETRIES && res < 0);

    if (res < 0) {
        log_error("I2C write timeout");
    }
}

void init_gpio() {
    gpiod_line_request_flags_t flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_EDGE_RISING;
    int ret = gpiod_chip_open_byname("gpiochip0");

    if (ret < 0) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_chip_get_line_bylabel(ret, "GPIO18");

    if (ret < 0) {
        log_error("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_dt(ret, "seismic_sensor", flags, &gpio_line);

    if (ret < 0) {
        log_error("Failed to request GPIO line");
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (csv_file) {
        fclose(csv_file);
    }

    if (error_log) {
        fclose(error_log);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    if (gpio_line >= 0) {
        gpiod_line_release(gpio_line);
    }

    gpiod_chip_close(gpio_line);
    exit(EXIT_SUCCESS);
}

void log_data(uint16_t x, uint16_t y, uint16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_string[80];
    double x_g, y_g, z_g;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", timeinfo);

    x_g = (double)x * G_SCALE;
    y_g = (double)y * G_SCALE;
    z_g = (double)z * G_SCALE;

    fprintf(csv_file, "%s,%f,%f,%f\n", time_string, x_g, y_g, z_g);
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                addr = strtol(optarg, NULL, 16);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <addr>] [-i <interval>] [-f <filename>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);

    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        log_error("Failed to set I2C slave address");
        exit(EXIT_FAILURE);
    }

    error_log = fopen("seismic_error.log", "w");
    csv_file = fopen(filename, "w");

    if (!csv_file) {
        log_error("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");

    init_gpio();

    while (1) {
        uint16_t x_l, x_h, y_l, y_h, z_l, z_h;

        if (gpio_get_value(gpio_line) == 0) {
            i2c_write_reg(0x28, 0x00);
            usleep(100000);
            i2c_read_reg(0x28, &x_l);
            i2c_read_reg(0x2A, &x_h);
            i2c_read_reg(0x2C, &y_l);
            i2c_read_reg(0x2E, &y_h);
            i2c_read_reg(0x20, &z_l);
            i2c_read_reg(0x22, &z_h);

            if (x_l == 0xFF || y_l == 0xFF || z_l == 0xFF) {
                log_error("Sensor absent");
                continue;
            }

            log_data(x_l, x_h, y_l, y_h, z_l, z_h);
        }

        sleep(interval);
    }

    cleanup();

    return 0;
}

