gpiod_line_request_linestate_cb_t gpio_cb;
struct gpiod_line_request *gpio_req;
int i2c_fd, udp_sock;

void gpio_cb(struct gpiod_line_request *req, int level, int event) {
    if (level == 0) {
        fprintf(stderr, "Error: Sensor not detected\n");
        sleep(1);
        exit(1);
    }
}

void i2c_read(uint8_t *buf, size_t len) {
    ssize_t bytes_read;
    if ((bytes_read = read(i2c_fd, buf, len)) < 0) {
        perror("Error reading from I2C");
        exit(1);
    }
}

void i2c_write(const uint8_t *buf, size_t len) {
    ssize_t bytes_written;
    if ((bytes_written = write(i2c_fd, buf, len)) != len) {
        perror("Error writing to I2C");
        exit(1);
    }
}

void udp_send(float lux) {
    struct sockaddr_in dest_addr;
    char lux_str[32];
    socklen_t addr_len = sizeof(dest_addr);

    snprintf(lux_str, sizeof(lux_str), "%.2f\n", lux);

    dest_addr.sin_family = AF_INET;
    dest_addr.sin_port = htons(UDP_PORT);
    dest_addr.sin_addr.s_addr = inet_addr("239.255.255.250");

    if (sendto(udp_sock, lux_str, strlen(lux_str), 0, (struct sockaddr *)&dest_addr, addr_len) < 0) {
        perror("Error sending UDP packet");
        exit(1);
    }
}

void sigint_handler(int sig) {
    close(i2c_fd);
    close(udp_sock);
    gpiod_line_release_request(gpio_req);
    exit(0);
}

