    if (!gpio_req) {
        perror("Error getting GPIO line request");
        exit(1);
    }

    gpiod_line_request_set_debounce(gpio_req, 10);
    gpiod_line_request_set_callback(gpio_req, gpio_cb);
    gpiod_line_request_enable(gpio_req, GPIOD_LINE_REQUEST_DIRECTION_IN);

    i2c_write(cmd, sizeof(cmd));
    sleep(1);

    udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_sock < 0) {
        perror("Error creating UDP socket");
        exit(1);
    }

    while (1) {
        i2c_read(data, sizeof(data));
        lux = data[0] * 256.0 + data[1];
        lux /= LUX_SCALE;

        udp_send(lux);
        sleep(1);
    }

    return 0;
}

