#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUDRATE B115200
#define TIMEOUT 2
#define BUFFER_SIZE 256
#define TIMESTAMP_SIZE 24

static void sigint_handler(int signum) {
    printf("\nGracefully shutting down...\n");
    close(fd);
    exit(0);
}

int main() {
    int fd, ret;
    char buffer[BUFFER_SIZE];
    char timestamp[TIMESTAMP_SIZE];
    struct termios options;
    fd_set read_fds;
    struct timeval tv;

    fd = open(UART_DEVICE, O_RDONLY | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    tcgetattr(fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = TIMEOUT;
    tcsetattr(fd, TCSANOW, &options);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        tv.tv_sec = 0;
        tv.tv_usec = 500000;
        ret = select(fd + 1, &read_fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select");
            continue;
        }

        if (FD_ISSET(fd, &read_fds)) {
            ret = read(fd, buffer, BUFFER_SIZE - 1);
            if (ret > 0) {
                buffer[ret] = '\0';
                if (strchr(buffer, '\n')) {
                    sscanf(buffer, "%23s,%f", timestamp, (float*)&buffer[TIMESTAMP_SIZE]);
                    struct tm tm;
                    strptime(timestamp, "%Y-%m-%d %H:%M:%S", &tm);
                    char time_str[32];
                    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm);
                    printf("Timestamp: %s, Range: %.2f meters\n", time_str, buffer[TIMESTAMP_SIZE]);
                }
            }
        }
    }

    close(fd);
    return 0;
}

