    struct timeval tv;

    fd = open(UART_DEVICE, O_RDONLY | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    tcgetattr(fd, &options);
    cfsetispeed(&options, BAUDRATE);
    cfsetospeed(&options, BAUDRATE);
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_iflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_cc[VMIN] = 0;
    options.c_cc[VTIME] = TIMEOUT;
    tcsetattr(fd, TCSANOW, &options);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(fd, &read_fds);

        tv.tv_sec = 0;
        tv.tv_usec = 500000;
        ret = select(fd + 1, &read_fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select");
            continue;
        }

        if (FD_ISSET(fd, &read_fds)) {
            ret = read(fd, buffer, BUFFER_SIZE - 1);
            if (ret > 0) {
                buffer[ret] = '\0';
                if (strchr(buffer, '\n')) {
                    sscanf(buffer, "%23s,%f", timestamp, (float*)&buffer[TIMESTAMP_SIZE]);
                    struct tm tm;
                    strptime(timestamp, "%Y-%m-%d %H:%M:%S", &tm);
                    char time_str[32];
                    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", &tm);
                    printf("Timestamp: %s, Range: %.2f meters\n", time_str, buffer[TIMESTAMP_SIZE]);
                }
            }
        }
    }

    close(fd);
    return 0;
}
```

This code opens the UART device, sets the baud rate, and configures it for non-canonical mode with a 0.5s inter-byte timeout. It then sets up signal handlers for SIGINT and SIGTERM to gracefully shut down the program. The main loop uses select() to wait for data availability, reads data from the UART, and parses valid lines containing a timestamp and range. It logs the valid detections to stdout in the requested format. The program closes the UART on all exit paths and checks every syscall for errors.

